#[derive(Debug, Clone)]
pub enum Ty {
    Name(String),
    App(Box<Ty>, Vec<Ty>),
    Arrow(Box<Ty>, Box<Ty>),
    Ref(Box<Ty>),
    MutRef(Box<Ty>),
    Shared(Box<Ty>),   // shared T → Arc<T> in Rust
    Optional(Box<Ty>), // T? → sugar for Option<T> (Kotlin-style nullability)
    Var(String),
    Unit,
    Hole,
}

impl fmt::Display for Ty {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Ty::Name(n) => write!(f, "{}", n),
            Ty::App(con, args) => {
                write!(f, "{}(", con)?;
                for (i, a) in args.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", a)?;
                }
                write!(f, ")")
            }
            Ty::Arrow(a, b) => write!(f, "{} -> {}", a, b),
            Ty::Ref(t) => write!(f, "&{}", t),
            Ty::MutRef(t) => write!(f, "&mut {}", t),
            Ty::Shared(t) => write!(f, "shared {}", t),
            Ty::Optional(t) => write!(f, "{}?", t),
            Ty::Var(n) => write!(f, "{}", n),
            Ty::Unit => write!(f, "()"),
            Ty::Hole => write!(f, "_"),
        }
    }
}

#[derive(Debug, Clone)]
pub struct Param {
    pub name: String,
    pub ty: Option<Ty>,
    pub inout: bool, // Mutable value semantics: caller passes &mut, function mutates in place
}

#[derive(Debug, Clone)]
pub enum Pat {
    Wild,
    Var(String),
    Lit(Literal),
    Con(String, Vec<Pat>),
    NamedCon(String, Vec<(String, Pat)>), // Circle(radius: r) — named field destructure
    As(Box<Pat>, String),
}

#[derive(Debug, Clone)]
pub enum Literal {
    Int(i64),
    Float(f64),
    Str(String),
    Char(char),
    Bool(bool),
}

impl fmt::Display for Literal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Literal::Int(n) => write!(f, "{}", n),
            Literal::Float(v) => write!(f, "{}", v),
            Literal::Str(s) => write!(f, "\"{}\"", s),
            Literal::Char(c) => write!(f, "'{}'", c),
            Literal::Bool(b) => write!(f, "{}", if *b { "True" } else { "False" }),
        }
    }
}

/// The expression AST node kind. Expr wraps this with a Span.
/// During the type alias phase, `Expr` = `ExprKind` (zero-cost transition).
#[derive(Debug, Clone)]
pub enum ExprKind {
    Var(String),
    Lit(Literal),
    App(Box<Expr>, Vec<Expr>),
    Lambda(Vec<Param>, Box<Expr>),
    BinOp(String, Box<Expr>, Box<Expr>),
    UnOp(String, Box<Expr>),
    If(Box<Expr>, Box<Expr>, Box<Expr>),
    Match(Box<Expr>, Vec<MatchArm>),
    Block(Vec<Stmt>),
    Field(Box<Expr>, String),
    Index(Box<Expr>, Box<Expr>),
    List(Vec<Expr>),
    Tuple(Vec<Expr>),
    Effect(String, Vec<Expr>),
    /// Algebraic effect handler: | handle EffectName { | op(args) -> body } in expr
    Handle {
        effect: String,
        handlers: Vec<EffHandler>,
        body: Box<Expr>,
    },
    /// Postfix ? operator (try/propagate errors)
    Try(Box<Expr>),
    /// Prolog-style conjunction: goal1, goal2, goal3 — all must succeed
    Conjunction(Vec<Expr>),
    /// Prolog-style disjunction: goal1 or goal2 — first that succeeds wins
    Disjunction(Vec<Expr>),
    /// Pipe-forward operator: a |> f — preserves ~ rune identity (not desugared to App)
    Pipe(Box<Expr>, Box<Expr>),
    Unit,
}

pub const NAMED_ARG_MARKER: &str = "__named_arg";
pub const PATHOF_MARKER: &str = "__pathof";
pub const REFOF_MARKER: &str = "__refof";

/// Expression AST node: wraps ExprKind with source location.
#[derive(Debug, Clone)]
pub struct Expr {
    pub kind: ExprKind,
    pub span: Span,
}

impl Expr {
    /// Create an Expr with a source span.
    pub fn new(kind: ExprKind, span: Span) -> Self {
        Expr { kind, span }
    }

    /// Shorthand for unspanned expressions (during migration).
    pub fn unspanned(kind: ExprKind) -> Self {
        Expr {
            kind,
            span: Span::dummy(),
        }
    }
}

pub fn named_arg_expr(field: String, value: Expr) -> Expr {
    named_arg_expr_with_span(field, value, Span::dummy())
}

pub fn named_arg_expr_with_span(field: String, value: Expr, span: Span) -> Expr {
    Expr::new(
        ExprKind::App(
            Box::new(ExprKind::Var(NAMED_ARG_MARKER.to_string()).into()),
            vec![ExprKind::Lit(Literal::Str(field)).into(), value],
        ),
        span,
    )
}

pub fn named_arg_parts(expr: &Expr) -> Option<(&str, &Expr)> {
    let ExprKind::App(func, args) = &expr.kind else {
        return None;
    };
    let ExprKind::Var(marker) = &func.kind else {
        return None;
    };
    if marker != NAMED_ARG_MARKER || args.len() != 2 {
        return None;
    }
    let ExprKind::Lit(Literal::Str(field)) = &args[0].kind else {
        return None;
    };
    Some((field.as_str(), &args[1]))
}

pub fn is_named_arg_expr(expr: &Expr) -> bool {
    named_arg_parts(expr).is_some()
}

pub fn has_named_args(args: &[Expr]) -> bool {
    args.iter().any(is_named_arg_expr)
}

pub fn all_named_args(args: &[Expr]) -> bool {
    args.iter().all(is_named_arg_expr)
}

/// Return the canonical path represented by the parser's internal `pathof`
/// call. The root type is used for checking but is not part of the serialized
/// calculation path.
pub fn pathof_canonical_path(expr: &Expr) -> Option<String> {
    let ExprKind::App(function, arguments) = &expr.kind else {
        return None;
    };
    if !matches!(&function.kind, ExprKind::Var(name) if name == PATHOF_MARKER)
        || arguments.len() < 2
    {
        return None;
    }
    let segments = arguments
        .iter()
        .skip(1)
        .map(|argument| match &argument.kind {
            ExprKind::Lit(Literal::Str(segment)) => Some(segment.as_str()),
            _ => None,
        })
        .collect::<Option<Vec<_>>>()?;
    Some(segments.join("."))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ProgramReferenceLiteral {
    Symbol { name: String },
    Type { name: String },
    Member { root_type: String, path: String },
}

/// Decode the parser's internal `refof` expression into its portable value.
pub fn refof_literal(expr: &Expr) -> Option<ProgramReferenceLiteral> {
    let ExprKind::App(function, arguments) = &expr.kind else {
        return None;
    };
    if !matches!(&function.kind, ExprKind::Var(name) if name == REFOF_MARKER) || arguments.len() < 2
    {
        return None;
    }
    let ExprKind::Lit(Literal::Str(mode)) = &arguments[0].kind else {
        return None;
    };
    let ExprKind::Lit(Literal::Str(root)) = &arguments[1].kind else {
        return None;
    };
    let segments = arguments
        .iter()
        .skip(2)
        .map(|argument| match &argument.kind {
            ExprKind::Lit(Literal::Str(segment)) => Some(segment.as_str()),
            _ => None,
        })
        .collect::<Option<Vec<_>>>()?;

    match (mode.as_str(), segments.is_empty()) {
        ("symbol", true) => Some(ProgramReferenceLiteral::Symbol { name: root.clone() }),
        ("type", true) => Some(ProgramReferenceLiteral::Type { name: root.clone() }),
        ("type", false) => Some(ProgramReferenceLiteral::Member {
            root_type: root.clone(),
            path: segments.join("."),
        }),
        _ => None,
    }
}

/// Lower `refof` to an ordinary prelude constructor so every runtime and
/// metadata consumer observes the same typed, serializable value.
pub fn refof_reference_expr(expr: &Expr) -> Option<Expr> {
    let (constructor, arguments) = match refof_literal(expr)? {
        ProgramReferenceLiteral::Symbol { name } => (
            "ProgramSymbolReference",
            vec![Expr::new(ExprKind::Lit(Literal::Str(name)), expr.span)],
        ),
        ProgramReferenceLiteral::Type { name } => (
            "ProgramTypeReference",
            vec![Expr::new(ExprKind::Lit(Literal::Str(name)), expr.span)],
        ),
        ProgramReferenceLiteral::Member { root_type, path } => (
            "ProgramMemberReference",
            vec![
                Expr::new(ExprKind::Lit(Literal::Str(root_type)), expr.span),
                Expr::new(ExprKind::Lit(Literal::Str(path)), expr.span),
            ],
        ),
    };
    Some(Expr::new(
        ExprKind::App(
            Box::new(Expr::new(ExprKind::Var(constructor.to_string()), expr.span)),
            arguments,
        ),
        expr.span,
    ))
}

pub fn reorder_named_args_by_names(param_order: &[String], args: &[Expr]) -> Option<Vec<Expr>> {
    if !has_named_args(args) || !all_named_args(args) {
        return None;
    }
    let mut by_name: BTreeMap<String, Expr> = BTreeMap::new();
    for arg in args {
        let (name, value) = named_arg_parts(arg)?;
        if !param_order.iter().any(|known| known == name) || by_name.contains_key(name) {
            return None;
        }
        by_name.insert(name.to_string(), value.clone());
    }
    if by_name.len() != param_order.len() {
        return None;
    }
    let mut ordered = Vec::with_capacity(param_order.len());
    for name in param_order {
        ordered.push(by_name.get(name)?.clone());
    }
    Some(ordered)
}

/// Allow ExprKind to convert to Expr (with dummy span) during migration.
impl From<ExprKind> for Expr {
    fn from(kind: ExprKind) -> Self {
        Expr::unspanned(kind)
    }
}

/// Allow ExprKind to convert to Box<Expr> directly.
impl From<ExprKind> for Box<Expr> {
    fn from(kind: ExprKind) -> Self {
        Box::new(Expr::unspanned(kind))
    }
}

