/// One explicitly selected, typed starter-support publication consumer.
///
/// These declarations are intentionally separate from [`ExploreAnalysisNode`]:
/// adding a presentation consumer must not rename the relation, question,
/// mechanism request, or core analysis DAG which supplies its authority.
#[derive(Debug, Clone)]
pub struct ExploreStarterProjection {
    pub name: String,
    pub request_name: String,
    pub subject: ExploreStarterProjectionSubject,
    /// Optional enclosing structural mechanism used to refine a shared node
    /// or edge's total support. This is a publication-time support slice; it
    /// never participates in the structural subject's identity.
    pub within_mechanism: Option<[u8; 32]>,
    pub value_view_name: String,
    pub span: Span,
}

/// One explicitly requested full semantic transition-graph publication.
///
/// The graph is identity-only: typed endpoint values require a separately
/// checked value-bearing consumer and are never disclosed by this declaration.
/// Like starter projections, this consumer is outside the core analysis DAG.
#[derive(Debug, Clone)]
pub struct ExploreTransitionGraph {
    pub name: String,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum ExploreAnalysisNode {
    Result(ExploreResultView),
    Mechanisms(ExploreMechanismRequest),
}

impl ExploreAnalysisNode {
    pub fn name(&self) -> &str {
        match self {
            Self::Result(result) => &result.name,
            Self::Mechanisms(request) => &request.name,
        }
    }

    pub fn span(&self) -> Span {
        match self {
            Self::Result(result) => result.span,
            Self::Mechanisms(request) => request.span,
        }
    }
}

#[derive(Debug, Clone)]
pub struct ExploreQuery {
    pub name: String,
    pub source: ExploreSourceRelation,
    pub successor: ExploreSuccessorRelation,
    pub admissions: Vec<ExploreAdmission>,
    pub selection: ExploreSelection,
    /// Post-FIND analysis declarations in dependency order. References may
    /// resolve only to an earlier node, so the authored order is already a DAG
    /// topological order and cannot encode a cycle.
    pub analysis: Vec<ExploreAnalysisNode>,
    /// Explicit publication consumers over already-declared analysis nodes.
    /// They never participate in the core analysis graph identity.
    pub starter_projections: Vec<ExploreStarterProjection>,
    /// Explicit identity-only semantic transition-graph consumers.
    pub transition_graphs: Vec<ExploreTransitionGraph>,
    pub span: Span,
}

pub const EXPLORE_RELATION_NORMALIZATION_VERSION: u32 = 1;

