// Compiler-provided first-order row identities available inside Explore
// result inputs. These are semantic identifier types, not String aliases: the
// result runtime preserves their typed digest values through projection and
// `count_distinct` without exposing string operations over them.
const EXPLORE_SELECTED_CASE_ROW_BINDINGS: &[(&str, &str)] = &[("case_id", "CaseId")];
const EXPLORE_MECHANISM_INCIDENCE_ROW_BINDINGS: &[(&str, &str)] = &[
    ("case_id", "CaseId"),
    ("transition_id", "TransitionId"),
    ("signature_id", "MechanismSignatureId"),
    ("structural_mechanism_id", "StructuralMechanismId"),
    ("execution_profile_id", "ExecutionProfileId"),
];

fn explore_result_input_row_bindings(
    input: &ExploreResultInput,
) -> &'static [(&'static str, &'static str)] {
    match input {
        ExploreResultInput::Sources => &[],
        ExploreResultInput::Selected => EXPLORE_SELECTED_CASE_ROW_BINDINGS,
        ExploreResultInput::MechanismIncidence { .. } => EXPLORE_MECHANISM_INCIDENCE_ROW_BINDINGS,
    }
}

#[derive(Debug, Clone)]
pub enum Stmt {
    Defn(Defn),
    TypeDecl(TypeDecl),
    Rule(Rule),
    Use(String),                     // @ use path::to::thing
    Import(String),                  // @ import ./module (multi-file, flat merge)
    QualifiedImport(String, String), // @ import Name from ./module (qualified access)
    HashImport(String, String),      // @ import #hash from ./module (content-addressed)
    Depend(String, String),          // @ depend "crate" "version"
    RustBlock(String),               // @ rust { raw Rust code }
    Annot(String, Vec<Expr>),
    Bind(Pat, Option<Ty>, Expr),
    /// Monadic bind: = pat <- expr (unwrap Ok/Some, early-return on Err/None)
    MonadicBind(Pat, Option<Ty>, Expr),
    For(String, Expr, Vec<Stmt>),   // for var in expr { body }
    While(Expr, Vec<Stmt>),         // while cond { body }
    Send(Expr, Expr),               // target <- message (actor send)
    StreamBind(String, Expr),       // ~ name = expr (reactive stream binding)
    StreamSub(Expr, Vec<MatchArm>), // ~ expr | pat -> { body } (reactive stream subscription)
    /// | name: subject -> predicate (named invariant / verification assertion)
    Invariant {
        name: String,
        subject: Expr,   // the expression being constrained
        predicate: Expr, // must evaluate to true
    },
    /// ? name — invoke verification (runtime check / Z3 proof / debug_assert)
    /// Optional: `: val` captures subject, `-> { pass }` block, `else { fail }` block
    Prove {
        name: String,
        proof_block: Option<ProofBlock>, // `by { | ... -> proof }`
        capture: Option<String>,         // `: val` — bind subject value
        pass_block: Option<Vec<Stmt>>,   // `-> { ... }` — custom pass handler
        else_block: Option<Vec<Stmt>>,   // `else { ... }` — custom fail handler (suppresses halt)
    },
    /// `? explore name { ... }` — finite relational exploration declaration.
    Explore(ExploreQuery),
    /// assert TypeName(args...) — insert fact (persist/store/in-memory)
    Assert(String, Vec<Expr>),
    /// retract TypeName(args...) — remove fact (persist/store/in-memory)
    Retract(String, Vec<Expr>),
    /// abort — exit current scope with ROLLBACK
    Abort,
    Expr(Expr),
}

#[derive(Debug, Clone)]
pub enum Defn {
    Fn {
        name: String,
        params: Vec<Param>,
        ret_ty: Option<Ty>,
        effects: Vec<String>,
        body: Expr,
    },
    Actor {
        name: String,
        state_param: Param,
        handlers: Vec<Handler>,
    },
    Module {
        name: String,
        body: Vec<Stmt>,
    },
}

#[derive(Debug, Clone)]
pub struct Handler {
    pub msg_pat: Pat,
    pub body: Expr,
}

#[derive(Debug, Clone)]
pub enum TypeDecl {
    ADT {
        name: String,
        params: Vec<Param>,
        variants: Vec<Variant>,
        methods: Vec<Defn>,
        /// EXCEPT clause: include all variants from this type minus the listed ones
        except_from: Option<(String, Vec<String>)>,
    },
    /// Conditional type evolution: # Type WHEN condition = new_variants
    WhenType {
        name: String,
        condition: Expr,
        variants: Vec<Variant>,
        except_from: Option<(String, Vec<String>)>,
    },
    EffectDecl {
        name: String,
        ops: Vec<(String, Vec<Param>, Option<Ty>)>,
    },
    TraitDecl {
        name: String,
        params: Vec<Param>, // trait type params
        methods: Vec<TraitMethod>,
    },
    ImplBlock {
        trait_name: String,
        for_type: String,
        methods: Vec<Defn>,
    },
    RuleScope {
        name: String,
        params: Vec<Param>,
        body: Vec<Stmt>,
    },
}

#[derive(Debug, Clone)]
pub struct TraitMethod {
    pub name: String,
    pub params: Vec<Param>,
    pub ret_ty: Option<Ty>,
    pub default_body: Option<Expr>, // default implementation
}

#[derive(Debug, Clone)]
pub struct Variant {
    pub name: String,
    pub fields: Vec<Field>,
    pub positional: bool, // true = tuple-style (Type, Type), false = named (name: Type)
    pub from_type: Option<String>, // Some("GeoArea") for subset variants: GeoArea.Danmark
}

#[derive(Debug, Clone)]
pub struct Field {
    pub name: String,
    pub ty: Ty,
}

#[derive(Debug, Clone)]
pub enum Rule {
    Clause {
        head: Expr,
        body: Option<Expr>,
    },
    Default {
        head: Expr,
        value: Expr,
        condition: Option<Expr>,
    },
    Exception {
        label: String,
        head: Expr,
        value: Expr,
        condition: Option<Expr>,
    },
    ReactiveScope {
        name: String,
        body: Vec<Stmt>,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum RuleDispatchTier {
    Exception,
    ConditionalDefault,
    Clause,
    UnconditionalDefault,
}

#[derive(Debug, Clone, Copy)]
pub struct RuleDispatchCandidate<'a> {
    pub rule: &'a Rule,
    pub source_order: usize,
    pub source_span: Span,
}

#[derive(Debug, Default)]
pub struct RuleDispatchPlan<'a> {
    pub exceptions: Vec<RuleDispatchCandidate<'a>>,
    pub conditional_defaults: Vec<RuleDispatchCandidate<'a>>,
    pub clauses: Vec<RuleDispatchCandidate<'a>>,
    pub unconditional_defaults: Vec<RuleDispatchCandidate<'a>>,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct RuleDispatchKey {
    pub scope: Option<String>,
    pub name: String,
    pub arity: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuleDispatchParameter {
    pub name: Option<String>,
    pub ty: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RuleDispatchTotality {
    PredicateFallbackFalse,
    IrrefutableCandidate,
    Partial,
}

#[derive(Debug)]
pub struct RuleDispatchGroup<'a> {
    pub key: RuleDispatchKey,
    pub captures: Vec<Param>,
    pub parameters: Vec<RuleDispatchParameter>,
    pub return_type: Option<String>,
    pub return_type_issue: Option<String>,
    pub totality: RuleDispatchTotality,
    pub plan: RuleDispatchPlan<'a>,
}

#[derive(Debug, Default)]
pub struct RuleDispatchRegistry<'a> {
    pub groups: BTreeMap<RuleDispatchKey, RuleDispatchGroup<'a>>,
}

impl Rule {
    pub fn head(&self) -> Option<&Expr> {
        match self {
            Rule::Clause { head, .. }
            | Rule::Default { head, .. }
            | Rule::Exception { head, .. } => Some(head),
            Rule::ReactiveScope { .. } => None,
        }
    }

    pub fn callable_name_arity(&self) -> Option<(String, usize)> {
        rule_head_name_arity(self.head()?)
    }

    pub fn dispatch_tier(&self) -> Option<RuleDispatchTier> {
        match self {
            Rule::Exception { .. } => Some(RuleDispatchTier::Exception),
            Rule::Default {
                condition: Some(_), ..
            } => Some(RuleDispatchTier::ConditionalDefault),
            Rule::Clause { .. } => Some(RuleDispatchTier::Clause),
            Rule::Default {
                condition: None, ..
            } => Some(RuleDispatchTier::UnconditionalDefault),
            Rule::ReactiveScope { .. } => None,
        }
    }
}

impl<'a> RuleDispatchPlan<'a> {
    pub fn from_rules(rules: impl IntoIterator<Item = &'a Rule>) -> Self {
        let mut plan = Self::default();
        for (source_order, rule) in rules.into_iter().enumerate() {
            let candidate = RuleDispatchCandidate {
                rule,
                source_order,
                source_span: rule
                    .head()
                    .map(|head| head.span)
                    .unwrap_or_else(Span::dummy),
            };
            match rule.dispatch_tier() {
                Some(RuleDispatchTier::Exception) => plan.exceptions.push(candidate),
                Some(RuleDispatchTier::ConditionalDefault) => {
                    plan.conditional_defaults.push(candidate)
                }
                Some(RuleDispatchTier::Clause) => plan.clauses.push(candidate),
                Some(RuleDispatchTier::UnconditionalDefault) => {
                    plan.unconditional_defaults.push(candidate)
                }
                None => {}
            }
        }
        plan
    }

    pub fn candidates(&self) -> impl Iterator<Item = RuleDispatchCandidate<'a>> + '_ {
        self.exceptions
            .iter()
            .chain(&self.conditional_defaults)
            .chain(&self.clauses)
            .chain(&self.unconditional_defaults)
            .copied()
    }
}

fn rule_head_name_arity(head: &Expr) -> Option<(String, usize)> {
    match &head.kind {
        ExprKind::App(function, arguments) => match &function.kind {
            ExprKind::Var(name) => Some((name.clone(), arguments.len())),
            _ => rule_head_name_arity(function).map(|(name, _)| (name, arguments.len())),
        },
        ExprKind::Var(name) => Some((name.clone(), 0)),
        _ => None,
    }
}

pub fn typed_rule_head_argument(argument: &Expr) -> Option<(&Expr, &str)> {
    let ExprKind::App(function, arguments) = &argument.kind else {
        return None;
    };
    if !matches!(&function.kind, ExprKind::Var(name) if name == "__typed") || arguments.len() != 2 {
        return None;
    }
    let ExprKind::Var(type_name) = &arguments[1].kind else {
        return None;
    };
    Some((&arguments[0], type_name))
}

fn rule_dispatch_parameter(argument: &Expr) -> RuleDispatchParameter {
    let (argument, ty) = typed_rule_head_argument(argument)
        .map(|(inner, ty)| (inner, Some(ty.to_string())))
        .unwrap_or((argument, None));
    let name = match &argument.kind {
        ExprKind::Var(name)
            if name != "_" && !name.chars().next().is_some_and(char::is_uppercase) =>
        {
            Some(name.clone())
        }
        _ => None,
    };
    RuleDispatchParameter { name, ty }
}

fn rule_dispatch_parameters(rules: &[&Rule], arity: usize) -> Vec<RuleDispatchParameter> {
    let mut parameters = vec![
        RuleDispatchParameter {
            name: None,
            ty: None,
        };
        arity
    ];
    for rule in rules {
        let Some(head) = rule.head() else {
            continue;
        };
        let ExprKind::App(_, arguments) = &head.kind else {
            continue;
        };
        for (index, argument) in arguments.iter().enumerate() {
            let candidate = rule_dispatch_parameter(argument);
            if parameters[index].name.is_none() {
                parameters[index].name = candidate.name;
            }
            if parameters[index].ty.is_none() {
                parameters[index].ty = candidate.ty;
            }
        }
    }
    parameters
}

fn rule_head_argument_is_irrefutable(argument: &Expr) -> bool {
    let argument = typed_rule_head_argument(argument)
        .map(|(inner, _)| inner)
        .unwrap_or(argument);
    matches!(&argument.kind, ExprKind::Var(name) if name == "_" || !name.chars().next().is_some_and(char::is_uppercase))
}

fn rule_head_is_irrefutable(rule: &Rule) -> bool {
    let Some(head) = rule.head() else {
        return false;
    };
    match &head.kind {
        ExprKind::Var(_) => true,
        ExprKind::App(_, arguments) => arguments.iter().all(rule_head_argument_is_irrefutable),
        _ => false,
    }
}

impl<'a> RuleDispatchRegistry<'a> {
    pub fn from_statements(stmts: &'a [Stmt], artifacts: &TypeCheckArtifacts) -> Self {
        #[derive(Default)]
        struct PendingGroup<'a> {
            captures: Vec<Param>,
            rules: Vec<&'a Rule>,
        }

        let mut pending: BTreeMap<RuleDispatchKey, PendingGroup<'a>> = BTreeMap::new();
        for statement in stmts {
            match statement {
                Stmt::Rule(rule) => {
                    if let Some((name, arity)) = rule.callable_name_arity() {
                        pending
                            .entry(RuleDispatchKey {
                                scope: None,
                                name,
                                arity,
                            })
                            .or_default()
                            .rules
                            .push(rule);
                    }
                }
                Stmt::TypeDecl(TypeDecl::RuleScope { name, params, body }) => {
                    pending.retain(|key, _| key.scope.as_deref() != Some(name));
                    for scoped_statement in body {
                        let Stmt::Rule(rule) = scoped_statement else {
                            continue;
                        };
                        let Some((member, arity)) = rule.callable_name_arity() else {
                            continue;
                        };
                        let group = pending
                            .entry(RuleDispatchKey {
                                scope: Some(name.clone()),
                                name: member,
                                arity,
                            })
                            .or_default();
                        group.captures = params.clone();
                        group.rules.push(rule);
                    }
                }
                _ => {}
            }
        }

        let groups = pending
            .into_iter()
            .map(|(key, pending)| {
                let return_type = artifacts.rule_dispatch_return_types.get(&key).cloned();
                let return_type_issue = artifacts.rule_dispatch_return_issues.get(&key).cloned();
                let totality = if return_type.as_deref() == Some("Bool") {
                    RuleDispatchTotality::PredicateFallbackFalse
                } else if pending.rules.iter().any(|rule| {
                    rule_head_is_irrefutable(rule)
                        && match rule {
                            Rule::Exception {
                                condition: None, ..
                            }
                            | Rule::Default {
                                condition: None, ..
                            } => true,
                            Rule::Clause { body, .. } => body.is_some(),
                            _ => false,
                        }
                }) {
                    RuleDispatchTotality::IrrefutableCandidate
                } else {
                    RuleDispatchTotality::Partial
                };
                let parameters = rule_dispatch_parameters(&pending.rules, key.arity);
                let plan = RuleDispatchPlan::from_rules(pending.rules.iter().copied());
                let group = RuleDispatchGroup {
                    key: key.clone(),
                    captures: pending.captures,
                    parameters,
                    return_type,
                    return_type_issue,
                    totality,
                    plan,
                };
                (key, group)
            })
            .collect();
        Self { groups }
    }

    pub fn get(
        &self,
        scope: Option<&str>,
        name: &str,
        arity: usize,
    ) -> Option<&RuleDispatchGroup<'a>> {
        self.groups.get(&RuleDispatchKey {
            scope: scope.map(str::to_string),
            name: name.to_string(),
            arity,
        })
    }
}

#[derive(Debug, Clone, Default)]
struct FreeSymbolUses {
    values: BTreeSet<String>,
    /// Occurrence counts complement the deduplicated dependency sets when a
    /// consumer must prove that every free role-root use is a projection.
    value_occurrences: BTreeMap<String, usize>,
    calls: BTreeSet<String>,
    member_calls: BTreeSet<(String, String)>,
    member_values: BTreeSet<(String, String)>,
    member_value_occurrences: BTreeMap<(String, String), usize>,
    typed_member_calls: BTreeSet<(String, String)>,
    runtime_calls: Vec<RuntimeCallUse>,
    runtime_member_calls: Vec<RuntimeMemberCallUse>,
}

impl FreeSymbolUses {
    fn extend(&mut self, other: Self) {
        self.values.extend(other.values);
        for (name, count) in other.value_occurrences {
            *self.value_occurrences.entry(name).or_default() += count;
        }
        self.calls.extend(other.calls);
        self.member_calls.extend(other.member_calls);
        self.member_values.extend(other.member_values);
        for (member, count) in other.member_value_occurrences {
            *self.member_value_occurrences.entry(member).or_default() += count;
        }
        self.typed_member_calls.extend(other.typed_member_calls);
        self.runtime_calls.extend(other.runtime_calls);
        self.runtime_member_calls.extend(other.runtime_member_calls);
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct RuntimeCallUse {
    pub(crate) name: String,
    /// The arity written at the transform root of a pipe.  Ordinary calls do
    /// not need a second identity because their source and runtime arities are
    /// the same.
    pub(crate) source_arity: Option<usize>,
    pub(crate) effective_arity: usize,
    pub(crate) through_pipe: bool,
    pub(crate) lexically_bound: bool,
    pub(crate) span: Span,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct RuntimeMemberCallUse {
    receiver: String,
    member: String,
    effective_arity: usize,
    typed_receiver: bool,
}

fn type_name(ty: &Ty) -> Option<&str> {
    match ty {
        Ty::Name(name) => Some(name),
        Ty::App(constructor, _) => type_name(constructor),
        Ty::Ref(inner) | Ty::MutRef(inner) | Ty::Shared(inner) | Ty::Optional(inner) => {
            type_name(inner)
        }
        Ty::Arrow(_, _) | Ty::Var(_) | Ty::Unit | Ty::Hole => None,
    }
}

fn typed_member_receivers(params: &[Param]) -> BTreeMap<String, String> {
    params
        .iter()
        .filter_map(|param| {
            param
                .ty
                .as_ref()
                .and_then(type_name)
                .map(|name| (param.name.clone(), name.to_string()))
        })
        .collect()
}

fn update_lexical_bindings(
    pattern: &Pat,
    ty: Option<&Ty>,
    expression: &Expr,
    bound: &mut BTreeSet<String>,
    typed_receivers: &mut BTreeMap<String, String>,
) {
    let receiver_type = if let Pat::Var(_) = pattern {
        ty.and_then(type_name)
            .map(str::to_string)
            .or_else(|| match &expression.kind {
                ExprKind::Var(source) => typed_receivers.get(source).cloned(),
                ExprKind::App(function, _) => match &function.kind {
                    ExprKind::Var(constructor) => Some(constructor.clone()),
                    _ => None,
                },
                _ => None,
            })
    } else {
        None
    };
    let mut names = BTreeSet::new();
    collect_pattern_names(pattern, &mut names);
    for name in &names {
        typed_receivers.remove(name);
    }

    if let Pat::Var(name) = pattern {
        if let Some(receiver_type) = receiver_type {
            typed_receivers.insert(name.clone(), receiver_type);
        }
    }
    bound.extend(names);
}

fn shadow_pattern_bindings(
    pattern: &Pat,
    bound: &mut BTreeSet<String>,
    typed_receivers: &mut BTreeMap<String, String>,
) {
    let mut names = BTreeSet::new();
    collect_pattern_names(pattern, &mut names);
    for name in &names {
        typed_receivers.remove(name);
    }
    bound.extend(names);
}

fn update_stmt_lexical_bindings(
    stmt: &Stmt,
    bound: &mut BTreeSet<String>,
    typed_receivers: &mut BTreeMap<String, String>,
) {
    match stmt {
        Stmt::Bind(pattern, ty, expression) | Stmt::MonadicBind(pattern, ty, expression) => {
            update_lexical_bindings(pattern, ty.as_ref(), expression, bound, typed_receivers);
        }
        Stmt::StreamBind(name, _) => {
            typed_receivers.remove(name);
            bound.insert(name.clone());
        }
        _ => {}
    }
}

fn extend_param_bindings(
    params: &[Param],
    bound: &mut BTreeSet<String>,
    typed_receivers: &mut BTreeMap<String, String>,
) {
    for param in params {
        typed_receivers.remove(&param.name);
        if let Some(receiver_type) = param.ty.as_ref().and_then(type_name) {
            typed_receivers.insert(param.name.clone(), receiver_type.to_string());
        }
        bound.insert(param.name.clone());
    }
}

fn collect_true_free_symbol_uses_stmt(
    stmt: &Stmt,
    uses: &mut FreeSymbolUses,
    bound: &BTreeSet<String>,
    typed_receivers: &BTreeMap<String, String>,
) {
    match stmt {
        Stmt::Bind(_, _, expr) | Stmt::MonadicBind(_, _, expr) => {
            collect_true_free_symbol_uses(expr, uses, bound, typed_receivers);
        }
        Stmt::Expr(expr) | Stmt::StreamBind(_, expr) => {
            collect_true_free_symbol_uses(expr, uses, bound, typed_receivers);
        }
        Stmt::Send(target, msg) => {
            collect_true_free_symbol_uses(target, uses, bound, typed_receivers);
            collect_true_free_symbol_uses(msg, uses, bound, typed_receivers);
        }
        Stmt::For(var, iter, body_stmts) => {
            collect_true_free_symbol_uses(iter, uses, bound, typed_receivers);
            let mut for_bound = bound.clone();
            let mut for_typed_receivers = typed_receivers.clone();
            for_bound.insert(var.clone());
            for_typed_receivers.remove(var);
            for body_stmt in body_stmts {
                collect_true_free_symbol_uses_stmt(
                    body_stmt,
                    uses,
                    &for_bound,
                    &for_typed_receivers,
                );
                update_stmt_lexical_bindings(body_stmt, &mut for_bound, &mut for_typed_receivers);
            }
        }
        Stmt::While(cond, body_stmts) => {
            collect_true_free_symbol_uses(cond, uses, bound, typed_receivers);
            let mut while_bound = bound.clone();
            let mut while_typed_receivers = typed_receivers.clone();
            for body_stmt in body_stmts {
                collect_true_free_symbol_uses_stmt(
                    body_stmt,
                    uses,
                    &while_bound,
                    &while_typed_receivers,
                );
                update_stmt_lexical_bindings(
                    body_stmt,
                    &mut while_bound,
                    &mut while_typed_receivers,
                );
            }
        }
        Stmt::StreamSub(expr, arms) => {
            collect_true_free_symbol_uses(expr, uses, bound, typed_receivers);
            for arm in arms {
                let mut arm_bound = bound.clone();
                let mut arm_typed_receivers = typed_receivers.clone();
                shadow_pattern_bindings(&arm.pat, &mut arm_bound, &mut arm_typed_receivers);
                if let Some(guard) = &arm.guard {
                    collect_true_free_symbol_uses(guard, uses, &arm_bound, &arm_typed_receivers);
                }
                collect_true_free_symbol_uses(&arm.body, uses, &arm_bound, &arm_typed_receivers);
            }
        }
        Stmt::Invariant {
            subject, predicate, ..
        } => {
            collect_true_free_symbol_uses(subject, uses, bound, typed_receivers);
            collect_true_free_symbol_uses(predicate, uses, bound, typed_receivers);
        }
        Stmt::Prove {
            pass_block,
            else_block,
            ..
        } => {
            if let Some(pass_block) = pass_block {
                let mut pass_bound = bound.clone();
                let mut pass_typed_receivers = typed_receivers.clone();
                for pass_stmt in pass_block {
                    collect_true_free_symbol_uses_stmt(
                        pass_stmt,
                        uses,
                        &pass_bound,
                        &pass_typed_receivers,
                    );
                    update_stmt_lexical_bindings(
                        pass_stmt,
                        &mut pass_bound,
                        &mut pass_typed_receivers,
                    );
                }
            }
            if let Some(else_block) = else_block {
                let mut else_bound = bound.clone();
                let mut else_typed_receivers = typed_receivers.clone();
                for else_stmt in else_block {
                    collect_true_free_symbol_uses_stmt(
                        else_stmt,
                        uses,
                        &else_bound,
                        &else_typed_receivers,
                    );
                    update_stmt_lexical_bindings(
                        else_stmt,
                        &mut else_bound,
                        &mut else_typed_receivers,
                    );
                }
            }
        }
        Stmt::Explore(query) => {
            let mut query_bound = bound.clone();
            let query_typed_receivers = typed_receivers.clone();
            for binding in &query.source.bindings {
                let expression = match &binding.kind {
                    ExploreSourceBindingKind::Singleton { value } => value,
                    ExploreSourceBindingKind::Finite { domain } => domain,
                };
                collect_true_free_symbol_uses(
                    expression,
                    uses,
                    &query_bound,
                    &query_typed_receivers,
                );
                query_bound.insert(binding.name.clone());
            }
            query_bound
                .retain(|name| name == "before" || name == "context" || bound.contains(name));
            let successor_expression = match &query.successor.kind {
                ExploreSuccessorKind::Singleton { value } => value,
                ExploreSuccessorKind::Finite { domain } => domain,
            };
            collect_true_free_symbol_uses(
                successor_expression,
                uses,
                &query_bound,
                &query_typed_receivers,
            );
            query_bound.insert("after".to_string());
            for admission in &query.admissions {
                collect_true_free_symbol_uses(
                    &admission.predicate,
                    uses,
                    &query_bound,
                    &query_typed_receivers,
                );
            }
            if let Some(predicate) = query.selection.predicate() {
                collect_true_free_symbol_uses(
                    predicate,
                    uses,
                    &query_bound,
                    &query_typed_receivers,
                );
            }
            for node in &query.analysis {
                match node {
                    ExploreAnalysisNode::Result(result) => {
                        let mut result_bound = query_bound.clone();
                        result_bound.extend(
                            explore_result_input_row_bindings(&result.input)
                                .iter()
                                .map(|(name, _)| (*name).to_string()),
                        );
                        if let ExploreResultGrain::GroupBy { fields, .. } = &result.grain {
                            for field in fields {
                                collect_true_free_symbol_uses(
                                    &field.value,
                                    uses,
                                    &result_bound,
                                    &query_typed_receivers,
                                );
                                result_bound.insert(field.name.clone());
                            }
                        }
                        for field in &result.measures {
                            collect_true_free_symbol_uses(
                                &field.value,
                                uses,
                                &result_bound,
                                &query_typed_receivers,
                            );
                            result_bound.insert(field.name.clone());
                        }
                        for field in &result.aggregates {
                            match &field.reducer {
                                ExploreAggregateReducer::CountDistinct { value } => {
                                    collect_true_free_symbol_uses(
                                        value,
                                        uses,
                                        &result_bound,
                                        &query_typed_receivers,
                                    );
                                }
                            }
                            result_bound.insert(field.name.clone());
                        }
                        for field in &result.select {
                            collect_true_free_symbol_uses(
                                &field.value,
                                uses,
                                &result_bound,
                                &query_typed_receivers,
                            );
                            result_bound.insert(field.name.clone());
                        }
                        if let Some(choice) = &result.choose {
                            match choice {
                                ExploreResultChoice::Optimize { objective, .. } => {
                                    collect_true_free_symbol_uses(
                                        objective,
                                        uses,
                                        &result_bound,
                                        &query_typed_receivers,
                                    );
                                }
                                ExploreResultChoice::Pareto { objectives, .. } => {
                                    for objective in objectives {
                                        collect_true_free_symbol_uses(
                                            &objective.value,
                                            uses,
                                            &result_bound,
                                            &query_typed_receivers,
                                        );
                                    }
                                }
                            }
                        }
                    }
                    ExploreAnalysisNode::Mechanisms(request) => {
                        let mut observation_bound = query_bound.clone();
                        observation_bound.insert("state".to_string());
                        collect_true_free_symbol_uses(
                            &request.endpoint_template,
                            uses,
                            &observation_bound,
                            &query_typed_receivers,
                        );
                    }
                }
            }
        }
        Stmt::Rule(Rule::ReactiveScope { body, .. }) => {
            let mut scope_bound = bound.clone();
            let mut scope_typed_receivers = typed_receivers.clone();
            for body_stmt in body {
                collect_true_free_symbol_uses_stmt(
                    body_stmt,
                    uses,
                    &scope_bound,
                    &scope_typed_receivers,
                );
                update_stmt_lexical_bindings(
                    body_stmt,
                    &mut scope_bound,
                    &mut scope_typed_receivers,
                );
            }
        }
        Stmt::Rule(_) => {}
        Stmt::Annot(_, args) | Stmt::Assert(_, args) | Stmt::Retract(_, args) => {
            for arg in args {
                collect_true_free_symbol_uses(arg, uses, bound, typed_receivers);
            }
        }
        Stmt::Use(_)
        | Stmt::Import(_)
        | Stmt::QualifiedImport(_, _)
        | Stmt::HashImport(_, _)
        | Stmt::Depend(_, _)
        | Stmt::Abort
        | Stmt::Defn(_)
        | Stmt::TypeDecl(_)
        | Stmt::RustBlock(_) => {}
    }
}

fn collect_true_free_symbol_uses(
    expr: &Expr,
    uses: &mut FreeSymbolUses,
    bound: &BTreeSet<String>,
    typed_receivers: &BTreeMap<String, String>,
) {
    match &expr.kind {
        ExprKind::Var(name) => {
            if !bound.contains(name) {
                uses.values.insert(name.clone());
                *uses.value_occurrences.entry(name.clone()).or_default() += 1;
            }
        }
        ExprKind::Lit(_) | ExprKind::Unit => {}
        ExprKind::BinOp(_, lhs, rhs) => {
            collect_true_free_symbol_uses(lhs, uses, bound, typed_receivers);
            collect_true_free_symbol_uses(rhs, uses, bound, typed_receivers);
        }
        ExprKind::UnOp(_, inner) | ExprKind::Try(inner) => {
            collect_true_free_symbol_uses(inner, uses, bound, typed_receivers)
        }
        ExprKind::App(func, args) => {
            if matches!(&func.kind, ExprKind::Var(name) if name == NAMED_ARG_MARKER) {
                if let Some(value) = args.get(1) {
                    collect_true_free_symbol_uses(value, uses, bound, typed_receivers);
                }
                return;
            }
            if let ExprKind::Var(fn_name) = &func.kind {
                uses.runtime_calls.push(RuntimeCallUse {
                    name: fn_name.clone(),
                    source_arity: None,
                    effective_arity: args.len(),
                    through_pipe: false,
                    lexically_bound: bound.contains(fn_name),
                    span: expr.span,
                });
                if (fn_name == "findall" || fn_name == "search") && args.len() >= 2 {
                    let mut inner_bound = bound.clone();
                    let mut inner_typed_receivers = typed_receivers.clone();
                    if let ExprKind::Var(qvar) = &args[0].kind {
                        inner_bound.insert(qvar.clone());
                        inner_typed_receivers.remove(qvar);
                    }
                    for arg in &args[1..] {
                        collect_true_free_symbol_uses(
                            arg,
                            uses,
                            &inner_bound,
                            &inner_typed_receivers,
                        );
                    }
                    return;
                }
            }
            if let ExprKind::Var(name) = &func.kind {
                if !bound.contains(name) {
                    uses.calls.insert(name.clone());
                }
            } else {
                if let ExprKind::Field(receiver, member) = &func.kind {
                    let receiver_name = match &receiver.kind {
                        ExprKind::Var(name) => Some(name),
                        ExprKind::App(constructor, _) => match &constructor.kind {
                            ExprKind::Var(name) => Some(name),
                            _ => None,
                        },
                        _ => None,
                    };
                    if let Some(receiver_name) = receiver_name {
                        if let Some(receiver_type) = typed_receivers.get(receiver_name) {
                            uses.typed_member_calls
                                .insert((receiver_type.clone(), member.clone()));
                            uses.runtime_member_calls.push(RuntimeMemberCallUse {
                                receiver: receiver_type.clone(),
                                member: member.clone(),
                                effective_arity: args.len(),
                                typed_receiver: true,
                            });
                        } else if !bound.contains(receiver_name) {
                            uses.member_calls
                                .insert((receiver_name.clone(), member.clone()));
                            uses.runtime_member_calls.push(RuntimeMemberCallUse {
                                receiver: receiver_name.clone(),
                                member: member.clone(),
                                effective_arity: args.len(),
                                typed_receiver: false,
                            });
                        }
                    }
                }
                collect_true_free_symbol_uses(func, uses, bound, typed_receivers);
            }
            for arg in args {
                collect_true_free_symbol_uses(arg, uses, bound, typed_receivers);
            }
        }
        ExprKind::If(cond, then_expr, else_expr) => {
            collect_true_free_symbol_uses(cond, uses, bound, typed_receivers);
            collect_true_free_symbol_uses(then_expr, uses, bound, typed_receivers);
            collect_true_free_symbol_uses(else_expr, uses, bound, typed_receivers);
        }
        ExprKind::Field(object, member) => {
            if let ExprKind::Var(receiver) = &object.kind {
                if !bound.contains(receiver) {
                    uses.member_values
                        .insert((receiver.clone(), member.clone()));
                    *uses
                        .member_value_occurrences
                        .entry((receiver.clone(), member.clone()))
                        .or_default() += 1;
                }
            }
            collect_true_free_symbol_uses(object, uses, bound, typed_receivers)
        }
        ExprKind::Index(collection, index) => {
            collect_true_free_symbol_uses(collection, uses, bound, typed_receivers);
            collect_true_free_symbol_uses(index, uses, bound, typed_receivers);
        }
        ExprKind::Match(scrutinee, arms) => {
            collect_true_free_symbol_uses(scrutinee, uses, bound, typed_receivers);
            for arm in arms {
                let mut arm_bound = bound.clone();
                let mut arm_typed_receivers = typed_receivers.clone();
                shadow_pattern_bindings(&arm.pat, &mut arm_bound, &mut arm_typed_receivers);
                collect_true_free_symbol_uses(&arm.body, uses, &arm_bound, &arm_typed_receivers);
                if let Some(guard) = &arm.guard {
                    collect_true_free_symbol_uses(guard, uses, &arm_bound, &arm_typed_receivers);
                }
            }
        }
        ExprKind::Lambda(params, body) => {
            let mut inner_bound = bound.clone();
            let mut inner_typed_receivers = typed_receivers.clone();
            extend_param_bindings(params, &mut inner_bound, &mut inner_typed_receivers);
            collect_true_free_symbol_uses(body, uses, &inner_bound, &inner_typed_receivers);
        }
        ExprKind::Block(stmts) => {
            let mut block_bound = bound.clone();
            let mut block_typed_receivers = typed_receivers.clone();
            for stmt in stmts {
                collect_true_free_symbol_uses_stmt(
                    stmt,
                    uses,
                    &block_bound,
                    &block_typed_receivers,
                );
                update_stmt_lexical_bindings(stmt, &mut block_bound, &mut block_typed_receivers);
            }
        }
        ExprKind::List(items) | ExprKind::Tuple(items) => {
            for item in items {
                collect_true_free_symbol_uses(item, uses, bound, typed_receivers);
            }
        }
        ExprKind::Effect(_, args) => {
            for arg in args {
                collect_true_free_symbol_uses(arg, uses, bound, typed_receivers);
            }
        }
        ExprKind::Handle { handlers, body, .. } => {
            for handler in handlers {
                let mut handler_bound = bound.clone();
                let mut handler_typed_receivers = typed_receivers.clone();
                for param in &handler.params {
                    handler_typed_receivers.remove(param);
                    handler_bound.insert(param.clone());
                }
                collect_true_free_symbol_uses(
                    &handler.body,
                    uses,
                    &handler_bound,
                    &handler_typed_receivers,
                );
            }
            collect_true_free_symbol_uses(body, uses, bound, typed_receivers);
        }
        ExprKind::Conjunction(goals) | ExprKind::Disjunction(goals) => {
            for goal in goals {
                collect_true_free_symbol_uses(goal, uses, bound, typed_receivers);
            }
        }
        ExprKind::Pipe(input, transform) => {
            collect_true_free_symbol_uses(input, uses, bound, typed_receivers);
            match &transform.kind {
                ExprKind::Var(name) => {
                    uses.runtime_calls.push(RuntimeCallUse {
                        name: name.clone(),
                        source_arity: None,
                        effective_arity: 1,
                        through_pipe: true,
                        lexically_bound: bound.contains(name),
                        span: transform.span,
                    });
                    if !bound.contains(name) {
                        uses.calls.insert(name.clone());
                    }
                }
                ExprKind::App(function, arguments) => {
                    if let ExprKind::Var(name) = &function.kind {
                        uses.runtime_calls.push(RuntimeCallUse {
                            name: name.clone(),
                            source_arity: Some(arguments.len()),
                            effective_arity: arguments.len() + 1,
                            through_pipe: true,
                            lexically_bound: bound.contains(name),
                            span: transform.span,
                        });
                        if !bound.contains(name) {
                            uses.calls.insert(name.clone());
                        }
                    } else {
                        collect_true_free_symbol_uses(function, uses, bound, typed_receivers);
                    }
                    for argument in arguments {
                        collect_true_free_symbol_uses(argument, uses, bound, typed_receivers);
                    }
                }
                _ => collect_true_free_symbol_uses(transform, uses, bound, typed_receivers),
            }
        }
    }
}

/// Collect truly free variables: referenced names minus names bound by local
/// patterns, parameters, and query variables.
pub fn collect_true_free_vars_stmt(
    stmt: &Stmt,
    free: &mut BTreeSet<String>,
    bound: &BTreeSet<String>,
) {
    let mut uses = FreeSymbolUses::default();
    collect_true_free_symbol_uses_stmt(stmt, &mut uses, bound, &BTreeMap::new());
    free.extend(uses.values);
    free.extend(uses.calls);
}

pub fn collect_true_free_vars(expr: &Expr, free: &mut BTreeSet<String>, bound: &BTreeSet<String>) {
    let mut uses = FreeSymbolUses::default();
    collect_true_free_symbol_uses(expr, &mut uses, bound, &BTreeMap::new());
    free.extend(uses.values);
    free.extend(uses.calls);
}

pub(crate) fn collect_scoped_runtime_calls(
    expr: &Expr,
    bound: &BTreeSet<String>,
) -> Vec<RuntimeCallUse> {
    let mut uses = FreeSymbolUses::default();
    collect_true_free_symbol_uses(expr, &mut uses, bound, &BTreeMap::new());
    uses.runtime_calls
}

/// One exact runtime dependency root for bounded exploration initialization.
/// Calls keep their effective runtime arity; the selected Explore question is
/// additionally identified as a rule so a same-named function or value cannot
/// silently redirect its dependency slice.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) enum ExploreRuntimeRoot {
    Value {
        name: String,
    },
    Call {
        name: String,
        arity: usize,
    },
    Rule {
        name: String,
        arity: usize,
    },
    MemberValue {
        receiver: String,
        member: String,
    },
    MemberCall {
        receiver: String,
        member: String,
        arity: usize,
        typed_receiver: bool,
    },
}

fn collect_explore_runtime_roots_with_receivers(
    expr: &Expr,
    roots: &mut BTreeSet<ExploreRuntimeRoot>,
    bound: &BTreeSet<String>,
    typed_receivers: &BTreeMap<String, String>,
) {
    let mut uses = FreeSymbolUses::default();
    collect_true_free_symbol_uses(expr, &mut uses, bound, typed_receivers);

    roots.extend(
        uses.values
            .into_iter()
            .map(|name| ExploreRuntimeRoot::Value { name }),
    );
    roots.extend(
        uses.runtime_calls
            .into_iter()
            .filter(|call| !call.lexically_bound)
            .map(|call| ExploreRuntimeRoot::Call {
                name: call.name,
                arity: call.effective_arity,
            }),
    );

    let called_members = uses
        .runtime_member_calls
        .iter()
        .map(|call| (call.receiver.clone(), call.member.clone()))
        .collect::<BTreeSet<_>>();
    roots.extend(
        uses.member_values
            .into_iter()
            .filter(|member| !called_members.contains(member))
            .map(|(receiver, member)| ExploreRuntimeRoot::MemberValue { receiver, member }),
    );
    roots.extend(uses.runtime_member_calls.into_iter().map(|call| {
        ExploreRuntimeRoot::MemberCall {
            receiver: call.receiver,
            member: call.member,
            arity: call.effective_arity,
            typed_receiver: call.typed_receiver,
        }
    }));
}

pub(crate) fn collect_typed_explore_runtime_roots(
    expr: &Expr,
    roots: &mut BTreeSet<ExploreRuntimeRoot>,
    bound: &BTreeSet<String>,
    typed_receivers: &BTreeMap<String, String>,
) {
    collect_explore_runtime_roots_with_receivers(expr, roots, bound, typed_receivers);
}

pub fn collect_pattern_names(pat: &Pat, names: &mut BTreeSet<String>) {
    match pat {
        Pat::Var(name) => {
            names.insert(name.clone());
        }
        Pat::Con(_, patterns) => {
            for pattern in patterns {
                collect_pattern_names(pattern, names);
            }
        }
        Pat::NamedCon(_, fields) => {
            for (_, pattern) in fields {
                collect_pattern_names(pattern, names);
            }
        }
        Pat::As(inner, alias) => {
            collect_pattern_names(inner, names);
            names.insert(alias.clone());
        }
        Pat::Wild | Pat::Lit(_) => {}
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TopLevelInitializationCycle {
    pub path: Vec<String>,
}

impl fmt::Display for TopLevelInitializationCycle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "cyclic top-level value initialization: {}",
            self.path.join(" -> ")
        )
    }
}

#[derive(Debug, Clone, Default)]
pub struct TopLevelBindingDependencyPlan {
    binding_names: BTreeSet<String>,
    dependencies: BTreeMap<String, BTreeSet<String>>,
}

impl TopLevelBindingDependencyPlan {
    pub fn order_statement_refs<'a>(
        &self,
        stmts: &[&'a Stmt],
    ) -> Result<Vec<&'a Stmt>, TopLevelInitializationCycle> {
        struct BindingBundle<'a> {
            annotations: Vec<&'a Stmt>,
            binding: &'a Stmt,
        }

        fn append_binding<'a>(
            name: &str,
            plan: &TopLevelBindingDependencyPlan,
            bindings: &BTreeMap<String, BindingBundle<'a>>,
            emitted: &mut BTreeSet<String>,
            active: &mut Vec<String>,
            ordered: &mut Vec<&'a Stmt>,
        ) -> Result<(), TopLevelInitializationCycle> {
            if emitted.contains(name) {
                return Ok(());
            }
            if let Some(cycle_start) = active.iter().position(|active_name| active_name == name) {
                let mut path = active[cycle_start..].to_vec();
                path.push(name.to_string());
                return Err(TopLevelInitializationCycle { path });
            }

            active.push(name.to_string());
            if let Some(dependencies) = plan.dependencies.get(name) {
                for dependency in dependencies {
                    if bindings.contains_key(dependency) {
                        append_binding(dependency, plan, bindings, emitted, active, ordered)?;
                    }
                }
            }
            active.pop();

            if emitted.insert(name.to_string()) {
                if let Some(bundle) = bindings.get(name) {
                    ordered.extend(bundle.annotations.iter().copied());
                    ordered.push(bundle.binding);
                }
            }
            Ok(())
        }

        let mut bindings = BTreeMap::new();
        let mut bundled_annotation_indexes = BTreeSet::new();
        for (index, stmt) in stmts.iter().enumerate() {
            let Stmt::Bind(Pat::Var(name), _, _) = stmt else {
                continue;
            };
            if !self.binding_names.contains(name) {
                continue;
            }

            let mut annotation_start = index;
            while annotation_start > 0 {
                let is_binding_annotation = matches!(
                    stmts[annotation_start - 1],
                    Stmt::Annot(annotation, arguments)
                        if arguments.is_empty()
                            && (annotation == "comptime" || annotation == "export")
                );
                if !is_binding_annotation {
                    break;
                }
                annotation_start -= 1;
            }
            let annotations = stmts[annotation_start..index].to_vec();
            bundled_annotation_indexes.extend(annotation_start..index);
            bindings.insert(
                name.clone(),
                BindingBundle {
                    annotations,
                    binding: *stmt,
                },
            );
        }
        let mut emitted = BTreeSet::new();
        let mut active = Vec::new();
        let mut ordered = Vec::with_capacity(stmts.len());

        for (index, stmt) in stmts.iter().enumerate() {
            if bundled_annotation_indexes.contains(&index) {
                continue;
            }
            if let Stmt::Bind(Pat::Var(name), _, _) = stmt {
                if self.binding_names.contains(name) {
                    append_binding(
                        name,
                        self,
                        &bindings,
                        &mut emitted,
                        &mut active,
                        &mut ordered,
                    )?;
                    continue;
                }
            }
            ordered.push(*stmt);
        }

        Ok(ordered)
    }
}

fn rule_head_name(head: &Expr) -> Option<&str> {
    match &head.kind {
        ExprKind::Var(name) => Some(name),
        ExprKind::App(function, _) => match &function.kind {
            ExprKind::Var(name) => Some(name),
            _ => None,
        },
        _ => None,
    }
}

fn rule_head_bound_names(head: &Expr) -> BTreeSet<String> {
    let ExprKind::App(_, args) = &head.kind else {
        return BTreeSet::new();
    };
    args.iter()
        .filter_map(|arg| {
            let inner = match &arg.kind {
                ExprKind::App(function, typed_args)
                    if matches!(&function.kind, ExprKind::Var(name) if name == "__typed") =>
                {
                    typed_args.first().unwrap_or(arg)
                }
                _ => arg,
            };
            match &inner.kind {
                ExprKind::Var(name) => Some(name.clone()),
                _ => None,
            }
        })
        .collect()
}

fn rule_scope_member_callable_name(scope: &str, member: &str) -> String {
    format!("\0rulescope:{scope}:{member}")
}

fn rule_scope_member_name(stmt: &Stmt) -> Option<&str> {
    match stmt {
        Stmt::Defn(Defn::Fn { name, .. }) => Some(name),
        Stmt::Rule(rule) if !matches!(rule, Rule::ReactiveScope { .. }) => match rule {
            Rule::Clause { head, .. }
            | Rule::Default { head, .. }
            | Rule::Exception { head, .. } => rule_head_name(head),
            Rule::ReactiveScope { .. } => None,
        },
        _ => None,
    }
}

fn direct_rule_scope_constructor<'a>(
    expression: &'a Expr,
    rule_scope_names: &BTreeSet<String>,
) -> Option<&'a str> {
    let ExprKind::App(function, _) = &expression.kind else {
        return None;
    };
    let ExprKind::Var(name) = &function.kind else {
        return None;
    };
    rule_scope_names.contains(name).then_some(name.as_str())
}

fn resolve_rule_scope_member_callable(
    receiver: &str,
    member: &str,
    statement_index: usize,
    binding_positions: &BTreeMap<String, usize>,
    binding_rule_scopes: &BTreeMap<String, String>,
    rule_scope_names: &BTreeSet<String>,
) -> Option<String> {
    let earlier_binding_shadows = binding_positions
        .get(receiver)
        .is_some_and(|position| *position < statement_index);
    if earlier_binding_shadows {
        return binding_rule_scopes
            .get(receiver)
            .map(|scope| rule_scope_member_callable_name(scope, member));
    }
    if rule_scope_names.contains(receiver) {
        return Some(rule_scope_member_callable_name(receiver, member));
    }
    binding_rule_scopes
        .get(receiver)
        .map(|scope| rule_scope_member_callable_name(scope, member))
}

fn collect_rule_head_typed_receivers(
    expression: &Expr,
    typed_receivers: &mut BTreeMap<String, String>,
) {
    match &expression.kind {
        ExprKind::App(function, args) if matches!(&function.kind, ExprKind::Var(name) if name == "__typed") => {
            if let [inner, type_expression] = args.as_slice() {
                if let (ExprKind::Var(name), ExprKind::Var(receiver_type)) =
                    (&inner.kind, &type_expression.kind)
                {
                    if name != "_"
                        && !name
                            .chars()
                            .next()
                            .is_some_and(|character| character.is_uppercase())
                    {
                        typed_receivers.insert(name.clone(), receiver_type.clone());
                    }
                }
                collect_rule_head_typed_receivers(inner, typed_receivers);
            }
        }
        ExprKind::App(_, args) | ExprKind::Tuple(args) => {
            for argument in args {
                collect_rule_head_typed_receivers(argument, typed_receivers);
            }
        }
        _ => {}
    }
}

fn rule_head_typed_receivers(head: &Expr) -> BTreeMap<String, String> {
    let mut typed_receivers = BTreeMap::new();
    if let ExprKind::App(_, args) = &head.kind {
        for argument in args {
            collect_rule_head_typed_receivers(argument, &mut typed_receivers);
        }
    }
    typed_receivers
}

fn collect_rule_head_binding_counts(expression: &Expr, counts: &mut BTreeMap<String, usize>) {
    match &expression.kind {
        ExprKind::App(function, args) if matches!(&function.kind, ExprKind::Var(name) if name == "__typed") => {
            if let Some(inner) = args.first() {
                collect_rule_head_binding_counts(inner, counts);
            }
        }
        ExprKind::Var(name)
            if name != "_"
                && !name
                    .chars()
                    .next()
                    .is_some_and(|character| character.is_uppercase()) =>
        {
            *counts.entry(name.clone()).or_default() += 1;
        }
        ExprKind::App(_, args) | ExprKind::Tuple(args) => {
            for argument in args {
                collect_rule_head_binding_counts(argument, counts);
            }
        }
        _ => {}
    }
}

fn rule_head_boolean_miss_safe_locals(head: &Expr) -> BTreeMap<String, String> {
    let mut locals = rule_head_typed_receivers(head);
    let mut counts = BTreeMap::new();
    if let ExprKind::App(_, arguments) = &head.kind {
        for argument in arguments {
            collect_rule_head_binding_counts(argument, &mut counts);
        }
    }
    locals.retain(|name, _| counts.get(name) == Some(&1));
    locals
}

pub fn analyze_top_level_binding_dependencies(stmts: &[Stmt]) -> TopLevelBindingDependencyPlan {
    let mut counts = BTreeMap::<String, usize>::new();
    let mut binding_positions = BTreeMap::<String, usize>::new();

    for (index, stmt) in stmts.iter().enumerate() {
        if let Stmt::Bind(Pat::Var(name), _, _) = stmt {
            *counts.entry(name.clone()).or_default() += 1;
            binding_positions.entry(name.clone()).or_insert(index);
        }
    }

    let binding_names = counts
        .into_iter()
        .filter_map(|(name, count)| (count == 1).then_some(name))
        .collect::<BTreeSet<_>>();

    let rule_scope_members = stmts
        .iter()
        .filter_map(|stmt| match stmt {
            Stmt::TypeDecl(TypeDecl::RuleScope { name, body, .. }) => Some((
                name.clone(),
                body.iter()
                    .filter_map(rule_scope_member_name)
                    .map(str::to_string)
                    .collect::<BTreeSet<_>>(),
            )),
            _ => None,
        })
        .collect::<BTreeMap<_, _>>();
    let rule_scope_names = rule_scope_members.keys().cloned().collect::<BTreeSet<_>>();
    let binding_rule_scopes = stmts
        .iter()
        .filter_map(|stmt| {
            let Stmt::Bind(Pat::Var(name), ty, expression) = stmt else {
                return None;
            };
            if !binding_names.contains(name) {
                return None;
            }
            let scope = ty
                .as_ref()
                .and_then(type_name)
                .filter(|name| rule_scope_names.contains(*name))
                .or_else(|| direct_rule_scope_constructor(expression, &rule_scope_names))?;
            Some((name.clone(), scope.to_string()))
        })
        .collect::<BTreeMap<_, _>>();

    let mut callable_dependencies = BTreeMap::<String, FreeSymbolUses>::new();
    for stmt in stmts {
        match stmt {
            Stmt::Defn(Defn::Fn {
                name, params, body, ..
            }) => {
                let bound = params
                    .iter()
                    .map(|param| param.name.clone())
                    .collect::<BTreeSet<_>>();
                let typed_receivers = typed_member_receivers(params);
                let uses = callable_dependencies.entry(name.clone()).or_default();
                collect_true_free_symbol_uses(body, uses, &bound, &typed_receivers);
            }
            Stmt::Rule(rule) => {
                let (head, expressions) = match rule {
                    Rule::Clause {
                        head,
                        body: Some(body),
                    } => (head, vec![body]),
                    Rule::Default {
                        head,
                        value,
                        condition,
                    }
                    | Rule::Exception {
                        head,
                        value,
                        condition,
                        ..
                    } => {
                        let mut expressions = vec![value];
                        expressions.extend(condition.iter());
                        (head, expressions)
                    }
                    Rule::Clause { head, body: None } => (head, Vec::new()),
                    Rule::ReactiveScope { .. } => continue,
                };
                let Some(name) = rule_head_name(head) else {
                    continue;
                };
                let bound = rule_head_bound_names(head);
                let typed_receivers = rule_head_typed_receivers(head);
                let uses = callable_dependencies.entry(name.to_string()).or_default();
                for expression in expressions {
                    collect_true_free_symbol_uses(expression, uses, &bound, &typed_receivers);
                }
            }
            Stmt::TypeDecl(TypeDecl::RuleScope { name, params, body }) => {
                callable_dependencies.entry(name.clone()).or_default();
                let member_names = rule_scope_members.get(name).cloned().unwrap_or_default();
                let scope_bound = params
                    .iter()
                    .map(|param| param.name.clone())
                    .collect::<BTreeSet<_>>();
                let scope_typed_receivers = typed_member_receivers(params);

                for member_stmt in body {
                    let member = match member_stmt {
                        Stmt::Defn(Defn::Fn {
                            name, params, body, ..
                        }) => {
                            let mut bound = scope_bound.clone();
                            let mut typed_receivers = scope_typed_receivers.clone();
                            extend_param_bindings(params, &mut bound, &mut typed_receivers);
                            Some((name.as_str(), bound, typed_receivers, vec![body]))
                        }
                        Stmt::Rule(rule) if !matches!(rule, Rule::ReactiveScope { .. }) => {
                            let (head, expressions) = match rule {
                                Rule::Clause {
                                    head,
                                    body: Some(body),
                                } => (head, vec![body]),
                                Rule::Default {
                                    head,
                                    value,
                                    condition,
                                }
                                | Rule::Exception {
                                    head,
                                    value,
                                    condition,
                                    ..
                                } => {
                                    let mut expressions = vec![value];
                                    expressions.extend(condition.iter());
                                    (head, expressions)
                                }
                                Rule::Clause { head, body: None } => (head, Vec::new()),
                                Rule::ReactiveScope { .. } => unreachable!(),
                            };
                            rule_head_name(head).map(|member_name| {
                                let mut bound = scope_bound.clone();
                                bound.extend(rule_head_bound_names(head));
                                let mut typed_receivers = scope_typed_receivers.clone();
                                typed_receivers.extend(rule_head_typed_receivers(head));
                                (member_name, bound, typed_receivers, expressions)
                            })
                        }
                        _ => None,
                    };
                    let Some((member_name, bound, typed_receivers, expressions)) = member else {
                        continue;
                    };

                    let mut member_uses = FreeSymbolUses::default();
                    for expression in expressions {
                        collect_true_free_symbol_uses(
                            expression,
                            &mut member_uses,
                            &bound,
                            &typed_receivers,
                        );
                    }
                    let sibling_calls = member_uses
                        .calls
                        .iter()
                        .filter(|call| member_names.contains(*call))
                        .cloned()
                        .collect::<Vec<_>>();
                    member_uses
                        .calls
                        .retain(|call| !member_names.contains(call));
                    member_uses.calls.extend(
                        sibling_calls
                            .iter()
                            .map(|call| rule_scope_member_callable_name(name, call)),
                    );
                    callable_dependencies
                        .entry(rule_scope_member_callable_name(name, member_name))
                        .or_default()
                        .extend(member_uses);
                }
            }
            Stmt::TypeDecl(TypeDecl::ADT { variants, .. })
            | Stmt::TypeDecl(TypeDecl::WhenType { variants, .. }) => {
                for variant in variants {
                    callable_dependencies
                        .entry(variant.name.clone())
                        .or_default();
                }
            }
            _ => {}
        }
    }

    let mut dependencies = BTreeMap::new();
    for (statement_index, stmt) in stmts.iter().enumerate() {
        let Stmt::Bind(Pat::Var(name), _, expression) = stmt else {
            continue;
        };
        if !binding_names.contains(name) {
            continue;
        }

        let mut uses = FreeSymbolUses::default();
        collect_true_free_symbol_uses(expression, &mut uses, &BTreeSet::new(), &BTreeMap::new());
        let FreeSymbolUses {
            values,
            value_occurrences: _,
            calls,
            member_calls,
            member_values: _,
            member_value_occurrences: _,
            typed_member_calls,
            runtime_calls: _,
            runtime_member_calls: _,
        } = uses;
        let mut callable_stack = calls.into_iter().collect::<Vec<_>>();
        callable_stack.extend(member_calls.iter().filter_map(|(receiver, member)| {
            resolve_rule_scope_member_callable(
                receiver,
                member,
                statement_index,
                &binding_positions,
                &binding_rule_scopes,
                &rule_scope_names,
            )
        }));
        callable_stack.extend(
            typed_member_calls
                .iter()
                .map(|(scope, member)| rule_scope_member_callable_name(scope, member)),
        );
        let mut visited_callables = BTreeSet::new();
        let mut binding_dependencies = values
            .into_iter()
            .filter(|symbol| binding_names.contains(symbol))
            .collect::<BTreeSet<_>>();

        while let Some(symbol) = callable_stack.pop() {
            if !visited_callables.insert(symbol.clone()) {
                continue;
            }
            if binding_names.contains(&symbol)
                && binding_positions
                    .get(&symbol)
                    .is_some_and(|position| *position < statement_index)
            {
                // An earlier value binding shadows a same-named static callable
                // in the call-site environment. The binding being initialized
                // does not shadow its own right-hand side.
                binding_dependencies.insert(symbol);
                continue;
            }
            if let Some(callable) = callable_dependencies.get(&symbol) {
                binding_dependencies.extend(
                    callable
                        .values
                        .iter()
                        .filter(|name| binding_names.contains(*name))
                        .cloned(),
                );
                callable_stack.extend(callable.calls.iter().cloned());
                callable_stack.extend(callable.member_calls.iter().filter_map(
                    |(receiver, member)| {
                        resolve_rule_scope_member_callable(
                            receiver,
                            member,
                            statement_index,
                            &binding_positions,
                            &binding_rule_scopes,
                            &rule_scope_names,
                        )
                    },
                ));
                callable_stack.extend(
                    callable
                        .typed_member_calls
                        .iter()
                        .map(|(scope, member)| rule_scope_member_callable_name(scope, member)),
                );
            } else if binding_names.contains(&symbol) {
                // A call without a static function, rule, or constructor resolves
                // through a function-valued top-level binding.
                binding_dependencies.insert(symbol);
            }
        }
        dependencies.insert(name.clone(), binding_dependencies);
    }

    TopLevelBindingDependencyPlan {
        binding_names,
        dependencies,
    }
}

/// Parsed source retained for the duration of a compiler process. Import-heavy
/// programs have several semantic consumers, but a module's syntax tree is
/// independent of the consumer that requested it.
#[derive(Debug)]
pub struct ParsedSourceModule {
    source: Arc<str>,
    statements: Arc<Vec<Stmt>>,
    content_hash: String,
}

impl ParsedSourceModule {
    pub fn source(&self) -> &str {
        &self.source
    }

    pub fn statements(&self) -> &[Stmt] {
        self.statements.as_slice()
    }

    pub fn content_hash(&self) -> &str {
        &self.content_hash
    }
}

static PARSED_SOURCE_MODULES: OnceLock<Mutex<BTreeMap<PathBuf, Arc<ParsedSourceModule>>>> =
    OnceLock::new();

fn parsed_source_modules() -> &'static Mutex<BTreeMap<PathBuf, Arc<ParsedSourceModule>>> {
    PARSED_SOURCE_MODULES.get_or_init(|| Mutex::new(BTreeMap::new()))
}

fn parsed_source_content_hash(source: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(source.as_bytes());
    format!("{:x}", hasher.finalize())
}

fn canonical_parsed_source_path(path: &Path) -> PathBuf {
    std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf())
}

/// Parse a module once per exact path/content pair and share its immutable AST
/// between graph discovery, type checking, metadata indexing, interpretation,
/// and code generation. Content hashing keeps long-lived processes correct
/// when a file is rewritten at the same path.
pub fn parse_source_module_cached(
    path: &Path,
    source: &str,
) -> Result<Arc<ParsedSourceModule>, String> {
    let path = canonical_parsed_source_path(path);
    let content_hash = parsed_source_content_hash(source);
    {
        let cache = parsed_source_modules()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(module) = cache.get(&path) {
            if module.content_hash == content_hash {
                return Ok(module.clone());
            }
        }
    }

    let mut lexer = Lexer::new(source);
    let tokens = lexer.tokenize();
    let mut parser = Parser::new(tokens, source);
    let statements = parser.parse_program()?;
    let module = Arc::new(ParsedSourceModule {
        source: Arc::from(source),
        statements: Arc::new(statements),
        content_hash,
    });
    parsed_source_modules()
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .insert(path, module.clone());
    Ok(module)
}

pub fn parse_source_module_file_cached(path: &Path) -> Result<Arc<ParsedSourceModule>, String> {
    let source = std::fs::read_to_string(path)
        .map_err(|error| format!("cannot read {}: {}", path.display(), error))?;
    parse_source_module_cached(path, &source)
}

#[derive(Debug, Clone)]
pub struct RuleScopeDef {
    pub params: Vec<Param>,
    pub body: Vec<Stmt>,
    rules_by_name: HashMap<String, Vec<Rc<Rule>>>,
}

#[derive(Debug, Clone)]
pub struct RuleScopeFrame {
    pub name: String,
    pub bindings: Rc<HashMap<String, Value>>,
    pub namespace: RuntimeNamespace,
    pub memoized_zero_arg_rules: HashMap<String, Value>,
}

/// Immutable dispatch metadata shared only while one exact Explore runtime is
/// evaluating cases. Ordinary interpretation still derives the same metadata
/// at each call; exact execution may retain it because its declaration graph
/// is frozen after guarded initialization.
#[derive(Debug)]
struct PreparedRuntimeRuleDispatch {
    matching: Vec<Rc<Rule>>,
    exceptions: Vec<usize>,
    conditional_defaults: Vec<usize>,
    clauses: Vec<usize>,
    unconditional_defaults: Vec<usize>,
    named_parameter_order: Option<Vec<String>>,
    head_local_names: BTreeSet<String>,
    body_goal_local_names: BTreeSet<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum RuntimeCallableKind {
    Function,
    Rule,
    RuleScope,
    RuleScopeFunction,
    RuleScopeRule,
    Method,
}

impl RuntimeCallableKind {
    pub fn as_str(self) -> &'static str {
        match self {
            RuntimeCallableKind::Function => "function",
            RuntimeCallableKind::Rule => "rule",
            RuntimeCallableKind::RuleScope => "rule_scope",
            RuntimeCallableKind::RuleScopeFunction => "rule_scope_function",
            RuntimeCallableKind::RuleScopeRule => "rule_scope_rule",
            RuntimeCallableKind::Method => "method",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuntimeCallableDeclaration {
    pub name: String,
    pub qualified_name: String,
    pub kind: RuntimeCallableKind,
    pub owner: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CalculationCallableReachability {
    pub declaration: RuntimeCallableDeclaration,
    pub reachable: bool,
}

#[derive(Debug, Clone, Copy)]
pub enum AstChild<'a> {
    Expr(&'a Expr),
    Stmt(&'a Stmt),
}

pub fn visit_ast_defn_children<'a, F>(defn: &'a Defn, visit: &mut F)
where
    F: FnMut(AstChild<'a>),
{
    match defn {
        Defn::Fn { body, .. } => visit(AstChild::Expr(body)),
        Defn::Actor { handlers, .. } => {
            for handler in handlers {
                visit(AstChild::Expr(&handler.body));
            }
        }
        Defn::Module { body, .. } => {
            for stmt in body {
                visit(AstChild::Stmt(stmt));
            }
        }
    }
}

pub fn visit_ast_expr_children<'a, F>(expr: &'a Expr, visit: &mut F)
where
    F: FnMut(AstChild<'a>),
{
    match &expr.kind {
        ExprKind::App(func, args) => {
            visit(AstChild::Expr(func));
            for arg in args {
                visit(AstChild::Expr(arg));
            }
        }
        ExprKind::Lambda(_, body) | ExprKind::UnOp(_, body) | ExprKind::Try(body) => {
            visit(AstChild::Expr(body));
        }
        ExprKind::BinOp(_, lhs, rhs) | ExprKind::Index(lhs, rhs) | ExprKind::Pipe(lhs, rhs) => {
            visit(AstChild::Expr(lhs));
            visit(AstChild::Expr(rhs));
        }
        ExprKind::If(cond, then_, else_) => {
            visit(AstChild::Expr(cond));
            visit(AstChild::Expr(then_));
            visit(AstChild::Expr(else_));
        }
        ExprKind::Match(scrutinee, arms) => {
            visit(AstChild::Expr(scrutinee));
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    visit(AstChild::Expr(guard));
                }
                visit(AstChild::Expr(&arm.body));
            }
        }
        ExprKind::Block(stmts) => {
            for stmt in stmts {
                visit(AstChild::Stmt(stmt));
            }
        }
        ExprKind::Field(base, _) => visit(AstChild::Expr(base)),
        ExprKind::List(items)
        | ExprKind::Tuple(items)
        | ExprKind::Conjunction(items)
        | ExprKind::Disjunction(items) => {
            for item in items {
                visit(AstChild::Expr(item));
            }
        }
        ExprKind::Effect(_, args) => {
            for arg in args {
                visit(AstChild::Expr(arg));
            }
        }
        ExprKind::Handle { handlers, body, .. } => {
            visit(AstChild::Expr(body));
            for handler in handlers {
                visit(AstChild::Expr(&handler.body));
            }
        }
        ExprKind::Var(_) | ExprKind::Lit(_) | ExprKind::Unit => {}
    }
}

pub fn visit_ast_type_decl_children<'a, F>(decl: &'a TypeDecl, visit: &mut F)
where
    F: FnMut(AstChild<'a>),
{
    match decl {
        TypeDecl::ADT { methods, .. } | TypeDecl::ImplBlock { methods, .. } => {
            for method in methods {
                visit_ast_defn_children(method, visit);
            }
        }
        TypeDecl::WhenType { condition, .. } => visit(AstChild::Expr(condition)),
        TypeDecl::TraitDecl { methods, .. } => {
            for method in methods {
                if let Some(body) = &method.default_body {
                    visit(AstChild::Expr(body));
                }
            }
        }
        TypeDecl::EffectDecl { .. } => {}
        TypeDecl::RuleScope { body, .. } => {
            for stmt in body {
                visit(AstChild::Stmt(stmt));
            }
        }
    }
}

pub fn visit_ast_rule_children<'a, F>(rule: &'a Rule, visit: &mut F)
where
    F: FnMut(AstChild<'a>),
{
    match rule {
        Rule::Clause { head, body } => {
            visit(AstChild::Expr(head));
            if let Some(body) = body {
                visit(AstChild::Expr(body));
            }
        }
        Rule::Default {
            head,
            value,
            condition,
            ..
        }
        | Rule::Exception {
            head,
            value,
            condition,
            ..
        } => {
            visit(AstChild::Expr(head));
            visit(AstChild::Expr(value));
            if let Some(condition) = condition {
                visit(AstChild::Expr(condition));
            }
        }
        Rule::ReactiveScope { body, .. } => {
            for stmt in body {
                visit(AstChild::Stmt(stmt));
            }
        }
    }
}

pub fn visit_ast_stmt_children<'a, F>(stmt: &'a Stmt, visit: &mut F)
where
    F: FnMut(AstChild<'a>),
{
    match stmt {
        Stmt::Defn(defn) => visit_ast_defn_children(defn, visit),
        Stmt::TypeDecl(decl) => visit_ast_type_decl_children(decl, visit),
        Stmt::Rule(rule) => visit_ast_rule_children(rule, visit),
        Stmt::Annot(_, args) | Stmt::Assert(_, args) | Stmt::Retract(_, args) => {
            for arg in args {
                visit(AstChild::Expr(arg));
            }
        }
        Stmt::Bind(_, _, expr) | Stmt::MonadicBind(_, _, expr) | Stmt::StreamBind(_, expr) => {
            visit(AstChild::Expr(expr));
        }
        Stmt::For(_, iter_expr, body) => {
            visit(AstChild::Expr(iter_expr));
            for stmt in body {
                visit(AstChild::Stmt(stmt));
            }
        }
        Stmt::While(cond, body) => {
            visit(AstChild::Expr(cond));
            for stmt in body {
                visit(AstChild::Stmt(stmt));
            }
        }
        Stmt::Send(target, msg) => {
            visit(AstChild::Expr(target));
            visit(AstChild::Expr(msg));
        }
        Stmt::StreamSub(expr, arms) => {
            visit(AstChild::Expr(expr));
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    visit(AstChild::Expr(guard));
                }
                visit(AstChild::Expr(&arm.body));
            }
        }
        Stmt::Invariant {
            subject, predicate, ..
        } => {
            visit(AstChild::Expr(subject));
            visit(AstChild::Expr(predicate));
        }
        Stmt::Prove {
            pass_block,
            else_block,
            ..
        } => {
            if let Some(stmts) = pass_block {
                for stmt in stmts {
                    visit(AstChild::Stmt(stmt));
                }
            }
            if let Some(stmts) = else_block {
                for stmt in stmts {
                    visit(AstChild::Stmt(stmt));
                }
            }
        }
        Stmt::Explore(query) => {
            for binding in &query.source.bindings {
                match &binding.kind {
                    ExploreSourceBindingKind::Singleton { value } => visit(AstChild::Expr(value)),
                    ExploreSourceBindingKind::Finite { domain } => visit(AstChild::Expr(domain)),
                }
            }
            match &query.successor.kind {
                ExploreSuccessorKind::Singleton { value } => visit(AstChild::Expr(value)),
                ExploreSuccessorKind::Finite { domain } => visit(AstChild::Expr(domain)),
            }
            for admission in &query.admissions {
                visit(AstChild::Expr(&admission.predicate));
            }
            if let Some(predicate) = query.selection.predicate() {
                visit(AstChild::Expr(predicate));
            }
            for node in &query.analysis {
                match node {
                    ExploreAnalysisNode::Result(result) => {
                        if let ExploreResultGrain::GroupBy { fields, .. } = &result.grain {
                            for field in fields {
                                visit(AstChild::Expr(&field.value));
                            }
                        }
                        for field in &result.measures {
                            visit(AstChild::Expr(&field.value));
                        }
                        for field in &result.aggregates {
                            match &field.reducer {
                                ExploreAggregateReducer::CountDistinct { value } => {
                                    visit(AstChild::Expr(value));
                                }
                            }
                        }
                        for field in &result.select {
                            visit(AstChild::Expr(&field.value));
                        }
                        if let Some(choice) = &result.choose {
                            match choice {
                                ExploreResultChoice::Optimize { objective, .. } => {
                                    visit(AstChild::Expr(objective));
                                }
                                ExploreResultChoice::Pareto { objectives, .. } => {
                                    for objective in objectives {
                                        visit(AstChild::Expr(&objective.value));
                                    }
                                }
                            }
                        }
                    }
                    ExploreAnalysisNode::Mechanisms(request) => {
                        visit(AstChild::Expr(&request.endpoint_template));
                    }
                }
            }
        }
        Stmt::Expr(expr) => visit(AstChild::Expr(expr)),
        Stmt::Use(_)
        | Stmt::Import(_)
        | Stmt::QualifiedImport(_, _)
        | Stmt::HashImport(_, _)
        | Stmt::Depend(_, _)
        | Stmt::RustBlock(_)
        | Stmt::Abort => {}
    }
}

pub fn walk_ast_expr<'a, F>(expr: &'a Expr, visit: &mut F)
where
    F: FnMut(AstChild<'a>),
{
    visit(AstChild::Expr(expr));
    visit_ast_expr_children(expr, &mut |child| match child {
        AstChild::Expr(expr) => walk_ast_expr(expr, visit),
        AstChild::Stmt(stmt) => walk_ast_stmt(stmt, visit),
    });
}

pub fn walk_ast_stmt<'a, F>(stmt: &'a Stmt, visit: &mut F)
where
    F: FnMut(AstChild<'a>),
{
    visit(AstChild::Stmt(stmt));
    visit_ast_stmt_children(stmt, &mut |child| match child {
        AstChild::Expr(expr) => walk_ast_expr(expr, visit),
        AstChild::Stmt(stmt) => walk_ast_stmt(stmt, visit),
    });
}

// ============================================================================
// PART 3b: CONTENT HASHING (Unison's Lesson)
// ============================================================================
// Identity is structure, not names. Two definitions with identical bodies
// get the same hash regardless of what they're called.

fn strip_spans_expr(expr: &Expr) -> Expr {
    let kind = match &expr.kind {
        ExprKind::Var(name) => ExprKind::Var(name.clone()),
        ExprKind::Lit(lit) => ExprKind::Lit(lit.clone()),
        ExprKind::App(func, args) => ExprKind::App(
            Box::new(strip_spans_expr(func)),
            args.iter().map(strip_spans_expr).collect(),
        ),
        ExprKind::Lambda(params, body) => {
            ExprKind::Lambda(params.clone(), Box::new(strip_spans_expr(body)))
        }
        ExprKind::BinOp(op, lhs, rhs) => ExprKind::BinOp(
            op.clone(),
            Box::new(strip_spans_expr(lhs)),
            Box::new(strip_spans_expr(rhs)),
        ),
        ExprKind::UnOp(op, inner) => ExprKind::UnOp(op.clone(), Box::new(strip_spans_expr(inner))),
        ExprKind::If(cond, then_, else_) => ExprKind::If(
            Box::new(strip_spans_expr(cond)),
            Box::new(strip_spans_expr(then_)),
            Box::new(strip_spans_expr(else_)),
        ),
        ExprKind::Match(scrutinee, arms) => ExprKind::Match(
            Box::new(strip_spans_expr(scrutinee)),
            arms.iter().map(strip_spans_match_arm).collect(),
        ),
        ExprKind::Block(stmts) => ExprKind::Block(stmts.iter().map(strip_spans_stmt).collect()),
        ExprKind::Field(obj, field) => {
            ExprKind::Field(Box::new(strip_spans_expr(obj)), field.clone())
        }
        ExprKind::Index(base, idx) => ExprKind::Index(
            Box::new(strip_spans_expr(base)),
            Box::new(strip_spans_expr(idx)),
        ),
        ExprKind::List(items) => ExprKind::List(items.iter().map(strip_spans_expr).collect()),
        ExprKind::Tuple(items) => ExprKind::Tuple(items.iter().map(strip_spans_expr).collect()),
        ExprKind::Effect(name, args) => {
            ExprKind::Effect(name.clone(), args.iter().map(strip_spans_expr).collect())
        }
        ExprKind::Handle {
            effect,
            handlers,
            body,
        } => ExprKind::Handle {
            effect: effect.clone(),
            handlers: handlers.iter().map(strip_spans_eff_handler).collect(),
            body: Box::new(strip_spans_expr(body)),
        },
        ExprKind::Try(inner) => ExprKind::Try(Box::new(strip_spans_expr(inner))),
        ExprKind::Conjunction(items) => {
            ExprKind::Conjunction(items.iter().map(strip_spans_expr).collect())
        }
        ExprKind::Disjunction(items) => {
            ExprKind::Disjunction(items.iter().map(strip_spans_expr).collect())
        }
        ExprKind::Pipe(lhs, rhs) => ExprKind::Pipe(
            Box::new(strip_spans_expr(lhs)),
            Box::new(strip_spans_expr(rhs)),
        ),
        ExprKind::Unit => ExprKind::Unit,
    };
    Expr {
        kind,
        span: Span::dummy(),
    }
}

fn strip_spans_eff_handler(handler: &EffHandler) -> EffHandler {
    EffHandler {
        op_name: handler.op_name.clone(),
        params: handler.params.clone(),
        body: strip_spans_expr(&handler.body),
    }
}

fn strip_spans_match_arm(arm: &MatchArm) -> MatchArm {
    MatchArm {
        pat: arm.pat.clone(),
        guard: arm.guard.as_ref().map(strip_spans_expr),
        body: strip_spans_expr(&arm.body),
    }
}

fn strip_spans_rule(rule: &Rule) -> Rule {
    match rule {
        Rule::Clause { head, body } => Rule::Clause {
            head: strip_spans_expr(head),
            body: body.as_ref().map(strip_spans_expr),
        },
        Rule::Default {
            head,
            value,
            condition,
        } => Rule::Default {
            head: strip_spans_expr(head),
            value: strip_spans_expr(value),
            condition: condition.as_ref().map(strip_spans_expr),
        },
        Rule::Exception {
            label,
            head,
            value,
            condition,
        } => Rule::Exception {
            label: label.clone(),
            head: strip_spans_expr(head),
            value: strip_spans_expr(value),
            condition: condition.as_ref().map(strip_spans_expr),
        },
        Rule::ReactiveScope { name, body } => Rule::ReactiveScope {
            name: name.clone(),
            body: body.iter().map(strip_spans_stmt).collect(),
        },
    }
}

fn strip_spans_defn(defn: &Defn) -> Defn {
    match defn {
        Defn::Fn {
            name,
            params,
            ret_ty,
            effects,
            body,
        } => Defn::Fn {
            name: name.clone(),
            params: params.clone(),
            ret_ty: ret_ty.clone(),
            effects: effects.clone(),
            body: strip_spans_expr(body),
        },
        Defn::Actor {
            name,
            state_param,
            handlers,
        } => Defn::Actor {
            name: name.clone(),
            state_param: state_param.clone(),
            handlers: handlers
                .iter()
                .map(|handler| Handler {
                    msg_pat: handler.msg_pat.clone(),
                    body: strip_spans_expr(&handler.body),
                })
                .collect(),
        },
        Defn::Module { name, body } => Defn::Module {
            name: name.clone(),
            body: body.iter().map(strip_spans_stmt).collect(),
        },
    }
}

fn strip_spans_type_decl(td: &TypeDecl) -> TypeDecl {
    match td {
        TypeDecl::ADT {
            name,
            params,
            variants,
            methods,
            except_from,
        } => TypeDecl::ADT {
            name: name.clone(),
            params: params.clone(),
            variants: variants.clone(),
            methods: methods.iter().map(strip_spans_defn).collect(),
            except_from: except_from.clone(),
        },
        TypeDecl::WhenType {
            name,
            condition,
            variants,
            except_from,
        } => TypeDecl::WhenType {
            name: name.clone(),
            condition: strip_spans_expr(condition),
            variants: variants.clone(),
            except_from: except_from.clone(),
        },
        TypeDecl::EffectDecl { name, ops } => TypeDecl::EffectDecl {
            name: name.clone(),
            ops: ops.clone(),
        },
        TypeDecl::TraitDecl {
            name,
            params,
            methods,
        } => TypeDecl::TraitDecl {
            name: name.clone(),
            params: params.clone(),
            methods: methods
                .iter()
                .map(|method| TraitMethod {
                    name: method.name.clone(),
                    params: method.params.clone(),
                    ret_ty: method.ret_ty.clone(),
                    default_body: method.default_body.as_ref().map(strip_spans_expr),
                })
                .collect(),
        },
        TypeDecl::ImplBlock {
            trait_name,
            for_type,
            methods,
        } => TypeDecl::ImplBlock {
            trait_name: trait_name.clone(),
            for_type: for_type.clone(),
            methods: methods.iter().map(strip_spans_defn).collect(),
        },
        TypeDecl::RuleScope { name, params, body } => TypeDecl::RuleScope {
            name: name.clone(),
            params: params.clone(),
            body: body.iter().map(strip_spans_stmt).collect(),
        },
    }
}

fn strip_spans_explore_result_field(field: &ExploreResultField) -> ExploreResultField {
    ExploreResultField {
        name: field.name.clone(),
        value: strip_spans_expr(&field.value),
        span: Span::dummy(),
    }
}

fn strip_spans_explore_aggregate_field(field: &ExploreAggregateField) -> ExploreAggregateField {
    ExploreAggregateField {
        name: field.name.clone(),
        reducer: match &field.reducer {
            ExploreAggregateReducer::CountDistinct { value } => {
                ExploreAggregateReducer::CountDistinct {
                    value: strip_spans_expr(value),
                }
            }
        },
        span: Span::dummy(),
    }
}

fn strip_spans_explore_having(having: &ExploreResultHaving) -> ExploreResultHaving {
    match having {
        ExploreResultHaving::Varies { measure_name, .. } => ExploreResultHaving::Varies {
            measure_name: measure_name.clone(),
            span: Span::dummy(),
        },
    }
}

fn strip_spans_explore_choice(choice: &ExploreResultChoice) -> ExploreResultChoice {
    match choice {
        ExploreResultChoice::Optimize {
            cardinality,
            direction,
            objective,
            ..
        } => ExploreResultChoice::Optimize {
            cardinality: *cardinality,
            direction: *direction,
            objective: strip_spans_expr(objective),
            span: Span::dummy(),
        },
        ExploreResultChoice::Pareto { objectives, .. } => ExploreResultChoice::Pareto {
            objectives: objectives
                .iter()
                .map(|objective| ExploreParetoObjective {
                    direction: objective.direction,
                    value: strip_spans_expr(&objective.value),
                    span: Span::dummy(),
                })
                .collect(),
            span: Span::dummy(),
        },
    }
}

fn strip_spans_explore_query(query: &ExploreQuery) -> ExploreQuery {
    ExploreQuery {
        name: query.name.clone(),
        source: ExploreSourceRelation {
            bindings: query
                .source
                .bindings
                .iter()
                .map(|binding| ExploreSourceBinding {
                    name: binding.name.clone(),
                    kind: match &binding.kind {
                        ExploreSourceBindingKind::Singleton { value } => {
                            ExploreSourceBindingKind::Singleton {
                                value: strip_spans_expr(value),
                            }
                        }
                        ExploreSourceBindingKind::Finite { domain } => {
                            ExploreSourceBindingKind::Finite {
                                domain: strip_spans_expr(domain),
                            }
                        }
                    },
                    span: Span::dummy(),
                })
                .collect(),
            span: Span::dummy(),
        },
        successor: ExploreSuccessorRelation {
            kind: match &query.successor.kind {
                ExploreSuccessorKind::Singleton { value } => ExploreSuccessorKind::Singleton {
                    value: strip_spans_expr(value),
                },
                ExploreSuccessorKind::Finite { domain } => ExploreSuccessorKind::Finite {
                    domain: strip_spans_expr(domain),
                },
            },
            span: Span::dummy(),
        },
        admissions: query
            .admissions
            .iter()
            .map(|admission| ExploreAdmission {
                scope: admission.scope,
                predicate: strip_spans_expr(&admission.predicate),
                span: Span::dummy(),
            })
            .collect(),
        selection: match &query.selection {
            ExploreSelection::All { .. } => ExploreSelection::All {
                span: Span::dummy(),
            },
            ExploreSelection::Matches { predicate, .. } => ExploreSelection::Matches {
                predicate: strip_spans_expr(predicate),
                span: Span::dummy(),
            },
            ExploreSelection::Violations { predicate, .. } => ExploreSelection::Violations {
                predicate: strip_spans_expr(predicate),
                span: Span::dummy(),
            },
        },
        analysis: query
            .analysis
            .iter()
            .map(|node| match node {
                ExploreAnalysisNode::Result(result) => {
                    ExploreAnalysisNode::Result(ExploreResultView {
                        name: result.name.clone(),
                        input: result.input.clone(),
                        grain: match &result.grain {
                            ExploreResultGrain::EachCase { .. } => ExploreResultGrain::EachCase {
                                span: Span::dummy(),
                            },
                            ExploreResultGrain::EachIncidence { .. } => {
                                ExploreResultGrain::EachIncidence {
                                    span: Span::dummy(),
                                }
                            }
                            ExploreResultGrain::GroupAll { .. } => ExploreResultGrain::GroupAll {
                                span: Span::dummy(),
                            },
                            ExploreResultGrain::GroupBy { fields, .. } => {
                                ExploreResultGrain::GroupBy {
                                    fields: fields
                                        .iter()
                                        .map(strip_spans_explore_result_field)
                                        .collect(),
                                    span: Span::dummy(),
                                }
                            }
                        },
                        measures: result
                            .measures
                            .iter()
                            .map(strip_spans_explore_result_field)
                            .collect(),
                        aggregates: result
                            .aggregates
                            .iter()
                            .map(strip_spans_explore_aggregate_field)
                            .collect(),
                        having: result.having.as_ref().map(strip_spans_explore_having),
                        select: result
                            .select
                            .iter()
                            .map(strip_spans_explore_result_field)
                            .collect(),
                        choose: result.choose.as_ref().map(strip_spans_explore_choice),
                        span: Span::dummy(),
                    })
                }
                ExploreAnalysisNode::Mechanisms(request) => {
                    ExploreAnalysisNode::Mechanisms(ExploreMechanismRequest {
                        name: request.name.clone(),
                        target: request.target.clone(),
                        callable_name: request.callable_name.clone(),
                        endpoint_template: strip_spans_expr(&request.endpoint_template),
                        span: Span::dummy(),
                    })
                }
            })
            .collect(),
        // Starter projections are appendable publication consumers with their
        // own checked identity. Excluding them here keeps the normalized
        // program and every upstream Explore identity stable when a consumer
        // is attached to an existing run.
        starter_projections: Vec::new(),
        // Full transition-graph declarations are publication consumers too.
        // They must never rename the relation/admission/question or analysis
        // program whose durable journal they observe.
        transition_graphs: Vec::new(),
        span: Span::dummy(),
    }
}

fn strip_spans_stmt(stmt: &Stmt) -> Stmt {
    match stmt {
        Stmt::Defn(defn) => Stmt::Defn(strip_spans_defn(defn)),
        Stmt::TypeDecl(td) => Stmt::TypeDecl(strip_spans_type_decl(td)),
        Stmt::Rule(rule) => Stmt::Rule(strip_spans_rule(rule)),
        Stmt::Use(path) => Stmt::Use(path.clone()),
        Stmt::Import(path) => Stmt::Import(path.clone()),
        Stmt::QualifiedImport(name, path) => Stmt::QualifiedImport(name.clone(), path.clone()),
        Stmt::HashImport(hash, path) => Stmt::HashImport(hash.clone(), path.clone()),
        Stmt::Depend(name, version) => Stmt::Depend(name.clone(), version.clone()),
        Stmt::RustBlock(code) => Stmt::RustBlock(code.clone()),
        Stmt::Annot(name, args) => {
            Stmt::Annot(name.clone(), args.iter().map(strip_spans_expr).collect())
        }
        Stmt::Bind(pat, ty, expr) => Stmt::Bind(pat.clone(), ty.clone(), strip_spans_expr(expr)),
        Stmt::MonadicBind(pat, ty, expr) => {
            Stmt::MonadicBind(pat.clone(), ty.clone(), strip_spans_expr(expr))
        }
        Stmt::For(var, expr, body) => Stmt::For(
            var.clone(),
            strip_spans_expr(expr),
            body.iter().map(strip_spans_stmt).collect(),
        ),
        Stmt::While(cond, body) => Stmt::While(
            strip_spans_expr(cond),
            body.iter().map(strip_spans_stmt).collect(),
        ),
        Stmt::Send(target, msg) => Stmt::Send(strip_spans_expr(target), strip_spans_expr(msg)),
        Stmt::StreamBind(name, expr) => Stmt::StreamBind(name.clone(), strip_spans_expr(expr)),
        Stmt::StreamSub(expr, arms) => Stmt::StreamSub(
            strip_spans_expr(expr),
            arms.iter().map(strip_spans_match_arm).collect(),
        ),
        Stmt::Invariant {
            name,
            subject,
            predicate,
        } => Stmt::Invariant {
            name: name.clone(),
            subject: strip_spans_expr(subject),
            predicate: strip_spans_expr(predicate),
        },
        Stmt::Prove {
            name,
            proof_block,
            capture,
            pass_block,
            else_block,
        } => Stmt::Prove {
            name: name.clone(),
            proof_block: proof_block.clone(),
            capture: capture.clone(),
            pass_block: pass_block
                .as_ref()
                .map(|stmts| stmts.iter().map(strip_spans_stmt).collect()),
            else_block: else_block
                .as_ref()
                .map(|stmts| stmts.iter().map(strip_spans_stmt).collect()),
        },
        Stmt::Explore(query) => Stmt::Explore(strip_spans_explore_query(query)),
        Stmt::Assert(name, args) => {
            Stmt::Assert(name.clone(), args.iter().map(strip_spans_expr).collect())
        }
        Stmt::Retract(name, args) => {
            Stmt::Retract(name.clone(), args.iter().map(strip_spans_expr).collect())
        }
        Stmt::Abort => Stmt::Abort,
        Stmt::Expr(expr) => Stmt::Expr(strip_spans_expr(expr)),
    }
}

/// Compute a canonical structural representation of a Defn (excluding the name).
/// Two functions with different names but identical params/body get the same hash.
pub fn content_hash_defn(defn: &Defn) -> String {
    let canonical = match defn {
        Defn::Fn {
            params,
            ret_ty,
            effects,
            body,
            ..
        } => {
            format!(
                "FN({:?},{:?},{:?},{:?})",
                params,
                ret_ty,
                effects,
                strip_spans_expr(body)
            )
        }
        Defn::Actor {
            state_param,
            handlers,
            ..
        } => {
            let stripped_handlers: Vec<Handler> = handlers
                .iter()
                .map(|handler| Handler {
                    msg_pat: handler.msg_pat.clone(),
                    body: strip_spans_expr(&handler.body),
                })
                .collect();
            format!("ACTOR({:?},{:?})", state_param, stripped_handlers)
        }
        Defn::Module { body, .. } => {
            format!(
                "MODULE({:?})",
                body.iter().map(strip_spans_stmt).collect::<Vec<_>>()
            )
        }
    };
    hash_string(&canonical)
}

/// Compute a canonical structural representation of a TypeDecl (excluding the name).
pub fn content_hash_type(td: &TypeDecl) -> String {
    let canonical = match td {
        TypeDecl::ADT {
            params,
            variants,
            methods,
            ..
        } => {
            format!(
                "ADT({:?},{:?},{:?})",
                params,
                variants,
                methods.iter().map(strip_spans_defn).collect::<Vec<_>>()
            )
        }
        TypeDecl::EffectDecl { ops, .. } => {
            format!("EFFECT({:?})", ops)
        }
        TypeDecl::TraitDecl {
            params, methods, ..
        } => {
            let stripped_methods: Vec<TraitMethod> = methods
                .iter()
                .map(|method| TraitMethod {
                    name: method.name.clone(),
                    params: method.params.clone(),
                    ret_ty: method.ret_ty.clone(),
                    default_body: method.default_body.as_ref().map(strip_spans_expr),
                })
                .collect();
            format!("TRAIT({:?},{:?})", params, stripped_methods)
        }
        TypeDecl::ImplBlock {
            trait_name,
            for_type,
            methods,
            ..
        } => {
            format!(
                "IMPL({:?},{:?},{:?})",
                trait_name,
                for_type,
                methods.iter().map(strip_spans_defn).collect::<Vec<_>>()
            )
        }
        TypeDecl::WhenType { name, variants, .. } => {
            format!(
                "WHEN({},{})",
                name,
                variants
                    .iter()
                    .map(|v| v.name.as_str())
                    .collect::<Vec<_>>()
                    .join("|")
            )
        }
        TypeDecl::RuleScope { params, body, .. } => {
            format!(
                "RULESCOPE({:?},{:?})",
                params,
                body.iter().map(strip_spans_stmt).collect::<Vec<_>>()
            )
        }
    };
    hash_string(&canonical)
}

/// SHA-256 of a string, truncated to 12 hex chars (48 bits — collision-safe for codebases).
pub fn hash_string(s: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(s.as_bytes());
    let result = hasher.finalize();
    // First 6 bytes = 12 hex chars
    format!(
        "{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        result[0], result[1], result[2], result[3], result[4], result[5]
    )
}

/// Get the name of a Defn.
pub fn defn_name(defn: &Defn) -> &str {
    match defn {
        Defn::Fn { name, .. } => name,
        Defn::Actor { name, .. } => name,
        Defn::Module { name, .. } => name,
    }
}

/// Get the name of a TypeDecl.
pub fn type_decl_name(td: &TypeDecl) -> &str {
    match td {
        TypeDecl::ADT { name, .. } => name,
        TypeDecl::EffectDecl { name, .. } => name,
        TypeDecl::TraitDecl { name, .. } => name,
        TypeDecl::ImplBlock {
            trait_name,
            for_type,
            ..
        } => {
            // impl blocks don't have a single name, use for_type
            for_type
        }
        TypeDecl::WhenType { name, .. } => name,
        TypeDecl::RuleScope { name, .. } => name,
    }
}

/// Print content hashes for all definitions in a program.
pub fn print_hashes(stmts: &[Stmt]) {
    let mut found = false;
    for stmt in stmts {
        match stmt {
            Stmt::Defn(defn) => {
                let hash = content_hash_defn(defn);
                let kind = match defn {
                    Defn::Fn { .. } => ">",
                    Defn::Actor { .. } => "|",
                    Defn::Module { .. } => "mod",
                };
                println!("  {} {} #{}", kind, defn_name(defn), hash);
                found = true;
            }
            Stmt::TypeDecl(td) => {
                let hash = content_hash_type(td);
                let kind = match td {
                    TypeDecl::ADT { .. } => "#",
                    TypeDecl::EffectDecl { .. } => "# effect",
                    TypeDecl::TraitDecl { .. } => "# trait",
                    TypeDecl::ImplBlock { .. } => "# impl",
                    TypeDecl::WhenType { .. } => "# WHEN",
                    TypeDecl::RuleScope { .. } => "# rulescope",
                };
                println!("  {} {} #{}", kind, type_decl_name(td), hash);
                found = true;
            }
            _ => {}
        }
    }
    if !found {
        println!("  (no definitions found)");
    }
}

// ============================================================================
// PART 4: PARSER
// ============================================================================

fn layout_previous_requires_continuation(token: &Token) -> bool {
    match token.kind {
        TokenKind::LParen
        | TokenKind::LBracket
        | TokenKind::Comma
        | TokenKind::Colon
        | TokenKind::Arrow
        | TokenKind::FatArrow
        | TokenKind::Dot
        | TokenKind::Pipe
        | TokenKind::PipeGt
        | TokenKind::SafeCall
        | TokenKind::Elvis
        | TokenKind::Send
        | TokenKind::Hash
        | TokenKind::At
        | TokenKind::Gt
        | TokenKind::Eq
        | TokenKind::Tilde => true,
        TokenKind::Op => token.text != "?",
        TokenKind::Ident | TokenKind::KW | TokenKind::Type => matches!(
            token.text.as_str(),
            "under" | "if" | "else" | "match" | "for" | "while" | "in" | "WHEN" | "by"
        ),
        _ => false,
    }
}

fn layout_next_continues_statement(token: &Token) -> bool {
    match token.kind {
        TokenKind::Arrow
        | TokenKind::FatArrow
        | TokenKind::Dot
        | TokenKind::PipeGt
        | TokenKind::SafeCall
        | TokenKind::Elvis
        | TokenKind::Send
        | TokenKind::LBrace
        | TokenKind::RParen
        | TokenKind::RBracket => true,
        TokenKind::Op => matches!(
            token.text.as_str(),
            "&&" | "==" | "!=" | "<" | "<=" | ">" | ">=" | "*" | "/" | "%" | "^"
        ),
        TokenKind::Ident | TokenKind::KW => {
            matches!(token.text.as_str(), "under" | "else" | "and" | "in")
        }
        _ => false,
    }
}

fn layout_inside_soft_delimiter(delimiters: &[TokenKind]) -> bool {
    matches!(
        delimiters.last(),
        Some(TokenKind::LParen | TokenKind::LBracket)
    )
}

/// Classify raw lexer newlines once, before grammar-specific parsing.
///
/// The lexer intentionally retains every statement newline as `Semi` so rune
/// detection remains source-accurate. The parser removes only newlines that
/// cannot terminate the current construct: those inside parentheses/brackets,
/// after incomplete syntax, or before an unambiguous continuation token.
/// Braces remain a hard statement boundary even when nested in a call.
fn classify_layout_newlines(tokens: Vec<Token>) -> Vec<Token> {
    let mut output = Vec::with_capacity(tokens.len());
    let mut delimiters = Vec::new();
    let mut softened_before_next = false;

    for (index, token) in tokens.iter().enumerate() {
        if token.kind == TokenKind::Semi {
            let previous = output
                .iter()
                .rev()
                .find(|token: &&Token| token.kind != TokenKind::Semi);
            let next = tokens[index + 1..]
                .iter()
                .find(|token| token.kind != TokenKind::Semi);
            let soft = layout_inside_soft_delimiter(&delimiters)
                || previous.is_some_and(|token| layout_previous_requires_continuation(token))
                || next.is_some_and(layout_next_continues_statement);
            if soft {
                softened_before_next = true;
                continue;
            }
            output.push(token.clone());
            softened_before_next = false;
            continue;
        }

        let mut token = token.clone();
        if softened_before_next {
            if token.kind == TokenKind::Gt {
                token.kind = TokenKind::Op;
            } else if token.kind == TokenKind::Eq {
                token.kind = TokenKind::Op;
            }
        }
        softened_before_next = false;

        match token.kind {
            TokenKind::LParen | TokenKind::LBracket | TokenKind::LBrace => {
                delimiters.push(token.kind)
            }
            TokenKind::RParen | TokenKind::RBracket | TokenKind::RBrace => {
                let expected = match token.kind {
                    TokenKind::RParen => TokenKind::LParen,
                    TokenKind::RBracket => TokenKind::LBracket,
                    TokenKind::RBrace => TokenKind::LBrace,
                    _ => unreachable!(),
                };
                if let Some(position) = delimiters.iter().rposition(|kind| *kind == expected) {
                    delimiters.truncate(position);
                }
            }
            _ => {}
        }
        output.push(token);
    }

    output
}

pub struct Parser {
    pub tokens: Vec<Token>,
    pub pos: usize,
    pub source_chars: Vec<char>,
    pub line_starts: Vec<usize>, // line_starts[i] = char index of start of line (i+1)
    pub in_rule_body: bool,      // true when parsing | rule body (and = conjunction, not &&)
}

impl Parser {
    pub fn new(tokens: Vec<Token>, source: &str) -> Self {
        let tokens = classify_layout_newlines(tokens);
        let source_chars: Vec<char> = source.chars().collect();
        let mut line_starts = vec![0usize]; // line 1 starts at char 0
        for (i, &c) in source_chars.iter().enumerate() {
            if c == '\n' && i + 1 < source_chars.len() {
                line_starts.push(i + 1);
            }
        }
        Parser {
            tokens,
            pos: 0,
            source_chars,
            line_starts,
            in_rule_body: false,
        }
    }

    /// Convert token line/col (1-based) to char offset in source_chars.
    pub fn char_offset(&self, line: usize, col: usize) -> usize {
        let line_idx = (line - 1).min(self.line_starts.len() - 1);
        self.line_starts[line_idx] + (col - 1)
    }

    /// Create a Span from a token's position to the end of its text.
    pub fn token_span(&self, tok: &Token) -> Span {
        let start = self.char_offset(tok.line, tok.col);
        let end = start + tok.source_text.chars().count();
        Span::new(start, end)
    }

    /// Create a Span from start token to end of most recently consumed token.
    pub fn span_since(&self, start_tok: &Token) -> Span {
        let start = self.char_offset(start_tok.line, start_tok.col);
        let prev = if self.pos > 0 {
            &self.tokens[self.pos - 1]
        } else {
            start_tok
        };
        let end = self.char_offset(prev.line, prev.col) + prev.source_text.chars().count();
        Span::new(start, end)
    }

    /// Create a spanned Expr using token positions.
    pub fn spanned(&self, kind: ExprKind, start_tok: &Token) -> Expr {
        Expr::new(kind, self.span_since(start_tok))
    }

    pub fn peek(&self) -> &Token {
        self.tokens.get(self.pos).unwrap_or(
            self.tokens.last().unwrap(), // EOF
        )
    }

    pub fn peek_kind(&self) -> TokenKind {
        self.peek().kind
    }

    pub fn advance(&mut self) -> Token {
        let tok = self
            .tokens
            .get(self.pos)
            .cloned()
            .unwrap_or_else(|| Token::new(TokenKind::Eof, "", 0, 0));
        self.pos += 1;
        tok
    }

    pub fn token_display(kind: TokenKind) -> &'static str {
        match kind {
            TokenKind::LBrace => "`{`",
            TokenKind::RBrace => "`}`",
            TokenKind::LParen => "`(`",
            TokenKind::RParen => "`)`",
            TokenKind::LBracket => "`[`",
            TokenKind::RBracket => "`]`",
            TokenKind::Arrow => "`->`",
            TokenKind::Comma => "`,`",
            TokenKind::Colon => "`:`",
            TokenKind::Semi => "a newline",
            TokenKind::Dot => "`.`",
            TokenKind::Eq => "`=`",
            TokenKind::Pipe => "`|`",
            TokenKind::Hash => "`#`",
            TokenKind::At => "`@`",
            TokenKind::Tilde => "`~`",
            TokenKind::Gt => "`>`",
            TokenKind::Eof => "end of file",
            TokenKind::Ident => "an identifier",
            TokenKind::Type => "a type name",
            TokenKind::String_ => "a string",
            TokenKind::Int_ => "a number",
            TokenKind::Float_ => "a number",
            TokenKind::KW => "a keyword",
            TokenKind::Send => "`<-`",
            _ => "token",
        }
    }

    pub fn expect(&mut self, kind: TokenKind) -> Result<Token, String> {
        let tok = self.advance();
        if tok.kind == kind {
            Ok(tok)
        } else {
            // Context-sensitive hints for common mistakes
            let hint = if kind == TokenKind::Arrow && tok.text == "=>" {
                "\n  Hint: Futuruna uses `->`, not `=>`. Replace `=>` with `->`."
            } else if kind == TokenKind::LBrace && tok.kind == TokenKind::Arrow {
                "\n  Hint: did you forget `{` before the body?"
            } else if kind == TokenKind::Comma && tok.kind == TokenKind::Colon {
                "\n  Hint: this looks like a type annotation. Typed parameters are valid in `>` functions and `|` rule heads, but ordinary call arguments use values, not declarations."
            } else if kind == TokenKind::RParen && tok.kind == TokenKind::Colon {
                "\n  Hint: unexpected `:` — type annotations belong in parameter declarations, such as `> f(x: Type)` or `| rule(x: Type) -> ...`."
            } else if tok.kind == TokenKind::Semi {
                "\n  Hint: this newline ended the statement. Put an incomplete token such as `=`, `->`, `,`, or an operator before the break, or wrap the continued expression in `(...)`."
            } else {
                ""
            };
            Err(format!(
                "{}:{}: expected {}, got `{}`{}",
                tok.line,
                tok.col,
                Self::token_display(kind),
                tok.text,
                hint
            ))
        }
    }

    pub fn expect_ident(&mut self) -> Result<String, String> {
        let tok = self.advance();
        match tok.kind {
            TokenKind::Ident | TokenKind::Type | TokenKind::Bool_ | TokenKind::KW => Ok(tok.text),
            _ => Err(format!(
                "{}:{}: expected an identifier, got `{}`",
                tok.line, tok.col, tok.source_text
            )),
        }
    }

    pub fn expect_field_name(&mut self) -> Result<String, String> {
        let tok = self.advance();
        match tok.kind {
            TokenKind::Ident | TokenKind::Type | TokenKind::Bool_ | TokenKind::KW => {
                Ok(tok.source_text)
            }
            TokenKind::Int_ => Ok(tok.text),
            _ => Err(format!(
                "{}:{}: expected a field name or tuple index, got `{}`",
                tok.line, tok.col, tok.source_text
            )),
        }
    }

    /// Parse a qualified name like `fmt::Display` or `std::ops::Add`.
    /// Returns the full path string.
    pub fn parse_qualified_name(&mut self) -> Result<String, String> {
        let mut name = self.expect_ident()?;
        while self.peek_kind() == TokenKind::Colon {
            let saved = self.pos;
            self.advance(); // first :
            if self.peek_kind() == TokenKind::Colon {
                self.advance(); // second :
                let seg = self.expect_ident()?;
                name.push_str("::");
                name.push_str(&seg);
            } else {
                self.pos = saved; // backtrack — was just a single :
                break;
            }
        }
        Ok(name)
    }

    pub fn skip_semis(&mut self) {
        while self.peek_kind() == TokenKind::Semi {
            self.advance();
        }
    }

    fn parse_comma_separated<T>(
        &mut self,
        closing: TokenKind,
        item_description: &str,
        mut parse_item: impl FnMut(&mut Self) -> Result<T, String>,
    ) -> Result<Vec<T>, String> {
        let mut items = Vec::new();
        self.skip_semis();
        while self.peek_kind() != closing {
            if self.peek_kind() == TokenKind::Eof {
                let token = self.peek();
                return Err(format!(
                    "{}:{}: expected {} to close {}, got end of file",
                    token.line,
                    token.col,
                    Self::token_display(closing),
                    item_description
                ));
            }

            items.push(parse_item(self)?);
            self.skip_semis();
            if self.peek_kind() == closing {
                break;
            }
            if self.peek_kind() != TokenKind::Comma {
                let token = self.peek();
                return Err(format!(
                    "{}:{}: expected `,` or {} after {}, got `{}`\n  Hint: separate adjacent {} with commas; a trailing comma before {} is allowed.",
                    token.line,
                    token.col,
                    Self::token_display(closing),
                    item_description,
                    token.source_text,
                    item_description,
                    Self::token_display(closing)
                ));
            }
            self.advance();
            self.skip_semis();
            if self.peek_kind() == closing {
                break;
            }
        }
        self.expect(closing)?;
        Ok(items)
    }

    pub fn at_block_end(&self) -> bool {
        matches!(self.peek_kind(), TokenKind::RBrace | TokenKind::Eof)
    }

    fn peek_word(&self, word: &str) -> bool {
        matches!(
            self.peek_kind(),
            TokenKind::Ident | TokenKind::KW | TokenKind::Type
        ) && self.peek().text == word
    }

    fn parse_dotted_name(&mut self) -> Result<String, String> {
        let mut name = self.expect_ident()?;
        while self.peek_kind() == TokenKind::Dot {
            self.advance();
            let seg = self.expect_ident()?;
            name.push('.');
            name.push_str(&seg);
        }
        Ok(name)
    }

    fn parse_proof_block(&mut self) -> Result<ProofBlock, String> {
        self.expect(TokenKind::LBrace)?;
        self.skip_semis();
        let mut arms = Vec::new();

        while self.peek_kind() != TokenKind::RBrace {
            self.expect(TokenKind::Pipe)?;
            let binders = self.parse_proof_binders()?;
            self.expect(TokenKind::Arrow)?;
            let term = self.parse_proof_term()?;
            arms.push(ProofArm { binders, term });
            self.skip_semis();
        }

        self.expect(TokenKind::RBrace)?;
        if arms.is_empty() {
            return Err("proof block needs at least one `| ... -> ...` arm".into());
        }
        Ok(ProofBlock { arms })
    }

    fn parse_proof_binders(&mut self) -> Result<Vec<String>, String> {
        if self.peek_kind() == TokenKind::LParen {
            self.advance();
            self.parse_comma_separated(TokenKind::RParen, "proof binder", |parser| {
                let binder = parser.expect_ident()?;
                if binder == "_" {
                    return Err("proof binders cannot use `_` yet".into());
                }
                if parser.peek_kind() == TokenKind::Colon {
                    parser.advance();
                    let _ = parser.parse_type()?;
                }
                Ok(binder)
            })
        } else {
            let binder = self.expect_ident()?;
            if binder == "_" {
                return Err("proof binders cannot use `_` yet".into());
            }
            if self.peek_kind() == TokenKind::Colon {
                self.advance();
                let _ = self.parse_type()?;
            }
            Ok(vec![binder])
        }
    }

    fn proof_ctor_arm_from_pattern(
        &self,
        pat: Pat,
        arm_kind: &str,
    ) -> Result<(String, Vec<String>), String> {
        match pat {
            Pat::Con(ctor, binders) => {
                let mut names = Vec::new();
                for binder in binders {
                    match binder {
                        Pat::Var(name) if name != "_" => names.push(name),
                        Pat::Wild => {
                            return Err(format!("{} cannot use `_` binders yet", arm_kind));
                        }
                        _ => {
                            return Err(format!(
                                "{} currently require simple constructor binders",
                                arm_kind
                            ));
                        }
                    }
                }
                Ok((ctor, names))
            }
            _ => Err(format!("{} require constructor patterns", arm_kind)),
        }
    }

    fn parse_proof_term(&mut self) -> Result<proof_kernel::ProofTerm, String> {
        if self.peek_kind() == TokenKind::LParen {
            self.advance();
            let term = self.parse_proof_term()?;
            self.expect(TokenKind::RParen)?;
            return Ok(term);
        }

        if self.peek_word("refl") {
            self.advance();
            return Ok(proof_kernel::ProofTerm::Refl);
        }

        if self.peek_word("apply") {
            self.advance();
            let name = self.parse_dotted_name()?;
            let args = if self.peek_kind() == TokenKind::LParen {
                self.advance();
                self.parse_comma_separated(TokenKind::RParen, "proof argument", |parser| {
                    parser.parse_proof_term()
                })?
            } else {
                Vec::new()
            };
            return Ok(proof_kernel::ProofTerm::Apply(name, args));
        }

        if self.peek_word("rewrite") {
            self.advance();
            let eq_term = self.parse_proof_term()?;
            if !self.peek_word("in") {
                return Err("expected `in` after `rewrite <proof>`".into());
            }
            self.advance();
            let body = self.parse_proof_term()?;
            return Ok(proof_kernel::ProofTerm::Rewrite(
                Box::new(eq_term),
                Box::new(body),
            ));
        }

        if self.peek_word("induction_on") {
            self.advance();
            let scrutinee = self.expect_ident()?;
            self.expect(TokenKind::LBrace)?;
            self.skip_semis();
            let mut arms = Vec::new();
            while self.peek_kind() != TokenKind::RBrace {
                self.expect(TokenKind::Pipe)?;
                let pat = self.parse_pattern()?;
                let (ctor, binders) = self.proof_ctor_arm_from_pattern(pat, "induction arms")?;
                self.expect(TokenKind::Arrow)?;
                let body = self.parse_proof_term()?;
                arms.push(proof_kernel::IndArm {
                    ctor,
                    binders,
                    body,
                });
                self.skip_semis();
            }
            self.expect(TokenKind::RBrace)?;
            return Ok(proof_kernel::ProofTerm::InductionOn(scrutinee, arms));
        }

        if self.peek_word("cases") {
            self.advance();
            let scrutinee_expr = self.parse_expr()?;
            let scrutinee = lower_expr_to_proof_term(&scrutinee_expr)?;
            self.expect(TokenKind::LBrace)?;
            self.skip_semis();
            let mut arms = Vec::new();
            while self.peek_kind() != TokenKind::RBrace {
                self.expect(TokenKind::Pipe)?;
                let pat = self.parse_pattern()?;
                let (ctor, binders) = self.proof_ctor_arm_from_pattern(pat, "case arms")?;
                self.expect(TokenKind::Arrow)?;
                let body = self.parse_proof_term()?;
                arms.push(proof_kernel::CaseArm {
                    ctor,
                    binders,
                    body,
                });
                self.skip_semis();
            }
            self.expect(TokenKind::RBrace)?;
            return Ok(proof_kernel::ProofTerm::Cases(scrutinee, arms));
        }

        if self.peek_word("let") {
            self.advance();
            let name = self.expect_ident()?;
            if self.peek_kind() == TokenKind::Eq {
                self.advance();
            } else if self.peek_kind() == TokenKind::Op && self.peek().text == "=" {
                self.advance();
            } else {
                return Err("expected `=` in proof `let` binding".into());
            }
            let bound = self.parse_proof_term()?;
            if !self.peek_word("in") {
                return Err("expected `in` after proof `let` binding".into());
            }
            self.advance();
            let body = self.parse_proof_term()?;
            return Ok(proof_kernel::ProofTerm::Let(
                name,
                Box::new(bound),
                Box::new(body),
            ));
        }

        if self.peek_word("assume") {
            self.advance();
            let prop_expr = self.parse_expr()?;
            let prop = lower_expr_to_proof_prop(&prop_expr)?;
            if !self.peek_word("in") {
                return Err("expected `in` after `assume <prop>`".into());
            }
            self.advance();
            let body = self.parse_proof_term()?;
            return Ok(proof_kernel::ProofTerm::Assume(prop, Box::new(body)));
        }

        Ok(proof_kernel::ProofTerm::Hyp(self.expect_ident()?))
    }

    // --- Top-level parsing ---

    pub fn parse_program(&mut self) -> Result<Vec<Stmt>, String> {
        let mut stmts = Vec::new();
        let mut errors: Vec<String> = Vec::new();
        self.skip_semis();
        while self.peek_kind() != TokenKind::Eof {
            match self.parse_statement() {
                Ok(stmt) => {
                    stmts.push(stmt);
                }
                Err(e) => {
                    errors.push(e);
                    // Synchronize: skip to the next statement boundary
                    self.synchronize();
                    if errors.len() >= 10 {
                        errors.push("... (too many errors, stopping)".to_string());
                        break;
                    }
                }
            }
            self.skip_semis();
        }
        if errors.is_empty() {
            Ok(stmts)
        } else {
            // Return all errors, but also include any successfully parsed statements
            // in a special format: errors first, then note about partial parse
            let error_count = errors.len();
            let mut msg = format!(
                "{} parse error{}:\n",
                error_count,
                if error_count == 1 { "" } else { "s" }
            );
            for (i, e) in errors.iter().enumerate() {
                if i > 0 {
                    msg.push('\n');
                }
                msg.push_str(e);
            }
            Err(msg)
        }
    }

    /// Skip tokens until we reach a likely statement boundary.
    /// Looks for rune characters at the start of a line, or `for`/`while`/`}` keywords.
    fn synchronize(&mut self) {
        // Skip the current token (the one that caused the error)
        if self.peek_kind() != TokenKind::Eof {
            self.advance();
        }
        while self.peek_kind() != TokenKind::Eof {
            let tok = self.peek();
            // Statement boundaries: rune characters at column 1, or keywords at column 1
            if tok.col <= 1 {
                match tok.kind {
                    TokenKind::Hash
                    | TokenKind::Arrow
                    | TokenKind::Pipe
                    | TokenKind::Eq
                    | TokenKind::Tilde
                    | TokenKind::At
                    | TokenKind::Gt => return,
                    // ? rune starts with Op("?")
                    TokenKind::Op if tok.text == "?" => return,
                    TokenKind::KW
                        if matches!(tok.text.as_str(), "for" | "while" | "if" | "match") =>
                    {
                        return
                    }
                    TokenKind::Ident
                        if matches!(tok.text.as_str(), "fn" | "let" | "struct" | "enum") =>
                    {
                        return
                    }
                    _ => {}
                }
            }
            self.advance();
        }
    }

    fn token_is_identifier_like(token: &Token) -> bool {
        matches!(
            token.kind,
            TokenKind::Ident | TokenKind::Type | TokenKind::Bool_ | TokenKind::KW
        )
    }

    fn token_is_explore_binder(token: &Token) -> bool {
        (token.kind == TokenKind::Ident
            || (token.kind == TokenKind::KW && token.source_text != token.text))
            && token.source_text != "_"
            && token
                .source_text
                .chars()
                .next()
                .is_some_and(|ch| ch == '_' || ch.is_lowercase())
    }

    fn expect_explore_binder(&mut self, role: &str) -> Result<(String, Token), String> {
        let token = self.peek().clone();
        if !Self::token_is_explore_binder(&token) {
            return Err(format!(
                "{}:{}: exploration {} must be a lowercase identifier, found `{}`",
                token.line, token.col, role, token.source_text
            ));
        }
        self.advance();
        Ok((token.text.clone(), token))
    }

    fn is_explore_query_start(&self) -> bool {
        if !self.peek_word("explore") {
            return false;
        }
        let Some(next) = self.tokens.get(self.pos + 1) else {
            return false;
        };
        if next.kind == TokenKind::LBrace {
            return true;
        }
        Self::token_is_identifier_like(next)
            && !matches!(next.text.as_str(), "by" | "else")
            && self
                .tokens
                .get(self.pos + 2)
                .is_some_and(|token| token.kind == TokenKind::LBrace)
    }

    fn expect_explore_word(&mut self, word: &str) -> Result<Token, String> {
        let token = self.peek().clone();
        if self.peek_word(word) {
            Ok(self.advance())
        } else {
            let found = if token.kind == TokenKind::RBrace {
                "the end of the exploration block".to_string()
            } else {
                format!("`{}`", token.source_text)
            };
            Err(format!(
                "{}:{}: expected `{}` in exploration, found {}; clauses must appear as `from`, `to`, zero or more `where`, `find`, then zero or more `results` and `mechanisms`",
                token.line, token.col, word, found
            ))
        }
    }

    fn consume_explore_equals(&mut self) -> bool {
        if self.peek_kind() == TokenKind::Eq
            || (self.peek_kind() == TokenKind::Op && self.peek().text == "=")
        {
            self.advance();
            true
        } else {
            false
        }
    }

    fn finish_explore_clause(&mut self, clause: &str) -> Result<(), String> {
        if self.peek_kind() == TokenKind::RBrace {
            return Ok(());
        }
        if self.peek_kind() != TokenKind::Semi {
            let token = self.peek();
            return Err(format!(
                "{}:{}: exploration {clause} clauses must be separated by a newline or `;`, found `{}`",
                token.line, token.col, token.source_text,
            ));
        }
        self.skip_semis();
        Ok(())
    }

    fn parse_explore_source(&mut self) -> Result<ExploreSourceRelation, String> {
        let start = self.expect_explore_word("from")?;
        self.expect(TokenKind::LBrace)?;
        self.skip_semis();
        let mut bindings = Vec::new();
        let mut names = BTreeSet::new();
        while self.peek_kind() != TokenKind::RBrace && self.peek_kind() != TokenKind::Eof {
            let token = self.peek().clone();
            let (name, _) = self.expect_explore_binder("source binding")?;
            if !names.insert(name.clone()) {
                return Err(format!(
                    "{}:{}: duplicate exploration source binding `{}`",
                    token.line, token.col, name
                ));
            }
            if name == "after" {
                return Err(format!(
                    "{}:{}: `after` is introduced by the `to` relation and cannot be a `from` binding",
                    token.line, token.col
                ));
            }
            let kind = if self.consume_explore_equals() {
                ExploreSourceBindingKind::Singleton {
                    value: self.parse_expr()?,
                }
            } else if self.peek_word("in") {
                self.advance();
                ExploreSourceBindingKind::Finite {
                    domain: self.parse_expr()?,
                }
            } else {
                let found = self.peek();
                return Err(format!(
                    "{}:{}: expected `=` or `in` after exploration source binding `{name}`",
                    found.line, found.col
                ));
            };
            bindings.push(ExploreSourceBinding {
                name,
                kind,
                span: self.span_since(&token),
            });
            self.finish_explore_clause("source-binding")?;
        }
        self.expect(TokenKind::RBrace)?;
        for required in ["before", "context"] {
            if !names.contains(required) {
                return Err(format!(
                    "exploration `from` must bind exactly one `{required}` value"
                ));
            }
        }
        Ok(ExploreSourceRelation {
            bindings,
            span: self.span_since(&start),
        })
    }

    fn parse_explore_successor(&mut self) -> Result<ExploreSuccessorRelation, String> {
        let start = self.expect_explore_word("to")?;
        self.expect_explore_word("after")?;
        let kind = if self.consume_explore_equals() {
            ExploreSuccessorKind::Singleton {
                value: self.parse_expr()?,
            }
        } else if self.peek_word("in") {
            self.advance();
            ExploreSuccessorKind::Finite {
                domain: self.parse_expr()?,
            }
        } else {
            let token = self.peek();
            return Err(format!(
                "{}:{}: expected `=` or `in` after exploration successor `after`",
                token.line, token.col
            ));
        };
        Ok(ExploreSuccessorRelation {
            kind,
            span: self.span_since(&start),
        })
    }

    fn parse_explore_result_field_list(
        &mut self,
        clause: &str,
    ) -> Result<Vec<ExploreResultField>, String> {
        self.expect(TokenKind::LBracket)?;
        self.skip_semis();
        let mut fields = Vec::new();
        let mut names = BTreeSet::new();
        while self.peek_kind() != TokenKind::RBracket && self.peek_kind() != TokenKind::Eof {
            let token = self.peek().clone();
            if !Self::token_is_identifier_like(&token) {
                return Err(format!(
                    "{}:{}: exploration `{}` fields must be identifiers or `name = expression`",
                    token.line, token.col, clause
                ));
            }
            let (name, _) = self.expect_explore_binder("result field")?;
            let value = if self.consume_explore_equals() {
                self.parse_expr()?
            } else {
                Expr::new(ExprKind::Var(name.clone()), self.token_span(&token))
            };
            if !names.insert(name.clone()) {
                return Err(format!(
                    "{}:{}: duplicate exploration `{}` field `{}`",
                    token.line, token.col, clause, name
                ));
            }
            fields.push(ExploreResultField {
                name,
                value,
                span: self.span_since(&token),
            });
            self.skip_semis();
            if self.peek_kind() == TokenKind::Comma {
                self.advance();
                self.skip_semis();
            } else if self.peek_kind() != TokenKind::RBracket {
                let next = self.peek();
                return Err(format!(
                    "{}:{}: expected `,` or `]` after exploration `{}` field",
                    next.line, next.col, clause
                ));
            }
        }
        self.expect(TokenKind::RBracket)?;
        Ok(fields)
    }

    fn parse_explore_aggregate_field_list(&mut self) -> Result<Vec<ExploreAggregateField>, String> {
        self.expect(TokenKind::LBracket)?;
        self.skip_semis();
        let mut fields = Vec::new();
        let mut names = BTreeSet::new();
        while self.peek_kind() != TokenKind::RBracket && self.peek_kind() != TokenKind::Eof {
            let token = self.peek().clone();
            let (name, _) = self.expect_explore_binder("aggregate field")?;
            if !names.insert(name.clone()) {
                return Err(format!(
                    "{}:{}: duplicate exploration `aggregate` field `{}`",
                    token.line, token.col, name
                ));
            }
            if !self.consume_explore_equals() {
                let found = self.peek();
                return Err(format!(
                    "{}:{}: exploration aggregate `{name}` requires `= count_distinct(EXPR)`",
                    found.line, found.col
                ));
            }
            self.expect_explore_word("count_distinct")?;
            self.expect(TokenKind::LParen)?;
            let value = self.parse_expr()?;
            self.expect(TokenKind::RParen)?;
            fields.push(ExploreAggregateField {
                name,
                reducer: ExploreAggregateReducer::CountDistinct { value },
                span: self.span_since(&token),
            });
            self.skip_semis();
            if self.peek_kind() == TokenKind::Comma {
                self.advance();
                self.skip_semis();
            } else if self.peek_kind() != TokenKind::RBracket {
                let next = self.peek();
                return Err(format!(
                    "{}:{}: expected `,` or `]` after exploration `aggregate` field",
                    next.line, next.col
                ));
            }
        }
        self.expect(TokenKind::RBracket)?;
        if fields.is_empty() {
            return Err(
                "exploration `aggregate []` is not canonical; omit the aggregate clause".into(),
            );
        }
        Ok(fields)
    }

    fn parse_explore_having(&mut self) -> Result<ExploreResultHaving, String> {
        let start = self.expect_explore_word("having")?;
        self.expect_explore_word("varies")?;
        self.expect(TokenKind::LParen)?;
        self.skip_semis();
        let (measure_name, _) =
            self.expect_explore_binder("measure name in `having varies(...)`")?;
        self.skip_semis();
        self.expect(TokenKind::RParen)?;
        Ok(ExploreResultHaving::Varies {
            measure_name,
            span: self.span_since(&start),
        })
    }

    fn parse_explore_choice(&mut self) -> Result<ExploreResultChoice, String> {
        let start = self.expect_explore_word("choose")?;
        if self.peek_word("pareto") {
            self.advance();
            self.expect(TokenKind::LBracket)?;
            self.skip_semis();
            let mut objectives = Vec::new();
            while self.peek_kind() != TokenKind::RBracket && self.peek_kind() != TokenKind::Eof {
                let objective_start = self.peek().clone();
                let direction = if self.peek_word("maximize") {
                    self.advance();
                    ExploreOptimizeDirection::Maximize
                } else if self.peek_word("minimize") {
                    self.advance();
                    ExploreOptimizeDirection::Minimize
                } else {
                    let token = self.peek();
                    return Err(format!(
                        "{}:{}: Pareto objectives must begin with `maximize` or `minimize`",
                        token.line, token.col
                    ));
                };
                objectives.push(ExploreParetoObjective {
                    direction,
                    value: self.parse_expr()?,
                    span: self.span_since(&objective_start),
                });
                self.skip_semis();
                if self.peek_kind() == TokenKind::Comma {
                    self.advance();
                    self.skip_semis();
                } else if self.peek_kind() != TokenKind::RBracket {
                    let token = self.peek();
                    return Err(format!(
                        "{}:{}: expected `,` or `]` after Pareto objective",
                        token.line, token.col
                    ));
                }
            }
            self.expect(TokenKind::RBracket)?;
            if objectives.is_empty() {
                return Err("exploration `choose pareto` requires at least one objective".into());
            }
            return Ok(ExploreResultChoice::Pareto {
                objectives,
                span: self.span_since(&start),
            });
        }

        let cardinality = if self.peek_word("one") {
            self.advance();
            ExploreChooseCardinality::One
        } else if self.peek_word("all") {
            self.advance();
            ExploreChooseCardinality::All
        } else {
            let token = self.peek();
            return Err(format!(
                "{}:{}: exploration `choose` expects `one`, `all`, or `pareto`",
                token.line, token.col
            ));
        };
        let direction = if self.peek_word("minimizing") {
            self.advance();
            ExploreOptimizeDirection::Minimize
        } else if self.peek_word("maximizing") {
            self.advance();
            ExploreOptimizeDirection::Maximize
        } else {
            let token = self.peek();
            return Err(format!(
                "{}:{}: exploration `choose one|all` expects `minimizing` or `maximizing`",
                token.line, token.col
            ));
        };
        Ok(ExploreResultChoice::Optimize {
            cardinality,
            direction,
            objective: self.parse_expr()?,
            span: self.span_since(&start),
        })
    }

    fn parse_explore_result(&mut self) -> Result<ExploreResultView, String> {
        let start = self.expect_explore_word("results")?;
        let (name, _) = self.expect_explore_binder("result view name")?;
        let input = if self.peek_word("from") {
            self.advance();
            if self.peek_word("sources") {
                self.advance();
                ExploreResultInput::Sources
            } else if self.peek_word("selected") {
                self.advance();
                ExploreResultInput::Selected
            } else if self.peek_word("mechanisms") {
                self.advance();
                let (request_name, _) =
                    self.expect_explore_binder("mechanism request used by result view")?;
                ExploreResultInput::MechanismIncidence { request_name }
            } else {
                let token = self.peek();
                return Err(format!(
                    "{}:{}: exploration result input must be `sources`, `selected`, or `mechanisms NAME`",
                    token.line, token.col
                ));
            }
        } else {
            ExploreResultInput::Selected
        };
        self.expect(TokenKind::LBrace)?;
        self.skip_semis();

        let grain_start = self.peek().clone();
        let grain = if self.peek_word("each") {
            self.advance();
            if self.peek_word("case") {
                self.advance();
                ExploreResultGrain::EachCase {
                    span: self.span_since(&grain_start),
                }
            } else if self.peek_word("incidence") {
                self.advance();
                ExploreResultGrain::EachIncidence {
                    span: self.span_since(&grain_start),
                }
            } else {
                let token = self.peek();
                return Err(format!(
                    "{}:{}: exploration `each` expects `case` or `incidence`",
                    token.line, token.col
                ));
            }
        } else if self.peek_word("group") {
            self.advance();
            if self.peek_word("all") {
                self.advance();
                ExploreResultGrain::GroupAll {
                    span: self.span_since(&grain_start),
                }
            } else if self.peek_word("by") {
                self.advance();
                let fields = self.parse_explore_result_field_list("group by")?;
                if fields.is_empty() {
                    return Err("exploration `group by` requires at least one field".into());
                }
                ExploreResultGrain::GroupBy {
                    fields,
                    span: self.span_since(&grain_start),
                }
            } else {
                let token = self.peek();
                return Err(format!(
                    "{}:{}: exploration `group` expects `all` or `by [FIELD...]`",
                    token.line, token.col
                ));
            }
        } else {
            let token = self.peek();
            return Err(format!(
                "{}:{}: exploration result grain must be `each case`, `each incidence`, `group all`, or `group by [FIELD...]`",
                token.line, token.col
            ));
        };
        self.skip_semis();

        let measures = if self.peek_word("measure") {
            self.advance();
            let fields = self.parse_explore_result_field_list("measure")?;
            if fields.is_empty() {
                return Err(
                    "exploration `measure []` is not canonical; omit the measure clause".into(),
                );
            }
            self.skip_semis();
            fields
        } else {
            Vec::new()
        };
        let aggregates = if self.peek_word("aggregate") {
            self.advance();
            let fields = self.parse_explore_aggregate_field_list()?;
            self.skip_semis();
            fields
        } else {
            Vec::new()
        };
        let having = if self.peek_word("having") {
            if measures.is_empty() {
                let token = self.peek();
                return Err(format!(
                    "{}:{}: exploration `having` requires a preceding nonempty `measure` clause",
                    token.line, token.col
                ));
            }
            let having = self.parse_explore_having()?;
            self.skip_semis();
            Some(having)
        } else {
            None
        };
        let select = if self.peek_word("select") {
            self.advance();
            let fields = self.parse_explore_result_field_list("select")?;
            self.skip_semis();
            fields
        } else {
            Vec::new()
        };
        let choose = if self.peek_word("choose") {
            let choose = self.parse_explore_choice()?;
            self.skip_semis();
            Some(choose)
        } else {
            None
        };
        if self.peek_kind() != TokenKind::RBrace {
            let token = self.peek();
            return Err(format!(
                "{}:{}: unexpected `{}` in exploration result; clauses must follow grain, optional `measure`, optional `aggregate`, optional `having`, optional `select`, optional `choose`",
                token.line, token.col, token.source_text
            ));
        }
        self.expect(TokenKind::RBrace)?;
        match (&input, &grain) {
            (
                ExploreResultInput::Sources,
                ExploreResultGrain::EachCase { .. } | ExploreResultGrain::EachIncidence { .. },
            ) => {
                return Err(
                    "source results currently require `group all` or `group by [...]`".into(),
                );
            }
            (ExploreResultInput::Selected, ExploreResultGrain::EachIncidence { .. }) => {
                return Err("`each incidence` requires a mechanism-incidence result input".into());
            }
            (
                ExploreResultInput::MechanismIncidence { .. },
                ExploreResultGrain::EachCase { .. },
            ) => {
                return Err("`each case` requires the selected-case result input".into());
            }
            _ => {}
        }
        if !aggregates.is_empty()
            && !matches!(
                &grain,
                ExploreResultGrain::GroupAll { .. } | ExploreResultGrain::GroupBy { .. }
            )
        {
            return Err("exploration `aggregate` requires `group all` or `group by [...]`".into());
        }
        Ok(ExploreResultView {
            name,
            input,
            grain,
            measures,
            aggregates,
            having,
            select,
            choose,
            span: self.span_since(&start),
        })
    }

    fn parse_explore_mechanism_request(&mut self) -> Result<ExploreMechanismRequest, String> {
        let start = self.expect_explore_word("mechanisms")?;
        let (name, _) = self.expect_explore_binder("mechanism request name")?;
        self.expect_explore_word("for")?;
        let target = if self.peek_word("selected") {
            self.advance();
            ExploreMechanismTarget::SelectedCases
        } else if self.peek_word("view") {
            self.advance();
            let (view_name, _) = self.expect_explore_binder("mechanism result view")?;
            self.expect_explore_word("chosen")?;
            ExploreMechanismTarget::ViewChosen { view_name }
        } else {
            let token = self.peek();
            return Err(format!(
                "{}:{}: exploration mechanism target must be `selected` or `view NAME chosen`",
                token.line, token.col
            ));
        };
        self.expect_explore_word("from")?;
        let callable_token = self.peek().clone();
        let callable_name = self.parse_qualified_name()?;
        let span = self.span_since(&start);
        let endpoint_template = Expr::new(
            ExprKind::App(
                Box::new(Expr::new(
                    ExprKind::Var(callable_name.clone()),
                    self.token_span(&callable_token),
                )),
                vec![
                    Expr::new(ExprKind::Var("state".to_string()), span),
                    Expr::new(ExprKind::Var("context".to_string()), span),
                ],
            ),
            span,
        );
        Ok(ExploreMechanismRequest {
            name,
            target,
            callable_name,
            endpoint_template,
            span,
        })
    }

    fn parse_explore_structural_digest(&mut self, label: &str) -> Result<[u8; 32], String> {
        let token = self.expect(TokenKind::String_)?;
        let bytes = token.text.as_bytes();
        if bytes.len() != 64
            || bytes
                .iter()
                .any(|byte| !matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
        {
            return Err(format!(
                "{}:{}: exploration {label} must be exactly 64 lowercase hexadecimal characters",
                token.line, token.col
            ));
        }
        let mut digest = [0_u8; 32];
        for (index, pair) in bytes.chunks_exact(2).enumerate() {
            let nibble = |byte| match byte {
                b'0'..=b'9' => byte - b'0',
                b'a'..=b'f' => byte - b'a' + 10,
                _ => unreachable!("validated lowercase hexadecimal digit"),
            };
            digest[index] = (nibble(pair[0]) << 4) | nibble(pair[1]);
        }
        Ok(digest)
    }

    fn parse_explore_starter_projection(&mut self) -> Result<ExploreStarterProjection, String> {
        let start = self.expect_explore_word("starters")?;
        let (name, _) = self.expect_explore_binder("starter projection name")?;
        self.expect_explore_word("from")?;
        self.expect_explore_word("mechanisms")?;
        let (request_name, _) =
            self.expect_explore_binder("starter projection mechanism request")?;
        self.expect_explore_word("for")?;
        let subject = if self.peek_word("mechanism") {
            self.advance();
            ExploreStarterProjectionSubject::Mechanism(
                self.parse_explore_structural_digest("structural mechanism ID")?,
            )
        } else if self.peek_word("node") {
            self.advance();
            let facet = self.parse_explore_starter_projection_facet("node")?;
            ExploreStarterProjectionSubject::Node {
                facet,
                node_id: self.parse_explore_structural_digest("structural node ID")?,
            }
        } else if self.peek_word("edge") {
            self.advance();
            let facet = self.parse_explore_starter_projection_facet("edge")?;
            ExploreStarterProjectionSubject::Edge {
                facet,
                edge_id: self.parse_explore_structural_digest("structural edge ID")?,
            }
        } else {
            let token = self.peek();
            return Err(format!(
                "{}:{}: starter projection subject must be `mechanism`, `node activation|differential`, or `edge activation|differential`",
                token.line, token.col
            ));
        };
        let within_mechanism = if self.peek_word("within") {
            self.advance();
            self.expect_explore_word("mechanism")?;
            if matches!(subject, ExploreStarterProjectionSubject::Mechanism(_)) {
                let token = self.peek();
                return Err(format!(
                    "{}:{}: whole-mechanism starter support cannot be refined `within mechanism`; select the mechanism directly",
                    token.line, token.col
                ));
            }
            Some(self.parse_explore_structural_digest("enclosing structural mechanism ID")?)
        } else {
            None
        };
        self.expect_explore_word("using")?;
        self.expect_explore_word("values")?;
        self.expect_explore_word("from")?;
        let (value_view_name, _) = self.expect_explore_binder("starter projection value view")?;
        Ok(ExploreStarterProjection {
            name,
            request_name,
            subject,
            within_mechanism,
            value_view_name,
            span: self.span_since(&start),
        })
    }

    fn parse_explore_starter_projection_facet(
        &mut self,
        subject_kind: &str,
    ) -> Result<ExploreStarterProjectionFacet, String> {
        if self.peek_word("activation") {
            self.advance();
            Ok(ExploreStarterProjectionFacet::Activation)
        } else if self.peek_word("differential") {
            self.advance();
            Ok(ExploreStarterProjectionFacet::DifferentialParticipation)
        } else {
            let token = self.peek();
            Err(format!(
                "{}:{}: starter projection {subject_kind} facet must be `activation` or `differential`",
                token.line, token.col
            ))
        }
    }

    fn parse_explore_transition_graph(&mut self) -> Result<ExploreTransitionGraph, String> {
        let start = self.expect_explore_word("transitions")?;
        let (name, _) = self.expect_explore_binder("transition graph name")?;
        self.expect_explore_word("from")?;
        self.expect_explore_word("all")?;
        self.expect_explore_word("cases")?;
        Ok(ExploreTransitionGraph {
            name,
            span: self.span_since(&start),
        })
    }

    fn parse_explore_query(&mut self, question_token: &Token) -> Result<Stmt, String> {
        self.expect_explore_word("explore")?;
        let (name, _) = self.expect_explore_binder("query name")?;
        self.expect(TokenKind::LBrace)?;
        self.skip_semis();

        let source = self.parse_explore_source()?;
        self.skip_semis();
        let successor = self.parse_explore_successor()?;
        self.skip_semis();

        let mut admissions = Vec::new();
        while self.peek_word("where") {
            let start = self.advance();
            let scope = if self.peek_word("before") {
                self.advance();
                ExploreAdmissionScope::Before
            } else if self.peek_word("after") {
                self.advance();
                ExploreAdmissionScope::After
            } else if self.peek_word("transition") {
                self.advance();
                ExploreAdmissionScope::Transition
            } else {
                let token = self.peek();
                return Err(format!(
                    "{}:{}: exploration `where` must name `before`, `after`, or `transition`",
                    token.line, token.col
                ));
            };
            admissions.push(ExploreAdmission {
                scope,
                predicate: self.parse_expr()?,
                span: self.span_since(&start),
            });
            self.skip_semis();
        }

        let find_start = self.expect_explore_word("find")?;
        let selection = if self.peek_word("all") {
            self.advance();
            ExploreSelection::All {
                span: self.span_since(&find_start),
            }
        } else if self.peek_word("matches") {
            self.advance();
            self.expect_explore_word("of")?;
            ExploreSelection::Matches {
                predicate: self.parse_expr()?,
                span: self.span_since(&find_start),
            }
        } else if self.peek_word("violations") {
            self.advance();
            self.expect_explore_word("of")?;
            ExploreSelection::Violations {
                predicate: self.parse_expr()?,
                span: self.span_since(&find_start),
            }
        } else {
            let token = self.peek();
            return Err(format!(
                "{}:{}: exploration `find` must be `find all`, `find matches of BOOL`, or `find violations of BOOL`",
                token.line, token.col
            ));
        };
        self.skip_semis();

        let mut analysis = Vec::<ExploreAnalysisNode>::new();
        let mut analysis_names = BTreeSet::new();
        while self.peek_word("results") || self.peek_word("mechanisms") {
            let node = if self.peek_word("results") {
                let result = self.parse_explore_result()?;
                if let ExploreResultInput::MechanismIncidence { request_name } = &result.input {
                    match analysis.iter().find(|node| node.name() == request_name) {
                        Some(ExploreAnalysisNode::Mechanisms(_)) => {}
                        Some(ExploreAnalysisNode::Result(_)) => {
                            return Err(format!(
                                "exploration result `{}` expects `{}` to name an earlier mechanism request",
                                result.name, request_name
                            ));
                        }
                        None => {
                            return Err(format!(
                                "exploration result `{}` may reference only an earlier mechanism request; `{}` is unresolved or declared later",
                                result.name, request_name
                            ));
                        }
                    }
                }
                ExploreAnalysisNode::Result(result)
            } else {
                let request = self.parse_explore_mechanism_request()?;
                if let ExploreMechanismTarget::ViewChosen { view_name } = &request.target {
                    match analysis.iter().find(|node| node.name() == view_name) {
                        Some(ExploreAnalysisNode::Result(view))
                            if view.choose.is_some()
                                && matches!(&view.input, ExploreResultInput::Selected) => {}
                        Some(ExploreAnalysisNode::Result(view))
                            if matches!(
                                &view.input,
                                ExploreResultInput::MechanismIncidence { .. }
                            ) =>
                        {
                            return Err(format!(
                                "exploration mechanism request `{}` cannot target post-mechanism view `{}`; `view NAME chosen` requires an earlier selected-case view",
                                request.name, view_name
                            ));
                        }
                        Some(ExploreAnalysisNode::Result(_)) => {
                            return Err(format!(
                                "exploration mechanism request `{}` requires earlier view `{}` to have a `choose` clause",
                                request.name, view_name
                            ));
                        }
                        Some(ExploreAnalysisNode::Mechanisms(_)) => {
                            return Err(format!(
                                "exploration mechanism request `{}` expects `{}` to name an earlier result view",
                                request.name, view_name
                            ));
                        }
                        None => {
                            return Err(format!(
                                "exploration mechanism request `{}` may reference only an earlier chosen result view; `{}` is unresolved or declared later",
                                request.name, view_name
                            ));
                        }
                    }
                }
                ExploreAnalysisNode::Mechanisms(request)
            };
            if !analysis_names.insert(node.name().to_string()) {
                return Err(format!(
                    "duplicate exploration analysis declaration `{}`",
                    node.name()
                ));
            }
            analysis.push(node);
            self.skip_semis();
        }
        let mut starter_projections = Vec::new();
        let mut transition_graphs = Vec::new();
        while self.peek_word("starters") || self.peek_word("transitions") {
            if self.peek_word("transitions") {
                let graph = self.parse_explore_transition_graph()?;
                if !analysis_names.insert(graph.name.clone()) {
                    return Err(format!(
                        "duplicate exploration declaration `{}`",
                        graph.name
                    ));
                }
                transition_graphs.push(graph);
                self.skip_semis();
                continue;
            }

            let projection = self.parse_explore_starter_projection()?;
            match analysis
                .iter()
                .find(|node| node.name() == projection.request_name)
            {
                Some(ExploreAnalysisNode::Mechanisms(_)) => {}
                Some(ExploreAnalysisNode::Result(_)) => {
                    return Err(format!(
                        "starter projection `{}` expects `{}` to name an earlier mechanism request",
                        projection.name, projection.request_name
                    ));
                }
                None => {
                    return Err(format!(
                        "starter projection `{}` may reference only an earlier mechanism request; `{}` is unresolved or declared later",
                        projection.name, projection.request_name
                    ));
                }
            }
            match analysis
                .iter()
                .find(|node| node.name() == projection.value_view_name)
            {
                Some(ExploreAnalysisNode::Result(_)) => {}
                Some(ExploreAnalysisNode::Mechanisms(_)) => {
                    return Err(format!(
                        "starter projection `{}` expects `{}` to name an earlier result view",
                        projection.name, projection.value_view_name
                    ));
                }
                None => {
                    return Err(format!(
                        "starter projection `{}` may use values only from an earlier result view; `{}` is unresolved or declared later",
                        projection.name, projection.value_view_name
                    ));
                }
            }
            if !analysis_names.insert(projection.name.clone()) {
                return Err(format!(
                    "duplicate exploration declaration `{}`",
                    projection.name
                ));
            }
            starter_projections.push(projection);
            self.skip_semis();
        }
        if self.peek_kind() != TokenKind::RBrace {
            let token = self.peek();
            return Err(format!(
                "{}:{}: unexpected exploration clause `{}`; post-`find` declarations must be `results`, `mechanisms`, or trailing `starters`/`transitions` consumers and may depend only on earlier declarations",
                token.line, token.col, token.source_text
            ));
        }
        self.expect(TokenKind::RBrace)?;

        Ok(Stmt::Explore(ExploreQuery {
            name,
            source,
            successor,
            admissions,
            selection,
            analysis,
            starter_projections,
            transition_graphs,
            span: self.span_since(question_token),
        }))
    }

    pub fn parse_statement(&mut self) -> Result<Stmt, String> {
        self.skip_semis();

        // ── Detect common mistakes from other languages ──
        if self.peek_kind() == TokenKind::Ident || self.peek_kind() == TokenKind::KW {
            let tok = self.peek();
            let line = tok.line;
            let col = tok.col;
            match tok.text.as_str() {
                "fn" | "func" | "def" | "fun" => {
                    return Err(format!(
                        "{}:{}: Futuruna uses `>` to define functions, not `{}`.\n  \
                        Try: > {}",
                        line,
                        col,
                        tok.text,
                        self.tokens
                            .get(self.pos + 1)
                            .map(|t| t.text.as_str())
                            .unwrap_or("name(args) -> Type { body }")
                    ));
                }
                "let" | "val" | "var" | "const" => {
                    return Err(format!(
                        "{}:{}: Futuruna uses `=` to bind values, not `{}`.\n  \
                        Try: = {}",
                        line,
                        col,
                        tok.text,
                        self.tokens
                            .get(self.pos + 1)
                            .map(|t| t.text.as_str())
                            .unwrap_or("name = value")
                    ));
                }
                "struct" | "class" | "enum" | "interface" => {
                    return Err(format!(
                        "{}:{}: Futuruna uses `#` to define types, not `{}`.\n  \
                        Try: # {}",
                        line,
                        col,
                        tok.text,
                        self.tokens
                            .get(self.pos + 1)
                            .map(|t| t.text.as_str())
                            .unwrap_or("TypeName(field: Type)")
                    ));
                }
                "import" | "require" | "include" => {
                    return Err(format!(
                        "{}:{}: Futuruna uses `@ import` for Futuruna modules and `@ use` for Rust imports, not `{}`.\n  \
                        Try: @ import ./module",
                        line, col, tok.text
                    ));
                }
                "print" | "println" | "console" | "echo" => {
                    return Err(format!(
                        "{}:{}: In Futuruna, IO is an effect — use the `@` rune.\n  \
                        Try: @ print(\"hello\")",
                        line, col
                    ));
                }
                // "assert" is now a real keyword for persist operations
                // (old error removed — assert is parsed as Stmt::Assert below)
                "test" if col == 1 => {
                    return Err(format!(
                        "{}:{}: Futuruna uses `?` for verification, not `test`.\n  \
                        Try: ? invariant_name",
                        line, col
                    ));
                }
                "trait" => {
                    return Err(format!(
                        "{}:{}: Futuruna uses `#` for traits.\n  \
                        Try: # trait {} {{ > method(self) -> Type }}",
                        line,
                        col,
                        self.tokens
                            .get(self.pos + 1)
                            .map(|t| t.text.as_str())
                            .unwrap_or("Name")
                    ));
                }
                "impl" => {
                    return Err(format!(
                        "{}:{}: Futuruna uses `#` for implementations.\n  \
                        Try: # impl TraitName for TypeName {{ ... }}",
                        line, col
                    ));
                }
                "match" if col == 1 => {
                    return Err(format!(
                        "{}:{}: `match` at the start of a line looks like a top-level statement.\n  \
                        If this is a match expression, it belongs inside a function body (> rune).\n  \
                        If you want pattern-based rules, use the `|` rune:\n  \
                        | rule_name(x) -> result",
                        line, col
                    ));
                }
                "type" => {
                    return Err(format!(
                        "{}:{}: Futuruna uses `#` to define types, not `type`.\n  \
                        Try: # TypeName(field: Type)",
                        line, col
                    ));
                }
                "return" => {
                    return Err(format!(
                        "{}:{}: Futuruna functions return their last expression — no `return` needed.\n  \
                        Just write the value as the last line of the function body.",
                        line, col
                    ));
                }
                "if" if col == 1 => {
                    return Err(format!(
                        "{}:{}: `if` at top level is not a statement.\n  \
                        If you want a conditional binding, use a function with the `>` rune.\n  \
                        If you want pattern rules, use the `|` rune.",
                        line, col
                    ));
                }
                _ => {}
            }
        }

        // ── Detect bare assignment without `=` rune ──
        if self.peek_kind() == TokenKind::Ident {
            if let Some(next) = self.tokens.get(self.pos + 1) {
                if next.kind == TokenKind::Eq || (next.kind == TokenKind::Op && next.text == "=") {
                    let tok = self.peek();
                    return Err(format!(
                        "{}:{}: bare assignment `{} = ...` needs the `=` rune.\n  \
                        Try: = {} = ...",
                        tok.line, tok.col, tok.text, tok.text
                    ));
                }
            }
        }

        match self.peek_kind() {
            // > rune: definition (Gt at top level, Op(">") inside braces)
            TokenKind::Gt => {
                self.advance();
                self.parse_definition()
            }
            TokenKind::Op if self.peek().text == ">" => {
                self.advance();
                self.parse_definition()
            }
            // | rune: rule/clause
            TokenKind::Pipe => {
                self.advance();
                self.parse_rule()
            }
            // # rune: type declaration
            TokenKind::Hash => {
                self.advance();
                self.parse_type_decl()
            }
            // @ rune: annotation
            TokenKind::At => {
                self.advance();
                self.parse_annotation()
            }
            // = rune: binding
            TokenKind::Eq => {
                self.advance();
                self.parse_binding()
            }
            // ~ rune: stream binding OR stream subscription
            // ~ rune: stream binding OR stream subscription
            TokenKind::Tilde => {
                // ~[...] stream source literal: ~[1, 2, 3] → Stmt::Expr(from_list([1, 2, 3]))
                {
                    let next_pos = self.pos + 1;
                    if next_pos < self.tokens.len()
                        && self.tokens[next_pos].kind == TokenKind::LBracket
                    {
                        self.advance(); // consume ~
                        let list_expr = self.parse_atom()?; // parse the [...] list literal
                        return Ok(Stmt::Expr(
                            ExprKind::App(
                                Box::new(ExprKind::Var("from_list".to_string()).into()),
                                vec![list_expr],
                            )
                            .into(),
                        ));
                    }
                }

                let saved = self.pos;
                self.advance();

                // Disambiguate: ~ name = expr (StreamBind) vs ~ expr | pat -> body (StreamSub)
                let name_tok = self.advance();
                let is_binding = name_tok.kind == TokenKind::Ident
                    && (self.peek_kind() == TokenKind::Eq
                        || (self.peek_kind() == TokenKind::Op && self.peek().text == "="));

                if is_binding {
                    // Consume =
                    if self.peek_kind() == TokenKind::Eq {
                        self.advance();
                    } else if self.peek_kind() == TokenKind::Op && self.peek().text == "=" {
                        self.advance();
                    }
                    let expr = self.parse_expr()?;
                    Ok(Stmt::StreamBind(name_tok.text.clone(), expr))
                } else {
                    // Backtrack and parse as stream expression + match arms
                    self.pos = saved;
                    self.advance(); // consume ~
                    let stream_expr = self.parse_expr()?;
                    let mut arms = Vec::new();

                    while self.peek_kind() == TokenKind::Pipe {
                        self.advance(); // consume |
                        let pat = self.parse_pattern()?;
                        let guard = if self.peek_kind() == TokenKind::KW && self.peek().text == "if"
                        {
                            self.advance();
                            Some(self.parse_expr()?)
                        } else {
                            None
                        };

                        if self.peek_kind() == TokenKind::Arrow {
                            self.advance();
                        } else if self.peek_kind() == TokenKind::Op && self.peek().text == "->" {
                            self.advance();
                        } else {
                            return Err(format!("{}:{}: expected `->` after pattern in subscription arm.\n  Each arm should look like: | pattern -> {{ body }}", self.peek().line, self.peek().col));
                        }

                        let body = self.parse_expr()?;
                        arms.push(MatchArm { pat, guard, body });
                        self.skip_semis();
                    }

                    if arms.is_empty() {
                        return Err(format!(
                            "{}:{}: stream subscription needs at least one `|` arm.\n  Example:\n    ~ my_stream\n    | x -> {{ @ print(x) }}\n    | Err(e) -> {{ @ print(\"error\") }}\n    | Complete -> {{ @ print(\"done\") }}",
                            self.peek().line, self.peek().col
                        ));
                    }
                    Ok(Stmt::StreamSub(stream_expr, arms))
                }
            }
            // ? rune: verify/prove an invariant (or "? all" for all)
            //        ? name by { | binders -> proof }
            // Forms: ? name
            //        ? name -> { pass }
            //        ? name else { fail }
            //        ? name -> { pass } else { fail }
            //        ? name: val -> { pass } else { fail }
            TokenKind::Op if self.peek().text == "?" => {
                let question_token = self.advance(); // consume '?'
                if self.is_explore_query_start() {
                    return self.parse_explore_query(&question_token);
                }
                let name = self.expect_ident()?;
                let proof_block = if self.peek_word("by") {
                    self.advance();
                    Some(self.parse_proof_block()?)
                } else {
                    None
                };

                if proof_block.is_some() {
                    self.skip_semis();
                    if self.peek_kind() == TokenKind::Colon
                        || self.peek_kind() == TokenKind::Arrow
                        || (self.peek_kind() == TokenKind::KW && self.peek().text == "else")
                    {
                        return Err(
                            "`? name by { ... }` cannot be combined with capture/pass/else blocks yet"
                                .into(),
                        );
                    }
                    return Ok(Stmt::Prove {
                        name,
                        proof_block,
                        capture: None,
                        pass_block: None,
                        else_block: None,
                    });
                }
                // Optional `: capture_var`
                let capture = if self.peek_kind() == TokenKind::Colon {
                    self.advance(); // consume ':'
                    Some(self.expect_ident()?)
                } else {
                    None
                };
                // Optional `-> { pass_block }`
                let pass_block = if self.peek_kind() == TokenKind::Arrow {
                    self.advance(); // consume '->'
                    self.expect(TokenKind::LBrace)?;
                    self.skip_semis();
                    let mut stmts = Vec::new();
                    while self.peek_kind() != TokenKind::RBrace {
                        stmts.push(self.parse_block_statement()?);
                        self.skip_semis();
                    }
                    self.expect(TokenKind::RBrace)?;
                    Some(stmts)
                } else {
                    None
                };
                // Optional `else { fail_block }`
                self.skip_semis();
                let else_block = if self.peek_kind() == TokenKind::KW && self.peek().text == "else"
                {
                    self.advance(); // consume 'else'
                    self.expect(TokenKind::LBrace)?;
                    self.skip_semis();
                    let mut stmts = Vec::new();
                    while self.peek_kind() != TokenKind::RBrace {
                        stmts.push(self.parse_block_statement()?);
                        self.skip_semis();
                    }
                    self.expect(TokenKind::RBrace)?;
                    Some(stmts)
                } else {
                    None
                };
                Ok(Stmt::Prove {
                    name,
                    proof_block: None,
                    capture,
                    pass_block,
                    else_block,
                })
            }
            // assert TypeName(args...) — insert a fact
            // Only when followed by an identifier (type name), not by ( which is assert(expr) function call
            TokenKind::KW
                if self.peek().text == "assert"
                    && self.tokens.get(self.pos + 1).map_or(false, |t| {
                        t.kind == TokenKind::Ident || t.kind == TokenKind::Type
                    }) =>
            {
                self.advance(); // consume 'assert'
                let type_name = self.expect_ident()?;
                self.expect(TokenKind::LParen)?;
                let args = self.parse_comma_separated(
                    TokenKind::RParen,
                    "assertion argument",
                    |parser| parser.parse_expr(),
                )?;
                Ok(Stmt::Assert(type_name, args))
            }
            // retract TypeName(args...) — remove a fact (wildcards allowed)
            TokenKind::KW if self.peek().text == "retract" => {
                self.advance(); // consume 'retract'
                let type_name = self.expect_ident()?;
                self.expect(TokenKind::LParen)?;
                let args = self.parse_comma_separated(
                    TokenKind::RParen,
                    "retraction argument",
                    |parser| parser.parse_expr(),
                )?;
                Ok(Stmt::Retract(type_name, args))
            }
            // abort — exit current scope with ROLLBACK
            TokenKind::KW if self.peek().text == "abort" => {
                self.advance(); // consume 'abort'
                Ok(Stmt::Abort)
            }
            // for x in expr { body }
            TokenKind::KW if self.peek().text == "for" => {
                self.advance(); // consume 'for'
                let var = self.expect_ident()?;
                if self.peek_kind() == TokenKind::KW && self.peek().text == "in" {
                    self.advance();
                } else {
                    let p = self.peek();
                    return Err(format!(
                        "{}:{}: expected `in` after `for {}`, got `{}`.\n  \
                        Try: for {} in collection {{ ... }}",
                        p.line, p.col, var, p.text, var
                    ));
                }
                let iter_expr = self.parse_expr_prec(0)?;
                self.expect(TokenKind::LBrace)?;
                self.skip_semis();
                let mut body = Vec::new();
                while self.peek_kind() != TokenKind::RBrace && self.peek_kind() != TokenKind::Eof {
                    body.push(self.parse_block_statement()?);
                    self.skip_semis();
                }
                self.expect(TokenKind::RBrace)?;
                Ok(Stmt::For(var, iter_expr, body))
            }
            // while cond { body }
            TokenKind::KW if self.peek().text == "while" => {
                self.advance(); // consume 'while'
                let cond = self.parse_expr_prec(0)?;
                self.expect(TokenKind::LBrace)?;
                self.skip_semis();
                let mut body = Vec::new();
                while self.peek_kind() != TokenKind::RBrace && self.peek_kind() != TokenKind::Eof {
                    body.push(self.parse_block_statement()?);
                    self.skip_semis();
                }
                self.expect(TokenKind::RBrace)?;
                Ok(Stmt::While(cond, body))
            }
            // Bare expression (inside blocks) — or send: expr <- expr
            _ => {
                let expr = self.parse_expr()?;
                // Check for <- (actor send): target <- message
                if self.peek_kind() == TokenKind::Send {
                    self.advance(); // consume '<-'
                    let msg = self.parse_expr()?;
                    Ok(Stmt::Send(expr, msg))
                } else {
                    Ok(Stmt::Expr(expr))
                }
            }
        }
    }

    // --- > Definition ---

    pub fn parse_definition(&mut self) -> Result<Stmt, String> {
        let name_tok = self.advance();
        let name = name_tok.text;

        // > actor Name(state) { ... }
        if name == "actor" {
            return self.parse_actor_defn();
        }
        // > module Name { ... }
        if name == "module" {
            return self.parse_module_defn();
        }

        // > name(params) -> RetTy with Effects { body }
        let params = if self.peek_kind() == TokenKind::LParen {
            self.parse_params()?
        } else {
            Vec::new()
        };

        let ret_ty = if self.peek_kind() == TokenKind::Arrow {
            self.advance();
            Some(self.parse_type()?)
        } else if self.peek_kind() == TokenKind::FatArrow {
            let tok = self.peek();
            return Err(format!(
                "{}:{}: Futuruna uses `->` for return types, not `=>`.\n  \
                Try: > {}({}) -> ReturnType {{ body }}",
                tok.line,
                tok.col,
                name,
                params
                    .iter()
                    .map(|p| p.name.as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            ));
        } else {
            None
        };

        let effects = if self.peek_kind() == TokenKind::KW && self.peek().text == "with" {
            self.advance();
            self.parse_effect_list()?
        } else {
            Vec::new()
        };

        let body = self.parse_block_expr()?;

        Ok(Stmt::Defn(Defn::Fn {
            name,
            params,
            ret_ty,
            effects,
            body,
        }))
    }

    pub fn parse_actor_defn(&mut self) -> Result<Stmt, String> {
        let name = self.expect_ident()?;
        self.expect(TokenKind::LParen)?;
        let state_name = self.expect_ident()?;
        let state_ty = if self.peek_kind() == TokenKind::Colon {
            self.advance();
            Some(self.parse_type()?)
        } else {
            None
        };
        self.expect(TokenKind::RParen)?;
        self.expect(TokenKind::LBrace)?;
        self.skip_semis();
        let mut handlers = Vec::new();
        while self.peek_kind() != TokenKind::RBrace && self.peek_kind() != TokenKind::Eof {
            if self.peek_kind() == TokenKind::Pipe {
                self.advance();
                if self.peek_kind() == TokenKind::KW && self.peek().text == "on" {
                    self.advance();
                }
                let msg_pat = self.parse_pattern()?;
                self.expect(TokenKind::Arrow)?;
                let body = self.parse_expr()?;
                handlers.push(Handler { msg_pat, body });
            } else {
                // Skip unexpected token to prevent infinite loop
                self.advance();
            }
            self.skip_semis();
        }
        self.expect(TokenKind::RBrace)?;
        Ok(Stmt::Defn(Defn::Actor {
            name,
            state_param: Param {
                name: state_name,
                ty: state_ty,
                inout: false,
            },
            handlers,
        }))
    }

    pub fn parse_module_defn(&mut self) -> Result<Stmt, String> {
        let name = self.expect_ident()?;
        self.expect(TokenKind::LBrace)?;
        self.skip_semis();
        let mut body = Vec::new();
        while self.peek_kind() != TokenKind::RBrace {
            let stmt = self.parse_statement()?;
            body.push(stmt);
            self.skip_semis();
        }
        self.expect(TokenKind::RBrace)?;
        Ok(Stmt::Defn(Defn::Module { name, body }))
    }

    pub fn parse_params(&mut self) -> Result<Vec<Param>, String> {
        self.expect(TokenKind::LParen)?;
        self.parse_comma_separated(TokenKind::RParen, "function parameter", |parser| {
            let name = parser.expect_ident()?;
            let mut inout = false;
            let ty = if parser.peek_kind() == TokenKind::Colon {
                parser.advance();
                // Check for inout modifier BEFORE parsing type
                if parser.peek_kind() == TokenKind::Ident && parser.peek().text == "inout" {
                    parser.advance(); // consume 'inout'
                    inout = true;
                }
                Some(parser.parse_type()?)
            } else {
                None
            };
            Ok(Param { name, ty, inout })
        })
    }

    pub fn parse_effect_list(&mut self) -> Result<Vec<String>, String> {
        let mut effects = Vec::new();
        let name = self.expect_ident()?;
        effects.push(name);
        while self.peek_kind() == TokenKind::Comma {
            self.advance();
            let name = self.expect_ident()?;
            effects.push(name);
        }
        Ok(effects)
    }

    /// Parse: handle EffectName { | op(args) -> body ... } in body_expr
    /// Called after consuming the leading `|` and seeing `handle` keyword.
    pub fn parse_handle_expr(&mut self) -> Result<Expr, String> {
        self.advance(); // consume 'handle'
        let effect = self.expect_ident()?;

        // Parse handler clauses: { | op(args) -> body ... }
        self.expect(TokenKind::LBrace)?;
        self.skip_semis();
        let mut handlers = Vec::new();
        while self.peek_kind() != TokenKind::RBrace {
            // Each handler: | op_name(param1, param2, ...) -> body
            self.expect(TokenKind::Pipe)?;
            let op_name = self.expect_ident()?;
            let params = if self.peek_kind() == TokenKind::LParen {
                self.advance(); // (
                self.parse_comma_separated(
                    TokenKind::RParen,
                    "effect-handler parameter",
                    |parser| parser.expect_ident(),
                )?
            } else {
                Vec::new()
            };
            self.expect(TokenKind::Arrow)?;
            let body = self.parse_expr()?;
            handlers.push(EffHandler {
                op_name,
                params,
                body,
            });
            self.skip_semis();
        }
        self.expect(TokenKind::RBrace)?;

        // Expect 'in' keyword followed by body expression
        if self.peek_kind() == TokenKind::KW && self.peek().text == "in" {
            self.advance();
        } else {
            let p = self.peek();
            return Err(format!(
                "{}:{}: expected 'in' after | handle {{ ... }}",
                p.line, p.col
            ));
        }
        let body = self.parse_expr()?;

        Ok(ExprKind::Handle {
            effect,
            handlers,
            body: Box::new(body),
        }
        .into())
    }

    // --- | Rule ---

    pub fn parse_rule(&mut self) -> Result<Stmt, String> {
        // | handle EffectName { ... } in body — algebraic effect handler
        if self.peek_kind() == TokenKind::KW && self.peek().text == "handle" {
            let expr = self.parse_handle_expr()?;
            return Ok(Stmt::Expr(expr));
        }

        // | scope Name { ... }
        if self.peek_kind() == TokenKind::KW && self.peek().text == "scope" {
            self.advance();
            let name = self.expect_ident()?;
            self.expect(TokenKind::LBrace)?;
            self.skip_semis();
            let mut body = Vec::new();
            while self.peek_kind() != TokenKind::RBrace {
                let stmt = self.parse_statement()?;
                body.push(stmt);
                self.skip_semis();
            }
            self.expect(TokenKind::RBrace)?;
            return Ok(Stmt::Rule(Rule::ReactiveScope { name, body }));
        }

        // | exception label ...
        if self.peek_kind() == TokenKind::KW && self.peek().text == "exception" {
            self.advance();
            let label = self.expect_ident()?;
            let head = self.parse_expr()?;
            self.expect(TokenKind::Arrow)?;
            let value = self.parse_expr()?;
            let condition = if self.peek_kind() == TokenKind::KW && self.peek().text == "under" {
                self.advance();
                Some(self.parse_expr()?)
            } else {
                None
            };
            return Ok(Stmt::Rule(Rule::Exception {
                label,
                head,
                value,
                condition,
            }));
        }

        // | name: subject -> predicate (named invariant for verification)
        // Detect: if next token is ident and token after is ':', it's an invariant
        if self.peek_kind() == TokenKind::Ident {
            let saved_pos = self.pos;
            let name_tok = self.advance();
            if self.peek_kind() == TokenKind::Colon {
                self.advance(); // consume ':'
                let subject = self.parse_expr()?;
                self.expect(TokenKind::Arrow)?;
                let predicate = self.parse_expr()?;
                return Ok(Stmt::Invariant {
                    name: name_tok.text.clone(),
                    subject,
                    predicate,
                });
            }
            // Not an invariant — backtrack
            self.pos = saved_pos;
        }

        // | head [-> body] [under condition]
        let head = self.parse_expr()?;
        if self.peek_kind() == TokenKind::Arrow {
            self.advance();
            self.in_rule_body = true;
            let body_or_value = self.parse_expr()?;
            self.in_rule_body = false;
            if self.peek_kind() == TokenKind::KW && self.peek().text == "under" {
                self.advance();
                let condition = self.parse_expr()?;
                Ok(Stmt::Rule(Rule::Default {
                    head,
                    value: body_or_value,
                    condition: Some(condition),
                }))
            } else {
                // Parse rule body with and/or precedence:
                // `and` (,) binds tighter than `or`
                // a and b or c and d → Disjunction([Conjunction([a,b]), Conjunction([c,d])])
                let parse_and_group = |parser: &mut Self, first: Expr| -> Result<Expr, String> {
                    let is_and = parser.peek_kind() == TokenKind::Comma
                        || (parser.peek_kind() == TokenKind::Ident && parser.peek().text == "and");
                    if is_and {
                        let mut goals = vec![first];
                        while parser.peek_kind() == TokenKind::Comma
                            || (parser.peek_kind() == TokenKind::Ident
                                && parser.peek().text == "and")
                        {
                            parser.advance();
                            goals.push(parser.parse_expr()?);
                        }
                        Ok(ExprKind::Conjunction(goals).into())
                    } else {
                        Ok(first)
                    }
                };

                let first_group = parse_and_group(self, body_or_value)?;

                // Check for `or` between groups
                let is_or = self.peek_kind() == TokenKind::Op && self.peek().text == "||";
                if is_or {
                    let mut alternatives = vec![first_group];
                    while self.peek_kind() == TokenKind::Op && self.peek().text == "||" {
                        self.advance(); // consume 'or' (lexed as ||)
                        let next_expr = self.parse_expr()?;
                        let group = parse_and_group(self, next_expr)?;
                        alternatives.push(group);
                    }
                    Ok(Stmt::Rule(Rule::Clause {
                        head,
                        body: Some(ExprKind::Disjunction(alternatives).into()),
                    }))
                } else {
                    Ok(Stmt::Rule(Rule::Clause {
                        head,
                        body: Some(first_group),
                    }))
                }
            }
        } else {
            // Bare fact
            Ok(Stmt::Rule(Rule::Clause { head, body: None }))
        }
    }

    // --- # Type declaration ---

    pub fn parse_type_decl(&mut self) -> Result<Stmt, String> {
        // # trait Name { > method(self) -> Type }
        if self.peek_kind() == TokenKind::KW && self.peek().text == "trait" {
            self.advance();
            return self.parse_trait_decl();
        }

        // # impl Trait for Type { > method(self) -> Type { body } }
        if self.peek_kind() == TokenKind::KW && self.peek().text == "impl" {
            self.advance();
            return self.parse_impl_block();
        }

        // # effect Name { ... }
        if self.peek_kind() == TokenKind::KW && self.peek().text == "effect" {
            self.advance();
            let name = self.expect_ident()?;
            self.expect(TokenKind::LBrace)?;
            self.skip_semis();
            let mut ops = Vec::new();
            while self.peek_kind() != TokenKind::RBrace && self.peek_kind() != TokenKind::Eof {
                let is_gt = self.peek_kind() == TokenKind::Gt
                    || (self.peek_kind() == TokenKind::Op && self.peek().text == ">");
                if is_gt {
                    self.advance();
                    let op_name = self.expect_ident()?;
                    let params = if self.peek_kind() == TokenKind::LParen {
                        self.parse_params()?
                    } else {
                        Vec::new()
                    };
                    let ret_ty = if self.peek_kind() == TokenKind::Arrow {
                        self.advance();
                        Some(self.parse_type()?)
                    } else {
                        None
                    };
                    ops.push((op_name, params, ret_ty));
                } else {
                    // Skip unknown tokens to prevent infinite loop
                    self.advance();
                }
                self.skip_semis();
            }
            self.expect(TokenKind::RBrace)?;
            return Ok(Stmt::TypeDecl(TypeDecl::EffectDecl { name, ops }));
        }

        // # Name(params) = Variant1 | Variant2 | ...
        let name = self.expect_ident()?;

        // # Type WHEN condition = new_variants (conditional type evolution)
        if self.peek_kind() == TokenKind::KW && self.peek().text == "WHEN"
            || (self.peek_kind() == TokenKind::Type && self.peek().text == "WHEN")
        {
            self.advance(); // consume WHEN
            let condition = self.parse_expr_prec(0)?;
            // Expect -> (arrow separates condition from new type definition)
            if self.peek_kind() == TokenKind::Arrow {
                self.advance();
            } else {
                let p = self.peek();
                return Err(format!("{}:{}: expected `->` after WHEN condition, got `{}`\n  Syntax: # Type WHEN condition -> NewVariants",
                    p.line, p.col, p.text));
            }
            let (variants, except_from) = self.parse_variants()?;
            return Ok(Stmt::TypeDecl(TypeDecl::WhenType {
                name,
                condition,
                variants,
                except_from,
            }));
        }

        // Detect # Name { ... } (curly-brace struct syntax from other languages)
        if self.peek_kind() == TokenKind::LBrace {
            let p = self.peek();
            return Err(format!(
                "{}:{}: struct fields use parentheses, not braces.\n  Try: # {}(field: Type, ...)\n  Not: # {} {{ field: Type, ... }}",
                p.line, p.col, name, name
            ));
        }

        let params = if self.peek_kind() == TokenKind::LParen {
            let preserve_typed_field_names = self.type_decl_params_form_product();
            self.parse_type_params(preserve_typed_field_names)?
        } else {
            Vec::new()
        };

        if self.peek_kind() == TokenKind::LBrace {
            self.advance();
            self.skip_semis();
            let mut body = Vec::new();
            while self.peek_kind() != TokenKind::RBrace && self.peek_kind() != TokenKind::Eof {
                body.push(self.parse_statement()?);
                self.skip_semis();
            }
            self.expect(TokenKind::RBrace)?;
            return Ok(Stmt::TypeDecl(TypeDecl::RuleScope { name, params, body }));
        }

        // Check for = (ADT definition) vs standalone declaration
        if self.peek_kind() == TokenKind::Op && self.peek().text == "=" {
            self.advance();
        } else if self.peek_kind() == TokenKind::Eq {
            self.advance();
        } else {
            // No = sign: check if params have type annotations (name: Type)
            // If so, this is a single-variant product type: # Point(x: Float, y: Float)
            let has_typed_params = params.iter().any(|p| p.ty.is_some());
            if has_typed_params {
                // Single-variant type with named fields
                let fields: Vec<Field> = params
                    .iter()
                    .map(|p| Field {
                        name: p.name.clone(),
                        ty: p.ty.clone().unwrap_or(Ty::Name("Any".into())),
                    })
                    .collect();
                let variant = Variant {
                    name: name.clone(),
                    fields,
                    positional: false,
                    from_type: None,
                };
                return Ok(Stmt::TypeDecl(TypeDecl::ADT {
                    name,
                    params: Vec::new(),
                    variants: vec![variant],
                    methods: Vec::new(),
                    except_from: None,
                }));
            }
            // Truly opaque type declaration
            return Ok(Stmt::TypeDecl(TypeDecl::ADT {
                name,
                params,
                variants: Vec::new(),
                methods: Vec::new(),
                except_from: None,
            }));
        }

        let (variants, except_from) = self.parse_variants()?;

        // Check for method block: # Type = ... { > method(self) -> ... { } }
        let methods = if self.peek_kind() == TokenKind::LBrace {
            self.advance(); // consume {
            self.skip_semis();
            let mut methods = Vec::new();
            while self.peek_kind() != TokenKind::RBrace && self.peek_kind() != TokenKind::Eof {
                let is_gt = self.peek_kind() == TokenKind::Gt
                    || (self.peek_kind() == TokenKind::Op && self.peek().text == ">");
                if is_gt {
                    self.advance(); // consume >
                    match self.parse_definition() {
                        Ok(Stmt::Defn(defn)) => methods.push(defn),
                        Ok(_) => {}
                        Err(e) => return Err(format!("in method block: {}", e)),
                    }
                } else if self.peek_kind() == TokenKind::Hash {
                    // Allow nested # type declarations inside method block
                    self.advance();
                    let _ = self.parse_type_decl()?;
                } else {
                    // skip unknown tokens inside method block
                    self.advance();
                }
                self.skip_semis();
            }
            if self.peek_kind() == TokenKind::RBrace {
                self.advance();
            }
            methods
        } else {
            Vec::new()
        };

        Ok(Stmt::TypeDecl(TypeDecl::ADT {
            name,
            params,
            variants,
            methods,
            except_from,
        }))
    }

    /// Parse: # trait Display { > fmt(self) -> String }
    pub fn parse_trait_decl(&mut self) -> Result<Stmt, String> {
        let name = self.expect_ident()?;
        let params = if self.peek_kind() == TokenKind::LParen {
            self.parse_type_params(false)?
        } else {
            Vec::new()
        };
        self.expect(TokenKind::LBrace)?;
        self.skip_semis();
        let mut methods = Vec::new();
        while self.peek_kind() != TokenKind::RBrace && self.peek_kind() != TokenKind::Eof {
            let is_gt = self.peek_kind() == TokenKind::Gt
                || (self.peek_kind() == TokenKind::Op && self.peek().text == ">");
            if is_gt {
                self.advance(); // consume >
                let method_name = self.expect_ident()?;
                let method_params = if self.peek_kind() == TokenKind::LParen {
                    self.parse_params()?
                } else {
                    Vec::new()
                };
                let ret_ty = if self.peek_kind() == TokenKind::Arrow {
                    self.advance();
                    Some(self.parse_type()?)
                } else {
                    None
                };
                // Optional default body
                let default_body = if self.peek_kind() == TokenKind::LBrace {
                    Some(self.parse_block_expr()?)
                } else {
                    None
                };
                methods.push(TraitMethod {
                    name: method_name,
                    params: method_params,
                    ret_ty,
                    default_body,
                });
            } else {
                self.advance(); // skip unknown
            }
            self.skip_semis();
        }
        if self.peek_kind() == TokenKind::RBrace {
            self.advance();
        }
        Ok(Stmt::TypeDecl(TypeDecl::TraitDecl {
            name,
            params,
            methods,
        }))
    }

    /// Parse: # impl Display for Shape { > fmt(self) -> String { ... } }
    pub fn parse_impl_block(&mut self) -> Result<Stmt, String> {
        let trait_name = self.parse_qualified_name()?;
        // expect "for"
        if self.peek_kind() == TokenKind::KW && self.peek().text == "for" {
            self.advance();
        } else {
            return Err(format!("expected 'for' after trait name in # impl"));
        }
        let for_type = self.parse_qualified_name()?;
        self.expect(TokenKind::LBrace)?;
        self.skip_semis();
        let mut methods = Vec::new();
        while self.peek_kind() != TokenKind::RBrace && self.peek_kind() != TokenKind::Eof {
            let is_gt = self.peek_kind() == TokenKind::Gt
                || (self.peek_kind() == TokenKind::Op && self.peek().text == ">");
            if is_gt {
                self.advance(); // consume >
                match self.parse_definition() {
                    Ok(Stmt::Defn(defn)) => methods.push(defn),
                    Ok(_) => {}
                    Err(e) => return Err(format!("in impl block: {}", e)),
                }
            } else {
                self.advance(); // skip
            }
            self.skip_semis();
        }
        if self.peek_kind() == TokenKind::RBrace {
            self.advance();
        }
        Ok(Stmt::TypeDecl(TypeDecl::ImplBlock {
            trait_name,
            for_type,
            methods,
        }))
    }

    fn type_decl_params_form_product(&self) -> bool {
        let mut depth = 0usize;
        for (index, token) in self.tokens.iter().enumerate().skip(self.pos) {
            match token.kind {
                TokenKind::LParen => depth += 1,
                TokenKind::RParen => {
                    depth = depth.saturating_sub(1);
                    if depth == 0 {
                        let next = self.tokens.get(index + 1);
                        return !matches!(
                            next.map(|candidate| candidate.kind),
                            Some(TokenKind::LBrace | TokenKind::Eq)
                        ) && !next.is_some_and(|candidate| {
                            candidate.kind == TokenKind::Op && candidate.text == "="
                        });
                    }
                }
                _ => {}
            }
        }
        false
    }

    pub fn parse_type_params(
        &mut self,
        preserve_typed_field_names: bool,
    ) -> Result<Vec<Param>, String> {
        self.expect(TokenKind::LParen)?;
        self.parse_comma_separated(TokenKind::RParen, "type parameter or field", |parser| {
            let token = parser.advance();
            if !matches!(
                token.kind,
                TokenKind::Ident | TokenKind::Type | TokenKind::Bool_ | TokenKind::KW
            ) {
                return Err(format!(
                    "{}:{}: expected a type parameter or field name, got `{}`",
                    token.line, token.col, token.source_text
                ));
            }
            let has_type = parser.peek_kind() == TokenKind::Colon;
            let name = if preserve_typed_field_names && has_type {
                token.source_text
            } else {
                token.text
            };
            let ty = if has_type {
                parser.advance();
                Some(parser.parse_type()?)
            } else {
                None
            };
            Ok(Param {
                name,
                ty,
                inout: false,
            })
        })
    }

    pub fn parse_variants(
        &mut self,
    ) -> Result<(Vec<Variant>, Option<(String, Vec<String>)>), String> {
        let mut variants = Vec::new();
        let mut except_from: Option<(String, Vec<String>)> = None;
        loop {
            let name = self.expect_ident()?;
            // Check for qualified variant: Parent.Variant (subset type syntax)
            if self.peek_kind() == TokenKind::Dot {
                self.advance(); // consume '.'
                let variant_name = self.expect_ident()?;
                variants.push(Variant {
                    name: variant_name,
                    fields: Vec::new(),
                    positional: false,
                    from_type: Some(name),
                });
            } else if (self.peek_kind() == TokenKind::Ident || self.peek_kind() == TokenKind::Type)
                && self.peek().text == "EXCEPT"
            {
                // TypeName EXCEPT Variant1 | Variant2 | ...
                // or: TypeName EXCEPT OtherType
                self.advance(); // consume 'EXCEPT'
                let mut excluded = Vec::new();
                loop {
                    let exc = self.expect_ident()?;
                    excluded.push(exc);
                    if self.peek_kind() == TokenKind::Pipe {
                        // Check if next after | is EXCEPT-continuation or a new variant group
                        let saved = self.pos;
                        self.advance(); // consume |
                                        // If next token followed by EXCEPT or end, it's a new group
                                        // For simplicity: EXCEPT consumes remaining | separated names
                                        // until we hit a non-ident or end
                        if self.peek_kind() == TokenKind::Ident
                            || self.peek_kind() == TokenKind::Type
                        {
                            // Continue collecting excluded variants
                            continue;
                        } else {
                            self.pos = saved;
                            break;
                        }
                    } else {
                        break;
                    }
                }
                except_from = Some((name, excluded));
                break; // EXCEPT always ends the variant list
            } else {
                let (fields, positional) = if self.peek_kind() == TokenKind::LParen {
                    self.parse_field_list()?
                } else {
                    (Vec::new(), false)
                };
                // If this is an uppercase name with no fields and no dot,
                // it MIGHT be a type inclusion (# A = Kristendom | Islam).
                // We can't resolve at parse time — mark with from_type = Some("__include")
                // and resolve during type registration.
                let is_potential_type_include = fields.is_empty()
                    && name.chars().next().map_or(false, |c| c.is_uppercase())
                    && self.peek_kind() != TokenKind::LParen;
                variants.push(Variant {
                    name: name.clone(),
                    fields,
                    positional,
                    from_type: if is_potential_type_include {
                        Some("__maybe_include".into())
                    } else {
                        None
                    },
                });
            }
            if self.peek_kind() == TokenKind::Pipe {
                self.advance();
            } else {
                let next = if self.peek_kind() == TokenKind::Semi {
                    self.tokens[self.pos + 1..]
                        .iter()
                        .find(|token| token.kind != TokenKind::Semi)
                } else {
                    Some(self.peek())
                };
                if next.is_some_and(|token| {
                    token.col > 1
                        && matches!(token.kind, TokenKind::Ident | TokenKind::Type)
                        && token
                            .source_text
                            .chars()
                            .next()
                            .is_some_and(char::is_uppercase)
                }) {
                    let token = next.unwrap();
                    return Err(format!(
                        "{}:{}: expected `|` before type variant `{}`\n  Hint: in a multiline type, end the preceding variant line with `|`.",
                        token.line, token.col, token.source_text
                    ));
                }
                break;
            }
        }
        Ok((variants, except_from))
    }

    /// Parse field list: (name: Type, ...) named OR (Type, Type, ...) positional.
    /// Returns (fields, is_positional).
    pub fn parse_field_list(&mut self) -> Result<(Vec<Field>, bool), String> {
        self.expect(TokenKind::LParen)?;
        if self.peek_kind() == TokenKind::RParen {
            self.expect(TokenKind::RParen)?;
            return Ok((Vec::new(), false));
        }

        // Detect positional vs named by peeking at first field
        let is_positional = {
            let saved = self.pos;
            let is_ident = matches!(
                self.peek_kind(),
                TokenKind::Ident | TokenKind::Type | TokenKind::KW
            );
            let result = if is_ident {
                self.advance();
                self.peek_kind() != TokenKind::Colon
            } else {
                true // non-ident start (e.g. `(`) must be a type → positional
            };
            self.pos = saved;
            result
        };

        let mut index = 0;
        let fields = self.parse_comma_separated(
            TokenKind::RParen,
            "constructor field",
            |parser| {
            if is_positional {
                let ty = parser.parse_type()?;
                let field = Field {
                    name: format!("_{}", index),
                    ty,
                };
                index += 1;
                Ok(field)
            } else {
                let tok = parser.peek().clone();
                let field_name = parser.expect_field_name()?;
                if parser.peek_kind() != TokenKind::Colon {
                    return Err(format!(
                        "{}:{}: constructor fields must be named — write `{}: Type` instead of just a type",
                        tok.line, tok.col, field_name
                    ));
                }
                parser.advance(); // consume colon
                let ty = parser.parse_type()?;
                Ok(Field {
                    name: field_name,
                    ty,
                })
            }
        },
        )?;
        Ok((fields, is_positional))
    }

    pub fn parse_type_list(&mut self) -> Result<Vec<Ty>, String> {
        self.expect(TokenKind::LParen)?;
        self.parse_comma_separated(TokenKind::RParen, "type argument", |parser| {
            parser.parse_type()
        })
    }

    // --- @ Annotation or Effect invocation ---

    pub fn parse_annotation(&mut self) -> Result<Stmt, String> {
        let tok = self.advance();
        let name = tok.text.clone();

        // @ use path::to::thing
        if name == "use" {
            return self.parse_use_decl();
        }

        // @ rust { raw Rust code } — escape hatch for inline Rust
        if name == "rust" && self.peek_kind() == TokenKind::LBrace {
            return self.parse_rust_block();
        }

        // @ import ./module — multi-file import
        if name == "import" {
            return self.parse_import_decl();
        }

        // @ depend "crate" "version" — Cargo dependency
        if name == "depend" {
            return self.parse_depend_decl();
        }

        // @ store TypeName [delete_on_change] [in "scope"]
        // Object store persistence (struct → JSON blob in SQLite)
        // @ persist TypeName [in "scope"]
        // Typed-column persistence (struct → SQLite table with one column per field)
        if name == "store" || name == "persist" {
            let kind = name.clone();
            let type_name = self.expect_ident()?;
            let mut args: Vec<Expr> = vec![ExprKind::Var(type_name.clone()).into()];
            // Optional `delete_on_change` flag (only meaningful for @ store today,
            // accepted in both for symmetry).
            if self.peek_kind() == TokenKind::Ident && self.peek().text == "delete_on_change" {
                self.advance();
                args.push(ExprKind::Var("delete_on_change".to_string()).into());
            }
            // Optional `in "scope"` clause
            if self.peek_kind() == TokenKind::KW && self.peek().text == "in" {
                self.advance(); // consume `in`
                if self.peek_kind() == TokenKind::String_ {
                    let scope = self.advance().text.clone();
                    args.push(ExprKind::Lit(Literal::Str(scope)).into());
                } else {
                    let p = self.peek();
                    return Err(format!(
                        "{}:{}: expected scope string after `in`\n  Try: @ {} {} in \"myapp\"",
                        p.line, p.col, kind, type_name
                    ));
                }
            }
            return Ok(Stmt::Annot(kind, args));
        }

        // @ migrate Type(old_fields...) -> Type(new_fields...) [unsafe]
        //
        // Kept as an annotation payload so older compiler passes can ignore it
        // unless they specifically care about persisted schema evolution.
        if name == "migrate" {
            let old_shape = self.parse_expr()?;
            self.expect(TokenKind::Arrow)?;
            let new_shape = self.parse_expr()?;
            let mut args = vec![old_shape, new_shape];
            if matches!(self.peek_kind(), TokenKind::Ident | TokenKind::KW)
                && self.peek().text == "unsafe"
            {
                self.advance();
                args.push(ExprKind::Var("unsafe".to_string()).into());
            }
            return Ok(Stmt::Annot(name, args));
        }

        // @ sprog / @ language — already consumed by lexer, skip the code token
        if name == "sprog" || name == "language" {
            if self.peek_kind() == TokenKind::Ident || self.peek_kind() == TokenKind::KW {
                self.advance(); // consume the language code (da, en, etc.)
            }
            return Ok(Stmt::Annot(name, Vec::new()));
        }

        // Leaf effect operations (no arguments required): @ time, @ random, @ input
        if name == "time" || name == "random" || name == "input" {
            // Allow optional parens: @ time and @ time() are both valid
            if self.peek_kind() == TokenKind::LParen {
                let _ = self.parse_arg_list()?; // consume empty parens
            }
            return Ok(Stmt::Expr(ExprKind::Effect(name, vec![]).into()));
        }

        // `@ calculate` is a declaration marker, even when it carries the
        // optional human-readable calculation title.
        if name == "calculate" && self.peek_kind() == TokenKind::LParen {
            let args = self.parse_arg_list()?;
            return Ok(Stmt::Annot(name, args));
        }

        // If followed by ( it's an effect invocation: @ print("hello")
        if self.peek_kind() == TokenKind::LParen {
            let args = self.parse_arg_list()?;
            Ok(Stmt::Expr(ExprKind::Effect(name, args).into()))
        } else if name == "export" && self.peek_kind() == TokenKind::Ident {
            // Post-hoc export: `@ export add` — capture the name as arg
            let export_name = self.advance().text.clone();
            Ok(Stmt::Annot(name, vec![ExprKind::Var(export_name).into()]))
        } else {
            // Pure annotation: @ test, @ pure, @ total
            Ok(Stmt::Annot(name, Vec::new()))
        }
    }

    /// Parse: @ rust { raw Rust code }
    /// Extracts raw source text between { }, preserving original formatting.
    pub fn parse_rust_block(&mut self) -> Result<Stmt, String> {
        let open_brace = self.advance(); // consume {
                                         // Find the char offset right after the opening brace
        let start = self.char_offset(open_brace.line, open_brace.col) + 1;

        // Scan raw source chars to find matching closing brace
        let mut depth = 1i32;
        let mut end = start;
        let mut in_string = false;
        let mut in_char = false;
        let mut escape = false;
        let mut in_line_comment = false;
        let mut in_block_comment = false;
        while end < self.source_chars.len() && depth > 0 {
            let c = self.source_chars[end];
            let next = self.source_chars.get(end + 1).copied();

            if escape {
                escape = false;
                end += 1;
                continue;
            }
            if in_line_comment {
                if c == '\n' {
                    in_line_comment = false;
                }
                end += 1;
                continue;
            }
            if in_block_comment {
                if c == '*' && next == Some('/') {
                    in_block_comment = false;
                    end += 2;
                    continue;
                }
                end += 1;
                continue;
            }
            if in_string {
                if c == '\\' {
                    escape = true;
                } else if c == '"' {
                    in_string = false;
                }
                end += 1;
                continue;
            }
            if in_char {
                if c == '\\' {
                    escape = true;
                } else if c == '\'' {
                    in_char = false;
                }
                end += 1;
                continue;
            }

            match c {
                '/' if next == Some('/') => {
                    in_line_comment = true;
                    end += 2;
                    continue;
                }
                '/' if next == Some('*') => {
                    in_block_comment = true;
                    end += 2;
                    continue;
                }
                '"' => {
                    in_string = true;
                }
                '\'' => {
                    in_char = true;
                }
                '{' => {
                    depth += 1;
                }
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
                _ => {}
            }
            end += 1;
        }

        let raw: String = self.source_chars[start..end].iter().collect();
        // Dedent: strip common leading whitespace
        let lines: Vec<&str> = raw.lines().collect();
        let min_indent = lines
            .iter()
            .filter(|l| !l.trim().is_empty())
            .map(|l| l.len() - l.trim_start().len())
            .min()
            .unwrap_or(0);
        let code: String = lines
            .iter()
            .map(|l| {
                if l.len() >= min_indent {
                    &l[min_indent..]
                } else {
                    l.trim()
                }
            })
            .collect::<Vec<_>>()
            .join("\n");

        // Advance the token stream past the matching closing brace
        let mut tok_depth = 1i32;
        while tok_depth > 0 && self.peek_kind() != TokenKind::Eof {
            let tok = self.advance();
            match tok.kind {
                TokenKind::LBrace => tok_depth += 1,
                TokenKind::RBrace => tok_depth -= 1,
                _ => {}
            }
        }

        Ok(Stmt::RustBlock(code.trim().to_string()))
    }

    /// Parse: @ use std::collections::HashMap
    pub fn parse_use_decl(&mut self) -> Result<Stmt, String> {
        let mut path = self.expect_ident()?;
        while self.peek_kind() == TokenKind::Colon {
            self.advance(); // first :
            if self.peek_kind() == TokenKind::Colon {
                self.advance(); // second :
                path.push_str("::");
                if self.peek_kind() == TokenKind::LBrace {
                    // @ use std::collections::{HashMap, BTreeMap}
                    self.advance();
                    let segments =
                        self.parse_comma_separated(TokenKind::RBrace, "imported name", |parser| {
                            parser.expect_ident()
                        })?;
                    path.push_str(&format!("{{{}}}", segments.join(", ")));
                } else if self.peek_kind() == TokenKind::Op && self.peek().text == "*" {
                    // @ use std::collections::*
                    self.advance();
                    path.push('*');
                } else {
                    let seg = self.expect_ident()?;
                    path.push_str(&seg);
                }
            } else {
                break;
            }
        }
        Ok(Stmt::Use(path))
    }

    /// Parse: @ import ./math, @ import Name from ./path, or @ import #hash from ./module
    pub fn parse_import_decl(&mut self) -> Result<Stmt, String> {
        // @ import Name from ./module — qualified import (M3b)
        // Name is a Type token (capitalized) followed by 'from'
        if self.peek_kind() == TokenKind::Type {
            let saved = self.pos;
            let mod_name = self.advance().text.clone();
            if self.peek_kind() == TokenKind::Ident && self.peek().text == "from" {
                self.advance(); // consume 'from'
                let path = self.parse_module_path()?;
                return Ok(Stmt::QualifiedImport(mod_name, path));
            }
            // Not a qualified import — backtrack
            self.pos = saved;
        }
        // @ import #hash from ./module — content-addressed import
        if self.peek_kind() == TokenKind::Hash {
            self.advance(); // consume '#'
                            // Collect hash chars: hex digits may lex as Ident/Int/Type tokens
            let mut hash = String::new();
            while self.peek_kind() != TokenKind::Eof {
                // Stop when we hit 'from' keyword
                if self.peek_kind() == TokenKind::Ident && self.peek().text == "from" {
                    break;
                }
                if self.peek_kind() == TokenKind::Ident
                    || self.peek_kind() == TokenKind::Int_
                    || self.peek_kind() == TokenKind::Type
                {
                    hash.push_str(&self.advance().text);
                } else {
                    break;
                }
            }
            if hash.is_empty() {
                let p = self.peek();
                return Err(format!(
                    "{}:{}: expected hash after # in @ import #hash from ./module",
                    p.line, p.col
                ));
            }
            // Expect 'from' keyword
            if self.peek_kind() == TokenKind::Ident && self.peek().text == "from" {
                self.advance(); // consume 'from'
            } else {
                let p = self.peek();
                return Err(format!(
                    "{}:{}: expected 'from' after hash in @ import #hash from ./module",
                    p.line, p.col
                ));
            }
            // Parse module path
            let path = self.parse_module_path()?;
            return Ok(Stmt::HashImport(hash, path));
        }
        // @ import ./module — regular import
        let path = self.parse_module_path()?;
        Ok(Stmt::Import(path))
    }

    /// Parse a module path like `./math`, `./utils/helpers`, or `./kapitel-08`
    pub fn parse_module_path(&mut self) -> Result<String, String> {
        let mut path = String::new();
        // Handle ./ and ../ prefixes (including chained ../../)
        while self.peek_kind() == TokenKind::Dot {
            self.advance();
            path.push('.');
            // Check for .. (parent directory)
            if self.peek_kind() == TokenKind::Dot {
                self.advance();
                path.push('.');
            }
            // Consume the / after . or ..
            if self.peek_kind() == TokenKind::Op && self.peek().text == "/" {
                self.advance();
                path.push('/');
            }
        }
        loop {
            if self.peek_kind() == TokenKind::Op && self.peek().text == "/" {
                self.advance();
                path.push('/');
            } else if self.peek_kind() == TokenKind::Dot {
                // Allow role-suffixed modules such as personskatteloven.audit.runa.
                self.advance();
                path.push('.');
            } else if self.peek_kind() == TokenKind::Op && self.peek().text == "-" {
                // Allow dashes in module paths (e.g. kapitel-08)
                self.advance();
                path.push('-');
            } else if self.peek_kind() == TokenKind::Ident
                || self.peek_kind() == TokenKind::Type
                || self.peek_kind() == TokenKind::Int_
            {
                let seg = self.advance().text.clone();
                path.push_str(&seg);
            } else {
                break;
            }
        }
        if path.is_empty() {
            let p = self.peek();
            return Err(format!(
                "{}:{}: expected module path after @ import\n  Try: @ import ./module_name",
                p.line, p.col
            ));
        }
        Ok(path)
    }

    /// Parse: @ depend "crate_name" "version"
    pub fn parse_depend_decl(&mut self) -> Result<Stmt, String> {
        let crate_name = if self.peek_kind() == TokenKind::String_ {
            self.advance().text.clone()
        } else {
            let p = self.peek();
            return Err(format!("{}:{}: expected crate name string after @ depend\n  Try: @ depend \"crate_name\" \"version\"", p.line, p.col));
        };
        let version = if self.peek_kind() == TokenKind::String_ {
            self.advance().text.clone()
        } else {
            let p = self.peek();
            return Err(format!("{}:{}: expected version string after crate name in @ depend\n  Try: @ depend \"{}\" \"1.0\"", p.line, p.col, crate_name));
        };
        Ok(Stmt::Depend(crate_name, version))
    }

    // --- = Binding ---

    pub fn parse_binding(&mut self) -> Result<Stmt, String> {
        let pat = self.parse_pattern()?;
        // A nullary constructor pattern (Pat::Con with no args) in a binding
        // context is almost certainly a variable name that starts uppercase
        // (e.g., K2, T1). The tokenizer classifies uppercase-starting names as
        // Type tokens, which parse_pattern turns into Pat::Con. Without this
        // fix, = K2 = value silently fails to bind (bind_pattern's _ => {} arm).
        let pat = match pat {
            Pat::Con(name, ref args) if args.is_empty() => Pat::Var(name),
            other => other,
        };
        let ty = if self.peek_kind() == TokenKind::Colon {
            self.advance();
            Some(self.parse_type()?)
        } else {
            None
        };
        // Check for <- (monadic bind) vs = (regular bind)
        if self.peek_kind() == TokenKind::Send {
            // = x <- expr  (monadic: unwrap Ok/Some, early-return on Err/None)
            self.advance();
            let value = self.parse_expr()?;
            return Ok(Stmt::MonadicBind(pat, ty, value));
        }
        // Consume = (could be Op("=") or part of the initial = rune)
        if self.peek_kind() == TokenKind::Op && self.peek().text == "=" {
            self.advance();
        } else if self.peek_kind() == TokenKind::Eq {
            self.advance();
        }
        let value = self.parse_expr()?;
        Ok(Stmt::Bind(pat, ty, value))
    }

    // --- Type parsing ---

    pub fn parse_type(&mut self) -> Result<Ty, String> {
        let mut base = self.parse_type_atom()?;
        // T? → Optional(T) — Kotlin-style nullable type sugar for Option(T)
        if self.peek_kind() == TokenKind::Op && self.peek().text == "?" {
            self.advance();
            base = Ty::Optional(Box::new(base));
        }
        if self.peek_kind() == TokenKind::Arrow {
            self.advance();
            let ret = self.parse_type()?;
            Ok(Ty::Arrow(Box::new(base), Box::new(ret)))
        } else {
            Ok(base)
        }
    }

    pub fn parse_type_atom(&mut self) -> Result<Ty, String> {
        // shared T → Ty::Shared(T)
        if self.peek_kind() == TokenKind::Ident && self.peek().text == "shared" {
            self.advance(); // consume "shared"
            let inner = self.parse_type_atom()?;
            return Ok(Ty::Shared(Box::new(inner)));
        }
        match self.peek_kind() {
            TokenKind::Type | TokenKind::Ident => {
                let tok = self.advance();
                // Check for qualified path: fmt::Display, std::ops::Add
                let mut name = tok.text.clone();
                while self.peek_kind() == TokenKind::Colon {
                    let saved = self.pos;
                    self.advance(); // first :
                    if self.peek_kind() == TokenKind::Colon {
                        self.advance(); // second :
                        if let Ok(seg) = self.expect_ident() {
                            name.push_str("::");
                            name.push_str(&seg);
                        } else {
                            self.pos = saved;
                            break;
                        }
                    } else {
                        self.pos = saved;
                        break;
                    }
                }
                if self.peek_kind() == TokenKind::LParen {
                    let args = self.parse_type_list()?;
                    Ok(Ty::App(Box::new(Ty::Name(name)), args))
                } else if name.contains("::") || name.starts_with(|c: char| c.is_uppercase()) {
                    Ok(Ty::Name(name))
                } else {
                    Ok(Ty::Var(name))
                }
            }
            TokenKind::LParen => {
                self.advance();
                if self.peek_kind() == TokenKind::RParen {
                    self.advance();
                    Ok(Ty::Unit)
                } else {
                    let inner = self.parse_type()?;
                    self.expect(TokenKind::RParen)?;
                    Ok(inner)
                }
            }
            TokenKind::Amp => {
                self.advance();
                if self.peek_kind() == TokenKind::KW && self.peek().text == "mut" {
                    self.advance();
                    Ok(Ty::MutRef(Box::new(self.parse_type_atom()?)))
                } else {
                    Ok(Ty::Ref(Box::new(self.parse_type_atom()?)))
                }
            }
            _ => {
                let tok = self.peek().clone();
                let got_desc = match tok.kind {
                    TokenKind::Semi => "newline".to_string(),
                    TokenKind::Op => format!("operator `{}`", tok.text),
                    TokenKind::Int_ | TokenKind::Float_ => format!("number `{}`", tok.text),
                    TokenKind::String_ => "a string literal".to_string(),
                    TokenKind::LBrace => "`{`".to_string(),
                    TokenKind::RBrace => "`}`".to_string(),
                    TokenKind::LParen => "`(`".to_string(),
                    TokenKind::RParen => "`)`".to_string(),
                    TokenKind::Eq => "`=`".to_string(),
                    TokenKind::Pipe => "`|`".to_string(),
                    TokenKind::Eof => "end of file".to_string(),
                    _ => format!("`{}`", tok.text),
                };
                let hint = match tok.kind {
                    TokenKind::Eq => "\n  Hint: did you forget the type? e.g. `name: Type`",
                    TokenKind::LBrace => {
                        "\n  Hint: types use parentheses for fields: `# Name(field: Type)`"
                    }
                    _ => "",
                };
                Err(format!(
                    "{}:{}: expected a type name, got {}{}",
                    tok.line, tok.col, got_desc, hint
                ))
            }
        }
    }

    // --- Pattern parsing ---

    pub fn parse_pattern(&mut self) -> Result<Pat, String> {
        match self.peek_kind() {
            TokenKind::Ident => {
                let tok = self.advance();
                if tok.text == "_" {
                    Ok(Pat::Wild)
                } else {
                    Ok(Pat::Var(tok.text))
                }
            }
            TokenKind::Type => {
                let tok = self.advance();
                if self.peek_kind() == TokenKind::LParen {
                    self.advance();
                    // Check if first arg is named (ident: pattern)
                    let is_named = if self.peek_kind() == TokenKind::Ident
                        && self.peek_kind() != TokenKind::RParen
                    {
                        let saved = self.pos;
                        let _ = self.advance();
                        let has_colon = self.peek_kind() == TokenKind::Colon;
                        self.pos = saved;
                        has_colon
                    } else {
                        false
                    };

                    if is_named {
                        // Named field pattern: Circle(radius: r, ...)
                        let named_args = self.parse_comma_separated(
                            TokenKind::RParen,
                            "named pattern field",
                            |parser| {
                                let field_name = parser.expect_field_name()?;
                                parser.expect(TokenKind::Colon)?;
                                let pattern = parser.parse_pattern()?;
                                Ok((field_name, pattern))
                            },
                        )?;
                        Ok(Pat::NamedCon(tok.text, named_args))
                    } else {
                        // Positional pattern: Circle(r)
                        let args = self.parse_comma_separated(
                            TokenKind::RParen,
                            "constructor pattern",
                            |parser| parser.parse_pattern(),
                        )?;
                        Ok(Pat::Con(tok.text, args))
                    }
                } else {
                    Ok(Pat::Con(tok.text, Vec::new()))
                }
            }
            TokenKind::Int_ => {
                let tok = self.advance();
                let value = tok.text.parse::<i64>().map_err(|_| {
                    format!(
                        "{}:{}: integer literal `{}` is outside Futuruna Int range",
                        tok.line, tok.col, tok.text
                    )
                })?;
                Ok(Pat::Lit(Literal::Int(value)))
            }
            TokenKind::Float_ => {
                let tok = self.advance();
                Ok(Pat::Lit(Literal::Float(tok.text.parse().unwrap_or(0.0))))
            }
            TokenKind::String_ => {
                let tok = self.advance();
                Ok(Pat::Lit(Literal::Str(tok.text)))
            }
            TokenKind::Bool_ => {
                let tok = self.advance();
                // In pattern context, True/False are constructors
                Ok(Pat::Con(tok.text, Vec::new()))
            }
            TokenKind::Op if self.peek().text == "-" => {
                self.advance();
                let tok = self.advance();
                if tok.kind == TokenKind::Float_ {
                    Ok(Pat::Lit(Literal::Float(
                        -tok.text.parse::<f64>().unwrap_or(0.0),
                    )))
                } else {
                    let magnitude = tok.text.parse::<i128>().map_err(|_| {
                        format!(
                            "{}:{}: integer literal `-{}` is outside Futuruna Int range",
                            tok.line, tok.col, tok.text
                        )
                    })?;
                    let value = i64::try_from(-magnitude).map_err(|_| {
                        format!(
                            "{}:{}: integer literal `-{}` is outside Futuruna Int range",
                            tok.line, tok.col, tok.text
                        )
                    })?;
                    Ok(Pat::Lit(Literal::Int(value)))
                }
            }
            _ => {
                let tok = self.advance();
                if tok.text == "_" {
                    Ok(Pat::Wild)
                } else {
                    Ok(Pat::Var(tok.text))
                }
            }
        }
    }

    // --- Expression parsing (Pratt / precedence climbing) ---

    pub fn parse_expr(&mut self) -> Result<Expr, String> {
        self.parse_expr_prec(0)
    }

    pub fn parse_expr_prec(&mut self, min_prec: u8) -> Result<Expr, String> {
        let mut lhs = self.parse_atom()?;

        loop {
            // Check for postfix / infix operations
            match self.peek_kind() {
                // Postfix ? operator (try/error propagation) — must be before generic Op
                TokenKind::Op if self.peek().text == "?" => {
                    let start_span = lhs.span;
                    self.advance();
                    let span =
                        start_span.merge(self.span_since(&self.tokens[self.pos - 1].clone()));
                    lhs = Expr::new(ExprKind::Try(Box::new(lhs)), span);
                }
                // Pipe-forward operator: x |> f — preserved as ExprKind::Pipe AST node
                TokenKind::PipeGt => {
                    let pipe_prec: u8 = 1; // lowest precedence
                    if pipe_prec < min_prec {
                        break;
                    }
                    let start_span = lhs.span;
                    self.advance();
                    let rhs = self.parse_expr_prec(pipe_prec + 1)?;
                    let span = start_span.merge(rhs.span);
                    lhs = Expr::new(ExprKind::Pipe(Box::new(lhs), Box::new(rhs)), span);
                }
                // Binary operators (including `or` which lexes as Op "||")
                TokenKind::Op => {
                    let op = &self.peek().text;
                    let prec = op_precedence(op);
                    if prec < min_prec {
                        break;
                    }
                    let start_span = lhs.span;
                    let op = self.advance().text;
                    let rhs = self.parse_expr_prec(prec + 1)?;
                    let span = start_span.merge(rhs.span);
                    lhs = Expr::new(ExprKind::BinOp(op, Box::new(lhs), Box::new(rhs)), span);
                }
                // `and` as infix operator (alias for &&) in non-rule expressions
                // In rule bodies, `and` is handled as conjunction separator instead
                TokenKind::Ident if self.peek().text == "and" && !self.in_rule_body => {
                    let prec = op_precedence("&&");
                    if prec < min_prec {
                        break;
                    }
                    let start_span = lhs.span;
                    self.advance();
                    let rhs = self.parse_expr_prec(prec + 1)?;
                    let span = start_span.merge(rhs.span);
                    lhs = Expr::new(
                        ExprKind::BinOp("&&".to_string(), Box::new(lhs), Box::new(rhs)),
                        span,
                    );
                }
                // Safe call: expr?.field → match expr { Some(v) -> Some(v.field), None -> None }
                TokenKind::SafeCall => {
                    self.advance(); // consume '?.'
                    let field = self.expect_field_name()?;
                    let v = format!("__safe_{}", field);
                    lhs = ExprKind::Match(
                        Box::new(lhs),
                        vec![
                            MatchArm {
                                pat: Pat::Con("Some".into(), vec![Pat::Var(v.clone())]),
                                guard: None,
                                body: ExprKind::App(
                                    Box::new(ExprKind::Var("Some".into()).into()),
                                    vec![ExprKind::Field(Box::new(ExprKind::Var(v).into()), field)
                                        .into()],
                                )
                                .into(),
                            },
                            MatchArm {
                                pat: Pat::Con("None".into(), vec![]),
                                guard: None,
                                body: ExprKind::Var("None".into()).into(),
                            },
                        ],
                    )
                    .into();
                }
                // Elvis: expr ?: default → match expr { Some(v) -> v, None -> default }
                TokenKind::Elvis => {
                    let prec: u8 = 2; // just above pipe (1), below arithmetic
                    if prec < min_prec {
                        break;
                    }
                    self.advance(); // consume '?:'
                    let default = self.parse_expr_prec(prec + 1)?;
                    let v = "__elvis_v".to_string();
                    lhs = ExprKind::Match(
                        Box::new(lhs),
                        vec![
                            MatchArm {
                                pat: Pat::Con("Some".into(), vec![Pat::Var(v.clone())]),
                                guard: None,
                                body: ExprKind::Var(v).into(),
                            },
                            MatchArm {
                                pat: Pat::Con("None".into(), vec![]),
                                guard: None,
                                body: default,
                            },
                        ],
                    )
                    .into();
                }
                // Field access: expr.field
                TokenKind::Dot => {
                    let start_span = lhs.span;
                    self.advance();
                    let field = self.expect_field_name()?;
                    let span =
                        start_span.merge(self.span_since(&self.tokens[self.pos - 1].clone()));
                    lhs = Expr::new(ExprKind::Field(Box::new(lhs), field), span);
                }
                // Function application: expr(args)
                TokenKind::LParen => {
                    let start_span = lhs.span;
                    let args = self.parse_arg_list()?;
                    let span =
                        start_span.merge(self.span_since(&self.tokens[self.pos - 1].clone()));
                    lhs = Expr::new(ExprKind::App(Box::new(lhs), args), span);
                }
                // Index: expr[idx]
                TokenKind::LBracket => {
                    self.advance();
                    let idx = self.parse_expr()?;
                    self.expect(TokenKind::RBracket)?;
                    lhs = ExprKind::Index(Box::new(lhs), Box::new(idx)).into();
                }
                _ => break,
            }
        }

        Ok(lhs)
    }

    fn parse_pathof_expr(&mut self, start_tok: Token) -> Result<Expr, String> {
        self.expect(TokenKind::LParen)?;
        self.skip_semis();

        let root = self.advance();
        if root.kind != TokenKind::Type {
            return Err(format!(
                "{}:{}: pathof root must be a declared type name, got `{}`",
                root.line, root.col, root.text
            ));
        }
        let mut arguments = vec![Expr::new(
            ExprKind::Lit(Literal::Str(root.text.clone())),
            self.token_span(&root),
        )];

        loop {
            self.skip_semis();
            if self.peek_kind() == TokenKind::RParen {
                break;
            }
            let first_colon = self.expect(TokenKind::Colon)?;
            if self.peek_kind() != TokenKind::Colon {
                let token = self.peek();
                return Err(format!(
                    "{}:{}: pathof segments use `::`; expected a second `:` after {}:{}",
                    token.line, token.col, first_colon.line, first_colon.col
                ));
            }
            self.advance();
            self.skip_semis();
            let segment = self.advance();
            if !matches!(
                segment.kind,
                TokenKind::Ident | TokenKind::Type | TokenKind::KW | TokenKind::Bool_
            ) {
                return Err(format!(
                    "{}:{}: expected a field, variant, or `$variant` after `::`, got `{}`",
                    segment.line, segment.col, segment.text
                ));
            }
            if segment.text.starts_with('$') && segment.text != "$variant" {
                return Err(format!(
                    "{}:{}: unknown pathof selector `{}`; only `$variant` is supported",
                    segment.line, segment.col, segment.text
                ));
            }
            arguments.push(Expr::new(
                ExprKind::Lit(Literal::Str(segment.source_text.clone())),
                self.token_span(&segment),
            ));
        }

        if arguments.len() == 1 {
            return Err(format!(
                "{}:{}: pathof requires at least one field or variant segment",
                root.line, root.col
            ));
        }
        self.expect(TokenKind::RParen)?;
        let function = Expr::new(
            ExprKind::Var(PATHOF_MARKER.to_string()),
            self.token_span(&start_tok),
        );
        Ok(self.spanned(ExprKind::App(Box::new(function), arguments), &start_tok))
    }

    fn parse_refof_expr(&mut self, start_tok: Token) -> Result<Expr, String> {
        self.expect(TokenKind::LParen)?;
        self.skip_semis();

        let root = self.advance();
        let mode = match root.kind {
            TokenKind::Ident | TokenKind::KW => "symbol",
            TokenKind::Type => "type",
            _ => {
                return Err(format!(
                    "{}:{}: refof target must start with a declared symbol or type name, got `{}`",
                    root.line, root.col, root.text
                ));
            }
        };
        let mut arguments = vec![
            Expr::new(
                ExprKind::Lit(Literal::Str(mode.to_string())),
                self.token_span(&start_tok),
            ),
            Expr::new(
                ExprKind::Lit(Literal::Str(root.text.clone())),
                self.token_span(&root),
            ),
        ];

        loop {
            self.skip_semis();
            if self.peek_kind() == TokenKind::RParen {
                break;
            }
            if mode == "symbol" {
                let token = self.peek();
                return Err(format!(
                    "{}:{}: refof symbol references are terminal; qualify members from a type name",
                    token.line, token.col
                ));
            }
            let first_colon = self.expect(TokenKind::Colon)?;
            if self.peek_kind() != TokenKind::Colon {
                let token = self.peek();
                return Err(format!(
                    "{}:{}: refof segments use `::`; expected a second `:` after {}:{}",
                    token.line, token.col, first_colon.line, first_colon.col
                ));
            }
            self.advance();
            self.skip_semis();
            let segment = self.advance();
            if !matches!(
                segment.kind,
                TokenKind::Ident | TokenKind::Type | TokenKind::KW | TokenKind::Bool_
            ) {
                return Err(format!(
                    "{}:{}: expected a field, variant, scoped member, or `$variant` after `::`, got `{}`",
                    segment.line, segment.col, segment.text
                ));
            }
            if segment.text.starts_with('$') && segment.text != "$variant" {
                return Err(format!(
                    "{}:{}: unknown refof selector `{}`; only `$variant` is supported",
                    segment.line, segment.col, segment.text
                ));
            }
            arguments.push(Expr::new(
                ExprKind::Lit(Literal::Str(segment.source_text.clone())),
                self.token_span(&segment),
            ));
        }

        self.expect(TokenKind::RParen)?;
        let function = Expr::new(
            ExprKind::Var(REFOF_MARKER.to_string()),
            self.token_span(&start_tok),
        );
        Ok(self.spanned(ExprKind::App(Box::new(function), arguments), &start_tok))
    }

    pub fn parse_atom(&mut self) -> Result<Expr, String> {
        match self.peek_kind() {
            // Identifiers and type constructors
            TokenKind::Ident => {
                let tok = self.advance();
                if tok.text == "pathof" && self.peek_kind() == TokenKind::LParen {
                    return self.parse_pathof_expr(tok);
                }
                if tok.text == "refof" && self.peek_kind() == TokenKind::LParen {
                    return self.parse_refof_expr(tok);
                }
                let span = self.token_span(&tok);
                Ok(Expr::new(ExprKind::Var(tok.text), span))
            }
            TokenKind::Type => {
                let tok = self.advance();
                let span = self.token_span(&tok);
                // Type constructor: might be called with args
                Ok(Expr::new(ExprKind::Var(tok.text), span))
            }
            // Literals
            TokenKind::Int_ => {
                let tok = self.advance();
                let span = self.token_span(&tok);
                let value = tok.text.parse::<i64>().map_err(|_| {
                    format!(
                        "{}:{}: integer literal `{}` is outside Futuruna Int range",
                        tok.line, tok.col, tok.text
                    )
                })?;
                Ok(Expr::new(ExprKind::Lit(Literal::Int(value)), span))
            }
            TokenKind::Float_ => {
                let tok = self.advance();
                let span = self.token_span(&tok);
                Ok(Expr::new(
                    ExprKind::Lit(Literal::Float(tok.text.parse().unwrap_or(0.0))),
                    span,
                ))
            }
            TokenKind::String_ => {
                let tok = self.advance();
                let span = self.token_span(&tok);
                Ok(Expr::new(ExprKind::Lit(Literal::Str(tok.text)), span))
            }
            TokenKind::Char_ => {
                let tok = self.advance();
                let span = self.token_span(&tok);
                let c = tok.text.chars().next().unwrap_or(' ');
                Ok(Expr::new(ExprKind::Lit(Literal::Char(c)), span))
            }
            TokenKind::Bool_ => {
                let tok = self.advance();
                let span = self.token_span(&tok);
                Ok(Expr::new(
                    ExprKind::Lit(Literal::Bool(tok.text == "True")),
                    span,
                ))
            }
            // Parenthesized expression, unit, or tuple
            TokenKind::LParen => {
                self.advance();
                while self.peek_kind() == TokenKind::Semi {
                    self.advance();
                }
                if self.peek_kind() == TokenKind::RParen {
                    self.advance();
                    return Ok(ExprKind::Unit.into());
                }
                let expr = self.parse_expr()?;
                while self.peek_kind() == TokenKind::Semi {
                    self.advance();
                }
                if self.peek_kind() == TokenKind::Comma {
                    // Tuple
                    let mut elems = vec![expr];
                    while self.peek_kind() == TokenKind::Comma {
                        self.advance();
                        while self.peek_kind() == TokenKind::Semi {
                            self.advance();
                        }
                        if self.peek_kind() == TokenKind::RParen {
                            break;
                        }
                        elems.push(self.parse_expr()?);
                        while self.peek_kind() == TokenKind::Semi {
                            self.advance();
                        }
                    }
                    self.expect(TokenKind::RParen)?;
                    return Ok(ExprKind::Tuple(elems).into());
                }
                self.expect(TokenKind::RParen)?;
                Ok(expr)
            }
            // Block
            TokenKind::LBrace => self.parse_block_expr(),
            // List literal (supports multi-line)
            TokenKind::LBracket => {
                let bracket_tok = self.advance();
                let elems =
                    self.parse_comma_separated(TokenKind::RBracket, "list element", |parser| {
                        parser.parse_expr()
                    })?;
                Ok(self.spanned(ExprKind::List(elems), &bracket_tok))
            }
            // Lambda: |params| body   OR   | handle Effect { ... } in body
            // || as single Op token — empty lambda
            TokenKind::Op if self.peek().text == "||" => {
                self.advance();
                let body = self.parse_expr()?;
                return Ok(ExprKind::Lambda(Vec::new(), Box::new(body)).into());
            }
            TokenKind::Pipe => {
                self.advance();
                // | handle EffectName { | op(args) -> handler } in body
                if self.peek_kind() == TokenKind::KW && self.peek().text == "handle" {
                    return self.parse_handle_expr();
                }
                if self.peek_kind() == TokenKind::Pipe {
                    // || — empty lambda (two separate Pipe tokens)
                    self.advance();
                    let body = self.parse_expr()?;
                    return Ok(ExprKind::Lambda(Vec::new(), Box::new(body)).into());
                }
                let params =
                    self.parse_comma_separated(TokenKind::Pipe, "lambda parameter", |parser| {
                        let name = parser.expect_ident()?;
                        let ty = if parser.peek_kind() == TokenKind::Colon {
                            parser.advance();
                            Some(parser.parse_type()?)
                        } else {
                            None
                        };
                        Ok(Param {
                            name,
                            ty,
                            inout: false,
                        })
                    })?;
                let body = self.parse_expr()?;
                Ok(ExprKind::Lambda(params, Box::new(body)).into())
            }
            // ~[...] stream source literal: ~[1, 2, 3] → from_list([1, 2, 3])
            TokenKind::Tilde
                if {
                    // Look ahead: is the token after ~ a [ ?
                    let next_pos = self.pos + 1;
                    next_pos < self.tokens.len()
                        && self.tokens[next_pos].kind == TokenKind::LBracket
                } =>
            {
                self.advance(); // consume ~
                let list_expr = self.parse_atom()?; // parse the [...] list literal
                Ok(ExprKind::App(
                    Box::new(ExprKind::Var("from_list".to_string()).into()),
                    vec![list_expr],
                )
                .into())
            }
            // Unary operators
            TokenKind::Op if self.peek().text == "-" || self.peek().text == "!" => {
                let tok = self.advance();
                if tok.text == "-"
                    && self.peek_kind() == TokenKind::Int_
                    && self.peek().text == "9223372036854775808"
                {
                    let magnitude = self.advance();
                    let span = self.token_span(&tok).merge(self.token_span(&magnitude));
                    return Ok(Expr::new(ExprKind::Lit(Literal::Int(i64::MIN)), span));
                }
                let operand = self.parse_expr_prec(u8::MAX)?;
                Ok(ExprKind::UnOp(tok.text, Box::new(operand)).into())
            }
            // & reference
            TokenKind::Amp => {
                self.advance();
                if self.peek_kind() == TokenKind::KW && self.peek().text == "mut" {
                    self.advance();
                    let inner = self.parse_expr_prec(u8::MAX)?;
                    Ok(ExprKind::UnOp("&mut".to_string(), Box::new(inner)).into())
                } else {
                    let inner = self.parse_expr_prec(u8::MAX)?;
                    Ok(ExprKind::UnOp("&".to_string(), Box::new(inner)).into())
                }
            }
            // @ effect invocation
            TokenKind::At => {
                self.advance();
                let name_tok = self.advance();
                let args = if self.peek_kind() == TokenKind::LParen {
                    self.parse_arg_list()?
                } else {
                    Vec::new()
                };
                Ok(ExprKind::Effect(name_tok.text, args).into())
            }
            // Keywords that start expressions
            TokenKind::KW => {
                let tok = self.advance();
                match tok.text.as_str() {
                    "match" => self.parse_match_expr(),
                    "if" => self.parse_if_expr(tok),
                    _ => Ok(ExprKind::Var(tok.text).into()),
                }
            }
            // = inside expressions (binding in block)
            TokenKind::Eq => {
                let tok = self.peek().clone();
                Err(format!(
                    "{}:{}: `=` binding found where an expression was expected.\n  Bindings (= name = value) can only appear at the top level or inside {{ blocks }}.\n  Did you mean `==` for comparison?",
                    tok.line, tok.col
                ))
            }
            _ => {
                let tok = self.peek().clone();
                let kind_name = match tok.kind {
                    TokenKind::Semi => "newline",
                    TokenKind::Colon => "colon `:`",
                    TokenKind::Pipe => "pipe `|`",
                    TokenKind::Hash => "hash `#`",
                    TokenKind::At => "at `@`",
                    TokenKind::Tilde => "tilde `~`",
                    TokenKind::Eq => "equals `=`",
                    TokenKind::Gt => "greater-than `>`",
                    TokenKind::Arrow => "arrow `->`",
                    TokenKind::Eof => "end of file",
                    _ => "",
                };
                let display = if kind_name.is_empty() {
                    format!("`{}`", tok.text)
                } else {
                    kind_name.to_string()
                };
                let hint = match tok.kind {
                    TokenKind::Hash => "\n  Hint: `#` starts a type declaration. Did you forget to close the previous expression?",
                    TokenKind::At => "\n  Hint: `@` starts an effect. Did you forget to close the previous expression?",
                    TokenKind::Pipe => "\n  Hint: `|` starts a rule. If you meant a lambda, use `|param| expr`.",
                    TokenKind::Eq => "\n  Hint: `=` starts a binding. Did you mean `==` for comparison?",
                    TokenKind::Semi => "\n  Hint: this is a hard statement newline. Continue after `=`, `->`, `,`, or an operator, or place the expression inside `(...)`.",
                    TokenKind::Eof => "\n  Hint: unexpected end of file. Check for unclosed `{`, `(`, or `[`.",
                    _ => "",
                };
                Err(format!(
                    "{}:{}: unexpected {}{}",
                    tok.line, tok.col, display, hint
                ))
            }
        }
    }

    pub fn parse_arg_list(&mut self) -> Result<Vec<Expr>, String> {
        self.expect(TokenKind::LParen)?;
        self.parse_comma_separated(TokenKind::RParen, "call argument", |parser| {
            if matches!(
                parser.peek_kind(),
                TokenKind::Ident | TokenKind::Type | TokenKind::Bool_ | TokenKind::KW
            ) && parser.tokens.get(parser.pos + 1).is_some_and(|tok| {
                tok.kind == TokenKind::Eq || (tok.kind == TokenKind::Op && tok.text == "=")
            }) {
                let start_tok = parser.peek().clone();
                let field_name = parser.advance().source_text;
                if parser.peek_kind() == TokenKind::Eq {
                    parser.advance();
                } else if parser.peek_kind() == TokenKind::Op && parser.peek().text == "=" {
                    parser.advance();
                } else {
                    parser.expect(TokenKind::Eq)?;
                }
                let value = parser.parse_expr()?;
                return Ok(named_arg_expr_with_span(
                    field_name,
                    value,
                    parser.span_since(&start_tok),
                ));
            }
            let argument = parser.parse_expr()?;
            // Allow optional type annotation `: Type` on args (used in rule heads).
            // Keep the canonical Futuruna spelling so generic annotations can be
            // reconstructed as Ty instead of leaking Rust debug output downstream.
            if parser.peek_kind() == TokenKind::Colon {
                parser.advance(); // consume ':'
                let ty = parser.parse_type()?;
                let type_name = ty.to_string();
                // Wrap in a typed annotation that the interpreter can check
                Ok(ExprKind::App(
                    Box::new(ExprKind::Var("__typed".into()).into()),
                    vec![argument, ExprKind::Var(type_name).into()],
                )
                .into())
            } else {
                Ok(argument)
            }
        })
    }

    pub fn parse_block_expr(&mut self) -> Result<Expr, String> {
        self.expect(TokenKind::LBrace)?;
        self.skip_semis();
        let mut stmts = Vec::new();
        while self.peek_kind() != TokenKind::RBrace {
            let stmt = self.parse_block_statement()?;
            stmts.push(stmt);
            self.skip_semis();
        }
        self.expect(TokenKind::RBrace)?;
        Ok(ExprKind::Block(stmts).into())
    }

    pub fn parse_block_statement(&mut self) -> Result<Stmt, String> {
        self.skip_semis();
        match self.peek_kind() {
            TokenKind::Eq => {
                self.advance();
                self.parse_binding()
            }
            TokenKind::Gt => {
                self.advance();
                self.parse_definition()
            }
            TokenKind::Op if self.peek().text == ">" => {
                self.advance();
                self.parse_definition()
            }
            TokenKind::Tilde => {
                // ~[...] stream source literal: ~[1, 2, 3] → Stmt::Expr(from_list([1, 2, 3]))
                {
                    let next_pos = self.pos + 1;
                    if next_pos < self.tokens.len()
                        && self.tokens[next_pos].kind == TokenKind::LBracket
                    {
                        self.advance(); // consume ~
                        let list_expr = self.parse_atom()?; // parse the [...] list literal
                        return Ok(Stmt::Expr(
                            ExprKind::App(
                                Box::new(ExprKind::Var("from_list".to_string()).into()),
                                vec![list_expr],
                            )
                            .into(),
                        ));
                    }
                }

                let saved = self.pos;
                self.advance();

                // Disambiguate: ~ name = expr (StreamBind) vs ~ expr | pat -> body (StreamSub)
                let name_tok = self.advance();
                let is_binding = name_tok.kind == TokenKind::Ident
                    && (self.peek_kind() == TokenKind::Eq
                        || (self.peek_kind() == TokenKind::Op && self.peek().text == "="));

                if is_binding {
                    // Consume =
                    if self.peek_kind() == TokenKind::Eq {
                        self.advance();
                    } else if self.peek_kind() == TokenKind::Op && self.peek().text == "=" {
                        self.advance();
                    }
                    let expr = self.parse_expr()?;
                    Ok(Stmt::StreamBind(name_tok.text.clone(), expr))
                } else {
                    // Backtrack and parse as stream expression + match arms
                    self.pos = saved;
                    self.advance(); // consume ~
                    let stream_expr = self.parse_expr()?;
                    let mut arms = Vec::new();

                    while self.peek_kind() == TokenKind::Pipe {
                        self.advance(); // consume |
                        let pat = self.parse_pattern()?;
                        let guard = if self.peek_kind() == TokenKind::KW && self.peek().text == "if"
                        {
                            self.advance();
                            Some(self.parse_expr()?)
                        } else {
                            None
                        };

                        if self.peek_kind() == TokenKind::Arrow {
                            self.advance();
                        } else if self.peek_kind() == TokenKind::Op && self.peek().text == "->" {
                            self.advance();
                        } else {
                            return Err(format!("{}:{}: expected `->` after pattern in subscription arm.\n  Each arm should look like: | pattern -> {{ body }}", self.peek().line, self.peek().col));
                        }

                        let body = self.parse_expr()?;
                        arms.push(MatchArm { pat, guard, body });
                        self.skip_semis();
                    }

                    if arms.is_empty() {
                        return Err(format!(
                            "{}:{}: stream subscription needs at least one `|` arm.\n  Example:\n    ~ my_stream\n    | x -> {{ @ print(x) }}\n    | Err(e) -> {{ @ print(\"error\") }}\n    | Complete -> {{ @ print(\"done\") }}",
                            self.peek().line, self.peek().col
                        ));
                    }
                    Ok(Stmt::StreamSub(stream_expr, arms))
                }
            }
            TokenKind::Pipe => {
                // Inside a block, | can be a lambda |x| ... OR a rule | head -> body
                // Disambiguate: if the token after | is an ident followed by |, it's a lambda
                // Otherwise it's a rule/match arm
                let saved = self.pos;
                self.advance(); // consume |
                                // Check if this looks like a lambda: |x| or |x, y|
                let mut looks_like_lambda = false;
                if self.peek_kind() == TokenKind::Pipe {
                    // || — empty lambda
                    looks_like_lambda = true;
                } else if self.peek_kind() == TokenKind::Ident {
                    // Save pos, scan forward
                    let saved2 = self.pos;
                    self.advance(); // consume ident
                    if self.peek_kind() == TokenKind::Pipe || self.peek_kind() == TokenKind::Comma {
                        looks_like_lambda = true;
                    }
                    self.pos = saved2; // restore
                }
                self.pos = saved; // restore to before |
                if looks_like_lambda {
                    let expr = self.parse_expr()?;
                    return Ok(Stmt::Expr(expr));
                }
                self.advance(); // consume |
                self.parse_rule()
            }
            TokenKind::Hash => {
                self.advance();
                self.parse_type_decl()
            }
            TokenKind::At => {
                self.advance();
                self.parse_annotation()
            }
            // for x in expr { body }
            TokenKind::KW if self.peek().text == "for" => {
                self.advance(); // consume 'for'
                let var = self.expect_ident()?;
                // expect 'in'
                if self.peek_kind() == TokenKind::KW && self.peek().text == "in" {
                    self.advance();
                } else {
                    let p = self.peek();
                    return Err(format!(
                        "{}:{}: expected `in` after `for {}`, got `{}`.\n  \
                        Try: for {} in collection {{ ... }}",
                        p.line, p.col, var, p.text, var
                    ));
                }
                let iter_expr = self.parse_expr_prec(0)?;
                self.expect(TokenKind::LBrace)?;
                self.skip_semis();
                let mut body = Vec::new();
                while self.peek_kind() != TokenKind::RBrace && self.peek_kind() != TokenKind::Eof {
                    body.push(self.parse_block_statement()?);
                    self.skip_semis();
                }
                self.expect(TokenKind::RBrace)?;
                Ok(Stmt::For(var, iter_expr, body))
            }
            // while cond { body }
            TokenKind::KW if self.peek().text == "while" => {
                self.advance(); // consume 'while'
                let cond = self.parse_expr_prec(0)?;
                self.expect(TokenKind::LBrace)?;
                self.skip_semis();
                let mut body = Vec::new();
                while self.peek_kind() != TokenKind::RBrace && self.peek_kind() != TokenKind::Eof {
                    body.push(self.parse_block_statement()?);
                    self.skip_semis();
                }
                self.expect(TokenKind::RBrace)?;
                Ok(Stmt::While(cond, body))
            }
            _ => {
                let expr = self.parse_expr()?;
                // Check for <- (actor send): target <- message
                if self.peek_kind() == TokenKind::Send {
                    self.advance(); // consume '<-'
                    let msg = self.parse_expr()?;
                    return Ok(Stmt::Send(expr, msg));
                }
                Ok(Stmt::Expr(expr))
            }
        }
    }

    pub fn parse_match_expr(&mut self) -> Result<Expr, String> {
        let scrut = self.parse_expr_prec(0)?;
        self.expect(TokenKind::LBrace)?;
        self.skip_semis();
        let mut arms = Vec::new();
        while self.peek_kind() != TokenKind::RBrace {
            if self.peek_kind() == TokenKind::Pipe {
                self.advance();
            }
            let pat = self.parse_pattern()?;
            let guard = if self.peek_kind() == TokenKind::KW && self.peek().text == "if" {
                self.advance();
                Some(self.parse_expr()?)
            } else {
                None
            };
            self.expect(TokenKind::Arrow)?;
            let body = self.parse_expr()?;
            arms.push(MatchArm { pat, guard, body });
            self.skip_semis();
        }
        self.expect(TokenKind::RBrace)?;
        Ok(ExprKind::Match(Box::new(scrut), arms).into())
    }

    pub fn parse_if_expr(&mut self, start_tok: Token) -> Result<Expr, String> {
        let cond = self.parse_expr_prec(0)?;
        let then_ = self.parse_block_expr()?;
        // Skip newlines (Semi tokens) between } and else
        self.skip_semis();
        let else_ = if self.peek_kind() == TokenKind::KW && self.peek().text == "else" {
            self.advance();
            if self.peek_kind() == TokenKind::KW && self.peek().text == "if" {
                let if_tok = self.advance();
                self.parse_if_expr(if_tok)?
            } else {
                self.parse_block_expr()?
            }
        } else {
            ExprKind::Unit.into()
        };
        Ok(self.spanned(
            ExprKind::If(Box::new(cond), Box::new(then_), Box::new(else_)),
            &start_tok,
        ))
    }
}

/// Parse the canonical type spelling carried by an internal rule-head
/// annotation. Rule annotations are represented inside the expression AST for
/// backward compatibility, while this helper restores the structured `Ty` used
/// by type checking, interpretation, and code generation.
pub fn parse_type_annotation(source: &str) -> Result<Ty, String> {
    let mut lexer = Lexer::new(source);
    let tokens = lexer.tokenize();
    let mut parser = Parser::new(tokens, source);
    let ty = parser.parse_type()?;
    parser.skip_semis();
    if parser.peek_kind() != TokenKind::Eof {
        let token = parser.peek();
        return Err(format!(
            "{}:{}: unexpected `{}` after type annotation",
            token.line, token.col, token.text
        ));
    }
    Ok(ty)
}

pub fn op_precedence(op: &str) -> u8 {
    match op {
        "||" => 1,
        "&&" => 2,
        "==" | "!=" => 3,
        "<" | ">" | "<=" | ">=" => 4,
        "+" | "-" => 5,
        "*" | "/" | "%" => 6,
        _ => 0,
    }
}

pub fn lower_expr_to_proof_term(expr: &Expr) -> Result<proof_kernel::Term, String> {
    match &expr.kind {
        ExprKind::Var(name) => Ok(proof_kernel::Term::Var(name.clone())),
        ExprKind::Lit(Literal::Int(n)) => Ok(proof_kernel::Term::Int(*n)),
        ExprKind::Lit(Literal::Bool(b)) => Ok(proof_kernel::Term::App(
            if *b { "True" } else { "False" }.into(),
            vec![],
        )),
        ExprKind::UnOp(op, inner) if op == "-" => Ok(proof_kernel::Term::Op(
            "-".into(),
            Box::new(proof_kernel::Term::Int(0)),
            Box::new(lower_expr_to_proof_term(inner)?),
        )),
        ExprKind::BinOp(op, lhs, rhs) if matches!(op.as_str(), "+" | "-" | "*" | "/") => {
            Ok(proof_kernel::Term::Op(
                op.clone(),
                Box::new(lower_expr_to_proof_term(lhs)?),
                Box::new(lower_expr_to_proof_term(rhs)?),
            ))
        }
        ExprKind::App(func, args) => {
            let name = match &func.kind {
                ExprKind::Var(name) => name.clone(),
                _ => {
                    return Err(
                        "proof kernel only supports simple function/constructor calls".into(),
                    );
                }
            };
            let mut lowered_args = Vec::with_capacity(args.len());
            for arg in args {
                lowered_args.push(lower_expr_to_proof_term(arg)?);
            }
            Ok(proof_kernel::Term::App(name, lowered_args))
        }
        _ => Err(format!(
            "proof kernel cannot lower term expression: {:?}",
            expr.kind
        )),
    }
}

pub fn lower_expr_to_proof_prop(expr: &Expr) -> Result<proof_kernel::Prop, String> {
    let succ = |term: proof_kernel::Term| {
        proof_kernel::Term::Op(
            "+".into(),
            Box::new(term),
            Box::new(proof_kernel::Term::Int(1)),
        )
    };

    match &expr.kind {
        ExprKind::BinOp(op, lhs, rhs) if op == "==" => Ok(proof_kernel::Prop::Eq(
            lower_expr_to_proof_term(lhs)?,
            lower_expr_to_proof_term(rhs)?,
        )),
        ExprKind::BinOp(op, lhs, rhs) if op == "<=" => Ok(proof_kernel::Prop::Le(
            lower_expr_to_proof_term(lhs)?,
            lower_expr_to_proof_term(rhs)?,
        )),
        ExprKind::BinOp(op, lhs, rhs) if op == ">=" => Ok(proof_kernel::Prop::Le(
            lower_expr_to_proof_term(rhs)?,
            lower_expr_to_proof_term(lhs)?,
        )),
        ExprKind::BinOp(op, lhs, rhs) if op == "<" => Ok(proof_kernel::Prop::Le(
            succ(lower_expr_to_proof_term(lhs)?),
            lower_expr_to_proof_term(rhs)?,
        )),
        ExprKind::BinOp(op, lhs, rhs) if op == ">" => Ok(proof_kernel::Prop::Le(
            succ(lower_expr_to_proof_term(rhs)?),
            lower_expr_to_proof_term(lhs)?,
        )),
        ExprKind::BinOp(op, lhs, rhs) if op == "&&" => Ok(proof_kernel::Prop::And(
            Box::new(lower_expr_to_proof_prop(lhs)?),
            Box::new(lower_expr_to_proof_prop(rhs)?),
        )),
        ExprKind::App(func, args)
            if matches!(&func.kind, ExprKind::Var(name) if name == "not") && args.len() == 1 =>
        {
            Ok(proof_kernel::Prop::Not(Box::new(lower_expr_to_proof_prop(
                &args[0],
            )?)))
        }
        ExprKind::Lit(Literal::Bool(false)) => Ok(proof_kernel::Prop::False),
        _ => Err(format!(
            "proof kernel cannot lower proposition expression: {:?}",
            expr.kind
        )),
    }
}

// ============================================================================
// PART 5: VALUES & ENVIRONMENT
// ============================================================================

#[derive(Debug, Clone)]
pub enum Value {
    Int(i64),
    Float(f64),
    Str(String),
    Char(char),
    Bool(bool),
    Unit,
    List(Vec<Value>),
    Tuple(Vec<Value>),
    Constructor(String, Rc<Vec<Value>>),
    NamedConstructor(String, Rc<Vec<(String, Value)>>), // Named fields: Circle { radius: 5.0 }
    /// A constructor declared in a qualified or inline runtime namespace.
    /// Root constructors retain the compact legacy variants above; module
    /// values carry their registry owner so later field/pattern/method lookup
    /// cannot fall back to a same-named declaration in the caller.
    NamespacedConstructor {
        namespace: RuntimeNamespace,
        name: String,
        arguments: Rc<Vec<Value>>,
        declaration_env: Option<Rc<Env>>,
    },
    NamespacedNamedConstructor {
        namespace: RuntimeNamespace,
        name: String,
        fields: Rc<Vec<(String, Value)>>,
        declaration_env: Option<Rc<Env>>,
    },
    Closure {
        name: Option<String>, // for recursion
        params: Vec<String>,
        body: Expr,
        env: Env,
    },
    Builtin(String),
    /// A rule, constructor, or other registry-backed callable whose spelling
    /// is meaningful only inside its declaration namespace.
    NamespacedBuiltin {
        namespace: RuntimeNamespace,
        name: String,
        declaration_env: Option<Rc<Env>>,
    },
    /// Actor: name, current state, handler definitions, base env
    Actor {
        actor_name: String,
        state: Box<Value>,
        state_param: String,
        handlers: Vec<Handler>,
        env: Env,
    },
    /// Reactive stream: ordered sequence of values (lazy in codegen, eager in interpreter)
    Stream(Vec<Value>),
    /// Subject: a mutable stream you can push into with <-
    /// (values, initial_value). Subjects ARE streams you can write to.
    Subject(Vec<Value>),
    /// Map: key-value dictionary with deterministic key iteration.
    Map(BTreeMap<String, Value>),
    /// Set: unique value collection keyed by canonical runtime value identity.
    Set(BTreeMap<String, Value>),
    /// Scope: a named block with its own environment. Bindings accessible via Scope.name.
    Scope {
        name: String,
        bindings: Rc<HashMap<String, Value>>,
        namespace: RuntimeNamespace,
        declaration_env: Rc<Env>,
    },
    /// RuleScope instance: pure scoped legal/calculation rules with captured inputs.
    RuleScopeInstance {
        name: String,
        bindings: Rc<HashMap<String, Value>>,
    },
    /// RuleScope instance declared in a qualified or inline namespace.
    NamespacedRuleScopeInstance {
        namespace: RuntimeNamespace,
        name: String,
        bindings: Rc<HashMap<String, Value>>,
        declaration_env: Option<Rc<Env>>,
    },
    /// Comptime type definition: describes a type to be generated at compile time.
    /// fields: vec of (field_name, type_name) for structs, or variant descriptions for enums.
    TypeDef {
        kind: String,
        fields: Vec<(String, String)>,
    },
}

const CHECKED_EXACT_OBSERVER_MEMO_ENTRY_LIMIT: usize = 2_048;
const CHECKED_EXACT_OBSERVER_MEMO_CANONICAL_BYTE_LIMIT: usize = 16 * 1024 * 1024;
const CHECKED_EXACT_OBSERVER_MEMO_SINGLE_VALUE_BYTE_LIMIT: usize = 1024 * 1024;
const CHECKED_MECHANISM_RULE_MEMO_ENTRY_LIMIT: usize = 16_384;
const CHECKED_MECHANISM_RULE_MEMO_CANONICAL_BYTE_LIMIT: usize = 64 * 1024 * 1024;

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub(crate) struct CheckedExactObserverMemoStats {
    pub(crate) hits: u64,
    pub(crate) misses: u64,
    pub(crate) inserts: u64,
    pub(crate) evictions: u64,
    pub(crate) entries: usize,
    pub(crate) retained_canonical_bytes: usize,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct CheckedExactObserverMemoKey {
    /// Complete producer-owned checked family identity. The Arc is shared by
    /// all entries for that family; no digest or runtime spelling substitutes
    /// for equality here.
    family: Arc<CheckedExactObserverRuleFamilyIdentity>,
    /// Complete, tagged, length-delimited structural encodings in canonical
    /// declaration argument order. This is the equality key, not a digest.
    ordered_arguments: Box<[u8]>,
}

#[derive(Debug, Clone)]
struct CheckedExactObserverMemoEntry {
    value: Value,
    dispatch_steps: usize,
    recency: u64,
    canonical_bytes: usize,
}

#[derive(Debug)]
struct CheckedExactObserverMemoState {
    analysis_program: AnalysisProgramId,
    families: BTreeMap<RuleDispatchKey, Arc<CheckedExactObserverRuleFamilyIdentity>>,
    entries: BTreeMap<CheckedExactObserverMemoKey, CheckedExactObserverMemoEntry>,
    recency: BTreeSet<(u64, CheckedExactObserverMemoKey)>,
    next_recency: u64,
    retained_canonical_bytes: usize,
    stats: CheckedExactObserverMemoStats,
    /// A retained entry records the cost of an uncached rule-family dispatch.
    /// Nested eligible calls are bypassed while producing that baseline, so a
    /// hit can charge the same exact-exploration step budget after restart.
    cold_dispatch_depth: usize,
}

/// One cold, producer-certified global rule dispatch retained only for the
/// lifetime of a checked mechanism endpoint. The event index is an immutable
/// anchor into that endpoint's append-only trace; entries are never evicted or
/// replaced while the trace is live.
#[derive(Debug, Clone)]
struct CheckedMechanismRuleMemoEntry {
    value: Value,
    cold_selection_event: usize,
    dispatch_steps: usize,
    canonical_bytes: usize,
}

#[derive(Debug)]
struct CheckedMechanismRuleMemoState {
    analysis_program: AnalysisProgramId,
    families: Arc<BTreeMap<RuleDispatchKey, Arc<CheckedExactObserverRuleFamilyIdentity>>>,
    entries: BTreeMap<CheckedExactObserverMemoKey, CheckedMechanismRuleMemoEntry>,
    retained_canonical_bytes: usize,
}

impl CheckedMechanismRuleMemoState {
    fn new(plan: CheckedMechanismRuleMemoPlan) -> Self {
        Self {
            analysis_program: plan.analysis_program,
            families: plan.families,
            entries: BTreeMap::new(),
            retained_canonical_bytes: 0,
        }
    }

    fn reset_endpoint(&mut self) {
        self.entries.clear();
        self.retained_canonical_bytes = 0;
    }

    fn lookup(&self, key: &CheckedExactObserverMemoKey) -> Option<(Value, usize, usize)> {
        self.entries.get(key).map(|entry| {
            (
                entry.value.clone(),
                entry.cold_selection_event,
                entry.dispatch_steps,
            )
        })
    }

    fn insert_if_absent(
        &mut self,
        key: CheckedExactObserverMemoKey,
        value: &Value,
        cold_selection_event: usize,
        dispatch_steps: usize,
        result_canonical_bytes: usize,
    ) {
        if self.entries.contains_key(&key) {
            return;
        }
        let canonical_bytes = key
            .ordered_arguments
            .len()
            .saturating_add(result_canonical_bytes);
        if self.entries.len() >= CHECKED_MECHANISM_RULE_MEMO_ENTRY_LIMIT
            || self
                .retained_canonical_bytes
                .saturating_add(canonical_bytes)
                > CHECKED_MECHANISM_RULE_MEMO_CANONICAL_BYTE_LIMIT
        {
            // A full memo becomes insertion-closed. Existing anchors remain
            // valid; later keys simply take the ordinary cold dispatch path.
            return;
        }
        self.retained_canonical_bytes = self
            .retained_canonical_bytes
            .saturating_add(canonical_bytes);
        self.entries.insert(
            key,
            CheckedMechanismRuleMemoEntry {
                value: value.clone(),
                cold_selection_event,
                dispatch_steps,
                canonical_bytes,
            },
        );
    }
}

impl CheckedExactObserverMemoState {
    fn new(plan: CheckedExactObserverMemoPlan) -> Self {
        Self {
            analysis_program: plan.analysis_program,
            families: plan.families,
            entries: BTreeMap::new(),
            recency: BTreeSet::new(),
            next_recency: 0,
            retained_canonical_bytes: 0,
            stats: CheckedExactObserverMemoStats::default(),
            cold_dispatch_depth: 0,
        }
    }

    fn next_recency(&mut self) -> u64 {
        if self.next_recency == u64::MAX {
            let keys = self
                .recency
                .iter()
                .map(|(_, key)| key.clone())
                .collect::<Vec<_>>();
            self.recency.clear();
            for (recency, key) in keys.into_iter().enumerate() {
                let recency = recency as u64;
                if let Some(entry) = self.entries.get_mut(&key) {
                    entry.recency = recency;
                }
                self.recency.insert((recency, key));
            }
            self.next_recency = self.entries.len() as u64;
        }
        let recency = self.next_recency;
        self.next_recency += 1;
        recency
    }

    fn lookup(&mut self, key: &CheckedExactObserverMemoKey) -> Option<(Value, usize)> {
        let Some(entry) = self.entries.get(key) else {
            self.stats.misses = self.stats.misses.saturating_add(1);
            return None;
        };
        let previous_recency = entry.recency;
        let value = entry.value.clone();
        let dispatch_steps = entry.dispatch_steps;
        self.recency.remove(&(previous_recency, key.clone()));
        let recency = self.next_recency();
        self.entries
            .get_mut(key)
            .expect("memo entry remains present while refreshing recency")
            .recency = recency;
        self.recency.insert((recency, key.clone()));
        self.stats.hits = self.stats.hits.saturating_add(1);
        Some((value, dispatch_steps))
    }

    fn evict_oldest(&mut self) -> bool {
        let Some((recency, key)) = self.recency.iter().next().cloned() else {
            return false;
        };
        self.recency.remove(&(recency, key.clone()));
        if let Some(entry) = self.entries.remove(&key) {
            self.retained_canonical_bytes = self
                .retained_canonical_bytes
                .saturating_sub(entry.canonical_bytes);
            self.stats.evictions = self.stats.evictions.saturating_add(1);
        }
        true
    }

    fn insert(
        &mut self,
        key: CheckedExactObserverMemoKey,
        value: Value,
        dispatch_steps: usize,
        result_canonical_bytes: usize,
    ) {
        let canonical_bytes = key
            .ordered_arguments
            .len()
            .saturating_add(result_canonical_bytes);
        if canonical_bytes > CHECKED_EXACT_OBSERVER_MEMO_CANONICAL_BYTE_LIMIT {
            return;
        }

        if let Some(previous) = self.entries.remove(&key) {
            self.recency.remove(&(previous.recency, key.clone()));
            self.retained_canonical_bytes = self
                .retained_canonical_bytes
                .saturating_sub(previous.canonical_bytes);
        }
        while self.entries.len() >= CHECKED_EXACT_OBSERVER_MEMO_ENTRY_LIMIT
            || self
                .retained_canonical_bytes
                .saturating_add(canonical_bytes)
                > CHECKED_EXACT_OBSERVER_MEMO_CANONICAL_BYTE_LIMIT
        {
            if !self.evict_oldest() {
                return;
            }
        }

        let recency = self.next_recency();
        self.retained_canonical_bytes = self
            .retained_canonical_bytes
            .saturating_add(canonical_bytes);
        self.entries.insert(
            key.clone(),
            CheckedExactObserverMemoEntry {
                value,
                dispatch_steps,
                recency,
                canonical_bytes,
            },
        );
        self.recency.insert((recency, key));
        self.stats.inserts = self.stats.inserts.saturating_add(1);
    }

    fn stats(&self) -> CheckedExactObserverMemoStats {
        CheckedExactObserverMemoStats {
            entries: self.entries.len(),
            retained_canonical_bytes: self.retained_canonical_bytes,
            ..self.stats
        }
    }
}

fn checked_exact_observer_memo_push_bytes(output: &mut Vec<u8>, bytes: &[u8]) -> Option<()> {
    if output.len().checked_add(bytes.len())? > CHECKED_EXACT_OBSERVER_MEMO_SINGLE_VALUE_BYTE_LIMIT
    {
        return None;
    }
    output.extend_from_slice(bytes);
    Some(())
}

fn checked_exact_observer_memo_push_len(output: &mut Vec<u8>, len: usize) -> Option<()> {
    let len = u64::try_from(len).ok()?;
    checked_exact_observer_memo_push_bytes(output, &len.to_le_bytes())
}

fn checked_exact_observer_memo_push_str(output: &mut Vec<u8>, value: &str) -> Option<()> {
    checked_exact_observer_memo_push_len(output, value.len())?;
    checked_exact_observer_memo_push_bytes(output, value.as_bytes())
}

/// Collision-free canonical representation of the immutable, first-order
/// runtime values admitted to checked observer memoization. Stateful and
/// callable values fail closed instead of acquiring an identity by display.
fn checked_exact_observer_memo_encode_value(value: &Value, output: &mut Vec<u8>) -> Option<()> {
    match value {
        Value::Int(value) => {
            checked_exact_observer_memo_push_bytes(output, &[0])?;
            checked_exact_observer_memo_push_bytes(output, &value.to_le_bytes())
        }
        Value::Float(value) => {
            checked_exact_observer_memo_push_bytes(output, &[1])?;
            checked_exact_observer_memo_push_bytes(output, &value.to_bits().to_le_bytes())
        }
        Value::Str(value) => {
            checked_exact_observer_memo_push_bytes(output, &[2])?;
            checked_exact_observer_memo_push_str(output, value)
        }
        Value::Char(value) => {
            checked_exact_observer_memo_push_bytes(output, &[3])?;
            checked_exact_observer_memo_push_bytes(output, &(*value as u32).to_le_bytes())
        }
        Value::Bool(value) => {
            checked_exact_observer_memo_push_bytes(output, &[4, u8::from(*value)])
        }
        Value::Unit => checked_exact_observer_memo_push_bytes(output, &[5]),
        Value::List(values) => {
            checked_exact_observer_memo_push_bytes(output, &[6])?;
            checked_exact_observer_memo_push_len(output, values.len())?;
            for value in values {
                checked_exact_observer_memo_encode_value(value, output)?;
            }
            Some(())
        }
        Value::Tuple(values) => {
            checked_exact_observer_memo_push_bytes(output, &[7])?;
            checked_exact_observer_memo_push_len(output, values.len())?;
            for value in values {
                checked_exact_observer_memo_encode_value(value, output)?;
            }
            Some(())
        }
        Value::Constructor(name, values) => {
            checked_exact_observer_memo_push_bytes(output, &[8])?;
            checked_exact_observer_memo_push_str(output, name)?;
            checked_exact_observer_memo_push_len(output, values.len())?;
            for value in values.iter() {
                checked_exact_observer_memo_encode_value(value, output)?;
            }
            Some(())
        }
        Value::NamedConstructor(name, fields) => {
            checked_exact_observer_memo_push_bytes(output, &[9])?;
            checked_exact_observer_memo_push_str(output, name)?;
            checked_exact_observer_memo_push_len(output, fields.len())?;
            for (field, value) in fields.iter() {
                checked_exact_observer_memo_push_str(output, field)?;
                checked_exact_observer_memo_encode_value(value, output)?;
            }
            Some(())
        }
        Value::NamespacedConstructor {
            namespace,
            name,
            arguments,
            ..
        } => {
            checked_exact_observer_memo_push_bytes(output, &[12])?;
            checked_exact_observer_memo_push_str(output, &namespace.semantic_key)?;
            checked_exact_observer_memo_push_str(output, name)?;
            checked_exact_observer_memo_push_len(output, arguments.len())?;
            for value in arguments.iter() {
                checked_exact_observer_memo_encode_value(value, output)?;
            }
            Some(())
        }
        Value::NamespacedNamedConstructor {
            namespace,
            name,
            fields,
            ..
        } => {
            checked_exact_observer_memo_push_bytes(output, &[13])?;
            checked_exact_observer_memo_push_str(output, &namespace.semantic_key)?;
            checked_exact_observer_memo_push_str(output, name)?;
            checked_exact_observer_memo_push_len(output, fields.len())?;
            for (field, value) in fields.iter() {
                checked_exact_observer_memo_push_str(output, field)?;
                checked_exact_observer_memo_encode_value(value, output)?;
            }
            Some(())
        }
        Value::Map(entries) => {
            checked_exact_observer_memo_push_bytes(output, &[10])?;
            checked_exact_observer_memo_push_len(output, entries.len())?;
            let mut encoded_entries = Vec::with_capacity(entries.len());
            for (stored_key, stored_value) in entries {
                let mut encoded = Vec::new();
                if let Some((key, value)) = runtime_map_entry_parts(stored_key, stored_value) {
                    checked_exact_observer_memo_encode_value(key, &mut encoded)?;
                    checked_exact_observer_memo_encode_value(value, &mut encoded)?;
                } else {
                    checked_exact_observer_memo_encode_value(
                        &Value::Str(stored_key.clone()),
                        &mut encoded,
                    )?;
                    checked_exact_observer_memo_encode_value(stored_value, &mut encoded)?;
                }
                encoded_entries.push(encoded);
            }
            encoded_entries.sort();
            for encoded in encoded_entries {
                checked_exact_observer_memo_push_len(output, encoded.len())?;
                checked_exact_observer_memo_push_bytes(output, &encoded)?;
            }
            Some(())
        }
        Value::Set(entries) => {
            checked_exact_observer_memo_push_bytes(output, &[11])?;
            checked_exact_observer_memo_push_len(output, entries.len())?;
            let mut encoded_values = Vec::with_capacity(entries.len());
            for value in entries.values() {
                let mut encoded = Vec::new();
                checked_exact_observer_memo_encode_value(value, &mut encoded)?;
                encoded_values.push(encoded);
            }
            encoded_values.sort();
            for encoded in encoded_values {
                checked_exact_observer_memo_push_len(output, encoded.len())?;
                checked_exact_observer_memo_push_bytes(output, &encoded)?;
            }
            Some(())
        }
        Value::Closure { .. }
        | Value::Builtin(_)
        | Value::NamespacedBuiltin { .. }
        | Value::Actor { .. }
        | Value::Stream(_)
        | Value::Subject(_)
        | Value::Scope { .. }
        | Value::RuleScopeInstance { .. }
        | Value::NamespacedRuleScopeInstance { .. }
        | Value::TypeDef { .. } => None,
    }
}

fn checked_exact_observer_memo_encode_arguments(arguments: &[Value]) -> Option<Box<[u8]>> {
    let mut output = Vec::new();
    checked_exact_observer_memo_push_bytes(&mut output, &[1])?;
    checked_exact_observer_memo_push_len(&mut output, arguments.len())?;
    for argument in arguments {
        checked_exact_observer_memo_encode_value(argument, &mut output)?;
    }
    Some(output.into_boxed_slice())
}

const RUNTIME_COLLECTION_KEY_PREFIX: &str = "__futuruna_value_digest_v2__";
const RUNTIME_MAP_ENTRY_MARKER: &str = "__futuruna_map_entry_v2__";

#[cfg(test)]
thread_local! {
    static FORCED_RUNTIME_COLLECTION_SEMANTIC_KEY: RefCell<Option<String>> =
        const { RefCell::new(None) };
}

#[cfg(test)]
struct ForcedRuntimeCollectionSemanticKeyGuard {
    previous: Option<String>,
}

#[cfg(test)]
impl Drop for ForcedRuntimeCollectionSemanticKeyGuard {
    fn drop(&mut self) {
        FORCED_RUNTIME_COLLECTION_SEMANTIC_KEY.with(|slot| {
            slot.replace(self.previous.take());
        });
    }
}

#[cfg(test)]
fn with_forced_runtime_collection_semantic_key<R>(
    semantic_key: &str,
    operation: impl FnOnce() -> R,
) -> R {
    let previous = FORCED_RUNTIME_COLLECTION_SEMANTIC_KEY
        .with(|slot| slot.replace(Some(semantic_key.to_string())));
    let _guard = ForcedRuntimeCollectionSemanticKeyGuard { previous };
    operation()
}

fn runtime_hash_len(hasher: &mut Sha256, len: usize) {
    hasher.update(u64::try_from(len).unwrap_or(u64::MAX).to_le_bytes());
}

fn runtime_hash_str(hasher: &mut Sha256, value: &str) {
    runtime_hash_len(hasher, value.len());
    hasher.update(value.as_bytes());
}

fn runtime_accumulate_unordered_digest(sum: &mut [u8; 32], xor: &mut [u8; 32], digest: &[u8; 32]) {
    let mut carry = 0_u16;
    for index in 0..digest.len() {
        xor[index] ^= digest[index];
        let total = u16::from(sum[index]) + u16::from(digest[index]) + carry;
        sum[index] = total as u8;
        carry = total >> 8;
    }
}

fn runtime_finish_unordered_digest(hasher: &mut Sha256, sum: [u8; 32], xor: [u8; 32]) {
    hasher.update(sum);
    hasher.update(xor);
}

fn runtime_hash_sequence(hasher: &mut Sha256, tag: u8, values: &[Value]) {
    hasher.update([tag]);
    runtime_hash_len(hasher, values.len());
    for value in values {
        runtime_hash_value(hasher, value);
    }
}

fn runtime_hash_bindings(hasher: &mut Sha256, bindings: &HashMap<String, Value>) {
    runtime_hash_len(hasher, bindings.len());
    let mut sum = [0_u8; 32];
    let mut xor = [0_u8; 32];
    for (name, value) in bindings {
        let mut binding_hasher = Sha256::new();
        binding_hasher.update(b"futuruna.runtime-binding.v2");
        runtime_hash_str(&mut binding_hasher, name);
        runtime_hash_value(&mut binding_hasher, value);
        let digest: [u8; 32] = binding_hasher.finalize().into();
        runtime_accumulate_unordered_digest(&mut sum, &mut xor, &digest);
    }
    runtime_finish_unordered_digest(hasher, sum, xor);
}

fn runtime_hash_value(hasher: &mut Sha256, value: &Value) {
    match value {
        Value::Int(value) => {
            hasher.update([0]);
            hasher.update(value.to_le_bytes());
        }
        Value::Float(value) => {
            hasher.update([1]);
            // Futuruna's current runtime Float equality is epsilon based and
            // therefore cannot be partitioned into exact hash buckets. Keep
            // every Float in one bucket and let the retained witness decide.
            let _ = value;
        }
        Value::Str(value) => {
            hasher.update([2]);
            runtime_hash_str(hasher, value);
        }
        Value::Char(value) => {
            hasher.update([3]);
            hasher.update((*value as u32).to_le_bytes());
        }
        Value::Bool(value) => hasher.update([4, u8::from(*value)]),
        Value::Unit => hasher.update([5]),
        Value::List(values) => runtime_hash_sequence(hasher, 6, values),
        Value::Tuple(values) => runtime_hash_sequence(hasher, 7, values),
        Value::Constructor(name, values) => {
            hasher.update([8]);
            runtime_hash_str(hasher, name);
            runtime_hash_len(hasher, values.len());
            for value in values.iter() {
                runtime_hash_value(hasher, value);
            }
        }
        Value::NamedConstructor(name, fields) => {
            hasher.update([9]);
            runtime_hash_str(hasher, name);
            runtime_hash_len(hasher, fields.len());
            for (field, value) in fields.iter() {
                runtime_hash_str(hasher, field);
                runtime_hash_value(hasher, value);
            }
        }
        Value::Map(entries) => {
            hasher.update([10]);
            runtime_hash_len(hasher, entries.len());
            let mut sum = [0_u8; 32];
            let mut xor = [0_u8; 32];
            for (stored_key, stored_value) in entries {
                let mut entry_hasher = Sha256::new();
                entry_hasher.update(b"futuruna.runtime-map-entry.v2");
                if let Some((key, value)) = runtime_map_entry_parts(stored_key, stored_value) {
                    runtime_hash_value(&mut entry_hasher, key);
                    runtime_hash_value(&mut entry_hasher, value);
                } else {
                    runtime_hash_value(&mut entry_hasher, &Value::Str(stored_key.clone()));
                    runtime_hash_value(&mut entry_hasher, stored_value);
                }
                let digest: [u8; 32] = entry_hasher.finalize().into();
                runtime_accumulate_unordered_digest(&mut sum, &mut xor, &digest);
            }
            runtime_finish_unordered_digest(hasher, sum, xor);
        }
        Value::Set(entries) => {
            hasher.update([11]);
            runtime_hash_len(hasher, entries.len());
            let mut sum = [0_u8; 32];
            let mut xor = [0_u8; 32];
            for value in entries.values() {
                let digest = runtime_value_structural_digest(value);
                runtime_accumulate_unordered_digest(&mut sum, &mut xor, &digest);
            }
            runtime_finish_unordered_digest(hasher, sum, xor);
        }
        Value::NamespacedConstructor {
            namespace,
            name,
            arguments,
            ..
        } => {
            hasher.update([12]);
            runtime_hash_str(hasher, namespace.semantic_identity());
            runtime_hash_str(hasher, name);
            runtime_hash_len(hasher, arguments.len());
            for value in arguments.iter() {
                runtime_hash_value(hasher, value);
            }
        }
        Value::NamespacedNamedConstructor {
            namespace,
            name,
            fields,
            ..
        } => {
            hasher.update([13]);
            runtime_hash_str(hasher, namespace.semantic_identity());
            runtime_hash_str(hasher, name);
            runtime_hash_len(hasher, fields.len());
            for (field, value) in fields.iter() {
                runtime_hash_str(hasher, field);
                runtime_hash_value(hasher, value);
            }
        }
        Value::Builtin(name) => {
            hasher.update([14]);
            runtime_hash_str(hasher, name);
        }
        Value::NamespacedBuiltin {
            namespace, name, ..
        } => {
            hasher.update([15]);
            runtime_hash_str(hasher, namespace.semantic_identity());
            runtime_hash_str(hasher, name);
        }
        Value::Closure {
            name,
            params,
            body,
            env,
        } => {
            hasher.update([16]);
            runtime_hash_str(
                hasher,
                env.runtime_namespace
                    .as_ref()
                    .map(RuntimeNamespace::semantic_identity)
                    .unwrap_or("legacy"),
            );
            runtime_hash_str(hasher, name.as_deref().unwrap_or(""));
            runtime_hash_len(hasher, params.len());
            for parameter in params {
                runtime_hash_str(hasher, parameter);
            }
            runtime_hash_str(hasher, &format!("{body:?}"));
        }
        Value::Actor {
            actor_name,
            state,
            state_param,
            env,
            ..
        } => {
            hasher.update([17]);
            runtime_hash_str(
                hasher,
                env.runtime_namespace
                    .as_ref()
                    .map(RuntimeNamespace::semantic_identity)
                    .unwrap_or("legacy"),
            );
            runtime_hash_str(hasher, actor_name);
            runtime_hash_str(hasher, state_param);
            runtime_hash_value(hasher, state);
        }
        Value::Stream(values) => runtime_hash_sequence(hasher, 18, values),
        Value::Subject(values) => runtime_hash_sequence(hasher, 19, values),
        Value::Scope {
            namespace, name, ..
        } => {
            hasher.update([20]);
            runtime_hash_str(hasher, namespace.semantic_identity());
            runtime_hash_str(hasher, name);
        }
        Value::RuleScopeInstance { name, bindings } => {
            hasher.update([21]);
            runtime_hash_str(hasher, "root");
            runtime_hash_str(hasher, name);
            runtime_hash_bindings(hasher, bindings);
        }
        Value::NamespacedRuleScopeInstance {
            namespace,
            name,
            bindings,
            ..
        } => {
            hasher.update([22]);
            runtime_hash_str(hasher, namespace.semantic_identity());
            runtime_hash_str(hasher, name);
            runtime_hash_bindings(hasher, bindings);
        }
        Value::TypeDef { kind, fields } => {
            hasher.update([23]);
            runtime_hash_str(hasher, kind);
            runtime_hash_len(hasher, fields.len());
            for (name, ty) in fields {
                runtime_hash_str(hasher, name);
                runtime_hash_str(hasher, ty);
            }
        }
    }
}

fn runtime_value_structural_digest(value: &Value) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.runtime-collection-value.v2");
    runtime_hash_value(&mut hasher, value);
    hasher.finalize().into()
}

pub(crate) fn runtime_value_semantic_key(value: &Value) -> String {
    #[cfg(test)]
    if let Some(forced) = FORCED_RUNTIME_COLLECTION_SEMANTIC_KEY.with(|slot| slot.borrow().clone())
    {
        return forced;
    }

    let digest = runtime_value_structural_digest(value);
    let mut key = String::with_capacity(65);
    key.push('v');
    for byte in digest {
        use std::fmt::Write as _;
        let _ = write!(key, "{byte:02x}");
    }
    key
}

fn runtime_values_semantically_equal(left: &Value, right: &Value) -> bool {
    match (left, right) {
        (Value::Int(left), Value::Int(right)) => left == right,
        (Value::Float(left), Value::Float(right)) => (left - right).abs() < f64::EPSILON,
        (Value::Str(left), Value::Str(right)) => left == right,
        (Value::Char(left), Value::Char(right)) => left == right,
        (Value::Bool(left), Value::Bool(right)) => left == right,
        (Value::Unit, Value::Unit) => true,
        (Value::List(left), Value::List(right))
        | (Value::Tuple(left), Value::Tuple(right))
        | (Value::Stream(left), Value::Stream(right))
        | (Value::Subject(left), Value::Subject(right)) => {
            left.len() == right.len()
                && left
                    .iter()
                    .zip(right)
                    .all(|(left, right)| runtime_values_semantically_equal(left, right))
        }
        (Value::Constructor(left_name, left), Value::Constructor(right_name, right)) => {
            left_name == right_name
                && left.len() == right.len()
                && left
                    .iter()
                    .zip(right.iter())
                    .all(|(left, right)| runtime_values_semantically_equal(left, right))
        }
        (Value::NamedConstructor(left_name, left), Value::NamedConstructor(right_name, right)) => {
            left_name == right_name
                && left.len() == right.len()
                && left
                    .iter()
                    .zip(right.iter())
                    .all(|((left_name, left), (right_name, right))| {
                        left_name == right_name && runtime_values_semantically_equal(left, right)
                    })
        }
        (
            Value::NamespacedConstructor {
                namespace: left_namespace,
                name: left_name,
                arguments: left,
                ..
            },
            Value::NamespacedConstructor {
                namespace: right_namespace,
                name: right_name,
                arguments: right,
                ..
            },
        ) => {
            left_namespace.same_instance(right_namespace)
                && left_name == right_name
                && left.len() == right.len()
                && left
                    .iter()
                    .zip(right.iter())
                    .all(|(left, right)| runtime_values_semantically_equal(left, right))
        }
        (
            Value::NamespacedNamedConstructor {
                namespace: left_namespace,
                name: left_name,
                fields: left,
                ..
            },
            Value::NamespacedNamedConstructor {
                namespace: right_namespace,
                name: right_name,
                fields: right,
                ..
            },
        ) => {
            left_namespace.same_instance(right_namespace)
                && left_name == right_name
                && left.len() == right.len()
                && left
                    .iter()
                    .zip(right.iter())
                    .all(|((left_name, left), (right_name, right))| {
                        left_name == right_name && runtime_values_semantically_equal(left, right)
                    })
        }
        (Value::Map(left), Value::Map(right)) => {
            left.len() == right.len()
                && left.iter().all(|(stored_key, stored_value)| {
                    if let Some((key, value)) = runtime_map_entry_parts(stored_key, stored_value) {
                        runtime_map_get_value(right, key)
                            .is_some_and(|right| runtime_values_semantically_equal(value, right))
                    } else {
                        runtime_map_get_value(right, &Value::Str(stored_key.clone())).is_some_and(
                            |right| runtime_values_semantically_equal(stored_value, right),
                        )
                    }
                })
        }
        (Value::Set(left), Value::Set(right)) => {
            left.len() == right.len()
                && left
                    .values()
                    .all(|value| runtime_set_find_storage_key(right, value).is_some())
        }
        (Value::Builtin(left), Value::Builtin(right)) => left == right,
        (
            Value::NamespacedBuiltin {
                namespace: left_namespace,
                name: left,
                ..
            },
            Value::NamespacedBuiltin {
                namespace: right_namespace,
                name: right,
                ..
            },
        ) => left_namespace.same_instance(right_namespace) && left == right,
        (
            Value::Scope {
                namespace: left_namespace,
                name: left,
                ..
            },
            Value::Scope {
                namespace: right_namespace,
                name: right,
                ..
            },
        ) => left_namespace.same_instance(right_namespace) && left == right,
        (
            Value::RuleScopeInstance {
                name: left_name,
                bindings: left,
            },
            Value::RuleScopeInstance {
                name: right_name,
                bindings: right,
            },
        ) => {
            left_name == right_name
                && left.len() == right.len()
                && left.iter().all(|(name, left)| {
                    right
                        .get(name)
                        .is_some_and(|right| runtime_values_semantically_equal(left, right))
                })
        }
        (
            Value::NamespacedRuleScopeInstance {
                namespace: left_namespace,
                name: left_name,
                bindings: left,
                ..
            },
            Value::NamespacedRuleScopeInstance {
                namespace: right_namespace,
                name: right_name,
                bindings: right,
                ..
            },
        ) => {
            left_namespace.same_instance(right_namespace)
                && left_name == right_name
                && left.len() == right.len()
                && left.iter().all(|(name, left)| {
                    right
                        .get(name)
                        .is_some_and(|right| runtime_values_semantically_equal(left, right))
                })
        }
        (
            Value::TypeDef {
                kind: left_kind,
                fields: left_fields,
            },
            Value::TypeDef {
                kind: right_kind,
                fields: right_fields,
            },
        ) => left_kind == right_kind && left_fields == right_fields,
        _ => false,
    }
}

fn runtime_collection_bucket_prefix(value: &Value) -> String {
    format!(
        "{}{}:",
        RUNTIME_COLLECTION_KEY_PREFIX,
        runtime_value_semantic_key(value)
    )
}

fn runtime_collection_new_storage_key(entries: &BTreeMap<String, Value>, value: &Value) -> String {
    let prefix = runtime_collection_bucket_prefix(value);
    for ordinal in 0..=entries.len() {
        let key = format!("{prefix}{ordinal:016x}");
        if !entries.contains_key(&key) {
            return key;
        }
    }
    unreachable!("entries + 1 candidate collision slots always contain a free key")
}

fn runtime_map_entry(key: Value, value: Value) -> Value {
    Value::Tuple(vec![
        Value::Str(RUNTIME_MAP_ENTRY_MARKER.to_string()),
        key,
        value,
    ])
}

fn runtime_map_entry_parts<'a>(
    stored_key: &str,
    stored_value: &'a Value,
) -> Option<(&'a Value, &'a Value)> {
    if !stored_key.starts_with(RUNTIME_COLLECTION_KEY_PREFIX) {
        return None;
    }
    let Value::Tuple(parts) = stored_value else {
        return None;
    };
    match parts.as_slice() {
        [Value::Str(marker), key, value] if marker == RUNTIME_MAP_ENTRY_MARKER => {
            Some((key, value))
        }
        _ => None,
    }
}

fn runtime_map_find_storage_key<'a>(
    entries: &'a BTreeMap<String, Value>,
    key: &Value,
) -> Option<&'a str> {
    let prefix = runtime_collection_bucket_prefix(key);
    let bucket_match = entries
        .range(prefix.clone()..)
        .take_while(|(stored_key, _)| stored_key.starts_with(&prefix))
        .find_map(|(stored_key, stored_value)| {
            runtime_map_entry_parts(stored_key, stored_value)
                .filter(|(candidate, _)| runtime_values_semantically_equal(candidate, key))
                .map(|_| stored_key.as_str())
        });
    bucket_match.or_else(|| {
        let Value::Str(candidate) = key else {
            return None;
        };
        entries
            .get_key_value(candidate)
            .and_then(|(stored_key, stored_value)| {
                runtime_map_entry_parts(stored_key, stored_value)
                    .is_none()
                    .then_some(stored_key.as_str())
            })
    })
}

pub(crate) fn runtime_map_insert_value(
    entries: &mut BTreeMap<String, Value>,
    key: Value,
    value: Value,
) -> bool {
    let mut inserted = true;
    while let Some(existing) = runtime_map_find_storage_key(entries, &key).map(str::to_string) {
        inserted = false;
        entries.remove(&existing);
    }
    let storage_key = runtime_collection_new_storage_key(entries, &key);
    entries.insert(storage_key, runtime_map_entry(key, value));
    inserted
}

fn runtime_map_get_value<'a>(
    entries: &'a BTreeMap<String, Value>,
    key: &Value,
) -> Option<&'a Value> {
    let stored_key = runtime_map_find_storage_key(entries, key)?;
    let stored_value = entries.get(stored_key)?;
    runtime_map_entry_parts(stored_key, stored_value)
        .map(|(_, value)| value)
        .or(Some(stored_value))
}

fn runtime_map_remove_value(entries: &mut BTreeMap<String, Value>, key: &Value) -> Option<Value> {
    let mut removed = None;
    while let Some(stored_key) = runtime_map_find_storage_key(entries, key).map(str::to_string) {
        let Some(stored_value) = entries.remove(&stored_key) else {
            continue;
        };
        if removed.is_none() {
            if let Value::Tuple(mut parts) = stored_value {
                if stored_key.starts_with(RUNTIME_COLLECTION_KEY_PREFIX)
                    && matches!(parts.first(), Some(Value::Str(marker)) if marker == RUNTIME_MAP_ENTRY_MARKER)
                    && parts.len() == 3
                {
                    removed = Some(parts.remove(2));
                } else {
                    removed = Some(Value::Tuple(parts));
                }
            } else {
                removed = Some(stored_value);
            }
        }
    }
    removed
}

pub(crate) fn runtime_map_string_entry<'a>(
    stored_key: &'a str,
    stored_value: &'a Value,
) -> Option<(&'a str, &'a Value)> {
    if let Some((Value::Str(key), value)) = runtime_map_entry_parts(stored_key, stored_value) {
        Some((key, value))
    } else if runtime_map_entry_parts(stored_key, stored_value).is_none() {
        Some((stored_key, stored_value))
    } else {
        None
    }
}

fn runtime_set_find_storage_key<'a>(
    entries: &'a BTreeMap<String, Value>,
    value: &Value,
) -> Option<&'a str> {
    let prefix = runtime_collection_bucket_prefix(value);
    entries
        .range(prefix.clone()..)
        .take_while(|(stored_key, _)| stored_key.starts_with(&prefix))
        .find_map(|(stored_key, candidate)| {
            runtime_values_semantically_equal(candidate, value).then_some(stored_key.as_str())
        })
        .or_else(|| {
            entries.iter().find_map(|(stored_key, candidate)| {
                runtime_values_semantically_equal(candidate, value).then_some(stored_key.as_str())
            })
        })
}

pub(crate) fn runtime_set_insert_value(
    entries: &mut BTreeMap<String, Value>,
    value: Value,
) -> bool {
    let mut inserted = true;
    while let Some(existing) = runtime_set_find_storage_key(entries, &value).map(str::to_string) {
        inserted = false;
        entries.remove(&existing);
    }
    let key = runtime_collection_new_storage_key(entries, &value);
    entries.insert(key, value);
    inserted
}

fn runtime_set_remove_value(entries: &mut BTreeMap<String, Value>, value: &Value) -> Option<Value> {
    let mut removed = None;
    while let Some(key) = runtime_set_find_storage_key(entries, value).map(str::to_string) {
        let candidate = entries.remove(&key);
        if removed.is_none() {
            removed = candidate;
        }
    }
    removed
}

fn checked_exact_observer_memo_value_size(value: &Value) -> Option<usize> {
    let mut output = Vec::new();
    checked_exact_observer_memo_encode_value(value, &mut output)?;
    Some(output.len())
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Value::Int(n) => write!(f, "{}", n),
            Value::Float(v) => write!(f, "{}", v),
            Value::Str(s) => write!(f, "{}", s),
            Value::Char(c) => write!(f, "{}", c),
            Value::Bool(b) => write!(f, "{}", if *b { "true" } else { "false" }),
            Value::Unit => write!(f, "()"),
            Value::List(elems) => {
                write!(f, "[")?;
                for (i, e) in elems.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", e)?;
                }
                write!(f, "]")
            }
            Value::Tuple(elems) => {
                write!(f, "(")?;
                for (i, e) in elems.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", e)?;
                }
                write!(f, ")")
            }
            Value::Constructor(name, args) if args.is_empty() => {
                if name == "Nil" {
                    write!(f, "[]") // Empty list
                } else {
                    write!(f, "{}", name)
                }
            }
            Value::Constructor(name, args) if name == "Cons" && args.len() == 2 => {
                // Display linked lists as [1, 2, 3] instead of Cons(1, Cons(2, Nil))
                let items = list_to_vec(self);
                write!(f, "[")?;
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", item)?;
                }
                write!(f, "]")
            }
            Value::Constructor(name, args) => {
                write!(f, "{}(", name)?;
                for (i, a) in args.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", a)?;
                }
                write!(f, ")")
            }
            Value::NamedConstructor(name, fields) if fields.is_empty() => {
                write!(f, "{}", name)
            }
            Value::NamedConstructor(name, fields) => {
                write!(f, "{}(", name)?;
                for (i, (fname, val)) in fields.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}: {}", fname, val)?;
                }
                write!(f, ")")
            }
            Value::NamespacedConstructor {
                name, arguments, ..
            } if arguments.is_empty() => write!(f, "{}", name),
            Value::NamespacedConstructor {
                name, arguments, ..
            } => {
                write!(f, "{}(", name)?;
                for (index, argument) in arguments.iter().enumerate() {
                    if index > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", argument)?;
                }
                write!(f, ")")
            }
            Value::NamespacedNamedConstructor { name, fields, .. } if fields.is_empty() => {
                write!(f, "{}", name)
            }
            Value::NamespacedNamedConstructor { name, fields, .. } => {
                write!(f, "{}(", name)?;
                for (index, (field, value)) in fields.iter().enumerate() {
                    if index > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}: {}", field, value)?;
                }
                write!(f, ")")
            }
            Value::Closure { name, params, .. } => {
                let n = name.as_deref().unwrap_or("lambda");
                write!(f, "<fn {}({})>", n, params.join(", "))
            }
            Value::Builtin(name) => write!(f, "<builtin:{}>", name),
            Value::NamespacedBuiltin { name, .. } => write!(f, "<builtin:{}>", name),
            Value::Actor {
                actor_name, state, ..
            } => write!(f, "<actor:{}({})>", actor_name, state),
            Value::Stream(items) => {
                write!(f, "~[")?;
                for (i, v) in items.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", v)?;
                }
                write!(f, "]")
            }
            Value::Subject(items) => {
                write!(f, "~subject[")?;
                for (i, v) in items.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", v)?;
                }
                write!(f, "]")
            }
            Value::Map(entries) => {
                write!(f, "{{")?;
                for (i, (stored_key, stored_value)) in entries.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    if let Some((key, value)) = runtime_map_entry_parts(stored_key, stored_value) {
                        write!(f, "{}: {}", key, value)?;
                    } else {
                        write!(f, "{}: {}", stored_key, stored_value)?;
                    }
                }
                write!(f, "}}")
            }
            Value::Set(items) => {
                write!(f, "{{")?;
                for (i, (_, v)) in items.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", v)?;
                }
                write!(f, "}}")
            }
            Value::Scope { name, .. } => write!(f, "<scope:{}>", name),
            Value::RuleScopeInstance { name, .. } => write!(f, "<rulescope:{}>", name),
            Value::NamespacedRuleScopeInstance { name, .. } => {
                write!(f, "<rulescope:{}>", name)
            }
            Value::TypeDef { kind, fields } => {
                write!(f, "<typedef:{} {{", kind)?;
                for (i, (n, t)) in fields.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}: {}", n, t)?;
                }
                write!(f, "}}>")
            }
        }
    }
}

#[derive(Debug, Clone)]
pub struct Env {
    /// Bindings are immutable snapshots shared by cloned environments. Mutation
    /// uses copy-on-write, so child calls do not recursively clone global values.
    pub bindings: Rc<HashMap<String, Value>>,
    /// Rc parent: child creation is O(1) refcount bump, not O(n) deep clone.
    /// This is the critical optimization for closure-heavy code (map/filter/foldl).
    pub parent: Option<Rc<Env>>,
    /// Runtime callable/type provenance is independent of lexical bindings.
    /// `None` is accepted only for legacy standalone environments and is
    /// interpreted as the receiving Interpreter's root namespace.
    runtime_namespace: Option<RuntimeNamespace>,
}

impl Env {
    pub fn new() -> Self {
        Env {
            bindings: Rc::new(HashMap::new()),
            parent: None,
            runtime_namespace: None,
        }
    }

    pub fn child(&self) -> Self {
        Env {
            bindings: Rc::new(HashMap::new()),
            parent: Some(Rc::new(self.clone())),
            runtime_namespace: self.runtime_namespace.clone(),
        }
    }

    /// Cheap child: shares parent via Rc (no clone of parent chain).
    /// Use this in hot paths (map/filter/foldl closure application).
    pub fn child_rc(self_rc: &Rc<Env>) -> Self {
        Env {
            bindings: Rc::new(HashMap::new()),
            parent: Some(Rc::clone(self_rc)),
            runtime_namespace: self_rc.runtime_namespace.clone(),
        }
    }

    pub fn get(&self, name: &str) -> Option<&Value> {
        self.bindings
            .get(name)
            .or_else(|| self.parent.as_ref().and_then(|p| p.get(name)))
    }

    pub fn set(&mut self, name: String, val: Value) {
        Rc::make_mut(&mut self.bindings).insert(name, val);
    }

    /// Iterate over all bindings (current scope + parents)
    pub fn iter_bindings(&self) -> Vec<(String, Value)> {
        let mut result = Vec::new();
        let mut seen = std::collections::HashSet::new();
        let mut current = Some(self);
        while let Some(env) = current {
            for (k, v) in env.bindings.iter() {
                if seen.insert(k.clone()) {
                    result.push((k.clone(), v.clone()));
                }
            }
            current = env.parent.as_ref().map(|p| p.as_ref());
        }
        result
    }

    pub fn remove(&mut self, name: &str) {
        if self.bindings.contains_key(name) {
            Rc::make_mut(&mut self.bindings).remove(name);
        }
    }

    fn set_runtime_namespace(&mut self, namespace: RuntimeNamespace) {
        self.runtime_namespace = Some(namespace);
    }

    fn with_runtime_namespace(mut self, namespace: RuntimeNamespace) -> Self {
        self.set_runtime_namespace(namespace);
        self
    }
}

fn comptime_typedef_to_type_decl(name: &str, kind: &str, fields: &[(String, String)]) -> TypeDecl {
    fn parse_ty(s: &str) -> Ty {
        match s {
            "Int" => Ty::Name("Int".into()),
            "Float" => Ty::Name("Float".into()),
            "String" => Ty::Name("String".into()),
            "Bool" => Ty::Name("Bool".into()),
            "Char" => Ty::Name("Char".into()),
            other => Ty::Name(other.into()),
        }
    }

    match kind {
        "struct" => {
            let variant_fields: Vec<Field> = fields
                .iter()
                .map(|(fname, fty)| Field {
                    name: fname.clone(),
                    ty: parse_ty(fty),
                })
                .collect();
            let variant = Variant {
                name: name.to_string(),
                fields: variant_fields,
                positional: false,
                from_type: None,
            };
            TypeDecl::ADT {
                name: name.to_string(),
                params: vec![],
                variants: vec![variant],
                methods: vec![],
                except_from: None,
            }
        }
        "enum" => {
            let variants: Vec<Variant> = fields
                .iter()
                .map(|(vname, field_str)| {
                    let variant_fields = if field_str.is_empty() {
                        vec![]
                    } else {
                        field_str
                            .split(',')
                            .filter_map(|part| {
                                let parts: Vec<&str> = part.trim().splitn(2, ':').collect();
                                if parts.len() == 2 {
                                    Some(Field {
                                        name: parts[0].trim().to_string(),
                                        ty: parse_ty(parts[1].trim()),
                                    })
                                } else {
                                    None
                                }
                            })
                            .collect()
                    };
                    Variant {
                        name: vname.clone(),
                        fields: variant_fields,
                        positional: false,
                        from_type: None,
                    }
                })
                .collect();
            TypeDecl::ADT {
                name: name.to_string(),
                params: vec![],
                variants,
                methods: vec![],
                except_from: None,
            }
        }
        _ => TypeDecl::ADT {
            name: name.to_string(),
            params: vec![],
            variants: vec![Variant {
                name: name.to_string(),
                fields: vec![],
                positional: false,
                from_type: None,
            }],
            methods: vec![],
            except_from: None,
        },
    }
}

