#[derive(Debug, Clone)]
pub struct FnDef {
    pub params: Vec<String>,
    pub body: Expr,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct RuntimeConstructorSignature {
    parent: String,
    positional: bool,
    fields: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RuleMissFallback {
    PredicateFalse,
    EmptyValue,
}

/// One runtime declaration namespace. Registry lookup walks `parent`, while
/// registration always mutates only this node. This is the semantic boundary
/// which qualified imports and inline modules were previously missing.
#[derive(Clone)]
#[doc(hidden)]
pub struct RuntimeNamespace {
    semantic_key: Rc<str>,
    state: Rc<RefCell<RuntimeNamespaceState>>,
    declaration_env: Rc<RefCell<Weak<Env>>>,
}

impl std::fmt::Debug for RuntimeNamespace {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("RuntimeNamespace")
            .field("semantic_key", &self.semantic_key)
            .finish_non_exhaustive()
    }
}

impl RuntimeNamespace {
    fn root() -> Self {
        Self {
            semantic_key: Rc::from("root"),
            state: Rc::new(RefCell::new(RuntimeNamespaceState::root())),
            declaration_env: Rc::new(RefCell::new(Weak::new())),
        }
    }

    fn child(&self, semantic_component: &str) -> Self {
        Self {
            semantic_key: Rc::from(format!("{}/{}", self.semantic_key, semantic_component)),
            state: Rc::new(RefCell::new(RuntimeNamespaceState::child(self.clone()))),
            declaration_env: Rc::new(RefCell::new(Weak::new())),
        }
    }

    /// Create a nominal child whose registry fallback is deliberately
    /// independent of the namespace that names this module instance.
    /// Qualified source files are not lexically nested in their importer, but
    /// their nominal identity still includes the import edge.
    fn isolated_child(&self, semantic_component: &str, registry_parent: RuntimeNamespace) -> Self {
        Self {
            semantic_key: Rc::from(format!("{}/{}", self.semantic_key, semantic_component)),
            state: Rc::new(RefCell::new(RuntimeNamespaceState::child(registry_parent))),
            declaration_env: Rc::new(RefCell::new(Weak::new())),
        }
    }

    fn detached(semantic_key: impl Into<Rc<str>>) -> Self {
        Self {
            semantic_key: semantic_key.into(),
            state: Rc::new(RefCell::new(RuntimeNamespaceState::childless(None))),
            declaration_env: Rc::new(RefCell::new(Weak::new())),
        }
    }

    fn identity_key(&self) -> String {
        self.semantic_key.to_string()
    }

    fn same_instance(&self, other: &Self) -> bool {
        self.semantic_key == other.semantic_key
    }

    fn parent(&self) -> Option<Self> {
        self.state.borrow().parent.clone()
    }

    fn install_declaration_env(&self, env: &Rc<Env>) {
        *self.declaration_env.borrow_mut() = Rc::downgrade(env);
    }

    fn declaration_env(&self) -> Option<Rc<Env>> {
        self.declaration_env.borrow().upgrade()
    }

    pub(crate) fn semantic_identity(&self) -> &str {
        &self.semantic_key
    }
}

const RUNTIME_NOMINAL_TYPE_PREFIX: &str = "__runtime_nominal_v1__";

pub(crate) fn runtime_nominal_type_name(owner: &RuntimeNamespace, type_name: &str) -> String {
    let identity = owner.semantic_identity();
    format!(
        "{}{}:{}{}",
        RUNTIME_NOMINAL_TYPE_PREFIX,
        identity.len(),
        identity,
        type_name
    )
}

pub(crate) fn runtime_nominal_type_parts(type_name: &str) -> Option<(&str, &str)> {
    let encoded = type_name.strip_prefix(RUNTIME_NOMINAL_TYPE_PREFIX)?;
    let (length, body) = encoded.split_once(':')?;
    let length = length.parse::<usize>().ok()?;
    let owner = body.get(..length)?;
    let declared = body.get(length..)?;
    (!declared.is_empty()).then_some((owner, declared))
}

pub(crate) fn runtime_nominal_declared_type_name(type_name: &str) -> &str {
    runtime_nominal_type_parts(type_name)
        .map(|(_, declared)| declared)
        .unwrap_or(type_name)
}

#[derive(Debug)]
struct RuntimeNamespaceState {
    parent: Option<RuntimeNamespace>,
    rules: Vec<(String, Rc<Rule>)>,
    rules_by_name: HashMap<String, Vec<usize>>,
    rule_miss_fallbacks: HashMap<String, HashMap<usize, RuleMissFallback>>,
    rule_dispatch_keys: BTreeSet<RuleDispatchKey>,
    rule_dispatch_return_types: BTreeMap<RuleDispatchKey, String>,
    rule_dispatch_return_issues: BTreeMap<RuleDispatchKey, String>,
    rule_dispatch_boolean_miss_safe_keys: BTreeSet<RuleDispatchKey>,
    exact_prepared_rule_dispatch: BTreeMap<RuleDispatchKey, Rc<PreparedRuntimeRuleDispatch>>,
    constructors: BTreeMap<String, (usize, bool)>,
    constructor_signatures: BTreeMap<String, Vec<RuntimeConstructorSignature>>,
    field_names: BTreeMap<String, Vec<String>>,
    type_variants: BTreeMap<String, Vec<String>>,
    ctor_to_type: BTreeMap<String, String>,
    functions: BTreeMap<String, FnDef>,
    impl_methods: BTreeMap<(String, String), FnDef>,
    rule_scopes: BTreeMap<String, Rc<RuleScopeDef>>,
    invariants: BTreeMap<String, (Expr, Expr)>,
    effect_decls: BTreeMap<String, Vec<(String, Vec<String>)>>,
    actor_defs: BTreeMap<String, Defn>,
    runtime_callable_declarations: BTreeMap<String, RuntimeCallableDeclaration>,
    completed_imports: BTreeSet<String>,
}

impl RuntimeNamespaceState {
    fn root() -> Self {
        let mut state = Self::childless(None);
        state.constructors.insert("Some".into(), (1, true));
        state.constructors.insert("None".into(), (0, true));
        state.constructor_signatures.insert(
            "Some".into(),
            vec![RuntimeConstructorSignature {
                parent: "Option".into(),
                positional: true,
                fields: vec!["_0".into()],
            }],
        );
        state.constructor_signatures.insert(
            "None".into(),
            vec![RuntimeConstructorSignature {
                parent: "Option".into(),
                positional: true,
                fields: vec![],
            }],
        );
        state
    }

    fn child(parent: RuntimeNamespace) -> Self {
        Self::childless(Some(parent))
    }

    fn childless(parent: Option<RuntimeNamespace>) -> Self {
        Self {
            parent,
            rules: Vec::new(),
            rules_by_name: HashMap::new(),
            rule_miss_fallbacks: HashMap::new(),
            rule_dispatch_keys: BTreeSet::new(),
            rule_dispatch_return_types: BTreeMap::new(),
            rule_dispatch_return_issues: BTreeMap::new(),
            rule_dispatch_boolean_miss_safe_keys: BTreeSet::new(),
            exact_prepared_rule_dispatch: BTreeMap::new(),
            constructors: BTreeMap::new(),
            constructor_signatures: BTreeMap::new(),
            field_names: BTreeMap::new(),
            type_variants: BTreeMap::new(),
            ctor_to_type: BTreeMap::new(),
            functions: BTreeMap::new(),
            impl_methods: BTreeMap::new(),
            rule_scopes: BTreeMap::new(),
            invariants: BTreeMap::new(),
            effect_decls: BTreeMap::new(),
            actor_defs: BTreeMap::new(),
            runtime_callable_declarations: BTreeMap::new(),
            completed_imports: BTreeSet::new(),
        }
    }
}

#[derive(Debug, Clone)]
struct RuntimeQualifiedModuleInstance {
    namespace: RuntimeNamespace,
    bindings: Rc<HashMap<String, Value>>,
    declaration_env: Rc<Env>,
}

impl RuntimeConstructorSignature {
    fn arity(&self) -> usize {
        self.fields.len()
    }

    fn matches_args(&self, args: &[Expr]) -> bool {
        if has_named_args(args) {
            if self.positional || !all_named_args(args) || args.len() != self.fields.len() {
                return false;
            }
            let supplied = args
                .iter()
                .filter_map(named_arg_parts)
                .map(|(field, _)| field)
                .collect::<BTreeSet<_>>();
            supplied.len() == args.len()
                && self
                    .fields
                    .iter()
                    .all(|field| supplied.contains(field.as_str()))
        } else {
            args.len() == self.arity()
        }
    }
}

/// Typed failures from the exact, effect-free interpreter boundary used by
/// bounded exploration.  These categories deliberately distinguish a finite
/// search that ran out of an operational budget from a program that cannot be
/// executed by the exact backend, and from an internal/runtime disagreement.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum ExploreRuntimeFailure {
    OperationalLimit {
        resource: ExploreRuntimeResource,
        limit: u128,
        observed: u128,
    },
    UnsupportedCapability {
        message: String,
    },
    ProducedOutput,
    RuntimeError {
        message: String,
    },
    Panicked,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum ExploreRuntimeResource {
    InitializationSteps,
    ExpressionSteps,
    CollectionMembers { operation: String },
}

impl std::fmt::Display for ExploreRuntimeFailure {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ExploreRuntimeFailure::OperationalLimit {
                resource,
                limit,
                observed,
            } => write!(
                formatter,
                "exact exploration {:?} limit {} was exceeded at {}",
                resource, limit, observed
            ),
            ExploreRuntimeFailure::UnsupportedCapability { message }
            | ExploreRuntimeFailure::RuntimeError { message } => formatter.write_str(message),
            ExploreRuntimeFailure::ProducedOutput => {
                formatter.write_str("exact exploration expression produced output")
            }
            ExploreRuntimeFailure::Panicked => {
                formatter.write_str("exact exploration expression panicked during evaluation")
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RuntimeInitializationMode {
    Ordinary,
    Calculation,
    Exploration,
}

impl RuntimeInitializationMode {
    fn prunes_top_level(self) -> bool {
        !matches!(self, RuntimeInitializationMode::Ordinary)
    }

    fn forces_exported_bindings(self) -> bool {
        matches!(self, RuntimeInitializationMode::Calculation)
    }
}

