#[derive(Debug, Clone)]
pub(crate) struct CheckedOpaqueQualifiedOwner {
    pub(crate) declaration: CheckedDeclarationOccurrenceId,
    pub(crate) target_module: Option<ModuleId>,
}

/// One program-scoped directory shared by compact expression-resolution maps.
/// Repeating the complete program/declaration identity in every `ExprSiteId`
/// key dominated preparation memory for large imported law graphs.
#[derive(Debug, Default)]
struct CheckedExpressionSiteScope {
    analysis_program: AnalysisProgramId,
    declarations: Arc<[DeclarationId]>,
}

impl CheckedExpressionSiteScope {
    fn from_program(program: &CheckedAnalysisProgram) -> Self {
        Self {
            analysis_program: program.id.clone(),
            declarations: program
                .declarations
                .iter()
                .map(|declaration| declaration.id.clone())
                .collect::<Vec<_>>()
                .into(),
        }
    }

    fn contains(&self, site: &ExprSiteId) -> bool {
        site.analysis_program == self.analysis_program
            && self.declarations.get(site.normalized_declaration_ordinal) == Some(&site.declaration)
    }
}

/// Program-scoped expression map keyed physically by declaration ordinal and
/// local AST path. The shared scope validates the complete public `ExprSiteId`
/// before lookup, so compaction does not weaken fail-closed identity checks.
#[derive(Debug, Clone)]
pub(crate) struct CheckedExpressionSiteMap<Value> {
    scope: Arc<CheckedExpressionSiteScope>,
    by_declaration: Vec<BTreeMap<Box<[u32]>, Value>>,
    len: usize,
}

impl<Value> Default for CheckedExpressionSiteMap<Value> {
    fn default() -> Self {
        Self {
            scope: Arc::new(CheckedExpressionSiteScope::default()),
            by_declaration: Vec::new(),
            len: 0,
        }
    }
}

impl<Value> CheckedExpressionSiteMap<Value> {
    fn with_scope(scope: Arc<CheckedExpressionSiteScope>) -> Self {
        let by_declaration = (0..scope.declarations.len())
            .map(|_| BTreeMap::new())
            .collect();
        Self {
            scope,
            by_declaration,
            len: 0,
        }
    }

    pub(crate) fn contains_key(&self, site: &ExprSiteId) -> bool {
        self.get(site).is_some()
    }

    pub(crate) fn get(&self, site: &ExprSiteId) -> Option<&Value> {
        self.scope.contains(site).then_some(())?;
        self.by_declaration
            .get(site.normalized_declaration_ordinal)?
            .get(site.ast_path.as_ref())
    }

    pub(crate) fn get_mut(&mut self, site: &ExprSiteId) -> Option<&mut Value> {
        self.scope.contains(site).then_some(())?;
        self.by_declaration
            .get_mut(site.normalized_declaration_ordinal)?
            .get_mut(site.ast_path.as_ref())
    }

    pub(crate) fn insert(&mut self, site: ExprSiteId, value: Value) -> Option<Value> {
        assert!(
            self.scope.contains(&site),
            "checked expression site belongs to the installed program scope"
        );
        let previous =
            self.by_declaration[site.normalized_declaration_ordinal].insert(site.ast_path, value);
        if previous.is_none() {
            self.len = self
                .len
                .checked_add(1)
                .expect("checked expression-site count fits usize");
        }
        previous
    }

    pub(crate) fn remove(&mut self, site: &ExprSiteId) -> Option<Value> {
        self.scope.contains(site).then_some(())?;
        let removed = self
            .by_declaration
            .get_mut(site.normalized_declaration_ordinal)?
            .remove(site.ast_path.as_ref());
        if removed.is_some() {
            self.len = self
                .len
                .checked_sub(1)
                .expect("checked expression-site count is positive");
        }
        removed
    }

    pub(crate) fn iter(&self) -> impl Iterator<Item = (ExprSiteId, &Value)> {
        let analysis_program = self.scope.analysis_program.clone();
        let declarations = Arc::clone(&self.scope.declarations);
        self.by_declaration.iter().enumerate().flat_map(
            move |(normalized_declaration_ordinal, entries)| {
                let analysis_program = analysis_program.clone();
                let declaration = declarations[normalized_declaration_ordinal].clone();
                entries.iter().map(move |(path, value)| {
                    (
                        ExprSiteId {
                            analysis_program: analysis_program.clone(),
                            declaration: declaration.clone(),
                            normalized_declaration_ordinal,
                            ast_path: path.clone(),
                        },
                        value,
                    )
                })
            },
        )
    }

    pub(crate) fn keys(&self) -> impl Iterator<Item = ExprSiteId> + '_ {
        self.iter().map(|(site, _)| site)
    }

    pub(crate) fn values(&self) -> impl Iterator<Item = &Value> {
        self.by_declaration.iter().flat_map(BTreeMap::values)
    }

    pub(crate) fn subtree<'a>(
        &'a self,
        root: &ExprSiteId,
    ) -> Box<dyn Iterator<Item = (ExprSiteId, &'a Value)> + 'a> {
        if !self.scope.contains(root) {
            return Box::new(std::iter::empty());
        }
        let Some(entries) = self.by_declaration.get(root.normalized_declaration_ordinal) else {
            return Box::new(std::iter::empty());
        };
        let start = root.ast_path.clone();
        let prefix = root.ast_path.clone();
        let template = root.clone();
        Box::new(
            entries
                .range(start..)
                .take_while(move |(path, _)| path.starts_with(prefix.as_ref()))
                .map(move |(path, value)| {
                    let mut site = template.clone();
                    site.ast_path = path.clone();
                    (site, value)
                }),
        )
    }

    pub(crate) const fn len(&self) -> usize {
        self.len
    }

    pub(crate) const fn is_empty(&self) -> bool {
        self.len == 0
    }
}

/// Checked, path-independent expression decisions for source bodies retained
/// by Phase A. Coverage is deliberately composable: an opaque qualified owner
/// is catalogued independently, and only a reachable expression that resolves
/// through that owner receives an unsupported issue.
#[derive(Debug, Clone, Default)]
pub(crate) struct CheckedResolutionArtifacts {
    pub(crate) analysis_program: AnalysisProgramId,
    /// False when a checker import reread did not match the Phase-A content
    /// snapshot. Ordinary checking keeps its legacy behavior, while exact
    /// source-resolution consumers fail closed through the issue seam below.
    pub(crate) source_snapshot_coherent: bool,
    pub(crate) expressions: CheckedExpressionSiteMap<CheckedExpressionResolution>,
    pub(crate) constructor_patterns:
        BTreeMap<CheckedPatternSiteId, CheckedConstructorPatternResolution>,
    /// Exact checked constructor/type catalog used to bind closed Explore
    /// values before the artifact crosses into Phase B. Keys are annotations
    /// for the producer only; consumers receive identities or location-bound
    /// ground facts and never need to repeat this lookup.
    constructor_identities: BTreeMap<(Box<str>, Box<str>), Arc<CheckedConstructorIdentity>>,
    data_type_identities: BTreeMap<Box<str>, CheckedDataTypeId>,
    /// Address bridges for stable checked data owners (currently ADTs and the
    /// active RuleScope). Semantic consumers use the model owner; syntax lookup
    /// and classifier slicing recover the exact query-inclusive checked
    /// declaration occurrence through this map.
    data_owner_to_analysis_occurrence:
        BTreeMap<CheckedModelOwnerKey, CheckedDeclarationOccurrenceId>,
    analysis_occurrence_to_data_owner:
        BTreeMap<CheckedDeclarationOccurrenceId, CheckedModelOwnerKey>,
    pub(crate) rule_families: BTreeMap<RuleDispatchKey, CheckedRuleFamilyResolution>,
    /// Exact families whose checked runtime miss is the semantic Boolean
    /// fallback rather than the ordinary partial-rule miss value.
    rule_dispatch_boolean_miss_safe_keys: BTreeSet<RuleDispatchKey>,
    pub(crate) opaque_qualified_owners:
        BTreeMap<CheckedDeclarationOccurrenceId, CheckedOpaqueQualifiedOwner>,
    pub(crate) unsupported_sites: CheckedExpressionSiteMap<BTreeSet<CheckedResolutionIssue>>,
}

impl CheckedResolutionArtifacts {
    /// Reachability-sensitive fail-closed query. Unrelated opaque modules do not
    /// poison a source slice; every issue attached to a requested site does.
    pub(crate) fn issues_for_reachable_sites<Site>(
        &self,
        sites: impl IntoIterator<Item = Site>,
    ) -> BTreeSet<CheckedResolutionIssue>
    where
        Site: std::borrow::Borrow<ExprSiteId>,
    {
        let mut result = BTreeSet::new();
        if !self.source_snapshot_coherent {
            result.insert(CheckedResolutionIssue::SourceSnapshotIncoherent);
        }
        for site in sites {
            let site = site.borrow();
            if !self.expressions.contains_key(site) {
                result.insert(CheckedResolutionIssue::ExpressionSiteNotRecorded);
            }
            if let Some(issues) = self.unsupported_sites.get(site) {
                result.extend(issues.iter().cloned());
            }
        }
        result
    }
}

