pub struct TypeChecker {
    /// function name -> param count
    pub functions: BTreeMap<String, usize>,
    /// function/rule name -> every declared arity. Calls are resolved by
    /// name and arity so a scoped member does not hide a global overload.
    function_arities: BTreeMap<String, BTreeSet<usize>>,
    /// function/rule name -> declaration-order parameter names for named calls.
    pub function_params: BTreeMap<String, Vec<String>>,
    /// function/rule name and arity -> declaration-order parameter names.
    function_params_by_arity: BTreeMap<(String, usize), Vec<String>>,
    /// rule name and arity -> declared parameter types, retaining unknowns.
    rule_param_types_by_arity: BTreeMap<(String, usize), Vec<Option<Ty>>>,
    /// Callables declared with the rule rune, distinct from ordinary functions.
    rule_arities: BTreeSet<(String, usize)>,
    /// type name -> exists
    pub types: BTreeSet<String>,
    /// constructor/variant name -> (parent type, field count)
    pub constructors: BTreeMap<String, (String, usize)>,
    /// Every declaration of a constructor name, retained for overload resolution.
    constructor_signatures: BTreeMap<String, Vec<TypeConstructorSignature>>,
    /// message name -> arity -> actor definitions that emit that bare variant.
    actor_message_arities: BTreeMap<String, BTreeMap<usize, BTreeSet<String>>>,
    /// Bare data constructors present in the backend's flattened root scope.
    top_level_constructor_names: BTreeSet<String>,
    /// Runtime names that coexist with bare actor-message variants in the
    /// flattened root scope. Nested functions, actors, and trait methods are
    /// intentionally excluded because codegen keeps them namespaced.
    root_actor_runtime_symbols: BTreeSet<String>,
    /// Lexically scoped actor identities inferred from `spawn(actor, state)`.
    actor_handle_scopes: Vec<BTreeMap<String, Option<String>>>,
    /// constructor/variant name -> declaration-order named fields.
    pub constructor_fields: BTreeMap<String, Vec<String>>,
    /// type name -> variant names (for exhaustiveness checking)
    pub type_variants: BTreeMap<String, Vec<String>>,
    /// builtin name -> arity
    pub builtins: BTreeMap<String, usize>,
    /// effect name -> set of operation names with arity
    pub effect_ops: BTreeMap<String, BTreeMap<String, usize>>,
    /// trait name -> required method names
    pub trait_methods: BTreeMap<String, Vec<String>>,
    /// (trait_name, for_type) -> provided method names
    pub impl_methods: BTreeMap<(String, String), Vec<String>>,
    /// (trait_name, method_name) -> receiver semantics required by the trait
    trait_method_receivers: BTreeMap<(String, String), MethodReceiverShape>,
    /// (trait_name, for_type, method_name) -> receiver semantics provided by the impl
    impl_method_receivers: BTreeMap<(String, String, String), MethodReceiverShape>,
    /// RuleScope name -> scoped rule name -> arity.
    rule_scope_methods: BTreeMap<String, BTreeMap<String, usize>>,
    /// RuleScope name -> scoped rule name -> declaration-order parameter names.
    rule_scope_method_params: BTreeMap<String, BTreeMap<String, Vec<String>>>,
    /// RuleScope name -> ordinary product method name -> arity excluding implicit self.
    rule_scope_value_methods: BTreeMap<String, BTreeMap<String, usize>>,
    /// RuleScope name -> ordinary product method name -> parameter names excluding implicit self.
    rule_scope_value_method_params: BTreeMap<String, BTreeMap<String, Vec<String>>>,
    /// Rule/function name -> RuleScope type directly constructed by its body.
    rule_scope_returning_rules: BTreeMap<String, String>,
    /// RuleScope-typed variables per lexical scope.
    rule_scope_vars: Vec<BTreeMap<String, String>>,
    /// Type name -> known field names.
    type_fields: BTreeMap<String, BTreeSet<String>>,
    /// Type name -> field name -> field type name.
    type_field_types: BTreeMap<String, BTreeMap<String, String>>,
    /// Type name -> field name -> declared field type, retained structurally for
    /// compile-time schema traversal such as `pathof`.
    type_field_tys: BTreeMap<String, BTreeMap<String, Ty>>,
    /// Rule/function name -> inferred value return type name.
    rule_return_types: BTreeMap<String, String>,
    /// Canonical rule result types resolved by exact scope, name, and arity.
    rule_dispatch_return_types: BTreeMap<RuleDispatchKey, String>,
    /// Exact rule identities whose result type is conflicting or unresolved.
    rule_dispatch_return_issues: BTreeMap<RuleDispatchKey, String>,
    /// Exact Bool families proven context-closed for the runtime miss override.
    rule_dispatch_boolean_miss_safe_keys: BTreeSet<RuleDispatchKey>,
    /// Every canonical rule identity declared in the flattened program.
    rule_dispatch_keys: BTreeSet<RuleDispatchKey>,
    /// Qualified imports, inline modules, and reactive scopes share interpreter
    /// rule registries today. Until those runtimes are namespaced, exact flat
    /// runtime-miss safety must be disabled wholesale.
    rule_dispatch_has_opaque_runtime_graph: bool,
    /// Runtime-visible declaration graph after recursively flattening plain
    /// imports. Qualified and hash import contents deliberately remain opaque.
    plain_import_rule_dispatch_statements: Arc<[Stmt]>,
    /// Origin-preserving checked declaration sequence built by the same
    /// constructor/import prepass. Downstream analysis must consume this
    /// artifact instead of resolving imports a second time.
    analysis_program: CheckedAnalysisProgram,
    /// Complete span-free resolved program identity, including execution and
    /// continuation statements omitted from `analysis_program`.
    resolved_program: CheckedResolvedProgramId,
    /// Legacy declaration collection still rereads imports. This sentinel is
    /// cleared if any reread that can influence exact checked resolution does
    /// not match the Phase-A content snapshot, so the recorder can fail closed
    /// without changing ordinary checker behavior.
    checked_resolution_source_snapshot_coherent: bool,
    /// Exploration rule result types resolved by exact name and arity.
    explore_rule_return_types_by_arity: BTreeMap<(String, usize), Ty>,
    /// Explicit ordinary-function results used by exploration expressions.
    explore_function_return_types_by_arity: BTreeMap<(String, usize), Ty>,
    /// Explicit function bodies and signatures retained for return validation.
    explore_function_definitions_by_arity:
        BTreeMap<(String, usize), Vec<(Vec<Param>, Option<Ty>, Expr)>>,
    /// Functions whose declared result cannot be trusted by exploration.
    explore_function_return_issues: BTreeMap<(String, usize), String>,
    /// Exact Explore return signatures that could not be resolved consistently.
    explore_rule_return_issues: BTreeMap<(String, usize), String>,
    /// Suppress the legacy name-only fallback while inferring exact rule overloads.
    inferring_exact_explore_rule_returns: bool,
    /// Require exact rule identities while checking an exploration query.
    checking_explore_query: bool,
    /// Bodies used to prove that an Explore question and its reachable helpers
    /// are free of effects and unsupported propagation paths.
    explore_callable_expressions_by_arity: BTreeMap<(String, usize), Vec<Expr>>,
    /// RuleScope member bodies retain their lexical owner so a method call
    /// cannot be redirected to a same-named root or different-scope rule.
    explore_scoped_callable_expressions: BTreeMap<RuleDispatchKey, Vec<ExplorePurityExpression>>,
    /// Every rule clause in the flattened checked program, retained so exact
    /// result inference cannot lose conflicts split across imports.
    explore_rules_by_arity: BTreeMap<(String, usize), Vec<Rule>>,
    /// Ordinary functions that declare an effect row.
    explore_declared_effect_callables: BTreeSet<(String, usize)>,
    /// Root/plain-import value bindings whose initializers may be demanded by
    /// an exact exploration. Every declaration is retained so shadowing or a
    /// duplicate import cannot hide an impure initializer from the proof.
    explore_top_level_binding_initializers: BTreeMap<String, Vec<Expr>>,
    /// Top-level binding forms whose execution is not part of the exact,
    /// effect-free initializer model (reactive and propagating bindings).
    explore_unsupported_top_level_bindings: BTreeSet<String>,
    /// RuleScope name -> scoped member name -> inferred value return type name.
    rule_scope_member_return_types: BTreeMap<String, BTreeMap<String, String>>,
    /// Active RuleScope while fixed-point return inference resolves bare sibling calls.
    active_rule_scope_inference: Option<String>,
    /// Variable type names per lexical scope.
    var_types: Vec<BTreeMap<String, String>>,
    /// qualified import module name -> exported member names
    module_exports: BTreeMap<String, BTreeSet<String>>,
    /// structured diagnostics accumulated during checking
    pub diagnostics: Vec<Diagnostic>,
    /// current variable scope stack
    pub scopes: Vec<BTreeSet<String>>,
    /// user-defined functions (distinct from rule functions for arity checks)
    pub user_functions: BTreeSet<String>,
    /// Declaration categories addressable through `refof(symbol)`.
    reference_symbols: BTreeMap<String, BTreeSet<ProgramSymbolKind>>,
    /// Invariant names addressable through the `? name` proof rune.
    invariant_names: BTreeSet<String>,
    /// Exploration declarations that passed the backend-neutral query checks.
    exploration_queries: Vec<TypedExploreQuery>,
    /// Named queries and the single allowed anonymous root query.
    exploration_names: BTreeSet<String>,
    anonymous_exploration_count: usize,
    /// Root runtime values that do not participate in the rule/function
    /// signature maps but still shadow a same-named rule call.
    explore_non_rule_runtime_names: BTreeSet<String>,
    /// Inline modules are qualified namespaces, not flat Explore declarations.
    explore_inline_module_depth: usize,
    /// source file directory (for resolving @ import paths)
    pub source_dir: Option<String>,
    /// already-imported file paths (prevents cycles)
    pub imported: BTreeSet<String>,
    /// original source text (for error positions)
    pub source_text: String,
    /// error context stack — breadcrumb trail for where we are in the program
    pub error_context: Vec<String>,
}

