pub(crate) enum CheckedExploreCoverageGapReason {
    SchemaNotDeclaredRecord,
    SchemaCompositionUnavailable,
    InterproceduralFieldProvenance,
    ConstructorFieldMappingUnavailable,
    ConstructorChoiceProvenanceUnavailable,
    UpstreamCoverageGap,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum CheckedExploreCoverageClassification {
    VariedFiniteDimension {
        dimension_id: [u8; 32],
    },
    DerivedFromDeclaredDimensions {
        dimension_ids: Box<[[u8; 32]]>,
    },
    ConditionedSingletonOrSourceRestriction,
    ExactIrrelevanceCertificate {
        certificate_digest: [u8; 32],
    },
    CoverageGap {
        reason: CheckedExploreCoverageGapReason,
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct CheckedExploreCoverageEntry {
    pub(crate) subject_id: [u8; 32],
    pub(crate) subject: CheckedExploreCoverageSubject,
    pub(crate) classification: CheckedExploreCoverageClassification,
}

/// Producer-minted coverage evidence for exactly one normalized relation.
/// Entries are sorted by canonical subject ID, making declaration and
/// traversal reorder presentation-only. A gap is evidence of unknown breadth,
/// never a license to synthesize a missing source dimension.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct CheckedExploreSourceCoverageManifest {
    pub(crate) version: u32,
    pub(crate) relation_id: explore::RelationId,
    /// Canonical closure of FROM expressions and their value/schema types.
    /// RelationId scopes this evidence but additionally includes TO.
    pub(crate) semantic_dependency_digest: [u8; 32],
    pub(crate) entries: Box<[CheckedExploreCoverageEntry]>,
    pub(crate) manifest_digest: Box<str>,
}

impl CheckedExploreSourceCoverageManifest {
    /// Revalidate the complete producer-owned wire identity. Presentation
    /// names are never hash inputs, while every subject ID is recomputed from
    /// its canonical structural preimage under this exact relation.
    pub(crate) fn validate_identity(&self) -> bool {
        if self.version != CHECKED_EXPLORE_SOURCE_COVERAGE_VERSION
            || self.entries.is_empty()
            || self
                .entries
                .windows(2)
                .any(|pair| pair[0].subject_id >= pair[1].subject_id)
        {
            return false;
        }

        let mut declared_dimensions = BTreeSet::new();
        for entry in &self.entries {
            let Some(expected_subject_id) =
                checked_explore_coverage_subject_identity(self.relation_id, &entry.subject)
            else {
                return false;
            };
            if entry.subject_id != expected_subject_id {
                return false;
            }
            if let CheckedExploreCoverageSubject::SourceBinding { .. } = &entry.subject {
                if let CheckedExploreCoverageClassification::VariedFiniteDimension {
                    dimension_id,
                } = &entry.classification
                {
                    if *dimension_id != entry.subject_id {
                        return false;
                    }
                    declared_dimensions.insert(*dimension_id);
                }
            }
        }

        for entry in &self.entries {
            match &entry.classification {
                CheckedExploreCoverageClassification::VariedFiniteDimension { dimension_id } => {
                    if !declared_dimensions.contains(dimension_id) {
                        return false;
                    }
                }
                CheckedExploreCoverageClassification::DerivedFromDeclaredDimensions {
                    dimension_ids,
                } => {
                    if dimension_ids.is_empty()
                        || dimension_ids.windows(2).any(|pair| pair[0] >= pair[1])
                        || dimension_ids
                            .iter()
                            .any(|dimension_id| !declared_dimensions.contains(dimension_id))
                    {
                        return false;
                    }
                }
                CheckedExploreCoverageClassification::ConditionedSingletonOrSourceRestriction
                | CheckedExploreCoverageClassification::ExactIrrelevanceCertificate { .. }
                | CheckedExploreCoverageClassification::CoverageGap { .. } => {}
            }
        }

        self.manifest_digest.as_ref()
            == checked_explore_source_coverage_manifest_digest(
                self.version,
                self.relation_id,
                self.semantic_dependency_digest,
                &self.entries,
            )
            .as_ref()
    }

    /// Coverage gaps are a fail-closed boundary for any claim that the source
    /// relation spans the complete profile space. Consumers may still report
    /// the explored relation and its explicit conditioning, but must not
    /// silently treat an unknown producer/field provenance as irrelevant.
    pub(crate) fn has_coverage_gaps(&self) -> bool {
        self.entries.iter().any(|entry| {
            matches!(
                &entry.classification,
                CheckedExploreCoverageClassification::CoverageGap { .. }
            )
        })
    }
}

/// Version of the compiler-owned, FROM-assignment separating-projection
/// certificate.  This is intentionally independent of the journal and
/// support-plan versions: an unsupported checked expression simply produces
/// no certificate and leaves the mapped source image open.
pub(crate) const CHECKED_EXPLORE_SOURCE_IMAGE_PROJECTION_VERSION: u32 = 2;

/// Semantic endpoint retained by one normalized source row.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) enum CheckedExploreSourceProjectionEndpoint {
    Context,
    Before,
}

/// Exact constructor-field identity in a separating endpoint path.
///
/// The owner digest is derived from [`CheckedDataTypeId`], including the exact
/// declared occurrence for user types. Names and spans are deliberately not
/// identity. Variant and field ordinals therefore remain meaningful only
/// under this exact owner.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) struct CheckedExploreSourceProjectionField {
    pub(crate) owner_digest: [u8; 32],
    pub(crate) variant_index: u32,
    pub(crate) field_index: u32,
}

/// One independent finite integer factor recognized by the checked producer.
/// The half-open bounds are also the totality domain used for every checked
/// arithmetic node in singleton-alias expansion.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct CheckedExploreSourceProjectionFactor {
    pub(crate) binding_index: u32,
    pub(crate) binder_digest: [u8; 32],
    pub(crate) start: i64,
    pub(crate) end_exclusive: i64,
    pub(crate) exact_cardinality: u128,
}

/// One factor-separating field projection. The checked expression at `path`
/// normalizes to `coefficient * factor + offset`; a nonzero coefficient makes
/// that leaf injective over the factor's exact integer domain.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct CheckedExploreSourceProjectionWitness {
    pub(crate) factor_binding_index: u32,
    pub(crate) endpoint: CheckedExploreSourceProjectionEndpoint,
    pub(crate) path: Box<[CheckedExploreSourceProjectionField]>,
    pub(crate) coefficient: i64,
    pub(crate) offset: i64,
    pub(crate) output_min: i64,
    pub(crate) output_max: i64,
    pub(crate) affine_proof_digest: [u8; 32],
    pub(crate) witness_id: [u8; 32],
}

/// Compiler-minted proof recipe for injectivity of the complete independent
/// finite assignment product into `(Context, Before)`.
///
/// `total_construction_digest` commits the exact constructor/alias/arithmetic
/// proof DAG. Every arithmetic node was interval-checked under Futuruna's
/// `i64` semantics before this value could be issued. The ordered factor and
/// witness arrays are in source binding order.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct CheckedExploreSourceImageProjectionCertificate {
    pub(crate) version: u32,
    pub(crate) relation_id: explore::RelationId,
    pub(crate) semantic_dependency_digest: [u8; 32],
    pub(crate) total_construction_digest: [u8; 32],
    pub(crate) factors: Box<[CheckedExploreSourceProjectionFactor]>,
    pub(crate) witnesses: Box<[CheckedExploreSourceProjectionWitness]>,
    pub(crate) certificate_id: [u8; 32],
}

impl CheckedExploreSourceImageProjectionCertificate {
    pub(crate) fn validate_identity(&self) -> bool {
        if self.version != CHECKED_EXPLORE_SOURCE_IMAGE_PROJECTION_VERSION
            || self.factors.is_empty()
            || self.factors.len() != self.witnesses.len()
            || self.factors.iter().enumerate().any(|(index, factor)| {
                factor.start >= factor.end_exclusive
                    || factor.exact_cardinality == 0
                    || (index > 0 && self.factors[index - 1].binding_index >= factor.binding_index)
            })
        {
            return false;
        }
        for (factor, witness) in self.factors.iter().zip(self.witnesses.iter()) {
            let Ok(implied_cardinality) =
                u128::try_from(i128::from(factor.end_exclusive) - i128::from(factor.start))
            else {
                return false;
            };
            let Some(maximum_input) = factor.end_exclusive.checked_sub(1) else {
                return false;
            };
            let Some(first_output) = factor
                .start
                .checked_mul(witness.coefficient)
                .and_then(|value| value.checked_add(witness.offset))
            else {
                return false;
            };
            let Some(last_output) = maximum_input
                .checked_mul(witness.coefficient)
                .and_then(|value| value.checked_add(witness.offset))
            else {
                return false;
            };
            if witness.factor_binding_index != factor.binding_index
                || factor.exact_cardinality != implied_cardinality
                || witness.coefficient == 0
                || witness.output_min != first_output.min(last_output)
                || witness.output_max != first_output.max(last_output)
                || checked_explore_projection_witness_id(
                    self.relation_id,
                    factor,
                    witness.endpoint,
                    &witness.path,
                    witness.coefficient,
                    witness.offset,
                    witness.output_min,
                    witness.output_max,
                    witness.affine_proof_digest,
                ) != witness.witness_id
            {
                return false;
            }
        }
        checked_explore_projection_certificate_id(
            self.version,
            self.relation_id,
            self.semantic_dependency_digest,
            self.total_construction_digest,
            &self.factors,
            &self.witnesses,
        ) == self.certificate_id
    }
}

/// Version of the compiler-owned theorem for one grouped source result over a
/// canonical mixed-radix product. This proof is an optional execution recipe;
/// it is deliberately absent from RelationId, QuestionId, ViewId and the
/// analysis-graph digest.
pub(crate) const CHECKED_EXPLORE_PRODUCT_RANK_GROUPED_DISTINCT_VERSION: u32 = 1;

/// Checked prefix/suffix reduction theorem for one source result view.
///
/// The source factors remain in finite-binding order. `group_factor_count`
/// splits that order into a nonempty prefix and suffix. The checked group tuple
/// depends exactly on, and separates, the prefix. The sole `count_distinct`
/// argument depends exactly on, and separates, the suffix. Consequently every
/// group has `exact_members_per_group` members and the same exact distinct
/// count, while `exact_group_count` checked representatives suffice to obtain
/// the public group values.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct CheckedExploreProductRankGroupedDistinctCertificate {
    version: u32,
    relation_id: explore::RelationId,
    view_id: explore::ViewId,
    source_projection_certificate_id: [u8; 32],
    source_factor_root: [u8; 32],
    factor_count: u32,
    group_factor_count: u32,
    exact_group_count: u128,
    exact_members_per_group: u128,
    group_projection_digest: [u8; 32],
    distinct_projection_digest: [u8; 32],
    certificate_id: [u8; 32],
}

impl CheckedExploreProductRankGroupedDistinctCertificate {
    pub(crate) const fn version(&self) -> u32 {
        self.version
    }

    pub(crate) const fn relation_id(&self) -> explore::RelationId {
        self.relation_id
    }

    pub(crate) const fn view_id(&self) -> explore::ViewId {
        self.view_id
    }

    pub(crate) const fn source_projection_certificate_id(&self) -> [u8; 32] {
        self.source_projection_certificate_id
    }

    pub(crate) const fn source_factor_root(&self) -> [u8; 32] {
        self.source_factor_root
    }

    pub(crate) const fn factor_count(&self) -> u32 {
        self.factor_count
    }

    pub(crate) const fn group_factor_count(&self) -> u32 {
        self.group_factor_count
    }

    pub(crate) const fn exact_group_count(&self) -> u128 {
        self.exact_group_count
    }

    pub(crate) const fn exact_members_per_group(&self) -> u128 {
        self.exact_members_per_group
    }

    pub(crate) const fn group_projection_digest(&self) -> [u8; 32] {
        self.group_projection_digest
    }

    pub(crate) const fn distinct_projection_digest(&self) -> [u8; 32] {
        self.distinct_projection_digest
    }

    pub(crate) const fn certificate_id(&self) -> [u8; 32] {
        self.certificate_id
    }

    pub(crate) fn validate_identity(&self) -> bool {
        self.version == CHECKED_EXPLORE_PRODUCT_RANK_GROUPED_DISTINCT_VERSION
            && self.factor_count >= 2
            && self.group_factor_count > 0
            && self.group_factor_count < self.factor_count
            && self.exact_group_count > 0
            && self.exact_members_per_group > 0
            && self
                .exact_group_count
                .checked_mul(self.exact_members_per_group)
                .is_some()
            && self.certificate_id
                == checked_explore_product_rank_grouped_distinct_certificate_id(self)
    }

    /// Rebind this view-local theorem to the exact existing source certificate.
    /// This comparison never broadens source-image proof authority.
    pub(crate) fn validates_source_projection(
        &self,
        source: &CheckedExploreSourceImageProjectionCertificate,
    ) -> bool {
        if !self.validate_identity()
            || !source.validate_identity()
            || self.relation_id != source.relation_id
            || self.source_projection_certificate_id != source.certificate_id
            || self.source_factor_root != checked_explore_product_rank_factor_root(&source.factors)
            || usize::try_from(self.factor_count).ok() != Some(source.factors.len())
        {
            return false;
        }
        let Some(split) = usize::try_from(self.group_factor_count).ok() else {
            return false;
        };
        checked_explore_projection_factor_cardinality(&source.factors[..split])
            == Some(self.exact_group_count)
            && checked_explore_projection_factor_cardinality(&source.factors[split..])
                == Some(self.exact_members_per_group)
    }
}

/// One immutable checked query boundary. This is the only artifact an exact
/// analysis consumer should select: it already joins the source occurrence,
/// closed relational IR, query sites, layered identities and analysis DAG.
#[derive(Debug, Clone)]
pub(crate) struct CheckedExploreQueryArtifact {
    pub(crate) identity: CheckedExploreQueryId,
    /// Producer-minted identity of the normalized FROM/TO relation. Scoped
    /// admission, FIND, views, mechanisms, names and operational plans are
    /// deliberately outside it.
    pub(crate) relation_id: explore::RelationId,
    /// Producer-minted identity of the normalized scoped-WHERE conjunction.
    pub(crate) admission_id: explore::AdmissionId,
    /// Producer-minted identity of FIND layered over the admitted relation.
    pub(crate) question_id: explore::QuestionId,
    /// Closed executable/residual classification graph minted from this exact
    /// checked query boundary. It is an overlay on the identity ladder: the
    /// relation/admission/question IDs remain independently authoritative.
    classification_program:
        Arc<explore::relational_classification_capsule::FrozenClassificationProgram>,
    /// Capsule-authenticated runtime spelling/layout adapter retained beside,
    /// never inside, the reusable name-free classification program.
    classification_runtime_shapes:
        Arc<explore::relational_classification_capsule::FrozenClassificationRuntimeShapes>,
    /// Compiler-owned transitive declaration slice for an optional native
    /// classifier. Occurrence identity prevents an accelerator from silently
    /// selecting another same-spelled declaration from the flattened graph.
    classifier_reachable_declarations: Box<[CheckedDeclarationOccurrenceId]>,
    classifier_reachable_dependencies: Box<[CheckedExploreSemanticDependency]>,
    /// Producer-minted transition schema receipt derived from this relational
    /// query's checked Before/Context types and nominal type owners.
    transition_schemas: explore::TransitionSchemaIdentities,
    /// View/request identities in the same order as `ExploreQueryIr.analysis`.
    pub(crate) analysis: Box<[CheckedExploreAnalysisIdentity]>,
    /// Canonical semantic seal for the requested analysis DAG. Authored names,
    /// node positions and independent topological order are excluded.
    pub(crate) analysis_graph_digest: Box<str>,
    /// Explicit starter publication consumers in authored declaration order.
    /// These identities are independent of the core analysis graph seal.
    pub(crate) starter_projections: Box<[CheckedExploreStarterProjectionIdentity]>,
    /// Order-independent identity of the attached starter consumer set.
    pub(crate) starter_consumer_set_id: CheckedExploreStarterConsumerSetId,
    /// Explicit full transition-graph consumers, independent of the core
    /// analysis DAG and of the selected typed edge-list projection.
    pub(crate) transition_graphs: Box<[CheckedExploreTransitionGraphIdentity]>,
    pub(crate) transition_graph_consumer_set_id: CheckedExploreTransitionGraphConsumerSetId,
    /// Conservative, producer-owned account of the finite source breadth and
    /// every immutable input reachable from its checked FROM-only semantic
    /// closure. Successor/question/analysis inputs are deliberately excluded.
    pub(crate) source_coverage: CheckedExploreSourceCoverageManifest,
    /// Optional compiler proof that every varying independent FROM factor is
    /// recoverable through a total constructor-field projection of Context or
    /// Before. Absence is fail-closed and never weakens ordinary exploration.
    pub(crate) source_image_projection: Option<CheckedExploreSourceImageProjectionCertificate>,
    /// Optional result-local reduction proofs derived after semantic ViewIds
    /// are fixed. Ordering is canonical by ViewId and has no semantic effect.
    product_rank_grouped_distinct: Box<[CheckedExploreProductRankGroupedDistinctCertificate]>,
    pub(crate) sites: CheckedExploreQuerySites,
    /// Index into the public closed-query projection. Access must go through
    /// `TypeCheckArtifacts::checked_exploration_query`, which revalidates the
    /// producer digest before exposing the borrowed closed query.
    closed_query_index: usize,
}

#[derive(Debug, Clone)]
pub(crate) enum CheckedExploreQueryArtifactIssue {
    AcceptedQueryCountMismatch {
        declarations: usize,
        closed_queries: usize,
    },
    QuerySiteMissing(ExprSiteId),
    TypeOwnerNotResolved {
        ty: Ty,
    },
    SemanticDependencyClosureUnsealed {
        layer: Box<str>,
        site: Option<ExprSiteId>,
    },
    ClassificationProgram(Box<str>),
    RelationalIr(String),
    AnalysisGraph(String),
}

#[derive(Debug, Clone)]
pub(crate) enum CheckedExploreQueryAccessError {
    Producer(CheckedExploreQueryArtifactIssue),
    AcceptedQueryMissing { index: usize, available: usize },
    AnalysisProgramIdentityMismatch,
    SourceSnapshotIncoherent,
    SourceDeclarationMissing(CheckedDeclarationOccurrenceId),
    ClassificationProgramInvalid(Box<str>),
    ClassificationProgramDiverged,
    ArtifactDiverged,
}

#[derive(Clone, Copy)]
pub(crate) struct CheckedExploreQueryView<'a> {
    pub(crate) artifact: &'a CheckedExploreQueryArtifact,
    pub(crate) closed_query: &'a explore::ExploreQueryIr,
    resolved_program: &'a CheckedResolvedProgramId,
}

/// Compact owned continuation of an already validated checked-query
/// boundary. Runtime preparation may retain this while dropping the much
/// larger whole-program resolution artifacts; `view` does not repeat or
/// weaken validation because every field was cloned from one joined view.
#[derive(Debug, Clone)]
pub(crate) struct OwnedCheckedExploreQuery {
    artifact: CheckedExploreQueryArtifact,
    closed_query: explore::ExploreQueryIr,
    resolved_program: CheckedResolvedProgramId,
}

impl OwnedCheckedExploreQuery {
    pub(crate) fn view(&self) -> CheckedExploreQueryView<'_> {
        CheckedExploreQueryView {
            artifact: &self.artifact,
            closed_query: &self.closed_query,
            resolved_program: &self.resolved_program,
        }
    }
}

impl CheckedExploreQueryView<'_> {
    pub(crate) fn to_owned_checked_query(&self) -> OwnedCheckedExploreQuery {
        OwnedCheckedExploreQuery {
            artifact: self.artifact.clone(),
            closed_query: self.closed_query.clone(),
            resolved_program: self.resolved_program.clone(),
        }
    }

    /// Complete resolved-program identity belonging to this validated query.
    pub(crate) fn program_hash(&self) -> &str {
        self.resolved_program.as_str()
    }

    /// Producer-owned identity of the normalized FROM/TO relation.
    pub(crate) const fn relation_id(&self) -> explore::RelationId {
        self.artifact.relation_id
    }

    pub(crate) const fn admission_id(&self) -> explore::AdmissionId {
        self.artifact.admission_id
    }

    pub(crate) const fn question_id(&self) -> explore::QuestionId {
        self.artifact.question_id
    }

    pub(crate) fn classification_program(
        &self,
    ) -> Arc<explore::relational_classification_capsule::FrozenClassificationProgram> {
        Arc::clone(&self.artifact.classification_program)
    }

    pub(crate) fn classification_runtime_shapes(
        &self,
    ) -> Arc<explore::relational_classification_capsule::FrozenClassificationRuntimeShapes> {
        Arc::clone(&self.artifact.classification_runtime_shapes)
    }

    /// Producer-bound schema identities for replaying this query's
    /// before-to-after transitions. Consumers cannot supply an independent
    /// schema receipt alongside a checked query.
    pub(crate) fn transition_schemas(&self) -> &explore::TransitionSchemaIdentities {
        &self.artifact.transition_schemas
    }

    pub(crate) fn source_coverage(&self) -> &CheckedExploreSourceCoverageManifest {
        &self.artifact.source_coverage
    }

    pub(crate) fn source_image_projection(
        &self,
    ) -> Option<&CheckedExploreSourceImageProjectionCertificate> {
        self.artifact.source_image_projection.as_ref()
    }

    pub(crate) fn product_rank_grouped_distinct_certificate(
        &self,
        view_id: explore::ViewId,
    ) -> Option<&CheckedExploreProductRankGroupedDistinctCertificate> {
        self.artifact
            .product_rank_grouped_distinct
            .binary_search_by_key(&view_id, |certificate| certificate.view_id())
            .ok()
            .and_then(|index| self.artifact.product_rank_grouped_distinct.get(index))
    }

    pub(crate) fn analysis_graph_hash(&self) -> &str {
        &self.artifact.analysis_graph_digest
    }

    pub(crate) const fn starter_consumer_set_id(&self) -> CheckedExploreStarterConsumerSetId {
        self.artifact.starter_consumer_set_id
    }

    pub(crate) const fn transition_graph_consumer_set_id(
        &self,
    ) -> CheckedExploreTransitionGraphConsumerSetId {
        self.artifact.transition_graph_consumer_set_id
    }

    /// Starter declarations paired with their producer-minted publication
    /// identities. The declaration name remains the output address; the
    /// checked identity binds that address to its request, subject, optional
    /// enclosing mechanism and view.
    pub(crate) fn starter_projection_consumers(
        &self,
    ) -> impl ExactSizeIterator<
        Item = (
            &explore::ExploreStarterProjectionIr,
            &CheckedExploreStarterProjectionIdentity,
        ),
    > + '_ {
        self.closed_query
            .starter_projections
            .iter()
            .zip(self.artifact.starter_projections.iter())
    }

    pub(crate) fn transition_graph_consumers(
        &self,
    ) -> impl ExactSizeIterator<
        Item = (
            &explore::ExploreTransitionGraphIr,
            &CheckedExploreTransitionGraphIdentity,
        ),
    > + '_ {
        self.closed_query
            .transition_graphs
            .iter()
            .zip(self.artifact.transition_graphs.iter())
    }

    /// Normalized analysis nodes paired with their producer-minted identities
    /// by the checked-artifact validator. Consumers cannot independently zip
    /// an unrelated IR and identity slice through this boundary.
    pub(crate) fn analysis_nodes(
        &self,
    ) -> impl ExactSizeIterator<
        Item = (
            &explore::ExploreAnalysisNodeIr,
            &CheckedExploreAnalysisIdentity,
        ),
    > + '_ {
        self.closed_query
            .analysis
            .iter()
            .zip(self.artifact.analysis.iter())
    }
}

pub struct TypeCheckArtifacts {
    pub diagnostics: Vec<Diagnostic>,
    pub calculation_contracts: Vec<calculate::CalculationContract>,
    pub compile_time_metadata_bindings: BTreeSet<String>,
    pub rule_return_types: BTreeMap<String, String>,
    pub rule_scope_member_return_types: BTreeMap<String, BTreeMap<String, String>>,
    pub rule_dispatch_return_types: BTreeMap<RuleDispatchKey, String>,
    pub rule_dispatch_return_issues: BTreeMap<RuleDispatchKey, String>,
    pub rule_dispatch_boolean_miss_safe_keys: BTreeSet<RuleDispatchKey>,
    pub exploration_queries: Vec<TypedExploreQuery>,
    /// Closed relational query descriptors. Solver/executor code must consume
    /// this layer, never reinterpret the typed source-domain syntax above.
    pub exploration_universes: Vec<explore::ExploreQueryIr>,
    /// Declaration-occurrence-bound checked query artifacts. Exact and
    /// proof-producing consumers must use this immutable joined layer rather
    /// than independently pairing the public typed and closed projections.
    pub(crate) checked_exploration_queries: Vec<CheckedExploreQueryArtifact>,
    pub(crate) checked_exploration_query_issue: Option<CheckedExploreQueryArtifactIssue>,
    pub(crate) analysis_program: CheckedAnalysisProgram,
    pub(crate) resolved_program: CheckedResolvedProgramId,
    /// Immutable root syntax accepted at the checked-program boundary. Exact
    /// stream evaluators replay this owned snapshot rather than a later-mutated
    /// caller buffer. Mechanism V1 additionally rejects every external import
    /// until replay can retain a frozen, boundary-preserving module graph.
    pub(crate) runtime_root_statements: Arc<[Stmt]>,
    runtime_root_program: CheckedResolvedProgramId,
    runtime_root_source_dir: Option<Box<str>>,
    pub(crate) checked_resolutions: CheckedResolutionArtifacts,
}

fn checked_explore_classifier_rule_signature(rule: &Rule) -> Option<(String, usize)> {
    match rule {
        Rule::Clause { head, .. } | Rule::Default { head, .. } | Rule::Exception { head, .. } => {
            rule_head_name_arity(head)
        }
        Rule::ReactiveScope { .. } => None,
    }
}

fn checked_explore_classifier_insert_unique_name(
    names: &mut BTreeSet<String>,
    name: &str,
    namespace: &str,
) -> Result<(), String> {
    if names.insert(name.to_string()) {
        Ok(())
    } else {
        Err(format!(
            "checked classifier backend {namespace} contains duplicate name `{name}`"
        ))
    }
}

#[derive(Clone)]
struct CheckedExploreClassifierConstructorLayoutV1 {
    owner: String,
    positional: bool,
    fields: Box<[String]>,
    owner_recursive: bool,
}

fn checked_explore_classifier_type_references_owner_v1(ty: &Ty, owner: &str) -> bool {
    match ty {
        Ty::Name(name) | Ty::Var(name) => name == owner,
        Ty::App(constructor, arguments) => {
            checked_explore_classifier_type_references_owner_v1(constructor, owner)
                || arguments.iter().any(|argument| {
                    checked_explore_classifier_type_references_owner_v1(argument, owner)
                })
        }
        Ty::Arrow(input, output) => {
            checked_explore_classifier_type_references_owner_v1(input, owner)
                || checked_explore_classifier_type_references_owner_v1(output, owner)
        }
        Ty::Ref(inner) | Ty::MutRef(inner) | Ty::Shared(inner) | Ty::Optional(inner) => {
            checked_explore_classifier_type_references_owner_v1(inner, owner)
        }
        Ty::Unit | Ty::Hole => false,
    }
}

fn checked_explore_classifier_constructor_call_matches_v1(
    layout: &CheckedExploreClassifierConstructorLayoutV1,
    arguments: &[Expr],
) -> bool {
    if !has_named_args(arguments) {
        return layout.fields.len() == arguments.len();
    }
    if layout.positional || !all_named_args(arguments) {
        return false;
    }
    let supplied = arguments
        .iter()
        .filter_map(named_arg_parts)
        .map(|(field, _)| field)
        .collect::<BTreeSet<_>>();
    supplied.len() == arguments.len()
        && layout.fields.len() == arguments.len()
        && layout
            .fields
            .iter()
            .all(|field| supplied.contains(field.as_str()))
}

fn checked_explore_classifier_validate_constructor_pattern_v1(
    pattern: &Pat,
    multiply_owned_fielded: &BTreeMap<String, Vec<CheckedExploreClassifierConstructorLayoutV1>>,
) -> Result<(), String> {
    let (name, arity, named_fields, children) = match pattern {
        Pat::Con(name, children) => (
            name,
            children.len(),
            None,
            children.iter().collect::<Vec<_>>(),
        ),
        Pat::NamedCon(name, fields) => (
            name,
            fields.len(),
            Some(
                fields
                    .iter()
                    .map(|(field, _)| field.as_str())
                    .collect::<BTreeSet<_>>(),
            ),
            fields.iter().map(|(_, child)| child).collect::<Vec<_>>(),
        ),
        Pat::As(inner, _) => {
            return checked_explore_classifier_validate_constructor_pattern_v1(
                inner,
                multiply_owned_fielded,
            );
        }
        Pat::Wild | Pat::Var(_) | Pat::Lit(_) => return Ok(()),
    };

    if let Some(layouts) = multiply_owned_fielded.get(name) {
        let matching = layouts
            .iter()
            .filter(|layout| {
                if let Some(supplied) = &named_fields {
                    !layout.positional
                        && layout.fields.len() == arity
                        && supplied.len() == arity
                        && layout
                            .fields
                            .iter()
                            .all(|field| supplied.contains(field.as_str()))
                } else {
                    layout.fields.len() == arity
                }
            })
            .collect::<Vec<_>>();
        if matching.len() != 1 {
            let owners = matching
                .iter()
                .map(|layout| layout.owner.as_str())
                .collect::<Vec<_>>()
                .join(", ");
            return Err(format!(
                "checked classifier backend pattern `{name}` does not recover exactly one constructor owner{}",
                (!owners.is_empty()).then(|| format!(" ({owners})")).unwrap_or_default(),
            ));
        }
    }

    for child in children {
        checked_explore_classifier_validate_constructor_pattern_v1(child, multiply_owned_fielded)?;
    }
    Ok(())
}

/// RustCodegen V1 still reconstructs several targets through global names.
/// The semantic slice may use it only when those reconstructed namespaces have
/// one possible meaning. Multiple candidates inside one exact rule family are
/// allowed; a second arity or a function/binding collision is not. A nullary
/// constructor may have several ADT owners because exact classifier codegen
/// poisons every owner-free fallback. Fielded owners are also admissible when
/// every arity is unique: direct applications and constructor
/// patterns then recover one parent from operational syntax, while bare
/// constructor values and same-arity layouts continue to fail closed.
fn checked_explore_classifier_backend_namespace_v1(statements: &[Stmt]) -> Result<(), String> {
    let mut type_names = BTreeSet::new();
    let mut constructor_names = BTreeSet::new();
    let mut constructor_layouts =
        BTreeMap::<String, Vec<CheckedExploreClassifierConstructorLayoutV1>>::new();
    let mut multiply_owned_constructor_names = BTreeSet::new();
    let mut value_names = BTreeSet::new();
    let mut root_rule_arities = BTreeMap::<String, usize>::new();

    for statement in statements {
        match statement {
            Stmt::Defn(Defn::Fn { name, effects, .. }) => {
                if !effects.is_empty() {
                    return Err(
                        "checked classifier backend slice contains an effectful function".into(),
                    );
                }
                checked_explore_classifier_insert_unique_name(
                    &mut value_names,
                    name,
                    "value namespace",
                )?;
            }
            Stmt::Bind(pattern, _, _) => {
                let mut names = BTreeSet::new();
                collect_pattern_names(pattern, &mut names);
                for name in names {
                    checked_explore_classifier_insert_unique_name(
                        &mut value_names,
                        &name,
                        "value namespace",
                    )?;
                }
            }
            Stmt::Rule(rule) => {
                let (name, arity) =
                    checked_explore_classifier_rule_signature(rule).ok_or_else(|| {
                        "checked classifier backend slice contains a reactive root rule".to_string()
                    })?;
                if root_rule_arities
                    .insert(name.clone(), arity)
                    .is_some_and(|previous| previous != arity)
                {
                    return Err(format!(
                        "checked classifier backend rule `{name}` has multiple reachable arities"
                    ));
                }
            }
            Stmt::TypeDecl(TypeDecl::ADT {
                name,
                variants,
                methods,
                ..
            }) => {
                if !methods.is_empty() {
                    return Err(
                        "checked classifier backend slice retains unproven ADT methods".into(),
                    );
                }
                checked_explore_classifier_insert_unique_name(
                    &mut type_names,
                    name,
                    "type namespace",
                )?;
                let owner_recursive = variants.iter().any(|variant| {
                    variant.fields.iter().any(|field| {
                        checked_explore_classifier_type_references_owner_v1(&field.ty, name)
                    })
                });
                let mut adt_constructor_names = BTreeSet::new();
                for variant in variants {
                    checked_explore_classifier_insert_unique_name(
                        &mut adt_constructor_names,
                        &variant.name,
                        "ADT constructor namespace",
                    )?;
                    if !constructor_names.insert(variant.name.clone()) {
                        multiply_owned_constructor_names.insert(variant.name.clone());
                    }
                    constructor_layouts
                        .entry(variant.name.clone())
                        .or_default()
                        .push(CheckedExploreClassifierConstructorLayoutV1 {
                            owner: name.clone(),
                            positional: variant.positional,
                            fields: variant
                                .fields
                                .iter()
                                .map(|field| field.name.clone())
                                .collect::<Vec<_>>()
                                .into_boxed_slice(),
                            owner_recursive,
                        });
                }
            }
            Stmt::TypeDecl(TypeDecl::RuleScope { name, body, .. }) => {
                checked_explore_classifier_insert_unique_name(
                    &mut type_names,
                    name,
                    "type namespace",
                )?;
                let mut member_names = BTreeSet::new();
                let mut member_rule_arities = BTreeMap::<String, usize>::new();
                for member in body {
                    match member {
                        Stmt::Defn(Defn::Fn { name, effects, .. }) => {
                            if !effects.is_empty() {
                                return Err(
                                    "checked classifier rule-scope slice contains an effectful member"
                                        .into(),
                                );
                            }
                            checked_explore_classifier_insert_unique_name(
                                &mut member_names,
                                name,
                                "rule-scope member namespace",
                            )?;
                        }
                        Stmt::Rule(rule) => {
                            let (name, arity) = checked_explore_classifier_rule_signature(rule)
                                .ok_or_else(|| {
                                    "checked classifier backend slice contains a reactive scoped rule"
                                        .to_string()
                                })?;
                            if member_rule_arities
                                .insert(name.clone(), arity)
                                .is_some_and(|previous| previous != arity)
                            {
                                return Err(format!(
                                    "checked classifier scoped rule `{name}` has multiple reachable arities"
                                ));
                            }
                        }
                        _ => return Err(
                            "checked classifier rule-scope slice contains an unsupported member"
                                .into(),
                        ),
                    }
                }
                for name in member_rule_arities.keys() {
                    checked_explore_classifier_insert_unique_name(
                        &mut member_names,
                        name,
                        "rule-scope member namespace",
                    )?;
                }
            }
            _ => {
                return Err(
                    "checked classifier backend slice contains an unsupported declaration".into(),
                )
            }
        }
    }
    for name in root_rule_arities.keys() {
        checked_explore_classifier_insert_unique_name(&mut value_names, name, "value namespace")?;
    }
    let mut multiply_owned_fielded = BTreeMap::new();
    for name in &multiply_owned_constructor_names {
        let layouts = constructor_layouts
            .get(name)
            .expect("multiply-owned constructor has registered layouts");
        if layouts.iter().any(|layout| !layout.fields.is_empty()) {
            let mut recoverable_arities = BTreeSet::new();
            for layout in layouts {
                if !layout.fields.is_empty() && layout.owner_recursive {
                    return Err(format!(
                        "checked classifier backend multiply-owned fielded constructor `{name}` has a recursive owner `{}`",
                        layout.owner,
                    ));
                }
                if !recoverable_arities.insert(layout.fields.len()) {
                    return Err(format!(
                        "checked classifier backend fielded constructor `{name}` has multiple owners with arity {}",
                        layout.fields.len(),
                    ));
                }
            }
            multiply_owned_fielded.insert(name.clone(), layouts.clone());
        }
    }

    let mut constructor_value_uses = BTreeMap::<String, usize>::new();
    let mut constructor_call_uses = BTreeMap::<String, usize>::new();
    let mut constructor_use_issue = None;
    for statement in statements {
        walk_ast_stmt(statement, &mut |child| {
            if constructor_use_issue.is_some() {
                return;
            }
            match child {
                AstChild::Expr(expr) => match &expr.kind {
                    ExprKind::Var(name) if multiply_owned_fielded.contains_key(name) => {
                        *constructor_value_uses.entry(name.clone()).or_default() += 1;
                    }
                    ExprKind::App(function, arguments) => {
                        let ExprKind::Var(name) = &function.kind else {
                            return;
                        };
                        let Some(layouts) = multiply_owned_fielded.get(name) else {
                            return;
                        };
                        *constructor_call_uses.entry(name.clone()).or_default() += 1;
                        let matching = layouts
                            .iter()
                            .filter(|layout| {
                                checked_explore_classifier_constructor_call_matches_v1(
                                    layout, arguments,
                                )
                            })
                            .count();
                        if matching != 1 {
                            constructor_use_issue = Some(format!(
                                "checked classifier backend call `{name}` does not recover exactly one constructor owner"
                            ));
                        }
                    }
                    ExprKind::Match(_, arms) => {
                        for arm in arms {
                            if let Err(error) =
                                checked_explore_classifier_validate_constructor_pattern_v1(
                                    &arm.pat,
                                    &multiply_owned_fielded,
                                )
                            {
                                constructor_use_issue = Some(error);
                                break;
                            }
                        }
                    }
                    _ => {}
                },
                AstChild::Stmt(statement) => {
                    let patterns = match statement {
                        Stmt::Bind(pattern, _, _) | Stmt::MonadicBind(pattern, _, _) => {
                            std::slice::from_ref(pattern)
                        }
                        Stmt::StreamSub(_, arms) => {
                            for arm in arms {
                                if let Err(error) =
                                    checked_explore_classifier_validate_constructor_pattern_v1(
                                        &arm.pat,
                                        &multiply_owned_fielded,
                                    )
                                {
                                    constructor_use_issue = Some(error);
                                    break;
                                }
                            }
                            &[]
                        }
                        Stmt::Defn(Defn::Actor { handlers, .. }) => {
                            for handler in handlers {
                                if let Err(error) =
                                    checked_explore_classifier_validate_constructor_pattern_v1(
                                        &handler.msg_pat,
                                        &multiply_owned_fielded,
                                    )
                                {
                                    constructor_use_issue = Some(error);
                                    break;
                                }
                            }
                            &[]
                        }
                        _ => &[],
                    };
                    for pattern in patterns {
                        if let Err(error) =
                            checked_explore_classifier_validate_constructor_pattern_v1(
                                pattern,
                                &multiply_owned_fielded,
                            )
                        {
                            constructor_use_issue = Some(error);
                            break;
                        }
                    }
                }
            }
        });
    }
    if let Some(issue) = constructor_use_issue {
        return Err(issue);
    }
    if let Some((name, _)) = constructor_value_uses
        .iter()
        .find(|(name, uses)| constructor_call_uses.get(*name).copied().unwrap_or(0) != **uses)
    {
        return Err(format!(
            "checked classifier backend multiply-owned fielded constructor `{name}` is used as an owner-free value"
        ));
    }
    if let Some(name) = constructor_names.intersection(&value_names).next() {
        return Err(format!(
            "checked classifier backend constructor `{name}` collides with a value name"
        ));
    }
    if let Some(name) = multiply_owned_constructor_names
        .intersection(&type_names)
        .next()
    {
        return Err(format!(
            "checked classifier backend multiply-owned constructor `{name}` collides with a type name"
        ));
    }
    if let Some(name) = multiply_owned_constructor_names.iter().find(|name| {
        matches!(
            name.as_str(),
            "None" | "Some" | "Nil" | "Cons" | "True" | "False" | "Ok" | "Err"
        )
    }) {
        return Err(format!(
            "checked classifier backend multiply-owned constructor `{name}` collides with a built-in constructor"
        ));
    }
    Ok(())
}

impl TypeCheckArtifacts {
    /// Revalidate and return the immutable root module captured by this
    /// artifact. The dedicated root digest includes execution statements that
    /// are intentionally absent from semantic-site identity.
    pub(crate) fn checked_runtime_root_program_v1(
        &self,
    ) -> Result<(&[Stmt], Option<&str>), String> {
        if self.analysis_program.id != self.checked_resolutions.analysis_program
            || !self.checked_resolutions.source_snapshot_coherent
        {
            return Err("checked runtime root belongs to an incoherent analysis snapshot".into());
        }
        let actual = TypeChecker::checked_resolved_program_id(
            &self.analysis_program,
            &self.runtime_root_statements,
        );
        if actual != self.runtime_root_program {
            return Err(
                "checked runtime root snapshot disagrees with its producer-owned identity".into(),
            );
        }
        let root_modules = self
            .analysis_program
            .declarations
            .iter()
            .filter(|declaration| matches!(declaration.import_kind, SourcedImportKind::Root))
            .map(|declaration| declaration.id.module.clone())
            .collect::<BTreeSet<_>>();
        if root_modules.len() != 1 {
            return Err(
                "checked runtime root does not identify exactly one root source module".into(),
            );
        }
        let expected_root = root_modules
            .iter()
            .next()
            .expect("one checked runtime root module");
        if &TypeChecker::analysis_module_id(&self.runtime_root_statements) != expected_root {
            return Err(
                "checked runtime root syntax disagrees with its checked source module".into(),
            );
        }
        Ok((
            &self.runtime_root_statements,
            self.runtime_root_source_dir.as_deref(),
        ))
    }

    /// Reject a caller buffer or source origin that differs from the immutable
    /// root snapshot selected by the artifact. Exact evaluation then uses only
    /// the artifact-owned slice returned above.
    pub(crate) fn validate_checked_runtime_entry_v1(
        &self,
        statements: &[Stmt],
        source_dir: Option<&str>,
    ) -> Result<(), String> {
        self.checked_runtime_root_program_v1()?;
        let supplied = TypeChecker::checked_resolved_program_id(&self.analysis_program, statements);
        if supplied != self.runtime_root_program {
            return Err(
                "runtime entry syntax differs from the immutable checked root snapshot".into(),
            );
        }
        if source_dir != self.runtime_root_source_dir.as_deref() {
            return Err(
                "runtime entry source directory differs from the checked root origin".into(),
            );
        }
        Ok(())
    }

    /// Materialize the compiler-proven classifier dependency graph in the
    /// checked program's canonical declaration order. The query view supplies
    /// exact occurrence identities, never names; every requested occurrence
    /// must still be present in this same coherent producer snapshot.
    pub(crate) fn checked_explore_classifier_declarations_v1(
        &self,
        checked: &CheckedExploreQueryView<'_>,
    ) -> Result<Box<[Stmt]>, String> {
        #[derive(Default)]
        struct DeclarationSupport {
            whole_statement: bool,
            declared_type_shell: bool,
            callable_paths: BTreeSet<Box<[u32]>>,
            rule_paths: BTreeSet<Box<[u32]>>,
        }

        if checked.artifact.identity.analysis_program != self.analysis_program.id
            || checked.resolved_program != &self.resolved_program
            || self.analysis_program.id != self.checked_resolutions.analysis_program
            || !self.checked_resolutions.source_snapshot_coherent
        {
            return Err(
                "checked classifier declarations belong to an incoherent program snapshot".into(),
            );
        }

        let required = checked
            .artifact
            .classifier_reachable_declarations
            .iter()
            .cloned()
            .collect::<BTreeSet<_>>();
        if required.len() != checked.artifact.classifier_reachable_declarations.len() {
            return Err(
                "checked classifier declaration slice contains duplicate identities".into(),
            );
        }

        let mut support = BTreeMap::<CheckedDeclarationOccurrenceId, DeclarationSupport>::new();
        for dependency in checked.artifact.classifier_reachable_dependencies.iter() {
            match dependency {
                CheckedExploreSemanticDependency::TopLevel(binding) => {
                    support
                        .entry(binding.declaration.clone())
                        .or_default()
                        .whole_statement = true;
                }
                CheckedExploreSemanticDependency::Callable(callable) => {
                    let entry = support.entry(callable.declaration.clone()).or_default();
                    if callable.structural_path.is_empty() {
                        entry.whole_statement = true;
                    } else {
                        entry
                            .callable_paths
                            .insert(callable.structural_path.clone());
                    }
                }
                CheckedExploreSemanticDependency::RuleFamily(key) => {
                    let family = self.checked_resolutions.rule_families.get(key).ok_or_else(
                        || {
                            "checked classifier rule family is missing from its program snapshot"
                                .to_string()
                        },
                    )?;
                    for candidate in family.candidates.iter() {
                        support
                            .entry(candidate.declaration.clone())
                            .or_default()
                            .rule_paths
                            .insert(candidate.statement_path.clone());
                    }
                }
                CheckedExploreSemanticDependency::DeclaredType(CheckedDataTypeId::Declared(
                    owner,
                )) => {
                    let declaration = self
                        .checked_resolutions
                        .data_owner_to_analysis_occurrence
                        .get(owner)
                        .ok_or_else(|| {
                            "checked classifier model owner has no analysis occurrence bridge"
                                .to_string()
                        })?;
                    support
                        .entry(declaration.clone())
                        .or_default()
                        .declared_type_shell = true;
                }
                CheckedExploreSemanticDependency::DeclaredType(CheckedDataTypeId::Intrinsic {
                    ..
                }) => {}
            }
        }
        if support.keys().cloned().collect::<BTreeSet<_>>() != required {
            return Err(
                "checked classifier declarations disagree with their semantic support graph".into(),
            );
        }

        let mut supported = support.into_iter().collect::<Vec<_>>();
        supported.sort_by_key(|(occurrence, _)| occurrence.normalized_ordinal);
        let explicit_display_types = self
            .analysis_program
            .declarations
            .iter()
            .filter_map(|declaration| match declaration.statement.as_ref() {
                Stmt::TypeDecl(TypeDecl::ImplBlock {
                    trait_name,
                    for_type,
                    ..
                }) if trait_name == "Display" => Some(for_type.clone()),
                _ => None,
            })
            .collect::<BTreeSet<_>>();
        let mut seen_ordinals = BTreeSet::new();
        let mut statements = Vec::with_capacity(supported.len());
        for (occurrence, support) in supported {
            if !seen_ordinals.insert(occurrence.normalized_ordinal) {
                return Err(
                    "checked classifier declarations reuse one normalized program ordinal".into(),
                );
            }
            let declaration = self
                .analysis_program
                .declarations
                .get(occurrence.normalized_ordinal)
                .ok_or_else(|| {
                    "checked classifier declaration ordinal is outside its program snapshot"
                        .to_string()
                })?;
            if CheckedDeclarationOccurrenceId::from_sourced(declaration) != occurrence {
                return Err(
                    "checked classifier declaration identity disagrees with its program ordinal"
                        .into(),
                );
            }
            if matches!(
                declaration.import_kind,
                SourcedImportKind::HashImport { .. } | SourcedImportKind::QualifiedImport { .. }
            ) {
                return Err(
                    "checked classifier V1 does not erase hash/qualified import provenance".into(),
                );
            }

            let statement = match declaration.statement.as_ref() {
                Stmt::Defn(Defn::Fn { .. })
                    if support.whole_statement
                        && !support.declared_type_shell
                        && support.callable_paths.is_empty()
                        && support.rule_paths.is_empty() =>
                {
                    declaration.statement.as_ref().clone()
                }
                Stmt::Bind(pattern, _, _)
                    if support.whole_statement
                        && !support.declared_type_shell
                        && support.callable_paths.is_empty()
                        && support.rule_paths.is_empty() =>
                {
                    let mut names = BTreeSet::new();
                    collect_pattern_names(pattern, &mut names);
                    if names
                        .iter()
                        .any(|name| self.compile_time_metadata_bindings.contains(name))
                    {
                        return Err(
                            "checked classifier reaches a compile-time metadata binding".into()
                        );
                    }
                    declaration.statement.as_ref().clone()
                }
                Stmt::Rule(_)
                    if !support.whole_statement
                        && !support.declared_type_shell
                        && support.callable_paths.is_empty()
                        && support.rule_paths.len() == 1
                        && support.rule_paths.contains(&Box::<[u32]>::default()) =>
                {
                    declaration.statement.as_ref().clone()
                }
                Stmt::TypeDecl(TypeDecl::ADT {
                    name,
                    params,
                    variants,
                    except_from,
                    ..
                }) if support.declared_type_shell
                    && !support.whole_statement
                    && support.callable_paths.is_empty()
                    && support.rule_paths.is_empty() =>
                {
                    if explicit_display_types.contains(name) {
                        return Err(
                            "checked classifier V1 does not separate an ADT from its explicit Display implementation"
                                .into(),
                        );
                    }
                    Stmt::TypeDecl(TypeDecl::ADT {
                        name: name.clone(),
                        params: params.clone(),
                        variants: variants.clone(),
                        methods: Vec::new(),
                        except_from: except_from.clone(),
                    })
                }
                Stmt::TypeDecl(TypeDecl::RuleScope { name, params, body })
                    if support.declared_type_shell && !support.whole_statement =>
                {
                    let mut child_indices = BTreeSet::new();
                    for path in support
                        .callable_paths
                        .iter()
                        .chain(support.rule_paths.iter())
                    {
                        let [child_index] = path.as_ref() else {
                            return Err(
                                "checked classifier V1 cannot prune a nested rule-scope member"
                                    .into(),
                            );
                        };
                        child_indices.insert(*child_index as usize);
                    }
                    let mut selected_body = Vec::with_capacity(child_indices.len());
                    for child_index in child_indices {
                        let child = body.get(child_index).ok_or_else(|| {
                            "checked classifier rule-scope member path is outside its declaration"
                                .to_string()
                        })?;
                        let path = vec![child_index as u32].into_boxed_slice();
                        let callable = support.callable_paths.contains(&path);
                        let rule = support.rule_paths.contains(&path);
                        if callable && !matches!(child, Stmt::Defn(Defn::Fn { .. }))
                            || rule && !matches!(child, Stmt::Rule(_))
                        {
                            return Err(
                                "checked classifier rule-scope member kind disagrees with its support graph"
                                    .into(),
                            );
                        }
                        selected_body.push(child.clone());
                    }
                    Stmt::TypeDecl(TypeDecl::RuleScope {
                        name: name.clone(),
                        params: params.clone(),
                        body: selected_body,
                    })
                }
                Stmt::TypeDecl(TypeDecl::ImplBlock { .. }) => {
                    return Err(
                        "checked classifier V1 does not emit partial implementation blocks".into(),
                    )
                }
                _ => return Err(
                    "checked classifier declaration shape exceeds the V1 backend support closure"
                        .into(),
                ),
            };
            statements.push(statement);
        }
        checked_explore_classifier_backend_namespace_v1(&statements)?;
        Ok(statements.into_boxed_slice())
    }

    pub(crate) fn checked_exploration_query_for_declaration(
        &self,
        declaration: &CheckedDeclarationOccurrenceId,
    ) -> Result<CheckedExploreQueryView<'_>, CheckedExploreQueryAccessError> {
        if let Some(issue) = &self.checked_exploration_query_issue {
            return Err(CheckedExploreQueryAccessError::Producer(issue.clone()));
        }
        let accepted_index = self
            .checked_exploration_queries
            .iter()
            .position(|query| &query.identity.declaration == declaration)
            .ok_or_else(|| {
                CheckedExploreQueryAccessError::SourceDeclarationMissing(declaration.clone())
            })?;
        self.checked_exploration_query(accepted_index)
    }

    /// Select one producer-minted checked query. The public projections are
    /// independently mutable, so the identity ladder is recomputed before a
    /// proof consumer receives a reference; stale or caller-modified state is
    /// rejected rather than rebound to the declaration by spelling.
    pub(crate) fn checked_exploration_query(
        &self,
        accepted_index: usize,
    ) -> Result<CheckedExploreQueryView<'_>, CheckedExploreQueryAccessError> {
        let semantic_index = CheckedExploreSemanticIndex::build(&self.analysis_program);
        self.checked_exploration_query_with_semantic_index(accepted_index, &semantic_index)
    }

    fn checked_exploration_query_with_semantic_index<'a>(
        &'a self,
        accepted_index: usize,
        semantic_index: &CheckedExploreSemanticIndex<'a>,
    ) -> Result<CheckedExploreQueryView<'a>, CheckedExploreQueryAccessError> {
        if let Some(issue) = &self.checked_exploration_query_issue {
            return Err(CheckedExploreQueryAccessError::Producer(issue.clone()));
        }
        let artifact = self.checked_exploration_queries.get(accepted_index).ok_or(
            CheckedExploreQueryAccessError::AcceptedQueryMissing {
                index: accepted_index,
                available: self.checked_exploration_queries.len(),
            },
        )?;
        if artifact.identity.analysis_program != self.analysis_program.id
            || artifact.identity.analysis_program != self.checked_resolutions.analysis_program
        {
            return Err(CheckedExploreQueryAccessError::AnalysisProgramIdentityMismatch);
        }
        if !self.checked_resolutions.source_snapshot_coherent {
            return Err(CheckedExploreQueryAccessError::SourceSnapshotIncoherent);
        }
        let closed_query = self
            .exploration_universes
            .get(artifact.closed_query_index)
            .ok_or(CheckedExploreQueryAccessError::ArtifactDiverged)?;
        let declaration = self
            .analysis_program
            .declarations
            .iter()
            .find(|declaration| {
                CheckedDeclarationOccurrenceId::from_sourced(declaration)
                    == artifact.identity.declaration
            })
            .ok_or_else(|| {
                CheckedExploreQueryAccessError::SourceDeclarationMissing(
                    artifact.identity.declaration.clone(),
                )
            })?;
        let Stmt::Explore(source_query) = &*declaration.statement else {
            return Err(CheckedExploreQueryAccessError::ArtifactDiverged);
        };
        closed_query
            .validate()
            .map_err(|_| CheckedExploreQueryAccessError::ArtifactDiverged)?;
        let sites = checked_explore_query_sites(&self.analysis_program, declaration, source_query);
        if sites != artifact.sites
            || checked_explore_site_roots(&sites)
                .into_iter()
                .any(|site| !self.checked_resolutions.expressions.contains_key(site))
        {
            return Err(CheckedExploreQueryAccessError::ArtifactDiverged);
        }
        let ladder = checked_explore_identity_ladder_with_index(
            &self.analysis_program,
            &self.checked_resolutions,
            closed_query,
            &sites,
            semantic_index,
        )
        .map_err(|_| CheckedExploreQueryAccessError::ArtifactDiverged)?;
        if !artifact.source_coverage.validate_identity()
            || !ladder.source_coverage.validate_identity()
            || ladder.relation_id != artifact.relation_id
            || ladder.admission_id != artifact.admission_id
            || ladder.question_id != artifact.question_id
            || ladder.classifier_reachable_declarations.as_ref()
                != artifact.classifier_reachable_declarations.as_ref()
            || ladder.classifier_reachable_dependencies.as_ref()
                != artifact.classifier_reachable_dependencies.as_ref()
            || ladder.transition_schemas != artifact.transition_schemas
            || ladder.analysis.as_ref() != artifact.analysis.as_ref()
            || ladder.analysis_graph_digest.as_ref() != artifact.analysis_graph_digest.as_ref()
            || ladder.starter_projections.as_ref() != artifact.starter_projections.as_ref()
            || ladder.starter_consumer_set_id != artifact.starter_consumer_set_id
            || ladder.transition_graphs.as_ref() != artifact.transition_graphs.as_ref()
            || ladder.transition_graph_consumer_set_id != artifact.transition_graph_consumer_set_id
            || ladder.source_coverage != artifact.source_coverage
            || ladder.source_image_projection != artifact.source_image_projection
            || ladder.product_rank_grouped_distinct.as_ref()
                != artifact.product_rank_grouped_distinct.as_ref()
        {
            return Err(CheckedExploreQueryAccessError::ArtifactDiverged);
        }
        let rebuilt_classification =
            checked_explore_classification::checked_explore_classification_program(
                &self.analysis_program,
                &self.checked_resolutions,
                closed_query,
                &sites,
                artifact.question_id,
            )
            .map_err(|error| {
                CheckedExploreQueryAccessError::ClassificationProgramInvalid(
                    error.to_string().into_boxed_str(),
                )
            })?;
        if !artifact.classification_program.validate_identity()
            || !artifact.classification_runtime_shapes.validate_identity()
            || artifact
                .classification_runtime_shapes
                .validate_for_program(artifact.classification_program.as_ref())
                .is_err()
            || !rebuilt_classification.program.validate_identity()
            || !rebuilt_classification.runtime_shapes.validate_identity()
            || rebuilt_classification
                .runtime_shapes
                .validate_for_program(&rebuilt_classification.program)
                .is_err()
            || rebuilt_classification.program.graph_root()
                != artifact.classification_program.graph_root()
            || rebuilt_classification.runtime_shapes.runtime_shape_root()
                != artifact.classification_runtime_shapes.runtime_shape_root()
            || &rebuilt_classification.program != artifact.classification_program.as_ref()
            || &rebuilt_classification.runtime_shapes
                != artifact.classification_runtime_shapes.as_ref()
        {
            return Err(CheckedExploreQueryAccessError::ClassificationProgramDiverged);
        }
        Ok(CheckedExploreQueryView {
            artifact,
            closed_query,
            resolved_program: &self.resolved_program,
        })
    }

    /// Validate one query and derive its optional exact-observer memo plan
    /// while sharing the same read-only semantic index. Preparation used to
    /// rebuild that whole-program index once for each operation.
    pub(crate) fn checked_exploration_query_with_observer_memo_plan(
        &self,
        accepted_index: usize,
    ) -> Result<
        (
            CheckedExploreQueryView<'_>,
            Option<CheckedExactObserverMemoPlan>,
        ),
        CheckedExploreQueryAccessError,
    > {
        let semantic_index = CheckedExploreSemanticIndex::build(&self.analysis_program);
        let checked =
            self.checked_exploration_query_with_semantic_index(accepted_index, &semantic_index)?;
        let memo_plan = if self
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.severity == Severity::Error)
        {
            None
        } else {
            checked_exact_observer_memo_plan_from_checked_with_index(
                &self.analysis_program,
                &self.checked_resolutions,
                &checked,
                &semantic_index,
            )
        };
        Ok((checked, memo_plan))
    }

    /// Validate one query and derive independent acceleration plans for the
    /// warm FIND classifier and fresh mechanism endpoint replays. Keeping the
    /// plans separate is semantic: FIND ALL has no selection root but may still
    /// have authored mechanism observers whose global rule DAG is memoizable.
    pub(crate) fn checked_exploration_query_with_memo_plans(
        &self,
        accepted_index: usize,
    ) -> Result<
        (
            CheckedExploreQueryView<'_>,
            Option<CheckedExactObserverMemoPlan>,
            Option<CheckedMechanismRuleMemoPlan>,
        ),
        CheckedExploreQueryAccessError,
    > {
        let semantic_index = CheckedExploreSemanticIndex::build(&self.analysis_program);
        let checked =
            self.checked_exploration_query_with_semantic_index(accepted_index, &semantic_index)?;
        let plans_enabled = !self
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.severity == Severity::Error);
        let observer_memo_plan = plans_enabled
            .then(|| {
                checked_exact_observer_memo_plan_from_checked_with_index(
                    &self.analysis_program,
                    &self.checked_resolutions,
                    &checked,
                    &semantic_index,
                )
            })
            .flatten();
        let mechanism_memo_plan = plans_enabled
            .then(|| {
                checked_mechanism_rule_memo_plan_from_checked_with_index(
                    &self.analysis_program,
                    &self.checked_resolutions,
                    &checked,
                    &semantic_index,
                )
            })
            .flatten();
        Ok((checked, observer_memo_plan, mechanism_memo_plan))
    }

    pub(crate) fn checked_mechanism_rule_memo_plan(
        &self,
        checked: &CheckedExploreQueryView<'_>,
    ) -> Option<CheckedMechanismRuleMemoPlan> {
        if self
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.severity == Severity::Error)
        {
            return None;
        }
        let index = CheckedExploreSemanticIndex::build(&self.analysis_program);
        checked_mechanism_rule_memo_plan_from_checked_with_index(
            &self.analysis_program,
            &self.checked_resolutions,
            checked,
            &index,
        )
    }

    /// Derive an optional acceleration plan from the same producer-owned
    /// checked query and semantic-resolution graph used by exact execution.
    /// Any missing proof condition disables the optimization; callers never
    /// need this plan for correctness or durable restart.
    pub(crate) fn checked_exact_observer_memo_plan(
        &self,
        accepted_index: usize,
    ) -> Option<CheckedExactObserverMemoPlan> {
        if self
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.severity == Severity::Error)
        {
            return None;
        }
        let checked = self.checked_exploration_query(accepted_index).ok()?;
        checked_exact_observer_memo_plan_from_checked(
            &self.analysis_program,
            &self.checked_resolutions,
            &checked,
        )
    }
}

fn checked_explore_query_sites(
    program: &CheckedAnalysisProgram,
    declaration: &SourcedStmt,
    query: &ExploreQuery,
) -> CheckedExploreQuerySites {
    let mut child = 0_u32;
    let source_bindings = query
        .source
        .bindings
        .iter()
        .enumerate()
        .map(|(binding_index, _)| {
            let ast_path = vec![child];
            child += 1;
            let expression = program.expression_site(declaration, ast_path.clone());
            let binder = CheckedBinderSiteId::Structural {
                analysis_program: program.id.clone(),
                declaration: declaration.id.clone(),
                normalized_declaration_ordinal: declaration.normalized_ordinal,
                ast_path: ast_path.into_boxed_slice(),
                binder_path: vec![
                    CheckedResolutionRecorder::BINDER_EXPLORE,
                    binding_index as u32,
                ]
                .into_boxed_slice(),
            };
            CheckedExploreSourceBindingSites { expression, binder }
        })
        .collect::<Vec<_>>()
        .into_boxed_slice();
    let successor = program.expression_site(declaration, vec![child]);
    child += 1;
    let admissions = query
        .admissions
        .iter()
        .map(|_| {
            let site = program.expression_site(declaration, vec![child]);
            child += 1;
            site
        })
        .collect::<Vec<_>>()
        .into_boxed_slice();
    let selection = query.selection.predicate().map(|_| {
        let site = program.expression_site(declaration, vec![child]);
        child += 1;
        site
    });
    let analysis = query
        .analysis
        .iter()
        .map(|node| match node {
            ExploreAnalysisNode::Result(result) => {
                let group_field_count = match &result.grain {
                    ExploreResultGrain::GroupBy { fields, .. } => fields.len(),
                    ExploreResultGrain::EachCase { .. }
                    | ExploreResultGrain::EachIncidence { .. }
                    | ExploreResultGrain::GroupAll { .. } => 0,
                };
                let mut sites = |count: usize| {
                    (0..count)
                        .map(|_| {
                            let site = program.expression_site(declaration, vec![child]);
                            child += 1;
                            site
                        })
                        .collect::<Vec<_>>()
                        .into_boxed_slice()
                };
                let group_fields = sites(group_field_count);
                let measures = sites(result.measures.len());
                let aggregates = sites(result.aggregates.len());
                let select = sites(result.select.len());
                let choice_count = match &result.choose {
                    None => 0,
                    Some(ExploreResultChoice::Optimize { .. }) => 1,
                    Some(ExploreResultChoice::Pareto { objectives, .. }) => objectives.len(),
                };
                let choice_objectives = sites(choice_count);
                CheckedExploreAnalysisNodeSites::Result(CheckedExploreResultSites {
                    group_fields,
                    measures,
                    aggregates,
                    select,
                    choice_objectives,
                })
            }
            ExploreAnalysisNode::Mechanisms(_) => {
                let site = program.expression_site(declaration, vec![child]);
                child += 1;
                CheckedExploreAnalysisNodeSites::Mechanisms(site)
            }
        })
        .collect::<Vec<_>>()
        .into_boxed_slice();
    CheckedExploreQuerySites {
        source_bindings,
        successor,
        admissions,
        selection,
        analysis,
    }
}

fn checked_explore_site_roots(sites: &CheckedExploreQuerySites) -> Vec<&ExprSiteId> {
    let mut roots = sites
        .source_bindings
        .iter()
        .map(|binding| &binding.expression)
        .chain(std::iter::once(&sites.successor))
        .chain(sites.admissions.iter())
        .chain(sites.selection.iter())
        .collect::<Vec<_>>();
    for node in &sites.analysis {
        match node {
            CheckedExploreAnalysisNodeSites::Result(result) => {
                roots.extend(result.group_fields.iter());
                roots.extend(result.measures.iter());
                roots.extend(result.aggregates.iter());
                roots.extend(result.select.iter());
                roots.extend(result.choice_objectives.iter());
            }
            CheckedExploreAnalysisNodeSites::Mechanisms(site) => roots.push(site),
        }
    }
    roots
}

fn checked_explore_semantic_binders(
    query: &explore::ExploreQueryIr,
    sites: &CheckedExploreQuerySites,
) -> Result<BTreeMap<CheckedBinderSiteId, Box<str>>, CheckedExploreQueryArtifactIssue> {
    if query.source.bindings.len() != sites.source_bindings.len()
        || query.analysis.len() != sites.analysis.len()
    {
        return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
            "relational query and checked semantic-binder sites diverged".into(),
        ));
    }
    let mut binders = BTreeMap::new();
    for (binding, checked) in query
        .source
        .bindings
        .iter()
        .zip(sites.source_bindings.iter())
    {
        let role = match binding.role {
            explore::ExploreSourceBindingRoleIr::Auxiliary => {
                format!("source-auxiliary:{}", binding.binding_index)
            }
            explore::ExploreSourceBindingRoleIr::Context => "source-context".to_string(),
            explore::ExploreSourceBindingRoleIr::Before => "source-before".to_string(),
        };
        binders.insert(checked.binder.clone(), role.into_boxed_str());
    }

    let successor = &sites.successor;
    binders.insert(
        CheckedExploreSemanticClosure::structural_binder(
            successor,
            &successor.ast_path,
            vec![CheckedResolutionRecorder::BINDER_EXPLORE_ROLE, 2],
        ),
        "successor-after".into(),
    );

    for (node, checked) in query.analysis.iter().zip(sites.analysis.iter()) {
        match (node, checked) {
            (
                explore::ExploreAnalysisNodeIr::Result(view),
                CheckedExploreAnalysisNodeSites::Result(result_sites),
            ) => {
                let input_roles: &[&str] = match &view.input {
                    explore::ExploreResultInputIr::Sources => &[],
                    explore::ExploreResultInputIr::Selected => &["selected-case"],
                    explore::ExploreResultInputIr::MechanismIncidence { .. } => &[
                        "incidence-case",
                        "incidence-transition",
                        "incidence-signature",
                        "incidence-structural-mechanism",
                        "incidence-execution-profile",
                    ],
                };
                {
                    let anchor = &sites.successor;
                    for (field_index, role) in input_roles.iter().enumerate() {
                        binders.insert(
                            CheckedExploreSemanticClosure::structural_binder(
                                anchor,
                                &[],
                                vec![
                                    CheckedResolutionRecorder::BINDER_EXPLORE_RESULT_INPUT,
                                    view.node_index as u32,
                                    field_index as u32,
                                ],
                            ),
                            (*role).into(),
                        );
                    }
                }
                let groups = match &view.grain {
                    explore::ExploreResultGrainIr::GroupBy { fields, .. } => fields.len(),
                    _ => 0,
                };
                if groups != result_sites.group_fields.len()
                    || view.measures.len() != result_sites.measures.len()
                    || view.aggregates.len() != result_sites.aggregates.len()
                    || view.select.len() != result_sites.select.len()
                {
                    return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
                        "result view and checked alias sites diverged".into(),
                    ));
                }
                for (kind, roots) in [
                    (
                        CheckedResolutionRecorder::EXPLORE_RESULT_GROUP,
                        result_sites.group_fields.as_ref(),
                    ),
                    (
                        CheckedResolutionRecorder::EXPLORE_RESULT_MEASURE,
                        result_sites.measures.as_ref(),
                    ),
                    (
                        CheckedResolutionRecorder::EXPLORE_RESULT_AGGREGATE,
                        result_sites.aggregates.as_ref(),
                    ),
                    (
                        CheckedResolutionRecorder::EXPLORE_RESULT_SELECT,
                        result_sites.select.as_ref(),
                    ),
                ] {
                    for (field_index, root) in roots.iter().enumerate() {
                        binders.insert(
                            CheckedExploreSemanticClosure::structural_binder(
                                root,
                                &root.ast_path,
                                vec![
                                    CheckedResolutionRecorder::BINDER_EXPLORE_RESULT,
                                    kind,
                                    view.node_index as u32,
                                    field_index as u32,
                                ],
                            ),
                            format!("view-local:{kind}:{field_index}").into_boxed_str(),
                        );
                    }
                }
            }
            (
                explore::ExploreAnalysisNodeIr::Mechanisms(_),
                CheckedExploreAnalysisNodeSites::Mechanisms(template),
            ) => {
                for (role_index, role) in ["observer-state", "observer-context"].iter().enumerate()
                {
                    binders.insert(
                        CheckedExploreSemanticClosure::structural_binder(
                            template,
                            &template.ast_path,
                            vec![
                                CheckedResolutionRecorder::BINDER_EXPLORE_OBSERVATION_STATE,
                                role_index as u32,
                            ],
                        ),
                        (*role).into(),
                    );
                }
            }
            _ => {
                return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
                    "analysis node and checked semantic-binder site have different kinds".into(),
                ));
            }
        }
    }
    Ok(binders)
}

#[derive(Clone)]
struct CheckedExploreSemanticCallable<'a> {
    runtime_name: &'a str,
    parameters: &'a [Param],
    return_type: Option<&'a Ty>,
    effects: &'a [String],
    body_site: ExprSiteId,
    parameter_sites: Box<[CheckedBinderSiteId]>,
}

/// Read-only source index for producer-owned semantic closure. Checked IDs are
/// lookup keys only: the canonical digest below never serializes declaration
/// occurrences, source paths, authored callable names, or normalized ordinals.
struct CheckedExploreSemanticIndex<'a> {
    program: &'a CheckedAnalysisProgram,
    declarations: BTreeMap<CheckedDeclarationOccurrenceId, &'a SourcedStmt>,
    /// Expression addresses are already scoped by this index's one checked
    /// program. Store the declaration ordinal once per inner map and only the
    /// local AST path per node; repeating the complete program/declaration
    /// identity in every key made large imported law models needlessly retain
    /// hundreds of megabytes during semantic sealing.
    expressions: BTreeMap<usize, BTreeMap<Box<[u32]>, &'a Expr>>,
    rules: BTreeMap<(CheckedDeclarationOccurrenceId, Box<[u32]>), &'a Rule>,
    callables: BTreeMap<CheckedCallableId, CheckedExploreSemanticCallable<'a>>,
    scoped_callables: BTreeMap<(String, String, usize), Vec<CheckedCallableId>>,
    type_declarations: BTreeMap<CheckedDeclarationOccurrenceId, &'a TypeDecl>,
    conditional_type_names: BTreeSet<String>,
    top_level_binding_names: BTreeMap<CheckedTopLevelBindingId, Box<str>>,
}

impl<'a> CheckedExploreSemanticIndex<'a> {
    fn empty(program: &'a CheckedAnalysisProgram) -> Self {
        Self {
            program,
            declarations: BTreeMap::new(),
            expressions: BTreeMap::new(),
            rules: BTreeMap::new(),
            callables: BTreeMap::new(),
            scoped_callables: BTreeMap::new(),
            type_declarations: BTreeMap::new(),
            conditional_type_names: BTreeSet::new(),
            top_level_binding_names: BTreeMap::new(),
        }
    }

    fn build(program: &'a CheckedAnalysisProgram) -> Self {
        let mut index = Self::empty(program);
        for declaration in program.declarations.iter() {
            let occurrence = CheckedDeclarationOccurrenceId::from_sourced(declaration);
            index.declarations.insert(occurrence.clone(), declaration);
            index.index_statement(declaration, declaration.statement.as_ref(), &[]);
            index.index_callable_declaration(declaration);
            if let Stmt::Bind(pattern, _, _) = declaration.statement.as_ref() {
                index.index_top_level_binding_names(declaration, pattern, Vec::new());
            }
            if let Stmt::TypeDecl(type_declaration) = declaration.statement.as_ref() {
                index.type_declarations.insert(occurrence, type_declaration);
                if let TypeDecl::WhenType { name, .. } = type_declaration {
                    index.conditional_type_names.insert(name.clone());
                }
            }
        }
        index
    }

    /// Build only the global callable directory needed to resolve a
    /// request-rooted mechanism trace. Expression and rule syntax is indexed
    /// lazily when the reachability worklist enters its owning declaration.
    /// This preserves global scoped-member ambiguity without retaining every
    /// expression in a large imported law corpus.
    fn build_mechanism_headers(program: &'a CheckedAnalysisProgram) -> Self {
        let mut index = Self::empty(program);
        for declaration in program.declarations.iter() {
            let occurrence = CheckedDeclarationOccurrenceId::from_sourced(declaration);
            index.declarations.insert(occurrence, declaration);
            index.index_callable_declaration(declaration);
        }
        index
    }

    fn index_declaration_syntax(&mut self, declaration: &CheckedDeclarationOccurrenceId) -> bool {
        let Some(declaration) = self.declarations.get(declaration).copied() else {
            return false;
        };
        self.index_statement(declaration, declaration.statement.as_ref(), &[]);
        true
    }

    fn index_top_level_binding_names(
        &mut self,
        declaration: &SourcedStmt,
        pattern: &Pat,
        path: Vec<u32>,
    ) {
        match pattern {
            Pat::Var(name) => {
                let mut binder_path = vec![CheckedResolutionRecorder::BINDER_PATTERN];
                binder_path.extend(path);
                self.top_level_binding_names.insert(
                    CheckedTopLevelBindingId {
                        declaration: CheckedDeclarationOccurrenceId::from_sourced(declaration),
                        binder_path: binder_path.into_boxed_slice(),
                    },
                    name.clone().into_boxed_str(),
                );
            }
            Pat::Con(_, children) => {
                for (index, child) in children.iter().enumerate() {
                    let mut child_path = path.clone();
                    child_path.push(index as u32);
                    self.index_top_level_binding_names(declaration, child, child_path);
                }
            }
            Pat::NamedCon(_, fields) => {
                for (index, (_, child)) in fields.iter().enumerate() {
                    let mut child_path = path.clone();
                    child_path.push(index as u32);
                    self.index_top_level_binding_names(declaration, child, child_path);
                }
            }
            Pat::As(child, name) => {
                self.index_top_level_binding_names(declaration, child, path.clone());
                let mut binder_path = vec![CheckedResolutionRecorder::BINDER_PATTERN];
                binder_path.extend(path);
                binder_path.push(u32::MAX);
                self.top_level_binding_names.insert(
                    CheckedTopLevelBindingId {
                        declaration: CheckedDeclarationOccurrenceId::from_sourced(declaration),
                        binder_path: binder_path.into_boxed_slice(),
                    },
                    name.clone().into_boxed_str(),
                );
            }
            Pat::Wild | Pat::Lit(_) => {}
        }
    }

    fn expression_site(&self, declaration: &SourcedStmt, path: &[u32]) -> ExprSiteId {
        self.program.expression_site(declaration, path.to_vec())
    }

    fn expression(&self, site: &ExprSiteId) -> Option<&'a Expr> {
        if site.analysis_program != self.program.id {
            return None;
        }
        self.expressions
            .get(&site.normalized_declaration_ordinal)?
            .get(site.ast_path.as_ref())
            .copied()
    }

    fn contains_expression(&self, site: &ExprSiteId) -> bool {
        self.expression(site).is_some()
    }

    fn index_statement(&mut self, declaration: &'a SourcedStmt, statement: &'a Stmt, path: &[u32]) {
        if let Stmt::Rule(rule) = statement {
            self.rules.insert(
                (
                    CheckedDeclarationOccurrenceId::from_sourced(declaration),
                    path.to_vec().into_boxed_slice(),
                ),
                rule,
            );
        }
        let mut child_index = 0_u32;
        visit_ast_stmt_children(statement, &mut |child| {
            let mut child_path = path.to_vec();
            child_path.push(child_index);
            child_index = child_index
                .checked_add(1)
                .expect("checked AST child count fits u32");
            match child {
                AstChild::Expr(expression) => {
                    self.index_expression(declaration, expression, &child_path)
                }
                AstChild::Stmt(statement) => {
                    self.index_statement(declaration, statement, &child_path)
                }
            }
        });
    }

    fn index_expression(
        &mut self,
        declaration: &'a SourcedStmt,
        expression: &'a Expr,
        path: &[u32],
    ) {
        self.expressions
            .entry(declaration.normalized_ordinal)
            .or_default()
            .insert(path.to_vec().into_boxed_slice(), expression);
        let mut child_index = 0_u32;
        visit_ast_expr_children(expression, &mut |child| {
            let mut child_path = path.to_vec();
            child_path.push(child_index);
            child_index = child_index
                .checked_add(1)
                .expect("checked AST child count fits u32");
            match child {
                AstChild::Expr(expression) => {
                    self.index_expression(declaration, expression, &child_path)
                }
                AstChild::Stmt(statement) => {
                    self.index_statement(declaration, statement, &child_path)
                }
            }
        });
    }

    fn structural_binder(
        &self,
        declaration: &SourcedStmt,
        ast_path: &[u32],
        binder_path: Vec<u32>,
    ) -> CheckedBinderSiteId {
        CheckedBinderSiteId::Structural {
            analysis_program: self.program.id.clone(),
            declaration: declaration.id.clone(),
            normalized_declaration_ordinal: declaration.normalized_ordinal,
            ast_path: ast_path.to_vec().into_boxed_slice(),
            binder_path: binder_path.into_boxed_slice(),
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn insert_callable(
        &mut self,
        declaration: &'a SourcedStmt,
        structural_path: &[u32],
        runtime_name: &'a str,
        parameters: &'a [Param],
        return_type: Option<&'a Ty>,
        effects: &'a [String],
        body_path: Vec<u32>,
        binder_prefix: &[u32],
    ) {
        let callable = CheckedCallableId {
            declaration: CheckedDeclarationOccurrenceId::from_sourced(declaration),
            structural_path: structural_path.to_vec().into_boxed_slice(),
        };
        let parameter_sites = parameters
            .iter()
            .enumerate()
            .map(|(index, _)| {
                let mut binder_path = binder_prefix.to_vec();
                binder_path.extend([CheckedResolutionRecorder::BINDER_PARAMETER, index as u32]);
                self.structural_binder(declaration, &body_path, binder_path)
            })
            .collect::<Vec<_>>()
            .into_boxed_slice();
        self.callables.insert(
            callable,
            CheckedExploreSemanticCallable {
                runtime_name,
                parameters,
                return_type,
                effects,
                body_site: self.expression_site(declaration, &body_path),
                parameter_sites,
            },
        );
    }

    fn index_callable_declaration(&mut self, declaration: &'a SourcedStmt) {
        match declaration.statement.as_ref() {
            Stmt::Defn(Defn::Fn {
                name,
                params,
                ret_ty,
                effects,
                ..
            }) => self.insert_callable(
                declaration,
                &[],
                name,
                params,
                ret_ty.as_ref(),
                effects,
                vec![0],
                &[],
            ),
            Stmt::TypeDecl(TypeDecl::ADT { name, methods, .. })
            | Stmt::TypeDecl(TypeDecl::ImplBlock {
                for_type: name,
                methods,
                ..
            }) => {
                let mut child_index = 0_u32;
                for method in methods {
                    match method {
                        Defn::Fn {
                            name: member,
                            params,
                            ret_ty,
                            effects,
                            ..
                        } => {
                            let structural_path = [child_index];
                            let callable = CheckedCallableId {
                                declaration: CheckedDeclarationOccurrenceId::from_sourced(
                                    declaration,
                                ),
                                structural_path: structural_path.to_vec().into_boxed_slice(),
                            };
                            self.insert_callable(
                                declaration,
                                &structural_path,
                                member,
                                params,
                                ret_ty.as_ref(),
                                effects,
                                vec![child_index],
                                &structural_path,
                            );
                            self.scoped_callables
                                .entry((name.clone(), member.clone(), params.len()))
                                .or_default()
                                .push(callable);
                            child_index += 1;
                        }
                        Defn::Actor { handlers, .. } => {
                            child_index += handlers.len() as u32;
                        }
                        Defn::Module { body, .. } => {
                            child_index += body.len() as u32;
                        }
                    }
                }
            }
            Stmt::TypeDecl(TypeDecl::RuleScope { name, body, .. }) => {
                for (statement_index, statement) in body.iter().enumerate() {
                    let Stmt::Defn(Defn::Fn {
                        name: member,
                        params,
                        ret_ty,
                        effects,
                        ..
                    }) = statement
                    else {
                        continue;
                    };
                    let structural_path = [statement_index as u32];
                    let callable = CheckedCallableId {
                        declaration: CheckedDeclarationOccurrenceId::from_sourced(declaration),
                        structural_path: structural_path.to_vec().into_boxed_slice(),
                    };
                    self.insert_callable(
                        declaration,
                        &structural_path,
                        member,
                        params,
                        ret_ty.as_ref(),
                        effects,
                        vec![statement_index as u32, 0],
                        &[],
                    );
                    let effective_arity = params
                        .iter()
                        .filter(|parameter| parameter.name.as_str() != "self")
                        .count();
                    self.scoped_callables
                        .entry((name.clone(), member.clone(), effective_arity))
                        .or_default()
                        .push(callable);
                }
            }
            _ => {}
        }
    }
}

/// Control sites that the relational mechanism ABI can retain today. The
/// checked source index contains every expression; this smaller enum prevents
/// an ordinary value node that happens to share a span from being selected as
/// a dynamic control occurrence.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) enum CheckedInterpreterMechanismExpressionKind {
    Application,
    IfDecision,
    MatchDecision,
    ShortCircuitAnd,
    ShortCircuitOr,
}

impl CheckedInterpreterMechanismExpressionKind {
    fn from_expression(expression: &Expr) -> Option<Self> {
        match &expression.kind {
            ExprKind::App(_, _) => Some(Self::Application),
            ExprKind::If(_, _, _) => Some(Self::IfDecision),
            ExprKind::Match(_, _) => Some(Self::MatchDecision),
            ExprKind::BinOp(operator, _, _) if operator == "&&" => Some(Self::ShortCircuitAnd),
            ExprKind::BinOp(operator, _, _) if operator == "||" => Some(Self::ShortCircuitOr),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
enum CheckedInterpreterMechanismOwner {
    Callable(CheckedCallableId),
    RuleCandidate {
        family: RuleDispatchKey,
        source_order: usize,
    },
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct CheckedInterpreterMechanismExpressionKey {
    owner: CheckedInterpreterMechanismOwner,
    kind: CheckedInterpreterMechanismExpressionKind,
    span_start: usize,
    span_end: usize,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct CheckedInterpreterMechanismExpressionCandidate {
    site: ExprSiteId,
    structural_digest: [u8; 32],
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CheckedInterpreterMechanismBuiltinCallback {
    site: ExprSiteId,
    kind: CheckedInterpreterMechanismBuiltinCallbackKind,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CheckedInterpreterMechanismBuiltinCallbackKind {
    /// Named functions, rule-family values, and checked callable binders must
    /// consume this exact target by entering a runtime activation.
    Activation(CheckedCallTarget),
    /// Anonymous lambdas keep the enclosing checked owner today, but their
    /// runtime closure must still match this exact producer-owned source body.
    InlineLambda {
        parameters: Box<[Box<str>]>,
        body_span: Span,
        body_digest: [u8; 32],
    },
}

fn checked_interpreter_mechanism_builtin_callback_contract(
    target: &CheckedCallTarget,
) -> Option<(usize, usize)> {
    let CheckedCallTarget::Builtin {
        canonical_name,
        arity,
    } = target
    else {
        return None;
    };
    match (canonical_name.as_ref(), *arity) {
        (
            "map" | "filter" | "sort_by" | "any" | "all" | "find" | "flat_map" | "take_while"
            | "drop_while" | "count_by" | "partition" | "subscribe",
            2,
        ) => Some((1, 1)),
        ("foldl" | "scan" | "reduce", 3) => Some((2, 2)),
        _ => None,
    }
}

#[derive(Debug, Clone)]
pub(crate) struct CheckedInterpreterMechanismCallable {
    callable: CheckedCallableId,
    runtime_name: Box<str>,
    parameters: Box<[Param]>,
    return_type: Option<Ty>,
    effects: Box<[String]>,
    body_site: ExprSiteId,
    body_digest: [u8; 32],
    body: Expr,
}

impl CheckedInterpreterMechanismCallable {
    pub(crate) fn body(&self) -> &Expr {
        &self.body
    }

    pub(crate) fn parameters(&self) -> &[Param] {
        &self.parameters
    }
}

/// Producer-owned lookup table used only during fresh interpreter replay.
///
/// Runtime spans and span-free structural digests are lookup annotations,
/// never identities. They are resolved inside an already selected checked
/// callable/rule candidate and must identify exactly one producer-minted
/// `ExprSiteId`; genuinely indistinguishable collisions therefore fail closed.
/// Stable mechanism identities are always derived from the checked IDs retained
/// in this catalog.
#[derive(Debug, Clone)]
pub(crate) struct CheckedInterpreterMechanismCatalog {
    analysis_program: AnalysisProgramId,
    expressions: BTreeMap<
        CheckedInterpreterMechanismExpressionKey,
        Box<[CheckedInterpreterMechanismExpressionCandidate]>,
    >,
    call_targets: BTreeMap<ExprSiteId, CheckedCallTarget>,
    builtin_callbacks: BTreeMap<(ExprSiteId, usize), CheckedInterpreterMechanismBuiltinCallback>,
    callables: BTreeMap<CheckedCallableId, CheckedInterpreterMechanismCallable>,
    scoped_callables: BTreeMap<(String, String, usize), Box<[CheckedCallableId]>>,
    rule_candidates: BTreeMap<(RuleDispatchKey, usize), CheckedRuleCandidateResolution>,
    rule_candidate_digests: BTreeMap<(RuleDispatchKey, usize), [u8; 32]>,
}

impl CheckedInterpreterMechanismCatalog {
    pub(crate) fn from_checked<'root>(
        program: &CheckedAnalysisProgram,
        resolutions: &CheckedResolutionArtifacts,
        roots: impl IntoIterator<Item = (&'root ExprSiteId, &'root CheckedCallableId)>,
    ) -> Result<Self, CheckedInterpreterMechanismTraceError> {
        if program.id != resolutions.analysis_program || !resolutions.source_snapshot_coherent {
            return Err(CheckedInterpreterMechanismTraceError::CatalogScopeMismatch);
        }
        let mut roots = roots.into_iter().peekable();
        if roots.peek().is_none() {
            return Ok(Self {
                analysis_program: program.id.clone(),
                expressions: BTreeMap::new(),
                call_targets: BTreeMap::new(),
                builtin_callbacks: BTreeMap::new(),
                callables: BTreeMap::new(),
                scoped_callables: BTreeMap::new(),
                rule_candidates: BTreeMap::new(),
                rule_candidate_digests: BTreeMap::new(),
            });
        }

        // The global header pass retains callable identities and scoped-member
        // ambiguity, but deliberately omits expression and rule syntax. The
        // worklist below materializes only declarations transitively reachable
        // from this checked query's mechanism observers.
        let mut index = CheckedExploreSemanticIndex::build_mechanism_headers(program);
        let mut expression_sites = BTreeMap::<
            CheckedInterpreterMechanismExpressionKey,
            Vec<CheckedInterpreterMechanismExpressionCandidate>,
        >::new();
        let mut call_targets = BTreeMap::new();
        let mut builtin_callbacks = BTreeMap::new();
        let mut callables = BTreeMap::new();
        let mut scoped_callables = BTreeMap::new();
        let mut rule_candidates = BTreeMap::new();
        let mut rule_candidate_digests = BTreeMap::new();
        let mut pending_callables = Vec::new();
        let mut pending_rule_families = Vec::new();
        let mut visited_callables = BTreeSet::new();
        let mut visited_rule_families = BTreeSet::new();
        let mut indexed_declarations = BTreeSet::new();

        for (template_site, endpoint_template) in roots {
            if template_site.analysis_program != program.id {
                return Err(CheckedInterpreterMechanismTraceError::CatalogScopeMismatch);
            }
            if resolutions.unsupported_sites.contains_key(template_site) {
                return Err(
                    CheckedInterpreterMechanismTraceError::UnsupportedCheckedSite(
                        template_site.clone(),
                    ),
                );
            }
            let target = resolutions
                .expressions
                .get(template_site)
                .ok_or_else(|| {
                    CheckedInterpreterMechanismTraceError::CheckedSiteMissing(template_site.clone())
                })?
                .call_target
                .clone()
                .ok_or_else(|| {
                    CheckedInterpreterMechanismTraceError::CheckedCallTargetMissing(
                        template_site.clone(),
                    )
                })?;
            if !matches!(
                &target,
                CheckedCallTarget::Function { callable, arity: 2 }
                    if callable == endpoint_template
            ) {
                return Err(CheckedInterpreterMechanismTraceError::EndpointTemplateMismatch);
            }
            if let Some(previous) = call_targets.insert(template_site.clone(), target.clone()) {
                if previous != target {
                    return Err(
                        CheckedInterpreterMechanismTraceError::CheckedCallTargetMismatch(
                            template_site.clone(),
                        ),
                    );
                }
            }
            pending_callables.push(endpoint_template.clone());
        }

        while !pending_callables.is_empty() || !pending_rule_families.is_empty() {
            while let Some(callable_id) = pending_callables.pop() {
                if !visited_callables.insert(callable_id.clone()) {
                    continue;
                }
                let callable = index.callables.get(&callable_id).cloned().ok_or_else(|| {
                    CheckedInterpreterMechanismTraceError::CheckedCallableMissing(
                        callable_id.clone(),
                    )
                })?;
                if indexed_declarations.insert(callable_id.declaration.clone())
                    && !index.index_declaration_syntax(&callable_id.declaration)
                {
                    return Err(CheckedInterpreterMechanismTraceError::CallableBodyMissing(
                        callable_id,
                    ));
                }
                let body = index.expression(&callable.body_site).ok_or_else(|| {
                    CheckedInterpreterMechanismTraceError::CallableBodyMissing(callable_id.clone())
                })?;
                callables.insert(
                    callable_id.clone(),
                    CheckedInterpreterMechanismCallable {
                        callable: callable_id.clone(),
                        runtime_name: callable.runtime_name.into(),
                        parameters: callable.parameters.to_vec().into_boxed_slice(),
                        return_type: callable.return_type.cloned(),
                        effects: callable.effects.to_vec().into_boxed_slice(),
                        body_site: callable.body_site.clone(),
                        body_digest: checked_interpreter_mechanism_body_digest(body),
                        body: (*body).clone(),
                    },
                );
                let mut discovered_targets = Vec::new();
                Self::index_traceable_expression_slice(
                    &index,
                    resolutions,
                    CheckedInterpreterMechanismOwner::Callable(callable_id),
                    std::slice::from_ref(&callable.body_site),
                    &mut expression_sites,
                    &mut call_targets,
                    &mut builtin_callbacks,
                    &mut discovered_targets,
                )?;
                for target in discovered_targets {
                    Self::enqueue_reachable_target(
                        &index,
                        &target,
                        &mut pending_callables,
                        &mut pending_rule_families,
                        &mut scoped_callables,
                    );
                }
            }

            while let Some(family) = pending_rule_families.pop() {
                if !visited_rule_families.insert(family.clone()) {
                    continue;
                }
                let resolution =
                    resolutions
                        .rule_families
                        .get(&family)
                        .cloned()
                        .ok_or_else(|| {
                            CheckedInterpreterMechanismTraceError::RuleFamilyMissing(family.clone())
                        })?;
                for candidate in resolution.candidates.iter() {
                    if indexed_declarations.insert(candidate.declaration.clone())
                        && !index.index_declaration_syntax(&candidate.declaration)
                    {
                        return Err(
                            CheckedInterpreterMechanismTraceError::RuleCandidateMissing {
                                family: family.clone(),
                                source_order: candidate.source_order,
                            },
                        );
                    }
                    let key = (family.clone(), candidate.source_order);
                    if rule_candidates
                        .insert(key.clone(), candidate.clone())
                        .is_some()
                    {
                        return Err(
                            CheckedInterpreterMechanismTraceError::DuplicateRuleCandidate {
                                family: family.clone(),
                                source_order: candidate.source_order,
                            },
                        );
                    }
                    let rule = index
                        .rules
                        .get(&(
                            candidate.declaration.clone(),
                            candidate.statement_path.clone(),
                        ))
                        .ok_or_else(|| {
                            CheckedInterpreterMechanismTraceError::RuleCandidateMissing {
                                family: family.clone(),
                                source_order: candidate.source_order,
                            }
                        })?;
                    rule_candidate_digests
                        .insert(key, checked_interpreter_mechanism_rule_digest(rule));
                    let roots = candidate
                        .condition_site
                        .iter()
                        .chain(candidate.value_site.iter())
                        .cloned()
                        .collect::<Vec<_>>();
                    let mut discovered_targets = Vec::new();
                    Self::index_traceable_expression_slice(
                        &index,
                        resolutions,
                        CheckedInterpreterMechanismOwner::RuleCandidate {
                            family: family.clone(),
                            source_order: candidate.source_order,
                        },
                        &roots,
                        &mut expression_sites,
                        &mut call_targets,
                        &mut builtin_callbacks,
                        &mut discovered_targets,
                    )?;
                    for target in discovered_targets {
                        Self::enqueue_reachable_target(
                            &index,
                            &target,
                            &mut pending_callables,
                            &mut pending_rule_families,
                            &mut scoped_callables,
                        );
                    }
                }
            }
        }

        Ok(Self {
            analysis_program: program.id.clone(),
            expressions: expression_sites
                .into_iter()
                .map(|(key, mut sites)| {
                    sites.sort();
                    sites.dedup();
                    (key, sites.into_boxed_slice())
                })
                .collect(),
            call_targets,
            builtin_callbacks,
            callables,
            scoped_callables,
            rule_candidates,
            rule_candidate_digests,
        })
    }

    fn enqueue_reachable_target(
        index: &CheckedExploreSemanticIndex<'_>,
        target: &CheckedCallTarget,
        pending_callables: &mut Vec<CheckedCallableId>,
        pending_rule_families: &mut Vec<RuleDispatchKey>,
        scoped_callables: &mut BTreeMap<(String, String, usize), Box<[CheckedCallableId]>>,
    ) {
        match target {
            CheckedCallTarget::Function { callable, .. } => {
                pending_callables.push(callable.clone());
            }
            CheckedCallTarget::RuleFamily(family)
            | CheckedCallTarget::ScopedMember {
                rule_family: Some(family),
                ..
            } => pending_rule_families.push(family.clone()),
            CheckedCallTarget::ScopedMember {
                owner_type,
                member,
                arity,
                rule_family: None,
            } => {
                let key = (owner_type.to_string(), member.to_string(), *arity);
                if scoped_callables.contains_key(&key) {
                    return;
                }
                let Some(candidates) = index.scoped_callables.get(&key) else {
                    return;
                };
                let mut candidates = candidates.clone();
                candidates.sort();
                candidates.dedup();
                if let [callable] = candidates.as_slice() {
                    pending_callables.push(callable.clone());
                }
                scoped_callables.insert(key, candidates.into_boxed_slice());
            }
            CheckedCallTarget::Builtin { .. }
            | CheckedCallTarget::Constructor { .. }
            | CheckedCallTarget::BoundCallable { .. } => {}
        }
    }

    fn checked_builtin_callback(
        index: &CheckedExploreSemanticIndex<'_>,
        resolutions: &CheckedResolutionArtifacts,
        callback_site: &ExprSiteId,
        callback_expression: &Expr,
        callback_arity: usize,
    ) -> Result<CheckedInterpreterMechanismBuiltinCallback, CheckedInterpreterMechanismTraceError>
    {
        if resolutions.unsupported_sites.contains_key(callback_site) {
            return Err(
                CheckedInterpreterMechanismTraceError::UnsupportedCheckedSite(
                    callback_site.clone(),
                ),
            );
        }
        let resolution = resolutions.expressions.get(callback_site).ok_or_else(|| {
            CheckedInterpreterMechanismTraceError::CheckedSiteMissing(callback_site.clone())
        })?;
        let kind = match (&callback_expression.kind, &resolution.value_binding) {
            (ExprKind::Lambda(parameters, body), _)
                if matches!(
                    &resolution.resolved_type,
                    CheckedExpressionType::Callable {
                        parameters: checked_parameters,
                        ..
                    } if checked_parameters.len() == callback_arity
                ) =>
            {
                CheckedInterpreterMechanismBuiltinCallbackKind::InlineLambda {
                    parameters: parameters
                        .iter()
                        .map(|parameter| parameter.name.clone().into_boxed_str())
                        .collect::<Vec<_>>()
                        .into_boxed_slice(),
                    body_span: body.span,
                    body_digest: checked_interpreter_mechanism_body_digest(body),
                }
            }
            (_, Some(CheckedValueBinding::Callable(callable))) => {
                let arity = index
                    .callables
                    .get(callable)
                    .map(|entry| entry.parameters.len())
                    .ok_or_else(|| {
                        CheckedInterpreterMechanismTraceError::CheckedCallableMissing(
                            callable.clone(),
                        )
                    })?;
                if arity != callback_arity {
                    return Err(
                        CheckedInterpreterMechanismTraceError::CheckedCallTargetMismatch(
                            callback_site.clone(),
                        ),
                    );
                }
                CheckedInterpreterMechanismBuiltinCallbackKind::Activation(
                    CheckedCallTarget::Function {
                        callable: callable.clone(),
                        arity,
                    },
                )
            }
            (_, Some(CheckedValueBinding::RuleFamily(family))) => {
                if family.arity != callback_arity {
                    return Err(
                        CheckedInterpreterMechanismTraceError::CheckedCallTargetMismatch(
                            callback_site.clone(),
                        ),
                    );
                }
                CheckedInterpreterMechanismBuiltinCallbackKind::Activation(
                    CheckedCallTarget::RuleFamily(family.clone()),
                )
            }
            (_, Some(CheckedValueBinding::Binder { site: binder, .. })) if callback_arity == 1 => {
                let CheckedExpressionType::Resolved(Ty::Arrow(parameter, result)) =
                    &resolution.resolved_type
                else {
                    return Err(
                        CheckedInterpreterMechanismTraceError::CheckedCallTargetMissing(
                            callback_site.clone(),
                        ),
                    );
                };
                CheckedInterpreterMechanismBuiltinCallbackKind::Activation(
                    CheckedCallTarget::BoundCallable {
                        binder: binder.clone(),
                        parameter_type: TypeChecker::canonical_explore_ty_name(parameter)
                            .into_boxed_str(),
                        result_type: TypeChecker::canonical_explore_ty_name(result)
                            .into_boxed_str(),
                        arity: 1,
                    },
                )
            }
            _ => {
                return Err(
                    CheckedInterpreterMechanismTraceError::CheckedCallTargetMissing(
                        callback_site.clone(),
                    ),
                )
            }
        };
        Ok(CheckedInterpreterMechanismBuiltinCallback {
            site: callback_site.clone(),
            kind,
        })
    }

    fn index_traceable_expression_slice(
        index: &CheckedExploreSemanticIndex<'_>,
        resolutions: &CheckedResolutionArtifacts,
        owner: CheckedInterpreterMechanismOwner,
        roots: &[ExprSiteId],
        expression_sites: &mut BTreeMap<
            CheckedInterpreterMechanismExpressionKey,
            Vec<CheckedInterpreterMechanismExpressionCandidate>,
        >,
        call_targets: &mut BTreeMap<ExprSiteId, CheckedCallTarget>,
        builtin_callbacks: &mut BTreeMap<
            (ExprSiteId, usize),
            CheckedInterpreterMechanismBuiltinCallback,
        >,
        discovered_targets: &mut Vec<CheckedCallTarget>,
    ) -> Result<(), CheckedInterpreterMechanismTraceError> {
        for root in roots {
            if root.analysis_program != index.program.id {
                return Err(CheckedInterpreterMechanismTraceError::CatalogScopeMismatch);
            }
            let declaration_expressions = index
                .expressions
                .get(&root.normalized_declaration_ordinal)
                .ok_or_else(|| {
                    CheckedInterpreterMechanismTraceError::CheckedSiteMissing(root.clone())
                })?;
            for (path, expression) in declaration_expressions.range(root.ast_path.clone()..) {
                if !path.starts_with(&root.ast_path) {
                    break;
                }
                let site = ExprSiteId {
                    analysis_program: root.analysis_program.clone(),
                    declaration: root.declaration.clone(),
                    normalized_declaration_ordinal: root.normalized_declaration_ordinal,
                    ast_path: path.clone(),
                };
                // The catalog covers the whole checked program, while one
                // mechanism request reaches only a dependency slice. Keep an
                // unrelated unsupported site from disabling every request;
                // if execution reaches it, scoped lookup fails closed and the
                // adapter records instrumentation-unavailable for that case.
                if resolutions.unsupported_sites.contains_key(&site) {
                    continue;
                }
                let checked = resolutions.expressions.get(&site).ok_or_else(|| {
                    CheckedInterpreterMechanismTraceError::CheckedSiteMissing(site.clone())
                })?;
                match checked.value_binding.as_ref() {
                    Some(CheckedValueBinding::Callable(callable)) => {
                        let arity = index
                            .callables
                            .get(callable)
                            .map(|entry| entry.parameters.len())
                            .ok_or_else(|| {
                                CheckedInterpreterMechanismTraceError::CheckedCallableMissing(
                                    callable.clone(),
                                )
                            })?;
                        discovered_targets.push(CheckedCallTarget::Function {
                            callable: callable.clone(),
                            arity,
                        });
                    }
                    Some(CheckedValueBinding::RuleFamily(family)) => {
                        discovered_targets.push(CheckedCallTarget::RuleFamily(family.clone()));
                    }
                    _ => {}
                }
                let Some(kind) =
                    CheckedInterpreterMechanismExpressionKind::from_expression(expression)
                else {
                    continue;
                };
                if matches!(kind, CheckedInterpreterMechanismExpressionKind::Application) {
                    let target = checked.call_target.clone().ok_or_else(|| {
                        CheckedInterpreterMechanismTraceError::CheckedCallTargetMissing(
                            site.clone(),
                        )
                    })?;
                    if let Some(previous) = call_targets.insert(site.clone(), target.clone()) {
                        if previous != target {
                            return Err(
                                CheckedInterpreterMechanismTraceError::CheckedCallTargetMismatch(
                                    site.clone(),
                                ),
                            );
                        }
                    }
                    if let Some((callback_index, callback_arity)) =
                        checked_interpreter_mechanism_builtin_callback_contract(&target)
                    {
                        let ExprKind::App(_, arguments) = &expression.kind else {
                            return Err(
                                CheckedInterpreterMechanismTraceError::CheckedCallTargetMismatch(
                                    site.clone(),
                                ),
                            );
                        };
                        let callback_expression =
                            arguments.get(callback_index).ok_or_else(|| {
                                CheckedInterpreterMechanismTraceError::CheckedCallTargetMismatch(
                                    site.clone(),
                                )
                            })?;
                        let mut callback_path = site.ast_path.to_vec();
                        callback_path.push((callback_index + 1) as u32);
                        let callback_site = ExprSiteId {
                            analysis_program: site.analysis_program.clone(),
                            declaration: site.declaration.clone(),
                            normalized_declaration_ordinal: site.normalized_declaration_ordinal,
                            ast_path: callback_path.into_boxed_slice(),
                        };
                        let callback = Self::checked_builtin_callback(
                            index,
                            resolutions,
                            &callback_site,
                            callback_expression,
                            callback_arity,
                        )?;
                        if let Some(previous) = builtin_callbacks
                            .insert((site.clone(), callback_index), callback.clone())
                        {
                            if previous != callback {
                                return Err(
                                    CheckedInterpreterMechanismTraceError::CheckedCallTargetMismatch(
                                        callback_site,
                                    ),
                                );
                            }
                        }
                        if let CheckedInterpreterMechanismBuiltinCallbackKind::Activation(
                            callback_target,
                        ) = callback.kind
                        {
                            discovered_targets.push(callback_target);
                        }
                    }
                    discovered_targets.push(target);
                }
                expression_sites
                    .entry(CheckedInterpreterMechanismExpressionKey {
                        owner: owner.clone(),
                        kind,
                        span_start: expression.span.start,
                        span_end: expression.span.end,
                    })
                    .or_default()
                    .push(CheckedInterpreterMechanismExpressionCandidate {
                        site: site.clone(),
                        structural_digest: checked_interpreter_mechanism_expression_digest(
                            expression,
                        ),
                    });
            }
        }
        Ok(())
    }

    pub(crate) fn callable(
        &self,
        callable: &CheckedCallableId,
    ) -> Option<&CheckedInterpreterMechanismCallable> {
        self.callables.get(callable)
    }

    fn bound_runtime_callable(
        &self,
        name: Option<&str>,
        parameters: &[String],
        body: &Expr,
    ) -> Result<CheckedCallableId, CheckedInterpreterMechanismTraceError> {
        let Some(name) = name else {
            return Err(
                CheckedInterpreterMechanismTraceError::BoundCallableTargetMissing {
                    arity: parameters.len(),
                },
            );
        };
        let body_digest = checked_interpreter_mechanism_body_digest(body);
        let candidates = self
            .callables
            .values()
            .filter(|checked| {
                checked.runtime_name.as_ref() == name
                    && checked.parameters.len() == parameters.len()
                    && checked
                        .parameters
                        .iter()
                        .zip(parameters)
                        .all(|(expected, actual)| expected.name.as_str() == actual.as_str())
                    && checked.body.span == body.span
                    && checked.body_digest == body_digest
            })
            .map(|checked| checked.callable.clone())
            .collect::<Vec<_>>();
        match candidates.as_slice() {
            [callable] => Ok(callable.clone()),
            [] => Err(
                CheckedInterpreterMechanismTraceError::BoundCallableTargetMissing {
                    arity: parameters.len(),
                },
            ),
            _ => Err(
                CheckedInterpreterMechanismTraceError::AmbiguousBoundCallableTarget {
                    arity: parameters.len(),
                    candidates: candidates.len(),
                },
            ),
        }
    }

    fn contains_rule_family(&self, family: &RuleDispatchKey) -> bool {
        self.rule_candidates
            .keys()
            .any(|(candidate, _)| candidate == family)
    }

    fn expression_site(
        &self,
        owner: &CheckedInterpreterMechanismOwner,
        kind: CheckedInterpreterMechanismExpressionKind,
        expression: &Expr,
    ) -> Result<ExprSiteId, CheckedInterpreterMechanismTraceError> {
        let key = CheckedInterpreterMechanismExpressionKey {
            owner: owner.clone(),
            kind,
            span_start: expression.span.start,
            span_end: expression.span.end,
        };
        match self.expressions.get(&key).map(Box::as_ref) {
            Some([candidate]) => Ok(candidate.site.clone()),
            Some(candidates) => {
                let structural_digest = checked_interpreter_mechanism_expression_digest(expression);
                let matching = candidates
                    .iter()
                    .filter(|candidate| candidate.structural_digest == structural_digest)
                    .collect::<Vec<_>>();
                match matching.as_slice() {
                    [candidate] => Ok(candidate.site.clone()),
                    [] => Err(
                        CheckedInterpreterMechanismTraceError::RuntimeExpressionMissing {
                            kind,
                            span: expression.span,
                        },
                    ),
                    candidates => Err(
                        CheckedInterpreterMechanismTraceError::AmbiguousRuntimeExpression {
                            kind,
                            span: expression.span,
                            candidates: candidates.len(),
                        },
                    ),
                }
            }
            None => Err(
                CheckedInterpreterMechanismTraceError::RuntimeExpressionMissing {
                    kind,
                    span: expression.span,
                },
            ),
        }
    }

    fn call_target(
        &self,
        site: &ExprSiteId,
    ) -> Result<CheckedCallTarget, CheckedInterpreterMechanismTraceError> {
        self.call_targets.get(site).cloned().ok_or_else(|| {
            CheckedInterpreterMechanismTraceError::CheckedCallTargetMissing(site.clone())
        })
    }

    fn builtin_callback(
        &self,
        application_site: &ExprSiteId,
        argument_index: usize,
    ) -> Result<CheckedInterpreterMechanismBuiltinCallback, CheckedInterpreterMechanismTraceError>
    {
        self.builtin_callbacks
            .get(&(application_site.clone(), argument_index))
            .cloned()
            .ok_or_else(|| {
                CheckedInterpreterMechanismTraceError::CheckedCallTargetMissing(
                    application_site.clone(),
                )
            })
    }

    fn rule_candidate(
        &self,
        family: &RuleDispatchKey,
        source_order: usize,
    ) -> Result<CheckedRuleCandidateResolution, CheckedInterpreterMechanismTraceError> {
        self.rule_candidates
            .get(&(family.clone(), source_order))
            .cloned()
            .ok_or_else(
                || CheckedInterpreterMechanismTraceError::RuleCandidateMissing {
                    family: family.clone(),
                    source_order,
                },
            )
    }

    fn rule_candidate_digest(
        &self,
        family: &RuleDispatchKey,
        source_order: usize,
    ) -> Result<[u8; 32], CheckedInterpreterMechanismTraceError> {
        self.rule_candidate_digests
            .get(&(family.clone(), source_order))
            .copied()
            .ok_or_else(
                || CheckedInterpreterMechanismTraceError::RuleCandidateMissing {
                    family: family.clone(),
                    source_order,
                },
            )
    }

    fn scoped_callable(
        &self,
        owner_type: &str,
        member: &str,
        arity: usize,
    ) -> Result<CheckedCallableId, CheckedInterpreterMechanismTraceError> {
        match self
            .scoped_callables
            .get(&(owner_type.to_string(), member.to_string(), arity))
            .map(Box::as_ref)
        {
            Some([callable]) => Ok(callable.clone()),
            Some(callables) => Err(
                CheckedInterpreterMechanismTraceError::AmbiguousScopedCallable {
                    owner_type: owner_type.to_string(),
                    member: member.to_string(),
                    arity,
                    candidates: callables.len(),
                },
            ),
            None => Err(
                CheckedInterpreterMechanismTraceError::ScopedCallableMissing {
                    owner_type: owner_type.to_string(),
                    member: member.to_string(),
                    arity,
                },
            ),
        }
    }
}

fn checked_interpreter_mechanism_body_digest(body: &Expr) -> [u8; 32] {
    Sha256::digest(format!("{:?}", strip_spans_expr(body)).as_bytes()).into()
}

fn checked_interpreter_mechanism_expression_digest(expression: &Expr) -> [u8; 32] {
    checked_interpreter_mechanism_body_digest(expression)
}

fn checked_interpreter_mechanism_rule_digest(rule: &Rule) -> [u8; 32] {
    Sha256::digest(format!("{:?}", strip_spans_rule(rule)).as_bytes()).into()
}

