#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum CheckedInterpreterMechanismTraceError {
    CatalogScopeMismatch,
    CallableBodyMissing(CheckedCallableId),
    CheckedSiteMissing(ExprSiteId),
    UnsupportedCheckedSite(ExprSiteId),
    CheckedCallTargetMissing(ExprSiteId),
    CheckedCallTargetMismatch(ExprSiteId),
    DuplicateRuleCandidate {
        family: RuleDispatchKey,
        source_order: usize,
    },
    RuleFamilyMissing(RuleDispatchKey),
    RuleCandidateMissing {
        family: RuleDispatchKey,
        source_order: usize,
    },
    RuleCandidateBodyMismatch {
        family: RuleDispatchKey,
        source_order: usize,
    },
    RuntimeExpressionMissing {
        kind: CheckedInterpreterMechanismExpressionKind,
        span: Span,
    },
    AmbiguousRuntimeExpression {
        kind: CheckedInterpreterMechanismExpressionKind,
        span: Span,
        candidates: usize,
    },
    ScopedCallableMissing {
        owner_type: String,
        member: String,
        arity: usize,
    },
    AmbiguousScopedCallable {
        owner_type: String,
        member: String,
        arity: usize,
        candidates: usize,
    },
    BoundCallableTargetMissing {
        arity: usize,
    },
    AmbiguousBoundCallableTarget {
        arity: usize,
        candidates: usize,
    },
    EndpointTemplateMismatch,
    CheckedCallableMissing(CheckedCallableId),
    CheckedCallableHasEffects(CheckedCallableId),
    CheckedCallableArity {
        callable: CheckedCallableId,
        expected: usize,
        actual: usize,
    },
    EndpointArgumentType {
        parameter: usize,
    },
    EndpointResultType,
    ActivationTargetMismatch,
    MemoizedRuleSelectionMismatch,
    CallableBodyMismatch(CheckedCallableId),
    MatchHadNoSelectedArm,
    NonBooleanShortCircuit,
    TraceCapacity {
        resource: &'static str,
        actual: usize,
        limit: usize,
    },
    TraceStackMismatch,
}

impl fmt::Display for CheckedInterpreterMechanismTraceError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::CatalogScopeMismatch => formatter.write_str(
                "checked interpreter mechanism catalog belongs to another or incoherent program",
            ),
            Self::CallableBodyMissing(_) => formatter
                .write_str("checked mechanism callable body is absent from the semantic index"),
            Self::CheckedSiteMissing(_) => formatter
                .write_str("checked mechanism expression site is absent from resolution artifacts"),
            Self::UnsupportedCheckedSite(_) => formatter.write_str(
                "checked mechanism expression reaches an unsupported resolution site",
            ),
            Self::CheckedCallTargetMissing(_) => formatter
                .write_str("checked mechanism call site has no exact checked call target"),
            Self::CheckedCallTargetMismatch(_) => formatter
                .write_str("checked mechanism call site has conflicting target identities"),
            Self::DuplicateRuleCandidate { .. } => formatter
                .write_str("checked mechanism rule family repeats one source-order candidate"),
            Self::RuleFamilyMissing(_) => formatter
                .write_str("checked mechanism call reaches an absent rule family"),
            Self::RuleCandidateMissing { .. } => formatter
                .write_str("runtime mechanism rule attempt has no checked candidate identity"),
            Self::RuleCandidateBodyMismatch { .. } => formatter.write_str(
                "runtime mechanism rule candidate disagrees with its checked source body",
            ),
            Self::RuntimeExpressionMissing { kind, span } => write!(
                formatter,
                "runtime {kind:?} at {}..{} has no checked site in the active declaration",
                span.start, span.end
            ),
            Self::AmbiguousRuntimeExpression {
                kind,
                span,
                candidates,
            } => write!(
                formatter,
                "runtime {kind:?} at {}..{} matches {candidates} checked sites in the active declaration",
                span.start, span.end
            ),
            Self::ScopedCallableMissing {
                owner_type,
                member,
                arity,
            } => write!(
                formatter,
                "checked scoped call {owner_type}::{member}/{arity} has no callable identity",
            ),
            Self::AmbiguousScopedCallable {
                owner_type,
                member,
                arity,
                candidates,
            } => write!(
                formatter,
                "checked scoped call {owner_type}::{member}/{arity} has {candidates} callable identities",
            ),
            Self::BoundCallableTargetMissing { arity } => write!(
                formatter,
                "runtime bound call at arity {arity} has no reachable checked callable identity",
            ),
            Self::AmbiguousBoundCallableTarget { arity, candidates } => write!(
                formatter,
                "runtime bound call at arity {arity} matches {candidates} checked callable identities",
            ),
            Self::EndpointTemplateMismatch => formatter.write_str(
                "mechanism endpoint template does not call the requested checked callable",
            ),
            Self::CheckedCallableMissing(_) => {
                formatter.write_str("mechanism endpoint checked callable is absent")
            }
            Self::CheckedCallableHasEffects(_) => formatter
                .write_str("mechanism endpoint checked callable declares effects"),
            Self::CheckedCallableArity {
                expected, actual, ..
            } => write!(
                formatter,
                "mechanism endpoint callable expects {expected} arguments but received {actual}",
            ),
            Self::EndpointArgumentType { parameter } => write!(
                formatter,
                "mechanism endpoint argument {parameter} disagrees with its checked type",
            ),
            Self::EndpointResultType => formatter
                .write_str("mechanism endpoint result disagrees with its checked type"),
            Self::ActivationTargetMismatch => formatter.write_str(
                "runtime mechanism activation disagrees with its checked call target",
            ),
            Self::MemoizedRuleSelectionMismatch => formatter.write_str(
                "runtime mechanism memo reference disagrees with its cold rule selection",
            ),
            Self::CallableBodyMismatch(_) => formatter.write_str(
                "runtime mechanism callable body disagrees with its checked body site",
            ),
            Self::MatchHadNoSelectedArm => formatter.write_str(
                "runtime mechanism match completed without a selected checked arm",
            ),
            Self::NonBooleanShortCircuit => formatter.write_str(
                "runtime mechanism short-circuit expression produced a non-Boolean result",
            ),
            Self::TraceCapacity {
                resource,
                actual,
                limit,
            } => write!(
                formatter,
                "mechanism interpreter trace needs {actual} {resource}; limit is {limit}",
            ),
            Self::TraceStackMismatch => formatter
                .write_str("mechanism interpreter trace ended with an unbalanced semantic stack"),
        }
    }
}

impl std::error::Error for CheckedInterpreterMechanismTraceError {}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum CheckedInterpreterMechanismEvaluationError {
    Trace(CheckedInterpreterMechanismTraceError),
    Runtime(ExploreRuntimeFailure),
}

impl fmt::Display for CheckedInterpreterMechanismEvaluationError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Trace(error) => error.fmt(formatter),
            Self::Runtime(error) => error.fmt(formatter),
        }
    }
}

impl std::error::Error for CheckedInterpreterMechanismEvaluationError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Trace(error) => Some(error),
            Self::Runtime(_) => None,
        }
    }
}

