#[derive(Debug)]
struct CheckedInterpreterMechanismTraceState {
    catalog: Arc<CheckedInterpreterMechanismCatalog>,
    owners: Vec<CheckedInterpreterMechanismOwner>,
    activation_paths: Vec<CheckedInterpreterMechanismActivationPathNode>,
    current_activation_path: CheckedInterpreterMechanismActivationPathId,
    call_stack: Vec<Option<CheckedInterpreterMechanismCallFrame>>,
    dependency_scopes: Vec<Vec<usize>>,
    invocation_ordinals: BTreeMap<
        (
            CheckedInterpreterMechanismActivationPathId,
            ExprSiteId,
            CheckedInterpreterMechanismCallee,
        ),
        u32,
    >,
    visit_ordinals: BTreeMap<
        (
            CheckedInterpreterMechanismActivationPathId,
            CheckedInterpreterMechanismEventSite,
            CheckedInterpreterMechanismEventKind,
        ),
        u32,
    >,
    events: Vec<CheckedInterpreterMechanismEvent>,
    edge_count: usize,
    memoized_rule_reuses: usize,
    diagnostics_enabled: bool,
    attempted_events: u64,
    attempted_event_kinds: [u64; 6],
    directly_event_bearing_activation_paths: Vec<bool>,
    family_diagnostics: BTreeMap<RuleDispatchKey, CheckedInterpreterMechanismFamilyDiagnostics>,
    validated_callable_bodies: BTreeSet<CheckedCallableId>,
    validated_rule_candidates: BTreeSet<(RuleDispatchKey, usize)>,
    error: Option<CheckedInterpreterMechanismTraceError>,
}

impl CheckedInterpreterMechanismTraceState {
    fn new(
        catalog: Arc<CheckedInterpreterMechanismCatalog>,
        template_site: &ExprSiteId,
        callable: &CheckedCallableId,
    ) -> Result<Self, CheckedInterpreterMechanismTraceError> {
        if template_site.analysis_program != catalog.analysis_program {
            return Err(CheckedInterpreterMechanismTraceError::CatalogScopeMismatch);
        }
        match catalog.call_target(template_site)? {
            CheckedCallTarget::Function {
                callable: target,
                arity: 2,
            } if &target == callable => {}
            _ => return Err(CheckedInterpreterMechanismTraceError::EndpointTemplateMismatch),
        }
        if !catalog.callables.contains_key(callable) {
            return Err(
                CheckedInterpreterMechanismTraceError::CheckedCallableMissing(callable.clone()),
            );
        }
        let root_activation = CheckedInterpreterMechanismActivation {
            call_site: template_site.clone(),
            callee: CheckedInterpreterMechanismCallee::Function(callable.clone()),
            invocation_ordinal: 0,
        };
        let root_path = CheckedInterpreterMechanismActivationPathId(0);
        let diagnostics_enabled = env::var_os("FUTURUNA_EXPLORE_TRACE").is_some();
        Ok(Self {
            catalog,
            owners: vec![CheckedInterpreterMechanismOwner::Callable(callable.clone())],
            activation_paths: vec![CheckedInterpreterMechanismActivationPathNode {
                parent: None,
                activation: root_activation,
                depth: 1,
            }],
            current_activation_path: root_path,
            call_stack: Vec::new(),
            dependency_scopes: vec![Vec::new()],
            invocation_ordinals: BTreeMap::new(),
            visit_ordinals: BTreeMap::new(),
            events: Vec::new(),
            edge_count: 0,
            memoized_rule_reuses: 0,
            diagnostics_enabled,
            attempted_events: 0,
            attempted_event_kinds: [0; 6],
            directly_event_bearing_activation_paths: diagnostics_enabled
                .then(|| vec![false])
                .unwrap_or_default(),
            family_diagnostics: BTreeMap::new(),
            validated_callable_bodies: BTreeSet::new(),
            validated_rule_candidates: BTreeSet::new(),
            error: None,
        })
    }

    fn fail(&mut self, error: CheckedInterpreterMechanismTraceError) {
        if self.error.is_none() {
            if env::var_os("FUTURUNA_EXPLORE_TRACE").is_some() {
                eprintln!(
                    "[explore trace] mechanism trace failed: {error}; events={}; edges={}; activation_paths={}; memoized_rule_reuses={}",
                    self.events.len(),
                    self.edge_count,
                    self.activation_paths.len(),
                    self.memoized_rule_reuses,
                );
            }
            self.error = Some(error);
        }
    }

    fn fail_activation_target_mismatch(&mut self, reason: &'static str) {
        if env::var_os("FUTURUNA_EXPLORE_TRACE").is_some() {
            eprintln!(
                "[explore trace] mechanism activation target mismatch: reason={reason}; owner={:?}; call_stack_depth={}; frame={:?}",
                self.current_owner(),
                self.call_stack.len(),
                self.call_stack.last(),
            );
        }
        self.fail(CheckedInterpreterMechanismTraceError::ActivationTargetMismatch);
    }

    fn current_owner(&self) -> Option<&CheckedInterpreterMechanismOwner> {
        self.owners.last()
    }

    fn diagnostic_family_mut(
        &mut self,
        family: &RuleDispatchKey,
    ) -> Option<&mut CheckedInterpreterMechanismFamilyDiagnostics> {
        self.diagnostics_enabled
            .then(|| self.family_diagnostics.entry(family.clone()).or_default())
    }

    fn diagnostic_observe_rule_activation(&mut self, callee: &CheckedInterpreterMechanismCallee) {
        let CheckedInterpreterMechanismCallee::RuleFamily(family) = callee else {
            return;
        };
        if let Some(diagnostics) = self.diagnostic_family_mut(family) {
            diagnostics.activations = diagnostics.activations.saturating_add(1);
        }
    }

    fn diagnostic_observe_cold_rule_dispatch(
        &mut self,
        family: &RuleDispatchKey,
        arguments: &[Value],
    ) {
        if !self.diagnostics_enabled {
            return;
        }
        let argument_digest = checked_exact_observer_memo_encode_arguments(arguments)
            .map(|encoded| Sha256::digest(encoded.as_ref()).into());
        let diagnostics = self.family_diagnostics.entry(family.clone()).or_default();
        diagnostics.cold_dispatches = diagnostics.cold_dispatches.saturating_add(1);
        if let Some(argument_digest) = argument_digest {
            diagnostics
                .canonical_argument_digests
                .insert(argument_digest);
        } else {
            diagnostics.unencodable_argument_calls =
                diagnostics.unencodable_argument_calls.saturating_add(1);
        }
    }

    fn diagnostic_observe_scoped_memo_reuse(&mut self, family: &RuleDispatchKey) {
        if let Some(diagnostics) = self.diagnostic_family_mut(family) {
            diagnostics.scoped_memo_reuses = diagnostics.scoped_memo_reuses.saturating_add(1);
        }
    }

    fn diagnostic_observe_global_memo_reuse(&mut self, family: &RuleDispatchKey) {
        if let Some(diagnostics) = self.diagnostic_family_mut(family) {
            diagnostics.global_memo_reuses = diagnostics.global_memo_reuses.saturating_add(1);
        }
    }

    fn diagnostic_observe_event(&mut self, kind: CheckedInterpreterMechanismEventKind) {
        if !self.diagnostics_enabled {
            return;
        }
        self.attempted_events = self.attempted_events.saturating_add(1);
        let kind_index = match kind {
            CheckedInterpreterMechanismEventKind::RuleAttempt => 0,
            CheckedInterpreterMechanismEventKind::RuleSelection => 1,
            CheckedInterpreterMechanismEventKind::IfDecision => 2,
            CheckedInterpreterMechanismEventKind::MatchDecision => 3,
            CheckedInterpreterMechanismEventKind::ShortCircuitAnd => 4,
            CheckedInterpreterMechanismEventKind::ShortCircuitOr => 5,
        };
        self.attempted_event_kinds[kind_index] =
            self.attempted_event_kinds[kind_index].saturating_add(1);
        if let Some(event_bearing) = self
            .directly_event_bearing_activation_paths
            .get_mut(self.current_activation_path.index())
        {
            *event_bearing = true;
        }
        let family = match self.current_owner() {
            Some(CheckedInterpreterMechanismOwner::RuleCandidate { family, .. }) => {
                Some(family.clone())
            }
            Some(CheckedInterpreterMechanismOwner::Callable(_)) | None => None,
        };
        let Some(family) = family else {
            return;
        };
        let diagnostics = self.family_diagnostics.entry(family).or_default();
        diagnostics.events = diagnostics.events.saturating_add(1);
        match kind {
            CheckedInterpreterMechanismEventKind::RuleAttempt => {
                diagnostics.rule_attempt_events = diagnostics.rule_attempt_events.saturating_add(1);
            }
            CheckedInterpreterMechanismEventKind::RuleSelection => {
                diagnostics.rule_selection_events =
                    diagnostics.rule_selection_events.saturating_add(1);
            }
            CheckedInterpreterMechanismEventKind::IfDecision
            | CheckedInterpreterMechanismEventKind::MatchDecision
            | CheckedInterpreterMechanismEventKind::ShortCircuitAnd
            | CheckedInterpreterMechanismEventKind::ShortCircuitOr => {}
        }
    }

    fn emit_diagnostics(&self) {
        if !self.diagnostics_enabled {
            return;
        }
        let mut retained_activation_paths = self.directly_event_bearing_activation_paths.clone();
        for ordinal in (0..retained_activation_paths.len()).rev() {
            if !retained_activation_paths[ordinal] {
                continue;
            }
            if let Some(parent) = self.activation_paths[ordinal].parent {
                retained_activation_paths[parent.index()] = true;
            }
        }
        let directly_event_bearing = self
            .directly_event_bearing_activation_paths
            .iter()
            .filter(|event_bearing| **event_bearing)
            .count();
        let retained_by_event_closure = retained_activation_paths
            .iter()
            .filter(|retained| **retained)
            .count();
        let ancestor_only = retained_by_event_closure.saturating_sub(directly_event_bearing);
        let prunable_eventless = self
            .activation_paths
            .len()
            .saturating_sub(retained_by_event_closure);
        let cold_dispatches = self
            .family_diagnostics
            .values()
            .map(|diagnostics| diagnostics.cold_dispatches)
            .sum::<u64>();
        let family_argument_keys = self
            .family_diagnostics
            .values()
            .map(|diagnostics| diagnostics.canonical_argument_digests.len() as u64)
            .sum::<u64>();
        let unencodable_argument_calls = self
            .family_diagnostics
            .values()
            .map(|diagnostics| diagnostics.unencodable_argument_calls)
            .sum::<u64>();
        let scoped_memo_reuses = self
            .family_diagnostics
            .values()
            .map(|diagnostics| diagnostics.scoped_memo_reuses)
            .sum::<u64>();
        let global_memo_reuses = self
            .family_diagnostics
            .values()
            .map(|diagnostics| diagnostics.global_memo_reuses)
            .sum::<u64>();
        eprintln!(
            "[explore trace] mechanism diagnostic totals: retained_events={}; attempted_events={}; kinds=rule_attempt:{},rule_selection:{},if:{},match:{},and:{},or:{}; activation_paths={}; direct_event_bearing={}; ancestor_only={}; prunable_eventless={}; cold_dispatches={}; family_argument_keys={}; unencodable_argument_calls={}; global_memo_reuses={}; scoped_memo_reuses={}",
            self.events.len(),
            self.attempted_events,
            self.attempted_event_kinds[0],
            self.attempted_event_kinds[1],
            self.attempted_event_kinds[2],
            self.attempted_event_kinds[3],
            self.attempted_event_kinds[4],
            self.attempted_event_kinds[5],
            self.activation_paths.len(),
            directly_event_bearing,
            ancestor_only,
            prunable_eventless,
            cold_dispatches,
            family_argument_keys,
            unencodable_argument_calls,
            global_memo_reuses,
            scoped_memo_reuses,
        );

        let mut by_events = self.family_diagnostics.iter().collect::<Vec<_>>();
        by_events.sort_by(|(left_family, left), (right_family, right)| {
            right
                .events
                .cmp(&left.events)
                .then_with(|| right.activations.cmp(&left.activations))
                .then_with(|| left_family.cmp(right_family))
        });
        for (rank, (family, diagnostics)) in by_events
            .iter()
            .take(CHECKED_INTERPRETER_MECHANISM_DIAGNOSTIC_TOP_FAMILIES)
            .enumerate()
        {
            let encodable_dispatches = diagnostics
                .cold_dispatches
                .saturating_sub(diagnostics.unencodable_argument_calls);
            let repeated_argument_dispatches = encodable_dispatches
                .saturating_sub(diagnostics.canonical_argument_digests.len() as u64);
            eprintln!(
                "[explore trace] mechanism family by events #{}: scope={}; name={}; arity={}; events={}; activations={}; attempts={}; selections={}; cold_dispatches={}; unique_argument_keys={}; repeated_argument_dispatches={}; unencodable_argument_calls={}; global_memo_reuses={}; scoped_memo_reuses={}",
                rank + 1,
                family.scope.as_deref().unwrap_or("<global>"),
                family.name,
                family.arity,
                diagnostics.events,
                diagnostics.activations,
                diagnostics.rule_attempt_events,
                diagnostics.rule_selection_events,
                diagnostics.cold_dispatches,
                diagnostics.canonical_argument_digests.len(),
                repeated_argument_dispatches,
                diagnostics.unencodable_argument_calls,
                diagnostics.global_memo_reuses,
                diagnostics.scoped_memo_reuses,
            );
        }

        let mut by_activations = self.family_diagnostics.iter().collect::<Vec<_>>();
        by_activations.sort_by(|(left_family, left), (right_family, right)| {
            right
                .activations
                .cmp(&left.activations)
                .then_with(|| right.events.cmp(&left.events))
                .then_with(|| left_family.cmp(right_family))
        });
        for (rank, (family, diagnostics)) in by_activations
            .iter()
            .take(CHECKED_INTERPRETER_MECHANISM_DIAGNOSTIC_TOP_FAMILIES)
            .enumerate()
        {
            eprintln!(
                "[explore trace] mechanism family by activations #{}: scope={}; name={}; arity={}; activations={}; events={}; cold_dispatches={}; unique_argument_keys={}; global_memo_reuses={}; scoped_memo_reuses={}",
                rank + 1,
                family.scope.as_deref().unwrap_or("<global>"),
                family.name,
                family.arity,
                diagnostics.activations,
                diagnostics.events,
                diagnostics.cold_dispatches,
                diagnostics.canonical_argument_digests.len(),
                diagnostics.global_memo_reuses,
                diagnostics.scoped_memo_reuses,
            );
        }
    }

    fn expression_site(
        &mut self,
        kind: CheckedInterpreterMechanismExpressionKind,
        expression: &Expr,
    ) -> Option<ExprSiteId> {
        let Some(owner) = self.current_owner().cloned() else {
            self.fail(CheckedInterpreterMechanismTraceError::TraceStackMismatch);
            return None;
        };
        match self.catalog.expression_site(&owner, kind, expression) {
            Ok(site) => Some(site),
            Err(error) => {
                self.fail(error);
                None
            }
        }
    }

    fn push_call(&mut self, expression: &Expr) {
        let frame = self
            .expression_site(
                CheckedInterpreterMechanismExpressionKind::Application,
                expression,
            )
            .and_then(|site| match self.catalog.call_target(&site) {
                Ok(target) => {
                    let requires_activation = matches!(
                        &target,
                        CheckedCallTarget::Function { .. }
                            | CheckedCallTarget::BoundCallable { .. }
                            | CheckedCallTarget::RuleFamily(_)
                            | CheckedCallTarget::ScopedMember { .. }
                    );
                    Some(CheckedInterpreterMechanismCallFrame {
                        site,
                        target,
                        requires_activation,
                        activation_consumed: false,
                    })
                }
                Err(error) => {
                    self.fail(error);
                    None
                }
            });
        self.call_stack.push(frame);
    }

    fn push_builtin_callback(
        &mut self,
        argument_index: usize,
        applied_arity: usize,
        runtime_callback: &Value,
    ) {
        let outer = self.call_stack.last().cloned().flatten();
        let frame = outer.and_then(|outer| {
            if checked_interpreter_mechanism_builtin_callback_contract(&outer.target).is_none_or(
                |(expected_index, expected_arity)| {
                    expected_index != argument_index || expected_arity != applied_arity
                },
            ) {
                self.fail_activation_target_mismatch("builtin callback contract");
                return None;
            }
            match self.catalog.builtin_callback(&outer.site, argument_index) {
                Ok(callback) => match callback.kind {
                    CheckedInterpreterMechanismBuiltinCallbackKind::Activation(target) => {
                        Some(CheckedInterpreterMechanismCallFrame {
                            site: callback.site,
                            target,
                            requires_activation: true,
                            activation_consumed: false,
                        })
                    }
                    CheckedInterpreterMechanismBuiltinCallbackKind::InlineLambda {
                        parameters,
                        body_span,
                        body_digest,
                    } => {
                        let matches = matches!(
                            runtime_callback,
                            Value::Closure {
                                name: None,
                                params,
                                body,
                                ..
                            } if params.iter().map(String::as_str).eq(
                                parameters.iter().map(|parameter| parameter.as_ref())
                            ) && body.span == body_span
                                && checked_interpreter_mechanism_body_digest(body) == body_digest
                        );
                        if !matches {
                            self.fail_activation_target_mismatch("inline callback identity");
                        }
                        None
                    }
                },
                Err(error) => {
                    self.fail(error);
                    None
                }
            }
        });
        if frame.is_none() && self.call_stack.last().is_none_or(Option::is_none) {
            self.fail_activation_target_mismatch("builtin callback has no outer checked call");
        }
        self.call_stack.push(frame);
    }

    fn pop_call(&mut self) {
        match self.call_stack.pop() {
            Some(Some(frame)) if frame.requires_activation && !frame.activation_consumed => {
                self.fail_activation_target_mismatch("required activation was not consumed");
            }
            Some(_) => {}
            None => self.fail(CheckedInterpreterMechanismTraceError::TraceStackMismatch),
        }
    }

    fn mark_current_call_frame_consumed(&mut self) {
        let Some(Some(frame)) = self.call_stack.last_mut() else {
            self.fail(CheckedInterpreterMechanismTraceError::TraceStackMismatch);
            return;
        };
        if frame.activation_consumed {
            self.fail_activation_target_mismatch("checked call activated more than once");
            return;
        }
        frame.activation_consumed = true;
    }

    fn callee_from_target(
        &self,
        target: &CheckedCallTarget,
    ) -> Result<Option<CheckedInterpreterMechanismCallee>, CheckedInterpreterMechanismTraceError>
    {
        match target {
            CheckedCallTarget::Function { callable, .. } => Ok(Some(
                CheckedInterpreterMechanismCallee::Function(callable.clone()),
            )),
            CheckedCallTarget::RuleFamily(family) => Ok(Some(
                CheckedInterpreterMechanismCallee::RuleFamily(family.clone()),
            )),
            CheckedCallTarget::ScopedMember {
                owner_type,
                member,
                arity,
                rule_family: Some(family),
            } => Ok(Some(CheckedInterpreterMechanismCallee::RuleFamily(
                family.clone(),
            ))),
            CheckedCallTarget::ScopedMember {
                owner_type,
                member,
                arity,
                rule_family: None,
            } => Ok(Some(CheckedInterpreterMechanismCallee::Function(
                self.catalog.scoped_callable(owner_type, member, *arity)?,
            ))),
            CheckedCallTarget::Builtin { .. }
            | CheckedCallTarget::Constructor { .. }
            | CheckedCallTarget::BoundCallable { .. } => Ok(None),
        }
    }

    fn current_call_frame(&mut self) -> Option<CheckedInterpreterMechanismCallFrame> {
        let Some(Some(frame)) = self.call_stack.last().cloned() else {
            if env::var_os("FUTURUNA_EXPLORE_TRACE").is_some() {
                eprintln!(
                    "[explore trace] mechanism activation has no checked call frame: owner={:?}; call_stack_depth={}",
                    self.current_owner(),
                    self.call_stack.len(),
                );
            }
            self.fail_activation_target_mismatch("runtime activation has no checked call frame");
            return None;
        };
        Some(frame)
    }

    fn enter_activation_at(
        &mut self,
        call_site: ExprSiteId,
        actual: CheckedInterpreterMechanismCallee,
        owner: CheckedInterpreterMechanismOwner,
    ) -> bool {
        let Some(current_path) = self
            .activation_paths
            .get(self.current_activation_path.index())
        else {
            self.fail(CheckedInterpreterMechanismTraceError::TraceStackMismatch);
            return false;
        };
        let current_depth = usize::from(current_path.depth);
        if current_depth >= CHECKED_INTERPRETER_MECHANISM_MAX_ACTIVATION_DEPTH {
            self.fail(CheckedInterpreterMechanismTraceError::TraceCapacity {
                resource: "activation depth",
                actual: current_depth + 1,
                limit: CHECKED_INTERPRETER_MECHANISM_MAX_ACTIVATION_DEPTH,
            });
            return false;
        }
        let ordinal_key = (
            self.current_activation_path,
            call_site.clone(),
            actual.clone(),
        );
        let ordinal = *self.invocation_ordinals.get(&ordinal_key).unwrap_or(&0);
        let Some(next) = ordinal.checked_add(1) else {
            self.fail(CheckedInterpreterMechanismTraceError::TraceCapacity {
                resource: "activation invocations",
                actual: usize::MAX,
                limit: u32::MAX as usize,
            });
            return false;
        };
        self.invocation_ordinals.insert(ordinal_key, next);
        if self.activation_paths.len() >= CHECKED_INTERPRETER_MECHANISM_MAX_ACTIVATION_PATHS {
            self.fail(CheckedInterpreterMechanismTraceError::TraceCapacity {
                resource: "activation paths",
                actual: self.activation_paths.len() + 1,
                limit: CHECKED_INTERPRETER_MECHANISM_MAX_ACTIVATION_PATHS,
            });
            return false;
        }
        let Some(path_id) =
            CheckedInterpreterMechanismActivationPathId::from_index(self.activation_paths.len())
        else {
            self.fail(CheckedInterpreterMechanismTraceError::TraceCapacity {
                resource: "activation paths",
                actual: self.activation_paths.len() + 1,
                limit: u32::MAX as usize,
            });
            return false;
        };
        self.diagnostic_observe_rule_activation(&actual);
        self.activation_paths
            .push(CheckedInterpreterMechanismActivationPathNode {
                parent: Some(self.current_activation_path),
                activation: CheckedInterpreterMechanismActivation {
                    call_site,
                    callee: actual,
                    invocation_ordinal: ordinal,
                },
                depth: (current_depth + 1) as u16,
            });
        if self.diagnostics_enabled {
            self.directly_event_bearing_activation_paths.push(false);
        }
        self.current_activation_path = path_id;
        self.owners.push(owner);
        true
    }

    fn enter_function(&mut self, name: Option<&str>, parameters: &[String], body: &Expr) -> bool {
        let Some(frame) = self.current_call_frame() else {
            return false;
        };
        let callable = match &frame.target {
            CheckedCallTarget::BoundCallable { arity, .. } => {
                if *arity != parameters.len() {
                    self.fail_activation_target_mismatch("bound callable arity");
                    return false;
                }
                match self.catalog.bound_runtime_callable(name, parameters, body) {
                    Ok(callable) => callable,
                    Err(error) => {
                        self.fail(error);
                        return false;
                    }
                }
            }
            target => match self.callee_from_target(target) {
                Ok(Some(CheckedInterpreterMechanismCallee::Function(callable))) => callable,
                Ok(_) => {
                    if env::var_os("FUTURUNA_EXPLORE_TRACE").is_some() {
                        eprintln!(
                            "[explore trace] checked call target did not enter a function: target={:?}; runtime_name={name:?}; arity={}",
                            frame.target,
                            parameters.len(),
                        );
                    }
                    self.fail_activation_target_mismatch("checked target did not enter a function");
                    return false;
                }
                Err(error) => {
                    self.fail(error);
                    return false;
                }
            },
        };
        let Some(checked) = self.catalog.callable(&callable) else {
            self.fail(
                CheckedInterpreterMechanismTraceError::CheckedCallableMissing(callable.clone()),
            );
            return false;
        };
        let shape_matches = name == Some(checked.runtime_name.as_ref())
            && checked.parameters.len() == parameters.len()
            && checked
                .parameters
                .iter()
                .zip(parameters)
                .all(|(expected, actual)| expected.name.as_str() == actual.as_str());
        let expected_span = checked.body.span;
        let expected_digest = checked.body_digest;
        if !shape_matches
            || expected_span != body.span
            || (!self.validated_callable_bodies.contains(&callable)
                && expected_digest != checked_interpreter_mechanism_body_digest(body))
        {
            self.fail(CheckedInterpreterMechanismTraceError::CallableBodyMismatch(
                callable.clone(),
            ));
            return false;
        }
        self.validated_callable_bodies.insert(callable.clone());
        let entered = self.enter_activation_at(
            frame.site,
            CheckedInterpreterMechanismCallee::Function(callable.clone()),
            CheckedInterpreterMechanismOwner::Callable(callable.clone()),
        );
        if entered {
            self.mark_current_call_frame_consumed();
        }
        entered
    }

    fn enter_rule_family(&mut self, family: &RuleDispatchKey) -> bool {
        let Some(frame) = self.current_call_frame() else {
            return false;
        };
        let callee = CheckedInterpreterMechanismCallee::RuleFamily(family.clone());
        let target_matches = match &frame.target {
            CheckedCallTarget::BoundCallable { arity, .. } => {
                *arity == family.arity && self.catalog.contains_rule_family(family)
            }
            target => match self.callee_from_target(target) {
                Ok(Some(target_callee)) => target_callee == callee,
                Ok(None) => false,
                Err(error) => {
                    self.fail(error);
                    return false;
                }
            },
        };
        if !target_matches {
            if env::var_os("FUTURUNA_EXPLORE_TRACE").is_some() {
                eprintln!(
                    "[explore trace] checked call target did not enter the runtime rule family: target={:?}; runtime_family={family:?}",
                    frame.target,
                );
            }
            self.fail_activation_target_mismatch("checked target did not enter a rule family");
            return false;
        }
        let entered = self.enter_activation_at(
            frame.site,
            callee,
            CheckedInterpreterMechanismOwner::RuleCandidate {
                family: family.clone(),
                // Replaced before any candidate expression is evaluated.
                source_order: usize::MAX,
            },
        );
        if entered {
            self.mark_current_call_frame_consumed();
        }
        entered
    }

    fn enter_rule_candidate(&mut self, family: &RuleDispatchKey, source_order: usize, rule: &Rule) {
        let candidate_key = (family.clone(), source_order);
        if !self.validated_rule_candidates.contains(&candidate_key) {
            match self.catalog.rule_candidate_digest(family, source_order) {
                Ok(expected) if expected == checked_interpreter_mechanism_rule_digest(rule) => {
                    self.validated_rule_candidates.insert(candidate_key);
                }
                Ok(_) => self.fail(
                    CheckedInterpreterMechanismTraceError::RuleCandidateBodyMismatch {
                        family: family.clone(),
                        source_order,
                    },
                ),
                Err(error) => self.fail(error),
            }
        }
        let Some(owner) = self.owners.last_mut() else {
            self.fail(CheckedInterpreterMechanismTraceError::TraceStackMismatch);
            return;
        };
        *owner = CheckedInterpreterMechanismOwner::RuleCandidate {
            family: family.clone(),
            source_order,
        };
    }

    fn exit_activation(&mut self) {
        let parent = self
            .activation_paths
            .get(self.current_activation_path.index())
            .and_then(|path| path.parent);
        let Some(parent) = parent else {
            self.fail(CheckedInterpreterMechanismTraceError::TraceStackMismatch);
            return;
        };
        if self.owners.len() <= 1 {
            self.fail(CheckedInterpreterMechanismTraceError::TraceStackMismatch);
            return;
        }
        self.current_activation_path = parent;
        self.owners.pop();
    }

    fn begin_dependency_scope(&mut self) {
        self.dependency_scopes.push(Vec::new());
    }

    fn bubble_dependency_scope(&mut self) {
        if self.dependency_scopes.len() <= 1 {
            self.fail(CheckedInterpreterMechanismTraceError::TraceStackMismatch);
            return;
        }
        let roots = self
            .dependency_scopes
            .pop()
            .expect("checked non-root dependency scope");
        self.dependency_scopes
            .last_mut()
            .expect("checked root dependency scope")
            .extend(roots);
    }

    fn record_expression_event(
        &mut self,
        expression_kind: CheckedInterpreterMechanismExpressionKind,
        event_kind: CheckedInterpreterMechanismEventKind,
        expression: &Expr,
        outcome: CheckedInterpreterMechanismEventOutcome,
    ) {
        let Some(site) = self.expression_site(expression_kind, expression) else {
            self.bubble_dependency_scope();
            return;
        };
        let _ = self.record_event(
            CheckedInterpreterMechanismEventSite::Expression(site),
            event_kind,
            outcome,
        );
    }

    fn record_rule_attempt(
        &mut self,
        family: &RuleDispatchKey,
        source_order: usize,
        outcome: CheckedInterpreterRuleAttemptOutcome,
    ) -> Option<CheckedRuleCandidateResolution> {
        let candidate = match self.catalog.rule_candidate(family, source_order) {
            Ok(candidate) => candidate,
            Err(error) => {
                self.fail(error);
                self.bubble_dependency_scope();
                return None;
            }
        };
        let _ = self.record_event(
            CheckedInterpreterMechanismEventSite::RuleCandidate(candidate.clone()),
            CheckedInterpreterMechanismEventKind::RuleAttempt,
            CheckedInterpreterMechanismEventOutcome::RuleAttempt(outcome),
        );
        Some(candidate)
    }

    fn record_rule_selection(
        &mut self,
        family: &RuleDispatchKey,
        selected: Option<CheckedRuleCandidateResolution>,
    ) -> Option<usize> {
        self.record_event(
            CheckedInterpreterMechanismEventSite::RuleFamily(family.clone()),
            CheckedInterpreterMechanismEventKind::RuleSelection,
            CheckedInterpreterMechanismEventOutcome::RuleSelection(match selected {
                Some(candidate) => CheckedInterpreterRuleSelectionOutcome::Selected(candidate),
                None => CheckedInterpreterRuleSelectionOutcome::NoApplicableRule,
            }),
        )
    }

    fn completed_rule_selection_memo(&mut self, family: &RuleDispatchKey) -> Option<usize> {
        if self.error.is_some() {
            return None;
        }
        let Some((cold_event_index, event)) = self
            .events
            .len()
            .checked_sub(1)
            .and_then(|index| self.events.get(index).map(|event| (index, event)))
        else {
            self.fail(CheckedInterpreterMechanismTraceError::MemoizedRuleSelectionMismatch);
            return None;
        };
        let matches_selection = matches!(
            (&event.site, event.kind, &event.outcome),
            (
                CheckedInterpreterMechanismEventSite::RuleFamily(event_family),
                CheckedInterpreterMechanismEventKind::RuleSelection,
                CheckedInterpreterMechanismEventOutcome::RuleSelection(_),
            ) if event_family == family
        );
        if !matches_selection {
            self.fail(CheckedInterpreterMechanismTraceError::MemoizedRuleSelectionMismatch);
            return None;
        }
        Some(cold_event_index)
    }

    fn replay_rule_selection_memo(
        &mut self,
        family: &RuleDispatchKey,
        cold_event_index: usize,
        scoped: bool,
    ) -> bool {
        let outcome = self.events.get(cold_event_index).and_then(|event| {
            match (&event.site, event.kind, &event.outcome) {
                (
                    CheckedInterpreterMechanismEventSite::RuleFamily(event_family),
                    CheckedInterpreterMechanismEventKind::RuleSelection,
                    CheckedInterpreterMechanismEventOutcome::RuleSelection(outcome),
                ) if event_family == family => Some(outcome.clone()),
                _ => None,
            }
        });
        let Some(outcome) = outcome else {
            self.fail(CheckedInterpreterMechanismTraceError::MemoizedRuleSelectionMismatch);
            return false;
        };
        if !self.enter_rule_family(family) {
            return false;
        }
        if scoped {
            self.diagnostic_observe_scoped_memo_reuse(family);
        } else {
            self.diagnostic_observe_global_memo_reuse(family);
        }
        self.begin_dependency_scope();
        self.dependency_scopes
            .last_mut()
            .expect("checked memoized rule selection dependency scope")
            .push(cold_event_index);
        let selected = match outcome {
            CheckedInterpreterRuleSelectionOutcome::NoApplicableRule => None,
            CheckedInterpreterRuleSelectionOutcome::Selected(candidate) => Some(candidate),
        };
        let recorded = self.record_rule_selection(family, selected).is_some();
        self.exit_activation();
        if recorded {
            self.memoized_rule_reuses = self.memoized_rule_reuses.saturating_add(1);
        }
        recorded
    }

    fn record_event(
        &mut self,
        site: CheckedInterpreterMechanismEventSite,
        kind: CheckedInterpreterMechanismEventKind,
        outcome: CheckedInterpreterMechanismEventOutcome,
    ) -> Option<usize> {
        self.diagnostic_observe_event(kind);
        if self.dependency_scopes.len() <= 1 {
            self.fail(CheckedInterpreterMechanismTraceError::TraceStackMismatch);
            return None;
        }
        let mut dependencies = self
            .dependency_scopes
            .pop()
            .expect("checked event dependency scope");
        dependencies.sort_unstable();
        dependencies.dedup();
        if self.events.len() >= CHECKED_INTERPRETER_MECHANISM_MAX_EVENTS {
            self.fail(CheckedInterpreterMechanismTraceError::TraceCapacity {
                resource: "events",
                actual: self.events.len() + 1,
                limit: CHECKED_INTERPRETER_MECHANISM_MAX_EVENTS,
            });
            self.dependency_scopes
                .last_mut()
                .expect("checked parent dependency scope")
                .extend(dependencies);
            return None;
        }
        let Some(next_edge_count) = self.edge_count.checked_add(dependencies.len()) else {
            self.fail(CheckedInterpreterMechanismTraceError::TraceCapacity {
                resource: "edges",
                actual: usize::MAX,
                limit: CHECKED_INTERPRETER_MECHANISM_MAX_EDGES,
            });
            return None;
        };
        if next_edge_count > CHECKED_INTERPRETER_MECHANISM_MAX_EDGES {
            self.fail(CheckedInterpreterMechanismTraceError::TraceCapacity {
                resource: "edges",
                actual: next_edge_count,
                limit: CHECKED_INTERPRETER_MECHANISM_MAX_EDGES,
            });
            return None;
        }
        let visit_key = (self.current_activation_path, site.clone(), kind);
        let visit_ordinal = *self.visit_ordinals.get(&visit_key).unwrap_or(&0);
        let Some(next_visit) = visit_ordinal.checked_add(1) else {
            self.fail(CheckedInterpreterMechanismTraceError::TraceCapacity {
                resource: "event visits",
                actual: usize::MAX,
                limit: u32::MAX as usize,
            });
            return None;
        };
        self.visit_ordinals.insert(visit_key, next_visit);
        self.edge_count = next_edge_count;
        let index = self.events.len();
        self.events.push(CheckedInterpreterMechanismEvent {
            root_index: 0,
            activation_path: self.current_activation_path,
            site,
            kind,
            visit_ordinal,
            outcome,
            dependencies: dependencies.into_boxed_slice(),
        });
        self.dependency_scopes
            .last_mut()
            .expect("checked parent dependency scope")
            .push(index);
        Some(index)
    }

    fn finish(
        self,
    ) -> Result<CheckedInterpreterMechanismTrace, CheckedInterpreterMechanismTraceError> {
        self.emit_diagnostics();
        if let Some(error) = self.error {
            return Err(error);
        }
        if !self.call_stack.is_empty()
            || self.dependency_scopes.len() != 1
            || self.owners.len() != 1
            || self.current_activation_path.index() != 0
        {
            return Err(CheckedInterpreterMechanismTraceError::TraceStackMismatch);
        }
        let mut roots = self
            .dependency_scopes
            .into_iter()
            .next()
            .expect("checked root dependency scope");
        roots.sort_unstable();
        roots.dedup();
        if env::var_os("FUTURUNA_EXPLORE_TRACE").is_some() {
            eprintln!(
                "[explore trace] mechanism trace complete: events={}; edges={}; activation_paths={}; maximum_depth={}; memoized_rule_reuses={}",
                self.events.len(),
                self.edge_count,
                self.activation_paths.len(),
                self.activation_paths
                    .iter()
                    .map(|path| path.depth)
                    .max()
                    .unwrap_or(0),
                self.memoized_rule_reuses,
            );
        }
        Ok(CheckedInterpreterMechanismTrace {
            roots: roots.into_boxed_slice(),
            activation_paths: self.activation_paths.into_boxed_slice(),
            events: self.events.into_boxed_slice(),
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
enum CheckedExploreSemanticDependency {
    TopLevel(CheckedTopLevelBindingId),
    Callable(CheckedCallableId),
    RuleFamily(RuleDispatchKey),
    DeclaredType(CheckedDataTypeId),
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct CheckedExploreSemanticLiteral {
    kind: CheckedExploreCoverageLiteralKind,
    value: Box<str>,
}

impl CheckedExploreSemanticLiteral {
    fn from_literal(literal: &Literal) -> Self {
        match literal {
            Literal::Int(value) => Self {
                kind: CheckedExploreCoverageLiteralKind::Integer,
                value: value.to_string().into_boxed_str(),
            },
            Literal::Float(value) => Self {
                kind: CheckedExploreCoverageLiteralKind::FloatBits,
                value: value.to_bits().to_string().into_boxed_str(),
            },
            Literal::Str(value) => Self {
                kind: CheckedExploreCoverageLiteralKind::String,
                value: value.clone().into_boxed_str(),
            },
            Literal::Char(value) => Self {
                kind: CheckedExploreCoverageLiteralKind::Character,
                value: (*value as u32).to_string().into_boxed_str(),
            },
            Literal::Bool(value) => Self {
                kind: CheckedExploreCoverageLiteralKind::Boolean,
                value: if *value { "true" } else { "false" }.into(),
            },
        }
    }

    fn unit() -> Self {
        Self {
            kind: CheckedExploreCoverageLiteralKind::Unit,
            value: "()".into(),
        }
    }
}

#[derive(Debug, Clone)]
struct CheckedExploreSemanticProducerInputs {
    literals: BTreeSet<CheckedExploreSemanticLiteral>,
    top_level_constants: BTreeSet<CheckedTopLevelBindingId>,
    constructor_choices:
        BTreeMap<CheckedConstructorIdentity, CheckedExploreConstructorChoiceProvenance>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CheckedExploreConstructorChoiceProvenance {
    /// A direct constructor spine rooted in one singleton FROM binding. No
    /// callable, collection, projection or control-flow node lies between the
    /// binding root and this occurrence.
    ConditionedFromSourceSingleton,
    /// Reachability alone does not prove that the constructor choice is fixed.
    Unproven,
}

#[derive(Debug, Clone)]
struct CheckedExploreSemanticSeal {
    digest: [u8; 32],
    /// Exact declaration occurrences traversed while sealing this closure.
    /// This operational projection never enters the canonical semantic digest;
    /// it lets optional backends compile only the already-proven dependency
    /// graph instead of repeating a spelling-based reachability analysis.
    reachable_declarations: BTreeSet<CheckedDeclarationOccurrenceId>,
    reachable_dependencies: BTreeSet<CheckedExploreSemanticDependency>,
    producer_inputs: CheckedExploreSemanticProducerInputs,
    /// Binder identities referenced before this closure reserved them as one
    /// of its own parameters, rule-head variables, or lexical patterns. For a
    /// dependency-root seal these are exactly the call-site environment
    /// captures that an args-only observer memo must refuse.
    dynamic_captures: BTreeSet<CheckedBinderSiteId>,
    effect_free: bool,
}

#[derive(Debug, Clone)]
struct CheckedExploreSemanticLayerSeal {
    digest: [u8; 32],
    reachable_declarations: BTreeSet<CheckedDeclarationOccurrenceId>,
    reachable_dependencies: BTreeSet<CheckedExploreSemanticDependency>,
}

struct CheckedExploreSemanticClosure<'a, 'index> {
    index: &'a CheckedExploreSemanticIndex<'index>,
    resolutions: &'a CheckedResolutionArtifacts,
    layer: &'a str,
    semantic_binders: &'a BTreeMap<CheckedBinderSiteId, Box<str>>,
    rule_head_roots: BTreeSet<ExprSiteId>,
    dependencies: Vec<CheckedExploreSemanticDependency>,
    dependency_indices: BTreeMap<CheckedExploreSemanticDependency, usize>,
    local_binder_indices: BTreeMap<CheckedBinderSiteId, usize>,
    producer_literals: BTreeSet<CheckedExploreSemanticLiteral>,
    producer_top_level_constants: BTreeSet<CheckedTopLevelBindingId>,
    producer_constructor_choices:
        BTreeMap<CheckedConstructorIdentity, CheckedExploreConstructorChoiceProvenance>,
    current_constructor_choice_provenance: CheckedExploreConstructorChoiceProvenance,
    dynamic_captures: BTreeSet<CheckedBinderSiteId>,
    effect_free: bool,
}

impl<'a, 'index> CheckedExploreSemanticClosure<'a, 'index> {
    fn new(
        index: &'a CheckedExploreSemanticIndex<'index>,
        resolutions: &'a CheckedResolutionArtifacts,
        layer: &'a str,
        semantic_binders: &'a BTreeMap<CheckedBinderSiteId, Box<str>>,
    ) -> Self {
        Self {
            index,
            resolutions,
            layer,
            semantic_binders,
            rule_head_roots: resolutions
                .rule_families
                .values()
                .flat_map(|family| family.candidates.iter())
                .map(|candidate| candidate.head_site.clone())
                .collect(),
            dependencies: Vec::new(),
            dependency_indices: BTreeMap::new(),
            local_binder_indices: BTreeMap::new(),
            producer_literals: BTreeSet::new(),
            producer_top_level_constants: BTreeSet::new(),
            producer_constructor_choices: BTreeMap::new(),
            current_constructor_choice_provenance:
                CheckedExploreConstructorChoiceProvenance::Unproven,
            dynamic_captures: BTreeSet::new(),
            effect_free: true,
        }
    }

    fn unsealed<T>(&self, site: Option<ExprSiteId>) -> Result<T, CheckedExploreQueryArtifactIssue> {
        if env::var_os("FUTURUNA_EXPLORE_TRACE").is_some() {
            match site.as_ref() {
                Some(site) => {
                    let expression_kind = self
                        .index
                        .expression(site)
                        .map(|expression| match &expression.kind {
                            ExprKind::Var(_) => "variable",
                            ExprKind::Lit(_) => "literal",
                            ExprKind::App(_, _) => "application",
                            ExprKind::Lambda(_, _) => "lambda",
                            ExprKind::BinOp(_, _, _) => "binary",
                            ExprKind::UnOp(_, _) => "unary",
                            ExprKind::If(_, _, _) => "if",
                            ExprKind::Match(_, _) => "match",
                            ExprKind::Block(_) => "block",
                            ExprKind::Field(_, _) => "field",
                            ExprKind::Index(_, _) => "index",
                            ExprKind::List(_) => "list",
                            ExprKind::Tuple(_) => "tuple",
                            ExprKind::Effect(_, _) => "effect",
                            ExprKind::Handle { .. } => "handle",
                            ExprKind::Try(_) => "try",
                            ExprKind::Conjunction(_) => "conjunction",
                            ExprKind::Disjunction(_) => "disjunction",
                            ExprKind::Pipe(_, _) => "pipe",
                            ExprKind::Unit => "unit",
                        })
                        .unwrap_or("missing");
                    eprintln!(
                        "[explore trace] semantic closure unsealed: layer={} kind={} site={:?} resolution={:?} issues={:?}",
                        self.layer,
                        expression_kind,
                        site,
                        self.resolutions.expressions.get(site),
                        self.resolutions.unsupported_sites.get(site),
                    );
                }
                None => eprintln!(
                    "[explore trace] semantic closure unsealed: layer={} site=<none>",
                    self.layer
                ),
            }
        }
        Err(
            CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                layer: self.layer.to_string().into_boxed_str(),
                site,
            },
        )
    }

    fn child_site(site: &ExprSiteId, child: usize) -> ExprSiteId {
        let mut child_site = site.clone();
        let mut path = site.ast_path.to_vec();
        path.push(child as u32);
        child_site.ast_path = path.into_boxed_slice();
        child_site
    }

    fn is_rule_head_site(&self, site: &ExprSiteId) -> bool {
        let mut ancestor = site.clone();
        loop {
            if self.rule_head_roots.contains(&ancestor) {
                return true;
            }
            let mut path = ancestor.ast_path.into_vec();
            if path.pop().is_none() {
                return false;
            }
            ancestor.ast_path = path.into_boxed_slice();
        }
    }

    fn structural_binder(
        site: &ExprSiteId,
        ast_path: &[u32],
        binder_path: Vec<u32>,
    ) -> CheckedBinderSiteId {
        CheckedBinderSiteId::Structural {
            analysis_program: site.analysis_program.clone(),
            declaration: site.declaration.clone(),
            normalized_declaration_ordinal: site.normalized_declaration_ordinal,
            ast_path: ast_path.to_vec().into_boxed_slice(),
            binder_path: binder_path.into_boxed_slice(),
        }
    }

    fn dependency_index(&mut self, dependency: CheckedExploreSemanticDependency) -> usize {
        if let Some(index) = self.dependency_indices.get(&dependency) {
            return *index;
        }
        let index = self.dependencies.len();
        self.dependencies.push(dependency.clone());
        self.dependency_indices.insert(dependency, index);
        index
    }

    fn hash_dependency_reference(
        &mut self,
        hasher: &mut Sha256,
        dependency: CheckedExploreSemanticDependency,
    ) {
        let index = self.dependency_index(dependency);
        checked_query_hash_component(hasher, "semantic-dependency", &index.to_string());
    }

    fn local_binder_index(&mut self, binder: CheckedBinderSiteId) -> usize {
        if let Some(index) = self.local_binder_indices.get(&binder) {
            return *index;
        }
        let index = self.local_binder_indices.len();
        self.local_binder_indices.insert(binder, index);
        index
    }

    fn hash_binder_reference(&mut self, hasher: &mut Sha256, binder: CheckedBinderSiteId) {
        if let Some(role) = self.semantic_binders.get(&binder) {
            checked_query_hash_component(hasher, "semantic-binder", role);
        } else {
            if !self.local_binder_indices.contains_key(&binder) {
                self.dynamic_captures.insert(binder.clone());
            }
            let index = self.local_binder_index(binder);
            checked_query_hash_component(hasher, "local-binder", &index.to_string());
        }
    }

    fn reserve_binder(&mut self, binder: CheckedBinderSiteId) {
        if !self.semantic_binders.contains_key(&binder) {
            self.local_binder_index(binder);
        }
    }

    fn hash_type(
        &mut self,
        hasher: &mut Sha256,
        ty: &Ty,
        type_variables: &mut BTreeMap<String, usize>,
    ) -> Result<(), CheckedExploreQueryArtifactIssue> {
        match ty {
            Ty::Name(name) if type_variables.contains_key(name) => {
                checked_query_hash_component(hasher, "semantic-type-kind", "variable");
                checked_query_hash_component(
                    hasher,
                    "semantic-type-variable",
                    &type_variables[name].to_string(),
                );
            }
            Ty::Name(name) if name == "Unit" => {
                checked_query_hash_component(hasher, "semantic-type-kind", "unit");
            }
            Ty::Name(name) => {
                checked_query_hash_component(hasher, "semantic-type-kind", "name");
                let owner = self
                    .resolutions
                    .data_type_identities
                    .get(name.as_str())
                    .cloned()
                    .ok_or_else(|| CheckedExploreQueryArtifactIssue::TypeOwnerNotResolved {
                        ty: ty.clone(),
                    })?;
                match owner {
                    CheckedDataTypeId::Intrinsic { canonical_name } => {
                        checked_query_hash_component(hasher, "intrinsic-type", &canonical_name);
                    }
                    CheckedDataTypeId::Declared(_) => self.hash_dependency_reference(
                        hasher,
                        CheckedExploreSemanticDependency::DeclaredType(owner),
                    ),
                }
            }
            Ty::App(constructor, arguments) => {
                checked_query_hash_component(hasher, "semantic-type-kind", "application");
                self.hash_type(hasher, constructor, type_variables)?;
                checked_query_hash_component(
                    hasher,
                    "semantic-type-argument-count",
                    &arguments.len().to_string(),
                );
                for argument in arguments {
                    self.hash_type(hasher, argument, type_variables)?;
                }
            }
            Ty::Arrow(parameter, result) => {
                checked_query_hash_component(hasher, "semantic-type-kind", "arrow");
                self.hash_type(hasher, parameter, type_variables)?;
                self.hash_type(hasher, result, type_variables)?;
            }
            Ty::Ref(inner) => {
                checked_query_hash_component(hasher, "semantic-type-kind", "reference");
                self.hash_type(hasher, inner, type_variables)?;
            }
            Ty::MutRef(inner) => {
                checked_query_hash_component(hasher, "semantic-type-kind", "mutable-reference");
                self.hash_type(hasher, inner, type_variables)?;
            }
            Ty::Shared(inner) => {
                checked_query_hash_component(hasher, "semantic-type-kind", "shared");
                self.hash_type(hasher, inner, type_variables)?;
            }
            Ty::Optional(inner) => {
                checked_query_hash_component(hasher, "semantic-type-kind", "optional");
                self.hash_type(hasher, &Ty::Name("Option".to_string()), type_variables)?;
                self.hash_type(hasher, inner, type_variables)?;
            }
            Ty::Var(name) => {
                let next = type_variables.len();
                let index = *type_variables.entry(name.clone()).or_insert(next);
                checked_query_hash_component(hasher, "semantic-type-kind", "variable");
                checked_query_hash_component(hasher, "semantic-type-variable", &index.to_string());
            }
            Ty::Unit => {
                checked_query_hash_component(hasher, "semantic-type-kind", "unit");
            }
            Ty::Hole => {
                return self.unsealed(None);
            }
        }
        Ok(())
    }

    fn record_constructor_choice(&mut self, constructor: &CheckedConstructorIdentity) {
        let occurrence = self.current_constructor_choice_provenance;
        self.producer_constructor_choices
            .entry(constructor.clone())
            .and_modify(|provenance| {
                if occurrence == CheckedExploreConstructorChoiceProvenance::Unproven {
                    *provenance = CheckedExploreConstructorChoiceProvenance::Unproven;
                }
            })
            .or_insert(occurrence);
    }

    fn hash_constructor(&mut self, hasher: &mut Sha256, constructor: &CheckedConstructorIdentity) {
        match &constructor.owner {
            CheckedDataTypeId::Intrinsic { canonical_name } => {
                checked_query_hash_component(hasher, "constructor-owner", canonical_name);
            }
            owner @ CheckedDataTypeId::Declared(_) => self.hash_dependency_reference(
                hasher,
                CheckedExploreSemanticDependency::DeclaredType(owner.clone()),
            ),
        }
        checked_query_hash_component(
            hasher,
            "constructor-variant-index",
            &constructor.variant_index.to_string(),
        );
        checked_query_hash_component(
            hasher,
            "constructor-layout",
            match constructor.layout {
                CheckedConstructorLayout::Positional => "positional",
                CheckedConstructorLayout::Named => "named",
            },
        );
    }

    fn scoped_callable(
        &self,
        owner_type: &str,
        member: &str,
        arity: usize,
        site: &ExprSiteId,
    ) -> Result<CheckedCallableId, CheckedExploreQueryArtifactIssue> {
        match self
            .index
            .scoped_callables
            .get(&(owner_type.to_string(), member.to_string(), arity))
            .map(Vec::as_slice)
        {
            Some([callable]) => Ok(callable.clone()),
            _ => self.unsealed(Some(site.clone())),
        }
    }

    fn checked_argument_has_container_type(
        &self,
        application_site: &ExprSiteId,
        argument_index: usize,
        constructors: &[&str],
    ) -> bool {
        let argument_site = Self::child_site(application_site, argument_index + 1);
        self.resolutions
            .expressions
            .get(&argument_site)
            .is_some_and(|resolution| {
                matches!(
                    &resolution.resolved_type,
                    CheckedExpressionType::Resolved(Ty::App(constructor, _))
                        if matches!(constructor.as_ref(), Ty::Name(name) if constructors.contains(&name.as_str()))
                )
            })
    }

    fn hash_call_target(
        &mut self,
        hasher: &mut Sha256,
        target: &CheckedCallTarget,
        site: &ExprSiteId,
        type_variables: &mut BTreeMap<String, usize>,
    ) -> Result<(), CheckedExploreQueryArtifactIssue> {
        match target {
            CheckedCallTarget::Builtin {
                canonical_name,
                arity,
            } => {
                static IMPURE_RUNTIME_NAMES: OnceLock<BTreeSet<String>> = OnceLock::new();
                let impure = IMPURE_RUNTIME_NAMES.get_or_init(meta_impure_runtime_names);
                let pure_eager_collection_overload = match canonical_name.as_ref() {
                    "last" | "take" => self.checked_argument_has_container_type(site, 0, &["List"]),
                    "collect" => {
                        self.checked_argument_has_container_type(site, 0, &["List", "Stream"])
                    }
                    _ => false,
                };
                if (impure.contains(canonical_name.as_ref()) && !pure_eager_collection_overload)
                    || matches!(canonical_name.as_ref(), "findall" | "search")
                {
                    self.effect_free = false;
                }
                checked_query_hash_component(hasher, "call-target", "builtin");
                checked_query_hash_component(hasher, "builtin-name", canonical_name);
                checked_query_hash_component(hasher, "builtin-arity", &arity.to_string());
            }
            CheckedCallTarget::Constructor { arity, .. } => {
                let resolution = self
                    .resolutions
                    .expressions
                    .get(site)
                    .and_then(|resolution| resolution.exact_constructor.as_ref())
                    .cloned()
                    .ok_or_else(|| {
                        CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                            layer: self.layer.to_string().into_boxed_str(),
                            site: Some(site.clone()),
                        }
                    })?;
                checked_query_hash_component(hasher, "call-target", "constructor");
                checked_query_hash_component(hasher, "call-arity", &arity.to_string());
                self.record_constructor_choice(&resolution);
                self.hash_constructor(hasher, &resolution);
            }
            CheckedCallTarget::Function { callable, arity } => {
                checked_query_hash_component(hasher, "call-target", "callable");
                checked_query_hash_component(hasher, "call-arity", &arity.to_string());
                self.hash_dependency_reference(
                    hasher,
                    CheckedExploreSemanticDependency::Callable(callable.clone()),
                );
            }
            CheckedCallTarget::BoundCallable {
                binder,
                parameter_type,
                result_type,
                arity,
            } => {
                let Ok(parameter_type) = parse_type_annotation(parameter_type) else {
                    return self.unsealed(Some(site.clone()));
                };
                let Ok(result_type) = parse_type_annotation(result_type) else {
                    return self.unsealed(Some(site.clone()));
                };
                checked_query_hash_component(hasher, "call-target", "bound-callable");
                checked_query_hash_component(hasher, "call-arity", &arity.to_string());
                checked_query_hash_component(hasher, "call-parameter-type", "structural");
                self.hash_type(hasher, &parameter_type, type_variables)?;
                checked_query_hash_component(hasher, "call-result-type", "structural");
                self.hash_type(hasher, &result_type, type_variables)?;
                self.hash_binder_reference(hasher, binder.clone());
            }
            CheckedCallTarget::RuleFamily(family) => {
                checked_query_hash_component(hasher, "call-target", "rule-family");
                self.hash_dependency_reference(
                    hasher,
                    CheckedExploreSemanticDependency::RuleFamily(family.clone()),
                );
            }
            CheckedCallTarget::ScopedMember {
                owner_type,
                member,
                arity,
                rule_family,
            } => {
                checked_query_hash_component(hasher, "call-target", "scoped-member");
                checked_query_hash_component(hasher, "call-arity", &arity.to_string());
                if let Some(family) = rule_family {
                    self.hash_dependency_reference(
                        hasher,
                        CheckedExploreSemanticDependency::RuleFamily(family.clone()),
                    );
                } else {
                    let callable = self.scoped_callable(owner_type, member, *arity, site)?;
                    self.hash_dependency_reference(
                        hasher,
                        CheckedExploreSemanticDependency::Callable(callable),
                    );
                }
            }
        }
        Ok(())
    }

    fn hash_literal(&mut self, hasher: &mut Sha256, literal: &Literal) {
        self.producer_literals
            .insert(CheckedExploreSemanticLiteral::from_literal(literal));
        match literal {
            Literal::Int(value) => {
                checked_query_hash_component(hasher, "literal-kind", "int");
                checked_query_hash_component(hasher, "literal-value", &value.to_string());
            }
            Literal::Float(value) => {
                checked_query_hash_component(hasher, "literal-kind", "float-bits");
                checked_query_hash_component(hasher, "literal-value", &value.to_bits().to_string());
            }
            Literal::Str(value) => {
                checked_query_hash_component(hasher, "literal-kind", "string");
                checked_query_hash_component(hasher, "literal-value", value);
            }
            Literal::Char(value) => {
                checked_query_hash_component(hasher, "literal-kind", "character");
                checked_query_hash_component(hasher, "literal-value", &(*value as u32).to_string());
            }
            Literal::Bool(value) => {
                checked_query_hash_component(hasher, "literal-kind", "boolean");
                checked_query_hash_component(
                    hasher,
                    "literal-value",
                    if *value { "true" } else { "false" },
                );
            }
        }
    }

    fn pattern_site(
        site: &ExprSiteId,
        ast_path: &[u32],
        pattern_path: &[u32],
    ) -> CheckedPatternSiteId {
        CheckedPatternSiteId {
            analysis_program: site.analysis_program.clone(),
            declaration: site.declaration.clone(),
            normalized_declaration_ordinal: site.normalized_declaration_ordinal,
            ast_path: ast_path.to_vec().into_boxed_slice(),
            pattern_path: pattern_path.to_vec().into_boxed_slice(),
        }
    }

    fn hash_pattern(
        &mut self,
        hasher: &mut Sha256,
        anchor: &ExprSiteId,
        ast_path: &[u32],
        pattern: &Pat,
        pattern_path: Vec<u32>,
    ) -> Result<(), CheckedExploreQueryArtifactIssue> {
        match pattern {
            Pat::Wild => {
                checked_query_hash_component(hasher, "pattern-kind", "wildcard");
            }
            Pat::Var(_) => {
                checked_query_hash_component(hasher, "pattern-kind", "binder");
                let mut binder_path = vec![CheckedResolutionRecorder::BINDER_PATTERN];
                binder_path.extend(pattern_path);
                let binder = Self::structural_binder(anchor, ast_path, binder_path);
                self.reserve_binder(binder.clone());
                self.hash_binder_reference(hasher, binder);
            }
            Pat::Lit(literal) => {
                checked_query_hash_component(hasher, "pattern-kind", "literal");
                self.hash_literal(hasher, literal);
            }
            Pat::Con(_, children) => {
                checked_query_hash_component(hasher, "pattern-kind", "constructor");
                let resolution = self
                    .resolutions
                    .constructor_patterns
                    .get(&Self::pattern_site(anchor, ast_path, &pattern_path))
                    .cloned()
                    .ok_or_else(|| {
                        CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                            layer: self.layer.to_string().into_boxed_str(),
                            site: Some(anchor.clone()),
                        }
                    })?;
                self.record_constructor_choice(&resolution.constructor);
                self.hash_constructor(hasher, &resolution.constructor);
                checked_query_hash_component(
                    hasher,
                    "pattern-child-count",
                    &children.len().to_string(),
                );
                for (index, child) in children.iter().enumerate() {
                    let mut child_path = pattern_path.clone();
                    child_path.push(index as u32);
                    self.hash_pattern(hasher, anchor, ast_path, child, child_path)?;
                }
            }
            Pat::NamedCon(_, fields) => {
                checked_query_hash_component(hasher, "pattern-kind", "named-constructor");
                let resolution = self
                    .resolutions
                    .constructor_patterns
                    .get(&Self::pattern_site(anchor, ast_path, &pattern_path))
                    .cloned()
                    .ok_or_else(|| {
                        CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                            layer: self.layer.to_string().into_boxed_str(),
                            site: Some(anchor.clone()),
                        }
                    })?;
                self.record_constructor_choice(&resolution.constructor);
                self.hash_constructor(hasher, &resolution.constructor);
                let mut canonical_fields = resolution
                    .source_fields
                    .iter()
                    .enumerate()
                    .map(|(source_index, field)| (field.field_index, source_index))
                    .collect::<Vec<_>>();
                canonical_fields.sort_unstable();
                checked_query_hash_component(
                    hasher,
                    "pattern-field-count",
                    &canonical_fields.len().to_string(),
                );
                for (field_index, source_index) in canonical_fields {
                    checked_query_hash_component(
                        hasher,
                        "pattern-field-index",
                        &field_index.to_string(),
                    );
                    let Some((_, child)) = fields.get(source_index) else {
                        return self.unsealed(Some(anchor.clone()));
                    };
                    let mut child_path = pattern_path.clone();
                    child_path.push(source_index as u32);
                    self.hash_pattern(hasher, anchor, ast_path, child, child_path)?;
                }
            }
            Pat::As(child, _) => {
                checked_query_hash_component(hasher, "pattern-kind", "as");
                self.hash_pattern(hasher, anchor, ast_path, child, pattern_path.clone())?;
                let mut binder_path = vec![CheckedResolutionRecorder::BINDER_PATTERN];
                binder_path.extend(pattern_path);
                binder_path.push(u32::MAX);
                let binder = Self::structural_binder(anchor, ast_path, binder_path);
                self.reserve_binder(binder.clone());
                self.hash_binder_reference(hasher, binder);
            }
        }
        Ok(())
    }

    fn hash_value_binding(
        &mut self,
        hasher: &mut Sha256,
        binding: &CheckedValueBinding,
        resolution: &CheckedExpressionResolution,
        site: &ExprSiteId,
    ) -> Result<(), CheckedExploreQueryArtifactIssue> {
        match binding {
            CheckedValueBinding::Binder { site: binder, .. } => {
                checked_query_hash_component(hasher, "value-binding", "binder");
                self.hash_binder_reference(hasher, binder.clone());
            }
            CheckedValueBinding::TopLevel(binding) => {
                checked_query_hash_component(hasher, "value-binding", "top-level");
                self.producer_top_level_constants.insert(binding.clone());
                self.hash_dependency_reference(
                    hasher,
                    CheckedExploreSemanticDependency::TopLevel(binding.clone()),
                );
            }
            CheckedValueBinding::Callable(callable) => {
                checked_query_hash_component(hasher, "value-binding", "callable");
                self.hash_dependency_reference(
                    hasher,
                    CheckedExploreSemanticDependency::Callable(callable.clone()),
                );
            }
            CheckedValueBinding::RuleFamily(family) => {
                checked_query_hash_component(hasher, "value-binding", "rule-family");
                self.hash_dependency_reference(
                    hasher,
                    CheckedExploreSemanticDependency::RuleFamily(family.clone()),
                );
            }
            CheckedValueBinding::Constructor { .. } => {
                checked_query_hash_component(hasher, "value-binding", "constructor");
                let Some(constructor) = &resolution.exact_constructor else {
                    return self.unsealed(Some(site.clone()));
                };
                self.record_constructor_choice(constructor);
                self.hash_constructor(hasher, constructor);
            }
            CheckedValueBinding::OpaqueQualifiedOwner(_) => {
                return self.unsealed(Some(site.clone()));
            }
        }
        Ok(())
    }

    fn hash_expression(
        &mut self,
        hasher: &mut Sha256,
        site: &ExprSiteId,
        type_variables: &mut BTreeMap<String, usize>,
    ) -> Result<(), CheckedExploreQueryArtifactIssue> {
        // The semantic index owns a stable reference into the immutable
        // checked program. Keep that borrowed node instead of cloning its
        // entire subtree at every recursive visit: retaining one clone per
        // ancestor made closure construction quadratic in expression depth
        // and exhausted the contained heap on large law models.
        let expression: &'index Expr = self
            .index
            .expression(site)
            .ok_or_else(|| CheckedExploreQueryArtifactIssue::QuerySiteMissing(site.clone()))?;
        // Rule-head type annotations are parser-internal `__typed(value, Ty)`
        // wrappers, not runtime applications. Their marker node deliberately
        // has no inferred value type, so seal the annotation and its matched
        // value directly while retaining every other fail-closed issue.
        if let Some((_, type_name)) = typed_rule_head_argument(expression) {
            if self.is_rule_head_site(site) {
                let resolution = self.resolutions.expressions.get(site).ok_or_else(|| {
                    CheckedExploreQueryArtifactIssue::QuerySiteMissing(site.clone())
                })?;
                let expected_marker = matches!(
                    &resolution.call_target,
                    Some(CheckedCallTarget::Builtin {
                        canonical_name,
                        arity: 2,
                    }) if canonical_name.as_ref() == "__typed"
                );
                let only_expected_inference_gap = self
                    .resolutions
                    .unsupported_sites
                    .get(site)
                    .is_none_or(|issues| {
                        issues
                            .iter()
                            .all(|issue| matches!(issue, CheckedResolutionIssue::TypeNotResolved))
                    });
                let Ok(ty) = parse_type_annotation(type_name) else {
                    return self.unsealed(Some(site.clone()));
                };
                if !expected_marker || !only_expected_inference_gap {
                    return self.unsealed(Some(site.clone()));
                }
                checked_query_hash_component(hasher, "expression-kind", "typed-rule-head-argument");
                self.hash_type(hasher, &ty, type_variables)?;
                return self.hash_expression(hasher, &Self::child_site(site, 1), type_variables);
            }
        }
        // `_` in a rule head is a matcher, not a runtime value. The ordinary
        // expression inferencer therefore has no value type to assign, while
        // the checked rule-family node still needs its exact wildcard shape.
        if matches!(&expression.kind, ExprKind::Var(name) if name == "_")
            && self.is_rule_head_site(site)
        {
            let resolution =
                self.resolutions.expressions.get(site).ok_or_else(|| {
                    CheckedExploreQueryArtifactIssue::QuerySiteMissing(site.clone())
                })?;
            let only_expected_inference_gap = self
                .resolutions
                .unsupported_sites
                .get(site)
                .is_none_or(|issues| {
                    issues
                        .iter()
                        .all(|issue| matches!(issue, CheckedResolutionIssue::TypeNotResolved))
                });
            if !only_expected_inference_gap
                || !matches!(resolution.resolved_type, CheckedExpressionType::Unsupported)
                || resolution.value_binding.is_some()
            {
                return self.unsealed(Some(site.clone()));
            }
            checked_query_hash_component(hasher, "expression-type", "rule-head-wildcard");
            checked_query_hash_component(hasher, "expression-kind", "variable");
            checked_query_hash_component(hasher, "value-binding", "wildcard");
            return Ok(());
        }
        if self.resolutions.unsupported_sites.contains_key(site) {
            return self.unsealed(Some(site.clone()));
        }
        let resolution = self
            .resolutions
            .expressions
            .get(site)
            .cloned()
            .ok_or_else(|| CheckedExploreQueryArtifactIssue::QuerySiteMissing(site.clone()))?;
        match &resolution.resolved_type {
            CheckedExpressionType::Resolved(ty) => {
                checked_query_hash_component(hasher, "expression-type", "resolved");
                self.hash_type(hasher, ty, type_variables)?;
            }
            CheckedExpressionType::Callable { parameters, result } => {
                if !matches!(&expression.kind, ExprKind::Lambda(_, _)) {
                    return self.unsealed(Some(site.clone()));
                }
                checked_query_hash_component(hasher, "expression-type", "n-ary-callable");
                checked_query_hash_component(
                    hasher,
                    "callable-parameter-count",
                    &parameters.len().to_string(),
                );
                for parameter in parameters.iter() {
                    self.hash_type(hasher, parameter, type_variables)?;
                }
                self.hash_type(hasher, result, type_variables)?;
            }
            CheckedExpressionType::CallableReference => {
                if !matches!(&expression.kind, ExprKind::Var(_))
                    || !matches!(
                        &resolution.value_binding,
                        Some(CheckedValueBinding::Callable(_) | CheckedValueBinding::RuleFamily(_))
                    )
                {
                    return self.unsealed(Some(site.clone()));
                }
                checked_query_hash_component(
                    hasher,
                    "expression-type",
                    "checked-callable-reference",
                );
            }
            CheckedExpressionType::PolymorphicEmptyList => {
                if !TypeChecker::is_polymorphic_empty_list_expr(expression) {
                    return self.unsealed(Some(site.clone()));
                }
                checked_query_hash_component(hasher, "expression-type", "polymorphic-empty-list");
            }
            CheckedExpressionType::Unsupported => return self.unsealed(Some(site.clone())),
        }

        // A constructor is a proven fixed source choice only while traversing
        // the direct constructor spine of a singleton FROM expression. Any
        // intervening computation could select a different variant from a
        // varied binder, even when the closure can enumerate all reachable
        // constructor identities. Keep those occurrences fail-closed.
        let parent_constructor_choice_provenance = self.current_constructor_choice_provenance;
        if resolution.exact_constructor.is_none() {
            self.current_constructor_choice_provenance =
                CheckedExploreConstructorChoiceProvenance::Unproven;
        }

        match &expression.kind {
            ExprKind::Var(name) => {
                checked_query_hash_component(hasher, "expression-kind", "variable");
                if let Some(binding) = &resolution.value_binding {
                    self.hash_value_binding(hasher, binding, &resolution, site)?;
                } else if name == "_" {
                    checked_query_hash_component(hasher, "value-binding", "wildcard");
                } else {
                    return self.unsealed(Some(site.clone()));
                }
            }
            ExprKind::Lit(literal) => {
                checked_query_hash_component(hasher, "expression-kind", "literal");
                self.hash_literal(hasher, literal);
            }
            ExprKind::App(function, arguments) => {
                checked_query_hash_component(hasher, "expression-kind", "application");
                let Some(target) = &resolution.call_target else {
                    return self.unsealed(Some(site.clone()));
                };
                self.hash_call_target(hasher, target, site, type_variables)?;
                match (&function.kind, target) {
                    (ExprKind::Var(_), CheckedCallTarget::BoundCallable { .. }) => {
                        checked_query_hash_component(hasher, "call-receiver", "bound-callable");
                        self.hash_expression(hasher, &Self::child_site(site, 0), type_variables)?;
                    }
                    (_, CheckedCallTarget::BoundCallable { .. }) => {
                        // Bound-callable targets are minted only for a bare
                        // lexical variable. Refuse any future syntax/target
                        // mismatch instead of omitting a dynamic operator.
                        return self.unsealed(Some(site.clone()));
                    }
                    (ExprKind::Field(_, _), CheckedCallTarget::ScopedMember { .. }) => {
                        checked_query_hash_component(hasher, "call-receiver", "resolved");
                        let function_site = Self::child_site(site, 0);
                        let receiver_site = Self::child_site(&function_site, 0);
                        self.hash_expression(hasher, &receiver_site, type_variables)?;
                    }
                    (ExprKind::Field(_, _), _) | (_, CheckedCallTarget::ScopedMember { .. }) => {
                        // Checked call-target construction currently admits a
                        // scoped member exactly when syntax supplies its
                        // receiver. Refuse a future mismatched shape instead
                        // of silently dropping a function-value input.
                        return self.unsealed(Some(site.clone()));
                    }
                    _ => {
                        checked_query_hash_component(hasher, "call-receiver", "none");
                    }
                }
                checked_query_hash_component(
                    hasher,
                    "argument-count",
                    &arguments.len().to_string(),
                );
                if let Some(order) = &resolution.named_arguments {
                    checked_query_hash_component(hasher, "argument-order", "canonical-named");
                    for source_index in &order.canonical_source_indices {
                        let argument_site = Self::child_site(site, source_index + 1);
                        let value_site = Self::child_site(&argument_site, 2);
                        self.hash_expression(hasher, &value_site, type_variables)?;
                    }
                } else {
                    checked_query_hash_component(hasher, "argument-order", "positional");
                    for index in 0..arguments.len() {
                        self.hash_expression(
                            hasher,
                            &Self::child_site(site, index + 1),
                            type_variables,
                        )?;
                    }
                }
            }
            ExprKind::Lambda(parameters, _) => {
                checked_query_hash_component(hasher, "expression-kind", "lambda");
                checked_query_hash_component(
                    hasher,
                    "parameter-count",
                    &parameters.len().to_string(),
                );
                for (index, parameter) in parameters.iter().enumerate() {
                    checked_query_hash_component(
                        hasher,
                        "parameter-inout",
                        if parameter.inout { "true" } else { "false" },
                    );
                    match &parameter.ty {
                        Some(ty) => self.hash_type(hasher, ty, type_variables)?,
                        None => checked_query_hash_component(hasher, "parameter-type", "inferred"),
                    }
                    self.reserve_binder(Self::structural_binder(
                        site,
                        &site.ast_path,
                        vec![CheckedResolutionRecorder::BINDER_PARAMETER, index as u32],
                    ));
                }
                self.hash_expression(hasher, &Self::child_site(site, 0), type_variables)?;
            }
            ExprKind::BinOp(operator, _, _) => {
                checked_query_hash_component(hasher, "expression-kind", "binary");
                checked_query_hash_component(hasher, "binary-operator", operator);
                self.hash_expression(hasher, &Self::child_site(site, 0), type_variables)?;
                self.hash_expression(hasher, &Self::child_site(site, 1), type_variables)?;
            }
            ExprKind::UnOp(operator, _) => {
                checked_query_hash_component(hasher, "expression-kind", "unary");
                checked_query_hash_component(hasher, "unary-operator", operator);
                self.hash_expression(hasher, &Self::child_site(site, 0), type_variables)?;
            }
            ExprKind::If(_, _, _) => {
                checked_query_hash_component(hasher, "expression-kind", "if");
                for index in 0..3 {
                    self.hash_expression(hasher, &Self::child_site(site, index), type_variables)?;
                }
            }
            ExprKind::Match(_, arms) => {
                checked_query_hash_component(hasher, "expression-kind", "match");
                self.hash_expression(hasher, &Self::child_site(site, 0), type_variables)?;
                checked_query_hash_component(hasher, "match-arm-count", &arms.len().to_string());
                let mut child_index = 1_usize;
                for (arm_index, arm) in arms.iter().enumerate() {
                    self.hash_pattern(
                        hasher,
                        site,
                        &site.ast_path,
                        &arm.pat,
                        vec![arm_index as u32],
                    )?;
                    checked_query_hash_component(
                        hasher,
                        "match-guard",
                        if arm.guard.is_some() { "some" } else { "none" },
                    );
                    if arm.guard.is_some() {
                        self.hash_expression(
                            hasher,
                            &Self::child_site(site, child_index),
                            type_variables,
                        )?;
                        child_index += 1;
                    }
                    self.hash_expression(
                        hasher,
                        &Self::child_site(site, child_index),
                        type_variables,
                    )?;
                    child_index += 1;
                }
            }
            ExprKind::Block(statements) => {
                checked_query_hash_component(hasher, "expression-kind", "block");
                checked_query_hash_component(
                    hasher,
                    "block-statement-count",
                    &statements.len().to_string(),
                );
                for (index, statement) in statements.iter().enumerate() {
                    let statement_site = Self::child_site(site, index);
                    match statement {
                        Stmt::Bind(pattern, annotation, _) => {
                            checked_query_hash_component(hasher, "block-statement", "bind");
                            match annotation {
                                Some(ty) => self.hash_type(hasher, ty, type_variables)?,
                                None => {
                                    checked_query_hash_component(hasher, "binding-type", "inferred")
                                }
                            }
                            self.hash_expression(
                                hasher,
                                &Self::child_site(&statement_site, 0),
                                type_variables,
                            )?;
                            self.hash_pattern(
                                hasher,
                                &statement_site,
                                &statement_site.ast_path,
                                pattern,
                                Vec::new(),
                            )?;
                        }
                        Stmt::Expr(_) => {
                            checked_query_hash_component(hasher, "block-statement", "expression");
                            self.hash_expression(
                                hasher,
                                &Self::child_site(&statement_site, 0),
                                type_variables,
                            )?;
                        }
                        _ => return self.unsealed(Some(statement_site)),
                    }
                }
            }
            ExprKind::Field(_, _) => {
                checked_query_hash_component(hasher, "expression-kind", "field");
                self.hash_expression(hasher, &Self::child_site(site, 0), type_variables)?;
                match &resolution.field {
                    Some(CheckedFieldResolution::Data { fields, .. }) => {
                        checked_query_hash_component(hasher, "field-kind", "data");
                        checked_query_hash_component(
                            hasher,
                            "field-candidate-count",
                            &fields.len().to_string(),
                        );
                        for field in fields.iter() {
                            match &field.identity.owner {
                                CheckedDataTypeId::Intrinsic { canonical_name } => {
                                    checked_query_hash_component(
                                        hasher,
                                        "field-owner",
                                        canonical_name,
                                    );
                                }
                                owner @ CheckedDataTypeId::Declared(_) => {
                                    self.hash_dependency_reference(
                                        hasher,
                                        CheckedExploreSemanticDependency::DeclaredType(
                                            owner.clone(),
                                        ),
                                    );
                                }
                            }
                            checked_query_hash_component(
                                hasher,
                                "field-variant-index",
                                &field.variant_index.to_string(),
                            );
                            checked_query_hash_component(
                                hasher,
                                "field-index",
                                &field.field_index.to_string(),
                            );
                        }
                    }
                    Some(CheckedFieldResolution::ScopedMember {
                        owner_type,
                        member,
                        rule_family,
                    }) => {
                        checked_query_hash_component(hasher, "field-kind", "scoped-member");
                        if let Some(family) = rule_family {
                            self.hash_dependency_reference(
                                hasher,
                                CheckedExploreSemanticDependency::RuleFamily(family.clone()),
                            );
                        } else {
                            let callable = self.scoped_callable(owner_type, member, 0, site)?;
                            self.hash_dependency_reference(
                                hasher,
                                CheckedExploreSemanticDependency::Callable(callable),
                            );
                        }
                    }
                    None => return self.unsealed(Some(site.clone())),
                }
            }
            ExprKind::Index(_, _) => {
                checked_query_hash_component(hasher, "expression-kind", "index");
                self.hash_expression(hasher, &Self::child_site(site, 0), type_variables)?;
                self.hash_expression(hasher, &Self::child_site(site, 1), type_variables)?;
            }
            ExprKind::List(items) | ExprKind::Tuple(items) => {
                checked_query_hash_component(
                    hasher,
                    "expression-kind",
                    if matches!(&expression.kind, ExprKind::List(_)) {
                        "list"
                    } else {
                        "tuple"
                    },
                );
                checked_query_hash_component(hasher, "item-count", &items.len().to_string());
                for index in 0..items.len() {
                    self.hash_expression(hasher, &Self::child_site(site, index), type_variables)?;
                }
            }
            ExprKind::Try(_) => {
                self.effect_free = false;
                checked_query_hash_component(hasher, "expression-kind", "try");
                self.hash_expression(hasher, &Self::child_site(site, 0), type_variables)?;
            }
            ExprKind::Conjunction(items) | ExprKind::Disjunction(items) => {
                checked_query_hash_component(
                    hasher,
                    "expression-kind",
                    if matches!(&expression.kind, ExprKind::Conjunction(_)) {
                        "conjunction"
                    } else {
                        "disjunction"
                    },
                );
                checked_query_hash_component(hasher, "item-count", &items.len().to_string());
                for index in 0..items.len() {
                    self.hash_expression(hasher, &Self::child_site(site, index), type_variables)?;
                }
            }
            ExprKind::Unit => {
                checked_query_hash_component(hasher, "expression-kind", "unit");
                self.producer_literals
                    .insert(CheckedExploreSemanticLiteral::unit());
            }
            ExprKind::Effect(_, _) | ExprKind::Handle { .. } | ExprKind::Pipe(_, _) => {
                return self.unsealed(Some(site.clone()));
            }
        }
        self.current_constructor_choice_provenance = parent_constructor_choice_provenance;
        Ok(())
    }

    fn reserve_rule_head_binders(&mut self, root: &ExprSiteId) {
        let binders = self
            .resolutions
            .expressions
            .subtree(root)
            .filter_map(|(_, resolution)| match &resolution.value_binding {
                Some(CheckedValueBinding::Binder {
                    kind: CheckedBinderKind::RuleHead,
                    site,
                }) => Some(site.clone()),
                _ => None,
            })
            .collect::<Vec<_>>();
        for binder in binders {
            self.reserve_binder(binder);
        }
    }

    fn hash_rule_head(
        &mut self,
        hasher: &mut Sha256,
        root: &ExprSiteId,
        type_variables: &mut BTreeMap<String, usize>,
    ) -> Result<(), CheckedExploreQueryArtifactIssue> {
        self.reserve_rule_head_binders(root);
        let expression = self
            .index
            .expression(root)
            .ok_or_else(|| CheckedExploreQueryArtifactIssue::QuerySiteMissing(root.clone()))?;
        let ExprKind::App(_, arguments) = &expression.kind else {
            return self.unsealed(Some(root.clone()));
        };
        checked_query_hash_component(hasher, "rule-head-kind", "application");
        checked_query_hash_component(
            hasher,
            "rule-head-argument-count",
            &arguments.len().to_string(),
        );
        for index in 0..arguments.len() {
            self.hash_expression(hasher, &Self::child_site(root, index + 1), type_variables)?;
        }
        Ok(())
    }

    fn reserve_rule_scope_parameters(&mut self, declaration: &SourcedStmt) {
        let Stmt::TypeDecl(TypeDecl::RuleScope { params, .. }) = declaration.statement.as_ref()
        else {
            return;
        };
        let anchor = self.index.expression_site(declaration, &[]);
        for (index, _) in params.iter().enumerate() {
            self.reserve_binder(Self::structural_binder(
                &anchor,
                &[],
                vec![CheckedResolutionRecorder::BINDER_PARAMETER, index as u32],
            ));
        }
    }

    fn hash_top_level_dependency(
        &mut self,
        hasher: &mut Sha256,
        binding: &CheckedTopLevelBindingId,
    ) -> Result<(), CheckedExploreQueryArtifactIssue> {
        let declaration = self
            .index
            .declarations
            .get(&binding.declaration)
            .copied()
            .ok_or_else(
                || CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                    layer: self.layer.to_string().into_boxed_str(),
                    site: None,
                },
            )?;
        let Stmt::Bind(pattern, annotation, _) = declaration.statement.as_ref() else {
            return self.unsealed(None);
        };
        self.producer_top_level_constants.insert(binding.clone());
        checked_query_hash_component(hasher, "dependency-kind", "top-level-constant");
        let mut type_variables = BTreeMap::new();
        match annotation {
            Some(ty) => self.hash_type(hasher, ty, &mut type_variables)?,
            None => checked_query_hash_component(hasher, "binding-type", "inferred"),
        }
        let initializer = self.index.expression_site(declaration, &[0]);
        self.hash_expression(hasher, &initializer, &mut type_variables)?;
        self.hash_pattern(hasher, &initializer, &[], pattern, Vec::new())?;
        checked_query_hash_component(hasher, "selected-pattern-binder", "resolved");
        self.hash_binder_reference(
            hasher,
            Self::structural_binder(&initializer, &[], binding.binder_path.to_vec()),
        );
        Ok(())
    }

    fn hash_callable_dependency(
        &mut self,
        hasher: &mut Sha256,
        callable: &CheckedCallableId,
    ) -> Result<(), CheckedExploreQueryArtifactIssue> {
        let descriptor = self.index.callables.get(callable).cloned().ok_or_else(|| {
            CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                layer: self.layer.to_string().into_boxed_str(),
                site: None,
            }
        })?;
        let declaration = self
            .index
            .declarations
            .get(&callable.declaration)
            .copied()
            .ok_or_else(
                || CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                    layer: self.layer.to_string().into_boxed_str(),
                    site: Some(descriptor.body_site.clone()),
                },
            )?;
        self.reserve_rule_scope_parameters(declaration);
        checked_query_hash_component(hasher, "dependency-kind", "callable");
        checked_query_hash_component(
            hasher,
            "parameter-count",
            &descriptor.parameters.len().to_string(),
        );
        let mut type_variables = BTreeMap::new();
        for (parameter, binder) in descriptor
            .parameters
            .iter()
            .zip(descriptor.parameter_sites.iter())
        {
            checked_query_hash_component(
                hasher,
                "parameter-inout",
                if parameter.inout { "true" } else { "false" },
            );
            match &parameter.ty {
                Some(ty) => self.hash_type(hasher, ty, &mut type_variables)?,
                None => checked_query_hash_component(hasher, "parameter-type", "inferred"),
            }
            self.reserve_binder(binder.clone());
        }
        match descriptor.return_type {
            Some(ty) => self.hash_type(hasher, ty, &mut type_variables)?,
            None => checked_query_hash_component(hasher, "return-type", "inferred"),
        }
        if !descriptor.effects.is_empty() {
            // Explore is pure. Retaining a spelling-only effect row here would
            // pretend that an effect declaration's semantic ABI was sealed.
            return self.unsealed(Some(descriptor.body_site.clone()));
        }
        checked_query_hash_component(hasher, "effect-semantics", "pure");
        self.hash_expression(hasher, &descriptor.body_site, &mut type_variables)
    }

    fn hash_rule_family_dependency(
        &mut self,
        hasher: &mut Sha256,
        key: &RuleDispatchKey,
    ) -> Result<(), CheckedExploreQueryArtifactIssue> {
        let family = self
            .resolutions
            .rule_families
            .get(key)
            .cloned()
            .ok_or_else(
                || CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                    layer: self.layer.to_string().into_boxed_str(),
                    site: None,
                },
            )?;
        checked_query_hash_component(hasher, "dependency-kind", "rule-family");
        checked_query_hash_component(hasher, "rule-arity", &key.arity.to_string());
        checked_query_hash_component(
            hasher,
            "rule-miss-semantics",
            if self
                .resolutions
                .rule_dispatch_boolean_miss_safe_keys
                .contains(key)
            {
                "boolean-false"
            } else {
                "partial-miss"
            },
        );
        let mut type_variables = BTreeMap::new();
        match &key.scope {
            Some(scope) => {
                checked_query_hash_component(hasher, "rule-scope", "typed");
                self.hash_type(hasher, &Ty::Name(scope.clone()), &mut type_variables)?;
            }
            None => checked_query_hash_component(hasher, "rule-scope", "root"),
        }
        checked_query_hash_component(
            hasher,
            "rule-candidate-count",
            &family.candidates.len().to_string(),
        );
        for candidate in family.candidates.iter() {
            checked_query_hash_component(
                hasher,
                "rule-tier",
                match candidate.tier {
                    RuleDispatchTier::Exception => "exception",
                    RuleDispatchTier::ConditionalDefault => "conditional-default",
                    RuleDispatchTier::Clause => "clause",
                    RuleDispatchTier::UnconditionalDefault => "unconditional-default",
                },
            );
            let declaration = self
                .index
                .declarations
                .get(&candidate.declaration)
                .copied()
                .ok_or_else(|| {
                    CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                        layer: self.layer.to_string().into_boxed_str(),
                        site: Some(candidate.head_site.clone()),
                    }
                })?;
            self.reserve_rule_scope_parameters(declaration);
            self.hash_rule_head(hasher, &candidate.head_site, &mut type_variables)?;
            checked_query_hash_component(
                hasher,
                "rule-condition",
                if candidate.condition_site.is_some() {
                    "some"
                } else {
                    "none"
                },
            );
            if let Some(site) = &candidate.condition_site {
                self.hash_expression(hasher, site, &mut type_variables)?;
            }
            checked_query_hash_component(
                hasher,
                "rule-value",
                if candidate.value_site.is_some() {
                    "some"
                } else {
                    "none"
                },
            );
            if let Some(site) = &candidate.value_site {
                self.hash_expression(hasher, site, &mut type_variables)?;
            }
        }
        Ok(())
    }

    fn hash_declared_type_dependency(
        &mut self,
        hasher: &mut Sha256,
        owner: &CheckedDataTypeId,
    ) -> Result<(), CheckedExploreQueryArtifactIssue> {
        let CheckedDataTypeId::Declared(model_owner) = owner else {
            return self.unsealed(None);
        };
        let declaration_id = self
            .resolutions
            .data_owner_to_analysis_occurrence
            .get(model_owner)
            .ok_or_else(
                || CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                    layer: self.layer.to_string().into_boxed_str(),
                    site: None,
                },
            )?;
        let declaration = self
            .index
            .type_declarations
            .get(declaration_id)
            .copied()
            .ok_or_else(
                || CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                    layer: self.layer.to_string().into_boxed_str(),
                    site: None,
                },
            )?;
        checked_query_hash_component(hasher, "dependency-kind", "declared-type");
        checked_query_hash_component(hasher, "model-owner", &model_owner.semantic_key());
        let mut type_variables = BTreeMap::new();
        match declaration {
            TypeDecl::ADT {
                name,
                params,
                variants,
                except_from,
                ..
            } => {
                if self.index.conditional_type_names.contains(name) {
                    // Conditional type evolution is evaluated against runtime
                    // state. Until its condition and resulting schema are
                    // represented as an exact checked schema node, accepting
                    // the base ADT alone would omit a reachable dependency.
                    return self.unsealed(None);
                }
                checked_query_hash_component(hasher, "declared-type-kind", "adt");
                checked_query_hash_component(
                    hasher,
                    "type-parameter-count",
                    &params.len().to_string(),
                );
                for (index, parameter) in params.iter().enumerate() {
                    type_variables.insert(parameter.name.clone(), index);
                    checked_query_hash_component(
                        hasher,
                        "type-parameter-inout",
                        if parameter.inout { "true" } else { "false" },
                    );
                    if let Some(ty) = &parameter.ty {
                        self.hash_type(hasher, ty, &mut type_variables)?;
                    }
                }
                checked_query_hash_component(hasher, "variant-count", &variants.len().to_string());
                for variant in variants {
                    checked_query_hash_component(hasher, "variant-name", &variant.name);
                    checked_query_hash_component(
                        hasher,
                        "variant-layout",
                        if variant.positional {
                            "positional"
                        } else {
                            "named"
                        },
                    );
                    match variant.from_type.as_deref() {
                        // The parser uses this private marker for an
                        // uppercase, fieldless spelling because only ordered
                        // type registration can decide whether it includes an
                        // already-declared type or declares a nullary
                        // constructor. Never hash the marker as a type name.
                        Some("__maybe_include") => {
                            let includes_existing_type = self
                                .resolutions
                                .data_type_identities
                                .get(variant.name.as_str())
                                .is_some_and(|owner| match owner {
                                    CheckedDataTypeId::Intrinsic { .. } => true,
                                    CheckedDataTypeId::Declared(owner) => self
                                        .resolutions
                                        .data_owner_to_analysis_occurrence
                                        .get(owner)
                                        .is_some_and(|occurrence| {
                                            occurrence.normalized_ordinal
                                                < declaration_id.normalized_ordinal
                                        }),
                                });
                            if includes_existing_type {
                                checked_query_hash_component(
                                    hasher,
                                    "variant-from",
                                    "ordered-type-inclusion",
                                );
                                self.hash_type(
                                    hasher,
                                    &Ty::Name(variant.name.clone()),
                                    &mut type_variables,
                                )?;
                            } else {
                                checked_query_hash_component(
                                    hasher,
                                    "variant-from",
                                    "nullary-constructor",
                                );
                            }
                        }
                        Some(from_type) => {
                            checked_query_hash_component(hasher, "variant-from", "qualified-type");
                            self.hash_type(
                                hasher,
                                &Ty::Name(from_type.to_string()),
                                &mut type_variables,
                            )?;
                        }
                        None => checked_query_hash_component(hasher, "variant-from", "none"),
                    }
                    checked_query_hash_component(
                        hasher,
                        "field-count",
                        &variant.fields.len().to_string(),
                    );
                    for field in &variant.fields {
                        checked_query_hash_component(hasher, "field-name", &field.name);
                        self.hash_type(hasher, &field.ty, &mut type_variables)?;
                    }
                }
                match except_from {
                    Some((from_type, excluded)) => {
                        checked_query_hash_component(hasher, "except-from", "some");
                        self.hash_type(hasher, &Ty::Name(from_type.clone()), &mut type_variables)?;
                        let excluded = excluded.iter().collect::<BTreeSet<_>>();
                        for variant in excluded {
                            checked_query_hash_component(hasher, "except-variant", variant);
                        }
                    }
                    None => checked_query_hash_component(hasher, "except-from", "none"),
                }
            }
            TypeDecl::RuleScope { params, .. } => {
                checked_query_hash_component(hasher, "declared-type-kind", "rule-scope");
                checked_query_hash_component(hasher, "field-count", &params.len().to_string());
                for parameter in params {
                    checked_query_hash_component(hasher, "field-name", &parameter.name);
                    checked_query_hash_component(
                        hasher,
                        "field-inout",
                        if parameter.inout { "true" } else { "false" },
                    );
                    match &parameter.ty {
                        Some(ty) => self.hash_type(hasher, ty, &mut type_variables)?,
                        None => checked_query_hash_component(hasher, "field-type", "inferred"),
                    }
                }
            }
            _ => return self.unsealed(None),
        }
        Ok(())
    }

    fn finish_digest(
        mut self,
        mut hasher: Sha256,
    ) -> Result<CheckedExploreSemanticSeal, CheckedExploreQueryArtifactIssue> {
        // Dependencies are semantically sealed, but their constructor choices
        // are not direct singleton-FROM occurrences. Interprocedural control
        // and data dependence therefore remain coverage gaps.
        self.current_constructor_choice_provenance =
            CheckedExploreConstructorChoiceProvenance::Unproven;
        let mut reachable_declarations = BTreeSet::new();
        let mut reachable_dependencies = BTreeSet::new();
        let mut node_index = 0_usize;
        while node_index < self.dependencies.len() {
            let dependency = self.dependencies[node_index].clone();
            checked_query_hash_component(
                &mut hasher,
                "dependency-node-index",
                &node_index.to_string(),
            );
            match &dependency {
                CheckedExploreSemanticDependency::TopLevel(binding) => {
                    self.hash_top_level_dependency(&mut hasher, binding)?;
                    reachable_declarations.insert(binding.declaration.clone());
                }
                CheckedExploreSemanticDependency::Callable(callable) => {
                    self.hash_callable_dependency(&mut hasher, callable)?;
                    reachable_declarations.insert(callable.declaration.clone());
                }
                CheckedExploreSemanticDependency::RuleFamily(key) => {
                    self.hash_rule_family_dependency(&mut hasher, key)?;
                    let family = self.resolutions.rule_families.get(key).ok_or_else(|| {
                        CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                            layer: self.layer.to_string().into_boxed_str(),
                            site: None,
                        }
                    })?;
                    reachable_declarations.extend(
                        family
                            .candidates
                            .iter()
                            .map(|candidate| candidate.declaration.clone()),
                    );
                }
                CheckedExploreSemanticDependency::DeclaredType(owner) => {
                    self.hash_declared_type_dependency(&mut hasher, owner)?;
                    if let CheckedDataTypeId::Declared(model_owner) = owner {
                        let declaration = self
                            .resolutions
                            .data_owner_to_analysis_occurrence
                            .get(model_owner)
                            .ok_or_else(|| {
                                CheckedExploreQueryArtifactIssue::SemanticDependencyClosureUnsealed {
                                    layer: self.layer.to_string().into_boxed_str(),
                                    site: None,
                                }
                            })?;
                        reachable_declarations.insert(declaration.clone());
                    }
                }
            }
            reachable_dependencies.insert(dependency);
            node_index += 1;
        }
        checked_query_hash_component(
            &mut hasher,
            "dependency-node-count",
            &self.dependencies.len().to_string(),
        );
        if !self.effect_free || !self.dynamic_captures.is_empty() {
            // A content-addressed Explore identity may describe only a closed,
            // pure computation. Retaining these as advisory flags lets an
            // effectful named callback or an unbound capture enter ordinary
            // relation/view identities even though observer memoization later
            // refuses it.
            return self.unsealed(None);
        }
        Ok(CheckedExploreSemanticSeal {
            digest: hasher.finalize().into(),
            reachable_declarations,
            reachable_dependencies,
            producer_inputs: CheckedExploreSemanticProducerInputs {
                literals: self.producer_literals,
                top_level_constants: self.producer_top_level_constants,
                constructor_choices: self.producer_constructor_choices,
            },
            dynamic_captures: self.dynamic_captures,
            effect_free: self.effect_free,
        })
    }

    fn seal_with_conditioned_constructor_roots(
        mut self,
        expression_roots: &[ExprSiteId],
        type_roots: &[Ty],
        conditioned_constructor_roots: &BTreeSet<ExprSiteId>,
    ) -> Result<CheckedExploreSemanticSeal, CheckedExploreQueryArtifactIssue> {
        if !self.resolutions.source_snapshot_coherent {
            return self.unsealed(None);
        }
        let mut hasher = Sha256::new();
        hasher.update(b"futuruna.checked-explore-semantic-closure.v1\0");
        checked_query_hash_component(&mut hasher, "builtin-semantic-abi", "v1");
        checked_query_hash_component(
            &mut hasher,
            "expression-root-count",
            &expression_roots.len().to_string(),
        );
        for root in expression_roots {
            self.current_constructor_choice_provenance =
                if conditioned_constructor_roots.contains(root) {
                    CheckedExploreConstructorChoiceProvenance::ConditionedFromSourceSingleton
                } else {
                    CheckedExploreConstructorChoiceProvenance::Unproven
                };
            let mut type_variables = BTreeMap::new();
            self.hash_expression(&mut hasher, root, &mut type_variables)?;
        }
        checked_query_hash_component(
            &mut hasher,
            "type-root-count",
            &type_roots.len().to_string(),
        );
        for ty in type_roots {
            self.hash_type(&mut hasher, ty, &mut BTreeMap::new())?;
        }
        self.finish_digest(hasher)
    }

    fn seal(
        self,
        expression_roots: &[ExprSiteId],
        type_roots: &[Ty],
    ) -> Result<CheckedExploreSemanticSeal, CheckedExploreQueryArtifactIssue> {
        self.seal_with_conditioned_constructor_roots(expression_roots, type_roots, &BTreeSet::new())
    }

    fn seal_source(
        self,
        expression_roots: &[ExprSiteId],
        type_roots: &[Ty],
        conditioned_constructor_roots: &BTreeSet<ExprSiteId>,
    ) -> Result<CheckedExploreSemanticSeal, CheckedExploreQueryArtifactIssue> {
        self.seal_with_conditioned_constructor_roots(
            expression_roots,
            type_roots,
            conditioned_constructor_roots,
        )
    }

    fn dependency_seal(
        mut self,
        dependency: CheckedExploreSemanticDependency,
    ) -> Result<CheckedExploreSemanticSeal, CheckedExploreQueryArtifactIssue> {
        if !self.resolutions.source_snapshot_coherent {
            return self.unsealed(None);
        }
        let mut hasher = Sha256::new();
        hasher.update(b"futuruna.checked-explore-semantic-dependency-root.v1\0");
        checked_query_hash_component(&mut hasher, "builtin-semantic-abi", "v1");
        self.hash_dependency_reference(&mut hasher, dependency);
        self.finish_digest(hasher)
    }
}

fn checked_explore_semantic_dependency_seal(
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
    semantic_binders: &BTreeMap<CheckedBinderSiteId, Box<str>>,
    layer: &str,
    expression_roots: &[ExprSiteId],
    type_roots: &[Ty],
) -> Result<CheckedExploreSemanticSeal, CheckedExploreQueryArtifactIssue> {
    CheckedExploreSemanticClosure::new(index, resolutions, layer, semantic_binders)
        .seal(expression_roots, type_roots)
}

fn checked_explore_semantic_dependency_digest(
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
    semantic_binders: &BTreeMap<CheckedBinderSiteId, Box<str>>,
    layer: &str,
    expression_roots: &[ExprSiteId],
    type_roots: &[Ty],
) -> Result<[u8; 32], CheckedExploreQueryArtifactIssue> {
    checked_explore_semantic_dependency_seal(
        index,
        resolutions,
        semantic_binders,
        layer,
        expression_roots,
        type_roots,
    )
    .map(|seal| seal.digest)
}

#[derive(Debug, Clone, Copy)]
struct CheckedExactObserverCallOccurrences {
    count: usize,
    minimum_depth: usize,
    first_order_result: bool,
}

fn checked_exact_observer_type_is_first_order(
    ty: &Ty,
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
    visiting: &mut BTreeSet<CheckedDataTypeId>,
) -> bool {
    match ty {
        Ty::Name(name) => {
            let Some(owner) = resolutions.data_type_identities.get(name.as_str()) else {
                return matches!(
                    name.as_str(),
                    "Int" | "Float" | "String" | "Char" | "Bool" | "Unit"
                );
            };
            match owner {
                CheckedDataTypeId::Intrinsic { canonical_name } => !matches!(
                    canonical_name.as_ref(),
                    "Stream" | "Subject" | "Db" | "TypeDef" | "ProgramReference" | "RuleScope"
                ),
                owner @ CheckedDataTypeId::Declared(model_owner) => {
                    if !visiting.insert(owner.clone()) {
                        return true;
                    }
                    let declaration = resolutions
                        .data_owner_to_analysis_occurrence
                        .get(model_owner);
                    let first_order = match declaration
                        .and_then(|declaration| index.type_declarations.get(declaration))
                        .copied()
                    {
                        Some(TypeDecl::ADT { variants, .. }) => variants.iter().all(|variant| {
                            variant.fields.iter().all(|field| {
                                checked_exact_observer_type_is_first_order(
                                    &field.ty,
                                    index,
                                    resolutions,
                                    visiting,
                                )
                            })
                        }),
                        _ => false,
                    };
                    visiting.remove(owner);
                    first_order
                }
            }
        }
        Ty::App(constructor, arguments) => {
            let allowed_container = matches!(
                type_name(constructor),
                Some("List" | "Map" | "Set" | "Tuple" | "Option")
            );
            (allowed_container
                || checked_exact_observer_type_is_first_order(
                    constructor,
                    index,
                    resolutions,
                    visiting,
                ))
                && arguments.iter().all(|argument| {
                    checked_exact_observer_type_is_first_order(
                        argument,
                        index,
                        resolutions,
                        visiting,
                    )
                })
        }
        Ty::Optional(inner) => {
            checked_exact_observer_type_is_first_order(inner, index, resolutions, visiting)
        }
        Ty::Unit => true,
        Ty::Arrow(_, _) | Ty::Ref(_) | Ty::MutRef(_) | Ty::Shared(_) | Ty::Var(_) | Ty::Hole => {
            false
        }
    }
}

fn checked_exact_observer_call_result_is_first_order(
    resolution: &CheckedExpressionResolution,
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
) -> bool {
    match &resolution.resolved_type {
        CheckedExpressionType::Resolved(ty) => {
            checked_exact_observer_type_is_first_order(ty, index, resolutions, &mut BTreeSet::new())
        }
        CheckedExpressionType::Callable { .. }
        | CheckedExpressionType::CallableReference
        | CheckedExpressionType::PolymorphicEmptyList => false,
        CheckedExpressionType::Unsupported => false,
    }
}

fn checked_exact_observer_call_occurrences(
    root: &ExprSiteId,
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
) -> Option<BTreeMap<RuleDispatchKey, CheckedExactObserverCallOccurrences>> {
    let trace = std::env::var_os("FUTURUNA_EXPLORE_TRACE").is_some();
    let mut occurrences = BTreeMap::<RuleDispatchKey, CheckedExactObserverCallOccurrences>::new();
    let mut pending_expression_roots = vec![(root.clone(), 0_usize)];
    let mut next_root = 0_usize;
    let mut visited_roots = BTreeSet::<ExprSiteId>::new();
    let mut expanded_callables = BTreeSet::<CheckedCallableId>::new();
    let mut expanded_families = BTreeSet::<RuleDispatchKey>::new();

    while next_root < pending_expression_roots.len() {
        let (root, depth) = pending_expression_roots[next_root].clone();
        next_root += 1;
        if !visited_roots.insert(root.clone()) {
            continue;
        }
        if !index.contains_expression(&root) || !resolutions.expressions.contains_key(&root) {
            if trace {
                eprintln!(
                    "[explore trace] observer memo occurrence closure missing root: {root:?}"
                );
            }
            return None;
        }
        for (site, resolution) in resolutions.expressions.subtree(&root) {
            if !index.contains_expression(&site) {
                if trace {
                    eprintln!(
                        "[explore trace] observer memo occurrence closure missing indexed site: {site:?}"
                    );
                }
                return None;
            }
            if let Some(issues) = resolutions.unsupported_sites.get(&site) {
                if trace {
                    eprintln!(
                        "[explore trace] observer memo occurrence closure unsupported site: site={site:?} issues={issues:?}"
                    );
                }
                return None;
            }
            match resolution.call_target.as_ref() {
                Some(CheckedCallTarget::RuleFamily(family)) => {
                    let first_order_result = checked_exact_observer_call_result_is_first_order(
                        resolution,
                        index,
                        resolutions,
                    );
                    occurrences
                        .entry(family.clone())
                        .and_modify(|record| {
                            record.count = record.count.saturating_add(1);
                            record.minimum_depth = record.minimum_depth.min(depth);
                            record.first_order_result &= first_order_result;
                        })
                        .or_insert(CheckedExactObserverCallOccurrences {
                            count: 1,
                            minimum_depth: depth,
                            first_order_result,
                        });
                    if family.scope.is_none() && expanded_families.insert(family.clone()) {
                        let Some(checked_family) = resolutions.rule_families.get(family) else {
                            if trace {
                                eprintln!(
                                    "[explore trace] observer memo occurrence closure missing family: {family:?}"
                                );
                            }
                            return None;
                        };
                        for candidate in checked_family.candidates.iter() {
                            if let Some(condition) = &candidate.condition_site {
                                pending_expression_roots.push((condition.clone(), depth + 1));
                            }
                            if let Some(value) = &candidate.value_site {
                                pending_expression_roots.push((value.clone(), depth + 1));
                            }
                        }
                    }
                }
                Some(CheckedCallTarget::Function { callable, .. }) => {
                    if expanded_callables.insert(callable.clone()) {
                        let Some(checked_callable) = index.callables.get(callable) else {
                            if trace {
                                eprintln!(
                                    "[explore trace] observer memo occurrence closure missing callable: {callable:?}"
                                );
                            }
                            return None;
                        };
                        if !checked_callable.effects.is_empty() {
                            if trace {
                                eprintln!(
                                    "[explore trace] observer memo occurrence closure effectful callable: callable={callable:?} effects={:?}",
                                    checked_callable.effects,
                                );
                            }
                            return None;
                        }
                        pending_expression_roots
                            .push((checked_callable.body_site.clone(), depth + 1));
                    }
                }
                Some(CheckedCallTarget::BoundCallable { .. }) => {
                    // A lexical callback has no additional statically named
                    // rule-family occurrence to count here. Do not disable
                    // memo planning for the entire checked observer graph:
                    // each candidate family still passes its own semantic
                    // dependency seal, and runtime key construction rejects
                    // callable arguments that lack a canonical value identity.
                }
                Some(CheckedCallTarget::ScopedMember { .. })
                | Some(CheckedCallTarget::Builtin { .. })
                | Some(CheckedCallTarget::Constructor { .. })
                | None => {}
            }
        }
    }
    Some(occurrences)
}

fn checked_exact_observer_memo_plan_from_checked(
    program: &CheckedAnalysisProgram,
    resolutions: &CheckedResolutionArtifacts,
    checked: &CheckedExploreQueryView<'_>,
) -> Option<CheckedExactObserverMemoPlan> {
    let index = CheckedExploreSemanticIndex::build(program);
    checked_exact_observer_memo_plan_from_checked_with_index(program, resolutions, checked, &index)
}

fn checked_exact_observer_memo_plan_from_checked_with_index(
    program: &CheckedAnalysisProgram,
    resolutions: &CheckedResolutionArtifacts,
    checked: &CheckedExploreQueryView<'_>,
    index: &CheckedExploreSemanticIndex<'_>,
) -> Option<CheckedExactObserverMemoPlan> {
    let trace = std::env::var_os("FUTURUNA_EXPLORE_TRACE").is_some();
    if program.id != resolutions.analysis_program
        || checked.artifact.identity.analysis_program != program.id
        || index.program.id != program.id
        || !resolutions.source_snapshot_coherent
    {
        if trace {
            eprintln!("[explore trace] observer memo disabled: checked program identity mismatch");
        }
        return None;
    }
    // V1 targets the repeated Before/After observation frontier feeding FIND.
    // Result expressions can reuse those entries, but do not independently
    // widen the eligible family set into the full downstream tax-rule graph.
    let Some(selection) = checked.artifact.sites.selection.as_ref() else {
        if trace {
            eprintln!("[explore trace] observer memo disabled: FIND has no selection predicate");
        }
        return None;
    };
    let Some(occurrences) = checked_exact_observer_call_occurrences(selection, index, resolutions)
    else {
        if trace {
            eprintln!(
                "[explore trace] observer memo disabled: static call-occurrence closure is unavailable"
            );
        }
        return None;
    };
    let mut eligible = Vec::<(
        usize,
        RuleDispatchKey,
        CheckedExactObserverRuleFamilyIdentity,
    )>::new();

    for (family, occurrence) in occurrences {
        if family.scope.is_some() || occurrence.count < 2 || !occurrence.first_order_result {
            continue;
        }
        let seal = CheckedExploreSemanticClosure::new(
            index,
            resolutions,
            "checked exact observer memo",
            &BTreeMap::new(),
        )
        .dependency_seal(CheckedExploreSemanticDependency::RuleFamily(family.clone()));
        let Ok(seal) = seal else {
            if trace {
                eprintln!(
                    "[explore trace] observer memo candidate rejected: family={family:?} reason=semantic_dependency_unsealed"
                );
            }
            continue;
        };
        if !seal.dynamic_captures.is_empty() || !seal.effect_free {
            if trace {
                eprintln!(
                    "[explore trace] observer memo candidate rejected: family={family:?} dynamic_captures={} effect_free={}",
                    seal.dynamic_captures.len(),
                    seal.effect_free,
                );
            }
            continue;
        }
        let checked_family = resolutions.rule_families.get(&family)?;
        let candidates = checked_family
            .candidates
            .iter()
            .map(|candidate| CheckedExactObserverRuleCandidateIdentity {
                tier: candidate.tier,
                source_order: candidate.source_order,
                declaration: candidate.declaration.clone(),
                statement_path: candidate.statement_path.clone(),
            })
            .collect::<Vec<_>>()
            .into_boxed_slice();
        eligible.push((
            occurrence.minimum_depth,
            family.clone(),
            CheckedExactObserverRuleFamilyIdentity {
                analysis_program: program.id.clone(),
                dispatch: family,
                candidates,
                semantic_digest: seal.digest,
            },
        ));
    }

    let Some(minimum_depth) = eligible.iter().map(|(depth, _, _)| *depth).min() else {
        if trace {
            eprintln!(
                "[explore trace] observer memo disabled: no repeated sealed first-order family"
            );
        }
        return None;
    };
    let families = eligible
        .into_iter()
        .filter(|(depth, _, _)| *depth == minimum_depth)
        .map(|(_, family, identity)| (family, Arc::new(identity)))
        .collect::<BTreeMap<_, _>>();
    if trace {
        eprintln!(
            "[explore trace] observer memo plan: eligible_families={} minimum_depth={minimum_depth}",
            families.len(),
        );
    }
    (!families.is_empty()).then(|| CheckedExactObserverMemoPlan {
        analysis_program: program.id.clone(),
        families,
    })
}

fn checked_mechanism_rule_memo_plan_from_checked_with_index(
    program: &CheckedAnalysisProgram,
    resolutions: &CheckedResolutionArtifacts,
    checked: &CheckedExploreQueryView<'_>,
    index: &CheckedExploreSemanticIndex<'_>,
) -> Option<CheckedMechanismRuleMemoPlan> {
    let trace = std::env::var_os("FUTURUNA_EXPLORE_TRACE").is_some();
    if program.id != resolutions.analysis_program
        || checked.artifact.identity.analysis_program != program.id
        || index.program.id != program.id
        || !resolutions.source_snapshot_coherent
    {
        if trace {
            eprintln!(
                "[explore trace] mechanism rule memo disabled: checked program identity mismatch"
            );
        }
        return None;
    }

    let roots = checked
        .artifact
        .analysis
        .iter()
        .filter_map(|identity| match identity {
            CheckedExploreAnalysisIdentity::Mechanisms { observation, .. } => {
                Some(observation.template_site.clone())
            }
            CheckedExploreAnalysisIdentity::View { .. } => None,
        })
        .collect::<BTreeSet<_>>();
    if roots.is_empty() {
        return None;
    }

    let mut reachable = BTreeMap::<RuleDispatchKey, bool>::new();
    for root in roots {
        let Some(occurrences) = checked_exact_observer_call_occurrences(&root, index, resolutions)
        else {
            if trace {
                eprintln!(
                    "[explore trace] mechanism rule memo disabled: endpoint call closure is unavailable"
                );
            }
            return None;
        };
        for (family, occurrence) in occurrences {
            reachable
                .entry(family)
                .and_modify(|first_order| *first_order &= occurrence.first_order_result)
                .or_insert(occurrence.first_order_result);
        }
    }

    let mut families = BTreeMap::new();
    for (family, first_order_result) in reachable {
        if family.scope.is_some() || !first_order_result {
            continue;
        }
        let seal = CheckedExploreSemanticClosure::new(
            index,
            resolutions,
            "checked mechanism rule memo",
            &BTreeMap::new(),
        )
        .dependency_seal(CheckedExploreSemanticDependency::RuleFamily(family.clone()));
        let Ok(seal) = seal else {
            if trace {
                eprintln!(
                    "[explore trace] mechanism rule memo candidate rejected: family={family:?} reason=semantic_dependency_unsealed"
                );
            }
            continue;
        };
        if !seal.dynamic_captures.is_empty() || !seal.effect_free {
            if trace {
                eprintln!(
                    "[explore trace] mechanism rule memo candidate rejected: family={family:?} dynamic_captures={} effect_free={}",
                    seal.dynamic_captures.len(),
                    seal.effect_free,
                );
            }
            continue;
        }
        let Some(checked_family) = resolutions.rule_families.get(&family) else {
            if trace {
                eprintln!(
                    "[explore trace] mechanism rule memo candidate rejected: family={family:?} reason=checked_family_missing"
                );
            }
            continue;
        };
        let candidates = checked_family
            .candidates
            .iter()
            .map(|candidate| CheckedExactObserverRuleCandidateIdentity {
                tier: candidate.tier,
                source_order: candidate.source_order,
                declaration: candidate.declaration.clone(),
                statement_path: candidate.statement_path.clone(),
            })
            .collect::<Vec<_>>()
            .into_boxed_slice();
        let identity = CheckedExactObserverRuleFamilyIdentity {
            analysis_program: program.id.clone(),
            dispatch: family.clone(),
            candidates,
            semantic_digest: seal.digest,
        };
        families.insert(family, Arc::new(identity));
    }

    if trace {
        eprintln!(
            "[explore trace] mechanism rule memo plan: eligible_families={}",
            families.len(),
        );
    }
    (!families.is_empty()).then(|| CheckedMechanismRuleMemoPlan {
        analysis_program: program.id.clone(),
        families: Arc::new(families),
    })
}

#[derive(Debug, Clone)]
struct CheckedExploreSchemaFieldDescriptor {
    path: Box<[CheckedExploreCoverageFieldPathSegment]>,
    completeness_gap: Option<CheckedExploreCoverageGapReason>,
}

#[derive(Debug, Clone)]
struct CheckedExploreSchemaDescriptor {
    fields: Vec<CheckedExploreSchemaFieldDescriptor>,
    completeness_gap: Option<CheckedExploreCoverageGapReason>,
}

#[derive(Debug, Clone)]
struct CheckedExploreDirectSchemaField {
    segment: CheckedExploreCoverageFieldPathSegment,
    field_ty: Option<Ty>,
}

#[derive(Debug, Clone)]
struct CheckedExploreSchemaNode {
    owner: CheckedDataTypeId,
    fields: Vec<CheckedExploreDirectSchemaField>,
    completeness_gap: Option<CheckedExploreCoverageGapReason>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CheckedExploreBindingCoverage {
    Varied([u8; 32]),
    Derived(BTreeSet<[u8; 32]>),
    Conditioned,
    Gap(CheckedExploreCoverageGapReason),
}

impl CheckedExploreBindingCoverage {
    fn classification(&self) -> CheckedExploreCoverageClassification {
        match self {
            Self::Varied(dimension_id) => {
                CheckedExploreCoverageClassification::VariedFiniteDimension {
                    dimension_id: *dimension_id,
                }
            }
            Self::Derived(dimension_ids) => {
                CheckedExploreCoverageClassification::DerivedFromDeclaredDimensions {
                    dimension_ids: dimension_ids
                        .iter()
                        .copied()
                        .collect::<Vec<_>>()
                        .into_boxed_slice(),
                }
            }
            Self::Conditioned => {
                CheckedExploreCoverageClassification::ConditionedSingletonOrSourceRestriction
            }
            Self::Gap(reason) => {
                CheckedExploreCoverageClassification::CoverageGap { reason: *reason }
            }
        }
    }

    fn projected_classification(&self) -> CheckedExploreCoverageClassification {
        match self {
            Self::Varied(dimension_id) => {
                CheckedExploreCoverageClassification::DerivedFromDeclaredDimensions {
                    dimension_ids: vec![*dimension_id].into_boxed_slice(),
                }
            }
            _ => self.classification(),
        }
    }
}

fn checked_explore_coverage_role(
    role: explore::ExploreSourceBindingRoleIr,
) -> CheckedExploreCoverageBindingRole {
    match role {
        explore::ExploreSourceBindingRoleIr::Auxiliary => {
            CheckedExploreCoverageBindingRole::Auxiliary
        }
        explore::ExploreSourceBindingRoleIr::Context => CheckedExploreCoverageBindingRole::Context,
        explore::ExploreSourceBindingRoleIr::Before => CheckedExploreCoverageBindingRole::Before,
    }
}

fn checked_explore_coverage_subject_id(
    relation_id: explore::RelationId,
    kind: &str,
    components: impl IntoIterator<Item = Box<str>>,
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-coverage-subject.v2\0");
    hasher.update(relation_id.bytes());
    checked_query_hash_component(&mut hasher, "subject-kind", kind);
    for component in components {
        checked_query_hash_component(&mut hasher, "subject-component", &component);
    }
    hasher.finalize().into()
}

fn checked_explore_source_binding_subject_id(
    relation_id: explore::RelationId,
    binding: &explore::ExploreSourceBindingIr,
) -> [u8; 32] {
    checked_explore_source_binding_subject_id_from_parts(
        relation_id,
        checked_explore_coverage_role(binding.role),
        binding.binding_index,
    )
}

fn checked_explore_source_binding_subject_id_from_parts(
    relation_id: explore::RelationId,
    role: CheckedExploreCoverageBindingRole,
    binding_index: usize,
) -> [u8; 32] {
    checked_explore_coverage_subject_id(
        relation_id,
        "source-binding",
        [
            match role {
                CheckedExploreCoverageBindingRole::Auxiliary => "auxiliary",
                CheckedExploreCoverageBindingRole::Context => "context",
                CheckedExploreCoverageBindingRole::Before => "before",
            }
            .into(),
            binding_index.to_string().into_boxed_str(),
        ],
    )
}

fn checked_explore_schema_root_subject_id(
    relation_id: explore::RelationId,
    role: CheckedExploreCoverageRootRole,
) -> [u8; 32] {
    checked_explore_coverage_subject_id(
        relation_id,
        "schema-root",
        [match role {
            CheckedExploreCoverageRootRole::Context => "context".into(),
            CheckedExploreCoverageRootRole::Before => "before".into(),
        }],
    )
}

fn checked_explore_schema_field_subject_id(
    relation_id: explore::RelationId,
    role: CheckedExploreCoverageRootRole,
    path: &[CheckedExploreCoverageFieldPathSegment],
) -> [u8; 32] {
    let mut components = Vec::with_capacity(path.len().saturating_mul(2).saturating_add(2));
    components.push(
        match role {
            CheckedExploreCoverageRootRole::Context => "context",
            CheckedExploreCoverageRootRole::Before => "before",
        }
        .into(),
    );
    components.push(path.len().to_string().into_boxed_str());
    for segment in path {
        components.push(segment.variant_index.to_string().into_boxed_str());
        components.push(segment.field_index.to_string().into_boxed_str());
    }
    checked_explore_coverage_subject_id(relation_id, "schema-field-path", components)
}

fn checked_explore_literal_subject_id(
    relation_id: explore::RelationId,
    literal: &CheckedExploreSemanticLiteral,
) -> [u8; 32] {
    checked_explore_literal_subject_id_from_parts(relation_id, literal.kind, &literal.value)
}

fn checked_explore_literal_subject_id_from_parts(
    relation_id: explore::RelationId,
    kind: CheckedExploreCoverageLiteralKind,
    value: &str,
) -> [u8; 32] {
    checked_explore_coverage_subject_id(
        relation_id,
        "literal",
        [
            match kind {
                CheckedExploreCoverageLiteralKind::Integer => "integer".into(),
                CheckedExploreCoverageLiteralKind::FloatBits => "float-bits".into(),
                CheckedExploreCoverageLiteralKind::String => "string".into(),
                CheckedExploreCoverageLiteralKind::Character => "character".into(),
                CheckedExploreCoverageLiteralKind::Boolean => "boolean".into(),
                CheckedExploreCoverageLiteralKind::Unit => "unit".into(),
            },
            value.to_string().into_boxed_str(),
        ],
    )
}

fn checked_explore_semantic_dependency_root_digest(
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
    semantic_binders: &BTreeMap<CheckedBinderSiteId, Box<str>>,
    dependency: CheckedExploreSemanticDependency,
) -> Result<[u8; 32], CheckedExploreQueryArtifactIssue> {
    CheckedExploreSemanticClosure::new(
        index,
        resolutions,
        "source coverage producer input",
        semantic_binders,
    )
    .dependency_seal(dependency)
    .map(|seal| seal.digest)
}

fn checked_explore_classification_hash(
    hasher: &mut Sha256,
    classification: &CheckedExploreCoverageClassification,
) {
    match classification {
        CheckedExploreCoverageClassification::VariedFiniteDimension { dimension_id } => {
            checked_query_hash_component(hasher, "coverage-class", "varied-finite-dimension");
            hasher.update(dimension_id);
        }
        CheckedExploreCoverageClassification::DerivedFromDeclaredDimensions { dimension_ids } => {
            checked_query_hash_component(
                hasher,
                "coverage-class",
                "derived-from-declared-dimensions",
            );
            checked_query_hash_component(
                hasher,
                "coverage-dimension-count",
                &dimension_ids.len().to_string(),
            );
            for dimension_id in dimension_ids {
                hasher.update(dimension_id);
            }
        }
        CheckedExploreCoverageClassification::ConditionedSingletonOrSourceRestriction => {
            checked_query_hash_component(
                hasher,
                "coverage-class",
                "conditioned-singleton-or-source-restriction",
            );
        }
        CheckedExploreCoverageClassification::ExactIrrelevanceCertificate {
            certificate_digest,
        } => {
            checked_query_hash_component(hasher, "coverage-class", "exact-irrelevance-certificate");
            hasher.update(certificate_digest);
        }
        CheckedExploreCoverageClassification::CoverageGap { reason } => {
            checked_query_hash_component(hasher, "coverage-class", "coverage-gap");
            checked_query_hash_component(
                hasher,
                "coverage-gap-reason",
                match reason {
                    CheckedExploreCoverageGapReason::SchemaNotDeclaredRecord => {
                        "schema-not-declared-record"
                    }
                    CheckedExploreCoverageGapReason::SchemaCompositionUnavailable => {
                        "schema-composition-unavailable"
                    }
                    CheckedExploreCoverageGapReason::InterproceduralFieldProvenance => {
                        "interprocedural-field-provenance"
                    }
                    CheckedExploreCoverageGapReason::ConstructorFieldMappingUnavailable => {
                        "constructor-field-mapping-unavailable"
                    }
                    CheckedExploreCoverageGapReason::ConstructorChoiceProvenanceUnavailable => {
                        "constructor-choice-provenance-unavailable"
                    }
                    CheckedExploreCoverageGapReason::UpstreamCoverageGap => "upstream-coverage-gap",
                },
            );
        }
    }
}

fn checked_explore_source_coverage_manifest_digest(
    version: u32,
    relation_id: explore::RelationId,
    semantic_dependency_digest: [u8; 32],
    entries: &[CheckedExploreCoverageEntry],
) -> Box<str> {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-coverage-manifest.v2\0");
    checked_query_hash_component(&mut hasher, "coverage-version", &version.to_string());
    hasher.update(relation_id.bytes());
    hasher.update(semantic_dependency_digest);
    checked_query_hash_component(
        &mut hasher,
        "coverage-entry-count",
        &entries.len().to_string(),
    );
    for entry in entries {
        hasher.update(entry.subject_id);
        checked_explore_classification_hash(&mut hasher, &entry.classification);
    }
    format!("{:x}", hasher.finalize()).into_boxed_str()
}

fn checked_explore_type_owner_name(ty: &Ty) -> Option<&str> {
    match ty {
        Ty::Name(name) => Some(name),
        Ty::App(constructor, _) => checked_explore_type_owner_name(constructor),
        Ty::Ref(inner) | Ty::MutRef(inner) | Ty::Shared(inner) => {
            checked_explore_type_owner_name(inner)
        }
        Ty::Optional(_) => Some("Option"),
        Ty::Unit => Some("Unit"),
        Ty::Arrow(_, _) | Ty::Var(_) | Ty::Hole => None,
    }
}

fn checked_explore_intrinsic_schema_field_ty(
    owner_name: &str,
    ty: &Ty,
    variant_index: usize,
    field_index: usize,
) -> Option<Ty> {
    match (owner_name, ty, variant_index, field_index) {
        ("Option", Ty::Optional(inner), 1, 0) => Some((**inner).clone()),
        ("Option", Ty::App(_, arguments), 1, 0) => arguments.first().cloned(),
        ("Result", Ty::App(_, arguments), 0, 0) => arguments.first().cloned(),
        ("Result", Ty::App(_, arguments), 1, 0) => arguments.get(1).cloned(),
        ("Pair", Ty::App(_, arguments), 0, field_index) => arguments.get(field_index).cloned(),
        _ => None,
    }
}

fn checked_explore_intrinsic_schema_is_closed_leaf(canonical_name: &str) -> bool {
    matches!(
        canonical_name,
        "Int"
            | "Nat"
            | "Float"
            | "String"
            | "Char"
            | "Unit"
            | "CaseId"
            | "TransitionId"
            | "MechanismSignatureId"
            | "StructuralMechanismId"
            | "ExecutionProfileId"
    )
}

fn checked_explore_schema_node(
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
    ty: &Ty,
) -> Option<CheckedExploreSchemaNode> {
    let owner_name = checked_explore_type_owner_name(ty)?;
    let owner = resolutions.data_type_identities.get(owner_name).cloned()?;
    if let CheckedDataTypeId::Intrinsic { canonical_name } = &owner {
        let mut fields = BTreeMap::new();
        let mut has_constructor = false;
        for constructor in resolutions.constructor_identities.values() {
            if &constructor.owner != &owner {
                continue;
            }
            has_constructor = true;
            for field in constructor.fields.iter() {
                fields.insert(
                    (constructor.variant_index, field.field_index),
                    CheckedExploreDirectSchemaField {
                        segment: CheckedExploreCoverageFieldPathSegment {
                            owner: owner.clone(),
                            owner_type_name: owner_name.to_string().into_boxed_str(),
                            variant_index: constructor.variant_index,
                            field_index: field.field_index,
                            variant_name: constructor.variant.clone(),
                            field_name: field.name.clone(),
                        },
                        field_ty: checked_explore_intrinsic_schema_field_ty(
                            owner_name,
                            ty,
                            constructor.variant_index,
                            field.field_index,
                        ),
                    },
                );
            }
        }
        let fields = fields.into_values().collect::<Vec<_>>();
        let composition_unavailable = fields.iter().any(|field| field.field_ty.is_none())
            || (!has_constructor
                && !checked_explore_intrinsic_schema_is_closed_leaf(canonical_name));
        return Some(CheckedExploreSchemaNode {
            owner,
            completeness_gap: composition_unavailable
                .then_some(CheckedExploreCoverageGapReason::SchemaCompositionUnavailable),
            fields,
        });
    }
    let CheckedDataTypeId::Declared(model_owner) = &owner else {
        unreachable!("intrinsic type owner returned above")
    };
    let declaration_id = resolutions
        .data_owner_to_analysis_occurrence
        .get(model_owner)?;
    let declaration = index.type_declarations.get(declaration_id).copied()?;
    let mut direct_fields = Vec::new();
    let mut completeness_gap = None;
    match declaration {
        TypeDecl::ADT {
            variants,
            except_from,
            ..
        } => {
            let composed =
                except_from.is_some() || variants.iter().any(|variant| variant.from_type.is_some());
            for (variant_index, variant) in variants.iter().enumerate() {
                for (field_index, field) in variant.fields.iter().enumerate() {
                    direct_fields.push(CheckedExploreDirectSchemaField {
                        segment: CheckedExploreCoverageFieldPathSegment {
                            owner: owner.clone(),
                            owner_type_name: owner_name.to_string().into_boxed_str(),
                            variant_index,
                            field_index,
                            variant_name: variant.name.clone().into_boxed_str(),
                            field_name: field.name.clone().into_boxed_str(),
                        },
                        field_ty: Some(field.ty.clone()),
                    });
                }
            }
            completeness_gap =
                composed.then_some(CheckedExploreCoverageGapReason::SchemaCompositionUnavailable);
        }
        TypeDecl::WhenType { variants, .. } => {
            for (variant_index, variant) in variants.iter().enumerate() {
                for (field_index, field) in variant.fields.iter().enumerate() {
                    direct_fields.push(CheckedExploreDirectSchemaField {
                        segment: CheckedExploreCoverageFieldPathSegment {
                            owner: owner.clone(),
                            owner_type_name: owner_name.to_string().into_boxed_str(),
                            variant_index,
                            field_index,
                            variant_name: variant.name.clone().into_boxed_str(),
                            field_name: field.name.clone().into_boxed_str(),
                        },
                        field_ty: Some(field.ty.clone()),
                    });
                }
            }
            completeness_gap = Some(CheckedExploreCoverageGapReason::SchemaCompositionUnavailable);
        }
        TypeDecl::RuleScope { name, params, .. } => {
            for (field_index, field) in params.iter().enumerate() {
                direct_fields.push(CheckedExploreDirectSchemaField {
                    segment: CheckedExploreCoverageFieldPathSegment {
                        owner: owner.clone(),
                        owner_type_name: owner_name.to_string().into_boxed_str(),
                        variant_index: 0,
                        field_index,
                        variant_name: name.clone().into_boxed_str(),
                        field_name: field.name.clone().into_boxed_str(),
                    },
                    field_ty: field.ty.clone(),
                });
            }
            if direct_fields.iter().any(|field| field.field_ty.is_none()) {
                completeness_gap =
                    Some(CheckedExploreCoverageGapReason::SchemaCompositionUnavailable);
            }
        }
        _ => return None,
    }
    Some(CheckedExploreSchemaNode {
        owner,
        fields: direct_fields,
        completeness_gap,
    })
}

fn checked_explore_merge_coverage_gap(
    target: &mut Option<CheckedExploreCoverageGapReason>,
    candidate: CheckedExploreCoverageGapReason,
) {
    match target {
        Some(current) if *current <= candidate => {}
        _ => *target = Some(candidate),
    }
}

fn checked_explore_schema_type_may_hide_fields(ty: &Ty) -> bool {
    !matches!(ty, Ty::Arrow(_, _) | Ty::Unit)
}

fn checked_explore_collect_schema_fields(
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
    node: CheckedExploreSchemaNode,
    active_owners: &mut BTreeSet<CheckedDataTypeId>,
    path: &mut Vec<CheckedExploreCoverageFieldPathSegment>,
    fields: &mut Vec<CheckedExploreSchemaFieldDescriptor>,
) -> Option<CheckedExploreCoverageGapReason> {
    if !active_owners.insert(node.owner.clone()) {
        return Some(CheckedExploreCoverageGapReason::SchemaCompositionUnavailable);
    }

    let mut completeness_gap = node.completeness_gap;
    for direct_field in node.fields {
        path.push(direct_field.segment);
        let descriptor_index = fields.len();
        fields.push(CheckedExploreSchemaFieldDescriptor {
            path: path.clone().into_boxed_slice(),
            completeness_gap: None,
        });

        let descendant_gap = match direct_field.field_ty {
            Some(field_ty) => match checked_explore_schema_node(index, resolutions, &field_ty) {
                Some(child) if child.fields.is_empty() && child.completeness_gap.is_none() => None,
                Some(child) => checked_explore_collect_schema_fields(
                    index,
                    resolutions,
                    child,
                    active_owners,
                    path,
                    fields,
                ),
                None if checked_explore_schema_type_may_hide_fields(&field_ty) => {
                    Some(CheckedExploreCoverageGapReason::SchemaCompositionUnavailable)
                }
                None => None,
            },
            None => Some(CheckedExploreCoverageGapReason::SchemaCompositionUnavailable),
        };
        if let Some(reason) = descendant_gap {
            fields[descriptor_index].completeness_gap = Some(reason);
            checked_explore_merge_coverage_gap(&mut completeness_gap, reason);
        }
        path.pop();
    }
    active_owners.remove(&node.owner);
    completeness_gap
}

fn checked_explore_schema_fields(
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
    ty: &Ty,
) -> Option<CheckedExploreSchemaDescriptor> {
    let root = checked_explore_schema_node(index, resolutions, ty)?;
    let mut fields = Vec::new();
    let mut active_owners = BTreeSet::new();
    let mut path = Vec::new();
    let completeness_gap = checked_explore_collect_schema_fields(
        index,
        resolutions,
        root,
        &mut active_owners,
        &mut path,
        &mut fields,
    );
    Some(CheckedExploreSchemaDescriptor {
        fields,
        completeness_gap,
    })
}

fn checked_explore_binding_coverages(
    query: &explore::ExploreQueryIr,
    subject_ids: &[[u8; 32]],
) -> Vec<CheckedExploreBindingCoverage> {
    let mut coverages = Vec::with_capacity(query.source.bindings.len());
    for (position, binding) in query.source.bindings.iter().enumerate() {
        let coverage = match &binding.kind {
            explore::ExploreSourceBindingKindIr::Finite { .. } => {
                CheckedExploreBindingCoverage::Varied(subject_ids[position])
            }
            explore::ExploreSourceBindingKindIr::Singleton { .. } => {
                let mut dimensions = BTreeSet::new();
                let mut gap = None;
                for dependency in &binding.dependencies {
                    match coverages.get(dependency.binding_index) {
                        Some(CheckedExploreBindingCoverage::Varied(dimension_id)) => {
                            dimensions.insert(*dimension_id);
                        }
                        Some(CheckedExploreBindingCoverage::Derived(dependencies)) => {
                            dimensions.extend(dependencies.iter().copied());
                        }
                        Some(CheckedExploreBindingCoverage::Conditioned) => {}
                        Some(CheckedExploreBindingCoverage::Gap(_)) | None => {
                            gap = Some(CheckedExploreCoverageGapReason::UpstreamCoverageGap);
                        }
                    }
                }
                if let Some(reason) = gap {
                    CheckedExploreBindingCoverage::Gap(reason)
                } else if dimensions.is_empty() {
                    CheckedExploreBindingCoverage::Conditioned
                } else {
                    CheckedExploreBindingCoverage::Derived(dimensions)
                }
            }
        };
        coverages.push(coverage);
    }
    coverages
}

fn checked_explore_expression_source_classification(
    site: &ExprSiteId,
    resolutions: &CheckedResolutionArtifacts,
    source_binder_indices: &BTreeMap<CheckedBinderSiteId, usize>,
    coverages: &[CheckedExploreBindingCoverage],
) -> CheckedExploreCoverageClassification {
    let direct_source = resolutions
        .expressions
        .get(site)
        .and_then(|resolution| resolution.value_binding.as_ref())
        .and_then(|binding| match binding {
            CheckedValueBinding::Binder { site, .. } => source_binder_indices.get(site).copied(),
            _ => None,
        });
    if let Some(index) = direct_source {
        return match coverages.get(index) {
            Some(CheckedExploreBindingCoverage::Varied(dimension_id)) => {
                CheckedExploreCoverageClassification::VariedFiniteDimension {
                    dimension_id: *dimension_id,
                }
            }
            Some(coverage) => coverage.classification(),
            None => CheckedExploreCoverageClassification::CoverageGap {
                reason: CheckedExploreCoverageGapReason::UpstreamCoverageGap,
            },
        };
    }

    let referenced_sources = resolutions
        .expressions
        .subtree(site)
        .filter_map(|(_, resolution)| match &resolution.value_binding {
            Some(CheckedValueBinding::Binder { site, .. }) => {
                source_binder_indices.get(site).copied()
            }
            _ => None,
        })
        .collect::<BTreeSet<_>>();
    let mut dimensions = BTreeSet::new();
    for index in referenced_sources {
        match coverages.get(index) {
            Some(CheckedExploreBindingCoverage::Varied(dimension_id)) => {
                dimensions.insert(*dimension_id);
            }
            Some(CheckedExploreBindingCoverage::Derived(dependencies)) => {
                dimensions.extend(dependencies.iter().copied());
            }
            Some(CheckedExploreBindingCoverage::Conditioned) => {}
            Some(CheckedExploreBindingCoverage::Gap(_)) | None => {
                return CheckedExploreCoverageClassification::CoverageGap {
                    reason: CheckedExploreCoverageGapReason::UpstreamCoverageGap,
                };
            }
        }
    }
    if dimensions.is_empty() {
        CheckedExploreCoverageClassification::ConditionedSingletonOrSourceRestriction
    } else {
        CheckedExploreCoverageClassification::DerivedFromDeclaredDimensions {
            dimension_ids: dimensions
                .into_iter()
                .collect::<Vec<_>>()
                .into_boxed_slice(),
        }
    }
}

fn checked_explore_direct_source_binding_index(
    site: &ExprSiteId,
    resolutions: &CheckedResolutionArtifacts,
    source_binder_indices: &BTreeMap<CheckedBinderSiteId, usize>,
) -> Option<usize> {
    resolutions
        .expressions
        .get(site)
        .and_then(|resolution| resolution.value_binding.as_ref())
        .and_then(|binding| match binding {
            CheckedValueBinding::Binder { site, .. } => source_binder_indices.get(site).copied(),
            _ => None,
        })
}

fn checked_explore_source_binding_field_path_classification(
    query: &explore::ExploreQueryIr,
    sites: &CheckedExploreQuerySites,
    resolutions: &CheckedResolutionArtifacts,
    source_binder_indices: &BTreeMap<CheckedBinderSiteId, usize>,
    coverages: &[CheckedExploreBindingCoverage],
    source_binding_index: usize,
    path: &[CheckedExploreCoverageFieldPathSegment],
    active_bindings: &mut BTreeSet<usize>,
) -> CheckedExploreCoverageClassification {
    if !active_bindings.insert(source_binding_index) {
        return CheckedExploreCoverageClassification::CoverageGap {
            reason: CheckedExploreCoverageGapReason::UpstreamCoverageGap,
        };
    }
    let Some(binding) = query.source.bindings.get(source_binding_index) else {
        active_bindings.remove(&source_binding_index);
        return CheckedExploreCoverageClassification::CoverageGap {
            reason: CheckedExploreCoverageGapReason::UpstreamCoverageGap,
        };
    };
    let classification = match &binding.kind {
        explore::ExploreSourceBindingKindIr::Finite { .. } => coverages
            .get(source_binding_index)
            .map(CheckedExploreBindingCoverage::projected_classification)
            .unwrap_or(CheckedExploreCoverageClassification::CoverageGap {
                reason: CheckedExploreCoverageGapReason::UpstreamCoverageGap,
            }),
        explore::ExploreSourceBindingKindIr::Singleton { value } => {
            match sites.source_bindings.get(source_binding_index) {
                Some(binding_sites) => checked_explore_expression_field_path_classification(
                    query,
                    sites,
                    resolutions,
                    source_binder_indices,
                    coverages,
                    value,
                    &binding_sites.expression,
                    path,
                    active_bindings,
                ),
                None => CheckedExploreCoverageClassification::CoverageGap {
                    reason: CheckedExploreCoverageGapReason::UpstreamCoverageGap,
                },
            }
        }
    };
    active_bindings.remove(&source_binding_index);
    classification
}

fn checked_explore_expression_field_path_classification(
    query: &explore::ExploreQueryIr,
    sites: &CheckedExploreQuerySites,
    resolutions: &CheckedResolutionArtifacts,
    source_binder_indices: &BTreeMap<CheckedBinderSiteId, usize>,
    coverages: &[CheckedExploreBindingCoverage],
    expression: &Expr,
    site: &ExprSiteId,
    path: &[CheckedExploreCoverageFieldPathSegment],
    active_bindings: &mut BTreeSet<usize>,
) -> CheckedExploreCoverageClassification {
    if path.is_empty() {
        return checked_explore_expression_source_classification(
            site,
            resolutions,
            source_binder_indices,
            coverages,
        );
    }
    if let Some(binding_index) =
        checked_explore_direct_source_binding_index(site, resolutions, source_binder_indices)
    {
        return checked_explore_source_binding_field_path_classification(
            query,
            sites,
            resolutions,
            source_binder_indices,
            coverages,
            binding_index,
            path,
            active_bindings,
        );
    }

    let Some(resolution) = resolutions.expressions.get(site) else {
        return CheckedExploreCoverageClassification::CoverageGap {
            reason: CheckedExploreCoverageGapReason::ConstructorFieldMappingUnavailable,
        };
    };
    let field = &path[0];
    match &expression.kind {
        ExprKind::App(_, arguments) => {
            let Some(constructor) = &resolution.exact_constructor else {
                return CheckedExploreCoverageClassification::CoverageGap {
                    reason: CheckedExploreCoverageGapReason::InterproceduralFieldProvenance,
                };
            };
            if constructor.owner != field.owner {
                return CheckedExploreCoverageClassification::CoverageGap {
                    reason: CheckedExploreCoverageGapReason::ConstructorFieldMappingUnavailable,
                };
            }
            if constructor.variant_index != field.variant_index {
                return CheckedExploreCoverageClassification::ConditionedSingletonOrSourceRestriction;
            }
            let source_index = match &resolution.named_arguments {
                Some(order) => order
                    .canonical_source_indices
                    .get(field.field_index)
                    .copied(),
                None => Some(field.field_index),
            };
            let Some(source_index) = source_index else {
                return CheckedExploreCoverageClassification::CoverageGap {
                    reason: CheckedExploreCoverageGapReason::ConstructorFieldMappingUnavailable,
                };
            };
            let Some(argument) = arguments.get(source_index) else {
                return CheckedExploreCoverageClassification::CoverageGap {
                    reason: CheckedExploreCoverageGapReason::ConstructorFieldMappingUnavailable,
                };
            };
            let (argument, argument_site) = if resolution.named_arguments.is_some() {
                let Some((_, argument)) = named_arg_parts(argument) else {
                    return CheckedExploreCoverageClassification::CoverageGap {
                        reason: CheckedExploreCoverageGapReason::ConstructorFieldMappingUnavailable,
                    };
                };
                let argument_site =
                    CheckedExploreSemanticClosure::child_site(site, source_index + 1);
                (
                    argument,
                    CheckedExploreSemanticClosure::child_site(&argument_site, 2),
                )
            } else {
                (
                    argument,
                    CheckedExploreSemanticClosure::child_site(site, source_index + 1),
                )
            };
            checked_explore_expression_field_path_classification(
                query,
                sites,
                resolutions,
                source_binder_indices,
                coverages,
                argument,
                &argument_site,
                &path[1..],
                active_bindings,
            )
        }
        ExprKind::Var(_) if resolution.exact_constructor.is_some() => {
            let constructor = resolution
                .exact_constructor
                .as_ref()
                .expect("checked above");
            if constructor.owner == field.owner && constructor.variant_index != field.variant_index
            {
                CheckedExploreCoverageClassification::ConditionedSingletonOrSourceRestriction
            } else {
                CheckedExploreCoverageClassification::CoverageGap {
                    reason: CheckedExploreCoverageGapReason::ConstructorFieldMappingUnavailable,
                }
            }
        }
        _ => CheckedExploreCoverageClassification::CoverageGap {
            reason: CheckedExploreCoverageGapReason::InterproceduralFieldProvenance,
        },
    }
}

fn checked_explore_schema_field_classification(
    query: &explore::ExploreQueryIr,
    sites: &CheckedExploreQuerySites,
    resolutions: &CheckedResolutionArtifacts,
    source_binder_indices: &BTreeMap<CheckedBinderSiteId, usize>,
    coverages: &[CheckedExploreBindingCoverage],
    source_binding_index: usize,
    field: &CheckedExploreSchemaFieldDescriptor,
) -> CheckedExploreCoverageClassification {
    if let Some(reason) = field.completeness_gap {
        return CheckedExploreCoverageClassification::CoverageGap { reason };
    }
    checked_explore_source_binding_field_path_classification(
        query,
        sites,
        resolutions,
        source_binder_indices,
        coverages,
        source_binding_index,
        &field.path,
        &mut BTreeSet::new(),
    )
}

fn checked_explore_top_level_constant_subject_id(
    relation_id: explore::RelationId,
    dependency_digest: [u8; 32],
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-coverage-subject.v2\0");
    hasher.update(relation_id.bytes());
    checked_query_hash_component(&mut hasher, "subject-kind", "top-level-constant");
    hasher.update(dependency_digest);
    hasher.finalize().into()
}

fn checked_explore_constructor_subject_id(
    relation_id: explore::RelationId,
    owner_digest: [u8; 32],
    variant_index: usize,
    layout: CheckedConstructorLayout,
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-coverage-subject.v2\0");
    hasher.update(relation_id.bytes());
    checked_query_hash_component(&mut hasher, "subject-kind", "constructor-choice");
    hasher.update(owner_digest);
    checked_query_hash_component(
        &mut hasher,
        "constructor-variant-index",
        &variant_index.to_string(),
    );
    checked_query_hash_component(
        &mut hasher,
        "constructor-layout",
        match layout {
            CheckedConstructorLayout::Positional => "positional",
            CheckedConstructorLayout::Named => "named",
        },
    );
    hasher.finalize().into()
}

fn checked_explore_coverage_subject_identity(
    relation_id: explore::RelationId,
    subject: &CheckedExploreCoverageSubject,
) -> Option<[u8; 32]> {
    match subject {
        CheckedExploreCoverageSubject::SourceBinding {
            binding_index,
            role,
            ..
        } => Some(checked_explore_source_binding_subject_id_from_parts(
            relation_id,
            *role,
            *binding_index,
        )),
        CheckedExploreCoverageSubject::SchemaRoot { role, type_name } if !type_name.is_empty() => {
            Some(checked_explore_schema_root_subject_id(relation_id, *role))
        }
        CheckedExploreCoverageSubject::SchemaRoot { .. } => None,
        CheckedExploreCoverageSubject::SchemaField { role, path }
            if !path.is_empty()
                && path.iter().all(|segment| {
                    !segment.owner_type_name.is_empty()
                        && !segment.variant_name.is_empty()
                        && !segment.field_name.is_empty()
                }) =>
        {
            Some(checked_explore_schema_field_subject_id(
                relation_id,
                *role,
                path,
            ))
        }
        CheckedExploreCoverageSubject::SchemaField { .. } => None,
        CheckedExploreCoverageSubject::Literal { kind, value } => Some(
            checked_explore_literal_subject_id_from_parts(relation_id, *kind, value),
        ),
        CheckedExploreCoverageSubject::TopLevelConstant {
            dependency_digest,
            addresses,
        } if !addresses.is_empty()
            && !addresses.iter().any(|address| address.is_empty())
            && !addresses.windows(2).any(|pair| pair[0] >= pair[1]) =>
        {
            Some(checked_explore_top_level_constant_subject_id(
                relation_id,
                *dependency_digest,
            ))
        }
        CheckedExploreCoverageSubject::TopLevelConstant { .. } => None,
        CheckedExploreCoverageSubject::ConstructorChoice {
            owner_digest,
            owner_name,
            variant_name,
            variant_index,
            layout,
        } if !owner_name.is_empty() && !variant_name.is_empty() => {
            Some(checked_explore_constructor_subject_id(
                relation_id,
                *owner_digest,
                *variant_index,
                *layout,
            ))
        }
        CheckedExploreCoverageSubject::ConstructorChoice { .. } => None,
    }
}

fn checked_explore_insert_coverage_entry(
    entries: &mut BTreeMap<[u8; 32], CheckedExploreCoverageEntry>,
    entry: CheckedExploreCoverageEntry,
) {
    match entries.entry(entry.subject_id) {
        std::collections::btree_map::Entry::Vacant(slot) => {
            slot.insert(entry);
        }
        std::collections::btree_map::Entry::Occupied(mut slot) => {
            if slot.get().classification != entry.classification {
                slot.get_mut().classification = CheckedExploreCoverageClassification::CoverageGap {
                    reason: CheckedExploreCoverageGapReason::UpstreamCoverageGap,
                };
            }
        }
    }
}

fn checked_explore_source_coverage_manifest(
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
    semantic_binders: &BTreeMap<CheckedBinderSiteId, Box<str>>,
    query: &explore::ExploreQueryIr,
    sites: &CheckedExploreQuerySites,
    relation_id: explore::RelationId,
    source_seal: &CheckedExploreSemanticSeal,
) -> Result<CheckedExploreSourceCoverageManifest, CheckedExploreQueryArtifactIssue> {
    if query.source.bindings.len() != sites.source_bindings.len() {
        return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
            "source coverage binding/site count mismatch".into(),
        ));
    }
    let source_subject_ids = query
        .source
        .bindings
        .iter()
        .map(|binding| checked_explore_source_binding_subject_id(relation_id, binding))
        .collect::<Vec<_>>();
    let binding_coverages = checked_explore_binding_coverages(query, &source_subject_ids);
    let source_binder_indices = query
        .source
        .bindings
        .iter()
        .zip(sites.source_bindings.iter())
        .map(|(binding, sites)| (sites.binder.clone(), binding.binding_index))
        .collect::<BTreeMap<_, _>>();
    let mut entries = BTreeMap::<[u8; 32], CheckedExploreCoverageEntry>::new();

    for ((binding, subject_id), coverage) in query
        .source
        .bindings
        .iter()
        .zip(source_subject_ids.iter())
        .zip(binding_coverages.iter())
    {
        checked_explore_insert_coverage_entry(
            &mut entries,
            CheckedExploreCoverageEntry {
                subject_id: *subject_id,
                subject: CheckedExploreCoverageSubject::SourceBinding {
                    binding_index: binding.binding_index,
                    binding_name: binding.name.clone().into_boxed_str(),
                    role: checked_explore_coverage_role(binding.role),
                },
                classification: coverage.classification(),
            },
        );
    }

    for (role, source_binding_index, ty) in [
        (
            CheckedExploreCoverageRootRole::Context,
            query.source.context_binding_index,
            &query.source.context_ty,
        ),
        (
            CheckedExploreCoverageRootRole::Before,
            query.source.before_binding_index,
            &query.source.before_ty,
        ),
    ] {
        let root_subject_id = checked_explore_schema_root_subject_id(relation_id, role);
        let schema = checked_explore_schema_fields(index, resolutions, ty);
        let root_classification = match &schema {
            Some(schema) if schema.completeness_gap.is_none() => binding_coverages
                .get(source_binding_index)
                .map(CheckedExploreBindingCoverage::classification)
                .unwrap_or(CheckedExploreCoverageClassification::CoverageGap {
                    reason: CheckedExploreCoverageGapReason::UpstreamCoverageGap,
                }),
            Some(schema) => CheckedExploreCoverageClassification::CoverageGap {
                reason: schema
                    .completeness_gap
                    .expect("guarded incomplete schema descriptor"),
            },
            None => CheckedExploreCoverageClassification::CoverageGap {
                reason: CheckedExploreCoverageGapReason::SchemaNotDeclaredRecord,
            },
        };
        checked_explore_insert_coverage_entry(
            &mut entries,
            CheckedExploreCoverageEntry {
                subject_id: root_subject_id,
                subject: CheckedExploreCoverageSubject::SchemaRoot {
                    role,
                    type_name: ty.to_string().into_boxed_str(),
                },
                classification: root_classification,
            },
        );
        let Some(schema) = schema else {
            continue;
        };
        for field in schema.fields {
            let subject_id =
                checked_explore_schema_field_subject_id(relation_id, role, &field.path);
            let classification = checked_explore_schema_field_classification(
                query,
                sites,
                resolutions,
                &source_binder_indices,
                &binding_coverages,
                source_binding_index,
                &field,
            );
            checked_explore_insert_coverage_entry(
                &mut entries,
                CheckedExploreCoverageEntry {
                    subject_id,
                    subject: CheckedExploreCoverageSubject::SchemaField {
                        role,
                        path: field.path,
                    },
                    classification,
                },
            );
        }
    }

    for literal in &source_seal.producer_inputs.literals {
        let subject_id = checked_explore_literal_subject_id(relation_id, literal);
        checked_explore_insert_coverage_entry(
            &mut entries,
            CheckedExploreCoverageEntry {
                subject_id,
                subject: CheckedExploreCoverageSubject::Literal {
                    kind: literal.kind,
                    value: literal.value.clone(),
                },
                classification:
                    CheckedExploreCoverageClassification::ConditionedSingletonOrSourceRestriction,
            },
        );
    }

    let mut top_level_inputs = BTreeMap::<[u8; 32], ([u8; 32], BTreeSet<Box<str>>)>::new();
    for binding in &source_seal.producer_inputs.top_level_constants {
        let dependency_digest = checked_explore_semantic_dependency_root_digest(
            index,
            resolutions,
            semantic_binders,
            CheckedExploreSemanticDependency::TopLevel(binding.clone()),
        )?;
        let subject_id =
            checked_explore_top_level_constant_subject_id(relation_id, dependency_digest);
        let address = index
            .top_level_binding_names
            .get(binding)
            .cloned()
            .unwrap_or_else(|| "<resolved constant>".into());
        let (canonical_dependency_digest, addresses) = top_level_inputs
            .entry(subject_id)
            .or_insert_with(|| (dependency_digest, BTreeSet::new()));
        if *canonical_dependency_digest != dependency_digest {
            return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
                "source coverage constant subject collision".into(),
            ));
        }
        addresses.insert(address);
    }
    for (subject_id, (dependency_digest, addresses)) in top_level_inputs {
        checked_explore_insert_coverage_entry(
            &mut entries,
            CheckedExploreCoverageEntry {
                subject_id,
                subject: CheckedExploreCoverageSubject::TopLevelConstant {
                    dependency_digest,
                    addresses: addresses.into_iter().collect::<Vec<_>>().into_boxed_slice(),
                },
                classification:
                    CheckedExploreCoverageClassification::ConditionedSingletonOrSourceRestriction,
            },
        );
    }

    for (constructor, provenance) in &source_seal.producer_inputs.constructor_choices {
        let owner_digest = match &constructor.owner {
            CheckedDataTypeId::Intrinsic { canonical_name } => {
                let mut hasher = Sha256::new();
                hasher.update(b"futuruna.checked-explore-intrinsic-type.v1\0");
                checked_query_hash_component(&mut hasher, "intrinsic-type", canonical_name);
                hasher.finalize().into()
            }
            owner @ CheckedDataTypeId::Declared(_) => {
                checked_explore_semantic_dependency_root_digest(
                    index,
                    resolutions,
                    semantic_binders,
                    CheckedExploreSemanticDependency::DeclaredType(owner.clone()),
                )?
            }
        };
        let subject_id = checked_explore_constructor_subject_id(
            relation_id,
            owner_digest,
            constructor.variant_index,
            constructor.layout,
        );
        checked_explore_insert_coverage_entry(
            &mut entries,
            CheckedExploreCoverageEntry {
                subject_id,
                subject: CheckedExploreCoverageSubject::ConstructorChoice {
                    owner_digest,
                    owner_name: constructor.owner_type.clone(),
                    variant_name: constructor.variant.clone(),
                    variant_index: constructor.variant_index,
                    layout: constructor.layout,
                },
                classification: match provenance {
                    CheckedExploreConstructorChoiceProvenance::ConditionedFromSourceSingleton => {
                        CheckedExploreCoverageClassification::ConditionedSingletonOrSourceRestriction
                    }
                    CheckedExploreConstructorChoiceProvenance::Unproven => {
                        CheckedExploreCoverageClassification::CoverageGap {
                            reason: CheckedExploreCoverageGapReason::ConstructorChoiceProvenanceUnavailable,
                        }
                    }
                },
            },
        );
    }

    let entries = entries.into_values().collect::<Vec<_>>();
    let manifest_digest = checked_explore_source_coverage_manifest_digest(
        CHECKED_EXPLORE_SOURCE_COVERAGE_VERSION,
        relation_id,
        source_seal.digest,
        &entries,
    );
    let manifest = CheckedExploreSourceCoverageManifest {
        version: CHECKED_EXPLORE_SOURCE_COVERAGE_VERSION,
        relation_id,
        semantic_dependency_digest: source_seal.digest,
        entries: entries.into_boxed_slice(),
        manifest_digest,
    };
    if !manifest.validate_identity() {
        return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
            "source coverage manifest invariants are not canonical".into(),
        ));
    }
    Ok(manifest)
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CheckedExploreSourceProjectionTerm {
    Affine(CheckedExploreSourceProjectionAffine),
    Constructor {
        constructor_digest: [u8; 32],
        fields: Box<
            [(
                CheckedExploreSourceProjectionField,
                CheckedExploreSourceProjectionTerm,
            )],
        >,
    },
    Ground {
        digest: [u8; 32],
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CheckedExploreSourceProjectionAffine {
    coefficients: BTreeMap<u32, i64>,
    offset: i64,
    minimum: i64,
    maximum: i64,
    proof_digest: [u8; 32],
}

struct CheckedExploreSourceProjectionAnalysis {
    certificate: CheckedExploreSourceImageProjectionCertificate,
    /// Normalized terms in source-binding order. These are retained only long
    /// enough to derive optional result-local execution theorems; they never
    /// enter or replace the existing source-image certificate bytes.
    terms: Box<[CheckedExploreSourceProjectionTerm]>,
}

fn checked_explore_source_image_projection_analysis(
    resolutions: &CheckedResolutionArtifacts,
    query: &explore::ExploreQueryIr,
    sites: &CheckedExploreQuerySites,
    relation_id: explore::RelationId,
    semantic_dependency_digest: [u8; 32],
) -> Result<Option<CheckedExploreSourceProjectionAnalysis>, CheckedExploreQueryArtifactIssue> {
    if query.source.bindings.len() != sites.source_bindings.len() {
        return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
            "source projection binding/site count mismatch".into(),
        ));
    }
    // Preserve the established direct-endpoint proof path. This certificate
    // is needed only when a varying Auxiliary
    // coordinate would otherwise be erased by SourceRow construction.
    if !query.source.bindings.iter().any(|binding| {
        binding.role == explore::ExploreSourceBindingRoleIr::Auxiliary
            && matches!(
                &binding.kind,
                explore::ExploreSourceBindingKindIr::Finite { .. }
            )
    }) {
        return Ok(None);
    }

    let binder_indices = query
        .source
        .bindings
        .iter()
        .zip(sites.source_bindings.iter())
        .map(|(binding, site)| (site.binder.clone(), binding.binding_index))
        .collect::<BTreeMap<_, _>>();
    let mut factors = Vec::new();
    let mut factor_bounds = BTreeMap::<u32, (i64, i64)>::new();
    let mut terms =
        Vec::<CheckedExploreSourceProjectionTerm>::with_capacity(query.source.bindings.len());

    for (binding, checked_site) in query
        .source
        .bindings
        .iter()
        .zip(sites.source_bindings.iter())
    {
        let binding_index = u32::try_from(binding.binding_index).ok();
        let Some(binding_index) = binding_index else {
            return Ok(None);
        };
        let term = match &binding.kind {
            explore::ExploreSourceBindingKindIr::Finite { domain }
                if binding.dependencies.is_empty() =>
            {
                let Some((start, end_exclusive)) =
                    checked_explore_projection_static_int_range(domain)
                else {
                    return Ok(None);
                };
                if start >= end_exclusive {
                    return Ok(None);
                }
                let exact_cardinality =
                    u128::try_from(i128::from(end_exclusive) - i128::from(start)).ok();
                let Some(exact_cardinality) = exact_cardinality else {
                    return Ok(None);
                };
                let maximum = end_exclusive.checked_sub(1);
                let Some(maximum) = maximum else {
                    return Ok(None);
                };
                let binder_digest = checked_explore_projection_binder_digest(&checked_site.binder);
                factors.push(CheckedExploreSourceProjectionFactor {
                    binding_index,
                    binder_digest,
                    start,
                    end_exclusive,
                    exact_cardinality,
                });
                factor_bounds.insert(binding_index, (start, maximum));
                let mut coefficients = BTreeMap::new();
                coefficients.insert(binding_index, 1);
                CheckedExploreSourceProjectionTerm::Affine(CheckedExploreSourceProjectionAffine {
                    coefficients,
                    offset: 0,
                    minimum: start,
                    maximum,
                    proof_digest: checked_explore_projection_affine_leaf_digest(
                        0x02,
                        binding_index,
                        start,
                        maximum,
                    ),
                })
            }
            explore::ExploreSourceBindingKindIr::Finite { .. } => return Ok(None),
            explore::ExploreSourceBindingKindIr::Singleton { value } => {
                let Some(term) = checked_explore_projection_term(
                    value,
                    &checked_site.expression,
                    resolutions,
                    &binder_indices,
                    &terms,
                    &factor_bounds,
                ) else {
                    return Ok(None);
                };
                term
            }
        };
        terms.push(term);
    }

    if factors.is_empty() {
        return Ok(None);
    }
    if factors.iter().enumerate().any(|(position, factor)| {
        position > 0 && factors[position - 1].binding_index >= factor.binding_index
    }) {
        return Ok(None);
    }

    let Some(context) = terms.get(query.source.context_binding_index) else {
        return Ok(None);
    };
    let Some(before) = terms.get(query.source.before_binding_index) else {
        return Ok(None);
    };
    let mut candidates = BTreeMap::<
        u32,
        Vec<(
            CheckedExploreSourceProjectionEndpoint,
            Box<[CheckedExploreSourceProjectionField]>,
            CheckedExploreSourceProjectionAffine,
        )>,
    >::new();
    checked_explore_projection_candidates(
        context,
        CheckedExploreSourceProjectionEndpoint::Context,
        &mut Vec::new(),
        &mut candidates,
    );
    checked_explore_projection_candidates(
        before,
        CheckedExploreSourceProjectionEndpoint::Before,
        &mut Vec::new(),
        &mut candidates,
    );

    let mut witnesses = Vec::with_capacity(factors.len());
    for factor in &factors {
        let Some(factor_candidates) = candidates.get_mut(&factor.binding_index) else {
            return Ok(None);
        };
        factor_candidates
            .sort_by(|left, right| (left.0, left.1.as_ref()).cmp(&(right.0, right.1.as_ref())));
        let Some((endpoint, path, affine)) = factor_candidates.first().cloned() else {
            return Ok(None);
        };
        let Some(coefficient) = affine.coefficients.get(&factor.binding_index).copied() else {
            return Ok(None);
        };
        if coefficient == 0 || affine.coefficients.len() != 1 {
            return Ok(None);
        }
        let Some(maximum_input) = factor.end_exclusive.checked_sub(1) else {
            return Ok(None);
        };
        let Some(first_output) = factor
            .start
            .checked_mul(coefficient)
            .and_then(|value| value.checked_add(affine.offset))
        else {
            return Ok(None);
        };
        let Some(last_output) = maximum_input
            .checked_mul(coefficient)
            .and_then(|value| value.checked_add(affine.offset))
        else {
            return Ok(None);
        };
        let output_min = first_output.min(last_output);
        let output_max = first_output.max(last_output);
        let witness_id = checked_explore_projection_witness_id(
            relation_id,
            factor,
            endpoint,
            &path,
            coefficient,
            affine.offset,
            output_min,
            output_max,
            affine.proof_digest,
        );
        witnesses.push(CheckedExploreSourceProjectionWitness {
            factor_binding_index: factor.binding_index,
            endpoint,
            path,
            coefficient,
            offset: affine.offset,
            output_min,
            output_max,
            affine_proof_digest: affine.proof_digest,
            witness_id,
        });
    }

    let mut construction_hasher = Sha256::new();
    construction_hasher.update(b"futuruna.checked-explore-source-total-construction.v1\0");
    construction_hasher.update(relation_id.bytes());
    construction_hasher.update(semantic_dependency_digest);
    for (binding, term) in query.source.bindings.iter().zip(terms.iter()) {
        checked_query_hash_component(
            &mut construction_hasher,
            "binding-index",
            &binding.binding_index.to_string(),
        );
        checked_explore_projection_hash_term(&mut construction_hasher, term);
    }
    let total_construction_digest = construction_hasher.finalize().into();

    let certificate_id = checked_explore_projection_certificate_id(
        CHECKED_EXPLORE_SOURCE_IMAGE_PROJECTION_VERSION,
        relation_id,
        semantic_dependency_digest,
        total_construction_digest,
        &factors,
        &witnesses,
    );
    let certificate = CheckedExploreSourceImageProjectionCertificate {
        version: CHECKED_EXPLORE_SOURCE_IMAGE_PROJECTION_VERSION,
        relation_id,
        semantic_dependency_digest,
        total_construction_digest,
        factors: factors.into_boxed_slice(),
        witnesses: witnesses.into_boxed_slice(),
        certificate_id,
    };
    if !certificate.validate_identity() {
        return Ok(None);
    }
    Ok(Some(CheckedExploreSourceProjectionAnalysis {
        certificate,
        terms: terms.into_boxed_slice(),
    }))
}

fn checked_explore_product_rank_grouped_distinct_certificates(
    resolutions: &CheckedResolutionArtifacts,
    query: &explore::ExploreQueryIr,
    sites: &CheckedExploreQuerySites,
    identities: &[CheckedExploreAnalysisIdentity],
    source: Option<&CheckedExploreSourceProjectionAnalysis>,
) -> Result<
    Box<[CheckedExploreProductRankGroupedDistinctCertificate]>,
    CheckedExploreQueryArtifactIssue,
> {
    if query.analysis.len() != sites.analysis.len()
        || query.analysis.len() != identities.len()
        || query.source.bindings.len() != sites.source_bindings.len()
    {
        return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
            "grouped-distinct projection inputs disagree with checked query shape".into(),
        ));
    }
    let Some(source) = source else {
        return Ok(Box::new([]));
    };
    if source.terms.len() != query.source.bindings.len() || !source.certificate.validate_identity()
    {
        return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
            "grouped-distinct projection source proof is internally inconsistent".into(),
        ));
    }

    let binder_indices = query
        .source
        .bindings
        .iter()
        .zip(sites.source_bindings.iter())
        .map(|(binding, site)| (site.binder.clone(), binding.binding_index))
        .collect::<BTreeMap<_, _>>();
    let mut certificates =
        BTreeMap::<explore::ViewId, CheckedExploreProductRankGroupedDistinctCertificate>::new();
    for ((node, node_sites), identity) in query
        .analysis
        .iter()
        .zip(sites.analysis.iter())
        .zip(identities.iter())
    {
        let (
            explore::ExploreAnalysisNodeIr::Result(view),
            CheckedExploreAnalysisNodeSites::Result(result_sites),
            CheckedExploreAnalysisIdentity::View { view_id },
        ) = (node, node_sites, identity)
        else {
            continue;
        };
        let Some(certificate) = checked_explore_product_rank_grouped_distinct_certificate(
            resolutions,
            query,
            view,
            result_sites,
            *view_id,
            &binder_indices,
            source,
        ) else {
            continue;
        };
        match certificates.entry(*view_id) {
            std::collections::btree_map::Entry::Vacant(entry) => {
                entry.insert(certificate);
            }
            std::collections::btree_map::Entry::Occupied(entry) if entry.get() == &certificate => {}
            std::collections::btree_map::Entry::Occupied(_) => {
                return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
                    "one semantic view identity derived conflicting grouped-distinct proofs".into(),
                ));
            }
        }
    }
    Ok(certificates
        .into_values()
        .collect::<Vec<_>>()
        .into_boxed_slice())
}

#[allow(clippy::too_many_arguments)]
fn checked_explore_product_rank_grouped_distinct_certificate(
    resolutions: &CheckedResolutionArtifacts,
    query: &explore::ExploreQueryIr,
    view: &explore::ExploreResultViewIr,
    sites: &CheckedExploreResultSites,
    view_id: explore::ViewId,
    binder_indices: &BTreeMap<CheckedBinderSiteId, usize>,
    source: &CheckedExploreSourceProjectionAnalysis,
) -> Option<CheckedExploreProductRankGroupedDistinctCertificate> {
    if !matches!(&view.input, explore::ExploreResultInputIr::Sources)
        || !view.measures.is_empty()
        || view.having.is_some()
        || view.choose.is_some()
        || view.aggregates.len() != 1
        || sites.measures.len() != view.measures.len()
        || sites.aggregates.len() != view.aggregates.len()
        || sites.select.len() != view.select.len()
        || !sites.choice_objectives.is_empty()
    {
        return None;
    }
    let explore::ExploreResultGrainIr::GroupBy { fields, .. } = &view.grain else {
        return None;
    };
    if fields.is_empty() || fields.len() != sites.group_fields.len() {
        return None;
    }
    let aggregate = view.aggregates.first()?;
    let explore::ExploreAggregateReducerIr::CountDistinct { value, .. } = &aggregate.reducer;

    // The compact executor may only publish aliases of the already closed
    // group/aggregate row. Any SELECT computation would need ordinary row
    // evaluation and therefore cannot consume this theorem.
    let mut closed_aliases = BTreeSet::<&str>::new();
    for alias in fields
        .iter()
        .map(|field| field.name.as_str())
        .chain(std::iter::once(aggregate.name.as_str()))
    {
        if matches!(alias, "before" | "context") || !closed_aliases.insert(alias) {
            return None;
        }
    }
    let mut selected_aliases = BTreeSet::new();
    for field in view.select.iter() {
        if matches!(field.name.as_str(), "before" | "context") {
            return None;
        }
        let ExprKind::Var(reference) = &field.value.kind else {
            return None;
        };
        if !selected_aliases.insert(field.name.as_str())
            || !closed_aliases.contains(reference.as_str())
            || (closed_aliases.contains(field.name.as_str())
                && field.name.as_str() != reference.as_str())
        {
            return None;
        }
        closed_aliases.insert(field.name.as_str());
    }

    let mut group_terms = Vec::with_capacity(fields.len());
    for (field, site) in fields.iter().zip(sites.group_fields.iter()) {
        group_terms.push(checked_explore_direct_source_projection_term(
            &field.value,
            site,
            resolutions,
            binder_indices,
            &source.terms,
            query.source.context_binding_index,
            query.source.before_binding_index,
        )?);
    }
    let distinct_term = checked_explore_direct_source_projection_term(
        value,
        sites.aggregates.first()?,
        resolutions,
        binder_indices,
        &source.terms,
        query.source.context_binding_index,
        query.source.before_binding_index,
    )?;

    let factors = source.certificate.factors.as_ref();
    if factors.len() < 2 {
        return None;
    }
    let factor_count = u32::try_from(factors.len()).ok()?;
    let factor_bindings = factors
        .iter()
        .map(|factor| factor.binding_index)
        .collect::<Vec<_>>();
    let mut group_dependencies = BTreeSet::new();
    let mut group_separators = BTreeSet::new();
    for term in &group_terms {
        checked_explore_projection_term_dependencies(term, &mut group_dependencies);
        checked_explore_projection_term_separators(term, &mut group_separators);
    }
    let mut distinct_dependencies = BTreeSet::new();
    let mut distinct_separators = BTreeSet::new();
    checked_explore_projection_term_dependencies(&distinct_term, &mut distinct_dependencies);
    checked_explore_projection_term_separators(&distinct_term, &mut distinct_separators);

    let split = (1..factors.len()).find(|split| {
        let prefix = factor_bindings[..*split]
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        let suffix = factor_bindings[*split..]
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        group_dependencies == prefix
            && distinct_dependencies == suffix
            && prefix.is_subset(&group_separators)
            && suffix.is_subset(&distinct_separators)
    })?;
    let group_factor_count = u32::try_from(split).ok()?;
    let exact_group_count = checked_explore_projection_factor_cardinality(&factors[..split])?;
    let exact_members_per_group = checked_explore_projection_factor_cardinality(&factors[split..])?;
    if exact_members_per_group > i64::MAX as u128 {
        return None;
    }

    let mut certificate = CheckedExploreProductRankGroupedDistinctCertificate {
        version: CHECKED_EXPLORE_PRODUCT_RANK_GROUPED_DISTINCT_VERSION,
        relation_id: source.certificate.relation_id,
        view_id,
        source_projection_certificate_id: source.certificate.certificate_id,
        source_factor_root: checked_explore_product_rank_factor_root(factors),
        factor_count,
        group_factor_count,
        exact_group_count,
        exact_members_per_group,
        group_projection_digest: checked_explore_product_rank_projection_digest(0x01, &group_terms),
        distinct_projection_digest: checked_explore_product_rank_projection_digest(
            0x02,
            std::slice::from_ref(&distinct_term),
        ),
        certificate_id: [0; 32],
    };
    certificate.certificate_id =
        checked_explore_product_rank_grouped_distinct_certificate_id(&certificate);
    (certificate.validate_identity()
        && certificate.validates_source_projection(&source.certificate))
    .then_some(certificate)
}

fn checked_explore_direct_source_projection_term(
    expression: &Expr,
    site: &ExprSiteId,
    resolutions: &CheckedResolutionArtifacts,
    binder_indices: &BTreeMap<CheckedBinderSiteId, usize>,
    source_terms: &[CheckedExploreSourceProjectionTerm],
    context_binding_index: usize,
    before_binding_index: usize,
) -> Option<CheckedExploreSourceProjectionTerm> {
    let resolution = resolutions.expressions.get(site)?;
    match &expression.kind {
        ExprKind::Var(_) => {
            let CheckedValueBinding::Binder {
                kind: CheckedBinderKind::ExploreValue,
                site: binder,
            } = resolution.value_binding.as_ref()?
            else {
                return None;
            };
            let binding_index = *binder_indices.get(binder)?;
            if binding_index != context_binding_index && binding_index != before_binding_index {
                return None;
            }
            source_terms.get(binding_index).cloned()
        }
        ExprKind::Field(base, member) => {
            let base_site = CheckedExploreSemanticClosure::child_site(site, 0);
            let base = checked_explore_direct_source_projection_term(
                base,
                &base_site,
                resolutions,
                binder_indices,
                source_terms,
                context_binding_index,
                before_binding_index,
            )?;
            let CheckedExploreSourceProjectionTerm::Constructor { fields, .. } = base else {
                return None;
            };
            let CheckedFieldResolution::Data {
                fields: resolved_fields,
                ..
            } = resolution.field.as_ref()?
            else {
                return None;
            };
            let mut selected = None;
            for resolved in resolved_fields.iter() {
                if resolved.identity.name.as_ref() != member.as_str() {
                    continue;
                }
                let projected = checked_explore_projection_field(&resolved.identity)?;
                for (field, value) in fields.iter() {
                    if *field == projected {
                        if selected.is_some() {
                            return None;
                        }
                        selected = Some(value.clone());
                    }
                }
            }
            selected
        }
        _ => None,
    }
}

fn checked_explore_projection_term_dependencies(
    term: &CheckedExploreSourceProjectionTerm,
    dependencies: &mut BTreeSet<u32>,
) {
    match term {
        CheckedExploreSourceProjectionTerm::Affine(affine) => {
            dependencies.extend(
                affine
                    .coefficients
                    .iter()
                    .filter_map(|(binding, coefficient)| (*coefficient != 0).then_some(*binding)),
            );
        }
        CheckedExploreSourceProjectionTerm::Constructor { fields, .. } => {
            for (_, child) in fields.iter() {
                checked_explore_projection_term_dependencies(child, dependencies);
            }
        }
        CheckedExploreSourceProjectionTerm::Ground { .. } => {}
    }
}

/// Collect only factors with their own nonzero affine leaf. A multi-factor
/// affine expression is not assumed injective merely because every
/// coefficient is nonzero.
fn checked_explore_projection_term_separators(
    term: &CheckedExploreSourceProjectionTerm,
    separators: &mut BTreeSet<u32>,
) {
    match term {
        CheckedExploreSourceProjectionTerm::Affine(affine) if affine.coefficients.len() == 1 => {
            let (&binding, &coefficient) = affine
                .coefficients
                .iter()
                .next()
                .expect("single affine coefficient checked");
            if coefficient != 0 {
                separators.insert(binding);
            }
        }
        CheckedExploreSourceProjectionTerm::Constructor { fields, .. } => {
            for (_, child) in fields.iter() {
                checked_explore_projection_term_separators(child, separators);
            }
        }
        CheckedExploreSourceProjectionTerm::Affine(_)
        | CheckedExploreSourceProjectionTerm::Ground { .. } => {}
    }
}

fn checked_explore_projection_term(
    expression: &Expr,
    site: &ExprSiteId,
    resolutions: &CheckedResolutionArtifacts,
    binder_indices: &BTreeMap<CheckedBinderSiteId, usize>,
    prior_terms: &[CheckedExploreSourceProjectionTerm],
    factor_bounds: &BTreeMap<u32, (i64, i64)>,
) -> Option<CheckedExploreSourceProjectionTerm> {
    let resolution = resolutions.expressions.get(site)?;
    match &expression.kind {
        ExprKind::Var(_) => {
            if let Some(CheckedValueBinding::Binder {
                kind: CheckedBinderKind::ExploreValue,
                site: binder,
            }) = &resolution.value_binding
            {
                return binder_indices
                    .get(binder)
                    .and_then(|index| prior_terms.get(*index))
                    .cloned();
            }
            let constructor = resolution.exact_constructor.as_ref()?;
            if !constructor.fields.is_empty() {
                return None;
            }
            Some(CheckedExploreSourceProjectionTerm::Constructor {
                constructor_digest: checked_explore_projection_constructor_digest(constructor),
                fields: Box::new([]),
            })
        }
        ExprKind::Lit(Literal::Int(_)) | ExprKind::BinOp(_, _, _) | ExprKind::UnOp(_, _) => {
            checked_explore_projection_affine(
                expression,
                site,
                resolutions,
                binder_indices,
                prior_terms,
                factor_bounds,
            )
            .map(CheckedExploreSourceProjectionTerm::Affine)
        }
        ExprKind::Lit(literal) => Some(CheckedExploreSourceProjectionTerm::Ground {
            digest: checked_explore_projection_literal_digest(literal),
        }),
        ExprKind::Unit => Some(CheckedExploreSourceProjectionTerm::Ground {
            digest: Sha256::digest(b"futuruna.checked-explore-source-projection.unit.v1\0").into(),
        }),
        ExprKind::App(_, arguments) => {
            let constructor = resolution.exact_constructor.as_ref()?;
            if constructor.fields.len() != arguments.len() {
                return None;
            }
            let mut fields = Vec::with_capacity(constructor.fields.len());
            for field in constructor.fields.iter() {
                let source_index = resolution
                    .named_arguments
                    .as_ref()
                    .and_then(|order| {
                        order
                            .canonical_source_indices
                            .get(field.field_index)
                            .copied()
                    })
                    .or_else(|| {
                        (resolution.named_arguments.is_none()).then_some(field.field_index)
                    })?;
                let argument = arguments.get(source_index)?;
                let argument_site =
                    CheckedExploreSemanticClosure::child_site(site, source_index + 1);
                let (value, value_site) = if resolution.named_arguments.is_some() {
                    let (_, value) = named_arg_parts(argument)?;
                    (
                        value,
                        CheckedExploreSemanticClosure::child_site(&argument_site, 2),
                    )
                } else {
                    (argument, argument_site)
                };
                let value = checked_explore_projection_term(
                    value,
                    &value_site,
                    resolutions,
                    binder_indices,
                    prior_terms,
                    factor_bounds,
                )?;
                fields.push((checked_explore_projection_field(field)?, value));
            }
            Some(CheckedExploreSourceProjectionTerm::Constructor {
                constructor_digest: checked_explore_projection_constructor_digest(constructor),
                fields: fields.into_boxed_slice(),
            })
        }
        _ => None,
    }
}

fn checked_explore_projection_affine(
    expression: &Expr,
    site: &ExprSiteId,
    resolutions: &CheckedResolutionArtifacts,
    binder_indices: &BTreeMap<CheckedBinderSiteId, usize>,
    prior_terms: &[CheckedExploreSourceProjectionTerm],
    factor_bounds: &BTreeMap<u32, (i64, i64)>,
) -> Option<CheckedExploreSourceProjectionAffine> {
    let resolution = resolutions.expressions.get(site)?;
    if !matches!(
        &resolution.resolved_type,
        CheckedExpressionType::Resolved(Ty::Name(name)) if name == "Int"
    ) {
        return None;
    }
    match &expression.kind {
        ExprKind::Lit(Literal::Int(value)) => Some(CheckedExploreSourceProjectionAffine {
            coefficients: BTreeMap::new(),
            offset: *value,
            minimum: *value,
            maximum: *value,
            proof_digest: checked_explore_projection_affine_leaf_digest(0x01, 0, *value, *value),
        }),
        ExprKind::Var(_) => {
            let CheckedValueBinding::Binder {
                kind: CheckedBinderKind::ExploreValue,
                site: binder,
            } = resolution.value_binding.as_ref()?
            else {
                return None;
            };
            let index = *binder_indices.get(binder)?;
            let term = prior_terms.get(index)?;
            match term {
                CheckedExploreSourceProjectionTerm::Affine(affine) => Some(affine.clone()),
                _ => None,
            }
        }
        ExprKind::UnOp(operator, inner) if matches!(operator.as_str(), "+" | "-") => {
            let inner_site = CheckedExploreSemanticClosure::child_site(site, 0);
            let inner = checked_explore_projection_affine(
                inner,
                &inner_site,
                resolutions,
                binder_indices,
                prior_terms,
                factor_bounds,
            )?;
            if operator == "+" {
                return Some(inner);
            }
            let coefficients = inner
                .coefficients
                .iter()
                .map(|(binding, coefficient)| {
                    coefficient.checked_neg().map(|value| (*binding, value))
                })
                .collect::<Option<BTreeMap<_, _>>>()?;
            let offset = inner.offset.checked_neg()?;
            let minimum = inner.maximum.checked_neg()?;
            let maximum = inner.minimum.checked_neg()?;
            let proof_digest = checked_explore_projection_affine_node_digest(
                0x03,
                inner.proof_digest,
                None,
                minimum,
                maximum,
            );
            Some(CheckedExploreSourceProjectionAffine {
                coefficients,
                offset,
                minimum,
                maximum,
                proof_digest,
            })
        }
        ExprKind::BinOp(operator, left, right) if matches!(operator.as_str(), "+" | "-" | "*") => {
            let left_site = CheckedExploreSemanticClosure::child_site(site, 0);
            let right_site = CheckedExploreSemanticClosure::child_site(site, 1);
            let left = checked_explore_projection_affine(
                left,
                &left_site,
                resolutions,
                binder_indices,
                prior_terms,
                factor_bounds,
            )?;
            let right = checked_explore_projection_affine(
                right,
                &right_site,
                resolutions,
                binder_indices,
                prior_terms,
                factor_bounds,
            )?;
            checked_explore_projection_affine_binary(operator, left, right)
        }
        _ => {
            let CheckedValueBinding::Binder {
                kind: CheckedBinderKind::ExploreValue,
                site: binder,
            } = resolution.value_binding.as_ref()?
            else {
                return None;
            };
            let index = u32::try_from(*binder_indices.get(binder)?).ok()?;
            let (minimum, maximum) = *factor_bounds.get(&index)?;
            let mut coefficients = BTreeMap::new();
            coefficients.insert(index, 1);
            Some(CheckedExploreSourceProjectionAffine {
                coefficients,
                offset: 0,
                minimum,
                maximum,
                proof_digest: checked_explore_projection_affine_leaf_digest(
                    0x02, index, minimum, maximum,
                ),
            })
        }
    }
}

fn checked_explore_projection_affine_binary(
    operator: &str,
    left: CheckedExploreSourceProjectionAffine,
    right: CheckedExploreSourceProjectionAffine,
) -> Option<CheckedExploreSourceProjectionAffine> {
    let (coefficients, offset, minimum, maximum, tag) = match operator {
        "+" | "-" => {
            let sign = if operator == "+" { 1_i64 } else { -1_i64 };
            let mut coefficients = left.coefficients.clone();
            for (binding, coefficient) in &right.coefficients {
                let scaled = coefficient.checked_mul(sign)?;
                let combined = coefficients
                    .get(binding)
                    .copied()
                    .unwrap_or(0)
                    .checked_add(scaled)?;
                if combined == 0 {
                    coefficients.remove(binding);
                } else {
                    coefficients.insert(*binding, combined);
                }
            }
            let offset = left.offset.checked_add(right.offset.checked_mul(sign)?)?;
            let (minimum, maximum) = if operator == "+" {
                (
                    left.minimum.checked_add(right.minimum)?,
                    left.maximum.checked_add(right.maximum)?,
                )
            } else {
                (
                    left.minimum.checked_sub(right.maximum)?,
                    left.maximum.checked_sub(right.minimum)?,
                )
            };
            (
                coefficients,
                offset,
                minimum,
                maximum,
                if operator == "+" { 0x04 } else { 0x05 },
            )
        }
        "*" => {
            let (affine, ground) = if left.coefficients.is_empty() {
                (&right, &left)
            } else if right.coefficients.is_empty() {
                (&left, &right)
            } else {
                return None;
            };
            if ground.minimum != ground.maximum || ground.offset != ground.minimum {
                return None;
            }
            let scalar = ground.offset;
            let coefficients = affine
                .coefficients
                .iter()
                .map(|(binding, coefficient)| {
                    coefficient
                        .checked_mul(scalar)
                        .map(|value| (*binding, value))
                })
                .collect::<Option<BTreeMap<_, _>>>()?;
            let offset = affine.offset.checked_mul(scalar)?;
            let products = [
                affine.minimum.checked_mul(scalar)?,
                affine.maximum.checked_mul(scalar)?,
            ];
            let minimum = *products.iter().min()?;
            let maximum = *products.iter().max()?;
            (coefficients, offset, minimum, maximum, 0x06)
        }
        _ => return None,
    };
    let proof_digest = checked_explore_projection_affine_node_digest(
        tag,
        left.proof_digest,
        Some(right.proof_digest),
        minimum,
        maximum,
    );
    Some(CheckedExploreSourceProjectionAffine {
        coefficients,
        offset,
        minimum,
        maximum,
        proof_digest,
    })
}

fn checked_explore_projection_candidates(
    term: &CheckedExploreSourceProjectionTerm,
    endpoint: CheckedExploreSourceProjectionEndpoint,
    path: &mut Vec<CheckedExploreSourceProjectionField>,
    candidates: &mut BTreeMap<
        u32,
        Vec<(
            CheckedExploreSourceProjectionEndpoint,
            Box<[CheckedExploreSourceProjectionField]>,
            CheckedExploreSourceProjectionAffine,
        )>,
    >,
) {
    match term {
        CheckedExploreSourceProjectionTerm::Affine(affine) if affine.coefficients.len() == 1 => {
            let (&binding, &coefficient) = affine
                .coefficients
                .iter()
                .next()
                .expect("single affine factor checked");
            if coefficient != 0 {
                candidates.entry(binding).or_default().push((
                    endpoint,
                    path.clone().into_boxed_slice(),
                    affine.clone(),
                ));
            }
        }
        CheckedExploreSourceProjectionTerm::Constructor { fields, .. } => {
            for (field, child) in fields.iter() {
                path.push(*field);
                checked_explore_projection_candidates(child, endpoint, path, candidates);
                path.pop();
            }
        }
        CheckedExploreSourceProjectionTerm::Affine(_)
        | CheckedExploreSourceProjectionTerm::Ground { .. } => {}
    }
}

fn checked_explore_projection_static_int_range(
    domain: &explore::ExploreFiniteDomainIr,
) -> Option<(i64, i64)> {
    let explore::ExploreFiniteDomainIr::IntRange {
        start,
        end_exclusive,
    } = domain
    else {
        return None;
    };
    Some((
        checked_explore_projection_ground_int(start)?,
        checked_explore_projection_ground_int(end_exclusive)?,
    ))
}

fn checked_explore_projection_ground_int(expression: &Expr) -> Option<i64> {
    match &expression.kind {
        ExprKind::Lit(Literal::Int(value)) => Some(*value),
        ExprKind::UnOp(operator, inner) if operator == "+" => {
            checked_explore_projection_ground_int(inner)
        }
        ExprKind::UnOp(operator, inner) if operator == "-" => {
            checked_explore_projection_ground_int(inner)?.checked_neg()
        }
        ExprKind::BinOp(operator, left, right) if matches!(operator.as_str(), "+" | "-" | "*") => {
            let left = checked_explore_projection_ground_int(left)?;
            let right = checked_explore_projection_ground_int(right)?;
            match operator.as_str() {
                "+" => left.checked_add(right),
                "-" => left.checked_sub(right),
                "*" => left.checked_mul(right),
                _ => unreachable!("guarded affine integer operator"),
            }
        }
        _ => None,
    }
}

fn checked_explore_projection_field(
    field: &CheckedDataFieldId,
) -> Option<CheckedExploreSourceProjectionField> {
    Some(CheckedExploreSourceProjectionField {
        owner_digest: checked_explore_projection_owner_digest(&field.owner),
        variant_index: u32::try_from(field.variant_index).ok()?,
        field_index: u32::try_from(field.field_index).ok()?,
    })
}

fn checked_explore_projection_owner_digest(owner: &CheckedDataTypeId) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-projection-owner.v2\0");
    match owner {
        CheckedDataTypeId::Intrinsic { canonical_name } => {
            checked_query_hash_component(&mut hasher, "owner-kind", "intrinsic");
            checked_query_hash_component(&mut hasher, "canonical-name", canonical_name);
        }
        CheckedDataTypeId::Declared(owner) => {
            checked_query_hash_component(&mut hasher, "owner-kind", "declared");
            checked_query_hash_component(&mut hasher, "model-owner", &owner.semantic_key());
        }
    }
    hasher.finalize().into()
}

fn checked_explore_projection_constructor_digest(
    constructor: &CheckedConstructorIdentity,
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-projection-constructor.v1\0");
    hasher.update(checked_explore_projection_owner_digest(&constructor.owner));
    checked_query_hash_component(
        &mut hasher,
        "variant-index",
        &constructor.variant_index.to_string(),
    );
    checked_query_hash_component(
        &mut hasher,
        "layout",
        match constructor.layout {
            CheckedConstructorLayout::Positional => "positional",
            CheckedConstructorLayout::Named => "named",
        },
    );
    for field in constructor.fields.iter() {
        if let Some(field) = checked_explore_projection_field(field) {
            checked_explore_projection_hash_field(&mut hasher, field);
        }
    }
    hasher.finalize().into()
}

fn checked_explore_projection_binder_digest(binder: &CheckedBinderSiteId) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-projection-binder.v1\0");
    match binder {
        CheckedBinderSiteId::Expression(site) => {
            checked_query_hash_component(&mut hasher, "binder-kind", "expression");
            checked_explore_projection_hash_site(&mut hasher, site);
        }
        CheckedBinderSiteId::Structural {
            analysis_program,
            declaration,
            normalized_declaration_ordinal,
            ast_path,
            binder_path,
        } => {
            checked_query_hash_component(&mut hasher, "binder-kind", "structural");
            checked_query_hash_component(
                &mut hasher,
                "analysis-program",
                analysis_program.as_str(),
            );
            checked_query_hash_component(&mut hasher, "declaration", &declaration.semantic_key());
            checked_query_hash_component(
                &mut hasher,
                "normalized-ordinal",
                &normalized_declaration_ordinal.to_string(),
            );
            checked_explore_projection_hash_path(&mut hasher, "ast-path", ast_path);
            checked_explore_projection_hash_path(&mut hasher, "binder-path", binder_path);
        }
    }
    hasher.finalize().into()
}

fn checked_explore_projection_hash_site(hasher: &mut Sha256, site: &ExprSiteId) {
    checked_query_hash_component(hasher, "analysis-program", site.analysis_program.as_str());
    checked_query_hash_component(hasher, "declaration", &site.declaration.semantic_key());
    checked_query_hash_component(
        hasher,
        "normalized-ordinal",
        &site.normalized_declaration_ordinal.to_string(),
    );
    checked_explore_projection_hash_path(hasher, "ast-path", &site.ast_path);
}

fn checked_explore_projection_hash_path(hasher: &mut Sha256, label: &str, path: &[u32]) {
    checked_query_hash_component(hasher, label, &path.len().to_string());
    for component in path {
        checked_query_hash_component(hasher, "path-component", &component.to_string());
    }
}

fn checked_explore_projection_literal_digest(literal: &Literal) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-projection-literal.v1\0");
    match literal {
        Literal::Int(value) => {
            checked_query_hash_component(&mut hasher, "kind", "int");
            checked_query_hash_component(&mut hasher, "value", &value.to_string());
        }
        Literal::Float(value) => {
            checked_query_hash_component(&mut hasher, "kind", "float-bits");
            checked_query_hash_component(&mut hasher, "value", &value.to_bits().to_string());
        }
        Literal::Str(value) => {
            checked_query_hash_component(&mut hasher, "kind", "string");
            checked_query_hash_component(&mut hasher, "value", value);
        }
        Literal::Char(value) => {
            checked_query_hash_component(&mut hasher, "kind", "character");
            checked_query_hash_component(&mut hasher, "value", &(*value as u32).to_string());
        }
        Literal::Bool(value) => {
            checked_query_hash_component(&mut hasher, "kind", "boolean");
            checked_query_hash_component(
                &mut hasher,
                "value",
                if *value { "true" } else { "false" },
            );
        }
    }
    hasher.finalize().into()
}

fn checked_explore_projection_affine_leaf_digest(
    tag: u8,
    binding_index: u32,
    minimum: i64,
    maximum: i64,
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-projection-affine.v1\0");
    hasher.update([tag]);
    hasher.update(binding_index.to_le_bytes());
    hasher.update(minimum.to_le_bytes());
    hasher.update(maximum.to_le_bytes());
    hasher.finalize().into()
}

fn checked_explore_projection_affine_node_digest(
    tag: u8,
    left: [u8; 32],
    right: Option<[u8; 32]>,
    minimum: i64,
    maximum: i64,
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-projection-affine.v1\0");
    hasher.update([tag]);
    hasher.update(left);
    if let Some(right) = right {
        hasher.update(right);
    }
    hasher.update(minimum.to_le_bytes());
    hasher.update(maximum.to_le_bytes());
    hasher.finalize().into()
}

fn checked_explore_projection_hash_field(
    hasher: &mut Sha256,
    field: CheckedExploreSourceProjectionField,
) {
    hasher.update(field.owner_digest);
    hasher.update(field.variant_index.to_le_bytes());
    hasher.update(field.field_index.to_le_bytes());
}

fn checked_explore_projection_hash_term(
    hasher: &mut Sha256,
    term: &CheckedExploreSourceProjectionTerm,
) {
    match term {
        CheckedExploreSourceProjectionTerm::Affine(affine) => {
            hasher.update([0x01]);
            hasher.update(affine.proof_digest);
            checked_query_hash_component(
                hasher,
                "coefficient-count",
                &affine.coefficients.len().to_string(),
            );
            for (binding, coefficient) in &affine.coefficients {
                hasher.update(binding.to_le_bytes());
                hasher.update(coefficient.to_le_bytes());
            }
            hasher.update(affine.offset.to_le_bytes());
            hasher.update(affine.minimum.to_le_bytes());
            hasher.update(affine.maximum.to_le_bytes());
        }
        CheckedExploreSourceProjectionTerm::Constructor {
            constructor_digest,
            fields,
        } => {
            hasher.update([0x02]);
            hasher.update(constructor_digest);
            checked_query_hash_component(hasher, "field-count", &fields.len().to_string());
            for (field, child) in fields.iter() {
                checked_explore_projection_hash_field(hasher, *field);
                checked_explore_projection_hash_term(hasher, child);
            }
        }
        CheckedExploreSourceProjectionTerm::Ground { digest } => {
            hasher.update([0x03]);
            hasher.update(digest);
        }
    }
}

fn checked_explore_projection_hash_factor(
    hasher: &mut Sha256,
    factor: &CheckedExploreSourceProjectionFactor,
) {
    hasher.update(factor.binding_index.to_le_bytes());
    hasher.update(factor.binder_digest);
    hasher.update(factor.start.to_le_bytes());
    hasher.update(factor.end_exclusive.to_le_bytes());
    hasher.update(factor.exact_cardinality.to_le_bytes());
}

fn checked_explore_projection_factor_cardinality(
    factors: &[CheckedExploreSourceProjectionFactor],
) -> Option<u128> {
    if factors.is_empty() {
        return None;
    }
    factors.iter().try_fold(1_u128, |cardinality, factor| {
        (factor.exact_cardinality > 0)
            .then_some(())
            .and_then(|()| cardinality.checked_mul(factor.exact_cardinality))
    })
}

fn checked_explore_product_rank_factor_root(
    factors: &[CheckedExploreSourceProjectionFactor],
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-product-rank-factor-root.v1\0");
    checked_query_hash_component(&mut hasher, "factor-count", &factors.len().to_string());
    for factor in factors {
        checked_explore_projection_hash_factor(&mut hasher, factor);
    }
    hasher.finalize().into()
}

fn checked_explore_product_rank_projection_digest(
    role: u8,
    terms: &[CheckedExploreSourceProjectionTerm],
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-product-rank-projection.v1\0");
    hasher.update([role]);
    checked_query_hash_component(&mut hasher, "term-count", &terms.len().to_string());
    for term in terms {
        checked_explore_projection_hash_term(&mut hasher, term);
    }
    hasher.finalize().into()
}

fn checked_explore_product_rank_grouped_distinct_certificate_id(
    certificate: &CheckedExploreProductRankGroupedDistinctCertificate,
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-product-rank-grouped-distinct.v1\0");
    hasher.update(certificate.version.to_le_bytes());
    hasher.update(certificate.relation_id.bytes());
    hasher.update(certificate.view_id.bytes());
    hasher.update(certificate.source_projection_certificate_id);
    hasher.update(certificate.source_factor_root);
    hasher.update(certificate.factor_count.to_le_bytes());
    hasher.update(certificate.group_factor_count.to_le_bytes());
    hasher.update(certificate.exact_group_count.to_le_bytes());
    hasher.update(certificate.exact_members_per_group.to_le_bytes());
    hasher.update(certificate.group_projection_digest);
    hasher.update(certificate.distinct_projection_digest);
    hasher.finalize().into()
}

fn checked_explore_projection_certificate_id(
    version: u32,
    relation_id: explore::RelationId,
    semantic_dependency_digest: [u8; 32],
    total_construction_digest: [u8; 32],
    factors: &[CheckedExploreSourceProjectionFactor],
    witnesses: &[CheckedExploreSourceProjectionWitness],
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-image-projection-certificate.v2\0");
    checked_query_hash_component(&mut hasher, "certificate-version", &version.to_string());
    hasher.update(relation_id.bytes());
    hasher.update(semantic_dependency_digest);
    hasher.update(total_construction_digest);
    checked_query_hash_component(&mut hasher, "factor-count", &factors.len().to_string());
    for factor in factors {
        checked_explore_projection_hash_factor(&mut hasher, factor);
    }
    checked_query_hash_component(&mut hasher, "witness-count", &witnesses.len().to_string());
    for witness in witnesses {
        hasher.update(witness.witness_id);
    }
    hasher.finalize().into()
}

#[allow(clippy::too_many_arguments)]
fn checked_explore_projection_witness_id(
    relation_id: explore::RelationId,
    factor: &CheckedExploreSourceProjectionFactor,
    endpoint: CheckedExploreSourceProjectionEndpoint,
    path: &[CheckedExploreSourceProjectionField],
    coefficient: i64,
    offset: i64,
    output_min: i64,
    output_max: i64,
    affine_proof_digest: [u8; 32],
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-source-projection-witness.v1\0");
    hasher.update(relation_id.bytes());
    checked_explore_projection_hash_factor(&mut hasher, factor);
    hasher.update([match endpoint {
        CheckedExploreSourceProjectionEndpoint::Context => 0x01,
        CheckedExploreSourceProjectionEndpoint::Before => 0x02,
    }]);
    checked_query_hash_component(&mut hasher, "path-count", &path.len().to_string());
    for field in path {
        checked_explore_projection_hash_field(&mut hasher, *field);
    }
    hasher.update(coefficient.to_le_bytes());
    hasher.update(offset.to_le_bytes());
    hasher.update(output_min.to_le_bytes());
    hasher.update(output_max.to_le_bytes());
    hasher.update(affine_proof_digest);
    hasher.finalize().into()
}

fn checked_query_hash_component(hasher: &mut Sha256, label: &str, value: &str) {
    hasher.update((label.len() as u64).to_le_bytes());
    hasher.update(label.as_bytes());
    hasher.update((value.len() as u64).to_le_bytes());
    hasher.update(value.as_bytes());
}

fn hash_checked_explore_type_owner(
    hasher: &mut Sha256,
    resolutions: &CheckedResolutionArtifacts,
    name: &str,
) -> Result<(), CheckedExploreQueryArtifactIssue> {
    let owner = resolutions.data_type_identities.get(name).ok_or_else(|| {
        CheckedExploreQueryArtifactIssue::TypeOwnerNotResolved {
            ty: Ty::Name(name.to_string()),
        }
    })?;
    match owner {
        CheckedDataTypeId::Declared(owner) => {
            checked_query_hash_component(hasher, "type-owner-kind", "declared");
            checked_query_hash_component(hasher, "type-owner", &owner.semantic_key());
        }
        CheckedDataTypeId::Intrinsic { canonical_name } => {
            checked_query_hash_component(hasher, "type-owner-kind", "intrinsic");
            checked_query_hash_component(hasher, "type-owner-intrinsic", canonical_name);
        }
    }
    Ok(())
}

fn hash_checked_explore_type_schema(
    hasher: &mut Sha256,
    resolutions: &CheckedResolutionArtifacts,
    ty: &Ty,
) -> Result<(), CheckedExploreQueryArtifactIssue> {
    match ty {
        Ty::Name(name) if name == "Unit" => {
            checked_query_hash_component(hasher, "type-kind", "unit");
            hash_checked_explore_type_owner(hasher, resolutions, "Unit")?;
        }
        Ty::Name(name) => {
            checked_query_hash_component(hasher, "type-kind", "name");
            hash_checked_explore_type_owner(hasher, resolutions, name)?;
        }
        Ty::App(constructor, arguments) => {
            checked_query_hash_component(hasher, "type-kind", "application");
            hash_checked_explore_type_schema(hasher, resolutions, constructor)?;
            checked_query_hash_component(
                hasher,
                "type-argument-count",
                &arguments.len().to_string(),
            );
            for argument in arguments {
                hash_checked_explore_type_schema(hasher, resolutions, argument)?;
            }
        }
        Ty::Arrow(parameter, result) => {
            checked_query_hash_component(hasher, "type-kind", "arrow");
            hash_checked_explore_type_schema(hasher, resolutions, parameter)?;
            hash_checked_explore_type_schema(hasher, resolutions, result)?;
        }
        Ty::Ref(inner) => {
            checked_query_hash_component(hasher, "type-kind", "reference");
            hash_checked_explore_type_schema(hasher, resolutions, inner)?;
        }
        Ty::MutRef(inner) => {
            checked_query_hash_component(hasher, "type-kind", "mutable-reference");
            hash_checked_explore_type_schema(hasher, resolutions, inner)?;
        }
        Ty::Shared(inner) => {
            checked_query_hash_component(hasher, "type-kind", "shared");
            hash_checked_explore_type_schema(hasher, resolutions, inner)?;
        }
        Ty::Optional(inner) => {
            checked_query_hash_component(hasher, "type-kind", "optional");
            hash_checked_explore_type_owner(hasher, resolutions, "Option")?;
            hash_checked_explore_type_schema(hasher, resolutions, inner)?;
        }
        Ty::Var(_) => {
            checked_query_hash_component(hasher, "type-kind", "variable");
        }
        Ty::Unit => {
            checked_query_hash_component(hasher, "type-kind", "unit");
            hash_checked_explore_type_owner(hasher, resolutions, "Unit")?;
        }
        Ty::Hole => {
            return Err(CheckedExploreQueryArtifactIssue::RelationalIr(
                "checked Explore relation contains an unresolved type hole".into(),
            ));
        }
    }
    Ok(())
}

fn hash_checked_explore_value(hasher: &mut Sha256, value: &explore::ExploreValue) {
    match value {
        explore::ExploreValue::Int(value) => {
            checked_query_hash_component(hasher, "value-kind", "int");
            checked_query_hash_component(hasher, "value", &value.to_string());
        }
        explore::ExploreValue::FloatBits(value) => {
            checked_query_hash_component(hasher, "value-kind", "float-bits");
            checked_query_hash_component(hasher, "value", &value.to_string());
        }
        explore::ExploreValue::String(value) => {
            checked_query_hash_component(hasher, "value-kind", "string");
            checked_query_hash_component(hasher, "value", value);
        }
        explore::ExploreValue::Character(value) => {
            checked_query_hash_component(hasher, "value-kind", "character");
            checked_query_hash_component(hasher, "value", &(*value as u32).to_string());
        }
        explore::ExploreValue::Boolean(value) => {
            checked_query_hash_component(hasher, "value-kind", "boolean");
            checked_query_hash_component(hasher, "value", if *value { "true" } else { "false" });
        }
        explore::ExploreValue::Unit => {
            checked_query_hash_component(hasher, "value-kind", "unit");
        }
        explore::ExploreValue::List(values)
        | explore::ExploreValue::Set(values)
        | explore::ExploreValue::Tuple(values) => {
            let kind = match value {
                explore::ExploreValue::List(_) => "list",
                explore::ExploreValue::Set(_) => "set",
                explore::ExploreValue::Tuple(_) => "tuple",
                _ => unreachable!(),
            };
            checked_query_hash_component(hasher, "value-kind", kind);
            checked_query_hash_component(hasher, "value-length", &values.len().to_string());
            for value in values {
                hash_checked_explore_value(hasher, value);
            }
        }
        explore::ExploreValue::Constructor {
            variant,
            positional,
            fields,
            ..
        } => {
            checked_query_hash_component(hasher, "value-kind", "constructor");
            checked_query_hash_component(hasher, "constructor-variant", variant);
            checked_query_hash_component(
                hasher,
                "constructor-layout",
                if *positional { "positional" } else { "named" },
            );
            checked_query_hash_component(
                hasher,
                "constructor-field-count",
                &fields.len().to_string(),
            );
            for (field, value) in fields.iter() {
                checked_query_hash_component(hasher, "constructor-field", field);
                hash_checked_explore_value(hasher, value);
            }
        }
    }
}

fn hash_checked_explore_cardinality(
    hasher: &mut Sha256,
    cardinality: &explore::ExploreCardinality,
) {
    match cardinality {
        explore::ExploreCardinality::Exact(value) => {
            checked_query_hash_component(hasher, "finite-plan-cardinality-kind", "exact");
            checked_query_hash_component(
                hasher,
                "finite-plan-cardinality-value",
                &value.to_string(),
            );
        }
        explore::ExploreCardinality::ExceedsU128 => {
            checked_query_hash_component(hasher, "finite-plan-cardinality-kind", "exceeds-u128");
        }
    }
}

fn hash_checked_explore_finite_plan(hasher: &mut Sha256, plan: &explore::ExploreFiniteTypePlan) {
    match plan {
        explore::ExploreFiniteTypePlan::Unit => {
            checked_query_hash_component(hasher, "finite-plan-kind", "unit");
        }
        explore::ExploreFiniteTypePlan::Bool => {
            checked_query_hash_component(hasher, "finite-plan-kind", "bool");
        }
        explore::ExploreFiniteTypePlan::Tuple {
            elements,
            cardinality,
        } => {
            checked_query_hash_component(hasher, "finite-plan-kind", "tuple");
            hash_checked_explore_cardinality(hasher, cardinality);
            checked_query_hash_component(
                hasher,
                "finite-plan-element-count",
                &elements.len().to_string(),
            );
            for element in elements {
                hash_checked_explore_finite_plan(hasher, element);
            }
        }
        explore::ExploreFiniteTypePlan::Sum {
            variants,
            cardinality,
            ..
        } => {
            checked_query_hash_component(hasher, "finite-plan-kind", "sum");
            hash_checked_explore_cardinality(hasher, cardinality);
            checked_query_hash_component(
                hasher,
                "finite-plan-variant-count",
                &variants.len().to_string(),
            );
            for (variant_index, variant) in variants.iter().enumerate() {
                checked_query_hash_component(
                    hasher,
                    "finite-plan-variant-index",
                    &variant_index.to_string(),
                );
                checked_query_hash_component(hasher, "finite-plan-variant-name", &variant.name);
                checked_query_hash_component(
                    hasher,
                    "finite-plan-variant-layout",
                    if variant.positional {
                        "positional"
                    } else {
                        "named"
                    },
                );
                checked_query_hash_component(
                    hasher,
                    "finite-plan-field-count",
                    &variant.fields.len().to_string(),
                );
                for field in &variant.fields {
                    checked_query_hash_component(hasher, "finite-plan-field-name", &field.name);
                    hash_checked_explore_finite_plan(hasher, &field.plan);
                }
            }
        }
    }
}

fn hash_checked_explore_exact_domain(
    hasher: &mut Sha256,
    resolutions: &CheckedResolutionArtifacts,
    domain: &explore::ExploreExactDomain,
) -> Result<(), CheckedExploreQueryArtifactIssue> {
    match domain {
        explore::ExploreExactDomain::Enumerated { values, .. } => {
            checked_query_hash_component(hasher, "exact-domain-kind", "enumerated-set");
            let values = values.iter().cloned().collect::<BTreeSet<_>>();
            checked_query_hash_component(
                hasher,
                "exact-domain-value-count",
                &values.len().to_string(),
            );
            for value in &values {
                hash_checked_explore_value(hasher, value);
            }
        }
        explore::ExploreExactDomain::IntRange {
            start,
            end_exclusive,
            cardinality,
        } => {
            checked_query_hash_component(hasher, "exact-domain-kind", "int-range");
            checked_query_hash_component(hasher, "exact-domain-start", &start.to_string());
            checked_query_hash_component(hasher, "exact-domain-end", &end_exclusive.to_string());
            checked_query_hash_component(
                hasher,
                "exact-domain-cardinality",
                &cardinality.to_string(),
            );
        }
        explore::ExploreExactDomain::FiniteType { ty, plan } => {
            checked_query_hash_component(hasher, "exact-domain-kind", "finite-type");
            hash_checked_explore_type_schema(hasher, resolutions, ty)?;
            hash_checked_explore_finite_plan(hasher, plan);
        }
    }
    Ok(())
}

fn hash_checked_explore_finite_domain_ir(
    hasher: &mut Sha256,
    resolutions: &CheckedResolutionArtifacts,
    domain: &explore::ExploreFiniteDomainIr,
) -> Result<(), CheckedExploreQueryArtifactIssue> {
    match domain {
        explore::ExploreFiniteDomainIr::Exact(domain) => {
            checked_query_hash_component(hasher, "domain-kind", "exact");
            hash_checked_explore_exact_domain(hasher, resolutions, domain)?;
        }
        explore::ExploreFiniteDomainIr::Collection {
            collection_ty,
            element_ty,
            ..
        } => {
            checked_query_hash_component(hasher, "domain-kind", "finite-collection");
            hash_checked_explore_type_schema(hasher, resolutions, collection_ty)?;
            hash_checked_explore_type_schema(hasher, resolutions, element_ty)?;
        }
        explore::ExploreFiniteDomainIr::IntRange { .. } => {
            checked_query_hash_component(hasher, "domain-kind", "dependent-int-range");
        }
    }
    Ok(())
}

fn hash_checked_explore_relation_ir(
    hasher: &mut Sha256,
    resolutions: &CheckedResolutionArtifacts,
    query: &explore::ExploreQueryIr,
    semantic_closure_digest: [u8; 32],
) -> Result<(), CheckedExploreQueryArtifactIssue> {
    checked_query_hash_component(
        hasher,
        "relational-ir-version",
        &explore::EXPLORE_RELATIONAL_IR_VERSION.to_string(),
    );
    checked_query_hash_component(
        hasher,
        "relation-normalization-version",
        &query.source.normalization_version.to_string(),
    );
    checked_query_hash_component(hasher, "source-multiplicity", "set-normalized");
    checked_query_hash_component(
        hasher,
        "source-binding-count",
        &query.source.bindings.len().to_string(),
    );
    for binding in &query.source.bindings {
        checked_query_hash_component(
            hasher,
            "source-binding-index",
            &binding.binding_index.to_string(),
        );
        checked_query_hash_component(
            hasher,
            "source-binding-role",
            match binding.role {
                explore::ExploreSourceBindingRoleIr::Auxiliary => "auxiliary",
                explore::ExploreSourceBindingRoleIr::Context => "context",
                explore::ExploreSourceBindingRoleIr::Before => "before",
            },
        );
        hash_checked_explore_type_schema(hasher, resolutions, &binding.value_ty)?;
        checked_query_hash_component(
            hasher,
            "source-dependency-count",
            &binding.dependencies.len().to_string(),
        );
        for dependency in &binding.dependencies {
            checked_query_hash_component(
                hasher,
                "source-dependency-index",
                &dependency.binding_index.to_string(),
            );
        }
        match &binding.kind {
            explore::ExploreSourceBindingKindIr::Singleton { .. } => {
                checked_query_hash_component(hasher, "source-binding-kind", "singleton");
            }
            explore::ExploreSourceBindingKindIr::Finite { domain } => {
                checked_query_hash_component(hasher, "source-binding-kind", "finite");
                hash_checked_explore_finite_domain_ir(hasher, resolutions, domain)?;
            }
        }
    }
    checked_query_hash_component(
        hasher,
        "context-binding-index",
        &query.source.context_binding_index.to_string(),
    );
    checked_query_hash_component(
        hasher,
        "before-binding-index",
        &query.source.before_binding_index.to_string(),
    );
    hash_checked_explore_type_schema(hasher, resolutions, &query.source.context_ty)?;
    hash_checked_explore_type_schema(hasher, resolutions, &query.source.before_ty)?;
    checked_query_hash_component(hasher, "successor-multiplicity", "set-normalized");
    hash_checked_explore_type_schema(hasher, resolutions, &query.successor.after_ty)?;

    match &query.successor.kind {
        explore::ExploreSuccessorKindIr::Singleton { .. } => {
            checked_query_hash_component(hasher, "successor-kind", "singleton");
        }
        explore::ExploreSuccessorKindIr::Finite { domain } => {
            checked_query_hash_component(hasher, "successor-kind", "finite");
            hash_checked_explore_finite_domain_ir(hasher, resolutions, domain)?;
        }
    }
    hasher.update(semantic_closure_digest);
    Ok(())
}

fn checked_explore_admission_semantic_seal(
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
    semantic_binders: &BTreeMap<CheckedBinderSiteId, Box<str>>,
    query: &explore::ExploreQueryIr,
    sites: &CheckedExploreQuerySites,
) -> Result<CheckedExploreSemanticLayerSeal, CheckedExploreQueryArtifactIssue> {
    if query.admissions.len() != sites.admissions.len() {
        return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
            "admission predicate and checked root count mismatch".into(),
        ));
    }
    let mut conjuncts = BTreeSet::new();
    let mut reachable_declarations = BTreeSet::new();
    let mut reachable_dependencies = BTreeSet::new();
    for (admission, site) in query.admissions.iter().zip(sites.admissions.iter()) {
        let mut conjunct_hasher = Sha256::new();
        checked_query_hash_component(
            &mut conjunct_hasher,
            "admission-scope",
            match admission.scope {
                ExploreAdmissionScope::Before => "before",
                ExploreAdmissionScope::After => "after",
                ExploreAdmissionScope::Transition => "transition",
            },
        );
        let root = [site.clone()];
        let closure = checked_explore_semantic_dependency_seal(
            index,
            resolutions,
            semantic_binders,
            "admission",
            &root,
            &[],
        )?;
        conjunct_hasher.update(closure.digest);
        reachable_declarations.extend(closure.reachable_declarations);
        reachable_dependencies.extend(closure.reachable_dependencies);
        conjuncts.insert(<[u8; 32]>::from(conjunct_hasher.finalize()));
    }
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-admission-semantics.v1\0");
    checked_query_hash_component(&mut hasher, "admission-count", &conjuncts.len().to_string());
    for conjunct in conjuncts {
        hasher.update(conjunct);
    }
    Ok(CheckedExploreSemanticLayerSeal {
        digest: hasher.finalize().into(),
        reachable_declarations,
        reachable_dependencies,
    })
}

fn checked_explore_find_semantic_seal(
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
    semantic_binders: &BTreeMap<CheckedBinderSiteId, Box<str>>,
    find: &explore::ExploreFindIr,
    site: Option<&ExprSiteId>,
) -> Result<CheckedExploreSemanticLayerSeal, CheckedExploreQueryArtifactIssue> {
    let mut hasher = Sha256::new();
    let mut reachable_declarations = BTreeSet::new();
    let mut reachable_dependencies = BTreeSet::new();
    hasher.update(b"futuruna.checked-explore-find-semantics.v1\0");
    match find {
        explore::ExploreFindIr::All { .. } => {
            checked_query_hash_component(&mut hasher, "find-form", "all");
        }
        explore::ExploreFindIr::Matches { .. } | explore::ExploreFindIr::Violations { .. } => {
            checked_query_hash_component(&mut hasher, "find-form", "predicate");
            let Some(site) = site else {
                return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
                    "predicate FIND has no checked expression root".into(),
                ));
            };
            let roots = [site.clone()];
            let closure = checked_explore_semantic_dependency_seal(
                index,
                resolutions,
                semantic_binders,
                "find",
                &roots,
                &[],
            )?;
            hasher.update(closure.digest);
            reachable_declarations.extend(closure.reachable_declarations);
            reachable_dependencies.extend(closure.reachable_dependencies);
        }
    }
    Ok(CheckedExploreSemanticLayerSeal {
        digest: hasher.finalize().into(),
        reachable_declarations,
        reachable_dependencies,
    })
}

fn hash_checked_explore_result_field_ir(
    hasher: &mut Sha256,
    resolutions: &CheckedResolutionArtifacts,
    role: &str,
    field: &explore::ExploreResultFieldIr,
) -> Result<(), CheckedExploreQueryArtifactIssue> {
    checked_query_hash_component(hasher, &format!("{role}-name"), &field.name);
    hash_checked_explore_type_schema(hasher, resolutions, &field.ty)?;
    Ok(())
}

fn hash_checked_explore_aggregate_field_ir(
    hasher: &mut Sha256,
    resolutions: &CheckedResolutionArtifacts,
    field: &explore::ExploreAggregateFieldIr,
) -> Result<(), CheckedExploreQueryArtifactIssue> {
    checked_query_hash_component(hasher, "aggregate-name", &field.name);
    hash_checked_explore_type_schema(hasher, resolutions, &field.ty)?;
    match &field.reducer {
        explore::ExploreAggregateReducerIr::CountDistinct { value_ty, .. } => {
            checked_query_hash_component(hasher, "aggregate-reducer", "count-distinct");
            hash_checked_explore_type_schema(hasher, resolutions, value_ty)?;
        }
    }
    Ok(())
}

fn checked_explore_view_semantic_digest(
    resolutions: &CheckedResolutionArtifacts,
    view: &explore::ExploreResultViewIr,
    semantic_closure_digest: [u8; 32],
) -> Result<[u8; 32], CheckedExploreQueryArtifactIssue> {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-view-semantics.v1\0");
    match &view.grain {
        explore::ExploreResultGrainIr::EachCase { .. } => {
            checked_query_hash_component(&mut hasher, "result-grain", "each-case");
        }
        explore::ExploreResultGrainIr::EachIncidence { .. } => {
            checked_query_hash_component(&mut hasher, "result-grain", "each-incidence");
        }
        explore::ExploreResultGrainIr::GroupAll { .. } => {
            checked_query_hash_component(&mut hasher, "result-grain", "group-all");
        }
        explore::ExploreResultGrainIr::GroupBy { fields, .. } => {
            checked_query_hash_component(&mut hasher, "result-grain", "group-by");
            checked_query_hash_component(
                &mut hasher,
                "group-field-count",
                &fields.len().to_string(),
            );
            for field in fields {
                hash_checked_explore_result_field_ir(
                    &mut hasher,
                    resolutions,
                    "group-field",
                    field,
                )?;
            }
        }
    }
    checked_query_hash_component(
        &mut hasher,
        "measure-count",
        &view.measures.len().to_string(),
    );
    for field in &view.measures {
        hash_checked_explore_result_field_ir(&mut hasher, resolutions, "measure", field)?;
    }
    checked_query_hash_component(
        &mut hasher,
        "aggregate-count",
        &view.aggregates.len().to_string(),
    );
    for field in &view.aggregates {
        hash_checked_explore_aggregate_field_ir(&mut hasher, resolutions, field)?;
    }
    match &view.having {
        None => checked_query_hash_component(&mut hasher, "having", "none"),
        Some(explore::ExploreResultHavingIr::Varies {
            measure_name,
            measure_index,
            ..
        }) => {
            checked_query_hash_component(&mut hasher, "having", "varies");
            checked_query_hash_component(&mut hasher, "having-measure-name", measure_name);
            checked_query_hash_component(
                &mut hasher,
                "having-measure-index",
                &measure_index.to_string(),
            );
        }
    }
    checked_query_hash_component(&mut hasher, "select-count", &view.select.len().to_string());
    for field in &view.select {
        hash_checked_explore_result_field_ir(&mut hasher, resolutions, "select", field)?;
    }
    match &view.choose {
        None => checked_query_hash_component(&mut hasher, "choose", "none"),
        Some(explore::ExploreResultChoiceIr::Optimize {
            cardinality,
            direction,
            objective_ty,
            ..
        }) => {
            checked_query_hash_component(&mut hasher, "choose", "optimize");
            checked_query_hash_component(
                &mut hasher,
                "choose-cardinality",
                match cardinality {
                    ExploreChooseCardinality::One => "one",
                    ExploreChooseCardinality::All => "all",
                },
            );
            checked_query_hash_component(
                &mut hasher,
                "choose-direction",
                match direction {
                    ExploreOptimizeDirection::Minimize => "minimize",
                    ExploreOptimizeDirection::Maximize => "maximize",
                },
            );
            hash_checked_explore_type_schema(&mut hasher, resolutions, objective_ty)?;
        }
        Some(explore::ExploreResultChoiceIr::Pareto { objectives, .. }) => {
            checked_query_hash_component(&mut hasher, "choose", "pareto");
            checked_query_hash_component(
                &mut hasher,
                "pareto-objective-count",
                &objectives.len().to_string(),
            );
            for objective in objectives {
                checked_query_hash_component(
                    &mut hasher,
                    "pareto-direction",
                    match objective.direction {
                        ExploreOptimizeDirection::Minimize => "minimize",
                        ExploreOptimizeDirection::Maximize => "maximize",
                    },
                );
                hash_checked_explore_type_schema(&mut hasher, resolutions, &objective.ty)?;
            }
        }
    }
    hasher.update(semantic_closure_digest);
    Ok(hasher.finalize().into())
}

fn checked_explore_analysis_identities(
    index: &CheckedExploreSemanticIndex<'_>,
    resolutions: &CheckedResolutionArtifacts,
    semantic_binders: &BTreeMap<CheckedBinderSiteId, Box<str>>,
    query: &explore::ExploreQueryIr,
    sites: &CheckedExploreQuerySites,
    relation_id: explore::RelationId,
    question_id: explore::QuestionId,
) -> Result<Box<[CheckedExploreAnalysisIdentity]>, CheckedExploreQueryArtifactIssue> {
    if query.analysis.len() != sites.analysis.len() {
        return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
            "analysis node/template site count mismatch".into(),
        ));
    }
    let mut identities = Vec::<CheckedExploreAnalysisIdentity>::with_capacity(query.analysis.len());
    for (node_index, (node, node_sites)) in
        query.analysis.iter().zip(sites.analysis.iter()).enumerate()
    {
        let identity = match (node, node_sites) {
            (
                explore::ExploreAnalysisNodeIr::Result(view),
                CheckedExploreAnalysisNodeSites::Result(result_sites),
            ) => {
                let input = match &view.input {
                    explore::ExploreResultInputIr::Sources => {
                        explore::ViewInputId::Sources(relation_id)
                    }
                    explore::ExploreResultInputIr::Selected => {
                        explore::ViewInputId::Selected(question_id)
                    }
                    explore::ExploreResultInputIr::MechanismIncidence {
                        request_node_index,
                    } => match identities.get(*request_node_index) {
                        Some(CheckedExploreAnalysisIdentity::Mechanisms { request_id, .. })
                            if *request_node_index < node_index =>
                        {
                            explore::ViewInputId::MechanismIncidence(*request_id)
                        }
                        _ => {
                            return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(format!(
                                "result node {node_index} does not resolve prior mechanism node {request_node_index}"
                            )))
                        }
                    },
                };
                let expression_roots = result_sites
                    .group_fields
                    .iter()
                    .chain(result_sites.measures.iter())
                    .chain(result_sites.aggregates.iter())
                    .chain(result_sites.select.iter())
                    .chain(result_sites.choice_objectives.iter())
                    .cloned()
                    .collect::<Vec<_>>();
                let mut type_roots = Vec::new();
                if let explore::ExploreResultGrainIr::GroupBy { fields, .. } = &view.grain {
                    type_roots.extend(fields.iter().map(|field| field.ty.clone()));
                }
                type_roots.extend(view.measures.iter().map(|field| field.ty.clone()));
                for aggregate in &view.aggregates {
                    type_roots.push(aggregate.ty.clone());
                    match &aggregate.reducer {
                        explore::ExploreAggregateReducerIr::CountDistinct { value_ty, .. } => {
                            type_roots.push(value_ty.clone());
                        }
                    }
                }
                type_roots.extend(view.select.iter().map(|field| field.ty.clone()));
                match &view.choose {
                    None => {}
                    Some(explore::ExploreResultChoiceIr::Optimize { objective_ty, .. }) => {
                        type_roots.push(objective_ty.clone());
                    }
                    Some(explore::ExploreResultChoiceIr::Pareto { objectives, .. }) => {
                        type_roots.extend(objectives.iter().map(|objective| objective.ty.clone()));
                    }
                }
                let closure_digest = checked_explore_semantic_dependency_digest(
                    index,
                    resolutions,
                    semantic_binders,
                    "result view",
                    &expression_roots,
                    &type_roots,
                )?;
                let view_digest =
                    checked_explore_view_semantic_digest(resolutions, view, closure_digest)?;
                CheckedExploreAnalysisIdentity::View {
                    view_id: explore::ViewId::from_canonical_view_digest(input, view_digest),
                }
            }
            (
                explore::ExploreAnalysisNodeIr::Mechanisms(request),
                CheckedExploreAnalysisNodeSites::Mechanisms(template_site),
            ) => {
                let target = match &request.target {
                    explore::ExploreMechanismTargetIr::SelectedCases => {
                        explore::MechanismTargetId::Selected
                    }
                    explore::ExploreMechanismTargetIr::ViewChosen { view_node_index } => {
                        match identities.get(*view_node_index) {
                            Some(CheckedExploreAnalysisIdentity::View { view_id })
                                if *view_node_index < node_index =>
                            {
                                explore::MechanismTargetId::ChosenView(*view_id)
                            }
                            _ => {
                                return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
                                    format!(
                                        "mechanism node {node_index} does not resolve prior view node {view_node_index}"
                                    ),
                                ));
                            }
                        }
                    }
                };
                let observation = explore::MechanismObservationIr::derive_checked(
                    resolutions,
                    template_site.clone(),
                    query.source.before_ty.clone(),
                    query.source.context_ty.clone(),
                )
                .map_err(|error| {
                    CheckedExploreQueryArtifactIssue::AnalysisGraph(error.to_string())
                })?;
                let roots = [template_site.clone()];
                let types = [
                    observation.state_type.clone(),
                    observation.context_type.clone(),
                    observation.observation_type.clone(),
                ];
                let closure_digest = checked_explore_semantic_dependency_digest(
                    index,
                    resolutions,
                    semantic_binders,
                    "mechanism observer",
                    &roots,
                    &types,
                )?;
                let mut observation_hasher = Sha256::new();
                observation_hasher.update(b"futuruna.checked-explore-mechanism-observation.v2\0");
                observation_hasher.update(closure_digest);
                let observation_digest = observation_hasher.finalize().into();
                let mut normalization_hasher = Sha256::new();
                normalization_hasher
                    .update(b"futuruna.checked-explore-mechanism-normalization.v2\0");
                checked_query_hash_component(
                    &mut normalization_hasher,
                    "observation-normalization-version",
                    &observation.normalization_version.to_string(),
                );
                checked_query_hash_component(
                    &mut normalization_hasher,
                    "signature-normalization",
                    "differential-control-signature-v3-complete-activation-anchors",
                );
                checked_query_hash_component(
                    &mut normalization_hasher,
                    "replay-abi-version",
                    &explore::RELATIONAL_MECHANISM_REPLAY_ABI_VERSION.to_string(),
                );
                let normalization_digest = normalization_hasher.finalize().into();
                CheckedExploreAnalysisIdentity::Mechanisms {
                    request_id: explore::MechanismRequestId::from_canonical_request_digests(
                        question_id,
                        target,
                        observation_digest,
                        normalization_digest,
                    ),
                    observation,
                }
            }
            _ => {
                return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(format!(
                    "analysis node {node_index} and its checked site have different kinds"
                )))
            }
        };
        identities.push(identity);
    }
    Ok(identities.into_boxed_slice())
}

fn checked_explore_analysis_graph_digest(
    query: &explore::ExploreQueryIr,
    question_id: explore::QuestionId,
    identities: &[CheckedExploreAnalysisIdentity],
) -> Result<Box<str>, CheckedExploreQueryArtifactIssue> {
    if query.analysis.len() != identities.len() {
        return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
            "analysis node/identity count mismatch".into(),
        ));
    }
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-analysis-graph.v1\0");
    hasher.update(question_id.bytes());
    let mut semantic_nodes = BTreeSet::<(u8, [u8; 32])>::new();
    for (node_index, (node, identity)) in query.analysis.iter().zip(identities).enumerate() {
        match (node, identity) {
            (
                explore::ExploreAnalysisNodeIr::Result(_),
                CheckedExploreAnalysisIdentity::View { view_id },
            ) => {
                semantic_nodes.insert((0x01, view_id.bytes()));
            }
            (
                explore::ExploreAnalysisNodeIr::Mechanisms(_),
                CheckedExploreAnalysisIdentity::Mechanisms { request_id, .. },
            ) => {
                semantic_nodes.insert((0x02, request_id.bytes()));
            }
            _ => {
                return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(format!(
                    "analysis node {node_index} and identity have different kinds"
                )))
            }
        }
    }
    checked_query_hash_component(
        &mut hasher,
        "semantic-node-count",
        &semantic_nodes.len().to_string(),
    );
    for (kind, identity) in semantic_nodes {
        hasher.update([kind]);
        hasher.update(identity);
    }
    Ok(format!("{:x}", hasher.finalize()).into_boxed_str())
}

fn hash_checked_explore_starter_subject(
    hasher: &mut Sha256,
    subject: explore::ExploreStarterProjectionSubjectIr,
) {
    match subject {
        explore::ExploreStarterProjectionSubjectIr::Mechanism(mechanism_id) => {
            hasher.update([0x01]);
            hasher.update(mechanism_id.bytes());
        }
        explore::ExploreStarterProjectionSubjectIr::Node { facet, node_id } => {
            hasher.update([match facet {
                explore::ExploreStarterProjectionFacetIr::Activation => 0x02,
                explore::ExploreStarterProjectionFacetIr::DifferentialParticipation => 0x03,
            }]);
            hasher.update(node_id.bytes());
        }
        explore::ExploreStarterProjectionSubjectIr::Edge { facet, edge_id } => {
            hasher.update([match facet {
                explore::ExploreStarterProjectionFacetIr::Activation => 0x04,
                explore::ExploreStarterProjectionFacetIr::DifferentialParticipation => 0x05,
            }]);
            hasher.update(edge_id.bytes());
        }
    }
}

fn checked_explore_starter_projection_id(
    name: &str,
    request_id: explore::MechanismRequestId,
    subject: explore::ExploreStarterProjectionSubjectIr,
    within_mechanism: Option<explore::StructuralMechanismId>,
    authorizing_view_id: explore::ViewId,
) -> CheckedExploreStarterProjectionId {
    let mut hasher = Sha256::new();
    match within_mechanism {
        Some(_) => {
            hasher.update(b"futuruna.checked-explore-routed-starter-projection-id.v1\0");
            hasher.update(CHECKED_EXPLORE_ROUTED_STARTER_PROJECTION_ID_VERSION.to_le_bytes());
        }
        None => {
            hasher.update(b"futuruna.checked-explore-starter-projection-id.v1\0");
            hasher.update(CHECKED_EXPLORE_STARTER_PROJECTION_ID_VERSION.to_le_bytes());
        }
    }
    checked_query_hash_component(&mut hasher, "consumer-name", name);
    hasher.update(request_id.bytes());
    hash_checked_explore_starter_subject(&mut hasher, subject);
    if let Some(mechanism_id) = within_mechanism {
        hasher.update(mechanism_id.bytes());
    }
    hasher.update(authorizing_view_id.bytes());
    CheckedExploreStarterProjectionId(hasher.finalize().into())
}

fn checked_explore_starter_projection_identities(
    query: &explore::ExploreQueryIr,
    question_id: explore::QuestionId,
    analysis: &[CheckedExploreAnalysisIdentity],
) -> Result<
    (
        Box<[CheckedExploreStarterProjectionIdentity]>,
        CheckedExploreStarterConsumerSetId,
    ),
    CheckedExploreQueryArtifactIssue,
> {
    let mut identities = Vec::with_capacity(query.starter_projections.len());
    let mut canonical_set = BTreeSet::new();
    for projection in query.starter_projections.iter() {
        let request_id = match analysis.get(projection.request_node_index) {
            Some(CheckedExploreAnalysisIdentity::Mechanisms { request_id, .. }) => *request_id,
            _ => {
                return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(format!(
                    "starter projection `{}` does not resolve checked mechanism node index {}",
                    projection.name, projection.request_node_index
                )))
            }
        };
        let authorizing_view_id = match analysis.get(projection.value_view_node_index) {
            Some(CheckedExploreAnalysisIdentity::View { view_id }) => *view_id,
            _ => {
                return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(format!(
                    "starter projection `{}` does not resolve checked value-view node index {}",
                    projection.name, projection.value_view_node_index
                )))
            }
        };
        let id = checked_explore_starter_projection_id(
            &projection.name,
            request_id,
            projection.subject,
            projection.within_mechanism,
            authorizing_view_id,
        );
        canonical_set.insert(id);
        identities.push(CheckedExploreStarterProjectionIdentity {
            id,
            request_id,
            subject: projection.subject,
            within_mechanism: projection.within_mechanism,
            authorizing_view_id,
        });
    }

    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-starter-consumer-set-id.v1\0");
    hasher.update(CHECKED_EXPLORE_STARTER_CONSUMER_SET_ID_VERSION.to_le_bytes());
    hasher.update(question_id.bytes());
    hasher.update((canonical_set.len() as u64).to_le_bytes());
    for id in canonical_set {
        hasher.update(id.bytes());
    }
    Ok((
        identities.into_boxed_slice(),
        CheckedExploreStarterConsumerSetId(hasher.finalize().into()),
    ))
}

fn checked_explore_transition_graph_identities(
    query: &explore::ExploreQueryIr,
    question_id: explore::QuestionId,
    schemas: &explore::TransitionSchemaIdentities,
) -> (
    Box<[CheckedExploreTransitionGraphIdentity]>,
    CheckedExploreTransitionGraphConsumerSetId,
) {
    let mut identities = Vec::with_capacity(query.transition_graphs.len());
    let mut canonical_set = BTreeSet::new();
    for graph in query.transition_graphs.iter() {
        let mut hasher = Sha256::new();
        hasher.update(b"futuruna.checked-explore-transition-graph-id.v1\0");
        hasher.update(CHECKED_EXPLORE_TRANSITION_GRAPH_ID_VERSION.to_le_bytes());
        checked_query_hash_component(&mut hasher, "consumer-name", &graph.name);
        hasher.update(question_id.bytes());
        hasher.update(schemas.state_schema_id().bytes());
        hasher.update(schemas.context_schema_id().bytes());
        hasher.update(schemas.transition_type_id().bytes());
        let id = CheckedExploreTransitionGraphId(hasher.finalize().into());
        canonical_set.insert(id);
        identities.push(CheckedExploreTransitionGraphIdentity {
            id,
            question_id,
            state_schema_id: schemas.state_schema_id(),
            context_schema_id: schemas.context_schema_id(),
            transition_type_id: schemas.transition_type_id(),
        });
    }

    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-transition-graph-consumer-set-id.v1\0");
    hasher.update(CHECKED_EXPLORE_TRANSITION_GRAPH_CONSUMER_SET_ID_VERSION.to_le_bytes());
    hasher.update(question_id.bytes());
    hasher.update((canonical_set.len() as u64).to_le_bytes());
    for id in canonical_set {
        hasher.update(id.bytes());
    }
    (
        identities.into_boxed_slice(),
        CheckedExploreTransitionGraphConsumerSetId(hasher.finalize().into()),
    )
}

fn checked_explore_relation_id(
    resolutions: &CheckedResolutionArtifacts,
    query: &explore::ExploreQueryIr,
    semantic_closure_digest: [u8; 32],
) -> Result<explore::RelationId, CheckedExploreQueryArtifactIssue> {
    let mut hasher = Sha256::new();
    hasher.update(b"futuruna.checked-explore-relation.v5\0");
    hash_checked_explore_relation_ir(&mut hasher, resolutions, query, semantic_closure_digest)?;
    Ok(explore::RelationId::from_canonical_semantic_digest(
        hasher.finalize().into(),
    ))
}

fn checked_explore_identity_ladder(
    program: &CheckedAnalysisProgram,
    resolutions: &CheckedResolutionArtifacts,
    query: &explore::ExploreQueryIr,
    sites: &CheckedExploreQuerySites,
) -> Result<CheckedExploreIdentityLadder, CheckedExploreQueryArtifactIssue> {
    let index = CheckedExploreSemanticIndex::build(program);
    checked_explore_identity_ladder_with_index(program, resolutions, query, sites, &index)
}

fn checked_explore_identity_ladder_with_index(
    program: &CheckedAnalysisProgram,
    resolutions: &CheckedResolutionArtifacts,
    query: &explore::ExploreQueryIr,
    sites: &CheckedExploreQuerySites,
    index: &CheckedExploreSemanticIndex<'_>,
) -> Result<CheckedExploreIdentityLadder, CheckedExploreQueryArtifactIssue> {
    query
        .validate()
        .map_err(CheckedExploreQueryArtifactIssue::RelationalIr)?;
    if index.program.id != program.id || resolutions.analysis_program != program.id {
        return Err(CheckedExploreQueryArtifactIssue::AnalysisGraph(
            "semantic index or resolution artifacts belong to a different checked program".into(),
        ));
    }
    let semantic_binders = checked_explore_semantic_binders(query, sites)?;
    let relation_roots = sites
        .source_bindings
        .iter()
        .map(|binding| binding.expression.clone())
        .chain(std::iter::once(sites.successor.clone()))
        .collect::<Vec<_>>();
    let relation_types = query
        .source
        .bindings
        .iter()
        .map(|binding| binding.value_ty.clone())
        .chain([
            query.source.context_ty.clone(),
            query.source.before_ty.clone(),
            query.successor.after_ty.clone(),
        ])
        .collect::<Vec<_>>();
    let relation_seal =
        CheckedExploreSemanticClosure::new(index, resolutions, "relation", &semantic_binders)
            .seal(&relation_roots, &relation_types)?;
    let relation_id = checked_explore_relation_id(resolutions, query, relation_seal.digest)?;
    // Coverage describes only producer inputs of the finite FROM relation.
    // The successor is part of RelationId, but its literals/helpers construct
    // `after` and are not profile conditioning.
    let source_roots = sites
        .source_bindings
        .iter()
        .map(|binding| binding.expression.clone())
        .collect::<Vec<_>>();
    let conditioned_constructor_roots = query
        .source
        .bindings
        .iter()
        .zip(sites.source_bindings.iter())
        .filter_map(|(binding, sites)| {
            matches!(
                &binding.kind,
                explore::ExploreSourceBindingKindIr::Singleton { .. }
            )
            .then(|| sites.expression.clone())
        })
        .collect::<BTreeSet<_>>();
    let source_types = query
        .source
        .bindings
        .iter()
        .map(|binding| binding.value_ty.clone())
        .chain([
            query.source.context_ty.clone(),
            query.source.before_ty.clone(),
        ])
        .collect::<Vec<_>>();
    let source_seal = CheckedExploreSemanticClosure::new(
        index,
        resolutions,
        "source coverage",
        &semantic_binders,
    )
    .seal_source(&source_roots, &source_types, &conditioned_constructor_roots)?;
    let source_coverage = checked_explore_source_coverage_manifest(
        index,
        resolutions,
        &semantic_binders,
        query,
        sites,
        relation_id,
        &source_seal,
    )?;
    let source_projection_analysis = checked_explore_source_image_projection_analysis(
        resolutions,
        query,
        sites,
        relation_id,
        source_seal.digest,
    )?;
    let admission_seal = checked_explore_admission_semantic_seal(
        index,
        resolutions,
        &semantic_binders,
        query,
        sites,
    )?;
    let admission_id =
        explore::AdmissionId::from_canonical_admission_digest(relation_id, admission_seal.digest);
    let find_seal = checked_explore_find_semantic_seal(
        index,
        resolutions,
        &semantic_binders,
        &query.find,
        sites.selection.as_ref(),
    )?;
    let question_id = explore::QuestionId::from_canonical_find_digest(
        admission_id,
        find_seal.digest,
        query.find.polarity(),
    );
    let mut classifier_reachable_declarations = relation_seal.reachable_declarations;
    classifier_reachable_declarations.extend(admission_seal.reachable_declarations);
    classifier_reachable_declarations.extend(find_seal.reachable_declarations);
    let mut classifier_reachable_dependencies = relation_seal.reachable_dependencies;
    classifier_reachable_dependencies.extend(admission_seal.reachable_dependencies);
    classifier_reachable_dependencies.extend(find_seal.reachable_dependencies);
    let transition_schemas = explore::TransitionSchemaIdentities::derive_checked_relational(
        &query.source.before_ty,
        &query.source.context_ty,
        &resolutions.data_type_identities,
    )
    .map_err(|message| {
        CheckedExploreQueryArtifactIssue::RelationalIr(format!(
            "checked transition schema identity: {message}"
        ))
    })?;
    let analysis = checked_explore_analysis_identities(
        index,
        resolutions,
        &semantic_binders,
        query,
        sites,
        relation_id,
        question_id,
    )?;
    let product_rank_grouped_distinct = checked_explore_product_rank_grouped_distinct_certificates(
        resolutions,
        query,
        sites,
        &analysis,
        source_projection_analysis.as_ref(),
    )?;
    let source_image_projection = source_projection_analysis.map(|analysis| analysis.certificate);
    let analysis_graph_digest =
        checked_explore_analysis_graph_digest(query, question_id, &analysis)?;
    let (starter_projections, starter_consumer_set_id) =
        checked_explore_starter_projection_identities(query, question_id, &analysis)?;
    let (transition_graphs, transition_graph_consumer_set_id) =
        checked_explore_transition_graph_identities(query, question_id, &transition_schemas);
    Ok(CheckedExploreIdentityLadder {
        relation_id,
        admission_id,
        question_id,
        classifier_reachable_declarations: classifier_reachable_declarations
            .into_iter()
            .collect::<Vec<_>>()
            .into_boxed_slice(),
        classifier_reachable_dependencies: classifier_reachable_dependencies
            .into_iter()
            .collect::<Vec<_>>()
            .into_boxed_slice(),
        transition_schemas,
        analysis,
        analysis_graph_digest,
        starter_projections,
        starter_consumer_set_id,
        transition_graphs,
        transition_graph_consumer_set_id,
        source_coverage,
        source_image_projection,
        product_rank_grouped_distinct,
    })
}

fn build_checked_explore_query_artifacts(
    program: &CheckedAnalysisProgram,
    resolutions: &CheckedResolutionArtifacts,
    closed_queries: &[explore::ExploreQueryIr],
) -> Result<Vec<CheckedExploreQueryArtifact>, CheckedExploreQueryArtifactIssue> {
    let declarations = program
        .declarations
        .iter()
        .filter(|declaration| {
            matches!(&declaration.import_kind, SourcedImportKind::Root)
                && matches!(&*declaration.statement, Stmt::Explore(_))
        })
        .collect::<Vec<_>>();
    if declarations.len() != closed_queries.len() {
        return Err(
            CheckedExploreQueryArtifactIssue::AcceptedQueryCountMismatch {
                declarations: declarations.len(),
                closed_queries: closed_queries.len(),
            },
        );
    }
    let mut artifacts = Vec::with_capacity(closed_queries.len());
    for (closed_query_index, (declaration, closed_query)) in
        declarations.into_iter().zip(closed_queries).enumerate()
    {
        let Stmt::Explore(source_query) = &*declaration.statement else {
            unreachable!("filtered Explore declaration")
        };
        let sites = checked_explore_query_sites(program, declaration, source_query);
        if let Some(missing) = checked_explore_site_roots(&sites)
            .into_iter()
            .find(|site| !resolutions.expressions.contains_key(*site))
        {
            return Err(CheckedExploreQueryArtifactIssue::QuerySiteMissing(
                missing.clone(),
            ));
        }
        let ladder = checked_explore_identity_ladder(program, resolutions, closed_query, &sites)?;
        let classification =
            checked_explore_classification::checked_explore_classification_program(
                program,
                resolutions,
                closed_query,
                &sites,
                ladder.question_id,
            )
            .map_err(|error| {
                CheckedExploreQueryArtifactIssue::ClassificationProgram(
                    error.to_string().into_boxed_str(),
                )
            })?;
        artifacts.push(CheckedExploreQueryArtifact {
            identity: CheckedExploreQueryId {
                analysis_program: program.id.clone(),
                declaration: CheckedDeclarationOccurrenceId::from_sourced(declaration),
            },
            relation_id: ladder.relation_id,
            admission_id: ladder.admission_id,
            question_id: ladder.question_id,
            classification_program: Arc::new(classification.program),
            classification_runtime_shapes: Arc::new(classification.runtime_shapes),
            classifier_reachable_declarations: ladder.classifier_reachable_declarations,
            classifier_reachable_dependencies: ladder.classifier_reachable_dependencies,
            transition_schemas: ladder.transition_schemas,
            analysis: ladder.analysis,
            analysis_graph_digest: ladder.analysis_graph_digest,
            starter_projections: ladder.starter_projections,
            starter_consumer_set_id: ladder.starter_consumer_set_id,
            transition_graphs: ladder.transition_graphs,
            transition_graph_consumer_set_id: ladder.transition_graph_consumer_set_id,
            source_coverage: ladder.source_coverage,
            source_image_projection: ladder.source_image_projection,
            product_rank_grouped_distinct: ladder.product_rank_grouped_distinct,
            sites,
            closed_query_index,
        });
    }
    Ok(artifacts)
}

#[derive(Debug, Clone)]
struct CheckedLocalBinding {
    kind: CheckedBinderKind,
    site: CheckedBinderSiteId,
    type_name: Option<String>,
}

/// Private marker carried only in the recorder's local type overlay. Source
/// syntax cannot contain NUL, so this can never alias a user-authored type.
/// Keeping the tombstone in the map is important: removing an untyped inner
/// binder would let `infer_expr_type_name_with_locals` fall back to a typed
/// top-level binding with the same spelling.
const CHECKED_UNTYPED_SHADOW_TYPE_TOMBSTONE: &str = "\0futuruna-checked-untyped-shadow";

#[derive(Debug, Clone)]
struct IndexedConstructor {
    identity: CheckedConstructorIdentity,
}

enum ExactConstructorSignature {
    NoMatch,
    Unique(TypeConstructorSignature),
    Ambiguous,
}

struct PendingCheckedRule<'a> {
    rule: &'a Rule,
    declaration: &'a SourcedStmt,
    statement_path: Vec<u32>,
}

struct CheckedResolutionRecorder<'a> {
    checker: &'a TypeChecker,
    program: &'a CheckedAnalysisProgram,
    artifacts: CheckedResolutionArtifacts,
    scopes: Vec<BTreeMap<String, CheckedLocalBinding>>,
    top_level_bindings: BTreeMap<String, Vec<CheckedTopLevelBindingId>>,
    callables: BTreeMap<(Option<String>, String, usize), Vec<CheckedCallableId>>,
    callable_arities: BTreeMap<CheckedCallableId, usize>,
    bare_runtime_callables_by_name: BTreeMap<String, Vec<CheckedCallableId>>,
    rule_families_by_scope_and_name: BTreeMap<(Option<String>, String), Vec<RuleDispatchKey>>,
    constructors: BTreeMap<(String, String), Vec<IndexedConstructor>>,
    data_fields: BTreeMap<(String, String), Vec<CheckedVariantField>>,
    data_owner_declarations: BTreeMap<String, BTreeSet<CheckedModelOwnerKey>>,
    active_rule_scope_owners: BTreeMap<String, CheckedModelOwnerKey>,
    qualified_aliases: BTreeMap<String, CheckedDeclarationOccurrenceId>,
    pending_rules: BTreeMap<RuleDispatchKey, Vec<PendingCheckedRule<'a>>>,
    duplicate_rule_scope_owners: BTreeSet<String>,
    active_rule_scope: Option<String>,
}

impl<'a> CheckedResolutionRecorder<'a> {
    const BINDER_PARAMETER: u32 = 0;
    const BINDER_PATTERN: u32 = 1;
    const BINDER_FOR: u32 = 2;
    const BINDER_EXPLORE: u32 = 3;
    const BINDER_HANDLER: u32 = 4;
    const BINDER_CAPTURE: u32 = 5;
    const BINDER_EXPLORE_RESULT: u32 = 6;
    const BINDER_EXPLORE_ROLE: u32 = 7;
    const BINDER_EXPLORE_OBSERVATION_STATE: u32 = 8;
    const BINDER_EXPLORE_RESULT_INPUT: u32 = 9;
    const EXPLORE_RESULT_GROUP: u32 = 0;
    const EXPLORE_RESULT_MEASURE: u32 = 1;
    const EXPLORE_RESULT_AGGREGATE: u32 = 2;
    const EXPLORE_RESULT_SELECT: u32 = 3;

    fn record(checker: &'a TypeChecker) -> CheckedResolutionArtifacts {
        let program = &checker.analysis_program;
        let expression_site_scope = Arc::new(CheckedExpressionSiteScope::from_program(program));
        let mut active_rule_scope_owners = BTreeMap::new();
        let mut rule_scope_owner_counts = BTreeMap::<String, usize>::new();
        for declaration in program.declarations.iter() {
            if let Stmt::TypeDecl(TypeDecl::RuleScope { name, .. }) = &*declaration.statement {
                active_rule_scope_owners.insert(name.clone(), Self::model_owner(declaration));
                *rule_scope_owner_counts.entry(name.clone()).or_default() += 1;
            }
        }
        let duplicate_rule_scope_owners = rule_scope_owner_counts
            .into_iter()
            .filter_map(|(name, count)| (count > 1).then_some(name))
            .collect();
        let mut recorder = Self {
            checker,
            program,
            artifacts: CheckedResolutionArtifacts {
                analysis_program: program.id.clone(),
                source_snapshot_coherent: checker.checked_resolution_source_snapshot_coherent,
                expressions: CheckedExpressionSiteMap::with_scope(Arc::clone(
                    &expression_site_scope,
                )),
                unsupported_sites: CheckedExpressionSiteMap::with_scope(expression_site_scope),
                rule_dispatch_boolean_miss_safe_keys: checker
                    .rule_dispatch_boolean_miss_safe_keys
                    .clone(),
                ..CheckedResolutionArtifacts::default()
            },
            scopes: vec![BTreeMap::new()],
            top_level_bindings: BTreeMap::new(),
            callables: BTreeMap::new(),
            callable_arities: BTreeMap::new(),
            bare_runtime_callables_by_name: BTreeMap::new(),
            rule_families_by_scope_and_name: BTreeMap::new(),
            constructors: BTreeMap::new(),
            data_fields: BTreeMap::new(),
            data_owner_declarations: BTreeMap::new(),
            active_rule_scope_owners,
            qualified_aliases: BTreeMap::new(),
            pending_rules: BTreeMap::new(),
            duplicate_rule_scope_owners,
            active_rule_scope: None,
        };
        recorder.index_program();
        recorder.freeze_constructor_identities();
        recorder.freeze_rule_families();
        recorder.freeze_value_lookup_indexes();
        for declaration in program.declarations.iter() {
            recorder.record_declaration(declaration);
        }
        recorder.artifacts
    }

    fn occurrence(declaration: &SourcedStmt) -> CheckedDeclarationOccurrenceId {
        CheckedDeclarationOccurrenceId::from_sourced(declaration)
    }

    fn model_owner(declaration: &SourcedStmt) -> CheckedModelOwnerKey {
        declaration
            .model_owner
            .clone()
            .expect("nominal type/namespace declaration has a model owner")
    }

    fn bridge_data_owner(
        &mut self,
        owner: &CheckedModelOwnerKey,
        occurrence: &CheckedDeclarationOccurrenceId,
    ) {
        if let Some(previous) = self
            .artifacts
            .data_owner_to_analysis_occurrence
            .insert(owner.clone(), occurrence.clone())
        {
            assert_eq!(
                &previous, occurrence,
                "one stable data owner cannot bridge to conflicting analysis occurrences"
            );
        }
        if let Some(previous) = self
            .artifacts
            .analysis_occurrence_to_data_owner
            .insert(occurrence.clone(), owner.clone())
        {
            assert_eq!(
                &previous, owner,
                "one analysis occurrence cannot bridge to conflicting stable data owners"
            );
        }
    }

    fn expression_site(&self, declaration: &SourcedStmt, path: &[u32]) -> ExprSiteId {
        self.program.expression_site(declaration, path.to_vec())
    }

    fn structural_binder_site(
        &self,
        declaration: &SourcedStmt,
        ast_path: &[u32],
        binder_path: Vec<u32>,
    ) -> CheckedBinderSiteId {
        CheckedBinderSiteId::Structural {
            analysis_program: self.program.id.clone(),
            declaration: declaration.id.clone(),
            normalized_declaration_ordinal: declaration.normalized_ordinal,
            ast_path: ast_path.to_vec().into_boxed_slice(),
            binder_path: binder_path.into_boxed_slice(),
        }
    }

    fn pattern_site(
        &self,
        declaration: &SourcedStmt,
        ast_path: &[u32],
        pattern_path: &[u32],
    ) -> CheckedPatternSiteId {
        CheckedPatternSiteId {
            analysis_program: self.program.id.clone(),
            declaration: declaration.id.clone(),
            normalized_declaration_ordinal: declaration.normalized_ordinal,
            ast_path: ast_path.to_vec().into_boxed_slice(),
            pattern_path: pattern_path.to_vec().into_boxed_slice(),
        }
    }

    fn issue(&mut self, site: &ExprSiteId, issue: CheckedResolutionIssue) {
        if let Some(issues) = self.artifacts.unsupported_sites.get_mut(site) {
            issues.insert(issue);
        } else {
            self.artifacts
                .unsupported_sites
                .insert(site.clone(), BTreeSet::from([issue]));
        }
    }

    fn path_child(path: &[u32], child: usize) -> Vec<u32> {
        let mut result = path.to_vec();
        result.push(child as u32);
        result
    }

    fn intrinsic_data_type_id(name: &str) -> CheckedDataTypeId {
        CheckedDataTypeId::Intrinsic {
            canonical_name: name.to_string().into_boxed_str(),
        }
    }

    fn intrinsic_constructor_identity(
        owner_type: &str,
        variant: &str,
    ) -> Option<CheckedConstructorIdentity> {
        let (variant_index, layout, field_names): (usize, CheckedConstructorLayout, &[&str]) =
            match (owner_type, variant) {
                ("Option", "None") => (0, CheckedConstructorLayout::Positional, &[]),
                ("Option", "Some") => (1, CheckedConstructorLayout::Positional, &["_0"]),
                ("Result", "Ok") => (0, CheckedConstructorLayout::Positional, &["_0"]),
                ("Result", "Err") => (1, CheckedConstructorLayout::Positional, &["_0"]),
                ("Pair", "Pair") => (0, CheckedConstructorLayout::Named, &["fst", "snd"]),
                ("Bool", "True") => (0, CheckedConstructorLayout::Positional, &[]),
                ("Bool", "False") => (1, CheckedConstructorLayout::Positional, &[]),
                _ => return None,
            };
        let owner = Self::intrinsic_data_type_id(owner_type);
        let fields = field_names
            .iter()
            .enumerate()
            .map(|(field_index, name)| CheckedDataFieldId {
                owner: owner.clone(),
                variant_index,
                field_index,
                name: (*name).to_string().into_boxed_str(),
            })
            .collect::<Vec<_>>()
            .into_boxed_slice();
        Some(CheckedConstructorIdentity {
            owner,
            owner_type: owner_type.to_string().into_boxed_str(),
            variant: variant.to_string().into_boxed_str(),
            variant_index,
            layout,
            fields,
        })
    }

    fn freeze_constructor_identities(&mut self) {
        for (owner, declarations) in &self.data_owner_declarations {
            if declarations.len() != 1 || self.duplicate_rule_scope_owners.contains(owner) {
                self.artifacts.data_type_identities.remove(owner.as_str());
            }
        }

        for ((owner, variant), constructors) in &self.constructors {
            let owner_is_unique = self
                .data_owner_declarations
                .get(owner)
                .is_some_and(|declarations| declarations.len() == 1)
                && !self.duplicate_rule_scope_owners.contains(owner);
            if !owner_is_unique {
                continue;
            }
            if let [constructor] = constructors.as_slice() {
                self.artifacts.constructor_identities.insert(
                    (
                        owner.clone().into_boxed_str(),
                        variant.clone().into_boxed_str(),
                    ),
                    Arc::new(constructor.identity.clone()),
                );
            }
        }
        for (owner, variant) in [
            ("Option", "None"),
            ("Option", "Some"),
            ("Result", "Ok"),
            ("Result", "Err"),
            ("Pair", "Pair"),
            ("Bool", "True"),
            ("Bool", "False"),
        ] {
            if self.data_owner_declarations.contains_key(owner)
                || self
                    .constructors
                    .contains_key(&(owner.to_string(), variant.to_string()))
            {
                continue;
            }
            let identity = Self::intrinsic_constructor_identity(owner, variant)
                .expect("closed intrinsic constructor table");
            for field in identity.fields.iter().cloned() {
                self.data_fields
                    .entry((owner.to_string(), field.name.to_string()))
                    .or_default()
                    .push(CheckedVariantField {
                        variant: variant.into(),
                        variant_index: identity.variant_index,
                        field_index: field.field_index,
                        layout: identity.layout,
                        identity: field,
                    });
            }
            self.artifacts
                .constructor_identities
                .insert((owner.into(), variant.into()), Arc::new(identity));
            self.artifacts
                .data_type_identities
                .entry(owner.into())
                .or_insert_with(|| Self::intrinsic_data_type_id(owner));
        }
        for intrinsic in [
            "Int",
            "Nat",
            "Float",
            "String",
            "Bool",
            "Char",
            "List",
            "Tuple",
            "Unit",
            "Option",
            "Result",
            "Pair",
            "Stream",
            "Subject",
            "Db",
            "TypeDef",
            "Set",
            "Map",
            "CaseId",
            "TransitionId",
            "MechanismSignatureId",
            "StructuralMechanismId",
            "ExecutionProfileId",
        ] {
            if self.data_owner_declarations.contains_key(intrinsic) {
                continue;
            }
            self.artifacts
                .data_type_identities
                .entry(intrinsic.into())
                .or_insert_with(|| Self::intrinsic_data_type_id(intrinsic));
        }
    }

    fn index_program(&mut self) {
        let program = self.program;
        for declaration in program.declarations.iter() {
            let occurrence = Self::occurrence(declaration);
            match &*declaration.statement {
                Stmt::QualifiedImport(alias, _) => {
                    self.qualified_aliases
                        .insert(alias.clone(), occurrence.clone());
                    self.artifacts.opaque_qualified_owners.insert(
                        occurrence.clone(),
                        CheckedOpaqueQualifiedOwner {
                            declaration: occurrence,
                            target_module: declaration.qualified_target_module.clone(),
                        },
                    );
                }
                Stmt::Defn(Defn::Fn { name, params, .. }) => {
                    self.callables
                        .entry((None, name.clone(), params.len()))
                        .or_default()
                        .push(CheckedCallableId {
                            declaration: occurrence,
                            structural_path: Box::new([]),
                        });
                }
                Stmt::Defn(Defn::Module { name, .. }) => {
                    self.qualified_aliases
                        .insert(name.clone(), occurrence.clone());
                    self.artifacts.opaque_qualified_owners.insert(
                        occurrence.clone(),
                        CheckedOpaqueQualifiedOwner {
                            declaration: occurrence,
                            target_module: None,
                        },
                    );
                }
                Stmt::TypeDecl(TypeDecl::ADT {
                    name,
                    variants,
                    methods,
                    ..
                }) => {
                    let model_owner = Self::model_owner(declaration);
                    self.bridge_data_owner(&model_owner, &occurrence);
                    let owner = CheckedDataTypeId::Declared(model_owner.clone());
                    self.data_owner_declarations
                        .entry(name.clone())
                        .or_default()
                        .insert(model_owner);
                    self.artifacts
                        .data_type_identities
                        .insert(name.clone().into_boxed_str(), owner.clone());
                    for (variant_index, variant) in variants.iter().enumerate() {
                        let layout = if variant.positional || variant.fields.is_empty() {
                            CheckedConstructorLayout::Positional
                        } else {
                            CheckedConstructorLayout::Named
                        };
                        let exact_fields = variant
                            .fields
                            .iter()
                            .enumerate()
                            .map(|(field_index, field)| CheckedDataFieldId {
                                owner: owner.clone(),
                                variant_index,
                                field_index,
                                name: field.name.clone().into_boxed_str(),
                            })
                            .collect::<Vec<_>>();
                        let identity = CheckedConstructorIdentity {
                            owner: owner.clone(),
                            owner_type: name.clone().into_boxed_str(),
                            variant: variant.name.clone().into_boxed_str(),
                            variant_index,
                            layout,
                            fields: exact_fields.clone().into_boxed_slice(),
                        };
                        self.constructors
                            .entry((name.clone(), variant.name.clone()))
                            .or_default()
                            .push(IndexedConstructor { identity });
                        for (field, identity) in variant.fields.iter().zip(exact_fields) {
                            self.data_fields
                                .entry((name.clone(), field.name.clone()))
                                .or_default()
                                .push(CheckedVariantField {
                                    variant: variant.name.clone().into_boxed_str(),
                                    variant_index,
                                    field_index: identity.field_index,
                                    layout,
                                    identity,
                                });
                        }
                    }
                    let mut child_index = 0;
                    for method in methods {
                        match method {
                            Defn::Fn {
                                name: method,
                                params,
                                ..
                            } => {
                                self.callables
                                    .entry((Some(name.clone()), method.clone(), params.len()))
                                    .or_default()
                                    .push(CheckedCallableId {
                                        declaration: occurrence.clone(),
                                        structural_path: vec![child_index].into_boxed_slice(),
                                    });
                                child_index += 1;
                            }
                            Defn::Actor { handlers, .. } => {
                                child_index += handlers.len() as u32;
                            }
                            Defn::Module { body, .. } => {
                                child_index += body.len() as u32;
                            }
                        }
                    }
                }
                Stmt::TypeDecl(TypeDecl::ImplBlock {
                    for_type, methods, ..
                }) => {
                    let mut child_index = 0;
                    for method in methods {
                        match method {
                            Defn::Fn { name, params, .. } => {
                                self.callables
                                    .entry((Some(for_type.clone()), name.clone(), params.len()))
                                    .or_default()
                                    .push(CheckedCallableId {
                                        declaration: occurrence.clone(),
                                        structural_path: vec![child_index].into_boxed_slice(),
                                    });
                                child_index += 1;
                            }
                            Defn::Actor { handlers, .. } => {
                                child_index += handlers.len() as u32;
                            }
                            Defn::Module { body, .. } => {
                                child_index += body.len() as u32;
                            }
                        }
                    }
                }
                Stmt::TypeDecl(TypeDecl::RuleScope {
                    name, params, body, ..
                }) => {
                    let model_owner = Self::model_owner(declaration);
                    if self.active_rule_scope_owners.get(name) != Some(&model_owner) {
                        continue;
                    }
                    self.bridge_data_owner(&model_owner, &occurrence);
                    self.data_owner_declarations
                        .entry(name.clone())
                        .or_default()
                        .insert(model_owner.clone());
                    let owner = CheckedDataTypeId::Declared(model_owner);
                    self.artifacts
                        .data_type_identities
                        .insert(name.clone().into_boxed_str(), owner.clone());
                    let exact_fields = params
                        .iter()
                        .enumerate()
                        .map(|(field_index, parameter)| CheckedDataFieldId {
                            owner: owner.clone(),
                            variant_index: 0,
                            field_index,
                            name: parameter.name.clone().into_boxed_str(),
                        })
                        .collect::<Vec<_>>();
                    self.constructors
                        .entry((name.clone(), name.clone()))
                        .or_default()
                        .push(IndexedConstructor {
                            identity: CheckedConstructorIdentity {
                                owner,
                                owner_type: name.clone().into_boxed_str(),
                                variant: name.clone().into_boxed_str(),
                                variant_index: 0,
                                layout: CheckedConstructorLayout::Named,
                                fields: exact_fields.clone().into_boxed_slice(),
                            },
                        });
                    for (parameter, identity) in params.iter().zip(exact_fields) {
                        self.data_fields
                            .entry((name.clone(), parameter.name.clone()))
                            .or_default()
                            .push(CheckedVariantField {
                                variant: name.clone().into_boxed_str(),
                                variant_index: 0,
                                field_index: identity.field_index,
                                layout: CheckedConstructorLayout::Named,
                                identity,
                            });
                    }
                    for (statement_index, statement) in body.iter().enumerate() {
                        let statement_path = vec![statement_index as u32];
                        match statement {
                            Stmt::Rule(rule) => self.index_rule(
                                declaration,
                                rule,
                                statement_path,
                                Some(name.clone()),
                            ),
                            Stmt::Defn(Defn::Fn {
                                name: member,
                                params,
                                ..
                            }) => {
                                let effective_arity = params
                                    .iter()
                                    .filter(|parameter| parameter.name.as_str() != "self")
                                    .count();
                                self.callables
                                    .entry((Some(name.clone()), member.clone(), effective_arity))
                                    .or_default()
                                    .push(CheckedCallableId {
                                        declaration: occurrence.clone(),
                                        structural_path: statement_path.into_boxed_slice(),
                                    });
                            }
                            _ => {}
                        }
                    }
                }
                Stmt::Rule(rule) => self.index_rule(declaration, rule, Vec::new(), None),
                Stmt::Bind(pattern, _, _) | Stmt::MonadicBind(pattern, _, _) => {
                    self.index_top_level_pattern(declaration, pattern, Vec::new());
                }
                Stmt::StreamBind(name, _) => {
                    self.top_level_bindings
                        .entry(name.clone())
                        .or_default()
                        .push(CheckedTopLevelBindingId {
                            declaration: occurrence,
                            binder_path: vec![Self::BINDER_PATTERN, 0].into_boxed_slice(),
                        });
                }
                _ => {}
            }
        }
    }

    fn index_top_level_pattern(
        &mut self,
        declaration: &SourcedStmt,
        pattern: &Pat,
        path: Vec<u32>,
    ) {
        match pattern {
            Pat::Var(name) => {
                let mut binder_path = vec![Self::BINDER_PATTERN];
                binder_path.extend(path);
                self.top_level_bindings
                    .entry(name.clone())
                    .or_default()
                    .push(CheckedTopLevelBindingId {
                        declaration: Self::occurrence(declaration),
                        binder_path: binder_path.into_boxed_slice(),
                    });
            }
            Pat::Con(_, patterns) => {
                for (index, pattern) in patterns.iter().enumerate() {
                    let mut child = path.clone();
                    child.push(index as u32);
                    self.index_top_level_pattern(declaration, pattern, child);
                }
            }
            Pat::NamedCon(_, fields) => {
                for (index, (_, pattern)) in fields.iter().enumerate() {
                    let mut child = path.clone();
                    child.push(index as u32);
                    self.index_top_level_pattern(declaration, pattern, child);
                }
            }
            Pat::As(pattern, name) => {
                self.index_top_level_pattern(declaration, pattern, path.clone());
                let mut binder_path = vec![Self::BINDER_PATTERN];
                binder_path.extend(path);
                binder_path.push(u32::MAX);
                self.top_level_bindings
                    .entry(name.clone())
                    .or_default()
                    .push(CheckedTopLevelBindingId {
                        declaration: Self::occurrence(declaration),
                        binder_path: binder_path.into_boxed_slice(),
                    });
            }
            Pat::Wild | Pat::Lit(_) => {}
        }
    }

    fn index_rule(
        &mut self,
        declaration: &'a SourcedStmt,
        rule: &'a Rule,
        statement_path: Vec<u32>,
        scope: Option<String>,
    ) {
        let Some((name, arity)) = rule.callable_name_arity() else {
            return;
        };
        let key = RuleDispatchKey { scope, name, arity };
        self.pending_rules
            .entry(key)
            .or_default()
            .push(PendingCheckedRule {
                rule,
                declaration,
                statement_path,
            });
    }

    fn freeze_rule_families(&mut self) {
        let pending = std::mem::take(&mut self.pending_rules);
        for (key, rules) in pending {
            let plan = RuleDispatchPlan::from_rules(rules.iter().map(|candidate| candidate.rule));
            let candidates = plan
                .candidates()
                .filter_map(|candidate| {
                    let pending = rules.get(candidate.source_order)?;
                    let tier = pending.rule.dispatch_tier()?;
                    let head_path = Self::path_child(&pending.statement_path, 0);
                    let value_path = match pending.rule {
                        Rule::Clause { body: Some(_), .. }
                        | Rule::Default { .. }
                        | Rule::Exception { .. } => {
                            Some(Self::path_child(&pending.statement_path, 1))
                        }
                        Rule::Clause { body: None, .. } | Rule::ReactiveScope { .. } => None,
                    };
                    let condition_path = match pending.rule {
                        Rule::Default {
                            condition: Some(_), ..
                        }
                        | Rule::Exception {
                            condition: Some(_), ..
                        } => Some(Self::path_child(&pending.statement_path, 2)),
                        _ => None,
                    };
                    Some(CheckedRuleCandidateResolution {
                        tier,
                        source_order: candidate.source_order,
                        declaration: Self::occurrence(pending.declaration),
                        statement_path: pending.statement_path.clone().into_boxed_slice(),
                        head_site: self.expression_site(pending.declaration, &head_path),
                        condition_site: condition_path
                            .as_ref()
                            .map(|path| self.expression_site(pending.declaration, path)),
                        value_site: value_path
                            .as_ref()
                            .map(|path| self.expression_site(pending.declaration, path)),
                    })
                })
                .collect::<Vec<_>>()
                .into_boxed_slice();
            self.artifacts
                .rule_families
                .insert(key.clone(), CheckedRuleFamilyResolution { key, candidates });
        }
    }

    fn freeze_value_lookup_indexes(&mut self) {
        for ((scope, name, arity), callables) in &self.callables {
            for callable in callables {
                self.callable_arities.insert(callable.clone(), *arity);
                if scope.is_none()
                    || matches!(
                        callable.declaration.declaration.kind,
                        DeclarationKind::Adt | DeclarationKind::Implementation
                    )
                {
                    self.bare_runtime_callables_by_name
                        .entry(name.clone())
                        .or_default()
                        .push(callable.clone());
                }
            }
        }
        for callables in self.bare_runtime_callables_by_name.values_mut() {
            callables.sort_by(|left, right| {
                left.declaration
                    .normalized_ordinal
                    .cmp(&right.declaration.normalized_ordinal)
                    .then_with(|| left.structural_path.cmp(&right.structural_path))
            });
            callables.dedup();
        }

        for key in self.artifacts.rule_families.keys() {
            self.rule_families_by_scope_and_name
                .entry((key.scope.clone(), key.name.clone()))
                .or_default()
                .push(key.clone());
        }
        for families in self.rule_families_by_scope_and_name.values_mut() {
            families.sort_by_key(|key| key.arity);
            families.dedup();
        }
    }

    fn push_scope(&mut self) {
        self.scopes.push(BTreeMap::new());
    }

    fn pop_scope(&mut self) {
        self.scopes.pop();
    }

    fn define_local(&mut self, name: String, binding: CheckedLocalBinding) {
        self.scopes
            .last_mut()
            .expect("checked resolution always has a lexical scope")
            .insert(name, binding);
    }

    fn local(&self, name: &str) -> Option<CheckedLocalBinding> {
        self.scopes
            .iter()
            .rev()
            .find_map(|scope| scope.get(name).cloned())
    }

    fn bound_callable_target(
        binding: &CheckedLocalBinding,
        arity: usize,
    ) -> Option<CheckedCallTarget> {
        if arity != 1 {
            return None;
        }
        let ty = parse_type_annotation(binding.type_name.as_deref()?).ok()?;
        let Ty::Arrow(parameter, result) = ty else {
            return None;
        };
        Some(CheckedCallTarget::BoundCallable {
            binder: binding.site.clone(),
            parameter_type: TypeChecker::canonical_explore_ty_name(&parameter).into_boxed_str(),
            result_type: TypeChecker::canonical_explore_ty_name(&result).into_boxed_str(),
            arity,
        })
    }

    fn type_locals(&self) -> BTreeMap<String, String> {
        let mut locals = BTreeMap::new();
        for scope in &self.scopes {
            for (name, binding) in scope {
                match &binding.type_name {
                    Some(type_name) => {
                        locals.insert(name.clone(), type_name.clone());
                    }
                    None => {
                        // An untyped inner binder is still a lexical shadow. It
                        // must mask, rather than merely erase, an outer/global
                        // type fact. The inference seam recognizes this private
                        // marker and refuses its own global fallback.
                        locals.insert(
                            name.clone(),
                            CHECKED_UNTYPED_SHADOW_TYPE_TOMBSTONE.to_string(),
                        );
                    }
                }
            }
        }
        locals
    }

    fn infer_expr_type_name_in_active_scope(
        &self,
        expression: &Expr,
        locals: &BTreeMap<String, String>,
    ) -> Option<String> {
        self.checker.infer_expr_type_name_with_locals_in_scope(
            expression,
            locals,
            self.active_rule_scope.as_deref(),
        )
    }

    fn inferred_collection_element_type(
        &self,
        expression: &Expr,
        locals: &BTreeMap<String, String>,
    ) -> Option<Ty> {
        let collection_type = self.infer_expr_type_name_in_active_scope(expression, locals)?;
        ["List", "Stream", "Subject"]
            .into_iter()
            .find_map(|constructor| {
                TypeChecker::applied_type_argument(&collection_type, constructor, 0)
            })
            .and_then(|element_type| parse_type_annotation(&element_type).ok())
    }

    fn source_callback_parameter_type(
        &self,
        callback: &Expr,
        arity: usize,
        parameter_index: usize,
    ) -> Option<Ty> {
        match &callback.kind {
            ExprKind::Lambda(parameters, _) if parameters.len() == arity => parameters
                .get(parameter_index)
                .and_then(|parameter| parameter.ty.as_ref())
                .filter(|ty| !matches!(ty, Ty::Hole))
                .cloned(),
            ExprKind::Var(name) => self
                .checker
                .explore_function_definitions_by_arity
                .get(&(name.clone(), arity))
                .and_then(|definitions| match definitions.as_slice() {
                    [(parameters, _, _)] => parameters
                        .get(parameter_index)
                        .and_then(|parameter| parameter.ty.as_ref())
                        .filter(|ty| !matches!(ty, Ty::Hole))
                        .cloned(),
                    _ => None,
                })
                .or_else(|| {
                    self.checker
                        .rule_param_types_by_arity
                        .get(&(name.clone(), arity))
                        .and_then(|parameters| parameters.get(parameter_index))
                        .and_then(Option::clone)
                }),
            _ => None,
        }
    }

    /// Infer only the parameter types supplied exactly by a checked
    /// higher-order builtin's calling convention. This is bidirectional type
    /// propagation, not body guessing: the collection fixes its item type and
    /// `foldl`'s initializer fixes its accumulator type.
    fn contextual_builtin_lambda_parameters(
        &self,
        target: Option<&CheckedCallTarget>,
        arguments: &[Expr],
    ) -> Option<(usize, Box<[Ty]>)> {
        let Some(CheckedCallTarget::Builtin { canonical_name, .. }) = target else {
            return None;
        };
        let locals = self.type_locals();
        match (canonical_name.as_ref(), arguments) {
            (
                "map" | "filter" | "sort_by" | "any" | "all" | "find" | "flat_map" | "take_while"
                | "drop_while" | "count_by" | "partition" | "subscribe",
                [collection, _],
            ) => {
                let item_type = self.inferred_collection_element_type(collection, &locals)?;
                Some((1, vec![item_type].into_boxed_slice()))
            }
            ("foldl" | "scan" | "reduce", [collection, initial, callback]) => {
                let accumulator_type = self
                    .infer_expr_type_name_in_active_scope(initial, &locals)
                    .and_then(|type_name| parse_type_annotation(&type_name).ok())
                    .or_else(|| {
                        TypeChecker::is_polymorphic_empty_list_expr(initial)
                            .then(|| self.source_callback_parameter_type(callback, 2, 0))
                            .flatten()
                    })?;
                let item_type = self.inferred_collection_element_type(collection, &locals)?;
                Some((2, vec![accumulator_type, item_type].into_boxed_slice()))
            }
            _ => None,
        }
    }

    fn contextual_builtin_callback_arity(
        target: Option<&CheckedCallTarget>,
        argument_count: usize,
    ) -> Option<(usize, usize)> {
        let target = target?;
        let CheckedCallTarget::Builtin { arity, .. } = target else {
            return None;
        };
        if *arity != argument_count {
            return None;
        }
        checked_interpreter_mechanism_builtin_callback_contract(target)
    }

    fn contextual_builtin_callback_result_type(
        &self,
        target: Option<&CheckedCallTarget>,
        arguments: &[Expr],
    ) -> Option<(usize, Ty)> {
        let Some(CheckedCallTarget::Builtin { canonical_name, .. }) = target else {
            return None;
        };
        match (canonical_name.as_ref(), arguments) {
            (
                "filter" | "any" | "all" | "find" | "take_while" | "drop_while" | "count_by"
                | "partition",
                [_, _],
            ) => Some((1, Ty::Name("Bool".to_string()))),
            ("foldl" | "scan" | "reduce", [_, initial, callback]) => self
                .infer_expr_type_name_in_active_scope(initial, &self.type_locals())
                .and_then(|type_name| parse_type_annotation(&type_name).ok())
                .or_else(|| {
                    TypeChecker::is_polymorphic_empty_list_expr(initial)
                        .then(|| self.source_callback_parameter_type(callback, 2, 0))
                        .flatten()
                })
                .map(|result_type| (2, result_type)),
            _ => None,
        }
    }

    fn checked_callback_signature(
        &self,
        resolution: &CheckedExpressionResolution,
    ) -> Option<(Box<[Ty]>, Ty)> {
        match (&resolution.value_binding, &resolution.resolved_type) {
            (_, CheckedExpressionType::Callable { parameters, result }) => {
                Some((parameters.clone(), result.as_ref().clone()))
            }
            (
                Some(CheckedValueBinding::Binder { .. }),
                CheckedExpressionType::Resolved(Ty::Arrow(parameter, result)),
            ) => Some((
                vec![parameter.as_ref().clone()].into_boxed_slice(),
                result.as_ref().clone(),
            )),
            (Some(CheckedValueBinding::Callable(callable)), _) => {
                let arity = self.callable_arities.get(callable).copied()?;
                if callable.declaration.declaration.kind != DeclarationKind::Function {
                    return None;
                }
                let name = callable.declaration.declaration.name.to_string();
                let definitions = self
                    .checker
                    .explore_function_definitions_by_arity
                    .get(&(name.clone(), arity))?;
                let [(parameters, _, _)] = definitions.as_slice() else {
                    return None;
                };
                let parameter_types = parameters
                    .iter()
                    .map(|parameter| {
                        parameter
                            .ty
                            .as_ref()
                            .filter(|ty| !matches!(ty, Ty::Hole))
                            .cloned()
                    })
                    .collect::<Option<Vec<_>>>()?
                    .into_boxed_slice();
                let result_type = self
                    .checker
                    .explore_function_return_types_by_arity
                    .get(&(name, arity))?
                    .clone();
                Some((parameter_types, result_type))
            }
            (Some(CheckedValueBinding::RuleFamily(family)), _) => {
                if family.scope.is_some() {
                    // The legacy parameter-type catalog is name/arity keyed.
                    // Do not pair a root signature with a same-named scoped
                    // family; scoped callback signatures need a full
                    // RuleDispatchKey-indexed catalog before admission.
                    return None;
                }
                let parameter_types = self
                    .checker
                    .rule_param_types_by_arity
                    .get(&(family.name.clone(), family.arity))?
                    .iter()
                    .cloned()
                    .collect::<Option<Vec<_>>>()?
                    .into_boxed_slice();
                let result_type = self
                    .checker
                    .rule_dispatch_return_types
                    .get(family)
                    .and_then(|type_name| parse_type_annotation(type_name).ok())?;
                Some((parameter_types, result_type))
            }
            _ => None,
        }
    }

    fn validate_contextual_callback_contract(
        &mut self,
        site: &ExprSiteId,
        expected_arity: usize,
        expected_parameters: Option<&[Ty]>,
        expected_result: Option<&Ty>,
    ) {
        let signature = self
            .artifacts
            .expressions
            .get(site)
            .and_then(|resolution| self.checked_callback_signature(resolution));
        let Some((actual_parameters, actual_result)) = signature else {
            self.issue(
                site,
                CheckedResolutionIssue::UnsupportedExpression(
                    "higher-order builtin callback signature is not exactly resolved".into(),
                ),
            );
            return;
        };
        if actual_parameters.len() != expected_arity {
            self.issue(
                site,
                CheckedResolutionIssue::UnsupportedExpression(
                    format!(
                        "higher-order builtin applies callback with arity {expected_arity}, but the checked callback has arity {}",
                        actual_parameters.len()
                    )
                    .into_boxed_str(),
                ),
            );
            return;
        }
        if let Some(expected_parameters) = expected_parameters {
            let parameters_match = actual_parameters.len() == expected_parameters.len()
                && actual_parameters
                    .iter()
                    .zip(expected_parameters)
                    .all(|(actual, expected)| {
                        TypeChecker::canonical_explore_ty_name(actual)
                            == TypeChecker::canonical_explore_ty_name(expected)
                    });
            if !parameters_match {
                self.issue(
                    site,
                    CheckedResolutionIssue::UnsupportedExpression(
                        "higher-order builtin callback parameter types do not match its checked input types"
                            .into(),
                    ),
                );
            }
        }
        if expected_result.is_some_and(|expected| {
            TypeChecker::canonical_explore_ty_name(&actual_result)
                != TypeChecker::canonical_explore_ty_name(expected)
        }) {
            self.issue(
                site,
                CheckedResolutionIssue::UnsupportedExpression(
                    "higher-order builtin callback result type does not match its checked result contract"
                        .into(),
                ),
            );
        }
    }

    fn contextually_typed_lambda(expression: &Expr, parameter_types: &[Ty]) -> Option<Expr> {
        let mut contextual = expression.clone();
        let ExprKind::Lambda(parameters, _) = &mut contextual.kind else {
            return None;
        };
        if parameters.len() != parameter_types.len() {
            return None;
        }
        for (parameter, expected) in parameters.iter_mut().zip(parameter_types) {
            match &parameter.ty {
                Some(actual)
                    if !matches!(actual, Ty::Hole)
                        && TypeChecker::canonical_explore_ty_name(actual)
                            != TypeChecker::canonical_explore_ty_name(expected) =>
                {
                    return None;
                }
                Some(actual) if !matches!(actual, Ty::Hole) => {}
                Some(_) | None => parameter.ty = Some(expected.clone()),
            }
        }
        Some(contextual)
    }

    fn infer_type(
        &mut self,
        declaration: &SourcedStmt,
        path: &[u32],
        expression: &Expr,
    ) -> CheckedExpressionType {
        let site = self.expression_site(declaration, path);
        if TypeChecker::is_polymorphic_empty_list_expr(expression) {
            return CheckedExpressionType::PolymorphicEmptyList;
        }
        let locals = self.type_locals();
        if let ExprKind::Lambda(parameters, body) = &expression.kind {
            let mut lambda_locals = locals;
            let mut parameter_types = Vec::with_capacity(parameters.len());
            for parameter in parameters {
                let Some(parameter_type) = parameter.ty.as_ref() else {
                    self.issue(&site, CheckedResolutionIssue::TypeNotResolved);
                    return CheckedExpressionType::Unsupported;
                };
                if matches!(parameter_type, Ty::Hole) {
                    self.issue(&site, CheckedResolutionIssue::TypeNotResolved);
                    return CheckedExpressionType::Unsupported;
                }
                let local_type = TypeChecker::canonical_explore_ty_name(parameter_type);
                lambda_locals.insert(parameter.name.clone(), local_type);
                parameter_types.push(parameter_type.clone());
            }
            let Some(result_type_name) =
                self.infer_expr_type_name_in_active_scope(body, &lambda_locals)
            else {
                self.issue(&site, CheckedResolutionIssue::TypeNotResolved);
                return CheckedExpressionType::Unsupported;
            };
            let result_type = match parse_type_annotation(&result_type_name) {
                Ok(result_type) => result_type,
                Err(_) => {
                    self.issue(
                        &site,
                        CheckedResolutionIssue::TypeNotRepresentable(
                            result_type_name.into_boxed_str(),
                        ),
                    );
                    return CheckedExpressionType::Unsupported;
                }
            };
            return CheckedExpressionType::Callable {
                parameters: parameter_types.into_boxed_slice(),
                result: Box::new(result_type),
            };
        }
        let Some(type_name) = self.infer_expr_type_name_in_active_scope(expression, &locals) else {
            self.issue(&site, CheckedResolutionIssue::TypeNotResolved);
            return CheckedExpressionType::Unsupported;
        };
        match parse_type_annotation(&type_name) {
            Ok(ty) => CheckedExpressionType::Resolved(ty),
            Err(_) => {
                self.issue(
                    &site,
                    CheckedResolutionIssue::TypeNotRepresentable(type_name.into_boxed_str()),
                );
                CheckedExpressionType::Unsupported
            }
        }
    }

    /// Runtime value lookup places ordinary root functions, ADT methods and
    /// implementation methods ahead of rule values and constructors. Phase A
    /// retains an exact identity for those callable forms. Multiple retained
    /// candidates remain unsupported here instead of guessing which legacy
    /// flat-registry insertion won.
    fn bare_runtime_callable_candidates(&self, name: &str) -> Vec<CheckedCallableId> {
        self.bare_runtime_callables_by_name
            .get(name)
            .cloned()
            .unwrap_or_default()
    }

    /// A rule used as a first-class value dispatches by the arity supplied
    /// later to `apply_rule_value`: an active RuleScope family wins for its
    /// arity, otherwise the root family is used. A single checked RuleFamily
    /// identity is sound only when that effective table has one entry.
    fn effective_rule_value_candidates(&self, name: &str) -> Vec<RuleDispatchKey> {
        let mut by_arity = self
            .rule_families_by_scope_and_name
            .get(&(None, name.to_string()))
            .into_iter()
            .flatten()
            .map(|key| (key.arity, key.clone()))
            .collect::<BTreeMap<_, _>>();
        if let Some(scope) = &self.active_rule_scope {
            if let Some(families) = self
                .rule_families_by_scope_and_name
                .get(&(Some(scope.clone()), name.to_string()))
            {
                for key in families {
                    by_arity.insert(key.arity, key.clone());
                }
            }
        }
        by_arity.into_values().collect()
    }

    fn resolve_var(
        &mut self,
        declaration: &SourcedStmt,
        path: &[u32],
        name: &str,
    ) -> Option<CheckedValueBinding> {
        let site = self.expression_site(declaration, path);
        if name == "_" {
            return None;
        }
        if let Some(binding) = self.local(name) {
            return Some(CheckedValueBinding::Binder {
                kind: binding.kind,
                site: binding.site,
            });
        }
        if let Some(owner) = self.qualified_aliases.get(name).cloned() {
            self.issue(
                &site,
                CheckedResolutionIssue::OpaqueQualifiedBody(owner.clone()),
            );
            return Some(CheckedValueBinding::OpaqueQualifiedOwner(owner));
        }
        if let Some(bindings) = self.top_level_bindings.get(name).cloned() {
            return match bindings.as_slice() {
                [binding] => Some(CheckedValueBinding::TopLevel(binding.clone())),
                _ => {
                    self.issue(
                        &site,
                        CheckedResolutionIssue::AmbiguousValueBinding(
                            name.to_string().into_boxed_str(),
                        ),
                    );
                    None
                }
            };
        }

        let callables = self.bare_runtime_callable_candidates(name);
        if !callables.is_empty() && self.checker.constructor_signatures.contains_key(name) {
            // Functions and constructors both install values in the runtime
            // Env; their source-order winner is not represented by the
            // namespace-only lookup below.
            self.issue(
                &site,
                CheckedResolutionIssue::AmbiguousValueBinding(name.to_string().into_boxed_str()),
            );
            return None;
        }
        match callables.as_slice() {
            [callable] => return Some(CheckedValueBinding::Callable(callable.clone())),
            [] => {}
            _ => {
                self.issue(
                    &site,
                    CheckedResolutionIssue::AmbiguousValueBinding(
                        name.to_string().into_boxed_str(),
                    ),
                );
                return None;
            }
        }

        // Some runtime functions (for example raw Rust declarations or trait
        // signatures) do not yet have a Phase-A callable occurrence. They
        // still outrank rule values at runtime, so fail closed rather than
        // redirecting the name to a rule or constructor.
        if self
            .checker
            .reference_symbols
            .get(name)
            .is_some_and(|kinds| kinds.contains(&ProgramSymbolKind::Function))
        {
            self.issue(
                &site,
                CheckedResolutionIssue::ValueBindingNotResolved(name.to_string().into_boxed_str()),
            );
            return None;
        }

        let rule_families = self.effective_rule_value_candidates(name);
        if !rule_families.is_empty()
            && (self.checker.constructor_signatures.contains_key(name)
                || self.checker.builtins.contains_key(builtin_canonical(name)))
        {
            // A bare rule name is materialized only after runtime Env lookup;
            // constructor and builtin values therefore make the first-class
            // value identity collision-dependent.
            self.issue(
                &site,
                CheckedResolutionIssue::AmbiguousValueBinding(name.to_string().into_boxed_str()),
            );
            return None;
        }
        match rule_families.as_slice() {
            [key] => return Some(CheckedValueBinding::RuleFamily(key.clone())),
            [] => {}
            _ => {
                self.issue(
                    &site,
                    CheckedResolutionIssue::AmbiguousValueBinding(
                        name.to_string().into_boxed_str(),
                    ),
                );
                return None;
            }
        }
        if self.duplicate_rule_scope_owners.contains(name)
            && self.checker.constructor_signatures.contains_key(name)
        {
            self.issue(
                &site,
                CheckedResolutionIssue::AmbiguousValueBinding(name.to_string().into_boxed_str()),
            );
            return None;
        }
        if self.checker.constructor_signatures.contains_key(name) {
            let signature = match self.exact_constructor_signature(name, &[], 0) {
                ExactConstructorSignature::Unique(signature) if signature.arity() == 0 => signature,
                ExactConstructorSignature::Unique(_) => {
                    self.issue(
                        &site,
                        CheckedResolutionIssue::UnsupportedExpression(
                            "non-nullary constructor used as a value".into(),
                        ),
                    );
                    return None;
                }
                ExactConstructorSignature::NoMatch => return None,
                ExactConstructorSignature::Ambiguous => {
                    // Constructor declarations install a same-named runtime
                    // value in source order. A unique nullary signature is not
                    // enough when another arity/layout can own that value.
                    self.issue(
                        &site,
                        CheckedResolutionIssue::AmbiguousValueBinding(
                            name.to_string().into_boxed_str(),
                        ),
                    );
                    return None;
                }
            };
            let (declaration_id, variant_index) =
                match self.indexed_constructor_identity(&signature, name) {
                    Ok(identity) => identity,
                    Err(()) => {
                        self.issue(
                            &site,
                            CheckedResolutionIssue::AmbiguousValueBinding(
                                name.to_string().into_boxed_str(),
                            ),
                        );
                        return None;
                    }
                };
            return Some(CheckedValueBinding::Constructor {
                declaration: declaration_id,
                owner_type: signature.parent.into_boxed_str(),
                variant: name.to_string().into_boxed_str(),
                variant_index,
            });
        }
        // Callable-position variables are suppressed by their App parent, so
        // reaching this branch means the builtin is genuinely first-class.
        // CheckedValueBinding has no builtin-value identity yet.
        if self.checker.builtins.contains_key(builtin_canonical(name)) {
            self.issue(
                &site,
                CheckedResolutionIssue::UnsupportedExpression(
                    "builtin used as a first-class value".into(),
                ),
            );
            None
        } else {
            self.issue(
                &site,
                CheckedResolutionIssue::ValueBindingNotResolved(name.to_string().into_boxed_str()),
            );
            None
        }
    }

    fn exact_callable_target(
        &mut self,
        declaration: &SourcedStmt,
        path: &[u32],
        scope: Option<String>,
        name: &str,
        arity: usize,
    ) -> Option<CheckedCallTarget> {
        let site = self.expression_site(declaration, path);
        let key = RuleDispatchKey {
            scope: scope.clone(),
            name: name.to_string(),
            arity,
        };
        let rules = self.artifacts.rule_families.contains_key(&key);
        let functions = self
            .callables
            .get(&(scope, name.to_string(), arity))
            .cloned()
            .unwrap_or_default();
        match (functions.as_slice(), rules) {
            ([callable], false) => Some(CheckedCallTarget::Function {
                callable: callable.clone(),
                arity,
            }),
            ([], true) => Some(CheckedCallTarget::RuleFamily(key)),
            ([], false) => None,
            _ => {
                self.issue(
                    &site,
                    CheckedResolutionIssue::AmbiguousCallable {
                        name: name.to_string().into_boxed_str(),
                        arity,
                    },
                );
                None
            }
        }
    }

    fn has_callable_candidates(&self, scope: Option<&str>, name: &str, arity: usize) -> bool {
        let key = RuleDispatchKey {
            scope: scope.map(ToString::to_string),
            name: name.to_string(),
            arity,
        };
        self.artifacts.rule_families.contains_key(&key)
            || self
                .callables
                .get(&(scope.map(ToString::to_string), name.to_string(), arity))
                .is_some_and(|candidates| !candidates.is_empty())
    }

    fn exact_constructor_signature(
        &self,
        name: &str,
        arguments: &[Expr],
        effective_arity: usize,
    ) -> ExactConstructorSignature {
        // The legacy checker retains historical constructor signatures for a
        // duplicate RuleScope while the runtime rule/member owner is replaced
        // wholesale by the latest declaration. Until a signature itself
        // carries an occurrence identity, pairing either historical layout
        // with the latest owner would be an invented resolution.
        if self.duplicate_rule_scope_owners.contains(name) {
            return ExactConstructorSignature::Ambiguous;
        }
        let Some(signatures) = self.checker.constructor_signatures.get(name) else {
            return ExactConstructorSignature::NoMatch;
        };
        let matching = signatures
            .iter()
            .filter(|signature| {
                if effective_arity == arguments.len() {
                    signature.matches_args(arguments)
                } else {
                    !has_named_args(arguments) && signature.arity() == effective_arity
                }
            })
            .collect::<Vec<_>>();
        match matching.as_slice() {
            [] => ExactConstructorSignature::NoMatch,
            [signature] => ExactConstructorSignature::Unique((*signature).clone()),
            [first, rest @ ..]
                if rest.iter().all(|signature| {
                    signature.parent == first.parent
                        && ((signature.positional
                            && first.positional
                            && signature.fields.len() == first.fields.len())
                            || (signature.fields.is_empty() && first.fields.is_empty())
                            || (!signature.positional
                                && !first.positional
                                && signature.fields == first.fields))
                }) =>
            {
                // Generic/imported checking can retain several static field-
                // type views of one runtime constructor. Positional field
                // labels are not runtime layout, while named labels are;
                // positional/named has no runtime distinction for a zero-field
                // value. Contextual field typing remains conservative when
                // type views differ.
                ExactConstructorSignature::Unique((*first).clone())
            }
            _ => ExactConstructorSignature::Ambiguous,
        }
    }

    fn constructor_signature_matches_identity(
        signature: &TypeConstructorSignature,
        identity: &CheckedConstructorIdentity,
    ) -> bool {
        if signature.parent != identity.owner_type.as_ref()
            || signature.fields.len() != identity.fields.len()
        {
            return false;
        }
        if signature.fields.is_empty() {
            return true;
        }
        match identity.layout {
            CheckedConstructorLayout::Positional => signature.positional,
            CheckedConstructorLayout::Named => {
                !signature.positional
                    && signature
                        .fields
                        .iter()
                        .map(String::as_str)
                        .eq(identity.fields.iter().map(|field| field.name.as_ref()))
            }
        }
    }

    fn indexed_constructor_identity(
        &self,
        signature: &TypeConstructorSignature,
        variant: &str,
    ) -> Result<(Option<CheckedDeclarationOccurrenceId>, Option<usize>), ()> {
        let owner_type = signature.parent.as_str();
        let prelude_constructor = matches!(
            (owner_type, variant),
            ("Option", "None" | "Some")
                | ("Result", "Ok" | "Err")
                | ("Pair", "Pair")
                | ("Bool", "True" | "False")
        );
        if self
            .data_owner_declarations
            .get(owner_type)
            .is_some_and(|declarations| declarations.len() != 1)
        {
            return Err(());
        }
        match self
            .constructors
            .get(&(owner_type.to_string(), variant.to_string()))
            .map(Vec::as_slice)
        {
            Some([constructor])
                if Self::constructor_signature_matches_identity(
                    signature,
                    &constructor.identity,
                ) =>
            {
                Ok((
                    match &constructor.identity.owner {
                        CheckedDataTypeId::Declared(owner) => self
                            .artifacts
                            .data_owner_to_analysis_occurrence
                            .get(owner)
                            .cloned(),
                        CheckedDataTypeId::Intrinsic { .. } => None,
                    },
                    Some(constructor.identity.variant_index),
                ))
            }
            Some(_) => Err(()),
            None if prelude_constructor
                && !self.data_owner_declarations.contains_key(owner_type)
                && Self::intrinsic_constructor_identity(owner_type, variant).is_some_and(
                    |identity| Self::constructor_signature_matches_identity(signature, &identity),
                ) =>
            {
                Ok((None, None))
            }
            None => Err(()),
        }
    }

    fn checked_constructor_identity(
        &self,
        owner_type: &str,
        variant: &str,
    ) -> Option<CheckedConstructorIdentity> {
        self.artifacts
            .constructor_identities
            .get(&(owner_type.into(), variant.into()))
            .map(|identity| identity.as_ref().clone())
    }

    fn named_order(
        &mut self,
        declaration: &SourcedStmt,
        path: &[u32],
        arguments: &[Expr],
        parameters: Option<Vec<String>>,
    ) -> Option<CheckedNamedArgumentOrder> {
        if !has_named_args(arguments) {
            return None;
        }
        let site = self.expression_site(declaration, path);
        let Some(parameters) = parameters else {
            self.issue(&site, CheckedResolutionIssue::NamedArgumentOrderNotResolved);
            return None;
        };
        if !all_named_args(arguments)
            || reorder_named_args_by_names(&parameters, arguments).is_none()
        {
            self.issue(&site, CheckedResolutionIssue::NamedArgumentOrderNotResolved);
            return None;
        }
        let source_names = arguments
            .iter()
            .filter_map(named_arg_parts)
            .map(|(name, _)| name)
            .collect::<Vec<_>>();
        let canonical_source_indices = parameters
            .iter()
            .map(|parameter| {
                source_names
                    .iter()
                    .position(|name| *name == parameter.as_str())
            })
            .collect::<Option<Vec<_>>>();
        let Some(canonical_source_indices) = canonical_source_indices else {
            self.issue(&site, CheckedResolutionIssue::NamedArgumentOrderNotResolved);
            return None;
        };
        Some(CheckedNamedArgumentOrder {
            parameter_names: parameters
                .into_iter()
                .map(String::into_boxed_str)
                .collect::<Vec<_>>()
                .into_boxed_slice(),
            canonical_source_indices: canonical_source_indices.into_boxed_slice(),
        })
    }

    fn resolve_call(
        &mut self,
        declaration: &SourcedStmt,
        path: &[u32],
        function: &Expr,
        arguments: &[Expr],
        effective_arity: usize,
    ) -> (Option<CheckedCallTarget>, Option<CheckedNamedArgumentOrder>) {
        let site = self.expression_site(declaration, path);
        if let ExprKind::Var(name) = &function.kind {
            if matches!(
                name.as_str(),
                NAMED_ARG_MARKER | "__typed" | PATHOF_MARKER | REFOF_MARKER
            ) {
                return (
                    Some(CheckedCallTarget::Builtin {
                        canonical_name: name.clone().into_boxed_str(),
                        arity: effective_arity,
                    }),
                    None,
                );
            }
            if let Some(scope) = self.active_rule_scope.clone() {
                if let Some(target) = self.exact_callable_target(
                    declaration,
                    path,
                    Some(scope.clone()),
                    name,
                    effective_arity,
                ) {
                    let parameters = self
                        .checker
                        .rule_scope_method_params
                        .get(&scope)
                        .and_then(|methods| methods.get(name))
                        .or_else(|| {
                            self.checker
                                .rule_scope_value_method_params
                                .get(&scope)
                                .and_then(|methods| methods.get(name))
                        })
                        .cloned();
                    let order = self.named_order(declaration, path, arguments, parameters);
                    return (Some(target), order);
                }
                if self.has_callable_candidates(Some(&scope), name, effective_arity) {
                    return (None, None);
                }
            }

            // Runtime App semantics consult a lexical closure before any
            // constructor, root function or rule family. Its concrete target
            // is dynamic, but a same-named global must never be invented.
            if let Some(binding) = self.local(name) {
                if !has_named_args(arguments) {
                    if let Some(target) = Self::bound_callable_target(&binding, effective_arity) {
                        return (Some(target), None);
                    }
                }
                self.issue(&site, CheckedResolutionIssue::DynamicCallable);
                return (None, None);
            }
            if self.top_level_bindings.contains_key(name) {
                // Runtime App consults the completed top-level Env at this
                // point and applies the value when it is a closure. Phase B
                // retains the binding occurrence but not its evaluated value,
                // so it must not redirect the call to a same-named static
                // constructor/function/rule.
                self.issue(&site, CheckedResolutionIssue::DynamicCallable);
                return (None, None);
            }

            let constructor_signature =
                self.exact_constructor_signature(name, arguments, effective_arity);
            let runtime_callables = !self.bare_runtime_callable_candidates(name).is_empty();
            if runtime_callables
                && matches!(
                    &constructor_signature,
                    ExactConstructorSignature::Unique(_) | ExactConstructorSignature::Ambiguous
                )
            {
                // Constructors and ordinary functions are installed into the
                // same runtime environment in declaration order. Namespace
                // lookup alone cannot prove which same-named static wins.
                self.issue(
                    &site,
                    CheckedResolutionIssue::AmbiguousCallable {
                        name: name.clone().into_boxed_str(),
                        arity: effective_arity,
                    },
                );
                return (None, None);
            }

            match constructor_signature {
                ExactConstructorSignature::Unique(signature) => {
                    let Ok((constructor, variant_index)) =
                        self.indexed_constructor_identity(&signature, name)
                    else {
                        self.issue(
                            &site,
                            CheckedResolutionIssue::AmbiguousCallable {
                                name: name.clone().into_boxed_str(),
                                arity: effective_arity,
                            },
                        );
                        return (None, None);
                    };
                    let order =
                        self.named_order(declaration, path, arguments, Some(signature.fields));
                    return (
                        Some(CheckedCallTarget::Constructor {
                            declaration: constructor,
                            owner_type: signature.parent.into_boxed_str(),
                            variant: name.clone().into_boxed_str(),
                            variant_index,
                            arity: effective_arity,
                        }),
                        order,
                    );
                }
                ExactConstructorSignature::Ambiguous => {
                    self.issue(
                        &site,
                        CheckedResolutionIssue::AmbiguousCallable {
                            name: name.clone().into_boxed_str(),
                            arity: effective_arity,
                        },
                    );
                    return (None, None);
                }
                ExactConstructorSignature::NoMatch => {}
            }

            let canonical = builtin_canonical(name);
            if self.checker.functions.contains_key(name) {
                if let Some(target) =
                    self.exact_callable_target(declaration, path, None, name, effective_arity)
                {
                    let parameters = self
                        .checker
                        .function_params_for_arity(name, effective_arity)
                        .cloned()
                        .or_else(|| self.checker.function_params.get(name).cloned());
                    let order = self.named_order(declaration, path, arguments, parameters);
                    return (Some(target), order);
                }
                if self.has_callable_candidates(None, name, effective_arity) {
                    return (None, None);
                }
                self.issue(
                    &site,
                    CheckedResolutionIssue::CallableNotResolved {
                        name: name.clone().into_boxed_str(),
                        arity: effective_arity,
                    },
                );
                return (None, None);
            }
            if self.checker.builtins.contains_key(canonical) {
                if has_named_args(arguments) {
                    self.issue(&site, CheckedResolutionIssue::NamedArgumentOrderNotResolved);
                    return (None, None);
                }
                return (
                    Some(CheckedCallTarget::Builtin {
                        canonical_name: canonical.to_string().into_boxed_str(),
                        arity: effective_arity,
                    }),
                    None,
                );
            }
            self.issue(
                &site,
                CheckedResolutionIssue::CallableNotResolved {
                    name: name.clone().into_boxed_str(),
                    arity: effective_arity,
                },
            );
            return (None, None);
        }

        if let ExprKind::Field(base, member) = &function.kind {
            if let ExprKind::Var(alias) = &base.kind {
                if self.local(alias).is_none() && !self.top_level_bindings.contains_key(alias) {
                    if let Some(owner) = self.qualified_aliases.get(alias).cloned() {
                        self.issue(
                            &site,
                            CheckedResolutionIssue::OpaqueQualifiedMember {
                                owner,
                                member: member.clone().into_boxed_str(),
                            },
                        );
                        return (None, None);
                    }
                }
            }
            let locals = self.type_locals();
            let Some(owner_type) = self.infer_checked_receiver_type(base, &locals) else {
                self.issue(
                    &site,
                    CheckedResolutionIssue::CallableNotResolved {
                        name: member.clone().into_boxed_str(),
                        arity: effective_arity,
                    },
                );
                return (None, None);
            };
            if self.duplicate_rule_scope_owners.contains(&owner_type) {
                self.issue(
                    &site,
                    CheckedResolutionIssue::UnsupportedExpression(
                        "duplicate RuleScope receiver layout".into(),
                    ),
                );
                return (None, None);
            }
            let key = RuleDispatchKey {
                scope: Some(owner_type.clone()),
                name: member.clone(),
                arity: effective_arity,
            };
            let rule_family = self
                .artifacts
                .rule_families
                .contains_key(&key)
                .then_some(key.clone());
            let declared_rule_arity = self
                .checker
                .rule_scope_methods
                .get(&owner_type)
                .and_then(|methods| methods.get(member))
                .copied();
            if rule_family.is_some() {
                let parameters = self
                    .checker
                    .rule_scope_method_params
                    .get(&owner_type)
                    .and_then(|methods| methods.get(member))
                    .cloned();
                let order = self.named_order(declaration, path, arguments, parameters);
                return (
                    Some(CheckedCallTarget::ScopedMember {
                        owner_type: owner_type.into_boxed_str(),
                        member: member.clone().into_boxed_str(),
                        arity: effective_arity,
                        rule_family,
                    }),
                    order,
                );
            }
            if declared_rule_arity.is_some_and(|arity| arity == effective_arity) {
                // The runtime would dispatch this exact scoped rule before
                // evaluating a same-named captured field or ordinary method.
                // Missing Phase-A family identity must therefore fail closed.
                self.issue(
                    &site,
                    CheckedResolutionIssue::CallableNotResolved {
                        name: member.clone().into_boxed_str(),
                        arity: effective_arity,
                    },
                );
                return (None, None);
            }

            if self.checker.field_type_name(&owner_type, member).is_some() {
                // Without an exact scoped-rule match, runtime App evaluates
                // the field. Captured values precede bound ordinary methods,
                // and their callable identity is dynamic at this boundary.
                self.issue(&site, CheckedResolutionIssue::DynamicCallable);
                return (None, None);
            }

            let value_method = self
                .checker
                .rule_scope_value_methods
                .get(&owner_type)
                .and_then(|methods| methods.get(member))
                .is_some_and(|arity| *arity == effective_arity);
            if !value_method {
                self.issue(
                    &site,
                    CheckedResolutionIssue::CallableNotResolved {
                        name: member.clone().into_boxed_str(),
                        arity: effective_arity,
                    },
                );
                return (None, None);
            }
            let parameters = self
                .checker
                .rule_scope_value_method_params
                .get(&owner_type)
                .and_then(|methods| methods.get(member))
                .cloned();
            let order = self.named_order(declaration, path, arguments, parameters);
            return (
                Some(CheckedCallTarget::ScopedMember {
                    owner_type: owner_type.into_boxed_str(),
                    member: member.clone().into_boxed_str(),
                    arity: effective_arity,
                    rule_family: None,
                }),
                order,
            );
        }

        self.issue(&site, CheckedResolutionIssue::DynamicCallable);
        (None, None)
    }

    /// Return the exact result of a bare call captured by the enclosing
    /// RuleScope, when such a scoped candidate exists. The outer `Option`
    /// distinguishes "no scoped candidate" from "a scoped candidate exists
    /// but its type is not sealed": the latter must not fall through to a
    /// same-named root declaration.
    fn active_scope_bare_call_return_type(&self, expression: &Expr) -> Option<Option<String>> {
        let ExprKind::App(function, arguments) = &expression.kind else {
            return None;
        };
        let ExprKind::Var(name) = &function.kind else {
            return None;
        };
        let scope = self.active_rule_scope.as_ref()?;
        let key = RuleDispatchKey {
            scope: Some(scope.clone()),
            name: name.clone(),
            arity: arguments.len(),
        };
        let has_rule_family = self.artifacts.rule_families.contains_key(&key);
        let scoped_functions = self
            .callables
            .get(&(Some(scope.clone()), name.clone(), arguments.len()))
            .map(Vec::as_slice)
            .unwrap_or_default();
        if !has_rule_family && scoped_functions.is_empty() {
            return None;
        }
        Some(match (scoped_functions, has_rule_family) {
            ([], true) => self.checker.rule_dispatch_return_types.get(&key).cloned(),
            // Checked function-return metadata is still name/arity keyed, not
            // occurrence keyed. Do not pair it with a scoped function merely
            // because the spelling matches.
            _ => None,
        })
    }

    fn infer_checked_receiver_type(
        &self,
        expression: &Expr,
        locals: &BTreeMap<String, String>,
    ) -> Option<String> {
        match self.active_scope_bare_call_return_type(expression) {
            Some(result) => result,
            None => self.infer_expr_type_name_in_active_scope(expression, locals),
        }
    }

    fn resolve_field(
        &mut self,
        declaration: &SourcedStmt,
        path: &[u32],
        base: &Expr,
        field: &str,
    ) -> Option<CheckedFieldResolution> {
        let site = self.expression_site(declaration, path);
        if let ExprKind::Var(alias) = &base.kind {
            if self.local(alias).is_none() && !self.top_level_bindings.contains_key(alias) {
                if let Some(owner) = self.qualified_aliases.get(alias).cloned() {
                    self.issue(
                        &site,
                        CheckedResolutionIssue::OpaqueQualifiedMember {
                            owner,
                            member: field.to_string().into_boxed_str(),
                        },
                    );
                    return None;
                }
            }
        }
        let locals = self.type_locals();
        let owner_type = self.infer_checked_receiver_type(base, &locals);
        let Some(owner_type) = owner_type else {
            self.issue(
                &site,
                CheckedResolutionIssue::FieldNotResolved {
                    owner_type: None,
                    field: field.to_string().into_boxed_str(),
                },
            );
            return None;
        };
        if self.duplicate_rule_scope_owners.contains(&owner_type) {
            self.issue(
                &site,
                CheckedResolutionIssue::UnsupportedExpression(
                    "duplicate RuleScope field layout".into(),
                ),
            );
            return None;
        }
        if self.checker.field_type_name(&owner_type, field).is_some() {
            let owner_is_unique = self
                .artifacts
                .data_type_identities
                .contains_key(owner_type.as_str());
            let fields = owner_is_unique
                .then(|| {
                    self.data_fields
                        .get(&(owner_type.clone(), field.to_string()))
                        .cloned()
                })
                .flatten();
            let Some(fields) = fields.filter(|fields| !fields.is_empty()) else {
                self.issue(
                    &site,
                    CheckedResolutionIssue::FieldNotResolved {
                        owner_type: Some(owner_type.into_boxed_str()),
                        field: field.to_string().into_boxed_str(),
                    },
                );
                return None;
            };
            return Some(CheckedFieldResolution::Data {
                owner_type: owner_type.into_boxed_str(),
                fields: fields.into_boxed_slice(),
            });
        }

        if self
            .checker
            .rule_scope_value_methods
            .get(&owner_type)
            .is_some_and(|methods| methods.contains_key(field))
        {
            self.issue(
                &site,
                CheckedResolutionIssue::UnsupportedExpression(
                    "bound method used as a first-class value".into(),
                ),
            );
            return None;
        }

        self.issue(
            &site,
            CheckedResolutionIssue::FieldNotResolved {
                owner_type: Some(owner_type.into_boxed_str()),
                field: field.to_string().into_boxed_str(),
            },
        );
        None
    }

    fn resolved_field_type(&self, resolution: &CheckedFieldResolution, field: &str) -> Option<Ty> {
        let type_name = match resolution {
            CheckedFieldResolution::Data { owner_type, .. } => {
                self.checker.field_type_name(owner_type, field)
            }
            CheckedFieldResolution::ScopedMember {
                owner_type,
                member,
                rule_family,
            } => match rule_family {
                Some(key) => self.checker.rule_dispatch_return_types.get(key).cloned(),
                None => self
                    .checker
                    .scoped_member_return_type(owner_type, member, 0),
            },
        }?;
        parse_type_annotation(&type_name).ok()
    }

    fn define_parameter(
        &mut self,
        declaration: &SourcedStmt,
        ast_path: &[u32],
        index: usize,
        parameter: &Param,
        extra_prefix: &[u32],
    ) {
        let mut binder_path = extra_prefix.to_vec();
        binder_path.extend([Self::BINDER_PARAMETER, index as u32]);
        self.define_local(
            parameter.name.clone(),
            CheckedLocalBinding {
                kind: CheckedBinderKind::Parameter,
                site: self.structural_binder_site(declaration, ast_path, binder_path),
                type_name: parameter.ty.as_ref().and_then(|ty| {
                    (!matches!(ty, Ty::Hole)).then(|| TypeChecker::canonical_explore_ty_name(ty))
                }),
            },
        );
    }

    fn define_pattern(
        &mut self,
        declaration: &SourcedStmt,
        ast_path: &[u32],
        pattern: &Pat,
        pattern_path: Vec<u32>,
        kind: CheckedBinderKind,
        type_name: Option<String>,
    ) {
        match pattern {
            Pat::Var(name) => {
                let mut binder_path = vec![Self::BINDER_PATTERN];
                binder_path.extend(pattern_path);
                self.define_local(
                    name.clone(),
                    CheckedLocalBinding {
                        kind,
                        site: self.structural_binder_site(declaration, ast_path, binder_path),
                        type_name,
                    },
                );
            }
            Pat::Con(constructor, patterns) => {
                if let Some(owner_type) = type_name
                    .as_deref()
                    .and_then(Self::data_owner_name_from_checked_type)
                {
                    if let Some(identity) =
                        self.checked_constructor_identity(&owner_type, constructor)
                    {
                        // A fielded positional constructor with no children is
                        // the checked tag-only refinement form. Whether the
                        // enclosing match may use that form is enforced from
                        // the scrutinee/whole-arm shape; retaining the exact
                        // constructor identity here lets semantic consumers
                        // normalize the accepted form without spelling lookup.
                        if identity.fields.len() == patterns.len() || patterns.is_empty() {
                            self.artifacts.constructor_patterns.insert(
                                self.pattern_site(declaration, ast_path, &pattern_path),
                                CheckedConstructorPatternResolution {
                                    source_fields: if patterns.is_empty() {
                                        Box::new([])
                                    } else {
                                        identity.fields.clone()
                                    },
                                    constructor: identity,
                                },
                            );
                        }
                    }
                }
                for (index, child) in patterns.iter().enumerate() {
                    let mut child_path = pattern_path.clone();
                    child_path.push(index as u32);
                    let child_type = self.checker.constructor_pattern_field_type_name(
                        constructor,
                        index,
                        type_name.as_deref(),
                    );
                    self.define_pattern(declaration, ast_path, child, child_path, kind, child_type);
                }
            }
            Pat::NamedCon(constructor, fields) => {
                if let Some(owner_type) = type_name
                    .as_deref()
                    .and_then(Self::data_owner_name_from_checked_type)
                {
                    if let Some(identity) =
                        self.checked_constructor_identity(&owner_type, constructor)
                    {
                        if identity.layout == CheckedConstructorLayout::Named {
                            let source_fields = fields
                                .iter()
                                .map(|(name, _)| {
                                    identity
                                        .fields
                                        .iter()
                                        .find(|field| field.name.as_ref() == name)
                                        .cloned()
                                })
                                .collect::<Option<Vec<_>>>();
                            if let Some(source_fields) = source_fields {
                                self.artifacts.constructor_patterns.insert(
                                    self.pattern_site(declaration, ast_path, &pattern_path),
                                    CheckedConstructorPatternResolution {
                                        constructor: identity,
                                        source_fields: source_fields.into_boxed_slice(),
                                    },
                                );
                            }
                        }
                    }
                }
                for (index, (field, child)) in fields.iter().enumerate() {
                    let mut child_path = pattern_path.clone();
                    child_path.push(index as u32);
                    let child_type = self.checker.named_constructor_pattern_field_type_name(
                        constructor,
                        field,
                        type_name.as_deref(),
                    );
                    self.define_pattern(declaration, ast_path, child, child_path, kind, child_type);
                }
            }
            Pat::As(child, name) => {
                self.define_pattern(
                    declaration,
                    ast_path,
                    child,
                    pattern_path.clone(),
                    kind,
                    type_name.clone(),
                );
                let mut binder_path = vec![Self::BINDER_PATTERN];
                binder_path.extend(pattern_path);
                binder_path.push(u32::MAX);
                self.define_local(
                    name.clone(),
                    CheckedLocalBinding {
                        kind,
                        site: self.structural_binder_site(declaration, ast_path, binder_path),
                        type_name,
                    },
                );
            }
            Pat::Wild | Pat::Lit(_) => {}
        }
    }

    fn first_unresolved_constructor_pattern(
        &self,
        declaration: &SourcedStmt,
        ast_path: &[u32],
        pattern: &Pat,
        pattern_path: Vec<u32>,
    ) -> Option<CheckedPatternSiteId> {
        match pattern {
            Pat::Con(_, children) => {
                let site = self.pattern_site(declaration, ast_path, &pattern_path);
                if !self.artifacts.constructor_patterns.contains_key(&site) {
                    return Some(site);
                }
                children.iter().enumerate().find_map(|(index, child)| {
                    let mut child_path = pattern_path.clone();
                    child_path.push(index as u32);
                    self.first_unresolved_constructor_pattern(
                        declaration,
                        ast_path,
                        child,
                        child_path,
                    )
                })
            }
            Pat::NamedCon(_, fields) => {
                let site = self.pattern_site(declaration, ast_path, &pattern_path);
                if !self.artifacts.constructor_patterns.contains_key(&site) {
                    return Some(site);
                }
                fields.iter().enumerate().find_map(|(index, (_, child))| {
                    let mut child_path = pattern_path.clone();
                    child_path.push(index as u32);
                    self.first_unresolved_constructor_pattern(
                        declaration,
                        ast_path,
                        child,
                        child_path,
                    )
                })
            }
            Pat::As(child, _) => self.first_unresolved_constructor_pattern(
                declaration,
                ast_path,
                child,
                pattern_path,
            ),
            Pat::Wild | Pat::Var(_) | Pat::Lit(_) => None,
        }
    }

    fn data_owner_name_from_checked_type(checked_type: &str) -> Option<String> {
        let ty = parse_type_annotation(checked_type).ok()?;
        match ty {
            Ty::Name(name) => Some(name),
            Ty::App(constructor, _) => type_name(constructor.as_ref()).map(ToString::to_string),
            Ty::Optional(_) => Some("Option".to_string()),
            Ty::Ref(inner) | Ty::MutRef(inner) | Ty::Shared(inner) => {
                type_name(inner.as_ref()).map(ToString::to_string)
            }
            Ty::Arrow(_, _) | Ty::Var(_) | Ty::Unit | Ty::Hole => None,
        }
    }

    fn define_rule_head_argument(
        &mut self,
        declaration: &SourcedStmt,
        expression: &Expr,
        path: &[u32],
        expected_type: Option<String>,
    ) {
        if let Some((inner, type_name)) = typed_rule_head_argument(expression) {
            let inner_path = Self::path_child(path, 1);
            self.define_rule_head_argument(
                declaration,
                inner,
                &inner_path,
                Some(type_name.to_string()),
            );
            return;
        }
        if let Some((_, value)) = named_arg_parts(expression) {
            let value_path = Self::path_child(path, 2);
            self.define_rule_head_argument(declaration, value, &value_path, expected_type);
            return;
        }
        match &expression.kind {
            ExprKind::Var(name)
                if name != "_" && !name.chars().next().is_some_and(char::is_uppercase) =>
            {
                self.define_local(
                    name.clone(),
                    CheckedLocalBinding {
                        kind: CheckedBinderKind::RuleHead,
                        site: CheckedBinderSiteId::Expression(
                            self.expression_site(declaration, path),
                        ),
                        type_name: expected_type,
                    },
                );
            }
            ExprKind::App(_, arguments) => {
                for (index, argument) in arguments.iter().enumerate() {
                    let argument_path = Self::path_child(path, index + 1);
                    self.define_rule_head_argument(declaration, argument, &argument_path, None);
                }
            }
            ExprKind::Tuple(items) => {
                for (index, item) in items.iter().enumerate() {
                    let item_path = Self::path_child(path, index);
                    self.define_rule_head_argument(declaration, item, &item_path, None);
                }
            }
            _ => {}
        }
    }

    fn define_rule_head(&mut self, declaration: &SourcedStmt, head: &Expr, path: &[u32]) {
        if let ExprKind::App(_, arguments) = &head.kind {
            for (index, argument) in arguments.iter().enumerate() {
                let argument_path = Self::path_child(path, index + 1);
                self.define_rule_head_argument(declaration, argument, &argument_path, None);
            }
        }
    }

    fn record_declaration(&mut self, declaration: &SourcedStmt) {
        if matches!(
            &declaration.import_kind,
            SourcedImportKind::QualifiedImport { .. }
        ) || matches!(&*declaration.statement, Stmt::Defn(Defn::Module { .. }))
        {
            return;
        }
        if let Stmt::TypeDecl(TypeDecl::RuleScope { name, .. }) = &*declaration.statement {
            if self.active_rule_scope_owners.get(name) != Some(&Self::model_owner(declaration)) {
                return;
            }
        }
        self.record_stmt(declaration, &declaration.statement, &[], true);
    }

    fn record_function_body(
        &mut self,
        declaration: &SourcedStmt,
        parameters: &[Param],
        body: &Expr,
        body_path: &[u32],
        prefix: &[u32],
    ) {
        self.push_scope();
        for (index, parameter) in parameters.iter().enumerate() {
            self.define_parameter(declaration, body_path, index, parameter, prefix);
        }
        self.record_expr(declaration, body, body_path, false, false);
        self.pop_scope();
    }

    fn record_rule(&mut self, declaration: &SourcedStmt, rule: &Rule, statement_path: &[u32]) {
        match rule {
            Rule::Clause { head, body } => {
                self.push_scope();
                let head_path = Self::path_child(statement_path, 0);
                self.define_rule_head(declaration, head, &head_path);
                self.record_expr(declaration, head, &head_path, true, false);
                if let Some(body) = body {
                    let body_path = Self::path_child(statement_path, 1);
                    self.record_expr(declaration, body, &body_path, false, false);
                }
                self.pop_scope();
            }
            Rule::Default {
                head,
                value,
                condition,
            }
            | Rule::Exception {
                head,
                value,
                condition,
                ..
            } => {
                self.push_scope();
                let head_path = Self::path_child(statement_path, 0);
                self.define_rule_head(declaration, head, &head_path);
                self.record_expr(declaration, head, &head_path, true, false);
                let value_path = Self::path_child(statement_path, 1);
                self.record_expr(declaration, value, &value_path, false, false);
                if let Some(condition) = condition {
                    let condition_path = Self::path_child(statement_path, 2);
                    self.record_expr(declaration, condition, &condition_path, false, false);
                }
                self.pop_scope();
            }
            Rule::ReactiveScope { body, .. } => {
                self.push_scope();
                for (index, statement) in body.iter().enumerate() {
                    let child_path = Self::path_child(statement_path, index);
                    self.record_stmt(declaration, statement, &child_path, false);
                }
                self.pop_scope();
            }
        }
    }

    fn record_stmt(
        &mut self,
        declaration: &SourcedStmt,
        statement: &Stmt,
        path: &[u32],
        top_level: bool,
    ) {
        match statement {
            Stmt::Defn(Defn::Fn { params, body, .. }) => {
                let body_path = Self::path_child(path, 0);
                self.record_function_body(declaration, params, body, &body_path, &[]);
            }
            Stmt::Defn(Defn::Actor {
                state_param,
                handlers,
                ..
            }) => {
                for (index, handler) in handlers.iter().enumerate() {
                    let body_path = Self::path_child(path, index);
                    self.push_scope();
                    self.define_parameter(declaration, &body_path, 0, state_param, &[]);
                    self.define_pattern(
                        declaration,
                        &body_path,
                        &handler.msg_pat,
                        vec![Self::BINDER_HANDLER],
                        CheckedBinderKind::Pattern,
                        None,
                    );
                    self.record_expr(declaration, &handler.body, &body_path, false, false);
                    self.pop_scope();
                }
            }
            Stmt::Defn(Defn::Module { .. }) => {
                // Inline modules share the qualified-opacity boundary of direct
                // qualified imports in this phase. Their owner is indexed above.
            }
            Stmt::TypeDecl(TypeDecl::ADT { methods, .. })
            | Stmt::TypeDecl(TypeDecl::ImplBlock { methods, .. }) => {
                let mut child_index = 0;
                for method in methods {
                    match method {
                        Defn::Fn { params, body, .. } => {
                            let body_path = Self::path_child(path, child_index);
                            self.record_function_body(
                                declaration,
                                params,
                                body,
                                &body_path,
                                &[child_index as u32],
                            );
                            child_index += 1;
                        }
                        Defn::Actor {
                            state_param,
                            handlers,
                            ..
                        } => {
                            for handler in handlers {
                                let body_path = Self::path_child(path, child_index);
                                self.push_scope();
                                self.define_parameter(
                                    declaration,
                                    &body_path,
                                    0,
                                    state_param,
                                    &[child_index as u32],
                                );
                                self.define_pattern(
                                    declaration,
                                    &body_path,
                                    &handler.msg_pat,
                                    vec![Self::BINDER_HANDLER],
                                    CheckedBinderKind::Pattern,
                                    None,
                                );
                                self.record_expr(
                                    declaration,
                                    &handler.body,
                                    &body_path,
                                    false,
                                    false,
                                );
                                self.pop_scope();
                                child_index += 1;
                            }
                        }
                        Defn::Module { body, .. } => {
                            // Nested qualified module body is opaque in Phase B.
                            child_index += body.len();
                        }
                    }
                }
            }
            Stmt::TypeDecl(TypeDecl::WhenType { condition, .. }) => {
                let child_path = Self::path_child(path, 0);
                self.record_expr(declaration, condition, &child_path, false, false);
            }
            Stmt::TypeDecl(TypeDecl::TraitDecl { methods, .. }) => {
                let mut child_index = 0;
                for method in methods {
                    if let Some(body) = &method.default_body {
                        let body_path = Self::path_child(path, child_index);
                        self.record_function_body(
                            declaration,
                            &method.params,
                            body,
                            &body_path,
                            &[child_index as u32],
                        );
                        child_index += 1;
                    }
                }
            }
            Stmt::TypeDecl(TypeDecl::EffectDecl { .. }) => {}
            Stmt::TypeDecl(TypeDecl::RuleScope {
                name, params, body, ..
            }) => {
                let previous_scope = self.active_rule_scope.replace(name.clone());
                self.push_scope();
                for (index, parameter) in params.iter().enumerate() {
                    self.define_parameter(declaration, path, index, parameter, &[]);
                }
                for (index, statement) in body.iter().enumerate() {
                    let child_path = Self::path_child(path, index);
                    self.record_stmt(declaration, statement, &child_path, false);
                }
                self.pop_scope();
                self.active_rule_scope = previous_scope;
            }
            Stmt::Rule(rule) => self.record_rule(declaration, rule, path),
            Stmt::Annot(name, arguments) => {
                for (index, argument) in arguments.iter().enumerate() {
                    let child_path = Self::path_child(path, index);
                    self.record_expr(declaration, argument, &child_path, false, false);
                    if matches!(name.as_str(), "store" | "migrate") {
                        let site = self.expression_site(declaration, &child_path);
                        self.issue(
                            &site,
                            CheckedResolutionIssue::UnsupportedExpression(
                                "unchecked metadata payload".into(),
                            ),
                        );
                    }
                }
            }
            Stmt::Bind(pattern, annotation, expression)
            | Stmt::MonadicBind(pattern, annotation, expression) => {
                let expression_path = Self::path_child(path, 0);
                let locals = self.type_locals();
                let inferred = annotation
                    .as_ref()
                    .and_then(TypeChecker::type_name_from_ty)
                    .or_else(|| self.infer_expr_type_name_in_active_scope(expression, &locals));
                self.record_expr(declaration, expression, &expression_path, false, false);
                if !top_level {
                    self.define_pattern(
                        declaration,
                        path,
                        pattern,
                        Vec::new(),
                        CheckedBinderKind::Local,
                        inferred,
                    );
                }
            }
            Stmt::For(variable, iterator, body) => {
                let iterator_path = Self::path_child(path, 0);
                self.record_expr(declaration, iterator, &iterator_path, false, false);
                let locals = self.type_locals();
                let iterator_type = self
                    .infer_expr_type_name_in_active_scope(iterator, &locals)
                    .and_then(|name| TypeChecker::applied_type_argument(&name, "List", 0));
                self.push_scope();
                self.define_local(
                    variable.clone(),
                    CheckedLocalBinding {
                        kind: CheckedBinderKind::Local,
                        site: self.structural_binder_site(
                            declaration,
                            path,
                            vec![Self::BINDER_FOR, 0],
                        ),
                        type_name: iterator_type,
                    },
                );
                for (index, statement) in body.iter().enumerate() {
                    let child_path = Self::path_child(path, index + 1);
                    self.record_stmt(declaration, statement, &child_path, false);
                }
                self.pop_scope();
            }
            Stmt::While(condition, body) => {
                let condition_path = Self::path_child(path, 0);
                self.record_expr(declaration, condition, &condition_path, false, false);
                self.push_scope();
                for (index, statement) in body.iter().enumerate() {
                    let child_path = Self::path_child(path, index + 1);
                    self.record_stmt(declaration, statement, &child_path, false);
                }
                self.pop_scope();
            }
            Stmt::Send(target, message) => {
                let target_path = Self::path_child(path, 0);
                let message_path = Self::path_child(path, 1);
                self.record_expr(declaration, target, &target_path, false, false);
                self.record_expr(declaration, message, &message_path, false, false);
            }
            Stmt::StreamBind(name, expression) => {
                let expression_path = Self::path_child(path, 0);
                self.record_expr(declaration, expression, &expression_path, false, false);
                if !top_level {
                    self.define_local(
                        name.clone(),
                        CheckedLocalBinding {
                            kind: CheckedBinderKind::Local,
                            site: self.structural_binder_site(
                                declaration,
                                path,
                                vec![Self::BINDER_PATTERN, 0],
                            ),
                            type_name: None,
                        },
                    );
                }
            }
            Stmt::StreamSub(expression, arms) => {
                let expression_path = Self::path_child(path, 0);
                self.record_expr(declaration, expression, &expression_path, false, false);
                let mut child_index = 1;
                for (arm_index, arm) in arms.iter().enumerate() {
                    self.push_scope();
                    self.define_pattern(
                        declaration,
                        path,
                        &arm.pat,
                        vec![arm_index as u32],
                        CheckedBinderKind::Pattern,
                        None,
                    );
                    if let Some(guard) = &arm.guard {
                        let guard_path = Self::path_child(path, child_index);
                        self.record_expr(declaration, guard, &guard_path, false, false);
                        child_index += 1;
                    }
                    let body_path = Self::path_child(path, child_index);
                    self.record_expr(declaration, &arm.body, &body_path, false, false);
                    child_index += 1;
                    self.pop_scope();
                }
            }
            Stmt::Invariant {
                subject, predicate, ..
            } => {
                self.push_scope();
                let subject_path = Self::path_child(path, 0);
                self.define_rule_head_argument(declaration, subject, &subject_path, None);
                self.record_expr(declaration, subject, &subject_path, false, false);
                let predicate_path = Self::path_child(path, 1);
                self.record_expr(declaration, predicate, &predicate_path, false, false);
                self.pop_scope();
            }
            Stmt::Prove {
                capture,
                pass_block,
                else_block,
                ..
            } => {
                self.push_scope();
                if let Some(capture) = capture {
                    self.define_local(
                        capture.clone(),
                        CheckedLocalBinding {
                            kind: CheckedBinderKind::Local,
                            site: self.structural_binder_site(
                                declaration,
                                path,
                                vec![Self::BINDER_CAPTURE, 0],
                            ),
                            type_name: None,
                        },
                    );
                }
                let mut child_index = 0;
                if let Some(block) = pass_block {
                    for statement in block {
                        let child_path = Self::path_child(path, child_index);
                        self.record_stmt(declaration, statement, &child_path, false);
                        child_index += 1;
                    }
                }
                if let Some(block) = else_block {
                    for statement in block {
                        let child_path = Self::path_child(path, child_index);
                        self.record_stmt(declaration, statement, &child_path, false);
                        child_index += 1;
                    }
                }
                self.pop_scope();
            }
            Stmt::Explore(query) => self.record_explore(declaration, query, path),
            Stmt::Assert(_, arguments) | Stmt::Retract(_, arguments) => {
                for (index, argument) in arguments.iter().enumerate() {
                    let child_path = Self::path_child(path, index);
                    self.record_expr(declaration, argument, &child_path, false, false);
                }
            }
            Stmt::Expr(expression) => {
                let child_path = Self::path_child(path, 0);
                self.record_expr(declaration, expression, &child_path, false, false);
            }
            Stmt::Use(_)
            | Stmt::Import(_)
            | Stmt::QualifiedImport(_, _)
            | Stmt::HashImport(_, _)
            | Stmt::Depend(_, _)
            | Stmt::RustBlock(_)
            | Stmt::Abort => {}
        }
    }

    fn record_explore(&mut self, declaration: &SourcedStmt, query: &ExploreQuery, path: &[u32]) {
        self.push_scope();
        let mut child_index = 0;
        let mut semantic_bindings = BTreeMap::<String, CheckedLocalBinding>::new();
        for (binding_index, binding) in query.source.bindings.iter().enumerate() {
            let expression_path = Self::path_child(path, child_index);
            let expression = match &binding.kind {
                ExploreSourceBindingKind::Singleton { value } => value,
                ExploreSourceBindingKind::Finite { domain } => domain,
            };
            let locals = self.type_locals();
            let inferred = match &binding.kind {
                ExploreSourceBindingKind::Singleton { .. } => {
                    self.infer_expr_type_name_in_active_scope(expression, &locals)
                }
                ExploreSourceBindingKind::Finite { .. } => self
                    .checker
                    .explore_domain_item_ty_with_locals(expression, &locals)
                    .map(|ty| TypeChecker::canonical_explore_ty_name(&ty)),
            };
            self.record_expr(declaration, expression, &expression_path, false, false);
            let local = CheckedLocalBinding {
                kind: CheckedBinderKind::ExploreValue,
                site: self.structural_binder_site(
                    declaration,
                    &expression_path,
                    vec![Self::BINDER_EXPLORE, binding_index as u32],
                ),
                type_name: inferred,
            };
            self.define_local(binding.name.clone(), local.clone());
            if matches!(binding.name.as_str(), "before" | "context") {
                semantic_bindings.insert(binding.name.clone(), local);
            }
            child_index += 1;
        }
        self.pop_scope();
        self.push_scope();
        for (name, binding) in semantic_bindings {
            self.define_local(name, binding);
        }

        let successor_path = Self::path_child(path, child_index);
        let successor_expression = match &query.successor.kind {
            ExploreSuccessorKind::Singleton { value } => value,
            ExploreSuccessorKind::Finite { domain } => domain,
        };
        let successor_type = match &query.successor.kind {
            ExploreSuccessorKind::Singleton { .. } => {
                self.infer_expr_type_name_in_active_scope(successor_expression, &self.type_locals())
            }
            ExploreSuccessorKind::Finite { .. } => self
                .checker
                .explore_domain_item_ty_with_locals(successor_expression, &self.type_locals())
                .map(|ty| TypeChecker::canonical_explore_ty_name(&ty)),
        };
        self.record_expr(
            declaration,
            successor_expression,
            &successor_path,
            false,
            false,
        );
        self.define_local(
            "after".to_string(),
            CheckedLocalBinding {
                kind: CheckedBinderKind::ExploreValue,
                site: self.structural_binder_site(
                    declaration,
                    &successor_path,
                    vec![Self::BINDER_EXPLORE_ROLE, 2],
                ),
                type_name: successor_type,
            },
        );
        child_index += 1;

        for admission in &query.admissions {
            let expression_path = Self::path_child(path, child_index);
            self.record_expr(
                declaration,
                &admission.predicate,
                &expression_path,
                false,
                false,
            );
            child_index += 1;
        }
        if let Some(predicate) = query.selection.predicate() {
            let expression_path = Self::path_child(path, child_index);
            self.record_expr(declaration, predicate, &expression_path, false, false);
            child_index += 1;
        }

        let before_type = self
            .local("before")
            .and_then(|binding| binding.type_name.clone());
        let context_type = self
            .local("context")
            .and_then(|binding| binding.type_name.clone());
        for (node_index, node) in query.analysis.iter().enumerate() {
            match node {
                ExploreAnalysisNode::Result(result) => {
                    self.push_scope();
                    for (field_index, (name, type_name)) in
                        explore_result_input_row_bindings(&result.input)
                            .iter()
                            .enumerate()
                    {
                        self.define_local(
                            (*name).to_string(),
                            CheckedLocalBinding {
                                kind: CheckedBinderKind::ExploreValue,
                                site: self.structural_binder_site(
                                    declaration,
                                    path,
                                    vec![
                                        Self::BINDER_EXPLORE_RESULT_INPUT,
                                        node_index as u32,
                                        field_index as u32,
                                    ],
                                ),
                                type_name: Some((*type_name).to_string()),
                            },
                        );
                    }
                    if let ExploreResultGrain::GroupBy { fields, .. } = &result.grain {
                        for (field_index, field) in fields.iter().enumerate() {
                            let expression_path = Self::path_child(path, child_index);
                            self.record_expr(
                                declaration,
                                &field.value,
                                &expression_path,
                                false,
                                false,
                            );
                            let type_name =
                                self.recorded_expression_type_name(declaration, &expression_path);
                            self.define_explore_result_alias(
                                declaration,
                                &field.name,
                                &expression_path,
                                Self::EXPLORE_RESULT_GROUP,
                                node_index,
                                field_index,
                                type_name,
                            );
                            child_index += 1;
                        }
                    }
                    for (field_index, field) in result.measures.iter().enumerate() {
                        let expression_path = Self::path_child(path, child_index);
                        self.record_expr(declaration, &field.value, &expression_path, false, false);
                        let type_name =
                            self.recorded_expression_type_name(declaration, &expression_path);
                        self.define_explore_result_alias(
                            declaration,
                            &field.name,
                            &expression_path,
                            Self::EXPLORE_RESULT_MEASURE,
                            node_index,
                            field_index,
                            type_name,
                        );
                        child_index += 1;
                    }
                    for (field_index, field) in result.aggregates.iter().enumerate() {
                        let expression_path = Self::path_child(path, child_index);
                        let value = match &field.reducer {
                            ExploreAggregateReducer::CountDistinct { value } => value,
                        };
                        self.record_expr(declaration, value, &expression_path, false, false);
                        self.define_explore_result_alias(
                            declaration,
                            &field.name,
                            &expression_path,
                            Self::EXPLORE_RESULT_AGGREGATE,
                            node_index,
                            field_index,
                            Some("Int".to_string()),
                        );
                        child_index += 1;
                    }
                    for (field_index, field) in result.select.iter().enumerate() {
                        let expression_path = Self::path_child(path, child_index);
                        self.record_expr(declaration, &field.value, &expression_path, false, false);
                        let type_name =
                            self.recorded_expression_type_name(declaration, &expression_path);
                        self.define_explore_result_alias(
                            declaration,
                            &field.name,
                            &expression_path,
                            Self::EXPLORE_RESULT_SELECT,
                            node_index,
                            field_index,
                            type_name,
                        );
                        child_index += 1;
                    }
                    if let Some(choice) = &result.choose {
                        match choice {
                            ExploreResultChoice::Optimize { objective, .. } => {
                                let expression_path = Self::path_child(path, child_index);
                                self.record_expr(
                                    declaration,
                                    objective,
                                    &expression_path,
                                    false,
                                    false,
                                );
                                child_index += 1;
                            }
                            ExploreResultChoice::Pareto { objectives, .. } => {
                                for objective in objectives {
                                    let expression_path = Self::path_child(path, child_index);
                                    self.record_expr(
                                        declaration,
                                        &objective.value,
                                        &expression_path,
                                        false,
                                        false,
                                    );
                                    child_index += 1;
                                }
                            }
                        }
                    }
                    self.pop_scope();
                }
                ExploreAnalysisNode::Mechanisms(request) => {
                    let expression_path = Self::path_child(path, child_index);
                    self.push_scope();
                    for (role_index, (name, type_name)) in [
                        ("state", before_type.clone()),
                        ("context", context_type.clone()),
                    ]
                    .into_iter()
                    .enumerate()
                    {
                        self.define_local(
                            name.to_string(),
                            CheckedLocalBinding {
                                kind: CheckedBinderKind::ExploreValue,
                                site: self.structural_binder_site(
                                    declaration,
                                    &expression_path,
                                    vec![Self::BINDER_EXPLORE_OBSERVATION_STATE, role_index as u32],
                                ),
                                type_name,
                            },
                        );
                    }
                    self.record_expr(
                        declaration,
                        &request.endpoint_template,
                        &expression_path,
                        false,
                        false,
                    );
                    self.pop_scope();
                    child_index += 1;
                }
            }
        }
        self.pop_scope();
    }

    fn recorded_expression_type_name(
        &self,
        declaration: &SourcedStmt,
        expression_path: &[u32],
    ) -> Option<String> {
        let site = self.expression_site(declaration, expression_path);
        self.artifacts
            .expressions
            .get(&site)
            .and_then(|resolution| match &resolution.resolved_type {
                CheckedExpressionType::Resolved(ty) => Some(ty.to_string()),
                CheckedExpressionType::Callable { .. }
                | CheckedExpressionType::CallableReference
                | CheckedExpressionType::PolymorphicEmptyList
                | CheckedExpressionType::Unsupported => None,
            })
    }

    #[allow(clippy::too_many_arguments)]
    fn define_explore_result_alias(
        &mut self,
        declaration: &SourcedStmt,
        name: &str,
        expression_path: &[u32],
        result_kind: u32,
        result_index: usize,
        field_index: usize,
        type_name: Option<String>,
    ) {
        self.define_local(
            name.to_string(),
            CheckedLocalBinding {
                kind: CheckedBinderKind::ExploreValue,
                site: self.structural_binder_site(
                    declaration,
                    expression_path,
                    vec![
                        Self::BINDER_EXPLORE_RESULT,
                        result_kind,
                        result_index as u32,
                        field_index as u32,
                    ],
                ),
                type_name,
            },
        );
    }

    fn resolved_call_target_type(&self, target: &CheckedCallTarget) -> Option<Ty> {
        match target {
            CheckedCallTarget::Constructor { owner_type, .. } => {
                parse_type_annotation(owner_type).ok()
            }
            CheckedCallTarget::Function { callable, arity }
                if callable.declaration.declaration.kind == DeclarationKind::Function
                    && callable.structural_path.is_empty() =>
            {
                self.checker
                    .explore_function_return_types_by_arity
                    .get(&(callable.declaration.declaration.name.to_string(), *arity))
                    .cloned()
            }
            CheckedCallTarget::Function { .. } => None,
            CheckedCallTarget::BoundCallable { result_type, .. } => {
                parse_type_annotation(result_type).ok()
            }
            CheckedCallTarget::RuleFamily(key) => self
                .checker
                .rule_dispatch_return_types
                .get(key)
                .and_then(|name| parse_type_annotation(name).ok()),
            CheckedCallTarget::ScopedMember {
                owner_type,
                member,
                arity,
                rule_family,
            } => match rule_family {
                Some(key) => self
                    .checker
                    .rule_dispatch_return_types
                    .get(key)
                    .and_then(|name| parse_type_annotation(name).ok()),
                None => self
                    .checker
                    .scoped_member_return_type(owner_type, member, *arity)
                    .and_then(|name| parse_type_annotation(&name).ok()),
            },
            CheckedCallTarget::Builtin { .. } => None,
        }
    }

    /// Expected constructor-field types aligned to source argument order.
    /// This closes inference gaps that are inherently contextual: empty
    /// collection producers have no member from which to infer their type,
    /// while an exact constructor field supplies it unambiguously.
    fn constructor_argument_types(
        &self,
        target: Option<&CheckedCallTarget>,
        arguments: &[Expr],
        named_arguments: Option<&CheckedNamedArgumentOrder>,
    ) -> Vec<Option<Ty>> {
        let Some(CheckedCallTarget::Constructor {
            owner_type,
            variant,
            ..
        }) = target
        else {
            return vec![None; arguments.len()];
        };
        let Some(signatures) = self.checker.constructor_signatures.get(variant.as_ref()) else {
            return vec![None; arguments.len()];
        };
        let matching = signatures
            .iter()
            .filter(|signature| {
                signature.parent == owner_type.as_ref() && signature.matches_args(arguments)
            })
            .collect::<Vec<_>>();
        let [signature] = matching.as_slice() else {
            return vec![None; arguments.len()];
        };
        let canonical_types = signature
            .field_tys
            .iter()
            .map(|ty| ty.as_deref().and_then(|ty| parse_type_annotation(ty).ok()))
            .collect::<Vec<_>>();
        let mut source_types = vec![None; arguments.len()];
        match named_arguments {
            Some(order) => {
                for (canonical_index, source_index) in
                    order.canonical_source_indices.iter().copied().enumerate()
                {
                    if let (Some(source), Some(expected)) = (
                        source_types.get_mut(source_index),
                        canonical_types.get(canonical_index),
                    ) {
                        *source = expected.clone();
                    }
                }
            }
            None => {
                for (source, expected) in source_types.iter_mut().zip(canonical_types) {
                    *source = expected;
                }
            }
        }
        source_types
    }

    fn contextualize_empty_collection(
        &mut self,
        declaration: &SourcedStmt,
        path: &[u32],
        expression: &Expr,
        expected: Option<&Ty>,
    ) {
        let site = self.expression_site(declaration, path);
        let contextual_type_matches = match (&expression.kind, expected) {
            (ExprKind::List(items), Some(Ty::App(constructor, arguments))) if items.is_empty() => {
                matches!(constructor.as_ref(), Ty::Name(name) if name == "List")
                    && arguments.len() == 1
            }
            (ExprKind::App(function, arguments), Some(Ty::App(constructor, type_arguments)))
                if arguments.is_empty() =>
            {
                let builtin = match &function.kind {
                    ExprKind::Var(name) if name == "map_new" => Some(("Map", 2, "map_new")),
                    ExprKind::Var(name) if name == "set_new" => Some(("Set", 1, "set_new")),
                    _ => None,
                };
                builtin.is_some_and(|(name, arity, builtin_name)| {
                    matches!(constructor.as_ref(), Ty::Name(actual) if actual == name)
                        && type_arguments.len() == arity
                        && matches!(
                            self.artifacts.expressions.get(&site).and_then(|resolution| resolution.call_target.as_ref()),
                            Some(CheckedCallTarget::Builtin { canonical_name, arity: 0 })
                                if canonical_name.as_ref() == builtin_name
                        )
                })
            }
            _ => false,
        };
        if !contextual_type_matches {
            return;
        }
        let only_contextual_gap =
            self.artifacts
                .unsupported_sites
                .get(&site)
                .is_some_and(|issues| {
                    !issues.is_empty()
                        && issues
                            .iter()
                            .all(|issue| matches!(issue, CheckedResolutionIssue::TypeNotResolved))
                });
        let Some(resolution) = self.artifacts.expressions.get_mut(&site) else {
            return;
        };
        if matches!(
            resolution.resolved_type,
            CheckedExpressionType::PolymorphicEmptyList
        ) || (only_contextual_gap
            && matches!(resolution.resolved_type, CheckedExpressionType::Unsupported))
        {
            resolution.resolved_type = CheckedExpressionType::Resolved(
                expected
                    .expect("contextual collection type was checked")
                    .clone(),
            );
            self.artifacts.unsupported_sites.remove(&site);
        }
    }

    /// Return an exact type only when the recorded expression subtree is
    /// already sealed. This prevents a legacy best-effort inference elsewhere
    /// in an unresolved expression from becoming proof for bidirectional
    /// constructor resolution.
    fn sealed_resolved_type(&self, site: &ExprSiteId) -> Option<Ty> {
        if self
            .artifacts
            .unsupported_sites
            .subtree(site)
            .next()
            .is_some()
        {
            return None;
        }
        match self.artifacts.expressions.get(site)?.resolved_type.clone() {
            CheckedExpressionType::Resolved(ty) => Some(ty),
            CheckedExpressionType::Callable { .. }
            | CheckedExpressionType::CallableReference
            | CheckedExpressionType::PolymorphicEmptyList
            | CheckedExpressionType::Unsupported => None,
        }
    }

    /// Named arguments are parser-internal `__named_arg(name, value)`
    /// wrappers. When constructor-field context refines a polymorphic child
    /// after the wrapper was first recorded, carry that exact type back to the
    /// wrapper so the checked artifact has no stale inference gap.
    fn contextualize_named_argument_wrapper(
        &mut self,
        declaration: &SourcedStmt,
        path: &[u32],
        expression: &Expr,
        expected: Option<&Ty>,
    ) {
        let (Some((_, _)), Some(expected)) = (named_arg_parts(expression), expected) else {
            return;
        };
        let site = self.expression_site(declaration, path);
        let only_contextual_gap =
            self.artifacts
                .unsupported_sites
                .get(&site)
                .is_some_and(|issues| {
                    issues.len() == 1 && issues.contains(&CheckedResolutionIssue::TypeNotResolved)
                });
        if !only_contextual_gap {
            return;
        }
        let value_path = Self::path_child(path, 2);
        let value_site = self.expression_site(declaration, &value_path);
        let Some(value_type) = self.sealed_resolved_type(&value_site) else {
            return;
        };
        if TypeChecker::canonical_explore_ty_name(&value_type)
            != TypeChecker::canonical_explore_ty_name(expected)
        {
            return;
        }
        let Some(resolution) = self.artifacts.expressions.get_mut(&site) else {
            return;
        };
        if !matches!(
            resolution.call_target.as_ref(),
            Some(CheckedCallTarget::Builtin {
                canonical_name,
                arity: 2,
            }) if canonical_name.as_ref() == NAMED_ARG_MARKER
        ) || !matches!(resolution.resolved_type, CheckedExpressionType::Unsupported)
        {
            return;
        }
        resolution.resolved_type = CheckedExpressionType::Resolved(expected.clone());
        self.artifacts.unsupported_sites.remove(&site);
    }

    /// Resolve a bare nullary constructor from an independently checked
    /// expected type. Constructor spellings may intentionally be shared by
    /// several ADTs; the checked owner occurrence, not the spelling or the
    /// runtime's flattened constructor value, is the semantic identity.
    fn contextualize_nullary_constructor(
        &mut self,
        declaration: &SourcedStmt,
        path: &[u32],
        expression: &Expr,
        expected: &Ty,
    ) {
        let ExprKind::Var(name) = &expression.kind else {
            return;
        };
        let owner_type = match expected {
            Ty::Name(name) => name.clone(),
            Ty::App(constructor, _) => {
                let Some(name) = type_name(constructor.as_ref()) else {
                    return;
                };
                name.to_string()
            }
            Ty::Optional(_) => "Option".to_string(),
            Ty::Arrow(_, _)
            | Ty::Ref(_)
            | Ty::MutRef(_)
            | Ty::Shared(_)
            | Ty::Var(_)
            | Ty::Unit
            | Ty::Hole => return,
        };
        let site = self.expression_site(declaration, path);
        let ambiguity =
            CheckedResolutionIssue::AmbiguousValueBinding(name.clone().into_boxed_str());
        if !self
            .artifacts
            .unsupported_sites
            .get(&site)
            .is_some_and(|issues| issues.len() == 1 && issues.contains(&ambiguity))
        {
            return;
        }

        // The same issue also represents collisions with runtime functions,
        // rule values, and top-level bindings. Expected result types cannot
        // change runtime name precedence, so only a constructor-only
        // ambiguity is eligible for contextual refinement.
        if self.local(name).is_some()
            || self.top_level_bindings.contains_key(name)
            || !self.bare_runtime_callable_candidates(name).is_empty()
            || !self.effective_rule_value_candidates(name).is_empty()
            || self.qualified_aliases.contains_key(name)
            || self.duplicate_rule_scope_owners.contains(name)
        {
            return;
        }

        let Some(signatures) = self.checker.constructor_signatures.get(name) else {
            return;
        };
        let matching = signatures
            .iter()
            .filter(|signature| signature.parent == owner_type && signature.arity() == 0)
            .collect::<Vec<_>>();
        if matching.is_empty() {
            return;
        }

        let mut candidates = BTreeSet::new();
        for signature in matching {
            let Ok((declaration_id, variant_index)) =
                self.indexed_constructor_identity(signature, name)
            else {
                return;
            };
            let Some(identity) = self.checked_constructor_identity(&owner_type, name) else {
                return;
            };
            if !Self::constructor_signature_matches_identity(signature, &identity) {
                return;
            }
            candidates.insert((declaration_id, variant_index, identity));
        }
        if candidates.len() != 1 {
            return;
        }
        let (declaration_id, variant_index, identity) = candidates
            .into_iter()
            .next()
            .expect("one contextual constructor candidate was checked");
        let Some(resolution) = self.artifacts.expressions.get_mut(&site) else {
            return;
        };
        resolution.resolved_type = CheckedExpressionType::Resolved(expected.clone());
        resolution.value_binding = Some(CheckedValueBinding::Constructor {
            declaration: declaration_id,
            owner_type: owner_type.into_boxed_str(),
            variant: name.clone().into_boxed_str(),
            variant_index,
        });
        resolution.exact_constructor = Some(identity);
        self.artifacts.unsupported_sites.remove(&site);
    }

    fn record_pipe_transform(&mut self, declaration: &SourcedStmt, transform: &Expr, path: &[u32]) {
        let site = self.expression_site(declaration, path);
        self.issue(
            &site,
            CheckedResolutionIssue::UnsupportedExpression(
                "pipe transform uses runtime value dispatch".into(),
            ),
        );
        let pipe_resolution = CheckedExpressionResolution {
            resolved_type: CheckedExpressionType::Unsupported,
            value_binding: None,
            call_target: None,
            field: None,
            named_arguments: None,
            exact_constructor: None,
        };
        self.artifacts
            .expressions
            .insert(site.clone(), pipe_resolution.clone());
        let pipe_issues = self.artifacts.unsupported_sites.get(&site).cloned();

        // Reuse canonical recursion and lexical-scope logic to retain every
        // descendant site. The ordinary App decision at this root is discarded:
        // runtime Pipe evaluates the transform as a value, whose collision
        // precedence differs from direct App dispatch.
        self.record_expr(declaration, transform, path, false, false);
        self.artifacts
            .expressions
            .insert(site.clone(), pipe_resolution);
        match pipe_issues {
            Some(issues) => {
                self.artifacts.unsupported_sites.insert(site, issues);
            }
            None => {
                self.artifacts.unsupported_sites.remove(&site);
            }
        }
    }

    fn record_expr(
        &mut self,
        declaration: &SourcedStmt,
        expression: &Expr,
        path: &[u32],
        suppress_call: bool,
        declaration_callable: bool,
    ) {
        let site = self.expression_site(declaration, path);
        if declaration.id.kind == DeclarationKind::RuleScope
            && self
                .duplicate_rule_scope_owners
                .contains(declaration.id.name.as_ref())
        {
            self.issue(
                &site,
                CheckedResolutionIssue::UnsupportedExpression(
                    "expression belongs to a duplicate RuleScope owner".into(),
                ),
            );
        }
        let mut value_binding = None;
        let mut call_target = None;
        let mut named_arguments = None;
        let mut field_resolution = None;
        let mut exact_target_required = false;

        match &expression.kind {
            ExprKind::Var(name) if !declaration_callable => {
                value_binding = self.resolve_var(declaration, path, name);
            }
            ExprKind::App(function, arguments) if !suppress_call => {
                exact_target_required = true;
                (call_target, named_arguments) =
                    self.resolve_call(declaration, path, function, arguments, arguments.len());
            }
            ExprKind::Field(base, field) if !declaration_callable => {
                exact_target_required = true;
                field_resolution = self.resolve_field(declaration, path, base, field);
            }
            ExprKind::Pipe(_, _) => {
                exact_target_required = true;
                self.issue(
                    &site,
                    CheckedResolutionIssue::UnsupportedExpression(
                        "pipe expression uses runtime value dispatch".into(),
                    ),
                );
            }
            _ => {}
        }

        let target_type = call_target
            .as_ref()
            .and_then(|target| self.resolved_call_target_type(target));
        let resolved_field_type = match (&expression.kind, field_resolution.as_ref()) {
            (ExprKind::Field(_, field), Some(resolution)) => {
                self.resolved_field_type(resolution, field)
            }
            _ => None,
        };
        let constructor_argument_types = match &expression.kind {
            ExprKind::App(_, arguments) => self.constructor_argument_types(
                call_target.as_ref(),
                arguments,
                named_arguments.as_ref(),
            ),
            _ => Vec::new(),
        };
        let unsealed_exact_call_type = matches!(
            call_target.as_ref(),
            Some(
                CheckedCallTarget::Constructor { .. }
                    | CheckedCallTarget::Function { .. }
                    | CheckedCallTarget::BoundCallable { .. }
                    | CheckedCallTarget::RuleFamily(_)
                    | CheckedCallTarget::ScopedMember { .. }
            )
        ) && target_type.is_none();
        let unsealed_exact_field_type = field_resolution.is_some() && resolved_field_type.is_none();
        if (unsealed_exact_call_type || unsealed_exact_field_type) && !declaration_callable {
            self.issue(&site, CheckedResolutionIssue::TypeNotResolved);
        }
        let resolved_type = if declaration_callable {
            // A rule/function declaration name is not evaluated as a standalone
            // value by check_expr. The enclosing checked App/rule-family record
            // carries the exact decision, so no invented arrow type is emitted.
            CheckedExpressionType::Unsupported
        } else if exact_target_required && call_target.is_none() && field_resolution.is_none() {
            CheckedExpressionType::Unsupported
        } else if unsealed_exact_call_type || unsealed_exact_field_type {
            CheckedExpressionType::Unsupported
        } else if let Some(target_type) = target_type {
            CheckedExpressionType::Resolved(target_type)
        } else if let Some(field_type) = resolved_field_type {
            CheckedExpressionType::Resolved(field_type)
        } else if matches!(
            &value_binding,
            Some(CheckedValueBinding::Callable(_) | CheckedValueBinding::RuleFamily(_))
        ) {
            CheckedExpressionType::CallableReference
        } else {
            self.infer_type(declaration, path, expression)
        };
        if matches!(
            &resolved_type,
            CheckedExpressionType::Resolved(Ty::Name(name))
                if self.duplicate_rule_scope_owners.contains(name)
        ) {
            self.issue(
                &site,
                CheckedResolutionIssue::UnsupportedExpression(
                    "expression has a duplicate RuleScope type".into(),
                ),
            );
        }
        let exact_constructor = value_binding
            .as_ref()
            .and_then(|binding| match binding {
                CheckedValueBinding::Constructor {
                    owner_type,
                    variant,
                    ..
                } => self.checked_constructor_identity(owner_type, variant),
                _ => None,
            })
            .or_else(|| {
                call_target.as_ref().and_then(|target| match target {
                    CheckedCallTarget::Constructor {
                        owner_type,
                        variant,
                        ..
                    } => self.checked_constructor_identity(owner_type, variant),
                    _ => None,
                })
            });
        // A statically resolved bare call already carries the exact callable,
        // constructor, rule-family, or builtin identity on its App site. The
        // semantic closure hashes that parent target and never evaluates the
        // operator Var as a standalone value, so avoid repeating global value
        // lookup for this child. Dynamic operators and genuinely first-class
        // callable values still take the ordinary resolution path.
        let static_bare_operator = call_target
            .as_ref()
            .is_some_and(|target| !matches!(target, CheckedCallTarget::BoundCallable { .. }))
            && matches!(&expression.kind, ExprKind::App(function, _) if matches!(&function.kind, ExprKind::Var(_)));
        let static_scoped_member_operator = matches!(
            call_target.as_ref(),
            Some(CheckedCallTarget::ScopedMember { .. })
        );
        let contextual_lambda_parameters = match &expression.kind {
            ExprKind::App(_, arguments) => {
                self.contextual_builtin_lambda_parameters(call_target.as_ref(), arguments)
            }
            _ => None,
        };
        let contextual_callback_arity = match &expression.kind {
            ExprKind::App(_, arguments) => {
                Self::contextual_builtin_callback_arity(call_target.as_ref(), arguments.len())
            }
            _ => None,
        };
        let contextual_callback_result_type = match &expression.kind {
            ExprKind::App(_, arguments) => {
                self.contextual_builtin_callback_result_type(call_target.as_ref(), arguments)
            }
            _ => None,
        };
        self.artifacts.expressions.insert(
            site.clone(),
            CheckedExpressionResolution {
                resolved_type,
                value_binding,
                call_target,
                field: field_resolution,
                named_arguments,
                exact_constructor,
            },
        );

        match &expression.kind {
            ExprKind::App(function, arguments) => {
                let function_path = Self::path_child(path, 0);
                let internal_marker = matches!(
                    &function.kind,
                    ExprKind::Var(name)
                        if matches!(
                            name.as_str(),
                            NAMED_ARG_MARKER | "__typed" | PATHOF_MARKER | REFOF_MARKER
                        )
                );
                let typed_marker =
                    matches!(&function.kind, ExprKind::Var(name) if name == "__typed");
                self.record_expr(
                    declaration,
                    function,
                    &function_path,
                    false,
                    suppress_call
                        || internal_marker
                        || static_bare_operator
                        || static_scoped_member_operator,
                );
                for (index, argument) in arguments.iter().enumerate() {
                    let argument_path = Self::path_child(path, index + 1);
                    let contextual_argument = contextual_lambda_parameters
                        .as_ref()
                        .filter(|(argument_index, _)| *argument_index == index)
                        .and_then(|(_, parameter_types)| {
                            Self::contextually_typed_lambda(argument, parameter_types)
                        });
                    self.record_expr(
                        declaration,
                        contextual_argument.as_ref().unwrap_or(argument),
                        &argument_path,
                        false,
                        typed_marker && index == 1,
                    );
                    if contextual_callback_arity
                        .is_some_and(|(argument_index, _)| argument_index == index)
                    {
                        let expected_parameters = contextual_lambda_parameters
                            .as_ref()
                            .filter(|(argument_index, _)| *argument_index == index)
                            .map(|(_, parameter_types)| parameter_types.as_ref());
                        let expected_result = contextual_callback_result_type
                            .as_ref()
                            .filter(|(argument_index, _)| *argument_index == index)
                            .map(|(_, result_type)| result_type);
                        self.validate_contextual_callback_contract(
                            &self.expression_site(declaration, &argument_path),
                            contextual_callback_arity
                                .expect("contextual callback index was checked")
                                .1,
                            expected_parameters,
                            expected_result,
                        );
                    }
                    let expected = constructor_argument_types
                        .get(index)
                        .and_then(Option::as_ref)
                        .or_else(|| {
                            contextual_lambda_parameters.as_ref().and_then(
                                |(callback_index, parameter_types)| {
                                    (*callback_index == 2 && index == 1)
                                        .then(|| parameter_types.first())
                                        .flatten()
                                },
                            )
                        });
                    match named_arg_parts(argument) {
                        Some((_, value)) => {
                            let value_path = Self::path_child(&argument_path, 2);
                            self.contextualize_empty_collection(
                                declaration,
                                &value_path,
                                value,
                                expected,
                            );
                            self.contextualize_named_argument_wrapper(
                                declaration,
                                &argument_path,
                                argument,
                                expected,
                            );
                        }
                        None => self.contextualize_empty_collection(
                            declaration,
                            &argument_path,
                            argument,
                            expected,
                        ),
                    }
                }
            }
            ExprKind::Lambda(parameters, body) => {
                self.push_scope();
                for (index, parameter) in parameters.iter().enumerate() {
                    self.define_parameter(declaration, path, index, parameter, &[]);
                }
                let body_path = Self::path_child(path, 0);
                self.record_expr(declaration, body, &body_path, false, false);
                self.pop_scope();
            }
            ExprKind::BinOp(operator, left, right) => {
                let left_path = Self::path_child(path, 0);
                self.record_expr(declaration, left, &left_path, false, false);
                let right_path = Self::path_child(path, 1);
                self.record_expr(declaration, right, &right_path, false, false);
                if matches!(operator.as_str(), "==" | "!=") {
                    let left_site = self.expression_site(declaration, &left_path);
                    let right_site = self.expression_site(declaration, &right_path);
                    // Capture both contexts before refining either side. Two
                    // ambiguous constructors therefore cannot prove one
                    // another's owner in a circular fashion.
                    let left_type = self.sealed_resolved_type(&left_site);
                    let right_type = self.sealed_resolved_type(&right_site);
                    if let Some(expected) = right_type.as_ref() {
                        self.contextualize_nullary_constructor(
                            declaration,
                            &left_path,
                            left,
                            expected,
                        );
                    }
                    if let Some(expected) = left_type.as_ref() {
                        self.contextualize_nullary_constructor(
                            declaration,
                            &right_path,
                            right,
                            expected,
                        );
                    }
                }
            }
            ExprKind::Index(left, right) => {
                let left_path = Self::path_child(path, 0);
                self.record_expr(declaration, left, &left_path, false, false);
                let right_path = Self::path_child(path, 1);
                self.record_expr(declaration, right, &right_path, false, false);
            }
            ExprKind::Pipe(left, transform) => {
                let left_path = Self::path_child(path, 0);
                self.record_expr(declaration, left, &left_path, false, false);
                let transform_path = Self::path_child(path, 1);
                self.record_pipe_transform(declaration, transform, &transform_path);
            }
            ExprKind::UnOp(_, operand) | ExprKind::Try(operand) => {
                let operand_path = Self::path_child(path, 0);
                self.record_expr(declaration, operand, &operand_path, false, false);
            }
            ExprKind::If(condition, then_expression, else_expression) => {
                for (index, child) in [condition.as_ref(), then_expression, else_expression]
                    .into_iter()
                    .enumerate()
                {
                    let child_path = Self::path_child(path, index);
                    self.record_expr(declaration, child, &child_path, false, false);
                }
            }
            ExprKind::Match(scrutinee, arms) => {
                let scrutinee_path = Self::path_child(path, 0);
                self.record_expr(declaration, scrutinee, &scrutinee_path, false, false);
                let locals = self.type_locals();
                let subject_type = self.infer_expr_type_name_in_active_scope(scrutinee, &locals);
                let mut child_index = 1;
                for (arm_index, arm) in arms.iter().enumerate() {
                    self.push_scope();
                    let pattern_path = vec![arm_index as u32];
                    self.define_pattern(
                        declaration,
                        path,
                        &arm.pat,
                        pattern_path.clone(),
                        CheckedBinderKind::Pattern,
                        subject_type.clone(),
                    );
                    if let Some(pattern_site) = self.first_unresolved_constructor_pattern(
                        declaration,
                        path,
                        &arm.pat,
                        pattern_path,
                    ) {
                        self.issue(
                            &site,
                            CheckedResolutionIssue::ConstructorPatternNotResolved(pattern_site),
                        );
                    }
                    if let Some(guard) = &arm.guard {
                        let guard_path = Self::path_child(path, child_index);
                        self.record_expr(declaration, guard, &guard_path, false, false);
                        child_index += 1;
                    }
                    let body_path = Self::path_child(path, child_index);
                    self.record_expr(declaration, &arm.body, &body_path, false, false);
                    child_index += 1;
                    self.pop_scope();
                }
            }
            ExprKind::Block(statements) => {
                self.push_scope();
                for (index, statement) in statements.iter().enumerate() {
                    let child_path = Self::path_child(path, index);
                    self.record_stmt(declaration, statement, &child_path, false);
                }
                self.pop_scope();
            }
            ExprKind::Field(base, _) => {
                let base_path = Self::path_child(path, 0);
                self.record_expr(declaration, base, &base_path, false, false);
            }
            ExprKind::List(items)
            | ExprKind::Tuple(items)
            | ExprKind::Conjunction(items)
            | ExprKind::Disjunction(items) => {
                for (index, item) in items.iter().enumerate() {
                    let item_path = Self::path_child(path, index);
                    self.record_expr(declaration, item, &item_path, false, false);
                }
            }
            ExprKind::Effect(_, arguments) => {
                for (index, argument) in arguments.iter().enumerate() {
                    let argument_path = Self::path_child(path, index);
                    self.record_expr(declaration, argument, &argument_path, false, false);
                }
            }
            ExprKind::Handle { handlers, body, .. } => {
                self.push_scope();
                self.define_local(
                    "resume".to_string(),
                    CheckedLocalBinding {
                        kind: CheckedBinderKind::HandlerParameter,
                        site: self.structural_binder_site(
                            declaration,
                            path,
                            vec![Self::BINDER_HANDLER, 0],
                        ),
                        type_name: None,
                    },
                );
                let body_path = Self::path_child(path, 0);
                self.record_expr(declaration, body, &body_path, false, false);
                for (handler_index, handler) in handlers.iter().enumerate() {
                    self.push_scope();
                    for (parameter_index, parameter) in handler.params.iter().enumerate() {
                        self.define_local(
                            parameter.clone(),
                            CheckedLocalBinding {
                                kind: CheckedBinderKind::HandlerParameter,
                                site: self.structural_binder_site(
                                    declaration,
                                    path,
                                    vec![
                                        Self::BINDER_HANDLER,
                                        (handler_index + 1) as u32,
                                        parameter_index as u32,
                                    ],
                                ),
                                type_name: None,
                            },
                        );
                    }
                    let handler_path = Self::path_child(path, handler_index + 1);
                    self.record_expr(declaration, &handler.body, &handler_path, false, false);
                    self.pop_scope();
                }
                self.pop_scope();
            }
            ExprKind::Var(_) | ExprKind::Lit(_) | ExprKind::Unit => {}
        }
    }
}

impl TypeChecker {
    /// Whether a concrete named type explicitly opts into a marker or ordinary
    /// trait. Empty marker implementations are recorded like method-bearing
    /// implementations, so tooling can use the language's normal trait model
    /// without inventing a parallel annotation registry.
    pub fn implements_trait(&self, trait_name: &str, for_type: &str) -> bool {
        self.impl_methods
            .contains_key(&(trait_name.to_string(), for_type.to_string()))
    }

    pub fn implementations_for_trait(&self, trait_name: &str) -> BTreeSet<String> {
        self.impl_methods
            .keys()
            .filter(|(implemented_trait, _)| implemented_trait == trait_name)
            .map(|(_, for_type)| for_type.clone())
            .collect()
    }

    pub fn new() -> Self {
        let mut tc = TypeChecker {
            functions: BTreeMap::new(),
            function_arities: BTreeMap::new(),
            function_params: BTreeMap::new(),
            function_params_by_arity: BTreeMap::new(),
            rule_param_types_by_arity: BTreeMap::new(),
            rule_arities: BTreeSet::new(),
            types: BTreeSet::new(),
            constructors: BTreeMap::new(),
            constructor_signatures: BTreeMap::new(),
            actor_message_arities: BTreeMap::new(),
            top_level_constructor_names: BTreeSet::new(),
            root_actor_runtime_symbols: BTreeSet::new(),
            actor_handle_scopes: vec![BTreeMap::new()],
            constructor_fields: BTreeMap::new(),
            type_variants: BTreeMap::new(),
            builtins: BTreeMap::new(),
            effect_ops: BTreeMap::new(),
            trait_methods: BTreeMap::new(),
            impl_methods: BTreeMap::new(),
            trait_method_receivers: BTreeMap::new(),
            impl_method_receivers: BTreeMap::new(),
            rule_scope_methods: BTreeMap::new(),
            rule_scope_method_params: BTreeMap::new(),
            rule_scope_value_methods: BTreeMap::new(),
            rule_scope_value_method_params: BTreeMap::new(),
            rule_scope_returning_rules: BTreeMap::new(),
            rule_scope_vars: vec![BTreeMap::new()],
            type_fields: BTreeMap::new(),
            type_field_types: BTreeMap::new(),
            type_field_tys: BTreeMap::new(),
            rule_return_types: BTreeMap::new(),
            rule_dispatch_return_types: BTreeMap::new(),
            rule_dispatch_return_issues: BTreeMap::new(),
            rule_dispatch_boolean_miss_safe_keys: BTreeSet::new(),
            rule_dispatch_keys: BTreeSet::new(),
            rule_dispatch_has_opaque_runtime_graph: false,
            plain_import_rule_dispatch_statements: Arc::from([]),
            analysis_program: CheckedAnalysisProgram::default(),
            resolved_program: CheckedResolvedProgramId::default(),
            checked_resolution_source_snapshot_coherent: true,
            explore_rule_return_types_by_arity: BTreeMap::new(),
            explore_function_return_types_by_arity: BTreeMap::new(),
            explore_function_definitions_by_arity: BTreeMap::new(),
            explore_function_return_issues: BTreeMap::new(),
            explore_rule_return_issues: BTreeMap::new(),
            inferring_exact_explore_rule_returns: false,
            checking_explore_query: false,
            explore_callable_expressions_by_arity: BTreeMap::new(),
            explore_scoped_callable_expressions: BTreeMap::new(),
            explore_rules_by_arity: BTreeMap::new(),
            explore_declared_effect_callables: BTreeSet::new(),
            explore_top_level_binding_initializers: BTreeMap::new(),
            explore_unsupported_top_level_bindings: BTreeSet::new(),
            rule_scope_member_return_types: BTreeMap::new(),
            active_rule_scope_inference: None,
            var_types: vec![BTreeMap::new()],
            module_exports: BTreeMap::new(),
            diagnostics: Vec::new(),
            scopes: vec![BTreeSet::new()],
            user_functions: BTreeSet::new(),
            reference_symbols: BTreeMap::new(),
            invariant_names: BTreeSet::new(),
            exploration_queries: Vec::new(),
            exploration_names: BTreeSet::new(),
            anonymous_exploration_count: 0,
            explore_non_rule_runtime_names: BTreeSet::new(),
            explore_inline_module_depth: 0,
            source_dir: None,
            imported: BTreeSet::new(),
            source_text: String::new(),
            error_context: Vec::new(),
        };
        // Register builtins (name -> arity)
        for &(name, arity) in &[
            // Math
            ("exp", 1),
            ("ln", 1),
            ("sqrt", 1),
            ("pow", 2),
            ("abs", 1),
            ("random_float", 0),
            ("random_choice", 1),
            ("shuffle", 1),
            ("sleep", 1),
            ("now", 0),
            ("time_diff", 2),
            ("regex_match", 2),
            ("regex_find", 2),
            ("regex_find_all", 2),
            ("regex_replace", 3),
            ("pair", 2),
            ("triple", 3),
            ("to_float", 1),
            ("round", 1),
            ("floor", 1),
            ("max_f", 2),
            ("min_f", 2),
            // Comptime type construction
            ("field", 2),
            ("struct_type", 1),
            ("enum_type", 1),
            // String
            ("split", 2),
            ("join", 2),
            ("trim", 1),
            ("contains", 2),
            ("starts_with", 2),
            ("ends_with", 2),
            ("replace", 3),
            ("to_upper", 1),
            ("to_lower", 1),
            ("substring", 3),
            ("char_at", 2),
            ("index_of", 2),
            ("format_float", 2),
            ("rust_debug", 1),
            ("parse_int", 1),
            ("parse_float", 1),
            ("string_chars", 1),
            ("string_length", 1),
            // File I/O
            ("read_file", 1),
            ("write_file", 2),
            ("append_file", 2),
            ("file_exists", 1),
            ("read_lines", 1),
            ("env_var", 1),
            ("process_run", 1),
            // JSON
            ("json_parse", 1),
            ("json_get", 2),
            ("json_string", 1),
            ("json_number", 1),
            ("json_bool", 1),
            ("json_array", 1),
            ("json_emit", 1),
            ("json_object", 1),
            // HTTP
            ("http_get", 1),
            ("http_post", 2),
            ("http_serve", 2),
            ("http_respond", 3),
            ("http_request_path", 1),
            ("http_request_method", 1),
            ("http_request_body", 1),
            // Database
            ("db_open", 1),
            ("db_exec", 2),
            ("db_query", 2),
            ("db_query_row", 2),
            ("db_insert", 2),
            ("db_close", 1),
            // Misc
            ("assert", 1),
            ("shared", 1),
            ("range", 2),
            // Collection/Functional
            ("map", 2),
            ("filter", 2),
            ("foldl", 3),
            ("sort", 1),
            ("sort_by", 2),
            ("list_min", 1),
            ("list_max", 1),
            ("is_some", 1),
            ("is_none", 1),
            ("any", 2),
            ("all", 2),
            ("find", 2),
            ("flat_map", 2),
            ("zip", 2),
            ("enumerate", 1),
            ("take_while", 2),
            ("drop_while", 2),
            ("sum_list", 1),
            ("distinct", 1),
            ("count_by", 2),
            ("partition", 2),
            ("chunked", 2),
            ("subscribe", 2),
            // Map (M24)
            ("map_new", 0),
            ("map_insert", 3),
            ("map_get", 2),
            ("map_get_or", 3),
            ("map_contains", 2),
            ("map_remove", 2),
            ("map_keys", 1),
            ("map_values", 1),
            ("map_entries", 1),
            ("map_len", 1),
            ("map_merge", 2),
            ("map_from", 1),
            // Set (M24)
            ("set_new", 0),
            ("set_insert", 2),
            ("set_contains", 2),
            ("set_remove", 2),
            ("set_len", 1),
            ("set_to_list", 1),
            ("set_union", 2),
            ("set_intersect", 2),
            ("set_diff", 2),
            ("set_from_list", 1),
            // Stream
            ("from_list", 1),
            ("watch", 1),
            ("scan", 3),
            ("merge", 2),
            ("take", 2),
            ("collect", 1),
            ("count", 1),
            ("skip", 2),
            ("window", 2),
            ("sum", 1),
            ("last", 1),
            ("combine_latest", 2),
            ("complete", 1),
            ("error", 2),
            ("take_until", 2),
            ("poll", 2),
            // New stream operators (M17b)
            ("tap", 2),
            ("catch", 2),
            ("first", 1),
            ("reduce", 3),
            ("start_with", 2),
            ("pairwise", 1),
            ("fst", 1),
            ("snd", 1),
            ("trd", 1),
            // Timing (M17)
            ("debounce", 2),
            ("throttle", 2),
            ("delay", 2),
            ("buffer", 2),
            ("timeout", 2),
            ("switch_map", 2),
            ("sample", 2),
        ] {
            tc.builtins.insert(name.to_string(), arity);
        }
        // Extra interpreter-only builtins not in codegen registry
        for &(name, arity) in &[
            ("show", 1),
            ("show_int", 1),
            ("show_float", 1),
            ("print", 1),
            ("length", 1),
            ("head", 1),
            ("tail", 1),
            ("not", 1),
            ("concat", 2),
            ("reverse", 1),
            ("push", 2),
            ("nth", 2),
            ("spawn", 2),
            ("ask", 2),
            ("teardown", 1),
            ("as_stream", 1),
            ("findall", 2),
            ("search", 2),
        ] {
            tc.builtins.entry(name.to_string()).or_insert(arity);
        }
        // Built-in types
        for name in &[
            "Int", "Float", "String", "Bool", "Char", "List", "Unit", "Option", "Result", "Pair",
            "Stream", "Subject", "Db", "TypeDef",
        ] {
            tc.types.insert(name.to_string());
        }
        // Prelude constructors
        tc.register_constructor_signature("Option", "None", true, vec![], vec![], vec![]);
        tc.register_constructor_signature(
            "Option",
            "Some",
            true,
            vec!["_0".into()],
            vec![None],
            vec![None],
        );
        tc.register_constructor_signature(
            "Result",
            "Ok",
            true,
            vec!["_0".into()],
            vec![None],
            vec![None],
        );
        tc.register_constructor_signature(
            "Result",
            "Err",
            true,
            vec!["_0".into()],
            vec![None],
            vec![None],
        );
        tc.register_constructor_signature(
            "Pair",
            "Pair",
            false,
            vec!["fst".into(), "snd".into()],
            vec![None, None],
            vec![None, None],
        );
        tc.register_constructor_signature("Bool", "True", true, vec![], vec![], vec![]);
        tc.register_constructor_signature("Bool", "False", true, vec![], vec![], vec![]);
        // Prelude type variants (for exhaustiveness checking)
        tc.type_variants
            .insert("Option".into(), vec!["Some".into(), "None".into()]);
        tc.type_variants
            .insert("Result".into(), vec!["Ok".into(), "Err".into()]);
        tc.type_variants
            .insert("Bool".into(), vec!["True".into(), "False".into()]);
        // Variable-arity builtins: registered in functions (not user_functions)
        // so is_rule_function() returns true → arity check skipped
        tc.functions.insert("subject".into(), 0);
        tc.record_function_signature("subject", 0, None);
        tc.functions.insert("complete".into(), 1);
        tc.record_function_signature("complete", 1, None);
        tc
    }

    fn record_function_signature(&mut self, name: &str, arity: usize, params: Option<Vec<String>>) {
        self.function_arities
            .entry(name.to_string())
            .or_default()
            .insert(arity);
        if let Some(params) = params {
            self.function_params_by_arity
                .insert((name.to_string(), arity), params);
        }
    }

    fn record_explore_function_definition(
        &mut self,
        name: &str,
        params: &[Param],
        ret_ty: Option<&Ty>,
        effects: &[String],
        body: &Expr,
    ) {
        let key = (name.to_string(), params.len());
        self.explore_function_definitions_by_arity
            .entry(key.clone())
            .or_default()
            .push((params.to_vec(), ret_ty.cloned(), body.clone()));
        self.explore_callable_expressions_by_arity
            .entry(key.clone())
            .or_default()
            .push(body.clone());
        if !effects.is_empty() {
            self.explore_declared_effect_callables.insert(key);
        }
    }

    fn record_explore_non_rule_runtime_name(&mut self, name: &str) {
        if self.explore_inline_module_depth == 0 {
            self.explore_non_rule_runtime_names.insert(name.to_string());
        }
    }

    fn record_explore_top_level_binding_initializer(&mut self, statement: &Stmt) {
        if self.explore_inline_module_depth != 0 {
            return;
        }
        match statement {
            Stmt::Bind(pattern, _, initializer) => {
                let mut names = BTreeSet::new();
                collect_pattern_names(pattern, &mut names);
                for name in names {
                    self.explore_top_level_binding_initializers
                        .entry(name)
                        .or_default()
                        .push(initializer.clone());
                }
            }
            Stmt::MonadicBind(pattern, _, _) => {
                let mut names = BTreeSet::new();
                collect_pattern_names(pattern, &mut names);
                self.explore_unsupported_top_level_bindings.extend(names);
            }
            Stmt::StreamBind(name, _) | Stmt::Rule(Rule::ReactiveScope { name, .. }) => {
                self.explore_unsupported_top_level_bindings
                    .insert(name.clone());
            }
            _ => {}
        }
    }

    fn record_explore_rule_body(&mut self, rule: &Rule) {
        let Some(key) = Self::rule_name_arity(rule) else {
            return;
        };
        self.explore_rules_by_arity
            .entry(key.clone())
            .or_default()
            .push(rule.clone());
        let expressions = self
            .explore_callable_expressions_by_arity
            .entry(key)
            .or_default();
        match rule {
            Rule::Clause { body, .. } => expressions.extend(body.iter().cloned()),
            Rule::Default {
                value, condition, ..
            }
            | Rule::Exception {
                value, condition, ..
            } => {
                expressions.push(value.clone());
                expressions.extend(condition.iter().cloned());
            }
            Rule::ReactiveScope { .. } => {}
        }
    }

    fn record_explore_scoped_rule_body(
        &mut self,
        scope_name: &str,
        captures: &[Param],
        rule: &Rule,
    ) {
        let Some((member, arity)) = Self::rule_name_arity(rule) else {
            return;
        };
        let head = match rule {
            Rule::Clause { head, .. }
            | Rule::Default { head, .. }
            | Rule::Exception { head, .. } => head,
            Rule::ReactiveScope { .. } => return,
        };
        let mut bound = captures
            .iter()
            .map(|param| param.name.clone())
            .collect::<BTreeSet<_>>();
        let mut callable_bound = captures
            .iter()
            .filter(|param| param.ty.as_ref().is_some_and(Self::explore_ty_is_callable))
            .map(|param| param.name.clone())
            .collect::<BTreeSet<_>>();
        if let ExprKind::App(_, arguments) = &head.kind {
            let mut scopes = vec![BTreeSet::new()];
            for argument in arguments {
                Self::define_rule_head_vars(argument, &mut scopes);
                if let Some((inner, type_name)) = Self::typed_rule_arg_parts(argument) {
                    if parse_type_annotation(type_name)
                        .ok()
                        .as_ref()
                        .is_some_and(Self::explore_ty_is_callable)
                    {
                        if let Some(name) = Self::rule_head_param_name(inner) {
                            callable_bound.insert(name);
                        }
                    }
                }
            }
            bound.extend(scopes.pop().unwrap_or_default());
        }

        let key = RuleDispatchKey {
            scope: Some(scope_name.to_string()),
            name: member,
            arity,
        };
        let expressions = self
            .explore_scoped_callable_expressions
            .entry(key)
            .or_default();
        let mut push = |expression: &Expr| {
            expressions.push(ExplorePurityExpression {
                expression: expression.clone(),
                bound: bound.clone(),
                callable_bound: callable_bound.clone(),
            });
        };
        match rule {
            Rule::Clause {
                body: Some(body), ..
            } => push(body),
            Rule::Default {
                value, condition, ..
            }
            | Rule::Exception {
                value, condition, ..
            } => {
                push(value);
                if let Some(condition) = condition {
                    push(condition);
                }
            }
            Rule::Clause { body: None, .. } | Rule::ReactiveScope { .. } => {}
        }
    }

    fn explore_ty_is_callable(ty: &Ty) -> bool {
        matches!(ty, Ty::Arrow(_, _))
    }

    fn explore_callable_bound_names(&self, key: &(String, usize)) -> BTreeSet<String> {
        let Some(types) = self.rule_param_types_by_arity.get(key) else {
            return BTreeSet::new();
        };
        self.function_params_by_arity
            .get(key)
            .into_iter()
            .flatten()
            .zip(types)
            .filter_map(|(name, ty)| {
                ty.as_ref()
                    .is_some_and(Self::explore_ty_is_callable)
                    .then(|| name.clone())
            })
            .collect()
    }

    fn record_rule_signature(&mut self, name: &str, head: &Expr) {
        let Some((_, arity)) = Self::rule_head_name_arity(head) else {
            return;
        };
        self.rule_arities.insert((name.to_string(), arity));
        let Some(incoming) = Self::rule_head_param_types(head) else {
            return;
        };
        let conflicts = {
            let stored = self
                .rule_param_types_by_arity
                .entry((name.to_string(), arity))
                .or_insert_with(|| vec![None; arity]);
            let mut conflicts = Vec::new();
            for (index, (slot, candidate)) in stored.iter_mut().zip(incoming).enumerate() {
                match (&*slot, candidate) {
                    (None, candidate) => *slot = candidate,
                    (Some(existing), Some(candidate))
                        if Self::canonical_explore_ty_name(existing)
                            != Self::canonical_explore_ty_name(&candidate) =>
                    {
                        conflicts.push((index, existing.to_string(), candidate.to_string()));
                    }
                    _ => {}
                }
            }
            conflicts
        };
        for (index, existing, candidate) in conflicts {
            self.error_at_expr(
                head,
                format!(
                    "rule `{}({} arguments)` declares conflicting types `{}` and `{}` for parameter {}",
                    name,
                    arity,
                    existing,
                    candidate,
                    index + 1
                ),
            );
        }
    }

    fn function_has_arity(&self, name: &str, arity: usize) -> bool {
        self.function_arities
            .get(name)
            .is_some_and(|arities| arities.contains(&arity))
    }

    fn function_params_for_arity(&self, name: &str, arity: usize) -> Option<&Vec<String>> {
        self.function_params_by_arity
            .get(&(name.to_string(), arity))
    }

    fn method_receiver_shape(params: &[Param]) -> MethodReceiverShape {
        let mut saw_self = false;
        for (index, param) in params.iter().enumerate() {
            if param.name == "self" {
                if saw_self || index != 0 {
                    return MethodReceiverShape::Invalid;
                }
                saw_self = true;
            }
        }
        if saw_self {
            MethodReceiverShape::SelfFirst
        } else {
            MethodReceiverShape::None
        }
    }

    pub fn push_scope(&mut self) {
        self.scopes.push(BTreeSet::new());
        self.rule_scope_vars.push(BTreeMap::new());
        self.var_types.push(BTreeMap::new());
        self.actor_handle_scopes.push(BTreeMap::new());
    }

    pub fn pop_scope(&mut self) {
        self.scopes.pop();
        self.rule_scope_vars.pop();
        self.var_types.pop();
        self.actor_handle_scopes.pop();
    }

    pub fn define_var(&mut self, name: &str) {
        if let Some(scope) = self.scopes.last_mut() {
            scope.insert(name.to_string());
        }
        if let Some(scope) = self.actor_handle_scopes.last_mut() {
            scope.insert(name.to_string(), None);
        }
    }

    fn register_reference_symbol(&mut self, name: &str, kind: ProgramSymbolKind) {
        self.reference_symbols
            .entry(name.to_string())
            .or_default()
            .insert(kind);
    }

    fn define_rule_scope_var(&mut self, name: &str, scope_name: &str) {
        if let Some(scope) = self.rule_scope_vars.last_mut() {
            scope.insert(name.to_string(), scope_name.to_string());
        }
        self.define_var_type_name(name, scope_name);
    }

    fn rule_scope_var_type(&self, name: &str) -> Option<&str> {
        for scope in self.rule_scope_vars.iter().rev() {
            if let Some(scope_name) = scope.get(name) {
                return Some(scope_name);
            }
        }
        None
    }

    fn define_var_type_name(&mut self, name: &str, type_name: &str) {
        if let Some(scope) = self.var_types.last_mut() {
            scope.insert(name.to_string(), type_name.to_string());
        }
    }

    fn define_inferred_var_type_name(&mut self, name: &str, type_name: &str) {
        if self.type_has_scoped_members(type_name) {
            self.define_rule_scope_var(name, type_name);
        } else {
            self.define_var_type_name(name, type_name);
        }
    }

    fn type_has_scoped_members(&self, type_name: &str) -> bool {
        self.rule_scope_methods.contains_key(type_name)
            || self.rule_scope_value_methods.contains_key(type_name)
    }

    fn define_var_type(&mut self, name: &str, ty: &Ty) {
        match ty {
            Ty::Name(type_name) => {
                if self.type_has_scoped_members(type_name) {
                    self.define_rule_scope_var(name, type_name);
                } else {
                    self.define_var_type_name(name, type_name);
                }
            }
            Ty::App(base, _) => {
                if let Ty::Name(type_name) = base.as_ref() {
                    if self.type_has_scoped_members(type_name) {
                        self.define_rule_scope_var(name, type_name);
                    } else {
                        self.define_var_type_name(name, &ty.to_string());
                    }
                }
            }
            Ty::Optional(_) => {
                self.define_var_type_name(name, &Self::canonical_explore_ty_name(ty));
            }
            Ty::Unit => self.define_var_type_name(name, "()"),
            _ => {}
        }
    }

    fn canonical_explore_ty_name(ty: &Ty) -> String {
        match ty {
            Ty::Name(name) if name == "Unit" => "()".to_string(),
            Ty::Name(name) | Ty::Var(name) => name.clone(),
            Ty::App(constructor, arguments) => format!(
                "{}({})",
                Self::canonical_explore_ty_name(constructor),
                arguments
                    .iter()
                    .map(Self::canonical_explore_ty_name)
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
            Ty::Arrow(input, output) => format!(
                "{} -> {}",
                Self::canonical_explore_ty_name(input),
                Self::canonical_explore_ty_name(output)
            ),
            Ty::Ref(inner) => format!("&{}", Self::canonical_explore_ty_name(inner)),
            Ty::MutRef(inner) => format!("&mut {}", Self::canonical_explore_ty_name(inner)),
            Ty::Shared(inner) => format!("shared {}", Self::canonical_explore_ty_name(inner)),
            Ty::Optional(inner) => {
                format!("Option({})", Self::canonical_explore_ty_name(inner))
            }
            Ty::Unit => "()".to_string(),
            Ty::Hole => "_".to_string(),
        }
    }

    fn canonical_explore_type_name(type_name: &str) -> String {
        parse_type_annotation(type_name)
            .map(|ty| Self::canonical_explore_ty_name(&ty))
            .unwrap_or_else(|_| type_name.to_string())
    }

    fn explore_tys_equivalent(left: &Ty, right: &Ty) -> bool {
        explore::relational_tys_equivalent(left, right)
    }

    fn explore_type_name_matches_ty(actual: &str, expected: &Ty) -> bool {
        Self::canonical_explore_type_name(actual) == Self::canonical_explore_ty_name(expected)
    }

    fn explore_contextual_intrinsic_is_shadowed(&self, name: &str, _arity: usize) -> bool {
        let root_value = self
            .scopes
            .first()
            .is_some_and(|scope| scope.contains(name));
        let Some(kinds) = self.reference_symbols.get(name) else {
            return root_value || self.constructor_signatures.contains_key(name);
        };
        root_value
            || kinds.contains(&ProgramSymbolKind::Binding)
            || kinds.contains(&ProgramSymbolKind::Function)
            || kinds.contains(&ProgramSymbolKind::Rule)
            || self.constructor_signatures.contains_key(name)
    }

    fn var_type_name(&self, name: &str) -> Option<&str> {
        for scope in self.var_types.iter().rev() {
            if let Some(type_name) = scope.get(name) {
                return Some(type_name);
            }
        }
        None
    }

    /// Return the inferred or annotated type name of a visible binding.
    ///
    /// Metadata tooling uses this after declaration and top-level inference
    /// passes so role references follow the same type facts as normal code.
    pub fn binding_type_name(&self, name: &str) -> Option<&str> {
        self.var_type_name(name)
    }

    /// Extract and define variable names from a rule head argument,
    /// including __typed(var, Type) wrappers.
    fn define_rule_head_vars(arg: &Expr, scopes: &mut Vec<BTreeSet<String>>) {
        match &arg.kind {
            ExprKind::Var(name) if !name.starts_with(|c: char| c.is_uppercase()) && name != "_" => {
                if let Some(scope) = scopes.last_mut() {
                    scope.insert(name.clone());
                }
            }
            ExprKind::App(func, args) if matches!(&func.kind, ExprKind::Var(n) if n == "__typed") =>
            {
                // __typed(var, Type) — define the variable
                if let Some(first) = args.first() {
                    Self::define_rule_head_vars(first, scopes);
                }
            }
            ExprKind::App(_, args) => {
                // Constructor with args: Cons(h, t)
                for a in args {
                    Self::define_rule_head_vars(a, scopes);
                }
            }
            ExprKind::Tuple(items) => {
                for item in items {
                    Self::define_rule_head_vars(item, scopes);
                }
            }
            _ => {}
        }
    }

    fn define_rule_head_var_types(&mut self, arg: &Expr) {
        match &arg.kind {
            ExprKind::App(func, args) if matches!(&func.kind, ExprKind::Var(n) if n == "__typed") => {
                if args.len() == 2 {
                    if let (ExprKind::Var(name), ExprKind::Var(type_name)) =
                        (&args[0].kind, &args[1].kind)
                    {
                        let ty = parse_type_annotation(type_name)
                            .unwrap_or_else(|_| Ty::Name(type_name.clone()));
                        self.define_var_type(name, &ty);
                    }
                    self.define_rule_head_var_types(&args[0]);
                }
            }
            ExprKind::App(_, args) => {
                for arg in args {
                    self.define_rule_head_var_types(arg);
                }
            }
            ExprKind::Tuple(items) => {
                for item in items {
                    self.define_rule_head_var_types(item);
                }
            }
            _ => {}
        }
    }

    fn typed_rule_arg_parts(arg: &Expr) -> Option<(&Expr, &str)> {
        let ExprKind::App(func, args) = &arg.kind else {
            return None;
        };
        if !matches!(&func.kind, ExprKind::Var(n) if n == "__typed") || args.len() != 2 {
            return None;
        }
        let ExprKind::Var(type_name) = &args[1].kind else {
            return None;
        };
        Some((&args[0], type_name.as_str()))
    }

    fn rule_head_param_name(arg: &Expr) -> Option<String> {
        if let Some((inner, _)) = Self::typed_rule_arg_parts(arg) {
            return Self::rule_head_param_name(inner);
        }
        match &arg.kind {
            ExprKind::Var(name) if !name.starts_with(|c: char| c.is_uppercase()) && name != "_" => {
                Some(name.clone())
            }
            _ => None,
        }
    }

    fn rule_head_param_names(head: &Expr) -> Option<Vec<String>> {
        match &head.kind {
            ExprKind::App(_, args) => args.iter().map(Self::rule_head_param_name).collect(),
            ExprKind::Var(_) => Some(vec![]),
            _ => None,
        }
    }

    fn rule_head_param_types(head: &Expr) -> Option<Vec<Option<Ty>>> {
        match &head.kind {
            ExprKind::App(_, args) => Some(
                args.iter()
                    .map(|arg| {
                        Self::typed_rule_arg_parts(arg).and_then(|(_, type_name)| {
                            Some(
                                parse_type_annotation(type_name)
                                    .unwrap_or_else(|_| Ty::Name(type_name.to_string())),
                            )
                        })
                    })
                    .collect(),
            ),
            ExprKind::Var(_) => Some(vec![]),
            _ => None,
        }
    }

    fn rule_head_name_arity(head: &Expr) -> Option<(String, usize)> {
        match &head.kind {
            ExprKind::App(func, args) => match &func.kind {
                ExprKind::Var(name) => Some((name.clone(), args.len())),
                _ => Self::rule_head_name_arity(func).map(|(name, _)| (name, args.len())),
            },
            ExprKind::Var(name) => Some((name.clone(), 0)),
            _ => None,
        }
    }

    fn rule_name_arity(rule: &Rule) -> Option<(String, usize)> {
        match rule {
            Rule::Clause { head, .. }
            | Rule::Default { head, .. }
            | Rule::Exception { head, .. } => Self::rule_head_name_arity(head),
            Rule::ReactiveScope { .. } => None,
        }
    }

    fn direct_constructor_call_name(expr: &Expr) -> Option<&str> {
        match &expr.kind {
            ExprKind::App(func, _) => match &func.kind {
                ExprKind::Var(name) => Some(name.as_str()),
                _ => None,
            },
            _ => None,
        }
    }

    fn type_name_from_ty(ty: &Ty) -> Option<String> {
        match ty {
            Ty::Name(type_name) => Some(type_name.clone()),
            Ty::App(_, _) => Some(ty.to_string()),
            Ty::Optional(inner) | Ty::Ref(inner) | Ty::MutRef(inner) | Ty::Shared(inner) => {
                Self::type_name_from_ty(inner)
            }
            _ => None,
        }
    }

    fn applied_type_argument(
        type_name: &str,
        constructor_name: &str,
        index: usize,
    ) -> Option<String> {
        let parsed = parse_type_annotation(type_name).ok()?;
        match parsed {
            Ty::App(constructor, arguments) if matches!(constructor.as_ref(), Ty::Name(name) if name == constructor_name) => {
                arguments.get(index).and_then(Self::type_name_from_ty)
            }
            Ty::Optional(inner) if constructor_name == "Option" && index == 0 => {
                Self::type_name_from_ty(&inner)
            }
            _ => None,
        }
    }

    fn merge_inferred_type_names(left: &str, right: &str) -> Option<String> {
        if Self::canonical_explore_type_name(left) == Self::canonical_explore_type_name(right) {
            return Some(left.to_string());
        }

        fn application_has_parent(ty: &Ty, parent: &str) -> bool {
            matches!(
                ty,
                Ty::App(constructor, _)
                    if matches!(constructor.as_ref(), Ty::Name(name) if name == parent)
            )
        }

        let left_ty = parse_type_annotation(left).ok()?;
        let right_ty = parse_type_annotation(right).ok()?;
        match (&left_ty, &right_ty) {
            (Ty::Name(parent), applied) if application_has_parent(applied, parent) => {
                Some(right.to_string())
            }
            (applied, Ty::Name(parent)) if application_has_parent(applied, parent) => {
                Some(left.to_string())
            }
            _ => None,
        }
    }

    fn merge_inferred_type_candidates<'a>(
        candidates: impl IntoIterator<Item = &'a String>,
    ) -> Result<Option<String>, (String, String)> {
        let mut merged: Option<String> = None;
        for candidate in candidates {
            let Some(known) = merged.take() else {
                merged = Some(candidate.clone());
                continue;
            };
            match Self::merge_inferred_type_names(&known, candidate) {
                Some(next) => merged = Some(next),
                None => return Err((known, candidate.clone())),
            }
        }
        Ok(merged)
    }

    fn register_constructor_signature(
        &mut self,
        parent: &str,
        constructor: &str,
        positional: bool,
        fields: Vec<String>,
        field_types: Vec<Option<String>>,
        field_tys: Vec<Option<String>>,
    ) {
        let signature = TypeConstructorSignature {
            parent: parent.to_string(),
            positional,
            fields,
            field_types,
            field_tys,
        };
        let signatures = self
            .constructor_signatures
            .entry(constructor.to_string())
            .or_default();
        if !signatures.contains(&signature) {
            signatures.push(signature.clone());
        }

        self.constructors.insert(
            constructor.to_string(),
            (parent.to_string(), signature.arity()),
        );
        if signature.positional || signature.fields.is_empty() {
            self.constructor_fields.remove(constructor);
        } else {
            self.constructor_fields
                .insert(constructor.to_string(), signature.fields);
        }
    }

    fn static_binding_name(pattern: &Pat) -> Option<&str> {
        match pattern {
            Pat::Var(name) => Some(name),
            Pat::Con(name, fields) if fields.is_empty() => Some(name),
            _ => None,
        }
    }

    fn resolve_prepass_import(path: &str, dir: &str) -> Option<(String, String)> {
        let file_path = Self::resolve_tc_import(path, dir)?;
        let canonical = std::fs::canonicalize(&file_path)
            .map(|resolved| resolved.to_string_lossy().to_string())
            .unwrap_or_else(|_| file_path.clone());
        let imported_dir = std::path::Path::new(&file_path)
            .parent()
            .map(|parent| parent.to_string_lossy().to_string())
            .unwrap_or_else(|| dir.to_string());
        Some((canonical, imported_dir))
    }

    fn analysis_declaration_signature(
        statement: &Stmt,
    ) -> Option<(DeclarationKind, Option<String>, String, Option<usize>)> {
        match statement {
            Stmt::Defn(Defn::Fn { name, params, .. }) => Some((
                DeclarationKind::Function,
                None,
                name.clone(),
                Some(params.len()),
            )),
            Stmt::Defn(Defn::Actor { name, .. }) => {
                Some((DeclarationKind::Actor, None, name.clone(), Some(1)))
            }
            Stmt::Defn(Defn::Module { name, .. }) => {
                Some((DeclarationKind::InlineModule, None, name.clone(), None))
            }
            Stmt::TypeDecl(TypeDecl::ADT { name, params, .. }) => {
                Some((DeclarationKind::Adt, None, name.clone(), Some(params.len())))
            }
            Stmt::TypeDecl(TypeDecl::EffectDecl { name, .. }) => {
                Some((DeclarationKind::Effect, None, name.clone(), None))
            }
            Stmt::TypeDecl(TypeDecl::TraitDecl { name, params, .. }) => Some((
                DeclarationKind::Trait,
                None,
                name.clone(),
                Some(params.len()),
            )),
            Stmt::TypeDecl(TypeDecl::ImplBlock {
                trait_name,
                for_type,
                ..
            }) => Some((
                DeclarationKind::Implementation,
                Some(trait_name.clone()),
                for_type.clone(),
                None,
            )),
            Stmt::TypeDecl(TypeDecl::WhenType { name, .. }) => {
                Some((DeclarationKind::WhenType, None, name.clone(), None))
            }
            Stmt::TypeDecl(TypeDecl::RuleScope { name, params, .. }) => Some((
                DeclarationKind::RuleScope,
                None,
                name.clone(),
                Some(params.len()),
            )),
            Stmt::Rule(Rule::Clause { head, .. }) => rule_head_name_arity(head)
                .map(|(name, arity)| (DeclarationKind::RuleClause, None, name, Some(arity))),
            Stmt::Rule(Rule::Default { head, .. }) => rule_head_name_arity(head)
                .map(|(name, arity)| (DeclarationKind::RuleDefault, None, name, Some(arity))),
            Stmt::Rule(Rule::Exception { head, .. }) => rule_head_name_arity(head)
                .map(|(name, arity)| (DeclarationKind::RuleException, None, name, Some(arity))),
            Stmt::Rule(Rule::ReactiveScope { name, .. }) => {
                Some((DeclarationKind::ReactiveScope, None, name.clone(), None))
            }
            Stmt::Bind(pattern, _, _) | Stmt::MonadicBind(pattern, _, _) => {
                let mut names = BTreeSet::new();
                collect_pattern_names(pattern, &mut names);
                let name = if names.is_empty() {
                    format!(
                        "$pattern:{}",
                        parsed_source_content_hash(&format!("{pattern:?}"))
                    )
                } else {
                    names.into_iter().collect::<Vec<_>>().join(",")
                };
                let kind = if matches!(statement, Stmt::Bind(_, _, _)) {
                    DeclarationKind::Binding
                } else {
                    DeclarationKind::MonadicBinding
                };
                Some((kind, None, name, None))
            }
            Stmt::StreamBind(name, _) => {
                Some((DeclarationKind::StreamBinding, None, name.clone(), None))
            }
            Stmt::Invariant { name, .. } => {
                Some((DeclarationKind::Invariant, None, name.clone(), Some(0)))
            }
            Stmt::Explore(query) => {
                Some((DeclarationKind::Explore, None, query.name.clone(), None))
            }
            Stmt::QualifiedImport(name, _) => {
                Some((DeclarationKind::QualifiedModule, None, name.clone(), None))
            }
            Stmt::Use(path) => Some((DeclarationKind::RustUse, None, path.clone(), None)),
            Stmt::Depend(name, version) => Some((
                DeclarationKind::RustDependency,
                Some(name.clone()),
                version.clone(),
                None,
            )),
            Stmt::RustBlock(_) => {
                Some((DeclarationKind::RustBlock, None, "$rust".to_string(), None))
            }
            Stmt::Import(_)
            | Stmt::HashImport(_, _)
            | Stmt::Annot(_, _)
            | Stmt::For(_, _, _)
            | Stmt::While(_, _)
            | Stmt::Send(_, _)
            | Stmt::StreamSub(_, _)
            | Stmt::Prove { .. }
            | Stmt::Assert(_, _)
            | Stmt::Retract(_, _)
            | Stmt::Abort
            | Stmt::Expr(_) => None,
        }
    }

    fn analysis_statement_span(statement: &Stmt) -> Option<Span> {
        let span = match statement {
            Stmt::Defn(Defn::Fn { body, .. }) => body.span,
            Stmt::Defn(Defn::Actor { handlers, .. }) => handlers
                .iter()
                .map(|handler| handler.body.span)
                .reduce(Span::merge)
                .unwrap_or_else(Span::dummy),
            Stmt::Rule(rule) => rule
                .head()
                .map(|head| head.span)
                .unwrap_or_else(Span::dummy),
            Stmt::Bind(_, _, expression)
            | Stmt::MonadicBind(_, _, expression)
            | Stmt::StreamBind(_, expression) => expression.span,
            Stmt::Invariant {
                subject, predicate, ..
            } => subject.span.merge(predicate.span),
            Stmt::Explore(query) => query.span,
            _ => Span::dummy(),
        };
        (!span.is_dummy()).then_some(span)
    }

    /// Deterministic, span-free statement content with every nested physical
    /// Futuruna import path replaced by a semantic import marker.
    fn canonical_analysis_statement(statement: &Stmt) -> String {
        let mut canonical = format!("{:?}", strip_spans_stmt(statement));
        let mut replacements = BTreeMap::<String, String>::new();
        walk_ast_stmt(statement, &mut |child| {
            let AstChild::Stmt(statement) = child else {
                return;
            };
            let replacement = match statement {
                Stmt::Import(_) => Some("Import(\"$resolved\")".to_string()),
                Stmt::QualifiedImport(name, _) => {
                    Some(format!("QualifiedImport({name:?}, \"$opaque-target\")"))
                }
                Stmt::HashImport(hash, _) => {
                    Some(format!("HashImport({hash:?}, \"$selected-target\")"))
                }
                _ => None,
            };
            if let Some(replacement) = replacement {
                replacements.insert(format!("{statement:?}"), replacement);
            }
        });
        // Longer fragments first make replacement independent of incidental
        // enum-name overlap (`Import` / `HashImport`). The map itself removes
        // duplicate paths without introducing HashMap iteration order.
        let mut replacements = replacements.into_iter().collect::<Vec<_>>();
        replacements.sort_by(|(left, _), (right, _)| {
            right.len().cmp(&left.len()).then_with(|| left.cmp(right))
        });
        for (physical, semantic) in replacements {
            canonical = canonical.replace(&physical, &semantic);
        }
        canonical
    }

    /// Declaration categories which establish a nominal type/namespace owner.
    /// Their ordinal is intentionally independent of executable declarations
    /// and every Explore occurrence.
    fn model_namespace_declaration_signature(
        statement: &Stmt,
    ) -> Option<(DeclarationKind, Option<String>, String, Option<usize>)> {
        let signature = Self::analysis_declaration_signature(statement)?;
        matches!(
            signature.0,
            DeclarationKind::Adt
                | DeclarationKind::Effect
                | DeclarationKind::Trait
                | DeclarationKind::WhenType
                | DeclarationKind::RuleScope
                | DeclarationKind::InlineModule
                | DeclarationKind::QualifiedModule
        )
        .then_some(signature)
    }

    /// Canonical type/schema-interface shell. Bodies which represent
    /// computation rather than nominal layout are excluded deliberately.
    fn canonical_model_interface_statement(statement: &Stmt) -> Option<String> {
        match statement {
            Stmt::Import(_) => Some("plain-import".to_string()),
            Stmt::HashImport(hash, _) => Some(format!("hash-import:{hash}")),
            Stmt::QualifiedImport(name, _) => Some(format!("qualified-import:{name}:opaque")),
            Stmt::Defn(Defn::Module { name, body }) => {
                let children = body
                    .iter()
                    .filter_map(Self::canonical_model_interface_statement)
                    .collect::<Vec<_>>();
                Some(format!("inline-module:{name}:{children:?}"))
            }
            Stmt::TypeDecl(TypeDecl::ADT {
                name,
                params,
                variants,
                except_from,
                ..
            }) => Some(format!(
                "adt:{name};params={params:?};variants={variants:?};except={except_from:?}"
            )),
            Stmt::TypeDecl(TypeDecl::RuleScope { name, params, .. }) => {
                Some(format!("rule-scope:{name};params={params:?}"))
            }
            Stmt::TypeDecl(TypeDecl::WhenType {
                name,
                condition,
                variants,
                except_from,
            }) => Some(format!(
                "when-type:{name};condition={:?};variants={variants:?};except={except_from:?}",
                strip_spans_expr(condition)
            )),
            Stmt::TypeDecl(TypeDecl::EffectDecl { name, ops }) => {
                Some(format!("effect:{name};ops={ops:?}"))
            }
            Stmt::TypeDecl(TypeDecl::TraitDecl {
                name,
                params,
                methods,
            }) => {
                let methods = methods
                    .iter()
                    .map(|method| {
                        (
                            method.name.as_str(),
                            method.params.as_slice(),
                            method.ret_ty.as_ref(),
                        )
                    })
                    .collect::<Vec<_>>();
                Some(format!(
                    "trait:{name};params={params:?};methods={methods:?}"
                ))
            }
            Stmt::TypeDecl(TypeDecl::ImplBlock { .. })
            | Stmt::Defn(Defn::Fn { .. } | Defn::Actor { .. })
            | Stmt::Rule(_)
            | Stmt::Bind(_, _, _)
            | Stmt::MonadicBind(_, _, _)
            | Stmt::StreamBind(_, _)
            | Stmt::Invariant { .. }
            | Stmt::Explore(_)
            | Stmt::Use(_)
            | Stmt::Depend(_, _)
            | Stmt::RustBlock(_)
            | Stmt::Annot(_, _)
            | Stmt::For(_, _, _)
            | Stmt::While(_, _)
            | Stmt::Send(_, _)
            | Stmt::StreamSub(_, _)
            | Stmt::Prove { .. }
            | Stmt::Assert(_, _)
            | Stmt::Retract(_, _)
            | Stmt::Abort
            | Stmt::Expr(_) => None,
        }
    }

    fn model_interface_local_module_id(statements: &[Stmt]) -> ModelModuleId {
        let mut hasher = Sha256::new();
        hasher.update(b"futuruna.checked-model-interface-module.v1\0");
        for statement in statements {
            let Some(canonical) = Self::canonical_model_interface_statement(statement) else {
                continue;
            };
            Self::hash_analysis_component(&mut hasher, &canonical);
        }
        ModelModuleId::top_level(format!("{:x}", hasher.finalize()))
    }

    fn model_interface_dependency_imports(statements: &[Stmt]) -> Vec<AnalysisDependencyImport> {
        fn collect(statement: &Stmt, imports: &mut Vec<AnalysisDependencyImport>) {
            let (kind, physical_path) = match statement {
                Stmt::Import(path) => (Some(AnalysisDependencyImportKind::Plain), Some(path)),
                Stmt::HashImport(hash, path) => (
                    Some(AnalysisDependencyImportKind::Hash(
                        hash.clone().into_boxed_str(),
                    )),
                    Some(path),
                ),
                Stmt::QualifiedImport(name, path) => (
                    Some(AnalysisDependencyImportKind::Qualified(
                        name.clone().into_boxed_str(),
                    )),
                    Some(path),
                ),
                Stmt::Defn(Defn::Module { body, .. }) => {
                    for child in body {
                        collect(child, imports);
                    }
                    (None, None)
                }
                // Type methods, RuleScope bodies, ordinary executable bodies
                // and Explore bodies cannot contribute to nominal ownership.
                _ => (None, None),
            };
            if let (Some(kind), Some(physical_path)) = (kind, physical_path) {
                imports.push(AnalysisDependencyImport {
                    ordinal: imports.len(),
                    kind,
                    physical_path: physical_path.clone(),
                });
            }
        }

        let mut imports = Vec::new();
        for statement in statements {
            collect(statement, &mut imports);
        }
        imports
    }

    fn collect_model_interface_dependency_closure(
        statements: &[Stmt],
        dir: &str,
        canonical_module: &str,
        visited: &mut BTreeMap<String, usize>,
        modules: &mut Vec<ModelInterfaceDependencyModule>,
    ) -> usize {
        if let Some(index) = visited.get(canonical_module) {
            return *index;
        }

        let index = modules.len();
        visited.insert(canonical_module.to_string(), index);
        modules.push(ModelInterfaceDependencyModule {
            local: Self::model_interface_local_module_id(statements),
            edges: Box::new([]),
        });
        let mut edges = Vec::new();
        for import in Self::model_interface_dependency_imports(statements) {
            let Some((canonical_target, imported_dir)) =
                Self::resolve_prepass_import(&import.physical_path, dir)
            else {
                edges.push(AnalysisDependencyEdge {
                    ordinal: import.ordinal,
                    kind: import.kind,
                    target: None,
                });
                continue;
            };
            let target = if let Some(target) = visited.get(&canonical_target) {
                Some(*target)
            } else {
                parse_source_module_file_cached(Path::new(&canonical_target))
                    .ok()
                    .map(|imported| {
                        Self::collect_model_interface_dependency_closure(
                            imported.statements(),
                            &imported_dir,
                            &canonical_target,
                            visited,
                            modules,
                        )
                    })
            };
            edges.push(AnalysisDependencyEdge {
                ordinal: import.ordinal,
                kind: import.kind,
                target,
            });
        }
        modules[index].edges = edges.into_boxed_slice();
        index
    }

    /// Cycle-safe, path-free transitive identity of a model/type interface.
    /// Physical paths are used only to resolve graph edges and backreferences.
    fn model_interface_module_id(
        statements: &[Stmt],
        dir: &str,
        canonical_module: &str,
    ) -> ModelModuleId {
        let mut visited = BTreeMap::new();
        let mut modules = Vec::new();
        Self::collect_model_interface_dependency_closure(
            statements,
            dir,
            canonical_module,
            &mut visited,
            &mut modules,
        );

        let mut hasher = Sha256::new();
        hasher.update(b"futuruna.checked-model-interface-closure.v1\0");
        Self::hash_analysis_component(&mut hasher, &modules.len().to_string());
        for (index, module) in modules.into_iter().enumerate() {
            Self::hash_analysis_component(&mut hasher, "module");
            Self::hash_analysis_component(&mut hasher, &index.to_string());
            Self::hash_analysis_component(&mut hasher, &module.local.interface_hash);
            Self::hash_analysis_component(&mut hasher, &module.edges.len().to_string());
            for edge in module.edges.iter() {
                Self::hash_analysis_component(&mut hasher, &edge.ordinal.to_string());
                match &edge.kind {
                    AnalysisDependencyImportKind::Plain => {
                        Self::hash_analysis_component(&mut hasher, "plain");
                    }
                    AnalysisDependencyImportKind::Hash(hash) => {
                        Self::hash_analysis_component(&mut hasher, "hash");
                        Self::hash_analysis_component(&mut hasher, hash);
                    }
                    AnalysisDependencyImportKind::Qualified(name) => {
                        Self::hash_analysis_component(&mut hasher, "qualified");
                        Self::hash_analysis_component(&mut hasher, name);
                    }
                }
                if let Some(target) = edge.target {
                    Self::hash_analysis_component(&mut hasher, "resolved-node");
                    Self::hash_analysis_component(&mut hasher, &target.to_string());
                } else {
                    Self::hash_analysis_component(
                        &mut hasher,
                        "$unresolved-model-interface-target",
                    );
                }
            }
        }
        ModelModuleId::top_level(format!("{:x}", hasher.finalize()))
    }

    /// Commit the exact resolved statement sequence consumed by the backend.
    /// `canonical_analysis_statement` is a span-free normalization despite its
    /// historical name; applying it without the analysis-declaration filter
    /// deliberately retains proof continuations and ordinary execution.
    fn checked_resolved_program_id(
        analysis_program: &CheckedAnalysisProgram,
        statements: &[Stmt],
    ) -> CheckedResolvedProgramId {
        let mut hasher = Sha256::new();
        hasher.update(b"futuruna.checked-resolved-program.v1\0");
        Self::hash_analysis_component(&mut hasher, analysis_program.id.as_str());
        Self::hash_analysis_component(&mut hasher, &statements.len().to_string());
        for statement in statements {
            let canonical = Self::canonical_analysis_statement(statement);
            Self::hash_analysis_component(&mut hasher, &canonical);
        }
        CheckedResolvedProgramId(format!("{:x}", hasher.finalize()).into_boxed_str())
    }

    /// Hash normalized local module content without admitting physical import
    /// paths into semantic identity. Plain imports contribute ordered markers;
    /// their resolved declarations are represented separately in the flattened
    /// program. Hash imports retain the selected content hash. Qualified
    /// imports retain only their local module name and stay opaque.
    fn analysis_module_id(statements: &[Stmt]) -> ModuleId {
        let mut hasher = Sha256::new();
        hasher.update(b"futuruna.checked-module.v1\0");
        for statement in statements {
            let canonical = match statement {
                Stmt::Import(_) => Some("plain-import".to_string()),
                Stmt::QualifiedImport(name, _) => Some(format!("qualified-import:{name}:opaque")),
                Stmt::HashImport(hash, _) => Some(format!("hash-import:{hash}")),
                other
                    if Self::analysis_declaration_signature(other).is_some()
                        || matches!(other, Stmt::Annot(_, _)) =>
                {
                    Some(Self::canonical_analysis_statement(other))
                }
                // Execution/proof continuations are not part of the checked
                // analysis declaration content. In particular, changing a
                // `? name -> { ... } else { ... }` presentation handler cannot
                // rename every semantic site in an otherwise identical query.
                _ => None,
            };
            let Some(canonical) = canonical else {
                continue;
            };
            hasher.update((canonical.len() as u64).to_le_bytes());
            hasher.update(canonical.as_bytes());
        }
        ModuleId::top_level(format!("{:x}", hasher.finalize()))
    }

    /// Find dependency edges only below content that participates in checked
    /// analysis identity. A top-level proof continuation is intentionally not
    /// followed, while an import nested in a declaration body remains part of
    /// that declaration's conservative semantic closure.
    fn analysis_dependency_imports(statements: &[Stmt]) -> Vec<AnalysisDependencyImport> {
        let mut imports = Vec::new();
        for statement in statements {
            if !matches!(
                statement,
                Stmt::Import(_)
                    | Stmt::QualifiedImport(_, _)
                    | Stmt::HashImport(_, _)
                    | Stmt::Annot(_, _)
            ) && Self::analysis_declaration_signature(statement).is_none()
            {
                continue;
            }
            walk_ast_stmt(statement, &mut |child| {
                let AstChild::Stmt(statement) = child else {
                    return;
                };
                let (kind, physical_path) = match statement {
                    Stmt::Import(path) => (AnalysisDependencyImportKind::Plain, path),
                    Stmt::HashImport(hash, path) => (
                        AnalysisDependencyImportKind::Hash(hash.clone().into_boxed_str()),
                        path,
                    ),
                    Stmt::QualifiedImport(name, path) => (
                        AnalysisDependencyImportKind::Qualified(name.clone().into_boxed_str()),
                        path,
                    ),
                    _ => return,
                };
                imports.push(AnalysisDependencyImport {
                    ordinal: imports.len(),
                    kind,
                    physical_path: physical_path.clone(),
                });
            });
        }
        imports
    }

    /// Discover a path-keyed dependency graph but retain only path-free node
    /// and edge content. Canonical paths decide whether an edge is a graph
    /// backreference; deterministic source-order discovery assigns the numeric
    /// node identity that enters the digest. This preserves which dependency
    /// belongs to which content-identical wrapper while making cycles finite.
    fn collect_analysis_dependency_closure(
        statements: &[Stmt],
        dir: &str,
        canonical_module: &str,
        visited: &mut BTreeMap<String, usize>,
        modules: &mut Vec<AnalysisDependencyModule>,
    ) -> usize {
        if let Some(index) = visited.get(canonical_module) {
            return *index;
        }

        let index = modules.len();
        visited.insert(canonical_module.to_string(), index);
        modules.push(AnalysisDependencyModule {
            local: Self::analysis_module_id(statements),
            edges: Box::new([]),
        });

        let mut edges = Vec::new();
        for import in Self::analysis_dependency_imports(statements) {
            let Some((canonical_target, imported_dir)) =
                Self::resolve_prepass_import(&import.physical_path, dir)
            else {
                edges.push(AnalysisDependencyEdge {
                    ordinal: import.ordinal,
                    kind: import.kind,
                    target: None,
                });
                continue;
            };
            let target = if let Some(target) = visited.get(&canonical_target) {
                Some(*target)
            } else {
                parse_source_module_file_cached(Path::new(&canonical_target))
                    .ok()
                    .map(|imported| {
                        Self::collect_analysis_dependency_closure(
                            imported.statements(),
                            &imported_dir,
                            &canonical_target,
                            visited,
                            modules,
                        )
                    })
            };
            edges.push(AnalysisDependencyEdge {
                ordinal: import.ordinal,
                kind: import.kind,
                target,
            });
        }
        modules[index].edges = edges.into_boxed_slice();
        index
    }

    /// Cycle-safe transitive semantic identity for an opaque qualified target.
    /// Canonical paths are used only to resolve and deduplicate graph nodes;
    /// the digest contains the root's local content plus a deterministic
    /// source-order graph serialization with numeric backreferences. Duplicate
    /// physical modules therefore retain both multiplicity and parent/child
    /// correlation without leaking their locations.
    fn analysis_qualified_target_module_id(
        statements: &[Stmt],
        dir: &str,
        canonical_module: &str,
    ) -> ModuleId {
        let root = Self::analysis_module_id(statements);
        let mut visited = BTreeMap::new();
        let mut modules = Vec::new();
        Self::collect_analysis_dependency_closure(
            statements,
            dir,
            canonical_module,
            &mut visited,
            &mut modules,
        );

        let mut hasher = Sha256::new();
        hasher.update(b"futuruna.checked-qualified-closure.v2\0");
        Self::hash_analysis_component(&mut hasher, &root.content_hash);
        Self::hash_analysis_component(&mut hasher, &root.internal_path.len().to_string());
        for component in root.internal_path.iter() {
            Self::hash_analysis_component(&mut hasher, component);
        }
        Self::hash_analysis_component(&mut hasher, &modules.len().to_string());
        for (index, module) in modules.into_iter().enumerate() {
            Self::hash_analysis_component(&mut hasher, "module");
            Self::hash_analysis_component(&mut hasher, &index.to_string());
            Self::hash_analysis_component(&mut hasher, &module.local.content_hash);
            Self::hash_analysis_component(
                &mut hasher,
                &module.local.internal_path.len().to_string(),
            );
            for component in module.local.internal_path.iter() {
                Self::hash_analysis_component(&mut hasher, component);
            }
            Self::hash_analysis_component(&mut hasher, &module.edges.len().to_string());
            for edge in module.edges.iter() {
                Self::hash_analysis_component(&mut hasher, &edge.ordinal.to_string());
                match &edge.kind {
                    AnalysisDependencyImportKind::Plain => {
                        Self::hash_analysis_component(&mut hasher, "plain");
                    }
                    AnalysisDependencyImportKind::Hash(hash) => {
                        Self::hash_analysis_component(&mut hasher, "hash");
                        Self::hash_analysis_component(&mut hasher, hash);
                    }
                    AnalysisDependencyImportKind::Qualified(name) => {
                        Self::hash_analysis_component(&mut hasher, "qualified");
                        Self::hash_analysis_component(&mut hasher, name);
                    }
                }
                if let Some(target) = edge.target {
                    Self::hash_analysis_component(&mut hasher, "resolved-node");
                    Self::hash_analysis_component(&mut hasher, &target.to_string());
                } else {
                    Self::hash_analysis_component(&mut hasher, "$unresolved-dependency-target");
                }
            }
        }
        ModuleId::top_level(format!("{:x}", hasher.finalize()))
    }

    fn imported_constructor_statement(imported_context: bool, statement: &Stmt) -> bool {
        !imported_context
            || matches!(
                statement,
                Stmt::Defn(_)
                    | Stmt::TypeDecl(_)
                    | Stmt::Rule(_)
                    | Stmt::Use(_)
                    | Stmt::RustBlock(_)
                    | Stmt::Annot(_, _)
                    | Stmt::Bind(_, _, _)
                    | Stmt::StreamBind(_, _)
                    | Stmt::Invariant { .. }
            )
    }

    fn push_analysis_declaration(
        declarations: &mut Vec<PrepassAnalysisDeclaration>,
        statement: &Stmt,
        module: &ModuleId,
        declaration_ordinal: usize,
        model_module: Option<&ModelModuleId>,
        model_declaration_ordinal: Option<usize>,
        import_kind: &SourcedImportKind,
        canonical_source_path: &Option<Arc<PathBuf>>,
        qualified_target_module: Option<ModuleId>,
        qualified_target_model_module: Option<ModelModuleId>,
        qualified_target_source_path: Option<Arc<PathBuf>>,
        participates_in_constructor_normalization: bool,
    ) {
        if Self::analysis_declaration_signature(statement).is_some() {
            declarations.push(PrepassAnalysisDeclaration {
                statement: statement.clone(),
                module: module.clone(),
                declaration_ordinal,
                model_module: model_module.cloned(),
                model_declaration_ordinal,
                import_kind: import_kind.clone(),
                canonical_source_path: canonical_source_path.clone(),
                qualified_target_module,
                qualified_target_model_module,
                qualified_target_source_path,
                participates_in_constructor_normalization,
            });
        }
    }

    /// Build the same top-level declaration sequence that the Rust backend sees
    /// for plain imports while retaining checked origins for analysis. The
    /// legacy constructor sequence and its independent plain-import `seen` set
    /// remain unchanged. `checked_seen` deduplicates analysis plain/hash
    /// selections independently; an opaque qualified alias does not consume a
    /// later plain-import occurrence. Every module is parsed at most once per
    /// visit here and no downstream analysis performs another import walk.
    fn flatten_constructor_prepass(
        &mut self,
        statements: &[Stmt],
        dir: &str,
        imported_context: bool,
        import_kind: SourcedImportKind,
        canonical_source_path: Option<Arc<PathBuf>>,
        emit_constructor_sequence: bool,
        emit_analysis_sequence: bool,
        constructor_seen: &mut BTreeSet<String>,
        checked_seen: &mut BTreeSet<String>,
        qualified_target_modules: &mut BTreeMap<String, ModuleId>,
        qualified_target_model_modules: &mut BTreeMap<String, ModelModuleId>,
        flattened: &mut Vec<Stmt>,
        analysis_declarations: &mut Vec<PrepassAnalysisDeclaration>,
    ) {
        let module = Self::analysis_module_id(statements);
        let model_module_key = canonical_source_path
            .as_deref()
            .map(|path| path.to_string_lossy().into_owned())
            .unwrap_or_else(|| "$checked-root".to_string());
        let model_module = Self::model_interface_module_id(statements, dir, &model_module_key);
        let mut declaration_ordinal = 0usize;
        let mut model_declaration_ordinal = 0usize;
        for statement in statements {
            let statement_ordinal = Self::analysis_declaration_signature(statement).map(|_| {
                let ordinal = declaration_ordinal;
                declaration_ordinal += 1;
                ordinal
            });
            let statement_model_ordinal = Self::model_namespace_declaration_signature(statement)
                .map(|_| {
                    let ordinal = model_declaration_ordinal;
                    model_declaration_ordinal += 1;
                    ordinal
                });

            if let Stmt::Import(path) = statement {
                let Some((canonical, imported_dir)) = Self::resolve_prepass_import(path, dir)
                else {
                    continue;
                };
                let emit_constructor_import =
                    emit_constructor_sequence && constructor_seen.insert(canonical.clone());
                let emit_analysis_import =
                    emit_analysis_sequence && checked_seen.insert(canonical.clone());
                if !emit_constructor_import && !emit_analysis_import {
                    continue;
                }
                let imported = match parse_source_module_file_cached(Path::new(&canonical)) {
                    Ok(imported) => imported,
                    Err(_) => continue,
                };
                self.flatten_constructor_prepass(
                    imported.statements(),
                    &imported_dir,
                    true,
                    SourcedImportKind::PlainImport,
                    Some(Arc::new(PathBuf::from(&canonical))),
                    emit_constructor_import,
                    emit_analysis_import,
                    constructor_seen,
                    checked_seen,
                    qualified_target_modules,
                    qualified_target_model_modules,
                    flattened,
                    analysis_declarations,
                );
                continue;
            }

            if let Stmt::QualifiedImport(name, path) = statement {
                if emit_analysis_sequence {
                    let mut qualified_target_module = None;
                    let mut qualified_target_model_module = None;
                    let mut qualified_target_source_path = None;
                    if let Some((canonical, imported_dir)) = Self::resolve_prepass_import(path, dir)
                    {
                        qualified_target_source_path = Some(Arc::new(PathBuf::from(&canonical)));
                        if let Some(cached) = qualified_target_modules.get(&canonical) {
                            qualified_target_module = Some(cached.clone());
                        } else if let Ok(imported) =
                            parse_source_module_file_cached(Path::new(&canonical))
                        {
                            let target = Self::analysis_qualified_target_module_id(
                                imported.statements(),
                                &imported_dir,
                                &canonical,
                            );
                            qualified_target_modules.insert(canonical.clone(), target.clone());
                            qualified_target_module = Some(target);
                        }
                        if let Some(cached) = qualified_target_model_modules.get(&canonical) {
                            qualified_target_model_module = Some(cached.clone());
                        } else if let Ok(imported) =
                            parse_source_module_file_cached(Path::new(&canonical))
                        {
                            let target = Self::model_interface_module_id(
                                imported.statements(),
                                &imported_dir,
                                &canonical,
                            );
                            qualified_target_model_modules
                                .insert(canonical.clone(), target.clone());
                            qualified_target_model_module = Some(target);
                        }
                    }
                    if let Some(statement_ordinal) = statement_ordinal {
                        Self::push_analysis_declaration(
                            analysis_declarations,
                            statement,
                            &module,
                            statement_ordinal,
                            Some(&model_module),
                            statement_model_ordinal,
                            &SourcedImportKind::QualifiedImport {
                                module_name: name.clone().into_boxed_str(),
                            },
                            &canonical_source_path,
                            qualified_target_module,
                            qualified_target_model_module,
                            qualified_target_source_path,
                            false,
                        );
                    }
                }
            }

            if let Stmt::HashImport(hash, path) = statement {
                if emit_analysis_sequence {
                    if let Some((canonical, imported_dir)) = Self::resolve_prepass_import(path, dir)
                    {
                        let import_key = format!("{canonical}#{hash}");
                        if checked_seen.insert(import_key) {
                            if let Ok(imported) =
                                parse_source_module_file_cached(Path::new(&canonical))
                            {
                                let imported_module =
                                    Self::analysis_module_id(imported.statements());
                                let imported_model_module = Self::model_interface_module_id(
                                    imported.statements(),
                                    &imported_dir,
                                    &canonical,
                                );
                                let imported_path = Some(Arc::new(PathBuf::from(&canonical)));
                                let mut imported_ordinal = 0usize;
                                let mut imported_model_ordinal = 0usize;
                                let mut matching = Vec::new();
                                for candidate in imported.statements() {
                                    let Some(_) = Self::analysis_declaration_signature(candidate)
                                    else {
                                        continue;
                                    };
                                    let candidate_ordinal = imported_ordinal;
                                    imported_ordinal += 1;
                                    let candidate_model_ordinal =
                                        Self::model_namespace_declaration_signature(candidate).map(
                                            |_| {
                                                let ordinal = imported_model_ordinal;
                                                imported_model_ordinal += 1;
                                                ordinal
                                            },
                                        );
                                    let selected = match candidate {
                                        Stmt::Defn(definition) => {
                                            content_hash_defn(definition) == *hash
                                        }
                                        Stmt::TypeDecl(declaration) => {
                                            content_hash_type(declaration) == *hash
                                        }
                                        _ => false,
                                    };
                                    if selected {
                                        matching.push((
                                            candidate,
                                            candidate_ordinal,
                                            candidate_model_ordinal,
                                        ));
                                    }
                                }
                                if let [(candidate, candidate_ordinal, candidate_model_ordinal)] =
                                    matching.as_slice()
                                {
                                    Self::push_analysis_declaration(
                                        analysis_declarations,
                                        candidate,
                                        &imported_module,
                                        *candidate_ordinal,
                                        candidate_model_ordinal.map(|_| &imported_model_module),
                                        *candidate_model_ordinal,
                                        &SourcedImportKind::HashImport {
                                            selected_hash: hash.clone().into_boxed_str(),
                                        },
                                        &imported_path,
                                        None,
                                        None,
                                        None,
                                        false,
                                    );
                                }
                            }
                        }
                    }
                }
            }

            let retained = Self::imported_constructor_statement(imported_context, statement);
            let retained_for_constructor = retained
                && !(imported_context
                    && matches!(statement, Stmt::Annot(name, _) if name == "print"));
            if emit_constructor_sequence && retained_for_constructor {
                // Modules, ReactiveScopes and expression Blocks stay opaque: no
                // recursive walk occurs after this top-level push.
                flattened.push(statement.clone());
            }

            if emit_analysis_sequence
                && retained
                && !matches!(statement, Stmt::QualifiedImport(_, _))
            {
                if let Some(statement_ordinal) = statement_ordinal {
                    Self::push_analysis_declaration(
                        analysis_declarations,
                        statement,
                        &module,
                        statement_ordinal,
                        statement_model_ordinal.map(|_| &model_module),
                        statement_model_ordinal,
                        &import_kind,
                        &canonical_source_path,
                        None,
                        None,
                        None,
                        true,
                    );
                }
            }
        }
    }

    fn hash_analysis_component(hasher: &mut Sha256, value: &str) {
        hasher.update((value.len() as u64).to_le_bytes());
        hasher.update(value.as_bytes());
    }

    fn normalize_analysis_program(
        mut declarations: Vec<PrepassAnalysisDeclaration>,
    ) -> CheckedAnalysisProgram {
        // Apply exactly the constructor prepass's existing first-type and
        // last-function/actor rules to root/plain-import declarations. A hash
        // selection did not participate in those legacy filters, so retaining
        // it here preserves rather than changes current shadow behavior.
        let mut seen_types = BTreeSet::new();
        declarations.retain(|declaration| {
            if !declaration.participates_in_constructor_normalization {
                return true;
            }
            match &declaration.statement {
                Stmt::TypeDecl(TypeDecl::ADT { name, .. })
                | Stmt::TypeDecl(TypeDecl::EffectDecl { name, .. })
                | Stmt::TypeDecl(TypeDecl::TraitDecl { name, .. }) => {
                    seen_types.insert(name.clone())
                }
                _ => true,
            }
        });
        let mut last_definitions = BTreeMap::new();
        for (index, declaration) in declarations.iter().enumerate() {
            if !declaration.participates_in_constructor_normalization {
                continue;
            }
            if let Stmt::Defn(Defn::Fn { name, .. }) | Stmt::Defn(Defn::Actor { name, .. }) =
                &declaration.statement
            {
                last_definitions.insert(name.clone(), index);
            }
        }
        declarations = declarations
            .into_iter()
            .enumerate()
            .filter_map(|(index, declaration)| {
                if declaration.participates_in_constructor_normalization {
                    if let Stmt::Defn(Defn::Fn { name, .. })
                    | Stmt::Defn(Defn::Actor { name, .. }) = &declaration.statement
                    {
                        if last_definitions.get(name) != Some(&index) {
                            return None;
                        }
                    }
                }
                Some(declaration)
            })
            .collect();

        let mut declaration_occurrence_counts = BTreeMap::<DeclarationId, usize>::new();
        let mut model_occurrence_counts = BTreeMap::<ModelDeclarationId, usize>::new();
        let declarations = declarations
            .into_iter()
            .enumerate()
            .map(|(normalized_ordinal, declaration)| {
                let (kind, owner, name, arity) =
                    Self::analysis_declaration_signature(&declaration.statement)
                        .expect("prepass analysis declarations have signatures");
                let id = DeclarationId {
                    module: declaration.module,
                    kind,
                    owner: owner.clone().map(String::into_boxed_str),
                    name: name.clone().into_boxed_str(),
                    arity,
                    ordinal: declaration.declaration_ordinal,
                };
                let model_owner = match (
                    declaration.model_module,
                    declaration.model_declaration_ordinal,
                ) {
                    (Some(module), Some(ordinal)) => {
                        let model_declaration = ModelDeclarationId {
                            module,
                            kind,
                            owner: owner.clone().map(String::into_boxed_str),
                            name: name.clone().into_boxed_str(),
                            arity,
                            ordinal,
                        };
                        let next_occurrence = model_occurrence_counts
                            .entry(model_declaration.clone())
                            .or_default();
                        let declaration_occurrence_ordinal = *next_occurrence;
                        *next_occurrence = next_occurrence
                            .checked_add(1)
                            .expect("retained model owner occurrence count fits usize");
                        Some(CheckedModelOwnerKey {
                            declaration: model_declaration,
                            declaration_occurrence_ordinal,
                        })
                    }
                    (None, None) => None,
                    _ => unreachable!("model module and declaration ordinal are paired"),
                };
                let next_occurrence = declaration_occurrence_counts.entry(id.clone()).or_default();
                let declaration_occurrence_ordinal = *next_occurrence;
                *next_occurrence = next_occurrence
                    .checked_add(1)
                    .expect("retained declaration occurrence count fits usize");
                let source_span = Self::analysis_statement_span(&declaration.statement);
                SourcedStmt {
                    id,
                    declaration_occurrence_ordinal,
                    model_owner,
                    normalized_ordinal,
                    import_kind: declaration.import_kind,
                    statement: Arc::new(declaration.statement),
                    canonical_source_path: declaration.canonical_source_path,
                    qualified_target_module: declaration.qualified_target_module,
                    qualified_target_model_module: declaration.qualified_target_model_module,
                    qualified_target_source_path: declaration.qualified_target_source_path,
                    source_span,
                }
            })
            .collect::<Vec<_>>();

        // This is deliberately a conservative whole-checked-declaration
        // identity for Phase A. Every current Explore semantic root is inside
        // its stripped `Stmt::Explore`: domain and fixed/derived bounds,
        // constraints, question, boundary, key, extrema/filter, shown values
        // and representative objective. Runtime proof/pass/else continuations
        // are not declarations and are excluded. A later resolved reachability
        // phase may derive a narrower dependency-slice identity from this
        // complete, origin-preserving input without importing source again.
        let mut hasher = Sha256::new();
        hasher.update(b"futuruna.checked-analysis-program.v1\0");
        for declaration in &declarations {
            Self::hash_analysis_component(&mut hasher, &declaration.id.module.content_hash);
            Self::hash_analysis_component(
                &mut hasher,
                &declaration.id.module.internal_path.len().to_string(),
            );
            for component in declaration.id.module.internal_path.iter() {
                Self::hash_analysis_component(&mut hasher, component);
            }
            Self::hash_analysis_component(&mut hasher, declaration.id.kind.token());
            Self::hash_analysis_component(
                &mut hasher,
                declaration.id.owner.as_deref().unwrap_or(""),
            );
            Self::hash_analysis_component(&mut hasher, &declaration.id.name);
            Self::hash_analysis_component(
                &mut hasher,
                &declaration
                    .id
                    .arity
                    .map(|arity| arity.to_string())
                    .unwrap_or_else(|| "-".to_string()),
            );
            Self::hash_analysis_component(&mut hasher, &declaration.id.ordinal.to_string());
            Self::hash_analysis_component(&mut hasher, &declaration.normalized_ordinal.to_string());
            match &declaration.import_kind {
                SourcedImportKind::Root => {
                    Self::hash_analysis_component(&mut hasher, "origin:root");
                }
                SourcedImportKind::PlainImport => {
                    Self::hash_analysis_component(&mut hasher, "origin:plain-import");
                }
                SourcedImportKind::HashImport { selected_hash } => {
                    Self::hash_analysis_component(&mut hasher, "origin:hash-import");
                    Self::hash_analysis_component(&mut hasher, selected_hash);
                }
                SourcedImportKind::QualifiedImport { module_name } => {
                    Self::hash_analysis_component(&mut hasher, "origin:qualified-import");
                    Self::hash_analysis_component(&mut hasher, module_name);
                }
            }
            if matches!(&*declaration.statement, Stmt::QualifiedImport(_, _)) {
                if let Some(target) = &declaration.qualified_target_module {
                    Self::hash_analysis_component(&mut hasher, &target.content_hash);
                    Self::hash_analysis_component(
                        &mut hasher,
                        &target.internal_path.len().to_string(),
                    );
                    for component in target.internal_path.iter() {
                        Self::hash_analysis_component(&mut hasher, component);
                    }
                } else {
                    Self::hash_analysis_component(&mut hasher, "$unresolved-qualified-target");
                }
            }
            let canonical_statement = Self::canonical_analysis_statement(&declaration.statement);
            Self::hash_analysis_component(&mut hasher, &canonical_statement);
        }
        CheckedAnalysisProgram {
            id: AnalysisProgramId(format!("{:x}", hasher.finalize()).into_boxed_str()),
            declarations: declarations.into(),
        }
    }

    fn build_constructor_prepass(&mut self, statements: &[Stmt]) -> ConstructorPrepass {
        let mut flattened = Vec::new();
        let mut analysis_declarations = Vec::new();
        let mut constructor_seen = BTreeSet::new();
        let mut checked_seen = BTreeSet::new();
        let mut qualified_target_modules = BTreeMap::new();
        let mut qualified_target_model_modules = BTreeMap::new();
        let root_dir = self.source_dir.clone().unwrap_or_else(|| ".".to_string());
        self.flatten_constructor_prepass(
            statements,
            &root_dir,
            false,
            SourcedImportKind::Root,
            None,
            true,
            true,
            &mut constructor_seen,
            &mut checked_seen,
            &mut qualified_target_modules,
            &mut qualified_target_model_modules,
            &mut flattened,
            &mut analysis_declarations,
        );

        // Mirror `scan_declarations`: ADTs, effects, and traits share a
        // first-declaration-wins namespace, while top-level functions and
        // actors share a later-declaration-wins namespace.
        let mut seen_types = BTreeSet::new();
        flattened.retain(|statement| match statement {
            Stmt::TypeDecl(TypeDecl::ADT { name, .. })
            | Stmt::TypeDecl(TypeDecl::EffectDecl { name, .. })
            | Stmt::TypeDecl(TypeDecl::TraitDecl { name, .. }) => seen_types.insert(name.clone()),
            _ => true,
        });
        let mut last_definitions = BTreeMap::new();
        for (index, statement) in flattened.iter().enumerate() {
            if let Stmt::Defn(Defn::Fn { name, .. }) | Stmt::Defn(Defn::Actor { name, .. }) =
                statement
            {
                last_definitions.insert(name.clone(), index);
            }
        }
        let flattened = flattened
            .into_iter()
            .enumerate()
            .filter_map(|(index, statement)| match &statement {
                Stmt::Defn(Defn::Fn { name, .. }) | Stmt::Defn(Defn::Actor { name, .. })
                    if last_definitions.get(name) != Some(&index) =>
                {
                    None
                }
                _ => Some(statement),
            })
            .collect::<Vec<_>>();

        let mut prepass = ConstructorPrepass {
            analysis_program: Self::normalize_analysis_program(analysis_declarations),
            ..ConstructorPrepass::default()
        };
        let mut binding_counts = BTreeMap::<String, usize>::new();
        for statement in &flattened {
            if let Stmt::Bind(Pat::Var(name), _, _) = statement {
                *binding_counts.entry(name.clone()).or_default() += 1;
            }
        }
        prepass.duplicate_bindings = binding_counts
            .into_iter()
            .filter_map(|(name, count)| (count > 1).then_some(name))
            .collect();
        for statement in flattened {
            match &statement {
                Stmt::Defn(Defn::Fn {
                    name,
                    params,
                    ret_ty,
                    effects,
                    body,
                }) => {
                    prepass.functions.insert(
                        name.clone(),
                        (
                            params.iter().map(|param| param.name.clone()).collect(),
                            body.clone(),
                            effects.is_empty(),
                        ),
                    );
                    prepass.actor_runtime_symbols.insert(name.clone());
                }
                Stmt::Defn(Defn::Actor { name, handlers, .. }) => {
                    prepass.actors.insert(
                        name.clone(),
                        handlers
                            .iter()
                            .filter_map(|handler| match &handler.msg_pat {
                                Pat::Con(message, fields) => Some((message.clone(), fields.len())),
                                _ => None,
                            })
                            .collect(),
                    );
                    prepass.actor_runtime_symbols.insert(name.clone());
                }
                Stmt::TypeDecl(TypeDecl::ADT {
                    name,
                    variants,
                    methods,
                    ..
                }) => {
                    prepass.explicit_types.insert(name.clone());
                    prepass
                        .constructors
                        .extend(variants.iter().map(|variant| variant.name.clone()));
                    // ADT method blocks are emitted as standalone root
                    // functions, including methods whose parameter is named
                    // `self`.
                    for method in methods {
                        if let Defn::Fn { name, .. } = method {
                            prepass.actor_runtime_symbols.insert(name.clone());
                        }
                    }
                }
                Stmt::TypeDecl(TypeDecl::EffectDecl { name, .. })
                | Stmt::TypeDecl(TypeDecl::TraitDecl { name, .. }) => {
                    prepass.explicit_types.insert(name.clone());
                }
                Stmt::TypeDecl(TypeDecl::RuleScope { name, .. }) => {
                    prepass.explicit_types.insert(name.clone());
                    prepass.constructors.insert(name.clone());
                }
                Stmt::TypeDecl(TypeDecl::ImplBlock { methods, .. }) => {
                    // Backend impl methods without a `self` parameter are
                    // emitted as standalone functions. Receiver methods remain
                    // inside the Rust impl and do not occupy the bare root
                    // namespace.
                    for method in methods {
                        if let Defn::Fn { name, params, .. } = method {
                            if params.iter().all(|param| param.name != "self") {
                                prepass.actor_runtime_symbols.insert(name.clone());
                            }
                        }
                    }
                }
                Stmt::Rule(Rule::Default { head, .. })
                | Stmt::Rule(Rule::Exception { head, .. })
                | Stmt::Rule(Rule::Clause { head, .. }) => {
                    if let Some(name) = rule_head_name(head) {
                        prepass.rule_names.insert(name.to_string());
                        prepass.actor_runtime_symbols.insert(name.to_string());
                    }
                }
                Stmt::Rule(Rule::ReactiveScope { name, .. }) => {
                    prepass.rule_names.insert(name.clone());
                    prepass.actor_runtime_symbols.insert(name.clone());
                }
                Stmt::Bind(pattern, _, _) => {
                    if let Some(name) = Self::static_binding_name(pattern) {
                        prepass.actor_runtime_symbols.insert(name.to_string());
                    }
                }
                Stmt::StreamBind(name, _) => {
                    prepass.actor_runtime_symbols.insert(name.clone());
                }
                Stmt::RustBlock(code) => {
                    for line in code.lines() {
                        let trimmed = line.trim();
                        let remainder = trimmed
                            .strip_prefix("pub fn ")
                            .or_else(|| trimmed.strip_prefix("fn "));
                        if let Some(remainder) = remainder {
                            if let Some(paren) = remainder.find('(') {
                                let name = remainder[..paren].trim();
                                if !name.is_empty() {
                                    prepass.actor_runtime_symbols.insert(name.to_string());
                                }
                            }
                        }
                    }
                }
                _ => {}
            }
            // `emit_program` scans comptime pairs over its `main_stmts`, after
            // declarations and non-comptime annotations have been routed away.
            // Preserve that exact filtering so a source-only annotation such as
            // `@ export` cannot spuriously consume a pending `@ comptime`.
            let retained_in_codegen_main = match &statement {
                Stmt::Defn(_)
                | Stmt::TypeDecl(_)
                | Stmt::Use(_)
                | Stmt::Import(_)
                | Stmt::QualifiedImport(_, _)
                | Stmt::HashImport(_, _)
                | Stmt::Depend(_, _)
                | Stmt::RustBlock(_) => false,
                Stmt::Annot(name, _) => name == "comptime",
                Stmt::Rule(Rule::ReactiveScope { .. }) => true,
                Stmt::Rule(_) => false,
                _ => true,
            };
            if retained_in_codegen_main {
                prepass.main_statements.push(statement.clone());
            }
            prepass.all_statements.push(statement);
        }
        prepass.resolved_program =
            Self::checked_resolved_program_id(&prepass.analysis_program, &prepass.all_statements);
        prepass
    }

    fn eval_static_type_expr(
        expression: &Expr,
        env: &BTreeMap<String, StaticTypeValue>,
        functions: &BTreeMap<String, (Vec<String>, Expr, bool)>,
        call_stack: &mut BTreeSet<String>,
        budget: &mut StaticTypeBudget,
    ) -> Option<StaticTypeValue> {
        budget.enter()?;
        let result = (|| match &expression.kind {
            ExprKind::Var(name) => env.get(name).and_then(|value| budget.clone_value(value)),
            ExprKind::Lit(Literal::Str(value)) => {
                budget.charge_string(value)?;
                Some(StaticTypeValue::Str(value.clone()))
            }
            ExprKind::List(items) => {
                (items.len() <= StaticTypeBudget::MAX_ITEMS).then_some(())?;
                let values = items
                    .iter()
                    .map(|item| {
                        Self::eval_static_type_expr(item, env, functions, call_stack, budget)
                    })
                    .collect::<Option<Vec<_>>>()?;
                budget.charge(1, 0)?;
                Some(StaticTypeValue::List(values))
            }
            ExprKind::Tuple(items) => {
                (items.len() <= StaticTypeBudget::MAX_ITEMS).then_some(())?;
                let values = items
                    .iter()
                    .map(|item| {
                        Self::eval_static_type_expr(item, env, functions, call_stack, budget)
                    })
                    .collect::<Option<Vec<_>>>()?;
                budget.charge(1, 0)?;
                Some(StaticTypeValue::Tuple(values))
            }
            ExprKind::App(function, arguments) => {
                let ExprKind::Var(function_name) = &function.kind else {
                    return None;
                };
                let arguments = arguments
                    .iter()
                    .map(|argument| {
                        Self::eval_static_type_expr(argument, env, functions, call_stack, budget)
                    })
                    .collect::<Option<Vec<_>>>()?;
                if env.contains_key(function_name) {
                    None
                } else if let Some((parameters, body, effect_free)) = functions.get(function_name) {
                    if !*effect_free
                        || parameters.len() != arguments.len()
                        || !call_stack.insert(function_name.clone())
                    {
                        None
                    } else {
                        let mut function_env = budget.clone_env(env)?;
                        for (parameter, argument) in parameters.iter().zip(arguments) {
                            budget.charge_string(parameter)?;
                            budget.insert_value(&mut function_env, parameter.clone(), argument)?;
                        }
                        let value = Self::eval_static_type_expr(
                            body,
                            &function_env,
                            functions,
                            call_stack,
                            budget,
                        );
                        call_stack.remove(function_name);
                        value
                    }
                } else {
                    match function_name.as_str() {
                        "field" => match arguments.as_slice() {
                            [StaticTypeValue::Str(name), StaticTypeValue::Str(ty)] => {
                                budget.charge_string(name)?;
                                budget.charge_string(ty)?;
                                Some(StaticTypeValue::Field(name.clone(), ty.clone()))
                            }
                            _ => None,
                        },
                        "struct_type" => match arguments.as_slice() {
                            [StaticTypeValue::List(items)]
                                if items.len() <= StaticTypeBudget::MAX_ITEMS =>
                            {
                                let fields = items
                                    .iter()
                                    .map(|item| match item {
                                        StaticTypeValue::Field(name, ty) => {
                                            budget.charge_string(name)?;
                                            budget.charge_string(ty)?;
                                            Some((name.clone(), ty.clone()))
                                        }
                                        _ => None,
                                    })
                                    .collect::<Option<Vec<_>>>()?;
                                budget.charge(1, 0)?;
                                budget.charge_string("struct")?;
                                Some(StaticTypeValue::TypeDef {
                                    kind: "struct".to_string(),
                                    fields,
                                })
                            }
                            _ => None,
                        },
                        "enum_type" => match arguments.as_slice() {
                            [StaticTypeValue::List(items)]
                                if items.len() <= StaticTypeBudget::MAX_ITEMS =>
                            {
                                let fields = items
                                .iter()
                                .map(|item| match item {
                                    StaticTypeValue::Str(name) => {
                                        budget.charge_string(name)?;
                                        Some((name.clone(), String::new()))
                                    }
                                    StaticTypeValue::Tuple(parts) => match parts.as_slice() {
                                        [StaticTypeValue::Str(name), StaticTypeValue::List(fields)] => {
                                            let fields = fields
                                                .iter()
                                                .map(|field| match field {
                                                    StaticTypeValue::Field(field, ty) => {
                                                        let encoded = format!("{}:{}", field, ty);
                                                        budget.charge_string(&encoded)?;
                                                        Some(encoded)
                                                    }
                                                    _ => None,
                                                })
                                                .collect::<Option<Vec<_>>>()?
                                                .join(",");
                                            budget.charge_string(name)?;
                                            budget.charge_string(&fields)?;
                                            Some((name.clone(), fields))
                                        }
                                        _ => None,
                                    },
                                    _ => None,
                                })
                                .collect::<Option<Vec<_>>>()?;
                                budget.charge(1, 0)?;
                                budget.charge_string("enum")?;
                                Some(StaticTypeValue::TypeDef {
                                    kind: "enum".to_string(),
                                    fields,
                                })
                            }
                            _ => None,
                        },
                        _ => None,
                    }
                }
            }
            ExprKind::Block(statements) => {
                let mut block_env = budget.clone_env(env)?;
                let mut value = None;
                for statement in statements {
                    match statement {
                        Stmt::Bind(pattern, _, expression) => {
                            let name = Self::static_binding_name(pattern)?;
                            let binding = Self::eval_static_type_expr(
                                expression, &block_env, functions, call_stack, budget,
                            )?;
                            budget.insert_value(&mut block_env, name.to_string(), binding)?;
                            value = None;
                        }
                        Stmt::Expr(expression) => {
                            value = Some(Self::eval_static_type_expr(
                                expression, &block_env, functions, call_stack, budget,
                            )?);
                        }
                        _ => return None,
                    }
                }
                value
            }
            ExprKind::Lit(_)
            | ExprKind::Lambda(_, _)
            | ExprKind::BinOp(_, _, _)
            | ExprKind::UnOp(_, _)
            | ExprKind::If(_, _, _)
            | ExprKind::Match(_, _)
            | ExprKind::Field(_, _)
            | ExprKind::Index(_, _)
            | ExprKind::Effect(_, _)
            | ExprKind::Handle { .. }
            | ExprKind::Try(_)
            | ExprKind::Conjunction(_)
            | ExprKind::Disjunction(_)
            | ExprKind::Pipe(_, _)
            | ExprKind::Unit => None,
        })();
        budget.leave();
        result
    }

    fn install_constructor_prepass(&mut self, statements: &[Stmt]) {
        let mut prepass = self.build_constructor_prepass(statements);
        let all_statements: Arc<[Stmt]> = std::mem::take(&mut prepass.all_statements).into();
        self.plain_import_rule_dispatch_statements = Arc::clone(&all_statements);
        self.analysis_program = prepass.analysis_program.clone();
        self.resolved_program = prepass.resolved_program.clone();
        self.top_level_constructor_names = prepass.constructors.clone();
        self.root_actor_runtime_symbols = prepass.actor_runtime_symbols.clone();

        // Freeze actor identities only after later-win definition shadowing.
        for (actor, messages) in &prepass.actors {
            let mut seen_in_actor = BTreeSet::new();
            for (message, arity) in messages {
                if !seen_in_actor.insert(message.clone()) {
                    self.error(format!(
                        "actor `{}` declares message constructor `{}` more than once",
                        actor, message
                    ));
                }
                self.actor_message_arities
                    .entry(message.clone())
                    .or_default()
                    .entry(*arity)
                    .or_default()
                    .insert(actor.clone());
            }
        }

        // Phase A mirrors codegen's initial comptime environment: declarations
        // are already registered, then every eligible binding is evaluated once
        // in normalized flattened source order. Duplicate Pat::Var bindings are
        // all skipped by codegen and therefore remain absent here as well.
        let mut env = BTreeMap::new();
        let mut budget = StaticTypeBudget::new();
        let blocked_names = prepass
            .actors
            .keys()
            .chain(prepass.constructors.iter())
            .chain(prepass.rule_names.iter());
        for name in blocked_names {
            if budget
                .insert_value(&mut env, name.clone(), StaticTypeValue::Blocked)
                .is_none()
            {
                return;
            }
        }
        let mut call_stack = BTreeSet::new();
        for statement in all_statements.iter() {
            let Stmt::Bind(pattern, _, expression) = statement else {
                continue;
            };
            let Some(name) = Self::static_binding_name(pattern).map(str::to_string) else {
                continue;
            };
            if matches!(pattern, Pat::Var(_)) && prepass.duplicate_bindings.contains(&name) {
                continue;
            }
            if let Some(value) = Self::eval_static_type_expr(
                expression,
                &env,
                &prepass.functions,
                &mut call_stack,
                &mut budget,
            ) {
                if budget.insert_value(&mut env, name, value).is_none() {
                    return;
                }
            }
        }

        // Phase B mirrors codegen's dependency-ordered `main_stmts` scan. A
        // comptime target is re-evaluated against the completed seed environment,
        // then bound sequentially so a later target can consume its result.
        let main_refs = prepass.main_statements.iter().collect::<Vec<_>>();
        let ordered_main = match analyze_top_level_binding_dependencies(&all_statements)
            .order_statement_refs(&main_refs)
        {
            Ok(ordered) => ordered,
            Err(cycle) => {
                self.error(cycle.to_string());
                return;
            }
        };
        let mut pending_comptime = false;
        let mut known_type_names = prepass.explicit_types;
        for statement in ordered_main {
            if let Stmt::Annot(name, arguments) = statement {
                if name == "comptime" && arguments.is_empty() {
                    pending_comptime = true;
                } else {
                    pending_comptime = false;
                }
                continue;
            }
            let is_target = pending_comptime;
            pending_comptime = false;
            let Stmt::Bind(pattern, _, expression) = statement else {
                continue;
            };
            let Some(name) = Self::static_binding_name(pattern).map(str::to_string) else {
                continue;
            };
            if !is_target {
                continue;
            }
            let value = Self::eval_static_type_expr(
                expression,
                &env,
                &prepass.functions,
                &mut call_stack,
                &mut budget,
            );
            if let Some(StaticTypeValue::TypeDef { kind, fields }) = &value {
                let declaration = comptime_typedef_to_type_decl(&name, kind, fields);
                let TypeDecl::ADT { variants, .. } = &declaration else {
                    unreachable!("comptime TypeDef must lower to an ADT")
                };
                let generated_constructors = variants
                    .iter()
                    .map(|variant| variant.name.clone())
                    .collect::<BTreeSet<_>>();
                if known_type_names.contains(&name) {
                    self.error(format!(
                        "comptime type `{}` collides with an explicit or generated type",
                        name
                    ));
                } else {
                    known_type_names.insert(name.clone());
                    self.top_level_constructor_names
                        .extend(generated_constructors);
                    self.collect_declarations(&[Stmt::TypeDecl(declaration)]);
                }
            }
            if let Some(value) = value {
                if budget.insert_value(&mut env, name, value).is_none() {
                    return;
                }
            }
        }
    }

    fn actor_message_actors(&self, message: &str) -> BTreeSet<String> {
        self.actor_message_arities
            .get(message)
            .into_iter()
            .flat_map(|arities| arities.values())
            .flatten()
            .cloned()
            .collect()
    }

    fn actor_message_arity_label(&self, message: &str) -> Option<String> {
        self.actor_message_arities.get(message).map(|arities| {
            arities
                .keys()
                .map(ToString::to_string)
                .collect::<Vec<_>>()
                .join(" or ")
        })
    }

    fn define_actor_handle(&mut self, name: &str, actor: Option<&str>) {
        if let Some(scope) = self.actor_handle_scopes.last_mut() {
            scope.insert(name.to_string(), actor.map(str::to_string));
        }
    }

    fn actor_for_handle_expr(&self, expression: &Expr) -> Option<String> {
        if let Some(actor) = Self::spawned_actor_name(expression) {
            return Some(actor.to_string());
        }
        match &expression.kind {
            ExprKind::Var(name) => self
                .actor_handle_scopes
                .iter()
                .rev()
                .find_map(|scope| scope.get(name))
                .cloned()
                .flatten(),
            _ => None,
        }
    }

    fn spawned_actor_name(expression: &Expr) -> Option<&str> {
        let ExprKind::App(function, arguments) = &expression.kind else {
            return None;
        };
        if arguments.len() != 2 {
            return None;
        }
        let ExprKind::Var(function_name) = &function.kind else {
            return None;
        };
        if function_name != "spawn" {
            return None;
        }
        match &arguments[0].kind {
            ExprKind::Var(actor) => Some(actor),
            _ => None,
        }
    }

    fn actor_message_parts(expression: &Expr) -> Option<(&str, &[Expr])> {
        match &expression.kind {
            ExprKind::Var(name) => Some((name, &[])),
            ExprKind::App(function, arguments) => match &function.kind {
                ExprKind::Var(name) => Some((name, arguments)),
                _ => None,
            },
            _ => None,
        }
    }

    /// Check a syntactic actor message. Returns true only when this expression
    /// was recognized as an actor constructor and therefore fully consumed.
    fn check_actor_message(&mut self, target: Option<&Expr>, expression: &Expr) -> bool {
        let Some((message, arguments)) = Self::actor_message_parts(expression) else {
            return false;
        };
        let Some(arities) = self.actor_message_arities.get(message) else {
            return false;
        };
        let lexical_collision = self
            .scopes
            .iter()
            .skip(1)
            .rev()
            .any(|scope| scope.contains(message));
        let runtime_collision =
            self.root_actor_runtime_symbols.contains(message) || lexical_collision;
        let data_constructor_collision = self.constructors.contains_key(message);
        // Outside an explicit send/ask, ordinary values/functions retain normal
        // expression precedence. At an actor-message site the backend emits the
        // name bare, so a same-name runtime symbol is unsafe and rejected.
        if target.is_none() && (runtime_collision || data_constructor_collision) {
            return false;
        }
        let actors = self.actor_message_actors(message);
        if runtime_collision {
            self.error_at_expr(
                expression,
                format!(
                    "actor message `{}` collides with an ordinary variable or function",
                    message
                ),
            );
        } else if actors.len() > 1 {
            self.error_at_expr(
                expression,
                format!(
                    "actor message `{}` is ambiguous; declared by actors {}",
                    message,
                    actors.into_iter().collect::<Vec<_>>().join(", ")
                ),
            );
        } else if data_constructor_collision {
            self.error_at_expr(
                expression,
                format!(
                    "actor message `{}` collides with an ordinary data constructor",
                    message
                ),
            );
        } else if !arities.contains_key(&arguments.len()) {
            let expected = self
                .actor_message_arity_label(message)
                .expect("known actor message has arity metadata");
            self.error_at_expr(
                expression,
                format!(
                    "actor message `{}` expects {} field{} but got {}",
                    message,
                    expected,
                    if expected == "1" { "" } else { "s" },
                    arguments.len()
                ),
            );
        } else if has_named_args(arguments) {
            self.error_at_expr(
                expression,
                format!(
                    "actor message `{}` requires positional fields; named fields are not supported",
                    message
                ),
            );
        } else if let Some(target_actor) =
            target.and_then(|target| self.actor_for_handle_expr(target))
        {
            if !actors.contains(&target_actor) {
                self.error_at_expr(
                    expression,
                    format!(
                        "actor `{}` has no message constructor `{}`",
                        target_actor, message
                    ),
                );
            }
        }
        for argument in arguments {
            self.check_expr(argument, None);
        }
        true
    }

    fn constructor_signature_for_args(
        &self,
        constructor: &str,
        args: &[Expr],
    ) -> Option<TypeConstructorSignature> {
        let matching = self
            .constructor_signatures
            .get(constructor)?
            .iter()
            .filter(|signature| signature.matches_args(args))
            .collect::<Vec<_>>();
        let parents = matching
            .iter()
            .map(|signature| signature.parent.as_str())
            .collect::<BTreeSet<_>>();
        if parents.len() == 1 {
            return matching.first().map(|signature| (*signature).clone());
        }
        None
    }

    fn constructor_signature_for_parent(
        &self,
        constructor: &str,
        parent: Option<&str>,
    ) -> Option<TypeConstructorSignature> {
        let signatures = self.constructor_signatures.get(constructor)?;
        if let Some(parent) = parent {
            if let Some(signature) = signatures
                .iter()
                .find(|signature| signature.parent == parent)
            {
                return Some(signature.clone());
            }
        }
        let (fallback_parent, fallback_arity) = self.constructors.get(constructor)?;
        signatures
            .iter()
            .find(|signature| {
                signature.parent == *fallback_parent && signature.arity() == *fallback_arity
            })
            .cloned()
            .or_else(|| signatures.last().cloned())
    }

    fn constructor_signature_for_named_validation(
        &self,
        constructor: &str,
        args: &[Expr],
    ) -> Option<TypeConstructorSignature> {
        if let Some(signature) = self.constructor_signature_for_args(constructor, args) {
            return Some(signature);
        }
        let supplied = args
            .iter()
            .filter_map(named_arg_parts)
            .map(|(field, _)| field)
            .collect::<BTreeSet<_>>();
        self.constructor_signatures
            .get(constructor)?
            .iter()
            .filter(|signature| !signature.positional)
            .max_by_key(|signature| {
                signature
                    .fields
                    .iter()
                    .filter(|field| supplied.contains(field.as_str()))
                    .count()
            })
            .cloned()
            .or_else(|| self.constructor_signature_for_parent(constructor, None))
    }

    fn constructor_parent_for_args(&self, constructor: &str, args: &[Expr]) -> Option<String> {
        self.constructor_signature_for_args(constructor, args)
            .map(|signature| signature.parent)
    }

    fn nullary_constructor_parent(&self, constructor: &str) -> Option<String> {
        let matching = self
            .constructor_signatures
            .get(constructor)?
            .iter()
            .filter(|signature| signature.arity() == 0)
            .map(|signature| signature.parent.as_str())
            .collect::<BTreeSet<_>>();
        (matching.len() == 1).then(|| matching.into_iter().next().unwrap().to_string())
    }

    fn check_named_constructor_args(
        &mut self,
        expr: &Expr,
        constructor: &str,
        args: &[Expr],
        signature: TypeConstructorSignature,
    ) {
        if args.iter().any(|arg| !is_named_arg_expr(arg)) {
            self.error_at_expr(
                expr,
                format!(
                    "constructor `{}` call mixes named and positional arguments; use either all named fields or all positional fields",
                    constructor
                ),
            );
            for arg in args {
                if let Some((_, value)) = named_arg_parts(arg) {
                    self.check_expr(value, None);
                } else {
                    self.check_expr(arg, None);
                }
            }
            return;
        }

        if signature.positional {
            self.error_at_expr(
                expr,
                format!(
                    "constructor `{}` does not have named fields; use positional arguments",
                    constructor
                ),
            );
            for arg in args {
                if let Some((_, value)) = named_arg_parts(arg) {
                    self.check_expr(value, None);
                }
            }
            return;
        }

        let fields = signature.fields;
        let field_tys = signature.field_tys;
        let expected = fields.len();

        let field_set: BTreeSet<&str> = fields.iter().map(|field| field.as_str()).collect();
        let mut seen = BTreeSet::new();
        for arg in args {
            if let Some((field, value)) = named_arg_parts(arg) {
                if !field_set.contains(field) {
                    self.error_at_expr(
                        arg,
                        format!("constructor `{}` has no field `{}`", constructor, field),
                    );
                }
                if !seen.insert(field.to_string()) {
                    self.error_at_expr(
                        arg,
                        format!(
                            "constructor `{}` field `{}` was provided more than once",
                            constructor, field
                        ),
                    );
                }
                if fields.iter().any(|candidate| candidate == field) {
                    let expected_type = fields
                        .iter()
                        .position(|candidate| candidate == field)
                        .and_then(|index| field_tys.get(index))
                        .and_then(|field_ty| field_ty.as_ref())
                        .and_then(|field_ty| parse_type_annotation(field_ty).ok());
                    let actual_type = self
                        .infer_expr_type_name(value)
                        .and_then(|type_name| parse_type_annotation(&type_name).ok());
                    if let (Some(Ty::Name(expected_type)), Some(Ty::Name(actual_type))) =
                        (expected_type.as_ref(), actual_type)
                    {
                        if self.types.contains(expected_type)
                            && self.types.contains(&actual_type)
                            && expected_type != &actual_type
                        {
                            self.error_at_expr(
                                value,
                                format!(
                                    "constructor `{}` field `{}` expects `{}` but expression has `{}`",
                                    constructor, field, expected_type, actual_type
                                ),
                            );
                        }
                    }
                }
                self.check_expr(value, None);
            }
        }

        if args.len() != expected {
            self.error_at_expr(
                expr,
                format!(
                    "constructor `{}` expects {} named field{} but got {}",
                    constructor,
                    expected,
                    if expected == 1 { "" } else { "s" },
                    args.len()
                ),
            );
        }

        for field in &fields {
            if !seen.contains(field) {
                self.error_at_expr(
                    expr,
                    format!(
                        "constructor `{}` is missing named field `{}`",
                        constructor, field
                    ),
                );
            }
        }
    }

    fn check_named_call_args(
        &mut self,
        expr: &Expr,
        kind: &str,
        callable: &str,
        args: &[Expr],
        params: &[String],
    ) {
        if args.iter().any(|arg| !is_named_arg_expr(arg)) {
            self.error_at_expr(
                expr,
                format!(
                    "{} `{}` call mixes named and positional arguments; use either all named arguments or all positional arguments",
                    kind, callable
                ),
            );
            for arg in args {
                if let Some((_, value)) = named_arg_parts(arg) {
                    self.check_expr(value, None);
                } else {
                    self.check_expr(arg, None);
                }
            }
            return;
        }

        let param_set: BTreeSet<&str> = params.iter().map(|param| param.as_str()).collect();
        let mut seen = BTreeSet::new();
        for arg in args {
            if let Some((param, value)) = named_arg_parts(arg) {
                if !param_set.contains(param) {
                    self.error_at_expr(
                        arg,
                        format!("{} `{}` has no parameter `{}`", kind, callable, param),
                    );
                }
                if !seen.insert(param.to_string()) {
                    self.error_at_expr(
                        arg,
                        format!(
                            "{} `{}` parameter `{}` was provided more than once",
                            kind, callable, param
                        ),
                    );
                }
                self.check_expr(value, None);
            }
        }

        if args.len() != params.len() {
            self.error_at_expr(
                expr,
                format!(
                    "{} `{}` expects {} named argument{} but got {}",
                    kind,
                    callable,
                    params.len(),
                    if params.len() == 1 { "" } else { "s" },
                    args.len()
                ),
            );
        }

        for param in params {
            if !seen.contains(param) {
                self.error_at_expr(
                    expr,
                    format!(
                        "{} `{}` is missing named argument `{}`",
                        kind, callable, param
                    ),
                );
            }
        }
    }

    fn rule_head_local_types(&self, head: &Expr) -> BTreeMap<String, String> {
        let mut locals = BTreeMap::new();
        if let ExprKind::App(_, args) = &head.kind {
            for arg in args {
                self.collect_rule_head_local_types(arg, None, &mut locals);
            }
        }
        locals
    }

    fn collect_rule_head_local_types(
        &self,
        arg: &Expr,
        expected_type: Option<&str>,
        locals: &mut BTreeMap<String, String>,
    ) {
        if let Some((inner, type_name)) = Self::typed_rule_arg_parts(arg) {
            let type_name = Self::canonical_explore_type_name(type_name);
            if let ExprKind::Var(name) = &inner.kind {
                locals.insert(name.clone(), type_name.clone());
            }
            self.collect_rule_head_local_types(inner, Some(&type_name), locals);
            return;
        }

        match &arg.kind {
            ExprKind::App(func, args) if matches!(&func.kind, ExprKind::Var(name) if name == NAMED_ARG_MARKER) => {
                if let Some(value) = args.get(1) {
                    self.collect_rule_head_local_types(value, expected_type, locals);
                }
            }
            ExprKind::App(func, args) => {
                let signature = match &func.kind {
                    ExprKind::Var(constructor) => match expected_type {
                        Some(parent) => self
                            .constructor_signature_for_parent(constructor, Some(parent))
                            .filter(|signature| {
                                signature.parent == parent && signature.matches_args(args)
                            }),
                        None => self.constructor_signature_for_args(constructor, args),
                    },
                    _ => None,
                };
                if let Some(signature) = signature {
                    for (index, arg) in args.iter().enumerate() {
                        let (value, field_index) = named_arg_parts(arg)
                            .map(|(field, value)| {
                                (
                                    value,
                                    signature
                                        .fields
                                        .iter()
                                        .position(|candidate| candidate == field),
                                )
                            })
                            .unwrap_or((arg, Some(index)));
                        let field_type = field_index
                            .and_then(|index| signature.field_types.get(index))
                            .and_then(Option::as_deref);
                        self.collect_rule_head_local_types(value, field_type, locals);
                    }
                } else {
                    for arg in args {
                        self.collect_rule_head_local_types(arg, None, locals);
                    }
                }
            }
            ExprKind::Tuple(items) => {
                for item in items {
                    self.collect_rule_head_local_types(item, None, locals);
                }
            }
            ExprKind::Var(name)
                if name != "_" && !name.chars().next().is_some_and(char::is_uppercase) =>
            {
                if let Some(expected_type) = expected_type {
                    locals.insert(name.clone(), expected_type.to_string());
                }
            }
            _ => {}
        }
    }

    fn scoped_member_return_type(
        &self,
        scope_name: &str,
        member: &str,
        arity: usize,
    ) -> Option<String> {
        let declared_arity = self
            .rule_scope_methods
            .get(scope_name)
            .and_then(|members| members.get(member))
            .or_else(|| {
                self.rule_scope_value_methods
                    .get(scope_name)
                    .and_then(|members| members.get(member))
            });
        if declared_arity != Some(&arity) {
            return None;
        }
        self.rule_scope_member_return_types
            .get(scope_name)
            .and_then(|members| members.get(member))
            .cloned()
    }

    fn field_type_name(&self, type_name: &str, field: &str) -> Option<String> {
        self.type_field_tys
            .get(type_name)
            .and_then(|fields| fields.get(field))
            .map(Self::canonical_explore_ty_name)
            .or_else(|| {
                self.type_field_types
                    .get(type_name)
                    .and_then(|fields| fields.get(field))
                    .cloned()
            })
    }

    fn pathof_transparent_ty(ty: &Ty) -> &Ty {
        match ty {
            Ty::Optional(inner) | Ty::Ref(inner) | Ty::MutRef(inner) | Ty::Shared(inner) => {
                Self::pathof_transparent_ty(inner)
            }
            Ty::App(constructor, arguments) => {
                let Ty::Name(name) = constructor.as_ref() else {
                    return ty;
                };
                let inner = match name.as_str() {
                    "List" | "Set" | "Option" => arguments.first(),
                    "Map" => arguments.get(1),
                    _ => None,
                };
                inner.map(Self::pathof_transparent_ty).unwrap_or(ty)
            }
            _ => ty,
        }
    }

    fn pathof_named_type(ty: &Ty) -> Option<&str> {
        match ty {
            Ty::Name(name) => Some(name),
            Ty::App(constructor, _) => match constructor.as_ref() {
                Ty::Name(name) => Some(name),
                _ => None,
            },
            _ => None,
        }
    }

    fn check_structural_path_expr(
        &mut self,
        expr: &Expr,
        arguments: &[Expr],
        operation: &str,
        allow_terminal_variant: bool,
    ) {
        if arguments.len() < 2 {
            self.error_at_expr(
                expr,
                format!(
                    "{} requires a root type and at least one path segment",
                    operation
                ),
            );
            return;
        }

        let ExprKind::Lit(Literal::Str(root)) = &arguments[0].kind else {
            self.error_at_expr(
                &arguments[0],
                format!("{} root must be a declared type name", operation),
            );
            return;
        };
        if !self.types.contains(root) {
            self.error_at_expr(
                &arguments[0],
                format!("{} references unknown type `{}`", operation, root),
            );
            return;
        }

        let mut current = Ty::Name(root.clone());
        for (index, argument) in arguments.iter().enumerate().skip(1) {
            let ExprKind::Lit(Literal::Str(segment)) = &argument.kind else {
                self.error_at_expr(
                    argument,
                    format!("{} segments must be structural names", operation),
                );
                return;
            };
            current = Self::pathof_transparent_ty(&current).clone();
            let Some(type_name) = Self::pathof_named_type(&current).map(str::to_string) else {
                self.error_at_expr(
                    argument,
                    format!(
                        "{} cannot traverse `{}` through non-record type `{}`",
                        operation, segment, current
                    ),
                );
                return;
            };

            let variants = self.type_variants.get(&type_name).cloned();
            if segment == "$variant" {
                if variants.as_ref().is_none_or(Vec::is_empty) {
                    self.error_at_expr(
                        argument,
                        format!(
                            "{} selector `$variant` requires a sum type, but `{}` has no alternatives",
                            operation, type_name
                        ),
                    );
                } else if index + 1 != arguments.len() {
                    self.error_at_expr(
                        argument,
                        format!(
                            "{} selector `$variant` is a terminal discriminator path",
                            operation
                        ),
                    );
                }
                return;
            }

            if let Some(variants) = variants.filter(|variants| !variants.is_empty()) {
                if variants.contains(segment) {
                    if index + 1 == arguments.len() {
                        if !allow_terminal_variant {
                            self.error_at_expr(
                                argument,
                                format!(
                                    "{} variant selector `{}` must be followed by a field; use `$variant` to target the discriminator",
                                    operation, segment
                                ),
                            );
                        }
                        return;
                    }
                    current = Ty::Name(segment.clone());
                    continue;
                }
                self.error_at_expr(
                    argument,
                    format!(
                        "{} must select a variant of `{}` before traversing its fields; expected one of: {}",
                        operation, type_name,
                        variants.join(", ")
                    ),
                );
                return;
            }

            let field_ty = self
                .type_field_tys
                .get(&type_name)
                .and_then(|fields| fields.get(segment))
                .cloned();
            let Some(field_ty) = field_ty else {
                let known_fields = self
                    .type_field_tys
                    .get(&type_name)
                    .map(|fields| fields.keys().cloned().collect::<Vec<_>>())
                    .unwrap_or_default();
                let suffix = if known_fields.is_empty() {
                    String::new()
                } else {
                    format!("; known fields: {}", known_fields.join(", "))
                };
                self.error_at_expr(
                    argument,
                    format!(
                        "{} type `{}` has no field `{}`{}",
                        operation, type_name, segment, suffix
                    ),
                );
                return;
            };
            current = field_ty;
        }
    }

    fn check_pathof_expr(&mut self, expr: &Expr, arguments: &[Expr]) {
        self.check_structural_path_expr(expr, arguments, "pathof", false);
    }

    fn check_refof_expr(&mut self, expr: &Expr, arguments: &[Expr]) {
        if arguments.len() < 2 {
            self.error_at_expr(expr, "refof requires a declaration target".to_string());
            return;
        }
        let ExprKind::Lit(Literal::Str(mode)) = &arguments[0].kind else {
            self.error_at_expr(expr, "invalid internal refof target mode".to_string());
            return;
        };
        let ExprKind::Lit(Literal::Str(root)) = &arguments[1].kind else {
            self.error_at_expr(expr, "refof target must be a declared name".to_string());
            return;
        };

        if mode == "symbol" {
            let Some(kinds) = self.reference_symbols.get(root) else {
                self.error_at_expr(
                    &arguments[1],
                    format!("refof references unknown symbol `{}`", root),
                );
                return;
            };
            if kinds.len() > 1 {
                let labels = kinds
                    .iter()
                    .map(|kind| kind.label())
                    .collect::<Vec<_>>()
                    .join(", ");
                self.error_at_expr(
                    &arguments[1],
                    format!(
                        "refof symbol `{}` is ambiguous; it is declared as: {}",
                        root, labels
                    ),
                );
            }
            return;
        }

        if mode != "type" {
            self.error_at_expr(expr, "invalid internal refof target mode".to_string());
            return;
        }
        if !self.types.contains(root) {
            self.error_at_expr(
                &arguments[1],
                format!("refof references unknown type `{}`", root),
            );
            return;
        }
        if arguments.len() == 2 {
            return;
        }

        if self.type_has_scoped_members(root) {
            let ExprKind::Lit(Literal::Str(member)) = &arguments[2].kind else {
                self.error_at_expr(
                    &arguments[2],
                    "refof scoped member must be a declared name".to_string(),
                );
                return;
            };
            let field = self
                .type_field_tys
                .get(root)
                .is_some_and(|fields| fields.contains_key(member));
            let scoped_rule = self
                .rule_scope_methods
                .get(root)
                .is_some_and(|methods| methods.contains_key(member));
            let scoped_function = self
                .rule_scope_value_methods
                .get(root)
                .is_some_and(|methods| methods.contains_key(member));
            let matches =
                usize::from(field) + usize::from(scoped_rule) + usize::from(scoped_function);
            if matches > 1 {
                self.error_at_expr(
                    &arguments[2],
                    format!(
                        "refof member `{}::{}` is ambiguous between a captured field and scoped callable",
                        root, member
                    ),
                );
                return;
            }
            if scoped_rule || scoped_function {
                if arguments.len() > 3 {
                    self.error_at_expr(
                        &arguments[3],
                        format!("refof scoped member `{}::{}` is terminal", root, member),
                    );
                }
                return;
            }
        }

        self.check_structural_path_expr(expr, &arguments[1..], "refof", true);
    }

    fn constructor_pattern_field_type_name(
        &self,
        constructor: &str,
        index: usize,
        parent: Option<&str>,
    ) -> Option<String> {
        let generic_field = match (constructor, index) {
            ("Some", 0) => Some(("Option", 0)),
            ("Ok", 0) => Some(("Result", 0)),
            ("Err", 0) => Some(("Result", 1)),
            _ => None,
        };
        if let (Some(parent), Some((generic_parent, generic_index))) = (parent, generic_field) {
            if let Some(field_type) =
                Self::applied_type_argument(parent, generic_parent, generic_index)
            {
                return Some(field_type);
            }
        }

        self.constructor_signature_for_parent(constructor, parent)
            .and_then(|signature| signature.field_tys.get(index).cloned().flatten())
            .or_else(|| {
                self.constructor_signature_for_parent(constructor, parent)
                    .and_then(|signature| signature.field_types.get(index).cloned().flatten())
            })
            .or_else(|| {
                let field = self
                    .constructor_fields
                    .get(constructor)
                    .and_then(|fields| fields.get(index))
                    .cloned()
                    .unwrap_or_else(|| format!("_{}", index));
                self.field_type_name(constructor, &field)
            })
    }

    fn named_constructor_pattern_field_type_name(
        &self,
        constructor: &str,
        field: &str,
        parent: Option<&str>,
    ) -> Option<String> {
        self.constructor_signature_for_parent(constructor, parent)
            .and_then(|signature| {
                signature
                    .fields
                    .iter()
                    .position(|candidate| candidate == field)
                    .and_then(|index| signature.field_tys.get(index).cloned().flatten())
            })
            .or_else(|| {
                self.constructor_signature_for_parent(constructor, parent)
                    .and_then(|signature| {
                        signature
                            .fields
                            .iter()
                            .position(|candidate| candidate == field)
                            .and_then(|index| signature.field_types.get(index).cloned().flatten())
                    })
            })
            .or_else(|| self.field_type_name(constructor, field))
    }

    fn collect_pattern_type_bindings(
        &self,
        pat: &Pat,
        subject_type: Option<&str>,
        bindings: &mut BTreeMap<String, String>,
    ) {
        match pat {
            Pat::Var(name) => {
                if let Some(type_name) = subject_type {
                    bindings.insert(name.clone(), type_name.to_string());
                }
            }
            Pat::Con(constructor, fields) => {
                for (index, field_pat) in fields.iter().enumerate() {
                    let field_type =
                        self.constructor_pattern_field_type_name(constructor, index, subject_type);
                    self.collect_pattern_type_bindings(field_pat, field_type.as_deref(), bindings);
                }
            }
            Pat::NamedCon(constructor, fields) => {
                for (field, field_pat) in fields {
                    let field_type = self.named_constructor_pattern_field_type_name(
                        constructor,
                        field,
                        subject_type,
                    );
                    self.collect_pattern_type_bindings(field_pat, field_type.as_deref(), bindings);
                }
            }
            Pat::As(inner, name) => {
                if let Some(type_name) = subject_type {
                    bindings.insert(name.clone(), type_name.to_string());
                }
                self.collect_pattern_type_bindings(inner, subject_type, bindings);
            }
            Pat::Wild | Pat::Lit(_) => {}
        }
    }

    fn pattern_type_bindings(
        &self,
        pat: &Pat,
        subject_type: Option<&str>,
    ) -> BTreeMap<String, String> {
        let mut bindings = BTreeMap::new();
        self.collect_pattern_type_bindings(pat, subject_type, &mut bindings);
        bindings
    }

    fn infer_expr_type_name(&self, expr: &Expr) -> Option<String> {
        self.infer_expr_type_name_with_locals(expr, &BTreeMap::new())
    }

    fn is_polymorphic_empty_list_expr(expr: &Expr) -> bool {
        match &expr.kind {
            ExprKind::List(items) => items.is_empty(),
            ExprKind::Block(stmts) => stmts.last().is_some_and(|stmt| match stmt {
                Stmt::Expr(result) => Self::is_polymorphic_empty_list_expr(result),
                _ => false,
            }),
            _ => false,
        }
    }

    fn infer_callable_result_type_with_locals(
        &self,
        callable: &Expr,
        arity: usize,
        locals: &BTreeMap<String, String>,
        active_rule_scope: Option<&str>,
    ) -> Option<String> {
        match &callable.kind {
            ExprKind::Lambda(params, body) if params.len() == arity => {
                let mut lambda_locals = locals.clone();
                for param in params {
                    let ty = param.ty.as_ref()?;
                    if matches!(ty, Ty::Hole) {
                        return None;
                    }
                    let ty = Self::canonical_explore_ty_name(ty);
                    lambda_locals.insert(param.name.clone(), ty);
                }
                self.infer_expr_type_name_with_locals_in_scope(
                    body,
                    &lambda_locals,
                    active_rule_scope,
                )
            }
            ExprKind::Var(name) => {
                if let Some(local_type) = locals.get(name) {
                    if let Ok(Ty::Arrow(_, return_type)) = parse_type_annotation(local_type) {
                        return Self::type_name_from_ty(&return_type);
                    }
                }
                if let Some(scope) = active_rule_scope {
                    let key = RuleDispatchKey {
                        scope: Some(scope.to_string()),
                        name: name.clone(),
                        arity,
                    };
                    if self.rule_dispatch_keys.contains(&key) {
                        return self.rule_dispatch_return_types.get(&key).cloned();
                    }
                    if let Some(return_type) = self.scoped_member_return_type(scope, name, arity) {
                        return Some(return_type);
                    }
                }
                self.explore_function_return_types_by_arity
                    .get(&(name.clone(), arity))
                    .and_then(Self::type_name_from_ty)
                    .or_else(|| {
                        self.explore_rule_return_types_by_arity
                            .get(&(name.clone(), arity))
                            .and_then(Self::type_name_from_ty)
                    })
                    .or_else(|| {
                        let key = RuleDispatchKey {
                            scope: None,
                            name: name.clone(),
                            arity,
                        };
                        self.rule_dispatch_return_types.get(&key).cloned()
                    })
                    .or_else(|| self.rule_return_types.get(name).cloned())
            }
            _ => None,
        }
    }

    /// Exact result laws for builtins whose result type is determined by
    /// their argument types. Keeping these laws beside ordinary expression
    /// inference gives checking and the Explore resolution recorder one
    /// shared authority; no runtime value or corpus-specific name is guessed.
    fn infer_checked_intrinsic_result_with_locals(
        &self,
        name: &str,
        args: &[Expr],
        locals: &BTreeMap<String, String>,
        active_rule_scope: Option<&str>,
    ) -> Option<String> {
        let argument_type = |index: usize| {
            args.get(index).and_then(|argument| {
                self.infer_expr_type_name_with_locals_in_scope(argument, locals, active_rule_scope)
            })
        };
        match (name, args.len()) {
            ("show" | "show_int" | "show_float" | "rust_debug", 1) => Some("String".to_string()),
            ("exp" | "ln" | "sqrt" | "to_float", 1) | ("pow", 2) => Some("Float".to_string()),
            ("round" | "floor" | "string_length", 1) => Some("Int".to_string()),
            ("contains" | "map_contains" | "set_contains", 2) | ("is_some" | "is_none", 1) => {
                Some("Bool".to_string())
            }
            ("map_len" | "set_len", 1) | ("count_by", 2) => Some("Int".to_string()),
            ("tail", 1)
            | ("push", 2)
            | ("map_insert", 3)
            | ("map_remove" | "map_merge", 2)
            | ("set_insert" | "set_remove", 2)
            | ("set_union" | "set_intersect" | "set_diff", 2) => argument_type(0),
            ("map_get_or", 3) => argument_type(2),
            ("map_get", 2) => {
                let map_type = argument_type(0)?;
                let value_type = Self::applied_type_argument(&map_type, "Map", 1)?;
                Some(format!("Option({value_type})"))
            }
            ("map_keys", 1) => {
                let map_type = argument_type(0)?;
                let key_type = Self::applied_type_argument(&map_type, "Map", 0)?;
                Some(format!("List({key_type})"))
            }
            ("map_values", 1) => {
                let map_type = argument_type(0)?;
                let value_type = Self::applied_type_argument(&map_type, "Map", 1)?;
                Some(format!("List({value_type})"))
            }
            ("set_to_list", 1) => {
                let set_type = argument_type(0)?;
                let item_type = Self::applied_type_argument(&set_type, "Set", 0)?;
                Some(format!("List({item_type})"))
            }
            ("set_from_list", 1) => {
                let list_type = argument_type(0)?;
                let item_type = Self::applied_type_argument(&list_type, "List", 0)?;
                Some(format!("Set({item_type})"))
            }
            ("list_min" | "list_max", 1) => {
                let list_type = argument_type(0)?;
                let item_type = Self::applied_type_argument(&list_type, "List", 0)?;
                Some(format!("Option({item_type})"))
            }
            ("take" | "skip", 2) => {
                let collection_type = argument_type(0)?;
                let item_type =
                    ["List", "Stream", "Subject"]
                        .into_iter()
                        .find_map(|constructor| {
                            Self::applied_type_argument(&collection_type, constructor, 0)
                        })?;
                // Runtime `take`/`skip` are stream-producing even when their
                // finite input happens to be represented as a list.
                Some(format!("Stream({item_type})"))
            }
            ("collect", 1) => {
                let collection_type = argument_type(0)?;
                let item_type =
                    ["List", "Stream", "Subject"]
                        .into_iter()
                        .find_map(|constructor| {
                            Self::applied_type_argument(&collection_type, constructor, 0)
                        })?;
                Some(format!("List({item_type})"))
            }
            ("take_while" | "drop_while", 2) => argument_type(0),
            ("chunked", 2) => {
                let list_type = argument_type(0)?;
                let item_type = Self::applied_type_argument(&list_type, "List", 0)?;
                Some(format!("List(List({item_type}))"))
            }
            ("partition", 2) => {
                let list_type = argument_type(0)?;
                Some(format!("Tuple({list_type}, {list_type})"))
            }
            _ => None,
        }
    }

    fn infer_expr_type_name_with_locals(
        &self,
        expr: &Expr,
        locals: &BTreeMap<String, String>,
    ) -> Option<String> {
        self.infer_expr_type_name_with_locals_in_scope(
            expr,
            locals,
            self.active_rule_scope_inference.as_deref(),
        )
    }

    /// Infer an expression while retaining the exact lexical RuleScope.
    ///
    /// The rule-return fixed point historically carried this context in a
    /// mutable checker field. Checked resolution runs later and has its own
    /// lexical walk, so relying on that ambient field loses scoped sibling
    /// calls inside composite expressions. Make the context an explicit
    /// recursive input instead.
    fn infer_expr_type_name_with_locals_in_scope(
        &self,
        expr: &Expr,
        locals: &BTreeMap<String, String>,
        active_rule_scope: Option<&str>,
    ) -> Option<String> {
        match &expr.kind {
            ExprKind::Lit(literal) => Some(Self::obvious_literal_ty(literal).to_string()),
            ExprKind::Unit => Some("()".to_string()),
            ExprKind::List(items) => {
                let mut item_type = None;
                for item in items {
                    let inferred = self.infer_expr_type_name_with_locals_in_scope(
                        item,
                        locals,
                        active_rule_scope,
                    )?;
                    if item_type.as_ref().is_some_and(|known| known != &inferred) {
                        return None;
                    }
                    item_type = Some(inferred);
                }
                item_type.map(|inner| format!("List({})", inner))
            }
            ExprKind::Tuple(items) => {
                let item_types = items
                    .iter()
                    .map(|item| {
                        self.infer_expr_type_name_with_locals_in_scope(
                            item,
                            locals,
                            active_rule_scope,
                        )
                    })
                    .collect::<Option<Vec<_>>>()?;
                Some(format!("Tuple({})", item_types.join(", ")))
            }
            ExprKind::Var(name) => match locals.get(name) {
                Some(type_name) if type_name == CHECKED_UNTYPED_SHADOW_TYPE_TOMBSTONE => None,
                Some(type_name) => Some(type_name.clone()),
                None => self
                    .var_type_name(name)
                    .map(str::to_string)
                    .or_else(|| self.nullary_constructor_parent(name))
                    .or_else(|| {
                        self.constructors
                            .get(name)
                            .map(|(parent, _)| parent.clone())
                    }),
            },
            ExprKind::App(func, args) => {
                if let ExprKind::Var(name) = &func.as_ref().kind {
                    if name == NAMED_ARG_MARKER {
                        return args.get(1).and_then(|value| {
                            self.infer_expr_type_name_with_locals_in_scope(
                                value,
                                locals,
                                active_rule_scope,
                            )
                        });
                    }
                    if name == PATHOF_MARKER {
                        return Some("String".to_string());
                    }
                    if name == REFOF_MARKER {
                        return Some("ProgramReference".to_string());
                    }
                    if !locals.contains_key(name)
                        && !self.explore_contextual_intrinsic_is_shadowed(name, args.len())
                    {
                        if let Some(result) = self.infer_checked_intrinsic_result_with_locals(
                            builtin_canonical(name),
                            args,
                            locals,
                            active_rule_scope,
                        ) {
                            return Some(result);
                        }
                    }
                    if name == "Some" && args.len() == 1 {
                        if let Some(inner) = self.infer_expr_type_name_with_locals_in_scope(
                            &args[0],
                            locals,
                            active_rule_scope,
                        ) {
                            return Some(format!("Option({})", inner));
                        }
                    }
                    // `foldl(collection, initial, step)` always returns the
                    // accumulator type, including for an empty collection.
                    // This is an exact higher-order builtin law, not a guess
                    // from the callback body, and lets Explore validate pure
                    // corpus helpers without expanding their finite inputs.
                    if name == "foldl" && args.len() == 3 {
                        if let Some(initial_type) = self.infer_expr_type_name_with_locals_in_scope(
                            &args[1],
                            locals,
                            active_rule_scope,
                        ) {
                            return Some(initial_type);
                        }
                        if Self::is_polymorphic_empty_list_expr(&args[1]) {
                            if let ExprKind::Lambda(params, _) = &args[2].kind {
                                if params.len() == 2 {
                                    return params[0].ty.as_ref().and_then(Self::type_name_from_ty);
                                }
                            }
                        }
                        return None;
                    }
                    if name == "map" && args.len() == 2 {
                        let result = self.infer_callable_result_type_with_locals(
                            &args[1],
                            1,
                            locals,
                            active_rule_scope,
                        )?;
                        let collection_type = self.infer_expr_type_name_with_locals_in_scope(
                            &args[0],
                            locals,
                            active_rule_scope,
                        )?;
                        let output_constructor =
                            if Self::applied_type_argument(&collection_type, "List", 0).is_some() {
                                "List"
                            } else if ["Stream", "Subject"].into_iter().any(|constructor| {
                                Self::applied_type_argument(&collection_type, constructor, 0)
                                    .is_some()
                            }) {
                                "Stream"
                            } else {
                                return None;
                            };
                        return Some(format!("{output_constructor}({result})"));
                    }
                    if name == "flat_map" && args.len() == 2 {
                        return self.infer_callable_result_type_with_locals(
                            &args[1],
                            1,
                            locals,
                            active_rule_scope,
                        );
                    }
                    if (matches!(name.as_str(), "distinct" | "reverse" | "sort") && args.len() == 1)
                        || (matches!(name.as_str(), "filter" | "sort_by") && args.len() == 2)
                    {
                        return self.infer_expr_type_name_with_locals_in_scope(
                            &args[0],
                            locals,
                            active_rule_scope,
                        );
                    }
                    if matches!(name.as_str(), "head" | "last") && args.len() == 1 {
                        let collection_type = self.infer_expr_type_name_with_locals_in_scope(
                            &args[0],
                            locals,
                            active_rule_scope,
                        )?;
                        return Self::applied_type_argument(&collection_type, "List", 0);
                    }
                    if name == "find" && args.len() == 2 {
                        let collection_type = self.infer_expr_type_name_with_locals_in_scope(
                            &args[0],
                            locals,
                            active_rule_scope,
                        )?;
                        let element_type =
                            Self::applied_type_argument(&collection_type, "List", 0)?;
                        return Some(format!("Option({element_type})"));
                    }
                    if name == "concat" && !args.is_empty() {
                        let mut result = self.infer_expr_type_name_with_locals_in_scope(
                            &args[0],
                            locals,
                            active_rule_scope,
                        )?;
                        for argument in &args[1..] {
                            let next = self.infer_expr_type_name_with_locals_in_scope(
                                argument,
                                locals,
                                active_rule_scope,
                            )?;
                            result = Self::merge_inferred_type_names(&result, &next)?;
                        }
                        return Some(result);
                    }
                    if matches!(name.as_str(), "all" | "any") && args.len() == 2 {
                        return Some("Bool".to_string());
                    }
                    if name == "length" && args.len() == 1 {
                        return Some("Int".to_string());
                    }
                    if name == "sum_list" && args.len() == 1 {
                        return Some("Int".to_string());
                    }
                    if let Some(local_type) = locals.get(name) {
                        if let Ok(Ty::Arrow(_, return_type)) = parse_type_annotation(local_type) {
                            return Self::type_name_from_ty(&return_type);
                        }
                    }
                    if name == "range" && args.len() == 2 {
                        return Some("List(Int)".to_string());
                    }
                    if let Some(parent) = self.constructor_parent_for_args(name, args) {
                        return Some(parent);
                    }
                    if let Some((parent, _)) = self.constructors.get(name) {
                        return Some(parent.clone());
                    }
                    if let Some(scope) = active_rule_scope {
                        let key = RuleDispatchKey {
                            scope: Some(scope.to_string()),
                            name: name.clone(),
                            arity: args.len(),
                        };
                        if self.rule_dispatch_keys.contains(&key) {
                            return self.rule_dispatch_return_types.get(&key).cloned();
                        }
                        if let Some(return_type) =
                            self.scoped_member_return_type(scope, name, args.len())
                        {
                            return Some(return_type);
                        }
                    }
                    if let Some(ret) = self
                        .explore_function_return_types_by_arity
                        .get(&(name.clone(), args.len()))
                    {
                        return Some(ret.to_string());
                    }
                    if let Some(ret) = self
                        .explore_rule_return_types_by_arity
                        .get(&(name.clone(), args.len()))
                    {
                        return Some(ret.to_string());
                    }
                    let dispatch_key = RuleDispatchKey {
                        scope: None,
                        name: name.clone(),
                        arity: args.len(),
                    };
                    if self.rule_dispatch_keys.contains(&dispatch_key) {
                        return self.rule_dispatch_return_types.get(&dispatch_key).cloned();
                    }
                    if (self.inferring_exact_explore_rule_returns || self.checking_explore_query)
                        && self.rule_arities.contains(&(name.clone(), args.len()))
                    {
                        return None;
                    }
                    if let Some(ret) = self.rule_return_types.get(name) {
                        return Some(ret.clone());
                    }
                }

                if let ExprKind::Field(base, member) = &func.as_ref().kind {
                    let base_type = self.infer_expr_type_name_with_locals_in_scope(
                        base,
                        locals,
                        active_rule_scope,
                    )?;
                    let dispatch_key = RuleDispatchKey {
                        scope: Some(base_type.clone()),
                        name: member.clone(),
                        arity: args.len(),
                    };
                    if self.rule_dispatch_keys.contains(&dispatch_key) {
                        return self.rule_dispatch_return_types.get(&dispatch_key).cloned();
                    }
                    if let Some(ret) =
                        self.scoped_member_return_type(&base_type, member, args.len())
                    {
                        return Some(ret);
                    }
                    return self.field_type_name(&base_type, member);
                }

                None
            }
            ExprKind::Field(base, field) => {
                let base_type = self.infer_expr_type_name_with_locals_in_scope(
                    base,
                    locals,
                    active_rule_scope,
                )?;
                self.field_type_name(&base_type, field)
            }
            ExprKind::BinOp(operator, left, right) => match operator.as_str() {
                "<" | ">" | "<=" | ">=" | "==" | "!=" | "&&" | "||" => Some("Bool".to_string()),
                _ => {
                    let left_type = self.infer_expr_type_name_with_locals_in_scope(
                        left,
                        locals,
                        active_rule_scope,
                    )?;
                    let right_type = self.infer_expr_type_name_with_locals_in_scope(
                        right,
                        locals,
                        active_rule_scope,
                    )?;
                    Self::merge_inferred_type_names(&left_type, &right_type)
                }
            },
            ExprKind::UnOp(operator, inner) => {
                if operator == "!" {
                    Some("Bool".to_string())
                } else {
                    self.infer_expr_type_name_with_locals_in_scope(inner, locals, active_rule_scope)
                }
            }
            ExprKind::Index(collection, _) => {
                let collection_type = self.infer_expr_type_name_with_locals_in_scope(
                    collection,
                    locals,
                    active_rule_scope,
                )?;
                Self::applied_type_argument(&collection_type, "List", 0)
            }
            ExprKind::If(_, then_expr, else_expr) => {
                let then_ty = self.infer_expr_type_name_with_locals_in_scope(
                    then_expr,
                    locals,
                    active_rule_scope,
                );
                let else_ty = self.infer_expr_type_name_with_locals_in_scope(
                    else_expr,
                    locals,
                    active_rule_scope,
                );
                match (then_ty, else_ty) {
                    (Some(then_ty), Some(else_ty)) => {
                        Self::merge_inferred_type_names(&then_ty, &else_ty)
                    }
                    (Some(then_ty), None) if Self::is_polymorphic_empty_list_expr(else_expr) => {
                        Some(then_ty)
                    }
                    (None, Some(else_ty)) if Self::is_polymorphic_empty_list_expr(then_expr) => {
                        Some(else_ty)
                    }
                    _ => None,
                }
            }
            ExprKind::Match(scrutinee, arms) => {
                let subject_type = self.infer_expr_type_name_with_locals_in_scope(
                    scrutinee,
                    locals,
                    active_rule_scope,
                );
                let mut result_type: Option<String> = None;
                for arm in arms {
                    let mut arm_locals = locals.clone();
                    arm_locals
                        .extend(self.pattern_type_bindings(&arm.pat, subject_type.as_deref()));
                    let arm_type = match self.infer_expr_type_name_with_locals_in_scope(
                        &arm.body,
                        &arm_locals,
                        active_rule_scope,
                    ) {
                        Some(arm_type) => arm_type,
                        None if Self::is_polymorphic_empty_list_expr(&arm.body) => {
                            // `[]` is polymorphic. A nonempty sibling arm fixes
                            // its exact list type; an all-empty match remains
                            // intentionally uninferred.
                            continue;
                        }
                        None => return None,
                    };
                    let merged = match result_type {
                        Some(known) => Self::merge_inferred_type_names(&known, &arm_type),
                        None => Some(arm_type),
                    }?;
                    result_type = Some(merged);
                }
                result_type
            }
            ExprKind::Block(stmts) => {
                let mut block_locals = locals.clone();
                let mut result = None;
                for stmt in stmts {
                    match stmt {
                        Stmt::Bind(Pat::Var(name), ty, expr) => {
                            let inferred =
                                ty.as_ref().and_then(Self::type_name_from_ty).or_else(|| {
                                    self.infer_expr_type_name_with_locals_in_scope(
                                        expr,
                                        &block_locals,
                                        active_rule_scope,
                                    )
                                });
                            if let Some(inferred) = &inferred {
                                block_locals.insert(name.clone(), inferred.clone());
                            }
                            result = inferred;
                        }
                        Stmt::Expr(expr) => {
                            result = self.infer_expr_type_name_with_locals_in_scope(
                                expr,
                                &block_locals,
                                active_rule_scope,
                            );
                        }
                        _ => result = None,
                    }
                }
                result
            }
            ExprKind::Conjunction(_) | ExprKind::Disjunction(_) => Some("Bool".to_string()),
            ExprKind::Try(inner) => {
                self.infer_expr_type_name_with_locals_in_scope(inner, locals, active_rule_scope)
            }
            ExprKind::Pipe(_, transform) => {
                self.infer_expr_type_name_with_locals_in_scope(transform, locals, active_rule_scope)
            }
            _ => None,
        }
    }

    /// Find a conflict-free type seed inside a branching expression. This is
    /// used only to start the exact rule-return fixed point: the completed
    /// pass below re-infers every branch and rejects unresolved or conflicting
    /// families before any Explore artifact is produced.
    fn provisional_expr_type_name_with_locals(
        &self,
        expr: &Expr,
        locals: &BTreeMap<String, String>,
    ) -> Option<String> {
        if let Some(inferred) = self.infer_expr_type_name_with_locals(expr, locals) {
            return Some(inferred);
        }

        let merge_candidates = |left: Option<String>, right: Option<String>| match (left, right) {
            (Some(left), Some(right)) => Self::merge_inferred_type_names(&left, &right),
            (Some(known), None) | (None, Some(known)) => Some(known),
            (None, None) => None,
        };

        match &expr.kind {
            ExprKind::If(_, then_expr, else_expr) => merge_candidates(
                self.provisional_expr_type_name_with_locals(then_expr, locals),
                self.provisional_expr_type_name_with_locals(else_expr, locals),
            ),
            ExprKind::App(function, arguments) if matches!(&function.kind, ExprKind::Var(name) if name == "concat") =>
            {
                let mut candidate: Option<String> = None;
                for argument in arguments {
                    let Some(argument_candidate) =
                        self.provisional_expr_type_name_with_locals(argument, locals)
                    else {
                        continue;
                    };
                    candidate = match candidate {
                        Some(known) => Some(Self::merge_inferred_type_names(
                            &known,
                            &argument_candidate,
                        )?),
                        None => Some(argument_candidate),
                    };
                }
                candidate
            }
            ExprKind::Match(scrutinee, arms) => {
                let subject_type = self.infer_expr_type_name_with_locals(scrutinee, locals);
                let mut candidate: Option<String> = None;
                for arm in arms {
                    let mut arm_locals = locals.clone();
                    arm_locals
                        .extend(self.pattern_type_bindings(&arm.pat, subject_type.as_deref()));
                    let Some(arm_candidate) =
                        self.provisional_expr_type_name_with_locals(&arm.body, &arm_locals)
                    else {
                        continue;
                    };
                    candidate = match candidate {
                        Some(known) => {
                            Some(Self::merge_inferred_type_names(&known, &arm_candidate)?)
                        }
                        None => Some(arm_candidate),
                    };
                }
                candidate
            }
            ExprKind::Block(stmts) => {
                let mut block_locals = locals.clone();
                let mut result = None;
                for stmt in stmts {
                    match stmt {
                        Stmt::Bind(Pat::Var(name), annotation, value) => {
                            result = annotation
                                .as_ref()
                                .and_then(Self::type_name_from_ty)
                                .or_else(|| {
                                    self.provisional_expr_type_name_with_locals(
                                        value,
                                        &block_locals,
                                    )
                                });
                            if let Some(inferred) = &result {
                                block_locals.insert(name.clone(), inferred.clone());
                            }
                        }
                        Stmt::Expr(value) => {
                            result =
                                self.provisional_expr_type_name_with_locals(value, &block_locals);
                        }
                        _ => result = None,
                    }
                }
                result
            }
            _ => None,
        }
    }

    fn infer_rule_result_with_expected_empty_list(
        &self,
        expression: &Expr,
        locals: &BTreeMap<String, String>,
        expected: Option<&str>,
    ) -> Option<String> {
        self.infer_expr_type_name_with_locals(expression, locals)
            .or_else(|| {
                expected
                    .filter(|_| Self::is_polymorphic_empty_list_expr(expression))
                    .map(str::to_string)
            })
    }

    fn infer_rule_scope_member_return_types(
        &mut self,
        scope_name: &str,
        params: &[Param],
        body: &[Stmt],
    ) {
        let previous_scope = self
            .active_rule_scope_inference
            .replace(scope_name.to_string());
        self.rule_scope_member_return_types
            .entry(scope_name.to_string())
            .or_default();

        let mut scope_locals = BTreeMap::new();
        for param in params {
            if let Some(ty) = &param.ty {
                if let Some(type_name) = Self::type_name_from_ty(ty) {
                    scope_locals.insert(param.name.clone(), type_name);
                }
            }
        }

        for _ in 0..body.len().max(1) {
            let mut changed = false;
            for stmt in body {
                match stmt {
                    Stmt::Rule(rule @ Rule::Clause { .. })
                    | Stmt::Rule(rule @ Rule::Default { .. })
                    | Stmt::Rule(rule @ Rule::Exception { .. }) => {
                        let Some((member, _)) = Self::rule_name_arity(rule) else {
                            continue;
                        };
                        let (head, value) = match rule {
                            Rule::Clause {
                                head,
                                body: Some(body),
                            } => (head, body),
                            Rule::Default { head, value, .. }
                            | Rule::Exception { head, value, .. } => (head, value),
                            _ => continue,
                        };
                        let mut locals = scope_locals.clone();
                        locals.extend(self.rule_head_local_types(head));
                        let Some(ret) = self.infer_expr_type_name_with_locals(value, &locals)
                        else {
                            continue;
                        };
                        let members = self
                            .rule_scope_member_return_types
                            .entry(scope_name.to_string())
                            .or_default();
                        if members.get(&member) != Some(&ret) {
                            members.insert(member, ret);
                            changed = true;
                        }
                    }
                    Stmt::Defn(Defn::Fn {
                        name,
                        params: method_params,
                        ret_ty,
                        body: method_body,
                        ..
                    }) => {
                        let ret = ret_ty
                            .as_ref()
                            .and_then(Self::type_name_from_ty)
                            .or_else(|| {
                                let mut locals = scope_locals.clone();
                                locals.insert("self".to_string(), scope_name.to_string());
                                for param in method_params {
                                    if param.name == "self" {
                                        continue;
                                    }
                                    if let Some(ty) = &param.ty {
                                        if let Some(type_name) = Self::type_name_from_ty(ty) {
                                            locals.insert(param.name.clone(), type_name);
                                        }
                                    }
                                }
                                self.infer_expr_type_name_with_locals(method_body, &locals)
                            });
                        let Some(ret) = ret else {
                            continue;
                        };
                        let members = self
                            .rule_scope_member_return_types
                            .entry(scope_name.to_string())
                            .or_default();
                        if members.get(name) != Some(&ret) {
                            members.insert(name.clone(), ret);
                            changed = true;
                        }
                    }
                    _ => {}
                }
            }
            if !changed {
                break;
            }
        }
        self.active_rule_scope_inference = previous_scope;
    }

    fn infer_rule_return_types(&mut self, stmts: &[Stmt]) {
        let mut groups: BTreeMap<String, Vec<&Rule>> = BTreeMap::new();
        for stmt in stmts {
            if let Stmt::Rule(rule @ Rule::Clause { .. })
            | Stmt::Rule(rule @ Rule::Default { .. })
            | Stmt::Rule(rule @ Rule::Exception { .. }) = stmt
            {
                if let Some((name, _)) = Self::rule_name_arity(rule) {
                    groups.entry(name).or_default().push(rule);
                }
            }
        }

        for _ in 0..groups.len().max(1) {
            let mut changed = false;
            for (name, rules) in &groups {
                for rule in rules {
                    let (head, value) = match rule {
                        Rule::Clause {
                            head,
                            body: Some(body),
                        } => (head, body),
                        Rule::Default { head, value, .. } | Rule::Exception { head, value, .. } => {
                            (head, value)
                        }
                        _ => continue,
                    };
                    let locals = self.rule_head_local_types(head);
                    let Some(ret) = self.infer_expr_type_name_with_locals(value, &locals) else {
                        continue;
                    };
                    if self.rule_return_types.get(name) != Some(&ret) {
                        self.rule_return_types.insert(name.clone(), ret);
                        changed = true;
                    }
                    break;
                }
            }
            if !changed {
                break;
            }
        }
    }

    fn boolean_miss_safe_primitive(type_name: &str) -> Option<String> {
        let canonical = Self::canonical_explore_type_name(type_name);
        matches!(
            canonical.as_str(),
            "Bool" | "Int" | "Float" | "String" | "Char" | "()"
        )
        .then_some(canonical)
    }

    /// Infer only expression shapes whose runtime result cannot be changed by
    /// Futuruna's current caller-environment lookup. This is intentionally much
    /// narrower than the static return-sort inference used by Explore and SMT.
    fn boolean_miss_safe_expr_type(
        &self,
        expression: &Expr,
        locals: &BTreeMap<String, String>,
        active_scope: Option<&str>,
        safe_keys: &BTreeSet<RuleDispatchKey>,
    ) -> Option<String> {
        match &expression.kind {
            ExprKind::Lit(literal) => {
                Self::boolean_miss_safe_primitive(Self::obvious_literal_ty(literal))
            }
            ExprKind::Unit => Some("()".to_string()),
            ExprKind::Var(name) => locals
                .get(name)
                .and_then(|type_name| Self::boolean_miss_safe_primitive(type_name)),
            ExprKind::App(function, arguments) => {
                let ExprKind::Var(name) = &function.kind else {
                    return None;
                };
                let scope = active_scope?;
                if name == NAMED_ARG_MARKER
                    || name == PATHOF_MARKER
                    || name == REFOF_MARKER
                    || (matches!(name.as_str(), "findall" | "search") && arguments.len() == 2)
                    || self
                        .effect_ops
                        .values()
                        .any(|operations| operations.contains_key(name))
                {
                    return None;
                }
                let key = RuleDispatchKey {
                    scope: Some(scope.to_string()),
                    name: name.clone(),
                    arity: arguments.len(),
                };
                if !safe_keys.contains(&key) {
                    return None;
                }
                for argument in arguments {
                    self.boolean_miss_safe_expr_type(argument, locals, active_scope, safe_keys)?;
                }
                Some("Bool".to_string())
            }
            ExprKind::BinOp(operator, left, right) => {
                let left_type =
                    self.boolean_miss_safe_expr_type(left, locals, active_scope, safe_keys)?;
                let right_type =
                    self.boolean_miss_safe_expr_type(right, locals, active_scope, safe_keys)?;
                let left_type = Self::canonical_explore_type_name(&left_type);
                let right_type = Self::canonical_explore_type_name(&right_type);
                let left_numeric = matches!(left_type.as_str(), "Int" | "Float");
                let right_numeric = matches!(right_type.as_str(), "Int" | "Float");
                match operator.as_str() {
                    "&&" | "||" if left_type == "Bool" && right_type == "Bool" => {
                        Some("Bool".to_string())
                    }
                    "<" | ">" | "<=" | ">=" if left_numeric && right_numeric => {
                        Some("Bool".to_string())
                    }
                    "==" if left_type == right_type
                        && matches!(left_type.as_str(), "Bool" | "Int" | "Float" | "String") =>
                    {
                        Some("Bool".to_string())
                    }
                    "!=" => Some("Bool".to_string()),
                    "+" if left_type == "String" || right_type == "String" => {
                        Some("String".to_string())
                    }
                    "+" | "-" | "*" | "/" if left_numeric && right_numeric => {
                        if left_type == "Float" || right_type == "Float" {
                            Some("Float".to_string())
                        } else {
                            Some("Int".to_string())
                        }
                    }
                    "%" if left_type == "Int" && right_type == "Int" => Some("Int".to_string()),
                    _ => None,
                }
            }
            ExprKind::UnOp(operator, inner) => {
                let inner_type =
                    self.boolean_miss_safe_expr_type(inner, locals, active_scope, safe_keys)?;
                let canonical = Self::canonical_explore_type_name(&inner_type);
                match operator.as_str() {
                    "!" if canonical == "Bool" => Some("Bool".to_string()),
                    "-" if matches!(canonical.as_str(), "Int" | "Float") => Some(canonical),
                    _ => None,
                }
            }
            ExprKind::If(condition, then_expression, else_expression) => {
                let condition_type =
                    self.boolean_miss_safe_expr_type(condition, locals, active_scope, safe_keys)?;
                if Self::canonical_explore_type_name(&condition_type) != "Bool" {
                    return None;
                }
                let then_type = self.boolean_miss_safe_expr_type(
                    then_expression,
                    locals,
                    active_scope,
                    safe_keys,
                )?;
                let else_type = self.boolean_miss_safe_expr_type(
                    else_expression,
                    locals,
                    active_scope,
                    safe_keys,
                )?;
                (Self::canonical_explore_type_name(&then_type)
                    == Self::canonical_explore_type_name(&else_type))
                .then_some(then_type)
            }
            ExprKind::Block(statements) => {
                let mut block_locals = locals.clone();
                let mut result = None;
                for statement in statements {
                    match statement {
                        Stmt::Bind(Pat::Var(name), annotation, value) => {
                            let actual = self.boolean_miss_safe_expr_type(
                                value,
                                &block_locals,
                                active_scope,
                                safe_keys,
                            )?;
                            if let Some(annotation) = annotation {
                                if matches!(annotation, Ty::Hole)
                                    || Self::canonical_explore_ty_name(annotation)
                                        != Self::canonical_explore_type_name(&actual)
                                {
                                    return None;
                                }
                            }
                            block_locals.insert(name.clone(), actual.clone());
                            result = Some(actual);
                        }
                        Stmt::Expr(value) => {
                            result = Some(self.boolean_miss_safe_expr_type(
                                value,
                                &block_locals,
                                active_scope,
                                safe_keys,
                            )?);
                        }
                        _ => return None,
                    }
                }
                result
            }
            ExprKind::Conjunction(items) | ExprKind::Disjunction(items) => {
                for item in items {
                    let item_type =
                        self.boolean_miss_safe_expr_type(item, locals, active_scope, safe_keys)?;
                    if Self::canonical_explore_type_name(&item_type) != "Bool" {
                        return None;
                    }
                }
                Some("Bool".to_string())
            }
            ExprKind::List(_)
            | ExprKind::Tuple(_)
            | ExprKind::Lambda(_, _)
            | ExprKind::Match(_, _)
            | ExprKind::Field(_, _)
            | ExprKind::Index(_, _)
            | ExprKind::Effect(_, _)
            | ExprKind::Handle { .. }
            | ExprKind::Try(_)
            | ExprKind::Pipe(_, _) => None,
        }
    }

    fn infer_rule_dispatch_return_types(&mut self, stmts: &[Stmt]) {
        type ReturnGroup<'a> = (BTreeMap<String, String>, Vec<&'a Rule>);

        let dispatch_statements: Arc<[Stmt]> =
            if self.plain_import_rule_dispatch_statements.is_empty() {
                stmts.to_vec().into()
            } else {
                Arc::clone(&self.plain_import_rule_dispatch_statements)
            };
        let mut groups: BTreeMap<RuleDispatchKey, ReturnGroup<'_>> = BTreeMap::new();
        for stmt in dispatch_statements.iter() {
            match stmt {
                Stmt::Rule(rule) => {
                    let Some((name, arity)) = Self::rule_name_arity(rule) else {
                        continue;
                    };
                    groups
                        .entry(RuleDispatchKey {
                            scope: None,
                            name,
                            arity,
                        })
                        .or_default()
                        .1
                        .push(rule);
                }
                Stmt::TypeDecl(TypeDecl::RuleScope { name, params, body }) => {
                    // A later declaration of the same RuleScope replaces its
                    // scoped dispatch surface, matching RuleDispatchRegistry.
                    groups.retain(|key, _| key.scope.as_deref() != Some(name));
                    let captures = params
                        .iter()
                        .filter_map(|param| {
                            param
                                .ty
                                .as_ref()
                                .and_then(Self::type_name_from_ty)
                                .map(|ty| (param.name.clone(), ty))
                        })
                        .collect::<BTreeMap<_, _>>();
                    for scoped_stmt in body {
                        let Stmt::Rule(rule) = scoped_stmt else {
                            continue;
                        };
                        let Some((member, arity)) = Self::rule_name_arity(rule) else {
                            continue;
                        };
                        let group = groups
                            .entry(RuleDispatchKey {
                                scope: Some(name.clone()),
                                name: member,
                                arity,
                            })
                            .or_default();
                        group.0 = captures.clone();
                        group.1.push(rule);
                    }
                }
                _ => {}
            }
        }

        self.rule_dispatch_return_types.clear();
        self.rule_dispatch_return_issues.clear();
        self.rule_dispatch_boolean_miss_safe_keys.clear();
        self.rule_dispatch_keys = groups.keys().cloned().collect();

        let infer_group = |checker: &TypeChecker,
                           captures: &BTreeMap<String, String>,
                           rules: &[&Rule],
                           expected: Option<&str>| {
            rules
                .iter()
                .map(|rule| match rule {
                    Rule::Clause { head, body } => match body {
                        Some(body) => {
                            let mut locals = captures.clone();
                            locals.extend(checker.rule_head_local_types(head));
                            checker
                                .infer_rule_result_with_expected_empty_list(body, &locals, expected)
                        }
                        None => Some("Bool".to_string()),
                    },
                    Rule::Default { head, value, .. } | Rule::Exception { head, value, .. } => {
                        let mut locals = captures.clone();
                        locals.extend(checker.rule_head_local_types(head));
                        checker.infer_rule_result_with_expected_empty_list(value, &locals, expected)
                    }
                    Rule::ReactiveScope { .. } => None,
                })
                .collect::<Vec<_>>()
        };

        let infer_group_provisionally =
            |checker: &TypeChecker, captures: &BTreeMap<String, String>, rules: &[&Rule]| {
                rules
                    .iter()
                    .map(|rule| match rule {
                        Rule::Clause { head, body } => match body {
                            Some(body) => {
                                let mut locals = captures.clone();
                                locals.extend(checker.rule_head_local_types(head));
                                checker.provisional_expr_type_name_with_locals(body, &locals)
                            }
                            None => Some("Bool".to_string()),
                        },
                        Rule::Default { head, value, .. } | Rule::Exception { head, value, .. } => {
                            let mut locals = captures.clone();
                            locals.extend(checker.rule_head_local_types(head));
                            checker.provisional_expr_type_name_with_locals(value, &locals)
                        }
                        Rule::ReactiveScope { .. } => None,
                    })
                    .collect::<Vec<_>>()
            };

        // A known base candidate can seed recursive references. Every result is
        // revalidated below after the fixed point, so a provisional type can
        // never hide a later conflict or unresolved dependency.
        let previous_active_scope = self.active_rule_scope_inference.clone();
        for _ in 0..groups.len().saturating_add(1) {
            let mut changed = false;
            for (key, (captures, rules)) in &groups {
                self.active_rule_scope_inference = key.scope.clone();
                let inferred = infer_group_provisionally(self, captures, rules);
                let known = inferred.iter().flatten().collect::<Vec<_>>();
                let Ok(Some(merged)) = Self::merge_inferred_type_candidates(known) else {
                    continue;
                };
                if self.rule_dispatch_return_types.get(key) != Some(&merged) {
                    self.rule_dispatch_return_types.insert(key.clone(), merged);
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }

        // Remove conflicts and unresolved families, then repeat so their
        // callers also fail closed instead of retaining a provisional sort.
        loop {
            let mut changed = false;
            for (key, (captures, rules)) in &groups {
                if self.rule_dispatch_return_issues.contains_key(key) {
                    continue;
                }
                self.active_rule_scope_inference = key.scope.clone();
                let expected = self.rule_dispatch_return_types.get(key).cloned();
                let inferred = infer_group(self, captures, rules, expected.as_deref());
                let issue = if inferred.iter().any(Option::is_none) {
                    Some(format!(
                        "cannot infer every return clause of rule `{}` with arity {}",
                        key.scope
                            .as_ref()
                            .map(|scope| format!("{}.{}", scope, key.name))
                            .unwrap_or_else(|| key.name.clone()),
                        key.arity
                    ))
                } else {
                    let inferred = inferred.into_iter().flatten().collect::<Vec<_>>();
                    Self::merge_inferred_type_candidates(&inferred)
                        .err()
                        .map(|(left, right)| {
                            format!(
                                "rule `{}` with arity {} has conflicting return types `{}` and `{}`",
                                key.scope
                                    .as_ref()
                                    .map(|scope| format!("{}.{}", scope, key.name))
                                    .unwrap_or_else(|| key.name.clone()),
                                key.arity,
                                left,
                                right
                            )
                        })
                };
                if let Some(issue) = issue {
                    self.rule_dispatch_return_types.remove(key);
                    self.rule_dispatch_return_issues.insert(key.clone(), issue);
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }
        self.active_rule_scope_inference = previous_active_scope;
        // Static return sorts are useful to Explore/SMT even when runtime
        // lookup is context-dependent. The Interpreter's Bool miss override
        // receives a strictly narrower proof: every possible hit expression
        // must be closed over runtime-checked primitive head values. A scoped
        // direct sibling is admitted only after that exact sibling has already
        // been proven safe, producing a monotone fixed point.
        if !self.rule_dispatch_has_opaque_runtime_graph {
            loop {
                let mut newly_safe = Vec::new();
                for (key, (_, rules)) in &groups {
                    if self.rule_dispatch_boolean_miss_safe_keys.contains(key)
                        || self.rule_dispatch_return_issues.contains_key(key)
                        || self
                            .rule_dispatch_return_types
                            .get(key)
                            .is_none_or(|return_type| {
                                Self::canonical_explore_type_name(return_type) != "Bool"
                            })
                    {
                        continue;
                    }
                    let safe = rules.iter().all(|rule| match rule {
                        Rule::Clause {
                            head,
                            body: Some(body),
                        } => {
                            let locals = rule_head_boolean_miss_safe_locals(head);
                            self.boolean_miss_safe_expr_type(
                                body,
                                &locals,
                                key.scope.as_deref(),
                                &self.rule_dispatch_boolean_miss_safe_keys,
                            )
                            .is_some_and(|return_type| {
                                Self::canonical_explore_type_name(&return_type) == "Bool"
                            })
                        }
                        Rule::Default {
                            head,
                            value,
                            condition,
                        }
                        | Rule::Exception {
                            head,
                            value,
                            condition,
                            ..
                        } => {
                            let locals = rule_head_boolean_miss_safe_locals(head);
                            let value_is_bool = self
                                .boolean_miss_safe_expr_type(
                                    value,
                                    &locals,
                                    key.scope.as_deref(),
                                    &self.rule_dispatch_boolean_miss_safe_keys,
                                )
                                .is_some_and(|return_type| {
                                    Self::canonical_explore_type_name(&return_type) == "Bool"
                                });
                            let condition_is_bool = condition.as_ref().is_none_or(|condition| {
                                self.boolean_miss_safe_expr_type(
                                    condition,
                                    &locals,
                                    key.scope.as_deref(),
                                    &self.rule_dispatch_boolean_miss_safe_keys,
                                )
                                .is_some_and(|condition_type| {
                                    Self::canonical_explore_type_name(&condition_type) == "Bool"
                                })
                            });
                            value_is_bool && condition_is_bool
                        }
                        Rule::Clause { body: None, .. } => true,
                        Rule::ReactiveScope { .. } => false,
                    });
                    if safe {
                        newly_safe.push(key.clone());
                    }
                }
                if newly_safe.is_empty() {
                    break;
                }
                self.rule_dispatch_boolean_miss_safe_keys.extend(newly_safe);
            }
        }
    }

    fn establish_explore_function_return_types(&mut self) {
        let definitions = self.explore_function_definitions_by_arity.clone();
        self.explore_function_return_types_by_arity.clear();
        self.explore_function_return_issues.clear();

        // Establish the declared signature environment first so forward and
        // mutually recursive helpers can be checked against explicit results.
        for (key, entries) in &definitions {
            let declarations = entries
                .iter()
                .map(|(_, ret_ty, _)| ret_ty.clone())
                .collect::<Vec<_>>();
            let issue = if declarations.iter().any(Option::is_none) {
                Some(format!(
                    "exploration helper `{}({} arguments)` needs an explicit result type",
                    key.0, key.1
                ))
            } else {
                let declarations = declarations.into_iter().flatten().collect::<Vec<_>>();
                declarations.first().and_then(|first| {
                        declarations
                            .iter()
                            .find(|candidate| !Self::explore_tys_equivalent(candidate, first))
                        .map(|candidate| {
                            format!(
                                "exploration helper `{}({} arguments)` declares conflicting result types `{}` and `{}`",
                                key.0, key.1, first, candidate
                            )
                        })
                })
            };
            if let Some(issue) = issue {
                self.explore_function_return_issues
                    .insert(key.clone(), issue);
            } else if let Some(ret_ty) = entries.first().and_then(|(_, ret_ty, _)| ret_ty.clone()) {
                self.explore_function_return_types_by_arity
                    .insert(key.clone(), ret_ty);
            }
        }
    }

    fn validate_explore_function_return_types(&mut self) {
        let definitions = self.explore_function_definitions_by_arity.clone();
        self.establish_explore_function_return_types();

        // Validate each body against its declared result. This is independent
        // of rustc so the backend-neutral exploration artifact is sound on its
        // own.
        for (key, entries) in &definitions {
            if self.explore_function_return_issues.contains_key(key) {
                continue;
            }
            let expected = self
                .explore_function_return_types_by_arity
                .get(key)
                .cloned()
                .expect("validated function signature");
            let issue = entries.iter().find_map(|(params, _, body)| {
                let mut locals = BTreeMap::new();
                for param in params {
                    let Some(ty) = param.ty.as_ref() else {
                        return Some(format!(
                            "exploration helper `{}({} arguments)` needs a type annotation on parameter `{}`",
                            key.0, key.1, param.name
                        ));
                    };
                    locals.insert(
                        param.name.clone(),
                        Self::canonical_explore_ty_name(ty),
                    );
                }
                match self.infer_rule_result_with_expected_empty_list(
                    body,
                    &locals,
                    Some(&Self::canonical_explore_ty_name(&expected)),
                ) {
                    Some(actual) if Self::explore_type_name_matches_ty(&actual, &expected) => None,
                    Some(actual) => Some(format!(
                        "exploration helper `{}({} arguments)` declares result `{}` but its body has type `{}`",
                        key.0, key.1, expected, actual
                    )),
                    None => Some(format!(
                        "cannot validate the body result of exploration helper `{}({} arguments)` against declared type `{}`",
                        key.0, key.1, expected
                    )),
                }
            });
            if let Some(issue) = issue {
                self.explore_function_return_types_by_arity.remove(key);
                self.explore_function_return_issues
                    .insert(key.clone(), issue);
            }
        }

        // Propagate invalid exact helper results through wrapper functions.
        loop {
            let mut changed = false;
            for (key, entries) in &definitions {
                if self.explore_function_return_issues.contains_key(key) {
                    continue;
                }
                let issue = entries.iter().find_map(|(params, _, body)| {
                    let locals = params
                        .iter()
                        .filter_map(|param| {
                            param
                                .ty
                                .as_ref()
                                .map(|ty| (param.name.clone(), Self::canonical_explore_ty_name(ty)))
                        })
                        .collect::<BTreeMap<_, _>>();
                    self.explore_operator_issues_with_locals(body, &locals)
                        .into_iter()
                        .next()
                });
                if let Some(issue) = issue {
                    self.explore_function_return_types_by_arity.remove(key);
                    self.explore_function_return_issues
                        .insert(key.clone(), issue);
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }
    }

    fn infer_explore_rule_return_types(&mut self, _stmts: &[Stmt]) {
        let groups = self.explore_rules_by_arity.clone();
        self.explore_rule_return_types_by_arity.clear();
        self.explore_rule_return_issues.clear();

        self.inferring_exact_explore_rule_returns = true;
        for _ in 0..groups.len().saturating_add(1) {
            let mut changed = false;
            for (key, rules) in &groups {
                let inferred = rules
                    .iter()
                    .map(|rule| match rule {
                        Rule::Clause { head, body } => match body {
                            Some(body) => {
                                let locals = self.rule_head_local_types(head);
                                self.provisional_expr_type_name_with_locals(body, &locals)
                            }
                            None => Some("Bool".to_string()),
                        },
                        Rule::Default { head, value, .. } | Rule::Exception { head, value, .. } => {
                            let locals = self.rule_head_local_types(head);
                            self.provisional_expr_type_name_with_locals(value, &locals)
                        }
                        Rule::ReactiveScope { .. } => None,
                    })
                    .collect::<Vec<_>>();
                let known = inferred.iter().flatten().collect::<Vec<_>>();
                let Ok(Some(merged)) = Self::merge_inferred_type_candidates(known) else {
                    continue;
                };
                let ty =
                    parse_type_annotation(&merged).unwrap_or_else(|_| Ty::Name(merged.clone()));
                if self
                    .explore_rule_return_types_by_arity
                    .get(key)
                    .is_none_or(|previous| !Self::explore_tys_equivalent(previous, &ty))
                {
                    self.explore_rule_return_types_by_arity
                        .insert(key.clone(), ty);
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }
        self.inferring_exact_explore_rule_returns = false;

        // First record every rule family's intrinsic result conflict. Dependency
        // diagnostics must not depend on lexical ordering between two families.
        for ((name, arity), rules) in &groups {
            let key = (name.clone(), *arity);
            let expected = self
                .explore_rule_return_types_by_arity
                .get(&key)
                .map(Self::canonical_explore_ty_name);
            let inferred = rules
                .iter()
                .map(|rule| match rule {
                    Rule::Clause { head, body } => match body {
                        Some(body) => {
                            let locals = self.rule_head_local_types(head);
                            self.infer_rule_result_with_expected_empty_list(
                                body,
                                &locals,
                                expected.as_deref(),
                            )
                        }
                        None => Some("Bool".to_string()),
                    },
                    Rule::Default { head, value, .. } | Rule::Exception { head, value, .. } => {
                        let locals = self.rule_head_local_types(head);
                        self.infer_rule_result_with_expected_empty_list(
                            value,
                            &locals,
                            expected.as_deref(),
                        )
                    }
                    Rule::ReactiveScope { .. } => None,
                })
                .collect::<Vec<_>>();
            let issue = if inferred.iter().any(Option::is_none) {
                Some(format!(
                    "cannot infer every result clause of exploration rule `{}({} arguments)`",
                    name, arity
                ))
            } else {
                let inferred = inferred.into_iter().flatten().collect::<Vec<_>>();
                Self::merge_inferred_type_candidates(&inferred)
                    .err()
                    .map(|(left, right)| {
                        format!(
                            "exploration rule `{}({} arguments)` has conflicting result types `{}` and `{}`",
                            name, arity, left, right
                        )
                    })
            };
            if let Some(issue) = issue {
                self.explore_rule_return_types_by_arity.remove(&key);
                self.explore_rule_return_issues.insert(key, issue);
            }
        }

        // Then propagate exact-call and operator failures through the reachable
        // rule graph to a fixed point. A wrapper is invalid when any helper it
        // calls lacks one conflict-free exact result type.
        loop {
            let mut changed = false;
            for (key, rules) in &groups {
                if self.explore_rule_return_issues.contains_key(key) {
                    continue;
                }
                let issue = rules.iter().find_map(|rule| {
                    let (head, expressions) = match rule {
                        Rule::Clause { head, body } => (head, body.iter().collect::<Vec<_>>()),
                        Rule::Default {
                            head,
                            value,
                            condition,
                        }
                        | Rule::Exception {
                            head,
                            value,
                            condition,
                            ..
                        } => {
                            let mut expressions = vec![value];
                            expressions.extend(condition.iter());
                            (head, expressions)
                        }
                        Rule::ReactiveScope { .. } => return None,
                    };
                    let locals = self.rule_head_local_types(head);
                    expressions.into_iter().find_map(|expression| {
                        self.explore_operator_issues_with_locals(expression, &locals)
                            .into_iter()
                            .next()
                    })
                });
                if let Some(issue) = issue {
                    self.explore_rule_return_types_by_arity.remove(key);
                    self.explore_rule_return_issues.insert(key.clone(), issue);
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }
    }

    fn infer_top_level_binding_types(&mut self, stmts: &[Stmt]) {
        for stmt in stmts {
            if let Stmt::Bind(Pat::Var(name), ty, expr) = stmt {
                let inferred = ty
                    .as_ref()
                    .and_then(Self::type_name_from_ty)
                    .or_else(|| self.infer_expr_type_name(expr));
                if let Some(type_name) = inferred {
                    self.define_inferred_var_type_name(name, &type_name);
                }
            }
        }
    }

    fn infer_canonical_rule_dispatch_metadata(&mut self, stmts: &[Stmt]) {
        self.infer_rule_dispatch_return_types(stmts);
    }

    fn rule_scope_return_candidate(rule: &Rule) -> Option<(String, String)> {
        let (rule_name, _) = Self::rule_name_arity(rule)?;
        let value = match rule {
            Rule::Clause {
                body: Some(body), ..
            } => body,
            Rule::Default { value, .. } | Rule::Exception { value, .. } => value,
            _ => return None,
        };
        let scope_name = Self::direct_constructor_call_name(value)?;
        Some((rule_name, scope_name.to_string()))
    }

    fn rule_scope_method_arities(body: &[Stmt]) -> BTreeMap<String, usize> {
        let mut methods = BTreeMap::new();
        for stmt in body {
            if let Stmt::Rule(rule) = stmt {
                if let Some((method, arity)) = Self::rule_name_arity(rule) {
                    methods.entry(method).or_insert(arity);
                }
            }
        }
        methods
    }

    fn rule_scope_method_params(body: &[Stmt]) -> BTreeMap<String, Vec<String>> {
        let mut methods = BTreeMap::new();
        for stmt in body {
            if let Stmt::Rule(rule) = stmt {
                let head = match rule {
                    Rule::Clause { head, .. }
                    | Rule::Default { head, .. }
                    | Rule::Exception { head, .. } => head,
                    Rule::ReactiveScope { .. } => continue,
                };
                if let Some((method, _)) = Self::rule_name_arity(rule) {
                    if let Some(params) = Self::rule_head_param_names(head) {
                        methods.entry(method).or_insert(params);
                    }
                }
            }
        }
        methods
    }

    fn rule_scope_value_method_arities(body: &[Stmt]) -> BTreeMap<String, usize> {
        let mut methods = BTreeMap::new();
        for stmt in body {
            if let Stmt::Defn(Defn::Fn { name, params, .. }) = stmt {
                let arity = params
                    .iter()
                    .filter(|param| param.name.as_str() != "self")
                    .count();
                methods.insert(name.clone(), arity);
            }
        }
        methods
    }

    fn rule_scope_value_method_params(body: &[Stmt]) -> BTreeMap<String, Vec<String>> {
        let mut methods = BTreeMap::new();
        for stmt in body {
            if let Stmt::Defn(Defn::Fn { name, params, .. }) = stmt {
                methods.insert(
                    name.clone(),
                    params
                        .iter()
                        .filter(|param| param.name.as_str() != "self")
                        .map(|param| param.name.clone())
                        .collect(),
                );
            }
        }
        methods
    }

    fn expr_rule_scope_type(&self, expr: &Expr) -> Option<String> {
        match &expr.kind {
            ExprKind::Var(name) => self.rule_scope_var_type(name).map(str::to_string),
            ExprKind::App(func, _) => match &func.kind {
                ExprKind::Var(name) if self.type_has_scoped_members(name) => Some(name.clone()),
                ExprKind::Var(name) => self.resolved_rule_scope_return_type(name),
                _ => None,
            },
            _ => None,
        }
    }

    fn resolved_rule_scope_return_type(&self, rule_name: &str) -> Option<String> {
        let mut current = rule_name.to_string();
        let mut seen = BTreeSet::new();
        while seen.insert(current.clone()) {
            let candidate = self.rule_scope_returning_rules.get(&current)?;
            if self.type_has_scoped_members(candidate) {
                return Some(candidate.clone());
            }
            current = candidate.clone();
        }
        None
    }

    fn is_rule_scope_method_name(&self, method: &str) -> bool {
        self.rule_scope_methods
            .values()
            .any(|methods| methods.contains_key(method))
    }

    fn is_rule_scope_member_name(&self, method: &str) -> bool {
        self.is_rule_scope_method_name(method)
            || self
                .rule_scope_value_methods
                .values()
                .any(|methods| methods.contains_key(method))
    }

    fn check_rule_scope_decl(&mut self, name: &str, params: &[Param], body: &[Stmt]) {
        self.push_context(format!("in rulescope `{}`", name));

        let mut methods = BTreeMap::new();
        let mut value_methods = BTreeMap::new();
        for stmt in body {
            match stmt {
                Stmt::Rule(rule @ Rule::Clause { .. })
                | Stmt::Rule(rule @ Rule::Default { .. })
                | Stmt::Rule(rule @ Rule::Exception { .. }) => {
                    if let Some((method, arity)) = Self::rule_name_arity(rule) {
                        if value_methods.contains_key(&method) {
                            self.error(format!(
                                "RuleScope `{}` has both a `|` rule and a `>` method named `{}`; member names must be unambiguous",
                                name, method
                            ));
                        }
                        if let Some(previous) = methods.insert(method.clone(), arity) {
                            if previous != arity {
                                self.error(format!(
                                    "scoped rule `{}` in `{}` is declared with incompatible arities: {} and {}",
                                    method, name, previous, arity
                                ));
                            }
                        }
                    }
                }
                Stmt::Defn(Defn::Fn {
                    name: method_name,
                    params,
                    ..
                }) => {
                    let arity = params
                        .iter()
                        .filter(|param| param.name.as_str() != "self")
                        .count();
                    if methods.contains_key(method_name) {
                        self.error(format!(
                            "RuleScope `{}` has both a `|` rule and a `>` method named `{}`; member names must be unambiguous",
                            name, method_name
                        ));
                    }
                    if let Some(previous) = value_methods.insert(method_name.clone(), arity) {
                        if previous != arity {
                            self.error(format!(
                                "method `{}` in RuleScope `{}` is declared with incompatible arities: {} and {}",
                                method_name, name, previous, arity
                            ));
                        }
                    }
                }
                Stmt::Rule(Rule::ReactiveScope { .. }) => {
                    self.error(format!(
                        "`| scope` is a reactive lifecycle scope; use `# {}(...) {{ | rule(...) -> ... }}` for pure scoped rules",
                        name
                    ));
                }
                Stmt::Annot(_, _) => {}
                _ => {
                    self.error(format!(
                        "RuleScope `{}` currently only allows `|` rules and `>` methods in its body",
                        name
                    ));
                }
            }
        }

        let old_functions = self.functions.clone();
        let old_function_arities = self.function_arities.clone();
        let old_function_params = self.function_params.clone();
        let old_function_params_by_arity = self.function_params_by_arity.clone();
        let old_user_functions = self.user_functions.clone();
        for (method, arity) in &methods {
            self.functions.insert(method.clone(), *arity);
            self.function_arities
                .entry(method.clone())
                .or_default()
                .insert(*arity);
            if let Some(params) = self
                .rule_scope_method_params
                .get(name)
                .and_then(|by_method| by_method.get(method))
                .cloned()
            {
                self.function_params.insert(method.clone(), params.clone());
                self.function_params_by_arity
                    .insert((method.clone(), *arity), params);
            }
            self.user_functions.insert(method.clone());
        }
        for (method, arity) in &value_methods {
            self.functions.insert(method.clone(), *arity);
            self.function_arities
                .entry(method.clone())
                .or_default()
                .insert(*arity);
            if let Some(params) = self
                .rule_scope_value_method_params
                .get(name)
                .and_then(|by_method| by_method.get(method))
                .cloned()
            {
                self.function_params.insert(method.clone(), params.clone());
                self.function_params_by_arity
                    .insert((method.clone(), *arity), params);
            }
            self.user_functions.insert(method.clone());
        }

        for stmt in body {
            match stmt {
                Stmt::Rule(Rule::Clause { .. })
                | Stmt::Rule(Rule::Default { .. })
                | Stmt::Rule(Rule::Exception { .. }) => {
                    self.push_scope();
                    for param in params {
                        self.define_var(&param.name);
                        if let Some(ty) = &param.ty {
                            self.define_var_type(&param.name, ty);
                        }
                    }
                    self.check_stmt(stmt);
                    self.pop_scope();
                }
                Stmt::Defn(Defn::Fn {
                    name: method_name,
                    params: method_params,
                    body,
                    ..
                }) => {
                    self.push_context(format!("in method `{}`", method_name));
                    self.push_scope();
                    self.define_var("self");
                    self.define_rule_scope_var("self", name);
                    self.define_var_type("self", &Ty::Name(name.to_string()));
                    for param in params {
                        self.define_var(&param.name);
                        if let Some(ty) = &param.ty {
                            self.define_var_type(&param.name, ty);
                        }
                    }
                    for param in method_params {
                        if param.name == "self" {
                            continue;
                        }
                        self.define_var(&param.name);
                        if let Some(ty) = &param.ty {
                            self.define_var_type(&param.name, ty);
                        }
                    }
                    self.check_expr(body, Some(method_name));
                    self.pop_scope();
                    self.pop_context();
                }
                _ => {}
            }
        }

        self.functions = old_functions;
        self.function_arities = old_function_arities;
        self.function_params = old_function_params;
        self.function_params_by_arity = old_function_params_by_arity;
        self.user_functions = old_user_functions;
        self.pop_context();
    }

    pub fn var_defined(&self, name: &str) -> bool {
        for scope in self.scopes.iter().rev() {
            if scope.contains(name) {
                return true;
            }
        }
        false
    }

    /// Report an error with a span from an AST expression.
    /// Uses the expression's span directly when available, falling back to
    /// the old find_symbol_in_source heuristic for dummy spans.
    pub fn error_at_expr(&mut self, expr: &Expr, msg: String) {
        let span = if !expr.span.is_dummy() {
            Some(expr.span)
        } else if !self.source_text.is_empty() {
            // Fallback: try to find symbol in source
            if let Some(start) = msg.find('`') {
                if let Some(end) = msg[start + 1..].find('`') {
                    let name = &msg[start + 1..start + 1 + end];
                    Self::find_symbol_in_source(&self.source_text, name)
                        .map(|(line, col)| line_col_to_span(&self.source_text, line, col))
                } else {
                    None
                }
            } else {
                None
            }
        } else {
            None
        };

        let mut diag = if let Some(s) = span {
            Diagnostic::error_at(s, &msg)
        } else {
            Diagnostic::error(&msg)
        };
        diag.context = self.error_context.clone();
        self.diagnostics.push(diag);
    }

    fn error_at_span(&mut self, span: Span, msg: impl Into<String>) {
        let mut diagnostic = if span.is_dummy() {
            Diagnostic::error(msg.into())
        } else {
            Diagnostic::error_at(span, msg.into())
        };
        diagnostic.context = self.error_context.clone();
        self.diagnostics.push(diagnostic);
    }

    pub fn error(&mut self, msg: String) {
        // Try to derive a span from backtick-quoted symbol name in the source
        let span = if !self.source_text.is_empty() {
            if let Some(start) = msg.find('`') {
                if let Some(end) = msg[start + 1..].find('`') {
                    let name = &msg[start + 1..start + 1 + end];
                    if let Some((line, col)) = Self::find_symbol_in_source(&self.source_text, name)
                    {
                        Some(line_col_to_span(&self.source_text, line, col))
                    } else {
                        None
                    }
                } else {
                    None
                }
            } else {
                None
            }
        } else {
            None
        };

        let mut diag = if let Some(s) = span {
            Diagnostic::error_at(s, &msg)
        } else {
            Diagnostic::error(&msg)
        };

        // Attach current context breadcrumbs
        diag.context = self.error_context.clone();

        self.diagnostics.push(diag);
    }

    /// Push an error context breadcrumb (e.g. "in function `foo`")
    pub fn push_context(&mut self, ctx: impl Into<String>) {
        self.error_context.push(ctx.into());
    }

    /// Pop the most recent error context breadcrumb
    pub fn pop_context(&mut self) {
        self.error_context.pop();
    }

    /// Find a symbol name in source text, returning 1-based (line, col).
    fn find_symbol_in_source(source: &str, name: &str) -> Option<(usize, usize)> {
        for (line_idx, line) in source.lines().enumerate() {
            // Skip comments
            let trimmed = line.trim();
            if trimmed.starts_with("--") {
                continue;
            }
            // Search for whole-word match
            let mut pos = 0;
            while let Some(found) = line[pos..].find(name) {
                let abs = pos + found;
                let before_ok = abs == 0
                    || !line.as_bytes()[abs - 1].is_ascii_alphanumeric()
                        && line.as_bytes()[abs - 1] != b'_';
                let after_pos = abs + name.len();
                let after_ok = after_pos >= line.len()
                    || !line.as_bytes()[after_pos].is_ascii_alphanumeric()
                        && line.as_bytes()[after_pos] != b'_';
                if before_ok && after_ok {
                    return Some((line_idx + 1, abs + 1));
                }
                pos = abs + 1;
            }
        }
        None
    }

    fn exported_names_from_stmts(stmts: &[Stmt]) -> BTreeSet<String> {
        let mut exported = BTreeSet::new();
        let mut is_export = false;
        for stmt in stmts {
            if let Stmt::Annot(name, args) = stmt {
                if name == "export" {
                    for arg in args {
                        if let ExprKind::Var(n) = &arg.kind {
                            exported.insert(n.clone());
                        }
                    }
                    if args.is_empty() {
                        is_export = true;
                    }
                    continue;
                }
            }
            if is_export {
                match stmt {
                    Stmt::Defn(Defn::Fn { name, .. })
                    | Stmt::Defn(Defn::Actor { name, .. })
                    | Stmt::Defn(Defn::Module { name, .. }) => {
                        exported.insert(name.clone());
                    }
                    Stmt::TypeDecl(TypeDecl::ADT { name, variants, .. }) => {
                        exported.insert(name.clone());
                        for variant in variants {
                            exported.insert(variant.name.clone());
                        }
                    }
                    Stmt::TypeDecl(TypeDecl::RuleScope { name, .. }) => {
                        exported.insert(name.clone());
                    }
                    Stmt::Bind(Pat::Var(name), _, _) | Stmt::StreamBind(name, _) => {
                        exported.insert(name.clone());
                    }
                    Stmt::TypeDecl(TypeDecl::WhenType { .. })
                    | Stmt::TypeDecl(TypeDecl::EffectDecl { .. })
                    | Stmt::TypeDecl(TypeDecl::TraitDecl { .. })
                    | Stmt::TypeDecl(TypeDecl::ImplBlock { .. })
                    | Stmt::Rule(_)
                    | Stmt::Use(_)
                    | Stmt::Import(_)
                    | Stmt::QualifiedImport(_, _)
                    | Stmt::HashImport(_, _)
                    | Stmt::Depend(_, _)
                    | Stmt::RustBlock(_)
                    | Stmt::Annot(_, _)
                    | Stmt::Bind(_, _, _)
                    | Stmt::MonadicBind(_, _, _)
                    | Stmt::For(_, _, _)
                    | Stmt::While(_, _)
                    | Stmt::Send(_, _)
                    | Stmt::StreamSub(_, _)
                    | Stmt::Invariant { .. }
                    | Stmt::Prove { .. }
                    | Stmt::Explore(_)
                    | Stmt::Assert(_, _)
                    | Stmt::Retract(_, _)
                    | Stmt::Abort
                    | Stmt::Expr(_) => {}
                }
                is_export = false;
            }
        }
        for stmt in stmts {
            if let Stmt::TypeDecl(TypeDecl::ADT { name, variants, .. }) = stmt {
                if exported.contains(name) {
                    for variant in variants {
                        exported.insert(variant.name.clone());
                    }
                }
            }
        }
        exported
    }

    fn import_path_span(&self, import_path: &str) -> Option<Span> {
        if self.source_text.is_empty() {
            return None;
        }
        Self::find_symbol_in_source(&self.source_text, import_path)
            .map(|(line, col)| line_col_to_span(&self.source_text, line, col))
    }

    fn error_at_import_path(&mut self, import_path: &str, msg: String) {
        let mut diag = if let Some(span) = self.import_path_span(import_path) {
            Diagnostic::error_at(span, &msg)
        } else {
            Diagnostic::error(&msg)
        };
        diag.context = self.error_context.clone();
        self.diagnostics.push(diag);
    }

    fn phase_a_source_snapshot_match(
        &self,
        file_path: &str,
        module: &ParsedSourceModule,
    ) -> Option<bool> {
        let canonical =
            std::fs::canonicalize(file_path).unwrap_or_else(|_| PathBuf::from(file_path));
        let current_module = Self::analysis_module_id(module.statements());
        let expected = self
            .analysis_program
            .declarations
            .iter()
            .filter(|declaration| {
                declaration
                    .canonical_source_path
                    .as_deref()
                    .is_some_and(|path| path.as_path() == canonical.as_path())
            })
            .map(|declaration| declaration.id.module.clone())
            .collect::<BTreeSet<_>>();
        (!expected.is_empty()).then(|| expected.contains(&current_module))
    }

    fn phase_a_has_exact_source_snapshot(&self, file_path: &str) -> bool {
        let canonical =
            std::fs::canonicalize(file_path).unwrap_or_else(|_| PathBuf::from(file_path));
        self.analysis_program
            .declarations
            .iter()
            .any(|declaration| {
                declaration
                    .canonical_source_path
                    .as_deref()
                    .is_some_and(|path| path.as_path() == canonical.as_path())
            })
    }

    fn parse_imported_source_for_tc(
        &mut self,
        import_path: &str,
        file_path: &str,
        feeds_checked_resolution: bool,
    ) -> Option<Arc<ParsedSourceModule>> {
        let source = match std::fs::read_to_string(file_path) {
            Ok(source) => source,
            Err(error) => {
                if feeds_checked_resolution || self.phase_a_has_exact_source_snapshot(file_path) {
                    self.checked_resolution_source_snapshot_coherent = false;
                }
                self.error_at_import_path(
                    import_path,
                    format!(
                        "cannot resolve import `{}`: {} ({})",
                        import_path, file_path, error
                    ),
                );
                return None;
            }
        };
        match parse_source_module_cached(Path::new(file_path), &source) {
            Ok(module) => {
                let snapshot_match = self.phase_a_source_snapshot_match(file_path, &module);
                if (feeds_checked_resolution && snapshot_match != Some(true))
                    || snapshot_match == Some(false)
                {
                    self.checked_resolution_source_snapshot_coherent = false;
                }
                Some(module)
            }
            Err(error) => {
                if feeds_checked_resolution || self.phase_a_has_exact_source_snapshot(file_path) {
                    self.checked_resolution_source_snapshot_coherent = false;
                }
                self.error_at_import_path(
                    import_path,
                    format!(
                        "cannot parse imported module `{}` at {}: {}",
                        import_path, file_path, error
                    ),
                );
                None
            }
        }
    }

    fn collect_declarations_from_imported_file(
        &mut self,
        import_stmts: &[Stmt],
        file_path: &str,
        fallback_dir: &str,
    ) {
        let imported_dir = std::path::Path::new(file_path)
            .parent()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|| fallback_dir.to_string());
        let previous_dir = self.source_dir.clone();
        self.source_dir = Some(imported_dir);
        self.collect_declarations(import_stmts);
        self.infer_rule_return_types(import_stmts);
        // Exact Explore rule-return inference is a whole-program fixed point.
        // Running it at every nested import boundary repeatedly revisits the
        // entire accumulated rule graph (quadratic on deep corpora) and cannot
        // establish anything the root pass does not recompute after collection.
        self.infer_top_level_binding_types(import_stmts);
        self.source_dir = previous_dir;
    }

    fn collect_nested_declarations(&mut self, stmts: &[Stmt]) {
        self.explore_inline_module_depth += 1;
        self.collect_declarations(stmts);
        self.explore_inline_module_depth -= 1;
    }

    fn rule_dispatch_prelude_declaration_identity(
        statement: &Stmt,
    ) -> Option<(String, String, String)> {
        match statement {
            Stmt::Defn(definition) => Some((
                "definition".to_string(),
                defn_name(definition).to_string(),
                content_hash_defn(definition),
            )),
            Stmt::TypeDecl(declaration) => Some((
                "type".to_string(),
                type_decl_name(declaration).to_string(),
                content_hash_type(declaration),
            )),
            _ => None,
        }
    }

    fn leading_rule_dispatch_prelude_indices(statements: &[Stmt]) -> BTreeSet<usize> {
        let prelude = parse_prelude()
            .iter()
            .filter_map(Self::rule_dispatch_prelude_declaration_identity)
            .collect::<Vec<_>>();
        let mut cursor = 0;
        let mut indices = BTreeSet::new();
        for (index, statement) in statements.iter().enumerate() {
            let Some(identity) = Self::rule_dispatch_prelude_declaration_identity(statement) else {
                break;
            };
            let Some(relative) = prelude[cursor..]
                .iter()
                .position(|candidate| candidate == &identity)
            else {
                break;
            };
            cursor += relative + 1;
            indices.insert(index);
        }
        indices
    }

    fn nested_rule_dispatch_ast_mutates_shared_registry(child: AstChild<'_>) -> bool {
        match child {
            AstChild::Stmt(statement)
                if matches!(
                    statement,
                    Stmt::Defn(_)
                        | Stmt::TypeDecl(_)
                        | Stmt::Rule(_)
                        | Stmt::Import(_)
                        | Stmt::QualifiedImport(_, _)
                        | Stmt::HashImport(_, _)
                ) =>
            {
                true
            }
            AstChild::Stmt(statement) => {
                let mut opaque = false;
                visit_ast_stmt_children(statement, &mut |child| {
                    opaque |= Self::nested_rule_dispatch_ast_mutates_shared_registry(child);
                });
                opaque
            }
            AstChild::Expr(expression) => {
                let mut opaque = false;
                visit_ast_expr_children(expression, &mut |child| {
                    opaque |= Self::nested_rule_dispatch_ast_mutates_shared_registry(child);
                });
                opaque
            }
        }
    }

    fn top_level_rule_dispatch_stmt_mutates_shared_registry(statement: &Stmt) -> bool {
        match statement {
            Stmt::Defn(Defn::Module { .. })
            | Stmt::TypeDecl(TypeDecl::WhenType { .. })
            | Stmt::Rule(Rule::ReactiveScope { .. })
            | Stmt::QualifiedImport(_, _) => true,
            Stmt::TypeDecl(TypeDecl::RuleScope { body, .. }) => {
                body.iter().any(|member| match member {
                    Stmt::Rule(rule) if !matches!(rule, Rule::ReactiveScope { .. }) => {
                        let mut opaque = false;
                        visit_ast_rule_children(rule, &mut |child| {
                            opaque |= Self::nested_rule_dispatch_ast_mutates_shared_registry(child);
                        });
                        opaque
                    }
                    Stmt::Defn(definition) if !matches!(definition, Defn::Module { .. }) => {
                        let mut opaque = false;
                        visit_ast_defn_children(definition, &mut |child| {
                            opaque |= Self::nested_rule_dispatch_ast_mutates_shared_registry(child);
                        });
                        opaque
                    }
                    Stmt::Defn(_)
                    | Stmt::TypeDecl(_)
                    | Stmt::Rule(_)
                    | Stmt::Import(_)
                    | Stmt::QualifiedImport(_, _)
                    | Stmt::HashImport(_, _) => true,
                    other => {
                        let mut opaque = false;
                        visit_ast_stmt_children(other, &mut |child| {
                            opaque |= Self::nested_rule_dispatch_ast_mutates_shared_registry(child);
                        });
                        opaque
                    }
                })
            }
            other => {
                let mut opaque = false;
                visit_ast_stmt_children(other, &mut |child| {
                    opaque |= Self::nested_rule_dispatch_ast_mutates_shared_registry(child);
                });
                opaque
            }
        }
    }
    fn rule_dispatch_program_has_opaque_runtime_graph(statements: &[Stmt]) -> bool {
        let injected_prelude = Self::leading_rule_dispatch_prelude_indices(statements);
        let mut program_started = false;
        for (index, statement) in statements.iter().enumerate() {
            if injected_prelude.contains(&index) {
                continue;
            }
            match statement {
                Stmt::HashImport(_, _) => return true,
                Stmt::Import(_) => {
                    if program_started {
                        return true;
                    }
                }
                Stmt::QualifiedImport(_, _) => return true,
                Stmt::Annot(_, _) | Stmt::Use(_) | Stmt::Depend(_, _) | Stmt::RustBlock(_) => {}
                _ => program_started = true,
            }
            if Self::top_level_rule_dispatch_stmt_mutates_shared_registry(statement) {
                return true;
            }
        }
        false
    }

    /// Resolve an import path for the type checker (manifest-aware).
    fn resolve_tc_import(import_path: &str, dir: &str) -> Option<String> {
        let rel = import_path.trim_start_matches("./");
        let file_path = format!("{}/{}.runa", dir, rel);

        if import_path.starts_with("./") || std::path::Path::new(&file_path).exists() {
            return Some(file_path);
        }

        // Try manifest-based resolution
        if let Some(toml_path) = Interpreter::find_manifest(dir) {
            if let Some((deps, _)) = Interpreter::parse_manifest_deps(&toml_path) {
                let toml_dir = std::path::Path::new(&toml_path)
                    .parent()
                    .map(|p| {
                        let s = p.to_string_lossy().to_string();
                        if s.is_empty() {
                            ".".to_string()
                        } else {
                            s
                        }
                    })
                    .unwrap_or_else(|| ".".to_string());

                if let Some(resolved) = Self::resolve_dep_module(import_path, &deps, &toml_dir) {
                    return Some(resolved);
                }
            }
        }

        Some(file_path)
    }

    /// Resolve a dependency module path from manifest deps
    fn resolve_dep_module(
        import_path: &str,
        deps: &[(String, String)],
        toml_dir: &str,
    ) -> Option<String> {
        let parts: Vec<&str> = import_path.splitn(2, '/').collect();
        let dep_name = parts[0];
        let module = if parts.len() > 1 { parts[1] } else { "lib" };

        for (name, dep_path) in deps {
            if name == dep_name {
                let abs_dep = if std::path::Path::new(dep_path.as_str()).is_absolute() {
                    dep_path.clone()
                } else {
                    format!("{}/{}", toml_dir, dep_path)
                };
                let dep_file = format!("{}/{}.runa", abs_dep, module);
                let dep_file_src = format!("{}/src/{}.runa", abs_dep, module);

                if std::path::Path::new(&dep_file).exists() {
                    return Some(dep_file);
                } else if std::path::Path::new(&dep_file_src).exists() {
                    return Some(dep_file_src);
                }
            }
        }
        None
    }

    /// Pass 1: collect all declarations from the program
    pub fn collect_declarations(&mut self, stmts: &[Stmt]) {
        self.rule_dispatch_has_opaque_runtime_graph |=
            Self::rule_dispatch_program_has_opaque_runtime_graph(stmts);
        for stmt in stmts {
            self.record_explore_top_level_binding_initializer(stmt);
            match stmt {
                Stmt::Defn(Defn::Fn {
                    name,
                    params,
                    ret_ty,
                    effects,
                    body,
                }) => {
                    self.record_explore_non_rule_runtime_name(name);
                    let param_names = params
                        .iter()
                        .map(|param| param.name.clone())
                        .collect::<Vec<_>>();
                    self.functions.insert(name.clone(), params.len());
                    self.function_params
                        .insert(name.clone(), param_names.clone());
                    self.record_function_signature(name, params.len(), Some(param_names));
                    self.user_functions.insert(name.clone());
                    if self.explore_inline_module_depth == 0 {
                        self.record_explore_function_definition(
                            name,
                            params,
                            ret_ty.as_ref(),
                            effects,
                            body,
                        );
                    }
                    self.register_reference_symbol(name, ProgramSymbolKind::Function);
                    self.define_var(name);
                }
                Stmt::Defn(Defn::Actor { name, .. }) => {
                    self.record_explore_non_rule_runtime_name(name);
                    self.types.insert(name.clone());
                    self.define_var(name);
                }
                Stmt::Defn(Defn::Module { name, body }) => {
                    self.record_explore_non_rule_runtime_name(name);
                    self.define_var(name);
                    self.collect_nested_declarations(body);
                }
                Stmt::TypeDecl(TypeDecl::ADT {
                    name,
                    variants,
                    methods,
                    ..
                }) => {
                    self.types.insert(name.clone());
                    let mut type_field_names = BTreeSet::new();
                    let mut type_field_types = BTreeMap::new();
                    let mut type_field_tys = BTreeMap::new();
                    let mut variant_names = Vec::new();
                    for variant in variants {
                        let field_count = variant.fields.len();
                        self.record_explore_non_rule_runtime_name(&variant.name);
                        self.register_constructor_signature(
                            name,
                            &variant.name,
                            variant.positional,
                            variant
                                .fields
                                .iter()
                                .map(|field| field.name.clone())
                                .collect(),
                            variant
                                .fields
                                .iter()
                                .map(|field| Self::type_name_from_ty(&field.ty))
                                .collect(),
                            variant
                                .fields
                                .iter()
                                .map(|field| Some(field.ty.to_string()))
                                .collect(),
                        );
                        variant_names.push(variant.name.clone());
                        let variant_field_names: BTreeSet<String> = variant
                            .fields
                            .iter()
                            .map(|field| field.name.clone())
                            .collect();
                        type_field_names.extend(variant_field_names.iter().cloned());
                        let variant_field_types: BTreeMap<String, String> = variant
                            .fields
                            .iter()
                            .filter_map(|field| {
                                Self::type_name_from_ty(&field.ty)
                                    .map(|ty| (field.name.clone(), ty))
                            })
                            .collect();
                        let variant_field_tys: BTreeMap<String, Ty> = variant
                            .fields
                            .iter()
                            .map(|field| (field.name.clone(), field.ty.clone()))
                            .collect();
                        for (field_name, field_ty) in &variant_field_types {
                            type_field_types
                                .entry(field_name.clone())
                                .or_insert_with(|| field_ty.clone());
                        }
                        for (field_name, field_ty) in &variant_field_tys {
                            type_field_tys
                                .entry(field_name.clone())
                                .or_insert_with(|| field_ty.clone());
                        }
                        if !variant_field_names.is_empty() {
                            self.type_fields
                                .insert(variant.name.clone(), variant_field_names);
                        }
                        if !variant_field_types.is_empty() {
                            self.type_field_types
                                .insert(variant.name.clone(), variant_field_types);
                        }
                        if !variant_field_tys.is_empty() {
                            self.type_field_tys
                                .insert(variant.name.clone(), variant_field_tys);
                        }
                        if variants.len() == 1 && variant.name == *name && field_count > 0 {
                            self.functions.insert(name.clone(), field_count);
                            self.record_function_signature(name, field_count, None);
                            self.user_functions.insert(name.clone());
                        }
                    }
                    if !type_field_names.is_empty() {
                        self.type_fields.insert(name.clone(), type_field_names);
                    }
                    if !type_field_types.is_empty() {
                        self.type_field_types.insert(name.clone(), type_field_types);
                    }
                    if !type_field_tys.is_empty() {
                        self.type_field_tys.insert(name.clone(), type_field_tys);
                    }
                    if variants.len() > 1 {
                        self.type_variants.insert(name.clone(), variant_names);
                    }
                    for defn in methods {
                        if let Defn::Fn {
                            name,
                            params,
                            effects,
                            body,
                            ..
                        } = defn
                        {
                            self.record_explore_non_rule_runtime_name(name);
                            let param_names = params
                                .iter()
                                .map(|param| param.name.clone())
                                .collect::<Vec<_>>();
                            self.functions.insert(name.clone(), params.len());
                            self.function_params
                                .insert(name.clone(), param_names.clone());
                            self.record_function_signature(name, params.len(), Some(param_names));
                            self.register_reference_symbol(name, ProgramSymbolKind::Function);
                        }
                    }
                }
                Stmt::TypeDecl(TypeDecl::RuleScope { name, params, body }) => {
                    self.record_explore_non_rule_runtime_name(name);
                    // A later declaration replaces the complete scoped rule
                    // surface, matching runtime RuleDispatchRegistry ownership.
                    if self.explore_inline_module_depth == 0 {
                        self.explore_scoped_callable_expressions
                            .retain(|key, _| key.scope.as_deref() != Some(name));
                        for statement in body {
                            if let Stmt::Rule(rule) = statement {
                                self.record_explore_scoped_rule_body(name, params, rule);
                            }
                        }
                    }
                    self.types.insert(name.clone());
                    self.register_constructor_signature(
                        name,
                        name,
                        false,
                        params.iter().map(|param| param.name.clone()).collect(),
                        params
                            .iter()
                            .map(|param| param.ty.as_ref().and_then(Self::type_name_from_ty))
                            .collect(),
                        params
                            .iter()
                            .map(|param| param.ty.as_ref().map(ToString::to_string))
                            .collect(),
                    );
                    self.functions.insert(name.clone(), params.len());
                    let param_names = params
                        .iter()
                        .map(|param| param.name.clone())
                        .collect::<Vec<_>>();
                    self.function_params
                        .insert(name.clone(), param_names.clone());
                    self.record_function_signature(name, params.len(), Some(param_names));
                    self.user_functions.insert(name.clone());
                    self.define_var(name);
                    self.type_fields.insert(
                        name.clone(),
                        params.iter().map(|param| param.name.clone()).collect(),
                    );
                    let rule_scope_field_types: BTreeMap<String, String> = params
                        .iter()
                        .filter_map(|param| {
                            param
                                .ty
                                .as_ref()
                                .and_then(Self::type_name_from_ty)
                                .map(|ty| (param.name.clone(), ty))
                        })
                        .collect();
                    if !rule_scope_field_types.is_empty() {
                        self.type_field_types
                            .insert(name.clone(), rule_scope_field_types);
                    }
                    let rule_scope_field_tys: BTreeMap<String, Ty> = params
                        .iter()
                        .filter_map(|param| {
                            param.ty.as_ref().map(|ty| (param.name.clone(), ty.clone()))
                        })
                        .collect();
                    if !rule_scope_field_tys.is_empty() {
                        self.type_field_tys
                            .insert(name.clone(), rule_scope_field_tys);
                    }
                    self.rule_scope_methods
                        .insert(name.clone(), Self::rule_scope_method_arities(body));
                    self.rule_scope_method_params
                        .insert(name.clone(), Self::rule_scope_method_params(body));
                    self.rule_scope_value_methods
                        .insert(name.clone(), Self::rule_scope_value_method_arities(body));
                    self.rule_scope_value_method_params
                        .insert(name.clone(), Self::rule_scope_value_method_params(body));
                    self.infer_rule_scope_member_return_types(name, params, body);
                }
                Stmt::TypeDecl(TypeDecl::EffectDecl { name, ops }) => {
                    self.types.insert(name.clone());
                    let mut ops_map = BTreeMap::new();
                    for (op_name, params, _) in ops {
                        self.record_explore_non_rule_runtime_name(op_name);
                        let param_names = params
                            .iter()
                            .map(|param| param.name.clone())
                            .collect::<Vec<_>>();
                        ops_map.insert(op_name.clone(), params.len());
                        self.functions.insert(op_name.clone(), params.len());
                        self.function_params
                            .insert(op_name.clone(), param_names.clone());
                        self.record_function_signature(op_name, params.len(), Some(param_names));
                        self.register_reference_symbol(op_name, ProgramSymbolKind::Function);
                    }
                    self.effect_ops.insert(name.clone(), ops_map);
                }
                Stmt::TypeDecl(TypeDecl::TraitDecl { name, methods, .. }) => {
                    self.types.insert(name.clone());
                    let mut method_names = Vec::new();
                    for method in methods {
                        self.record_explore_non_rule_runtime_name(&method.name);
                        let param_names = method
                            .params
                            .iter()
                            .map(|param| param.name.clone())
                            .collect::<Vec<_>>();
                        self.functions
                            .insert(method.name.clone(), method.params.len());
                        self.function_params
                            .insert(method.name.clone(), param_names.clone());
                        self.record_function_signature(
                            &method.name,
                            method.params.len(),
                            Some(param_names),
                        );
                        self.register_reference_symbol(&method.name, ProgramSymbolKind::Function);
                        method_names.push(method.name.clone());
                        self.trait_method_receivers.insert(
                            (name.clone(), method.name.clone()),
                            Self::method_receiver_shape(&method.params),
                        );
                    }
                    self.trait_methods.insert(name.clone(), method_names);
                }
                Stmt::TypeDecl(TypeDecl::ImplBlock {
                    trait_name,
                    for_type,
                    methods,
                }) => {
                    let mut method_names = Vec::new();
                    for defn in methods {
                        if let Defn::Fn {
                            name,
                            params,
                            effects,
                            body,
                            ..
                        } = defn
                        {
                            self.record_explore_non_rule_runtime_name(name);
                            let param_names = params
                                .iter()
                                .map(|param| param.name.clone())
                                .collect::<Vec<_>>();
                            self.functions.insert(name.clone(), params.len());
                            self.function_params
                                .insert(name.clone(), param_names.clone());
                            self.record_function_signature(name, params.len(), Some(param_names));
                            self.register_reference_symbol(name, ProgramSymbolKind::Function);
                            method_names.push(name.clone());
                            self.impl_method_receivers.insert(
                                (trait_name.clone(), for_type.clone(), name.clone()),
                                Self::method_receiver_shape(params),
                            );
                        }
                    }
                    self.impl_methods
                        .insert((trait_name.clone(), for_type.clone()), method_names);
                }
                Stmt::Bind(Pat::Var(name), _, _) => {
                    self.record_explore_non_rule_runtime_name(name);
                    self.register_reference_symbol(name, ProgramSymbolKind::Binding);
                    self.define_var(name);
                }
                Stmt::MonadicBind(Pat::Var(name), _, _) => {
                    self.record_explore_non_rule_runtime_name(name);
                    self.register_reference_symbol(name, ProgramSymbolKind::Binding);
                    self.define_var(name);
                }
                Stmt::Bind(pattern, _, _) | Stmt::MonadicBind(pattern, _, _) => {
                    let mut names = BTreeSet::new();
                    collect_pattern_names(pattern, &mut names);
                    for name in names {
                        self.record_explore_non_rule_runtime_name(&name);
                        self.register_reference_symbol(&name, ProgramSymbolKind::Binding);
                        self.define_var(&name);
                    }
                }
                Stmt::StreamBind(name, _) => {
                    self.record_explore_non_rule_runtime_name(name);
                    self.register_reference_symbol(name, ProgramSymbolKind::Binding);
                    self.define_var(name);
                }
                Stmt::Rule(Rule::ReactiveScope { name, body }) => {
                    self.record_explore_non_rule_runtime_name(name);
                    self.register_reference_symbol(name, ProgramSymbolKind::Binding);
                    self.define_var(name);
                    self.collect_nested_declarations(body);
                }
                Stmt::Rule(Rule::Default { head, .. })
                | Stmt::Rule(Rule::Exception { head, .. })
                | Stmt::Rule(Rule::Clause { head, .. }) => {
                    if let ExprKind::App(func, args) = &head.kind {
                        if let ExprKind::Var(fname) = &func.as_ref().kind {
                            self.functions.entry(fname.clone()).or_insert(args.len());
                            self.record_function_signature(fname, args.len(), None);
                            if let Some(param_names) = Self::rule_head_param_names(head) {
                                self.function_params
                                    .entry(fname.clone())
                                    .or_insert_with(|| param_names.clone());
                                self.function_params_by_arity
                                    .entry((fname.clone(), args.len()))
                                    .or_insert(param_names);
                            }
                            self.register_reference_symbol(fname, ProgramSymbolKind::Rule);
                            if self.explore_inline_module_depth == 0 {
                                self.record_rule_signature(fname, head);
                            }
                            self.define_var(fname);
                        }
                    } else if let ExprKind::Var(fname) = &head.kind {
                        // Zero-arg rule without parens: | foo -> Bar
                        self.functions.entry(fname.clone()).or_insert(0);
                        self.function_params.entry(fname.clone()).or_insert(vec![]);
                        self.record_function_signature(fname, 0, None);
                        self.function_params_by_arity
                            .entry((fname.clone(), 0))
                            .or_insert(vec![]);
                        self.register_reference_symbol(fname, ProgramSymbolKind::Rule);
                        if self.explore_inline_module_depth == 0 {
                            self.record_rule_signature(fname, head);
                        }
                        self.define_var(fname);
                    }
                    if let Stmt::Rule(rule) = stmt {
                        if self.explore_inline_module_depth == 0 {
                            self.record_explore_rule_body(rule);
                        }
                        if let Some((rule_name, scope_name)) =
                            Self::rule_scope_return_candidate(rule)
                        {
                            self.rule_scope_returning_rules
                                .insert(rule_name, scope_name);
                        }
                    }
                }
                Stmt::Invariant { name, .. } => {
                    self.invariant_names.insert(name.clone());
                }
                Stmt::For(var, _, _) => {
                    self.define_var(var);
                }
                Stmt::RustBlock(code) => {
                    // Register functions defined in @ rust { } blocks so the type
                    // checker doesn't reject calls to them. Parse fn signatures.
                    for line in code.lines() {
                        let trimmed = line.trim();
                        // Match: fn name(params) or pub fn name(params)
                        let fn_start = if trimmed.starts_with("pub fn ") {
                            Some(7)
                        } else if trimmed.starts_with("fn ") {
                            Some(3)
                        } else {
                            None
                        };
                        if let Some(start) = fn_start {
                            let rest = &trimmed[start..];
                            if let Some(paren) = rest.find('(') {
                                let fn_name = rest[..paren].trim().to_string();
                                // Count params by counting commas + 1 (rough)
                                if let Some(close) = rest.find(')') {
                                    let params_str = &rest[paren + 1..close];
                                    let arity = if params_str.trim().is_empty() {
                                        0
                                    } else {
                                        params_str.split(',').count()
                                    };
                                    self.functions.insert(fn_name.clone(), arity);
                                    self.record_explore_non_rule_runtime_name(&fn_name);
                                    self.record_function_signature(&fn_name, arity, None);
                                    self.register_reference_symbol(
                                        &fn_name,
                                        ProgramSymbolKind::Function,
                                    );
                                    self.define_var(&fn_name);
                                }
                            }
                        }
                    }
                }
                Stmt::Import(path) => {
                    // Resolve @ import and collect declarations.
                    if let Some(dir) = self.source_dir.clone() {
                        let file_path = Self::resolve_tc_import(path, &dir);
                        if let Some(file_path) = file_path {
                            let canon = std::fs::canonicalize(&file_path)
                                .map(|p| p.to_string_lossy().to_string())
                                .unwrap_or(file_path.clone());
                            if !self.imported.contains(&canon) {
                                self.imported.insert(canon);
                                if let Some(import_stmts) =
                                    self.parse_imported_source_for_tc(path, &file_path, true)
                                {
                                    self.collect_declarations_from_imported_file(
                                        import_stmts.statements(),
                                        &file_path,
                                        &dir,
                                    );
                                }
                            }
                        }
                    }
                }
                Stmt::QualifiedImport(mod_name, path) => {
                    self.record_explore_non_rule_runtime_name(mod_name);
                    self.define_var(mod_name);
                    if let Some(dir) = self.source_dir.clone() {
                        if let Some(file_path) = Self::resolve_tc_import(path, &dir) {
                            let canon = std::fs::canonicalize(&file_path)
                                .map(|p| p.to_string_lossy().to_string())
                                .unwrap_or(file_path.clone());
                            if !self.imported.contains(&canon) {
                                self.imported.insert(canon);
                            }
                            if let Some(import_stmts) =
                                self.parse_imported_source_for_tc(path, &file_path, false)
                            {
                                let exported =
                                    Self::exported_names_from_stmts(import_stmts.statements());
                                self.module_exports.insert(mod_name.clone(), exported);
                            }
                        }
                    }
                }
                Stmt::Use(_) => {}
                Stmt::HashImport(hash, path) => {
                    if let Some(dir) = self.source_dir.clone() {
                        if let Some(file_path) = Self::resolve_tc_import(path, &dir) {
                            let canon = std::fs::canonicalize(&file_path)
                                .map(|p| p.to_string_lossy().to_string())
                                .unwrap_or(file_path.clone());
                            let import_key = format!("{}#{}", canon, hash);
                            if !self.imported.contains(&import_key) {
                                self.imported.insert(import_key);
                                if let Some(import_stmts) =
                                    self.parse_imported_source_for_tc(path, &file_path, true)
                                {
                                    let matched: Vec<Stmt> = import_stmts
                                        .statements()
                                        .iter()
                                        .filter(|s| match s {
                                            Stmt::Defn(d) => content_hash_defn(d) == *hash,
                                            Stmt::TypeDecl(td) => content_hash_type(td) == *hash,
                                            Stmt::Rule(_)
                                            | Stmt::Use(_)
                                            | Stmt::Import(_)
                                            | Stmt::QualifiedImport(_, _)
                                            | Stmt::HashImport(_, _)
                                            | Stmt::Depend(_, _)
                                            | Stmt::RustBlock(_)
                                            | Stmt::Annot(_, _)
                                            | Stmt::Bind(_, _, _)
                                            | Stmt::MonadicBind(_, _, _)
                                            | Stmt::For(_, _, _)
                                            | Stmt::While(_, _)
                                            | Stmt::Send(_, _)
                                            | Stmt::StreamBind(_, _)
                                            | Stmt::StreamSub(_, _)
                                            | Stmt::Invariant { .. }
                                            | Stmt::Prove { .. }
                                            | Stmt::Explore(_)
                                            | Stmt::Assert(_, _)
                                            | Stmt::Retract(_, _)
                                            | Stmt::Abort
                                            | Stmt::Expr(_) => false,
                                        })
                                        .cloned()
                                        .collect();
                                    if matched.len() != 1 {
                                        self.error_at_import_path(
                                            path,
                                            format!(
                                                "cannot resolve hash import `#{}` from `{}`: expected exactly one matching definition, found {}",
                                                hash,
                                                path,
                                                matched.len()
                                            ),
                                        );
                                    } else {
                                        self.collect_declarations_from_imported_file(
                                            &matched, &file_path, &dir,
                                        );
                                    }
                                }
                            }
                        }
                    }
                }
                Stmt::TypeDecl(TypeDecl::WhenType { .. })
                | Stmt::Depend(_, _)
                | Stmt::Annot(_, _)
                | Stmt::While(_, _)
                | Stmt::Send(_, _)
                | Stmt::StreamSub(_, _)
                | Stmt::Prove { .. }
                | Stmt::Explore(_)
                | Stmt::Assert(_, _)
                | Stmt::Retract(_, _)
                | Stmt::Abort
                | Stmt::Expr(_) => {}
            }
        }
    }

    /// Pass 2: check the program for errors
    pub fn check_program(&mut self, stmts: &[Stmt]) {
        self.check_stmt_sequence_with_exploration_selection(stmts, true);
        // Check trait impl completeness
        self.check_trait_impls();
    }

    fn check_stmt_sequence(&mut self, stmts: &[Stmt]) {
        self.check_stmt_sequence_with_exploration_selection(stmts, false);
    }

    fn check_stmt_sequence_with_exploration_selection(
        &mut self,
        stmts: &[Stmt],
        selectable_explorations: bool,
    ) {
        let mut pending_comptime = false;
        for stmt in stmts {
            match stmt {
                Stmt::Annot(name, _) if name == "comptime" => {
                    self.check_stmt_with_exploration_selection(stmt, selectable_explorations);
                    pending_comptime = true;
                }
                Stmt::Expr(expr) if pending_comptime => {
                    if let ExprKind::App(func, args) = &expr.kind {
                        if matches!(&func.kind, ExprKind::Var(name) if name == "assert")
                            && args.len() == 1
                        {
                            self.check_expr(&args[0], None);
                            pending_comptime = false;
                            continue;
                        }
                    }
                    self.check_stmt_with_exploration_selection(stmt, selectable_explorations);
                    pending_comptime = false;
                }
                _ => {
                    self.check_stmt_with_exploration_selection(stmt, selectable_explorations);
                    pending_comptime = false;
                }
            }
        }
    }

    fn check_stmt_with_exploration_selection(&mut self, stmt: &Stmt, selectable: bool) {
        if let Stmt::Explore(query) = stmt {
            self.check_explore_query(query, selectable);
        } else {
            self.check_stmt(stmt);
        }
    }

    /// Verify each `# impl Trait for Type` provides all required methods.
    fn check_trait_impls(&mut self) {
        let mut errors = Vec::new();
        for ((trait_name, for_type, method_name), shape) in &self.impl_method_receivers {
            if *shape == MethodReceiverShape::Invalid {
                errors.push(format!(
                    "`# impl {} for {}` method `{}` uses `self` in an invalid position; `self` must be the first parameter",
                    trait_name, for_type, method_name
                ));
            }
        }
        for ((trait_name, for_type), provided) in &self.impl_methods {
            if let Some(required) = self.trait_methods.get(trait_name) {
                let missing: Vec<&String> = required
                    .iter()
                    .filter(|m| !provided.iter().any(|p| p == *m))
                    .collect();
                if !missing.is_empty() {
                    let missing_names: Vec<&str> = missing.iter().map(|s| s.as_str()).collect();
                    errors.push(format!(
                        "`# impl {} for {}` is missing method{}: {}",
                        trait_name,
                        for_type,
                        if missing.len() == 1 { "" } else { "s" },
                        missing_names.join(", ")
                    ));
                }
                for method_name in required {
                    if !provided.iter().any(|p| p == method_name) {
                        continue;
                    }
                    let trait_shape = self
                        .trait_method_receivers
                        .get(&(trait_name.clone(), method_name.clone()))
                        .copied()
                        .unwrap_or(MethodReceiverShape::None);
                    let impl_shape = self
                        .impl_method_receivers
                        .get(&(trait_name.clone(), for_type.clone(), method_name.clone()))
                        .copied()
                        .unwrap_or(MethodReceiverShape::None);
                    if impl_shape == MethodReceiverShape::Invalid || trait_shape == impl_shape {
                        continue;
                    }
                    match (trait_shape, impl_shape) {
                        (MethodReceiverShape::SelfFirst, MethodReceiverShape::None) => errors.push(
                            format!(
                                "`# impl {} for {}` method `{}` must declare `self` as its first parameter to match the trait receiver",
                                trait_name, for_type, method_name
                            ),
                        ),
                        (MethodReceiverShape::None, MethodReceiverShape::SelfFirst) => errors.push(
                            format!(
                                "`# impl {} for {}` method `{}` must not declare `self`; the trait method is not a receiver method",
                                trait_name, for_type, method_name
                            ),
                        ),
                        _ => {}
                    }
                }
            }
        }
        for err in errors {
            self.error(err);
        }
    }

    fn obvious_literal_ty(lit: &Literal) -> &'static str {
        match lit {
            Literal::Int(_) => "Int",
            Literal::Float(_) => "Float",
            Literal::Str(_) => "String",
            Literal::Char(_) => "Char",
            Literal::Bool(_) => "Bool",
        }
    }

    fn obvious_expr_ty(&mut self, expr: &Expr) -> Option<String> {
        match &expr.kind {
            ExprKind::Lit(lit) => Some(Self::obvious_literal_ty(lit).to_string()),
            ExprKind::Unit => Some("()".to_string()),
            ExprKind::List(items) => {
                let mut expected: Option<String> = None;
                for item in items {
                    let Some(item_ty) = self.obvious_expr_ty(item) else {
                        continue;
                    };
                    if let Some(expected_ty) = &expected {
                        if expected_ty != &item_ty {
                            self.error_at_expr(
                                item,
                                format!(
                                    "list elements must have the same type; first element is `{}` but this element is `{}`",
                                    expected_ty, item_ty
                                ),
                            );
                        }
                    } else {
                        expected = Some(item_ty);
                    }
                }
                expected.map(|inner| format!("List({})", inner))
            }
            ExprKind::If(_, then_expr, else_expr) => {
                let then_ty = self.obvious_expr_ty(then_expr);
                let else_ty = self.obvious_expr_ty(else_expr);
                match (then_ty, else_ty) {
                    (Some(then_ty), Some(else_ty)) => {
                        if then_ty != else_ty {
                            self.error_at_expr(
                                expr,
                                format!(
                                    "if branches must have the same type; then branch is `{}` but else branch is `{}`",
                                    then_ty, else_ty
                                ),
                            );
                        }
                        Some(then_ty)
                    }
                    (Some(ty), None) | (None, Some(ty)) => Some(ty),
                    (None, None) => None,
                }
            }
            ExprKind::Block(stmts) => stmts.last().and_then(|stmt| match stmt {
                Stmt::Expr(expr) => self.obvious_expr_ty(expr),
                _ => None,
            }),
            _ => None,
        }
    }

    fn check_declared_binding_ty(&mut self, ty: &Ty, expr: &Expr) {
        let Some(actual_ty) = self.obvious_expr_ty(expr) else {
            return;
        };
        let expected_ty = ty.to_string();
        if expected_ty != actual_ty {
            self.error_at_expr(
                expr,
                format!(
                    "type mismatch: binding expects `{}` but expression has `{}`",
                    expected_ty, actual_ty
                ),
            );
        }
    }

    fn inferred_explore_ty(&self, expr: &Expr) -> Option<Ty> {
        self.infer_expr_type_name(expr)
            .map(|name| parse_type_annotation(&name).unwrap_or_else(|_| Ty::Name(name)))
    }

    /// Decode the deliberately type-shaped argument of contextual
    /// `values(Type)`.  This is not general expression inference: only named
    /// type constructors and their type arguments are accepted.
    fn explore_ty_from_expr(expr: &Expr) -> Option<Ty> {
        match &expr.kind {
            ExprKind::Var(name) => {
                Some(parse_type_annotation(name).unwrap_or_else(|_| Ty::Name(name.clone())))
            }
            ExprKind::App(constructor, arguments) => {
                let ExprKind::Var(name) = &constructor.kind else {
                    return None;
                };
                let arguments = arguments
                    .iter()
                    .map(Self::explore_ty_from_expr)
                    .collect::<Option<Vec<_>>>()?;
                Some(Ty::App(Box::new(Ty::Name(name.clone())), arguments))
            }
            ExprKind::Unit => Some(Ty::Unit),
            _ => None,
        }
    }

    fn explore_domain_item_ty(&self, expr: &Expr) -> Option<Ty> {
        match &expr.kind {
            ExprKind::List(items) if items.is_empty() => None,
            ExprKind::App(function, arguments)
                if matches!(&function.kind, ExprKind::Var(name) if name == "values")
                    && arguments.len() == 1 =>
            {
                Self::explore_ty_from_expr(&arguments[0])
            }
            _ => {
                let collection = self.infer_expr_type_name(expr)?;
                let item = Self::applied_type_argument(&collection, "List", 0)
                    .or_else(|| Self::applied_type_argument(&collection, "Set", 0))?;
                Some(parse_type_annotation(&item).unwrap_or_else(|_| Ty::Name(item)))
            }
        }
    }

    fn explore_domain_item_ty_with_locals(
        &self,
        expr: &Expr,
        locals: &BTreeMap<String, String>,
    ) -> Option<Ty> {
        match &expr.kind {
            ExprKind::List(items) if items.is_empty() => None,
            ExprKind::App(function, arguments)
                if matches!(&function.kind, ExprKind::Var(name) if name == "values")
                    && arguments.len() == 1 =>
            {
                Self::explore_ty_from_expr(&arguments[0])
            }
            _ => {
                let collection = self.infer_expr_type_name_with_locals(expr, locals)?;
                let item = Self::applied_type_argument(&collection, "List", 0)
                    .or_else(|| Self::applied_type_argument(&collection, "Set", 0))?;
                Some(parse_type_annotation(&item).unwrap_or_else(|_| Ty::Name(item)))
            }
        }
    }

    fn eval_explore_fixed_int(expr: &Expr, fixed: &BTreeMap<String, i64>) -> Option<i64> {
        match &expr.kind {
            ExprKind::Lit(Literal::Int(value)) => Some(*value),
            ExprKind::Var(name) => fixed.get(name).copied(),
            ExprKind::UnOp(operator, value) if operator == "-" => {
                Self::eval_explore_fixed_int(value, fixed)?.checked_neg()
            }
            ExprKind::UnOp(operator, value) if operator == "+" => {
                Self::eval_explore_fixed_int(value, fixed)
            }
            ExprKind::BinOp(operator, left, right) => {
                let left = Self::eval_explore_fixed_int(left, fixed)?;
                let right = Self::eval_explore_fixed_int(right, fixed)?;
                match operator.as_str() {
                    "+" => left.checked_add(right),
                    "-" => left.checked_sub(right),
                    "*" => left.checked_mul(right),
                    "/" => left.checked_div(right),
                    "%" => left.checked_rem(right),
                    _ => None,
                }
            }
            _ => None,
        }
    }

    fn explore_scoped_member_call_key(
        &self,
        function: &Expr,
        arity: usize,
    ) -> Option<RuleDispatchKey> {
        let ExprKind::Field(receiver, member) = &function.kind else {
            return None;
        };
        let ExprKind::App(constructor, constructor_arguments) = &receiver.kind else {
            return None;
        };
        let ExprKind::Var(receiver_name) = &constructor.kind else {
            return None;
        };
        let scope = if let Some(signature) =
            self.constructor_signature_for_args(receiver_name, constructor_arguments)
        {
            (signature.parent == *receiver_name && self.type_has_scoped_members(&signature.parent))
                .then_some(signature.parent)?
        } else {
            let receiver_key = RuleDispatchKey {
                scope: None,
                name: receiver_name.clone(),
                arity: constructor_arguments.len(),
            };
            if self.explore_non_rule_runtime_names.contains(receiver_name)
                || !self.rule_dispatch_keys.contains(&receiver_key)
            {
                return None;
            }
            let return_type = self.rule_dispatch_return_types.get(&receiver_key)?;
            self.type_has_scoped_members(return_type)
                .then_some(return_type.clone())?
        };
        let key = RuleDispatchKey {
            scope: Some(scope),
            name: member.clone(),
            arity,
        };
        (self.rule_dispatch_keys.contains(&key)
            && self.explore_scoped_callable_expressions.contains_key(&key))
        .then_some(key)
    }

    fn explore_expression_capabilities(
        &self,
        expr: &Expr,
        bound: &BTreeSet<String>,
        callable_bound: &BTreeSet<String>,
    ) -> (bool, BTreeSet<(String, usize)>, BTreeSet<RuleDispatchKey>) {
        let impure_names = meta_impure_runtime_names();
        let effect_operations = self
            .effect_ops
            .values()
            .flat_map(|operations| operations.keys().cloned())
            .collect::<BTreeSet<_>>();
        let mut supported = true;
        let mut calls = BTreeSet::new();
        let mut scoped_calls = BTreeSet::new();
        walk_ast_expr(expr, &mut |child| match child {
            AstChild::Expr(expr) => match &expr.kind {
                ExprKind::Effect(_, _) | ExprKind::Handle { .. } | ExprKind::Try(_) => {
                    supported = false;
                }
                ExprKind::Field(receiver, _)
                    if matches!(
                        &receiver.kind,
                        ExprKind::Var(module) if self.module_exports.contains_key(module)
                    ) =>
                {
                    // Runtime initialization of a module member requires the
                    // owner-aware namespace slice.  Ordinary ADT fields remain
                    // supported; qualified module values fail closed in v1.
                    supported = false;
                }
                ExprKind::Pipe(_, transform)
                    if !matches!(&transform.kind, ExprKind::Var(_))
                        && !matches!(
                            &transform.kind,
                            ExprKind::App(function, _)
                                if matches!(&function.kind, ExprKind::Var(_))
                        ) =>
                {
                    // Replay identity is only exact for a statically named pipe
                    // transform.  A computed callable can select a closure,
                    // constructor, rule value, or builtin only at runtime.
                    supported = false;
                }
                ExprKind::App(function, arguments) => {
                    if matches!(&function.kind, ExprKind::Var(_)) {
                        // Bare calls are resolved below by exact name and arity.
                    } else if let Some(key) =
                        self.explore_scoped_member_call_key(function, arguments.len())
                    {
                        scoped_calls.insert(key);
                    } else {
                        // Qualified modules, ordinary methods, and computed
                        // receivers need a different owner-aware purity model.
                        supported = false;
                    }
                }
                _ => {}
            },
            AstChild::Stmt(statement) => {
                // Interpreter blocks hoist static declarations before any
                // expression runs.  The replay catalog is query-wide rather
                // than block-local, so only the two ordinary lexical forms
                // have an exact identity and source-order model here.
                if !matches!(statement, Stmt::Bind(..) | Stmt::Expr(_)) {
                    supported = false;
                }
            }
        });
        for call in collect_scoped_runtime_calls(expr, bound) {
            if call.lexically_bound {
                if !callable_bound.contains(&call.name) {
                    supported = false;
                }
                // Arrow-typed callable parameters are evaluated by the exact
                // interpreter. The active exploration effect guard remains
                // authoritative for the concrete closure supplied by a call.
                continue;
            }
            let canonical = builtin_canonical(&call.name);
            if ((impure_names.contains(&call.name) || impure_names.contains(canonical))
                && !matches!(canonical, "last" | "take" | "collect"))
                || effect_operations.contains(&call.name)
                || matches!(canonical, "findall" | "search")
            {
                supported = false;
            }
            calls.insert((call.name, call.effective_arity));
        }
        (supported, calls, scoped_calls)
    }

    fn explore_call_has_supported_definition(&self, key: &(String, usize)) -> bool {
        let (name, arity) = key;
        if matches!(
            name.as_str(),
            "values" | NAMED_ARG_MARKER | PATHOF_MARKER | REFOF_MARKER
        ) {
            return true;
        }
        if self.explore_callable_expressions_by_arity.contains_key(key)
            || self.explore_declared_effect_callables.contains(key)
        {
            return true;
        }
        let canonical = builtin_canonical(name);
        if self
            .builtins
            .get(canonical)
            .is_some_and(|expected| expected == arity)
        {
            return true;
        }
        self.constructors
            .get(name)
            .is_some_and(|(_, fields)| fields == arity)
    }

    fn explore_expression_dependencies_are_pure_inner(
        &self,
        expr: &Expr,
        bound: &BTreeSet<String>,
        callable_bound: &BTreeSet<String>,
        active_scope: Option<&str>,
        visiting: &mut BTreeSet<ExplorePurityNode>,
        memo: &mut BTreeMap<ExplorePurityNode, bool>,
    ) -> bool {
        let (supported, calls, scoped_calls) =
            self.explore_expression_capabilities(expr, bound, callable_bound);
        if !supported {
            return false;
        }
        for key in scoped_calls {
            if !self.explore_purity_node_is_pure_inner(
                &ExplorePurityNode::ScopedRule(key),
                visiting,
                memo,
            ) {
                return false;
            }
        }
        for call in calls {
            let scoped_key = active_scope.map(|scope| RuleDispatchKey {
                scope: Some(scope.to_string()),
                name: call.0.clone(),
                arity: call.1,
            });
            if let Some(scoped_key) = scoped_key.filter(|key| self.rule_dispatch_keys.contains(key))
            {
                if !self
                    .explore_scoped_callable_expressions
                    .contains_key(&scoped_key)
                {
                    return false;
                }
                if !self.explore_purity_node_is_pure_inner(
                    &ExplorePurityNode::ScopedRule(scoped_key),
                    visiting,
                    memo,
                ) {
                    return false;
                }
                continue;
            }
            if active_scope.is_some_and(|scope| {
                self.rule_scope_value_methods
                    .get(scope)
                    .and_then(|methods| methods.get(&call.0))
                    .is_some_and(|arity| *arity == call.1)
            }) {
                return false;
            }
            if !self.explore_call_has_supported_definition(&call) {
                return false;
            }
            if (self
                .explore_callable_expressions_by_arity
                .contains_key(&call)
                || self.explore_declared_effect_callables.contains(&call))
                && !self.explore_purity_node_is_pure_inner(
                    &ExplorePurityNode::Callable {
                        name: call.0,
                        arity: call.1,
                        active_scope: active_scope.map(str::to_string),
                    },
                    visiting,
                    memo,
                )
            {
                return false;
            }
        }

        let mut uses = FreeSymbolUses::default();
        collect_true_free_symbol_uses(expr, &mut uses, bound, &BTreeMap::new());
        for name in uses.values {
            if (self
                .explore_top_level_binding_initializers
                .contains_key(&name)
                || self.explore_unsupported_top_level_bindings.contains(&name))
                && !self.explore_purity_node_is_pure_inner(
                    &ExplorePurityNode::TopLevelBinding(name),
                    visiting,
                    memo,
                )
            {
                return false;
            }
        }
        true
    }

    fn explore_purity_node_is_pure_inner(
        &self,
        node: &ExplorePurityNode,
        visiting: &mut BTreeSet<ExplorePurityNode>,
        memo: &mut BTreeMap<ExplorePurityNode, bool>,
    ) -> bool {
        if let Some(pure) = memo.get(node) {
            return *pure;
        }
        if !visiting.insert(node.clone()) {
            // Purity is coinductive over the callable/value dependency graph:
            // recursion is not itself an effect. Every body on the cycle is
            // still inspected by its first visit, while exact execution fuel
            // reports a non-terminating concrete case as Partial rather than
            // allowing it to contribute to a Complete result.
            return true;
        }

        let (expressions, intrinsically_unsupported, definition_is_known, active_scope) = match node
        {
            ExplorePurityNode::Callable {
                name,
                arity,
                active_scope,
            } => {
                let key = (name.clone(), *arity);
                let definition_is_known = self
                    .explore_callable_expressions_by_arity
                    .contains_key(&key)
                    || self.explore_declared_effect_callables.contains(&key);
                let expressions = self
                    .explore_callable_expressions_by_arity
                    .get(&key)
                    .cloned()
                    .unwrap_or_default()
                    .into_iter()
                    .map(|expression| ExplorePurityExpression {
                        expression,
                        bound: self
                            .function_params_by_arity
                            .get(&key)
                            .into_iter()
                            .flatten()
                            .cloned()
                            .collect(),
                        callable_bound: self.explore_callable_bound_names(&key),
                    })
                    .collect();
                (
                    expressions,
                    self.explore_declared_effect_callables.contains(&key),
                    definition_is_known,
                    active_scope.clone(),
                )
            }
            ExplorePurityNode::ScopedRule(key) => (
                self.explore_scoped_callable_expressions
                    .get(key)
                    .cloned()
                    .unwrap_or_default(),
                false,
                self.explore_scoped_callable_expressions.contains_key(key),
                key.scope.clone(),
            ),
            ExplorePurityNode::TopLevelBinding(name) => {
                let expressions = self
                    .explore_top_level_binding_initializers
                    .get(name)
                    .cloned()
                    .unwrap_or_default()
                    .into_iter()
                    .map(|expression| ExplorePurityExpression {
                        expression,
                        bound: BTreeSet::new(),
                        callable_bound: BTreeSet::new(),
                    })
                    .collect();
                (
                    expressions,
                    self.explore_unsupported_top_level_bindings.contains(name),
                    self.explore_top_level_binding_initializers
                        .contains_key(name),
                    None,
                )
            }
        };

        let pure = !intrinsically_unsupported
            && definition_is_known
            && expressions.iter().all(|record| {
                self.explore_expression_dependencies_are_pure_inner(
                    &record.expression,
                    &record.bound,
                    &record.callable_bound,
                    active_scope.as_deref(),
                    visiting,
                    memo,
                )
            });
        visiting.remove(node);
        memo.insert(node.clone(), pure);
        pure
    }

    fn explore_callable_is_pure(&self, key: &(String, usize)) -> bool {
        self.explore_purity_node_is_pure_inner(
            &ExplorePurityNode::Callable {
                name: key.0.clone(),
                arity: key.1,
                active_scope: None,
            },
            &mut BTreeSet::new(),
            &mut BTreeMap::new(),
        )
    }

    /// Builtins admitted by the observer-totality proof. This is deliberately
    /// a closed allow-list: adding a builtin to the language cannot silently
    /// make a previously sealed observer partial. Each admitted operation
    /// returns a value for every runtime value shape and has no index, parsing,
    /// arithmetic-overflow, callback, stream, or external-runtime edge.
    fn explore_observation_builtin_is_total(name: &str) -> bool {
        matches!(
            builtin_canonical(name),
            "show"
                | "show_int"
                | "show_float"
                | "rust_debug"
                | "length"
                | "not"
                | "contains"
                | "starts_with"
                | "ends_with"
                | "index_of"
                | "string_length"
                | "is_some"
                | "is_none"
        )
    }

    fn explore_observation_expression_is_total_inner(
        &self,
        expression: &Expr,
        bound: &BTreeSet<String>,
        visiting: &mut BTreeSet<ExplorePurityNode>,
        memo: &mut BTreeMap<ExplorePurityNode, bool>,
    ) -> bool {
        let mut locally_total = true;
        walk_ast_expr(expression, &mut |child| match child {
            AstChild::Expr(expression) => match &expression.kind {
                // These forms either contain an intrinsically partial runtime
                // edge or require a separate proof that v1 does not possess.
                ExprKind::Index(_, _)
                | ExprKind::Try(_)
                | ExprKind::Effect(_, _)
                | ExprKind::Handle { .. }
                | ExprKind::Lambda(_, _)
                | ExprKind::Match(_, _)
                | ExprKind::Conjunction(_)
                | ExprKind::Disjunction(_)
                | ExprKind::Pipe(_, _) => locally_total = false,
                // Exact exploration reports integer overflow and zero/overflow
                // division as partial. Without a range proof, arithmetic cannot
                // be sealed as total merely because it type-checks.
                ExprKind::BinOp(operator, _, _)
                    if !matches!(
                        operator.as_str(),
                        "==" | "!=" | "<" | ">" | "<=" | ">=" | "&&" | "||"
                    ) =>
                {
                    locally_total = false
                }
                ExprKind::UnOp(operator, _) if !matches!(operator.as_str(), "!" | "&" | "&mut") => {
                    locally_total = false
                }
                ExprKind::App(function, _) if !matches!(&function.kind, ExprKind::Var(_)) => {
                    locally_total = false
                }
                _ => {}
            },
            AstChild::Stmt(statement) => {
                // A block-local value binding is total exactly when its walked
                // initializer is total. Destructuring and executable statement
                // forms need separate failure/termination proofs.
                if !matches!(statement, Stmt::Bind(Pat::Var(_), _, _) | Stmt::Expr(_)) {
                    locally_total = false;
                }
            }
        });
        if !locally_total {
            return false;
        }

        let callable_bound = BTreeSet::new();
        let (supported, calls, scoped_calls) =
            self.explore_expression_capabilities(expression, bound, &callable_bound);
        if !supported || !scoped_calls.is_empty() {
            return false;
        }
        // A lexically supplied closure is pure only under a concrete runtime
        // guard; that is not a static termination/totality proof.
        if collect_scoped_runtime_calls(expression, bound)
            .iter()
            .any(|call| call.lexically_bound)
        {
            return false;
        }

        for call in calls {
            // A root value binding is consulted before global callable
            // registries at runtime. Its initializer may be a dynamically
            // selected closure, so a same-named constructor/function/builtin
            // cannot provide the totality proof for this call.
            if self
                .explore_top_level_binding_initializers
                .contains_key(&call.0)
                || self
                    .explore_unsupported_top_level_bindings
                    .contains(&call.0)
            {
                return false;
            }
            if self
                .constructors
                .get(&call.0)
                .is_some_and(|(_, arity)| *arity == call.1)
            {
                continue;
            }
            let dependency = ExplorePurityNode::Callable {
                name: call.0.clone(),
                arity: call.1,
                active_scope: None,
            };
            if self
                .explore_function_definitions_by_arity
                .contains_key(&(call.0.clone(), call.1))
            {
                if !self.explore_observation_node_is_total_inner(&dependency, visiting, memo) {
                    return false;
                }
                continue;
            }
            if self
                .explore_rules_by_arity
                .contains_key(&(call.0.clone(), call.1))
            {
                if !self.explore_observation_node_is_total_inner(&dependency, visiting, memo) {
                    return false;
                }
                continue;
            }
            let canonical = builtin_canonical(&call.0);
            if self
                .builtins
                .get(canonical)
                .is_some_and(|arity| *arity == call.1)
            {
                if !Self::explore_observation_builtin_is_total(canonical) {
                    return false;
                }
                continue;
            }
            // Scoped members, unknown runtime callables, and special compiler
            // markers have no total dispatch proof in v1.
            return false;
        }

        let mut uses = FreeSymbolUses::default();
        collect_true_free_symbol_uses(expression, &mut uses, bound, &BTreeMap::new());
        for name in uses.values {
            if self
                .explore_top_level_binding_initializers
                .contains_key(&name)
                || self.explore_unsupported_top_level_bindings.contains(&name)
            {
                if !self.explore_observation_node_is_total_inner(
                    &ExplorePurityNode::TopLevelBinding(name),
                    visiting,
                    memo,
                ) {
                    return false;
                }
                continue;
            }
            if self
                .constructors
                .get(&name)
                .is_some_and(|(_, arity)| *arity == 0)
            {
                continue;
            }
            // A first-class function, builtin, rule, module member, or unknown
            // value has no sealed total-value identity in the observation IR.
            return false;
        }
        true
    }

    fn explore_observation_rule_is_total_inner(
        &self,
        key: &(String, usize),
        visiting: &mut BTreeSet<ExplorePurityNode>,
        memo: &mut BTreeMap<ExplorePurityNode, bool>,
    ) -> bool {
        if self.rule_dispatch_has_opaque_runtime_graph
            || self
                .rule_dispatch_return_issues
                .contains_key(&RuleDispatchKey {
                    scope: None,
                    name: key.0.clone(),
                    arity: key.1,
                })
        {
            return false;
        }
        let Some(rules) = self.explore_rules_by_arity.get(key) else {
            return false;
        };
        let dispatch_key = RuleDispatchKey {
            scope: None,
            name: key.0.clone(),
            arity: key.1,
        };
        if !self.rule_dispatch_return_types.contains_key(&dispatch_key) {
            return false;
        }
        // Dispatch tiers may select an earlier exception/default/clause, but
        // every candidate expression is checked below. If none selects, an
        // unconditional irrefutable candidate must eventually yield a value;
        // an independently proven Bool family instead has the checked False
        // miss value.
        let dispatch_is_total = self
            .rule_dispatch_boolean_miss_safe_keys
            .contains(&dispatch_key)
            || rules.iter().any(|rule| {
                rule_head_is_irrefutable(rule)
                    && match rule {
                        Rule::Exception {
                            condition: None, ..
                        }
                        | Rule::Default {
                            condition: None, ..
                        } => true,
                        Rule::Clause { body, .. } => body.is_some(),
                        _ => false,
                    }
            });
        if !dispatch_is_total {
            return false;
        }

        for rule in rules {
            let Some(head) = rule.head() else {
                return false;
            };
            let mut binding_counts = BTreeMap::new();
            if let ExprKind::App(_, arguments) = &head.kind {
                for argument in arguments {
                    collect_rule_head_binding_counts(argument, &mut binding_counts);
                }
            }
            let bound = binding_counts.into_keys().collect::<BTreeSet<_>>();
            match rule {
                Rule::Clause {
                    body: Some(value), ..
                } => {
                    if !self.explore_observation_expression_is_total_inner(
                        value, &bound, visiting, memo,
                    ) {
                        return false;
                    }
                }
                Rule::Clause { body: None, .. } => {}
                Rule::Default {
                    value, condition, ..
                }
                | Rule::Exception {
                    value, condition, ..
                } => {
                    if !self.explore_observation_expression_is_total_inner(
                        value, &bound, visiting, memo,
                    ) || condition.as_ref().is_some_and(|condition| {
                        !self.explore_observation_expression_is_total_inner(
                            condition, &bound, visiting, memo,
                        )
                    }) {
                        return false;
                    }
                }
                Rule::ReactiveScope { .. } => return false,
            }
        }
        true
    }

    fn explore_observation_node_is_total_inner(
        &self,
        node: &ExplorePurityNode,
        visiting: &mut BTreeSet<ExplorePurityNode>,
        memo: &mut BTreeMap<ExplorePurityNode, bool>,
    ) -> bool {
        if let Some(total) = memo.get(node) {
            return *total;
        }
        if !visiting.insert(node.clone()) {
            return false;
        }
        let total = match node {
            ExplorePurityNode::Callable {
                name,
                arity,
                active_scope: None,
            } => {
                let key = (name.clone(), *arity);
                let definitions = self.explore_function_definitions_by_arity.get(&key);
                if let Some(definitions) = definitions {
                    definitions.len() == 1
                        && !self.explore_declared_effect_callables.contains(&key)
                        && self.explore_observation_expression_is_total_inner(
                            &definitions[0].2,
                            &definitions[0]
                                .0
                                .iter()
                                .map(|parameter| parameter.name.clone())
                                .collect(),
                            visiting,
                            memo,
                        )
                } else {
                    self.explore_observation_rule_is_total_inner(&key, visiting, memo)
                }
            }
            ExplorePurityNode::TopLevelBinding(name) => {
                let initializers = self.explore_top_level_binding_initializers.get(name);
                !self.explore_unsupported_top_level_bindings.contains(name)
                    && initializers.is_some_and(|initializers| {
                        initializers.len() == 1
                            && self.explore_observation_expression_is_total_inner(
                                &initializers[0],
                                &BTreeSet::new(),
                                visiting,
                                memo,
                            )
                    })
            }
            ExplorePurityNode::Callable {
                active_scope: Some(_),
                ..
            }
            | ExplorePurityNode::ScopedRule(_) => false,
        };
        visiting.remove(node);
        memo.insert(node.clone(), total);
        total
    }

    /// Conservative totality proof for an endpoint-observation template.
    /// Mechanism replay cannot turn a partial observer into evidence, so every
    /// reachable operation and value dependency must close under the proof.
    #[allow(dead_code)]
    fn explore_observation_callable_is_total(&self, key: &(String, usize)) -> bool {
        self.explore_observation_node_is_total_inner(
            &ExplorePurityNode::Callable {
                name: key.0.clone(),
                arity: key.1,
                active_scope: None,
            },
            &mut BTreeSet::new(),
            &mut BTreeMap::new(),
        )
    }

    fn explore_expression_is_pure(&self, expr: &Expr, bound: &BTreeSet<String>) -> bool {
        self.explore_expression_dependencies_are_pure_inner(
            expr,
            bound,
            &BTreeSet::new(),
            None,
            &mut BTreeSet::new(),
            &mut BTreeMap::new(),
        )
    }

    fn explore_exact_call_type_issue(&self, name: &str, arity: usize) -> Option<String> {
        let key = (name.to_string(), arity);
        if self.rule_arities.contains(&key) {
            if let Some(issue) = self.explore_rule_return_issues.get(&key) {
                return Some(issue.clone());
            }
            if !self.explore_rule_return_types_by_arity.contains_key(&key) {
                return Some(format!(
                    "cannot resolve the exact result type of exploration rule `{}({} arguments)`",
                    name, arity
                ));
            }
        } else if self
            .explore_callable_expressions_by_arity
            .contains_key(&key)
        {
            if let Some(issue) = self.explore_function_return_issues.get(&key) {
                return Some(issue.clone());
            }
            if !self
                .explore_function_return_types_by_arity
                .contains_key(&key)
            {
                return Some(format!(
                    "cannot resolve the exact result type of exploration helper `{}({} arguments)`",
                    name, arity
                ));
            }
        }
        None
    }

    fn explore_operator_issues_with_locals(
        &self,
        expr: &Expr,
        locals: &BTreeMap<String, String>,
    ) -> Vec<String> {
        let mut issues = Vec::new();
        walk_ast_expr(expr, &mut |child| {
            let AstChild::Expr(expression) = child else {
                return;
            };
            let inferred = |operand: &Expr| self.infer_expr_type_name_with_locals(operand, locals);
            match &expression.kind {
                ExprKind::App(function, arguments) => {
                    if let ExprKind::Var(name) = &function.kind {
                        if let Some(issue) =
                            self.explore_exact_call_type_issue(name, arguments.len())
                        {
                            issues.push(issue);
                        }
                    }
                }
                ExprKind::BinOp(operator, left, right) if operator == "&&" || operator == "||" => {
                    for operand in [left.as_ref(), right.as_ref()] {
                        if inferred(operand).as_deref().is_some_and(|ty| ty != "Bool") {
                            issues.push(format!(
                                "exploration logical operator `{}` requires `Bool` operands",
                                operator
                            ));
                        }
                    }
                }
                ExprKind::BinOp(operator, left, right)
                    if matches!(operator.as_str(), "==" | "!=" | "<" | "<=" | ">" | ">=") =>
                {
                    if let (Some(left), Some(right)) = (inferred(left), inferred(right)) {
                        let compatible = if matches!(operator.as_str(), "==" | "!=") {
                            Self::merge_inferred_type_names(&left, &right).is_some()
                        } else {
                            left == right
                        };
                        if !compatible {
                            issues.push(format!(
                                "exploration comparison `{}` requires compatible operands, but found `{}` and `{}`",
                                operator, left, right
                            ));
                        }
                    }
                }
                ExprKind::BinOp(operator, left, right)
                    if matches!(operator.as_str(), "+" | "-" | "*" | "/" | "%") =>
                {
                    if let (Some(left), Some(right)) = (inferred(left), inferred(right)) {
                        let valid = left == right
                            && (left == "Int"
                                || (left == "Float" && operator != "%")
                                || (left == "String" && operator == "+"));
                        if !valid {
                            issues.push(format!(
                                "exploration arithmetic operator `{}` cannot combine `{}` and `{}`",
                                operator, left, right
                            ));
                        }
                    }
                }
                ExprKind::UnOp(operator, operand) if operator == "!" => {
                    if inferred(operand).as_deref().is_some_and(|ty| ty != "Bool") {
                        issues.push(
                            "exploration logical negation requires a `Bool` operand".to_string(),
                        );
                    }
                }
                ExprKind::UnOp(operator, operand) if operator == "+" || operator == "-" => {
                    if inferred(operand)
                        .as_deref()
                        .is_some_and(|ty| ty != "Int" && ty != "Float")
                    {
                        issues.push(format!(
                            "exploration unary operator `{}` requires an `Int` or `Float` operand",
                            operator
                        ));
                    }
                }
                ExprKind::Conjunction(items) | ExprKind::Disjunction(items) => {
                    if items
                        .iter()
                        .any(|item| inferred(item).as_deref().is_some_and(|ty| ty != "Bool"))
                    {
                        issues.push(
                            "exploration logical goals must each have type `Bool`".to_string(),
                        );
                    }
                }
                _ => {}
            }
        });
        issues.sort();
        issues.dedup();
        issues
    }

    fn explore_key_ty_supported(&self, ty: &Ty) -> bool {
        self.explore_key_ty_supported_inner(ty, &mut BTreeSet::new())
    }

    fn explore_key_ty_supported_inner(&self, ty: &Ty, visiting: &mut BTreeSet<String>) -> bool {
        match ty {
            Ty::Name(name) => {
                if matches!(
                    name.as_str(),
                    "Float" | "Stream" | "Subject" | "Db" | "TypeDef" | "ProgramReference"
                ) || self.rule_scope_methods.contains_key(name)
                    || self.rule_scope_value_methods.contains_key(name)
                    || self.effect_ops.contains_key(name)
                {
                    return false;
                }
                if !visiting.insert(name.clone()) {
                    return false;
                }
                let fields_supported = self.type_field_tys.get(name).is_none_or(|fields| {
                    fields
                        .values()
                        .all(|field| self.explore_key_ty_supported_inner(field, visiting))
                });
                let variants_supported = self.type_variants.get(name).is_none_or(|variants| {
                    variants.iter().all(|variant| {
                        self.type_field_tys.get(variant).is_none_or(|fields| {
                            fields
                                .values()
                                .all(|field| self.explore_key_ty_supported_inner(field, visiting))
                        })
                    })
                });
                visiting.remove(name);
                fields_supported && variants_supported
            }
            Ty::App(constructor, arguments) => {
                !matches!(
                    type_name(constructor),
                    Some("Stream" | "Subject" | "Db" | "Map" | "Set")
                ) && self.explore_key_ty_supported_inner(constructor, visiting)
                    && arguments
                        .iter()
                        .all(|argument| self.explore_key_ty_supported_inner(argument, visiting))
            }
            Ty::Optional(inner) => self.explore_key_ty_supported_inner(inner, visiting),
            Ty::Unit => true,
            Ty::Arrow(_, _)
            | Ty::Ref(_)
            | Ty::MutRef(_)
            | Ty::Shared(_)
            | Ty::Var(_)
            | Ty::Hole => false,
        }
    }

    fn check_explore_expression(&mut self, expr: &Expr) {
        if let ExprKind::App(function, arguments) = &expr.kind {
            if matches!(&function.kind, ExprKind::Var(name) if name == "values") {
                if arguments.len() != 1 {
                    self.error_at_expr(
                        expr,
                        "exploration `values(Type)` expects exactly one declared type".to_string(),
                    );
                } else if Self::explore_ty_from_expr(&arguments[0]).is_none() {
                    self.error_at_expr(
                        &arguments[0],
                        "exploration `values(Type)` expects a declared type expression".to_string(),
                    );
                }
                // Type-shaped arguments are elaborated by the exact finite-type
                // catalog; they are not runtime calls and must not enter the
                // ordinary expression/purity checker.
                return;
            }
        }
        let bound = self.scopes.last().cloned().unwrap_or_default();
        if !self.explore_expression_is_pure(expr, &bound) {
            self.error_at_expr(
                expr,
                "exploration expressions must use only pure, exploration-supported operations; effects, effectful helpers and `?` propagation are not supported"
                    .to_string(),
            );
        }
        for issue in self.explore_operator_issues_with_locals(expr, &BTreeMap::new()) {
            self.error_at_expr(expr, issue);
        }
        self.check_expr(expr, None);
    }

    fn check_explore_available_references(
        &mut self,
        expr: &Expr,
        reserved: &BTreeSet<String>,
        available: &BTreeSet<String>,
    ) {
        let mut uses = FreeSymbolUses::default();
        collect_true_free_symbol_uses(expr, &mut uses, &BTreeSet::new(), &BTreeMap::new());
        let referenced = uses
            .values
            .into_iter()
            .chain(uses.calls)
            .collect::<BTreeSet<_>>();
        for name in referenced {
            if reserved.contains(&name) && !available.contains(&name) {
                self.error_at_expr(
                    expr,
                    format!(
                        "exploration name `{}` is referenced before its bound or shown value is available",
                        name
                    ),
                );
            }
        }
    }

    fn check_explore_role_environment(&mut self, expr: &Expr, allowed: &[&str], environment: &str) {
        let mut uses = FreeSymbolUses::default();
        collect_true_free_symbol_uses(expr, &mut uses, &BTreeSet::new(), &BTreeMap::new());
        let allowed = allowed.iter().copied().collect::<BTreeSet<_>>();
        for role in ["before", "after", "context"] {
            if (uses.values.contains(role) || uses.calls.contains(role)) && !allowed.contains(role)
            {
                self.error_at_expr(
                    expr,
                    format!(
                        "exploration {environment} cannot reference `{role}` in this transition environment"
                    ),
                );
            }
        }
    }

    fn check_explore_finite_domain(
        &mut self,
        label: &str,
        domain: &Expr,
        available_names: &BTreeSet<String>,
    ) -> (Ty, TypedExploreDomain) {
        let value_ty = self.explore_domain_item_ty(domain).unwrap_or_else(|| {
            self.error_at_expr(
                domain,
                format!("cannot determine the finite item type of exploration domain `{label}`"),
            );
            Ty::Hole
        });
        let typed = self.check_explore_domain_against(label, domain, &value_ty, available_names);
        (value_ty, typed)
    }

    fn explore_declared_product_fields(
        &mut self,
        ty: &Ty,
        role: &str,
        span: Span,
        allow_unit: bool,
    ) -> Option<Vec<(String, Ty)>> {
        if matches!(ty, Ty::Unit) {
            if allow_unit {
                return Some(Vec::new());
            }
            self.error_at_span(
                span,
                format!("exploration {role} must be a declared named-field product, not `()`"),
            );
            return None;
        }
        let Ty::Name(type_name) = ty else {
            self.error_at_span(
                span,
                format!(
                    "exploration {role} type `{ty}` must name one declared, non-generic product type"
                ),
            );
            return None;
        };
        let constructors = self
            .constructor_signatures
            .iter()
            .flat_map(|(constructor_name, signatures)| {
                signatures
                    .iter()
                    .filter(|signature| signature.parent == *type_name)
                    .map(move |signature| (constructor_name.clone(), signature.clone()))
            })
            .collect::<Vec<_>>();
        if constructors.len() != 1 {
            self.error_at_span(
                span,
                format!(
                    "exploration {role} type `{type_name}` must have exactly one constructor, found {}",
                    constructors.len()
                ),
            );
            return None;
        }
        let (constructor_name, signature) = &constructors[0];
        if constructor_name != type_name {
            self.error_at_span(
                span,
                format!(
                    "exploration {role} type `{type_name}` must use the same-named product constructor `{type_name}(...)`, found `{constructor_name}(...)`"
                ),
            );
            return None;
        }
        if signature.positional || signature.fields.is_empty() {
            self.error_at_span(
                span,
                format!(
                    "exploration {role} type `{type_name}` must be a nonempty named-field product"
                ),
            );
            return None;
        }
        if signature.field_tys.len() != signature.fields.len() {
            self.error_at_span(
                span,
                format!(
                    "cannot resolve the complete named-field schema of exploration {role} type `{type_name}`"
                ),
            );
            return None;
        }
        let mut fields = Vec::with_capacity(signature.fields.len());
        for (field, field_ty) in signature.fields.iter().zip(&signature.field_tys) {
            let Some(field_ty) = field_ty
                .as_deref()
                .and_then(|field_ty| parse_type_annotation(field_ty).ok())
            else {
                self.error_at_span(
                    span,
                    format!(
                        "cannot resolve type of exploration {role} field `{type_name}.{field}`"
                    ),
                );
                return None;
            };
            fields.push((field.clone(), field_ty));
        }
        Some(fields)
    }

    fn check_explore_domain_against(
        &mut self,
        label: &str,
        domain: &Expr,
        expected: &Ty,
        available_names: &BTreeSet<String>,
    ) -> TypedExploreDomain {
        self.check_explore_expression(domain);
        if let Some(actual) = self.explore_domain_item_ty(domain) {
            if !Self::explore_tys_equivalent(&actual, expected) {
                self.error_at_expr(
                    domain,
                    format!(
                        "exploration domain `{label}` contains `{actual}` values but the field expects `{expected}`"
                    ),
                );
            }
        } else if !matches!(&domain.kind, ExprKind::List(items) if items.is_empty()) {
            self.error_at_expr(
                domain,
                format!("cannot determine the finite item type of exploration domain `{label}`"),
            );
        }
        match &domain.kind {
            ExprKind::App(function, arguments)
                if matches!(&function.kind, ExprKind::Var(name) if name == "range")
                    && arguments.len() == 2 =>
            {
                if available_names.contains("range")
                    || self.explore_contextual_intrinsic_is_shadowed("range", 2)
                {
                    self.error_at_expr(
                        domain,
                        "exploration `range(start, end)` is shadowed by an available query value or program declaration; rename that declaration so the bounded range is unambiguous"
                            .to_string(),
                    );
                }
                for endpoint in arguments {
                    if self
                        .inferred_explore_ty(endpoint)
                        .as_ref()
                        .map(ToString::to_string)
                        .as_deref()
                        != Some("Int")
                    {
                        self.error_at_expr(
                            endpoint,
                            "exploration range endpoints must have type `Int`".to_string(),
                        );
                    }
                }
                TypedExploreDomain::Range {
                    start: arguments[0].clone(),
                    end_exclusive: arguments[1].clone(),
                }
            }
            ExprKind::App(function, arguments)
                if matches!(&function.kind, ExprKind::Var(name) if name == "values")
                    && arguments.len() == 1 =>
            {
                if available_names.contains("values")
                    || self.explore_contextual_intrinsic_is_shadowed("values", 1)
                {
                    self.error_at_expr(
                        domain,
                        "exploration `values(Type)` is shadowed by an available query value or program declaration; rename that declaration so finite-type enumeration is unambiguous"
                            .to_string(),
                    );
                }
                let ty = Self::explore_ty_from_expr(&arguments[0]).unwrap_or_else(|| {
                    self.error_at_expr(
                        &arguments[0],
                        "`values(...)` expects a declared type, such as `values(Status)` or `values(Option(Status))`"
                            .to_string(),
                    );
                    Ty::Hole
                });
                TypedExploreDomain::Values { ty }
            }
            _ => {
                let collection_ty = self.inferred_explore_ty(domain).unwrap_or_else(|| {
                    Ty::App(
                        Box::new(Ty::Name("List".to_string())),
                        vec![expected.clone()],
                    )
                });
                TypedExploreDomain::FiniteExpr {
                    expression: domain.clone(),
                    collection_ty,
                    element_ty: expected.clone(),
                }
            }
        }
    }

    fn check_explore_bool(
        &mut self,
        expression: &Expr,
        label: &str,
        reserved_names: &BTreeSet<String>,
        available_names: &BTreeSet<String>,
        allowed_roles: &[&str],
    ) {
        self.check_explore_available_references(expression, reserved_names, available_names);
        self.check_explore_role_environment(expression, allowed_roles, label);
        self.check_explore_expression(expression);
        let actual = self.inferred_explore_ty(expression).unwrap_or(Ty::Hole);
        if actual.to_string() != "Bool" {
            self.error_at_expr(
                expression,
                format!("exploration {label} must have type Bool, found {actual}"),
            );
        }
    }

    fn check_explore_result_field(
        &mut self,
        field: &ExploreResultField,
        label: &str,
        reserved_names: &BTreeSet<String>,
        available_names: &BTreeSet<String>,
        require_key_type: bool,
    ) -> TypedExploreResultField {
        self.check_explore_available_references(&field.value, reserved_names, available_names);
        self.check_explore_role_environment(&field.value, &["before", "after", "context"], label);
        self.check_explore_expression(&field.value);
        let ty = self.inferred_explore_ty(&field.value).unwrap_or_else(|| {
            self.error_at_expr(
                &field.value,
                format!(
                    "cannot infer the type of exploration {label} {}",
                    field.name
                ),
            );
            Ty::Hole
        });
        if require_key_type && !self.explore_key_ty_supported(&ty) {
            self.error_at_expr(
                &field.value,
                format!(
                    "exploration {label} {} has unsupported key type {ty}",
                    field.name
                ),
            );
        }
        TypedExploreResultField {
            name: field.name.clone(),
            value: field.value.clone(),
            ty,
            span: field.span,
        }
    }

    fn check_explore_aggregate_field(
        &mut self,
        field: &ExploreAggregateField,
        reserved_names: &BTreeSet<String>,
        available_names: &BTreeSet<String>,
    ) -> TypedExploreAggregateField {
        match &field.reducer {
            ExploreAggregateReducer::CountDistinct { value } => {
                self.check_explore_available_references(value, reserved_names, available_names);
                self.check_explore_role_environment(
                    value,
                    &["before", "after", "context"],
                    "count_distinct aggregate",
                );
                self.check_explore_expression(value);
                let value_ty = self.inferred_explore_ty(value).unwrap_or_else(|| {
                    self.error_at_expr(
                        value,
                        format!(
                            "cannot infer the key type of exploration aggregate {}",
                            field.name
                        ),
                    );
                    Ty::Hole
                });
                if !self.explore_key_ty_supported(&value_ty) {
                    self.error_at_expr(
                        value,
                        format!(
                            "exploration count_distinct aggregate {} has unsupported key type {value_ty}",
                            field.name
                        ),
                    );
                }
                TypedExploreAggregateField {
                    name: field.name.clone(),
                    reducer: TypedExploreAggregateReducer::CountDistinct {
                        value: value.clone(),
                        value_ty,
                    },
                    ty: Ty::Name("Int".to_string()),
                    span: field.span,
                }
            }
        }
    }

    fn explore_starter_value_view_is_compatible(
        view: &TypedExploreResultView,
        context_ty: &Ty,
        before_ty: &Ty,
        after_ty: &Ty,
    ) -> bool {
        if !matches!(&view.input, TypedExploreResultInput::Selected)
            || !matches!(&view.grain, TypedExploreResultGrain::EachCase { .. })
            || !view.aggregates.is_empty()
            || view.having.is_some()
            || view.choose.is_some()
        {
            return false;
        }

        let mut roles = [false; 4];
        for field in &view.select {
            let ExprKind::Var(binding) = &field.value.kind else {
                continue;
            };
            let role = match binding.as_str() {
                "case_id" if matches!(&field.ty, Ty::Name(name) if name == "CaseId") => Some(0),
                "context" if Self::explore_tys_equivalent(&field.ty, context_ty) => Some(1),
                "before" if Self::explore_tys_equivalent(&field.ty, before_ty) => Some(2),
                "after" if Self::explore_tys_equivalent(&field.ty, after_ty) => Some(3),
                "case_id" | "context" | "before" | "after" => return false,
                _ => None,
            };
            if let Some(role) = role {
                if roles[role] {
                    return false;
                }
                roles[role] = true;
            }
        }
        roles.into_iter().all(|present| present)
    }

    fn check_explore_query(&mut self, query: &ExploreQuery, selectable: bool) {
        let diagnostic_start = self.diagnostics.len();
        self.checking_explore_query = true;
        self.push_context(format!("in exploration {}", query.name));

        if selectable && !self.exploration_names.insert(query.name.clone()) {
            self.error_at_span(
                query.span,
                format!("duplicate exploration name {}", query.name),
            );
        }

        let mut reserved_names = query
            .source
            .bindings
            .iter()
            .map(|binding| binding.name.clone())
            .collect::<BTreeSet<_>>();
        reserved_names.extend([
            "before".to_string(),
            "after".to_string(),
            "context".to_string(),
        ]);
        let before_positions = query
            .source
            .bindings
            .iter()
            .enumerate()
            .filter_map(|(index, binding)| (binding.name == "before").then_some(index))
            .collect::<Vec<_>>();
        let context_positions = query
            .source
            .bindings
            .iter()
            .enumerate()
            .filter_map(|(index, binding)| (binding.name == "context").then_some(index))
            .collect::<Vec<_>>();
        if before_positions.len() != 1 {
            self.error_at_span(
                query.source.span,
                "exploration source must bind exactly one before value",
            );
        }
        if context_positions.len() != 1 {
            self.error_at_span(
                query.source.span,
                "exploration source must bind exactly one context value",
            );
        }

        self.push_scope();
        let mut available_names = BTreeSet::new();
        let mut typed_bindings = Vec::with_capacity(query.source.bindings.len());
        for binding in &query.source.bindings {
            let (value_ty, kind) = match &binding.kind {
                ExploreSourceBindingKind::Singleton { value } => {
                    self.check_explore_available_references(
                        value,
                        &reserved_names,
                        &available_names,
                    );
                    self.check_explore_expression(value);
                    let value_ty = self.inferred_explore_ty(value).unwrap_or_else(|| {
                        self.error_at_expr(
                            value,
                            format!(
                                "cannot infer the type of exploration source binding {}",
                                binding.name
                            ),
                        );
                        Ty::Hole
                    });
                    (
                        value_ty,
                        TypedExploreSourceBindingKind::Singleton {
                            value: value.clone(),
                        },
                    )
                }
                ExploreSourceBindingKind::Finite { domain } => {
                    self.check_explore_available_references(
                        domain,
                        &reserved_names,
                        &available_names,
                    );
                    let (value_ty, domain) =
                        self.check_explore_finite_domain(&binding.name, domain, &available_names);
                    (value_ty, TypedExploreSourceBindingKind::Finite { domain })
                }
            };
            self.define_var(&binding.name);
            self.define_var_type(&binding.name, &value_ty);
            available_names.insert(binding.name.clone());
            typed_bindings.push(TypedExploreSourceBinding {
                name: binding.name.clone(),
                value_ty,
                kind,
                span: binding.span,
            });
        }

        let before_binding_index = before_positions.first().copied().unwrap_or(0);
        let context_binding_index = context_positions.first().copied().unwrap_or(0);
        let before_ty = typed_bindings
            .get(before_binding_index)
            .map(|binding| binding.value_ty.clone())
            .unwrap_or(Ty::Hole);
        let context_ty = typed_bindings
            .get(context_binding_index)
            .map(|binding| binding.value_ty.clone())
            .unwrap_or(Ty::Hole);

        self.pop_scope();
        self.push_scope();
        self.define_var("before");
        self.define_var_type("before", &before_ty);
        self.define_var("context");
        self.define_var_type("context", &context_ty);
        available_names = BTreeSet::from(["before".to_string(), "context".to_string()]);

        let (after_ty, typed_successor_kind) = match &query.successor.kind {
            ExploreSuccessorKind::Singleton { value } => {
                self.check_explore_available_references(value, &reserved_names, &available_names);
                self.check_explore_role_environment(
                    value,
                    &["before", "context"],
                    "successor relation",
                );
                self.check_explore_expression(value);
                let ty = self.inferred_explore_ty(value).unwrap_or_else(|| {
                    self.error_at_expr(
                        value,
                        "cannot infer exploration successor type".to_string(),
                    );
                    Ty::Hole
                });
                (
                    ty,
                    TypedExploreSuccessorKind::Singleton {
                        value: value.clone(),
                    },
                )
            }
            ExploreSuccessorKind::Finite { domain } => {
                self.check_explore_available_references(domain, &reserved_names, &available_names);
                self.check_explore_role_environment(
                    domain,
                    &["before", "context"],
                    "successor relation",
                );
                let (ty, domain) =
                    self.check_explore_finite_domain("after", domain, &available_names);
                (ty, TypedExploreSuccessorKind::Finite { domain })
            }
        };
        if !Self::explore_tys_equivalent(&before_ty, &after_ty) {
            self.error_at_span(
                query.successor.span,
                format!(
                    "exploration successor has type {after_ty}, but before has type {before_ty}"
                ),
            );
        }
        self.define_var("after");
        self.define_var_type("after", &after_ty);
        available_names.insert("after".to_string());

        let typed_admissions = query
            .admissions
            .iter()
            .map(|admission| {
                let allowed_roles: &[&str] = match admission.scope {
                    ExploreAdmissionScope::Before => &["before", "context"],
                    ExploreAdmissionScope::After => &["after", "context"],
                    ExploreAdmissionScope::Transition => &["before", "after", "context"],
                };
                self.check_explore_bool(
                    &admission.predicate,
                    "admission predicate",
                    &reserved_names,
                    &available_names,
                    allowed_roles,
                );
                TypedExploreAdmission {
                    scope: admission.scope,
                    predicate: admission.predicate.clone(),
                    span: admission.span,
                }
            })
            .collect::<Vec<_>>();

        let typed_selection = match &query.selection {
            ExploreSelection::All { span } => TypedExploreSelection::All { span: *span },
            ExploreSelection::Matches { predicate, span } => {
                self.check_explore_bool(
                    predicate,
                    "matches selection",
                    &reserved_names,
                    &available_names,
                    &["before", "after", "context"],
                );
                TypedExploreSelection::Matches {
                    predicate: predicate.clone(),
                    span: *span,
                }
            }
            ExploreSelection::Violations { predicate, span } => {
                self.check_explore_bool(
                    predicate,
                    "violations selection",
                    &reserved_names,
                    &available_names,
                    &["before", "after", "context"],
                );
                TypedExploreSelection::Violations {
                    predicate: predicate.clone(),
                    span: *span,
                }
            }
        };

        let mut typed_analysis = Vec::with_capacity(query.analysis.len());
        let mut analysis_by_name = BTreeMap::<String, usize>::new();
        for (node_index, node) in query.analysis.iter().enumerate() {
            if analysis_by_name.contains_key(node.name()) {
                self.error_at_span(
                    node.span(),
                    format!("duplicate exploration analysis declaration {}", node.name()),
                );
            }

            let typed_node = match node {
                ExploreAnalysisNode::Result(result) => {
                    let typed_input = match &result.input {
                        ExploreResultInput::Sources => TypedExploreResultInput::Sources,
                        ExploreResultInput::Selected => TypedExploreResultInput::Selected,
                        ExploreResultInput::MechanismIncidence { request_name } => {
                            let request_node_index = analysis_by_name
                                .get(request_name)
                                .copied()
                                .filter(|index| {
                                    matches!(
                                        typed_analysis.get(*index),
                                        Some(TypedExploreAnalysisNode::Mechanisms(_))
                                    )
                                })
                                .unwrap_or_else(|| {
                                    self.error_at_span(
                                        result.span,
                                        format!(
                                            "result view {} may reference only an earlier mechanism request; {} is unresolved, the wrong node kind, or declared later",
                                            result.name, request_name
                                        ),
                                    );
                                    usize::MAX
                                });
                            TypedExploreResultInput::MechanismIncidence {
                                request_name: request_name.clone(),
                                request_node_index,
                            }
                        }
                    };

                    match (&result.input, &result.grain) {
                        (
                            ExploreResultInput::Sources,
                            ExploreResultGrain::EachCase { .. }
                            | ExploreResultGrain::EachIncidence { .. },
                        ) => self.error_at_span(
                            result.grain.span(),
                            "source results require group all or group by",
                        ),
                        (
                            ExploreResultInput::Selected,
                            ExploreResultGrain::EachIncidence { .. },
                        ) => self.error_at_span(
                            result.grain.span(),
                            "each incidence requires a mechanism-incidence result input",
                        ),
                        (
                            ExploreResultInput::MechanismIncidence { .. },
                            ExploreResultGrain::EachCase { .. },
                        ) => self.error_at_span(
                            result.grain.span(),
                            "each case requires the selected-case result input",
                        ),
                        _ => {}
                    }
                    if !result.aggregates.is_empty()
                        && !matches!(
                            &result.grain,
                            ExploreResultGrain::GroupAll { .. }
                                | ExploreResultGrain::GroupBy { .. }
                        )
                    {
                        self.error_at_span(result.span, "aggregate requires group all or group by");
                    }

                    self.push_scope();
                    // A normalized source row contains exactly the canonical
                    // `(context, before)` pair. Auxiliary FROM bindings are
                    // construction lineage and may converge on that same row;
                    // `after` belongs to the successor relation. Neither is a
                    // value of the source input relation.
                    let mut result_available =
                        if matches!(&result.input, ExploreResultInput::Sources) {
                            BTreeSet::from(["before".to_string(), "context".to_string()])
                        } else {
                            available_names.clone()
                        };
                    let mut result_reserved_names = reserved_names.clone();
                    for (name, type_name) in explore_result_input_row_bindings(&result.input) {
                        let ty = Ty::Name((*type_name).to_string());
                        self.define_var(name);
                        self.define_var_type(name, &ty);
                        result_available.insert((*name).to_string());
                        result_reserved_names.insert((*name).to_string());
                    }

                    let group_fields = match &result.grain {
                        ExploreResultGrain::GroupBy { fields, .. } => fields.as_slice(),
                        ExploreResultGrain::EachCase { .. }
                        | ExploreResultGrain::EachIncidence { .. }
                        | ExploreResultGrain::GroupAll { .. } => &[],
                    };
                    let mut output_names = BTreeSet::new();
                    for name in group_fields
                        .iter()
                        .map(|field| &field.name)
                        .chain(result.measures.iter().map(|field| &field.name))
                        .chain(result.aggregates.iter().map(|field| &field.name))
                    {
                        if !output_names.insert(name.clone()) {
                            self.error_at_span(
                                result.span,
                                format!(
                                    "exploration result view {} declares output field {} more than once",
                                    result.name, name
                                ),
                            );
                        }
                        result_reserved_names.insert(name.clone());
                    }
                    let mut select_output_names = BTreeSet::new();
                    for field in &result.select {
                        if !select_output_names.insert(field.name.clone()) {
                            self.error_at_span(
                                field.span,
                                format!(
                                    "exploration result view {} selects output field {} more than once",
                                    result.name, field.name
                                ),
                            );
                        }
                    }
                    result_reserved_names
                        .extend(result.select.iter().map(|field| field.name.clone()));

                    let typed_grain = match &result.grain {
                        ExploreResultGrain::EachCase { span } => {
                            TypedExploreResultGrain::EachCase { span: *span }
                        }
                        ExploreResultGrain::EachIncidence { span } => {
                            TypedExploreResultGrain::EachIncidence { span: *span }
                        }
                        ExploreResultGrain::GroupAll { span } => {
                            TypedExploreResultGrain::GroupAll { span: *span }
                        }
                        ExploreResultGrain::GroupBy { fields, span } => {
                            let mut typed_fields = Vec::with_capacity(fields.len());
                            for field in fields {
                                let typed = self.check_explore_result_field(
                                    field,
                                    "group field",
                                    &result_reserved_names,
                                    &result_available,
                                    true,
                                );
                                self.define_var(&typed.name);
                                self.define_var_type(&typed.name, &typed.ty);
                                result_available.insert(typed.name.clone());
                                typed_fields.push(typed);
                            }
                            TypedExploreResultGrain::GroupBy {
                                fields: typed_fields,
                                span: *span,
                            }
                        }
                    };

                    let mut typed_measures = Vec::with_capacity(result.measures.len());
                    for field in &result.measures {
                        let typed = self.check_explore_result_field(
                            field,
                            "measure",
                            &result_reserved_names,
                            &result_available,
                            false,
                        );
                        self.define_var(&typed.name);
                        self.define_var_type(&typed.name, &typed.ty);
                        result_available.insert(typed.name.clone());
                        typed_measures.push(typed);
                    }

                    let mut typed_aggregates = Vec::with_capacity(result.aggregates.len());
                    for field in &result.aggregates {
                        let typed = self.check_explore_aggregate_field(
                            field,
                            &result_reserved_names,
                            &result_available,
                        );
                        self.define_var(&typed.name);
                        self.define_var_type(&typed.name, &typed.ty);
                        result_available.insert(typed.name.clone());
                        typed_aggregates.push(typed);
                    }

                    let typed_having = result.having.as_ref().and_then(|having| {
                        if matches!(
                            &result.grain,
                            ExploreResultGrain::EachCase { .. }
                                | ExploreResultGrain::EachIncidence { .. }
                        ) {
                            self.error_at_span(
                                result.grain.span(),
                                "having varies requires group all or group by",
                            );
                        }
                        match having {
                            ExploreResultHaving::Varies { measure_name, span } => typed_measures
                                .iter()
                                .position(|measure| measure.name == *measure_name)
                                .map(|measure_index| TypedExploreResultHaving::Varies {
                                    measure_name: measure_name.clone(),
                                    measure_index,
                                    span: *span,
                                })
                                .or_else(|| {
                                    self.error_at_span(
                                        *span,
                                        format!(
                                            "having varies({measure_name}) must name a preceding measure"
                                        ),
                                    );
                                    None
                                }),
                        }
                    });

                    let grouped_without_choice = matches!(
                        &result.grain,
                        ExploreResultGrain::GroupAll { .. } | ExploreResultGrain::GroupBy { .. }
                    ) && result.choose.is_none();
                    let mut select_available = if grouped_without_choice {
                        group_fields
                            .iter()
                            .map(|field| field.name.clone())
                            .chain(typed_aggregates.iter().map(|field| field.name.clone()))
                            .collect::<BTreeSet<_>>()
                    } else {
                        result_available.clone()
                    };
                    let mut typed_select = Vec::with_capacity(result.select.len());
                    for field in &result.select {
                        let typed = self.check_explore_result_field(
                            field,
                            "selected field",
                            &result_reserved_names,
                            &select_available,
                            false,
                        );
                        self.define_var(&typed.name);
                        self.define_var_type(&typed.name, &typed.ty);
                        result_available.insert(typed.name.clone());
                        select_available.insert(typed.name.clone());
                        typed_select.push(typed);
                    }

                    let check_objective = |value: &Expr, label: &str, checker: &mut Self| {
                        checker.check_explore_available_references(
                            value,
                            &result_reserved_names,
                            &result_available,
                        );
                        checker.check_explore_role_environment(
                            value,
                            &["before", "after", "context"],
                            label,
                        );
                        checker.check_explore_expression(value);
                        let ty = checker.inferred_explore_ty(value).unwrap_or(Ty::Hole);
                        if ty.to_string() != "Int" {
                            checker.error_at_expr(
                                value,
                                format!("exploration {label} must have type Int, found {ty}"),
                            );
                        }
                        ty
                    };
                    let typed_choose = match &result.choose {
                        None => None,
                        Some(ExploreResultChoice::Optimize {
                            cardinality,
                            direction,
                            objective,
                            span,
                        }) => {
                            let objective_ty = check_objective(objective, "choice objective", self);
                            Some(TypedExploreResultChoice::Optimize {
                                cardinality: *cardinality,
                                direction: *direction,
                                objective: objective.clone(),
                                objective_ty,
                                span: *span,
                            })
                        }
                        Some(ExploreResultChoice::Pareto { objectives, span }) => {
                            let objectives = objectives
                                .iter()
                                .map(|objective| TypedExploreParetoObjective {
                                    direction: objective.direction,
                                    ty: check_objective(&objective.value, "Pareto objective", self),
                                    value: objective.value.clone(),
                                    span: objective.span,
                                })
                                .collect();
                            Some(TypedExploreResultChoice::Pareto {
                                objectives,
                                span: *span,
                            })
                        }
                    };
                    self.pop_scope();

                    TypedExploreAnalysisNode::Result(TypedExploreResultView {
                        name: result.name.clone(),
                        input: typed_input,
                        grain: typed_grain,
                        measures: typed_measures,
                        aggregates: typed_aggregates,
                        having: typed_having,
                        select: typed_select,
                        choose: typed_choose,
                        span: result.span,
                    })
                }
                ExploreAnalysisNode::Mechanisms(request) => {
                    let typed_target = match &request.target {
                        ExploreMechanismTarget::SelectedCases => {
                            TypedExploreMechanismTarget::SelectedCases
                        }
                        ExploreMechanismTarget::ViewChosen { view_name } => {
                            let view_node_index = analysis_by_name
                                .get(view_name)
                                .copied()
                                .filter(|index| {
                                    matches!(
                                        typed_analysis.get(*index),
                                        Some(TypedExploreAnalysisNode::Result(view))
                                            if view.choose.is_some()
                                                && matches!(
                                                    &view.input,
                                                    TypedExploreResultInput::Selected
                                                )
                                    )
                                })
                                .unwrap_or_else(|| {
                                    self.error_at_span(
                                        request.span,
                                        format!(
                                            "mechanism request {} may target only an earlier chosen selected-case view; {} is unresolved, not chosen, post-mechanism, or declared later",
                                            request.name, view_name
                                        ),
                                    );
                                    usize::MAX
                                });
                            TypedExploreMechanismTarget::ViewChosen {
                                view_name: view_name.clone(),
                                view_node_index,
                            }
                        }
                    };

                    let key = (request.callable_name.clone(), 2_usize);
                    let definitions = self
                        .explore_function_definitions_by_arity
                        .get(&key)
                        .cloned();
                    let mut observation_ty = Ty::Hole;
                    match definitions
                        .as_ref()
                        .and_then(|definitions| definitions.first())
                    {
                        None => self.error_at_span(
                            request.span,
                            format!(
                                "mechanism observer {} must name one ordinary two-argument function",
                                request.callable_name
                            ),
                        ),
                        Some((parameters, return_type, _)) => {
                            if definitions
                                .as_ref()
                                .is_some_and(|definitions| definitions.len() != 1)
                            {
                                self.error_at_span(
                                    request.span,
                                    format!(
                                        "mechanism observer {} is ambiguous",
                                        request.callable_name
                                    ),
                                );
                            }
                            for (index, (parameter, expected)) in parameters
                                .iter()
                                .zip([&before_ty, &context_ty])
                                .enumerate()
                            {
                                match &parameter.ty {
                                    Some(actual)
                                        if Self::explore_tys_equivalent(actual, expected) => {}
                                    Some(actual) => self.error_at_span(
                                        request.span,
                                        format!(
                                            "mechanism observer parameter {} has type {actual}; expected {expected}",
                                            index + 1
                                        ),
                                    ),
                                    None => self.error_at_span(
                                        request.span,
                                        format!(
                                            "mechanism observer parameter {} needs explicit type {expected}",
                                            index + 1
                                        ),
                                    ),
                                }
                            }
                            if parameters.len() != 2 {
                                self.error_at_span(
                                    request.span,
                                    "mechanism observer must have exactly (State, Context) parameters",
                                );
                            }
                            match return_type {
                                Some(ty) => observation_ty = ty.clone(),
                                None => self.error_at_span(
                                    request.span,
                                    "mechanism observer needs an explicit result type",
                                ),
                            }
                        }
                    }
                    if !self.explore_callable_is_pure(&key) {
                        self.error_at_span(
                            request.span,
                            "mechanism observer must be pure and exploration-supported",
                        );
                    }

                    self.push_scope();
                    self.define_var("state");
                    self.define_var_type("state", &before_ty);
                    self.define_var("context");
                    self.define_var_type("context", &context_ty);
                    let observation_available = BTreeSet::from([
                        "state".to_string(),
                        "context".to_string(),
                        request.callable_name.clone(),
                    ]);
                    self.check_explore_available_references(
                        &request.endpoint_template,
                        &reserved_names,
                        &observation_available,
                    );
                    self.check_explore_expression(&request.endpoint_template);
                    self.pop_scope();

                    TypedExploreAnalysisNode::Mechanisms(TypedExploreMechanismRequest {
                        name: request.name.clone(),
                        target: typed_target,
                        callable_name: request.callable_name.clone(),
                        endpoint_template: request.endpoint_template.clone(),
                        observation_ty,
                        span: request.span,
                    })
                }
            };

            if !analysis_by_name.contains_key(node.name()) {
                analysis_by_name.insert(node.name().to_string(), node_index);
            }
            typed_analysis.push(typed_node);
        }

        let mut projection_names = analysis_by_name.keys().cloned().collect::<BTreeSet<_>>();
        let mut typed_starter_projections = Vec::with_capacity(query.starter_projections.len());
        for projection in &query.starter_projections {
            if !projection_names.insert(projection.name.clone()) {
                self.error_at_span(
                    projection.span,
                    format!("duplicate exploration declaration {}", projection.name),
                );
            }
            let request_node_index = analysis_by_name
                .get(&projection.request_name)
                .copied()
                .filter(|index| {
                    matches!(
                        typed_analysis.get(*index),
                        Some(TypedExploreAnalysisNode::Mechanisms(_))
                    )
                })
                .unwrap_or_else(|| {
                    self.error_at_span(
                        projection.span,
                        format!(
                            "starter projection {} may reference only an earlier mechanism request; {} is unresolved or has the wrong node kind",
                            projection.name, projection.request_name
                        ),
                    );
                    usize::MAX
                });
            let value_view_node_index = analysis_by_name
                .get(&projection.value_view_name)
                .copied()
                .filter(|index| {
                    matches!(
                        typed_analysis.get(*index),
                        Some(TypedExploreAnalysisNode::Result(view))
                            if Self::explore_starter_value_view_is_compatible(
                                view,
                                &context_ty,
                                &before_ty,
                                &after_ty,
                            )
                    )
                })
                .unwrap_or_else(|| {
                    self.error_at_span(
                        projection.span,
                        format!(
                            "starter projection {} requires earlier value view {} to be a selected-input `each case` view which directly selects case_id, context, before, and after without aggregates, having, or choice",
                            projection.name, projection.value_view_name
                        ),
                    );
                    usize::MAX
                });
            typed_starter_projections.push(TypedExploreStarterProjection {
                name: projection.name.clone(),
                request_name: projection.request_name.clone(),
                request_node_index,
                subject: projection.subject.into(),
                within_mechanism: projection
                    .within_mechanism
                    .map(explore::StructuralMechanismId::from_checked_source_bytes),
                value_view_name: projection.value_view_name.clone(),
                value_view_node_index,
                span: projection.span,
            });
        }
        let mut typed_transition_graphs = Vec::with_capacity(query.transition_graphs.len());
        for graph in &query.transition_graphs {
            if !projection_names.insert(graph.name.clone()) {
                self.error_at_span(
                    graph.span,
                    format!("duplicate exploration declaration {}", graph.name),
                );
            }
            typed_transition_graphs.push(TypedExploreTransitionGraph {
                name: graph.name.clone(),
                span: graph.span,
            });
        }

        self.pop_scope();

        if selectable && self.diagnostics.len() == diagnostic_start {
            self.exploration_queries.push(TypedExploreQuery {
                name: query.name.clone(),
                source: TypedExploreSourceRelation {
                    normalization_version: EXPLORE_RELATION_NORMALIZATION_VERSION,
                    multiplicity: ExploreRelationMultiplicity::SetNormalized,
                    bindings: typed_bindings,
                    before_binding_index,
                    context_binding_index,
                    before_ty,
                    context_ty,
                },
                successor: TypedExploreSuccessorRelation {
                    multiplicity: ExploreRelationMultiplicity::SetNormalized,
                    after_ty,
                    kind: typed_successor_kind,
                    span: query.successor.span,
                },
                admissions: typed_admissions,
                selection: typed_selection,
                analysis: typed_analysis,
                starter_projections: typed_starter_projections,
                transition_graphs: typed_transition_graphs,
                span: query.span,
            });
        }
        self.checking_explore_query = false;
        self.pop_context();
    }

    pub fn check_stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::Defn(Defn::Fn {
                name, params, body, ..
            }) => {
                self.push_context(format!("in function `{}`", name));
                self.push_scope();
                for p in params {
                    self.define_var(&p.name);
                    if let Some(ty) = &p.ty {
                        self.define_var_type(&p.name, ty);
                    }
                }
                self.check_expr(body, Some(name));
                self.pop_scope();
                self.pop_context();
            }
            Stmt::Defn(Defn::Actor {
                name,
                handlers,
                state_param,
                ..
            }) => {
                self.push_context(format!("in actor `{}`", name));
                for handler in handlers {
                    self.push_scope();
                    self.define_var(&state_param.name);
                    if let Some(ty) = &state_param.ty {
                        self.define_var_type(&state_param.name, ty);
                    }
                    self.define_pat_vars(&handler.msg_pat);
                    self.check_expr(&handler.body, None);
                    self.pop_scope();
                }
                self.pop_context();
            }
            Stmt::Defn(Defn::Module { name, body, .. }) => {
                self.push_context(format!("in module `{}`", name));
                self.push_scope();
                self.collect_nested_declarations(body);
                self.check_stmt_sequence(body);
                self.pop_scope();
                self.pop_context();
            }
            Stmt::TypeDecl(TypeDecl::ADT { methods, .. }) => {
                for defn in methods {
                    if let Defn::Fn {
                        name: mname,
                        params,
                        body,
                        ..
                    } = defn
                    {
                        self.push_scope();
                        for p in params {
                            self.define_var(&p.name);
                            if let Some(ty) = &p.ty {
                                self.define_var_type(&p.name, ty);
                            }
                        }
                        self.check_expr(body, Some(mname));
                        self.pop_scope();
                    }
                }
            }
            Stmt::TypeDecl(TypeDecl::ImplBlock { methods, .. }) => {
                for defn in methods {
                    if let Defn::Fn {
                        name: mname,
                        params,
                        body,
                        ..
                    } = defn
                    {
                        self.push_scope();
                        for p in params {
                            self.define_var(&p.name);
                            if let Some(ty) = &p.ty {
                                self.define_var_type(&p.name, ty);
                            }
                        }
                        self.check_expr(body, Some(mname));
                        self.pop_scope();
                    }
                }
            }
            Stmt::TypeDecl(TypeDecl::WhenType { condition, .. }) => {
                self.check_expr(condition, None);
            }
            Stmt::TypeDecl(TypeDecl::TraitDecl { methods, .. }) => {
                for method in methods {
                    if let Some(body) = &method.default_body {
                        self.push_scope();
                        for p in &method.params {
                            self.define_var(&p.name);
                            if let Some(ty) = &p.ty {
                                self.define_var_type(&p.name, ty);
                            }
                        }
                        self.check_expr(body, Some(&method.name));
                        self.pop_scope();
                    }
                }
            }
            Stmt::TypeDecl(TypeDecl::EffectDecl { .. }) => {}
            Stmt::TypeDecl(TypeDecl::RuleScope { name, params, body }) => {
                self.check_rule_scope_decl(name, params, body);
            }
            Stmt::Bind(pat, ty, expr) => {
                self.check_expr(expr, None);
                if let Some(ty) = ty {
                    self.check_declared_binding_ty(ty, expr);
                } else {
                    self.obvious_expr_ty(expr);
                }
                self.define_pat_vars(pat);
                if let Pat::Var(name) = pat {
                    let actor = Self::spawned_actor_name(expr);
                    self.define_actor_handle(name, actor);
                }
                if let (Pat::Var(name), Some(ty)) = (pat, ty.as_ref()) {
                    self.define_var_type(name, ty);
                } else if let Pat::Var(name) = pat {
                    if let Some(type_name) = self.infer_expr_type_name(expr) {
                        self.define_inferred_var_type_name(name, &type_name);
                    }
                }
                if let Pat::Var(name) = pat {
                    if let Some(scope_name) = self.expr_rule_scope_type(expr) {
                        self.define_rule_scope_var(name, &scope_name);
                    }
                }
            }
            Stmt::MonadicBind(pat, ty, expr) => {
                self.check_expr(expr, None);
                self.obvious_expr_ty(expr);
                self.define_pat_vars(pat);
                if let (Pat::Var(name), Some(ty)) = (pat, ty.as_ref()) {
                    self.define_var_type(name, ty);
                }
            }
            Stmt::StreamBind(name, expr) => {
                self.check_expr(expr, None);
                self.define_var(name);
            }
            Stmt::For(var, iter_expr, body) => {
                self.check_expr(iter_expr, None);
                self.push_scope();
                self.define_var(var);
                for s in body {
                    self.check_stmt(s);
                }
                self.pop_scope();
            }
            Stmt::While(cond, body) => {
                self.check_expr(cond, None);
                self.push_scope();
                for s in body {
                    self.check_stmt(s);
                }
                self.pop_scope();
            }
            Stmt::Expr(expr) => {
                self.check_expr(expr, None);
            }
            Stmt::Send(target, msg) => {
                self.check_expr(target, None);
                if !self.check_actor_message(Some(target), msg) {
                    self.check_expr(msg, None);
                }
            }
            Stmt::StreamSub(expr, arms) => {
                self.check_expr(expr, None);
                for arm in arms {
                    self.push_scope();
                    self.define_pat_vars(&arm.pat);
                    if let Some(g) = &arm.guard {
                        self.check_expr(g, None);
                    }
                    self.check_expr(&arm.body, None);
                    self.pop_scope();
                }
            }
            Stmt::Rule(Rule::ReactiveScope { body, .. }) => {
                self.push_scope();
                self.collect_nested_declarations(body);
                self.check_stmt_sequence(body);
                self.pop_scope();
            }
            Stmt::Rule(Rule::Default {
                head,
                value,
                condition,
                ..
            }) => {
                self.push_scope();
                // Rule head params are in scope for value/condition
                if let ExprKind::App(_, args) = &head.kind {
                    for arg in args {
                        Self::define_rule_head_vars(arg, &mut self.scopes);
                        self.define_rule_head_var_types(arg);
                    }
                }
                self.check_expr(value, None);
                if let Some(c) = condition {
                    self.check_expr(c, None);
                }
                self.pop_scope();
            }
            Stmt::Rule(Rule::Exception {
                head,
                value,
                condition,
                ..
            }) => {
                self.push_scope();
                if let ExprKind::App(_, args) = &head.kind {
                    for arg in args {
                        Self::define_rule_head_vars(arg, &mut self.scopes);
                        self.define_rule_head_var_types(arg);
                    }
                }
                self.check_expr(value, None);
                if let Some(c) = condition {
                    self.check_expr(c, None);
                }
                self.pop_scope();
            }
            Stmt::Rule(Rule::Clause { head, body }) => {
                self.push_scope();
                if let ExprKind::App(_, args) = &head.kind {
                    for arg in args {
                        Self::define_rule_head_vars(arg, &mut self.scopes);
                        self.define_rule_head_var_types(arg);
                    }
                }
                // For conjunctive bodies, also define existential variables
                // (variables that appear as arguments in goals but not in the head)
                if let Some(Expr {
                    kind: ExprKind::Conjunction(goals),
                    ..
                }) = body
                {
                    for goal in goals {
                        if let ExprKind::App(_, goal_args) = &goal.kind {
                            for arg in goal_args {
                                if let ExprKind::Var(name) = &arg.kind {
                                    self.define_var(name);
                                }
                            }
                        }
                    }
                }
                self.check_expr(head, None);
                if let Some(b) = body {
                    self.check_expr(b, None);
                }
                self.pop_scope();
            }
            Stmt::Invariant {
                subject, predicate, ..
            } => {
                self.push_scope();
                Self::define_rule_head_vars(subject, &mut self.scopes);
                self.define_rule_head_var_types(subject);
                self.check_expr(subject, None);
                self.check_expr(predicate, None);
                self.pop_scope();
            }
            Stmt::Prove {
                name,
                proof_block: _,
                capture,
                pass_block,
                else_block,
            } => {
                if name != "all" && !self.invariant_names.contains(name) {
                    self.error(format!(
                        "unknown invariant `{}`; define it with `| {}: subject -> predicate` and prove it with `? {}`",
                        name, name, name
                    ));
                }
                self.push_scope();
                // ? name: val — the capture variable is in scope for blocks
                if let Some(var_name) = capture {
                    self.define_var(var_name);
                }
                if let Some(stmts) = pass_block {
                    for s in stmts {
                        self.check_stmt(s);
                    }
                }
                if let Some(stmts) = else_block {
                    for s in stmts {
                        self.check_stmt(s);
                    }
                }
                self.pop_scope();
            }
            Stmt::Explore(query) => self.check_explore_query(query, false),
            Stmt::Assert(_, args) | Stmt::Retract(_, args) => {
                for arg in args {
                    self.check_expr(arg, None);
                }
            }
            Stmt::Use(_)
            | Stmt::Import(_)
            | Stmt::QualifiedImport(_, _)
            | Stmt::HashImport(_, _)
            | Stmt::Depend(_, _)
            | Stmt::RustBlock(_)
            | Stmt::Abort => {}
            Stmt::Annot(name, args) => {
                // Skip metadata annotations whose payloads are declarations, not
                // executable expressions in the current schema.
                if name != "store" && name != "migrate" {
                    for a in args {
                        self.check_expr(a, None);
                    }
                }
            }
        }
    }

    pub fn check_expr(&mut self, expr: &Expr, _in_fn: Option<&str>) {
        match &expr.kind {
            ExprKind::Var(name) => {
                if self.actor_message_arities.contains_key(name)
                    && self.check_actor_message(None, expr)
                {
                    return;
                }
                let canonical = builtin_canonical(name);
                if !self.var_defined(name)
                    && !self.functions.contains_key(name)
                    && !self.builtins.contains_key(canonical)
                    && !self.constructors.contains_key(name)
                    && !name.contains("::")
                    && !name.contains(".")
                    && name != "_"
                // wildcard — always valid
                {
                    let symbol_kind = if name.starts_with(|c: char| c.is_uppercase()) {
                        "constructor"
                    } else {
                        "variable"
                    };
                    self.error_at_expr(expr, format!("undefined {} `{}`", symbol_kind, name));
                }
            }
            ExprKind::App(func, args) => {
                if matches!(&func.kind, ExprKind::Var(name) if name == "__typed") {
                    if let Some(value) = args.first() {
                        self.check_expr(value, _in_fn);
                    }
                    return;
                }
                if matches!(&func.kind, ExprKind::Var(name) if name == PATHOF_MARKER) {
                    self.check_pathof_expr(expr, args);
                    return;
                }
                if matches!(&func.kind, ExprKind::Var(name) if name == REFOF_MARKER) {
                    self.check_refof_expr(expr, args);
                    return;
                }
                if matches!(&func.kind, ExprKind::Var(name) if self.actor_message_arities.contains_key(name))
                    && self.check_actor_message(None, expr)
                {
                    return;
                }
                if matches!(&func.kind, ExprKind::Var(name) if name == "ask") && args.len() == 2 {
                    self.check_expr(&args[0], _in_fn);
                    if !matches!(&args[0].kind, ExprKind::Var(_)) {
                        self.error_at_expr(
                            &args[0],
                            "actor `ask` target must be a bound actor handle; direct expressions are not supported"
                                .to_string(),
                        );
                        self.check_expr(&args[1], _in_fn);
                        return;
                    }
                    if !self.check_actor_message(Some(&args[0]), &args[1]) {
                        self.check_expr(&args[1], _in_fn);
                    }
                    return;
                }
                if let ExprKind::Field(base, method) = &func.as_ref().kind {
                    self.check_expr(base, _in_fn);
                    if let ExprKind::Var(module_name) = &base.kind {
                        if let Some(exported) = self.module_exports.get(module_name) {
                            if !exported.contains(method) {
                                self.error_at_expr(
                                    func,
                                    format!(
                                        "qualified import `{}` has no exported member `{}`; add `@ export` in the imported file or use an exported member",
                                        module_name, method
                                    ),
                                );
                            }
                        }
                    }
                    if let Some(scope_name) = self.expr_rule_scope_type(base) {
                        let scoped_rule_arity = self
                            .rule_scope_methods
                            .get(&scope_name)
                            .and_then(|methods| methods.get(method))
                            .copied();
                        let value_method_arity = self
                            .rule_scope_value_methods
                            .get(&scope_name)
                            .and_then(|methods| methods.get(method))
                            .copied();
                        if let Some(expected) = scoped_rule_arity {
                            if has_named_args(args) {
                                if let Some(params) = self
                                    .rule_scope_method_params
                                    .get(&scope_name)
                                    .and_then(|methods| methods.get(method))
                                    .cloned()
                                {
                                    self.check_named_call_args(
                                        expr,
                                        "scoped rule",
                                        &format!("{}.{}", scope_name, method),
                                        args,
                                        &params,
                                    );
                                } else {
                                    self.error_at_expr(
                                        expr,
                                        format!(
                                            "scoped rule `{}.{}` does not expose named parameters",
                                            scope_name, method
                                        ),
                                    );
                                }
                                return;
                            } else if args.len() != expected {
                                self.error_at_expr(
                                    expr,
                                    format!(
                                        "scoped rule `{}.{}` expects {} argument{} but got {}",
                                        scope_name,
                                        method,
                                        expected,
                                        if expected == 1 { "" } else { "s" },
                                        args.len()
                                    ),
                                );
                            }
                        } else if let Some(expected) = value_method_arity {
                            if has_named_args(args) {
                                if let Some(params) = self
                                    .rule_scope_value_method_params
                                    .get(&scope_name)
                                    .and_then(|methods| methods.get(method))
                                    .cloned()
                                {
                                    self.check_named_call_args(
                                        expr,
                                        "method",
                                        &format!("{}.{}", scope_name, method),
                                        args,
                                        &params,
                                    );
                                } else {
                                    self.error_at_expr(
                                        expr,
                                        format!(
                                            "method `{}.{}` does not expose named parameters",
                                            scope_name, method
                                        ),
                                    );
                                }
                                return;
                            } else if args.len() != expected {
                                self.error_at_expr(
                                    expr,
                                    format!(
                                        "method `{}.{}` expects {} argument{} but got {}",
                                        scope_name,
                                        method,
                                        expected,
                                        if expected == 1 { "" } else { "s" },
                                        args.len()
                                    ),
                                );
                            }
                        } else {
                            self.error_at_expr(
                                func,
                                format!(
                                    "RuleScope `{}` has no scoped rule or method `{}`",
                                    scope_name, method
                                ),
                            );
                        }
                    } else if self.is_rule_scope_member_name(method) {
                        self.error_at_expr(
                            func,
                            format!(
                                "scoped member `{}` must be called on a RuleScope value",
                                method
                            ),
                        );
                    }
                    for arg in args {
                        self.check_expr(arg, _in_fn);
                    }
                    return;
                }
                if let ExprKind::Var(name) = &func.as_ref().kind {
                    let canonical = builtin_canonical(name);
                    let actual_arity = args.len();
                    if has_named_args(args) {
                        if self.constructor_signatures.contains_key(name) {
                            let signature = self
                                .constructor_signature_for_named_validation(name, args)
                                .expect("registered constructor has a validation signature");
                            self.check_named_constructor_args(expr, name, args, signature);
                        } else if let Some(params) =
                            self.function_params_for_arity(name, actual_arity).cloned()
                        {
                            self.check_named_call_args(expr, "function/rule", name, args, &params);
                        } else if let Some(params) = self.function_params.get(name).cloned() {
                            self.check_named_call_args(expr, "function/rule", name, args, &params);
                        } else if self.functions.contains_key(name) {
                            self.error_at_expr(
                                expr,
                                format!(
                                    "function/rule `{}` does not expose named parameters",
                                    name
                                ),
                            );
                            for arg in args {
                                if let Some((_, value)) = named_arg_parts(arg) {
                                    self.check_expr(value, _in_fn);
                                } else {
                                    self.check_expr(arg, _in_fn);
                                }
                            }
                        } else if self.builtins.contains_key(canonical) {
                            self.error_at_expr(
                                expr,
                                format!("named arguments are not supported for builtin `{}`", name),
                            );
                            for arg in args {
                                if let Some((_, value)) = named_arg_parts(arg) {
                                    self.check_expr(value, _in_fn);
                                } else {
                                    self.check_expr(arg, _in_fn);
                                }
                            }
                        } else {
                            self.error_at_expr(
                                expr,
                                format!(
                                    "named arguments require a known function, rule, or constructor; `{}` is not defined",
                                    name
                                ),
                            );
                            for arg in args {
                                if let Some((_, value)) = named_arg_parts(arg) {
                                    self.check_expr(value, _in_fn);
                                } else {
                                    self.check_expr(arg, _in_fn);
                                }
                            }
                        }
                        return;
                    }

                    if let Some(&expected) = self.functions.get(name) {
                        if !self.function_has_arity(name, actual_arity)
                            && actual_arity != expected
                            && !self.is_rule_function(name)
                        {
                            self.error_at_expr(
                                expr,
                                format!(
                                    "`{}` expects {} argument{} but got {}",
                                    name,
                                    expected,
                                    if expected == 1 { "" } else { "s" },
                                    actual_arity
                                ),
                            );
                        }
                    } else if let Some(&expected) = self.builtins.get(canonical) {
                        if actual_arity != expected {
                            self.error_at_expr(
                                expr,
                                format!(
                                    "builtin `{}` expects {} argument{} but got {}",
                                    name,
                                    expected,
                                    if expected == 1 { "" } else { "s" },
                                    actual_arity
                                ),
                            );
                        }
                    } else if self.constructor_signatures.contains_key(name) {
                        if self.constructor_signature_for_args(name, args).is_none() {
                            let expected = self
                                .constructor_signature_for_parent(name, None)
                                .map(|signature| signature.arity())
                                .unwrap_or(actual_arity);
                            self.error_at_expr(
                                expr,
                                format!(
                                    "constructor `{}` expects {} field{} but got {}",
                                    name,
                                    expected,
                                    if expected == 1 { "" } else { "s" },
                                    actual_arity
                                ),
                            );
                        }
                    } else if !self.var_defined(name)
                        && !name.contains("::")
                        && !name.contains(".")
                        && name != "__typed"
                    {
                        let symbol_kind = if name.starts_with(|c: char| c.is_uppercase()) {
                            "constructor"
                        } else {
                            "function"
                        };
                        self.error_at_expr(func, format!("undefined {} `{}`", symbol_kind, name));
                    }
                } else {
                    self.check_expr(func, _in_fn);
                }
                // findall(template_var, goal) — template var and goal vars are scoped
                if let ExprKind::Var(name) = &func.as_ref().kind {
                    if (name == "findall" || name == "search") && args.len() == 2 {
                        self.push_scope();
                        // Define the template variable
                        if let ExprKind::Var(tvar) = &args[0].kind {
                            self.define_var(tvar);
                        }
                        // Define unbound variables in the goal
                        if let ExprKind::App(_, goal_args) = &args[1].kind {
                            for ga in goal_args {
                                if let ExprKind::Var(gv) = &ga.kind {
                                    self.define_var(gv);
                                }
                            }
                        }
                        for arg in args {
                            self.check_expr(arg, _in_fn);
                        }
                        self.pop_scope();
                        // Early return — already checked args in scope
                        return;
                    }
                }
                for arg in args {
                    self.check_expr(arg, _in_fn);
                }
            }
            ExprKind::BinOp(_, lhs, rhs) => {
                self.check_expr(lhs, _in_fn);
                self.check_expr(rhs, _in_fn);
            }
            ExprKind::UnOp(_, operand) => {
                self.check_expr(operand, _in_fn);
            }
            ExprKind::If(cond, then_br, else_br) => {
                self.check_expr(cond, _in_fn);
                self.check_expr(then_br, _in_fn);
                self.check_expr(else_br, _in_fn);
            }
            ExprKind::Match(scrutinee, arms) => {
                self.check_expr(scrutinee, _in_fn);
                let subject_type = self.infer_expr_type_name(scrutinee);
                self.check_refined_variant_match(scrutinee, arms, subject_type.as_deref());
                let mut first_arm_type: Option<String> = None;
                for (index, arm) in arms.iter().enumerate() {
                    self.check_pattern_constructor_arity(
                        &arm.pat,
                        &arm.body,
                        subject_type.as_deref(),
                    );
                    self.push_scope();
                    self.define_pat_vars(&arm.pat);
                    for (name, type_name) in
                        self.pattern_type_bindings(&arm.pat, subject_type.as_deref())
                    {
                        self.define_inferred_var_type_name(&name, &type_name);
                    }
                    if let Some(g) = &arm.guard {
                        self.check_expr(g, _in_fn);
                    }
                    self.check_expr(&arm.body, _in_fn);
                    if let Some(arm_type) = self.infer_expr_type_name(&arm.body) {
                        if let Some(expected) = first_arm_type.take() {
                            if let Some(merged) =
                                Self::merge_inferred_type_names(&expected, &arm_type)
                            {
                                first_arm_type = Some(merged);
                            } else {
                                self.error_at_expr(
                                    &arm.body,
                                    format!(
                                        "match arms must have the same type; first arm is `{}` but arm {} is `{}`",
                                        expected,
                                        index + 1,
                                        arm_type
                                    ),
                                );
                                first_arm_type = Some(expected);
                            }
                        } else {
                            first_arm_type = Some(arm_type);
                        }
                    }
                    self.pop_scope();
                }
                // Exhaustiveness check
                self.check_match_exhaustiveness(arms);
            }
            ExprKind::Block(stmts) => {
                self.push_scope();
                self.collect_nested_declarations(stmts);
                self.check_stmt_sequence(stmts);
                self.pop_scope();
            }
            ExprKind::Lambda(params, body) => {
                self.push_scope();
                for p in params {
                    self.define_var(&p.name);
                }
                self.check_expr(body, _in_fn);
                self.pop_scope();
            }
            ExprKind::Field(base, field) => {
                self.check_expr(base, _in_fn);
                if let ExprKind::Var(module_name) = &base.kind {
                    if let Some(exported) = self.module_exports.get(module_name) {
                        if !exported.contains(field) {
                            self.error_at_expr(
                                expr,
                                format!(
                                    "qualified import `{}` has no exported member `{}`; add `@ export` in the imported file or use an exported member",
                                    module_name, field
                                ),
                            );
                        }
                    }
                }
                if let Some(type_name) = self.infer_expr_type_name(base) {
                    if let Some(fields) = self.type_fields.get(&type_name) {
                        if !fields.contains(field) {
                            self.error_at_expr(
                                expr,
                                format!("type `{}` has no field `{}`", type_name, field),
                            );
                        }
                    }
                }
            }
            ExprKind::Index(base, idx) => {
                self.check_expr(base, _in_fn);
                self.check_expr(idx, _in_fn);
            }
            ExprKind::List(elems) => {
                for e in elems {
                    self.check_expr(e, _in_fn);
                }
            }
            ExprKind::Tuple(elems) => {
                for e in elems {
                    self.check_expr(e, _in_fn);
                }
            }
            ExprKind::Effect(name, args) => {
                for a in args {
                    self.check_expr(a, _in_fn);
                }
                let canonical = builtin_canonical(name);
                if let Some(&expected) = self.builtins.get(canonical) {
                    if args.len() != expected {
                        self.error_at_expr(
                            expr,
                            format!(
                                "effect `{}` expects {} argument{} but got {}",
                                name,
                                expected,
                                if expected == 1 { "" } else { "s" },
                                args.len()
                            ),
                        );
                    }
                }
            }
            ExprKind::Handle { body, handlers, .. } => {
                self.push_scope();
                self.define_var("resume");
                for h in handlers {
                    self.push_scope();
                    for p in &h.params {
                        self.define_var(p);
                    }
                    self.check_expr(&h.body, _in_fn);
                    self.pop_scope();
                }
                self.check_expr(body, _in_fn);
                self.pop_scope();
            }
            ExprKind::Try(inner) => {
                self.check_expr(inner, _in_fn);
            }
            ExprKind::Lit(_) | ExprKind::Unit => {}
            ExprKind::Conjunction(exprs) | ExprKind::Disjunction(exprs) => {
                for e in exprs {
                    self.check_expr(e, _in_fn);
                }
            }
            ExprKind::Pipe(input, transform) => {
                self.check_expr(input, _in_fn);
                // For pipe RHS, skip arity check on the outer App because
                // the pipe desugars a |> f(y) → f(a, y), adding an implicit first arg.
                // Check the inner expressions without the top-level arity check.
                match &transform.kind {
                    ExprKind::App(func, args) => {
                        self.check_expr(func, _in_fn);
                        for arg in args {
                            self.check_expr(arg, _in_fn);
                        }
                    }
                    _ => self.check_expr(transform, _in_fn),
                }
            }
        }
    }

    pub fn define_pat_vars(&mut self, pat: &Pat) {
        match pat {
            Pat::Var(name) => self.define_var(name),
            Pat::Con(_, pats) => {
                for p in pats {
                    self.define_pat_vars(p);
                }
            }
            Pat::NamedCon(_, fields) => {
                for (_, p) in fields {
                    self.define_pat_vars(p);
                }
            }
            Pat::As(inner, name) => {
                self.define_pat_vars(inner);
                self.define_var(name);
            }
            Pat::Wild | Pat::Lit(_) => {}
        }
    }

    fn bare_fielded_constructor_name<'a>(
        &self,
        pat: &'a Pat,
        subject_type: Option<&str>,
    ) -> Option<&'a str> {
        let Pat::Con(name, args) = pat else {
            return None;
        };
        if !args.is_empty() {
            return None;
        }
        self.constructor_signature_for_parent(name, subject_type)
            .and_then(|signature| (signature.arity() > 0).then_some(name.as_str()))
    }

    fn tag_only_pattern(pat: &Pat) -> bool {
        match pat {
            Pat::Wild | Pat::Lit(_) => true,
            Pat::Con(_, args) => args.is_empty(),
            Pat::Var(_) | Pat::NamedCon(_, _) | Pat::As(_, _) => false,
        }
    }

    fn check_refined_variant_match(
        &mut self,
        scrutinee: &Expr,
        arms: &[MatchArm],
        subject_type: Option<&str>,
    ) {
        let bare_names: Vec<&str> = arms
            .iter()
            .filter_map(|arm| self.bare_fielded_constructor_name(&arm.pat, subject_type))
            .collect();
        if bare_names.is_empty() {
            return;
        }

        if !matches!(scrutinee.kind, ExprKind::Var(_)) {
            let first = bare_names[0];
            self.error_at_expr(
                scrutinee,
                format!(
                    "bare fielded variant pattern `{}` only refines a named match subject; bind the scrutinee with `=` first or destructure fields explicitly",
                    first
                ),
            );
        }

        if let Some(arm) = arms.iter().find(|arm| !Self::tag_only_pattern(&arm.pat)) {
            self.error(format!(
                "bare fielded variant refinement cannot be mixed with destructuring pattern `{}` in the same match",
                Self::pattern_label(&arm.pat)
            ));
        }
    }

    fn check_pattern_constructor_arity(
        &mut self,
        pat: &Pat,
        anchor: &Expr,
        subject_type: Option<&str>,
    ) {
        match pat {
            Pat::Con(name, args) => {
                let signature = self.constructor_signature_for_parent(name, subject_type);
                // A fielded variant with no arguments is the separate tag-only
                // refinement form checked by check_refined_variant_match.
                if !args.is_empty() {
                    if let Some(signature) = &signature {
                        if args.len() != signature.arity() {
                            self.error_at_expr(
                                anchor,
                                format!(
                                    "constructor pattern `{}` expects {} fields but got {}; use an explicit wildcard for every ignored positional field",
                                    name,
                                    signature.arity(),
                                    args.len()
                                ),
                            );
                        }
                    }
                }
                for (index, arg) in args.iter().enumerate() {
                    let field_type = signature
                        .as_ref()
                        .and_then(|signature| signature.field_types.get(index))
                        .and_then(|field_type| field_type.as_deref());
                    self.check_pattern_constructor_arity(arg, anchor, field_type);
                }
            }
            Pat::NamedCon(name, fields) => {
                let signature = self.constructor_signature_for_parent(name, subject_type);
                for (field, field_pat) in fields {
                    let field_type = signature.as_ref().and_then(|signature| {
                        signature
                            .fields
                            .iter()
                            .position(|candidate| candidate == field)
                            .and_then(|index| signature.field_types.get(index))
                            .and_then(|field_type| field_type.as_deref())
                    });
                    self.check_pattern_constructor_arity(field_pat, anchor, field_type);
                }
            }
            Pat::As(inner, _) => self.check_pattern_constructor_arity(inner, anchor, subject_type),
            Pat::Wild | Pat::Var(_) | Pat::Lit(_) => {}
        }
    }

    fn pattern_label(pat: &Pat) -> String {
        match pat {
            Pat::Wild => "_".to_string(),
            Pat::Var(name) => name.clone(),
            Pat::Con(name, _) | Pat::NamedCon(name, _) => name.clone(),
            Pat::Lit(lit) => lit.to_string(),
            Pat::As(_, name) => name.clone(),
        }
    }

    /// Check match exhaustiveness: are all variants of an ADT covered?
    fn check_match_exhaustiveness(&mut self, arms: &[MatchArm]) {
        if arms.is_empty() {
            return;
        }

        // If any arm has a wildcard or variable pattern (without a guard), match is exhaustive
        for arm in arms {
            if arm.guard.is_none() {
                match &arm.pat {
                    Pat::Wild | Pat::Var(_) => return, // catch-all
                    _ => {}
                }
            }
        }

        // Collect constructor names from top-level patterns
        let mut matched_ctors: BTreeSet<String> = BTreeSet::new();
        let mut has_lit_pattern = false;
        for arm in arms {
            match &arm.pat {
                Pat::Con(name, _) | Pat::NamedCon(name, _) => {
                    matched_ctors.insert(name.clone());
                }
                Pat::Lit(_) => {
                    has_lit_pattern = true;
                }
                _ => {}
            }
        }

        // If matching on literals (Int, String, etc.), we can't check exhaustiveness
        if has_lit_pattern || matched_ctors.is_empty() {
            return;
        }

        // Find the parent type from the first constructor
        let first_ctor = matched_ctors.iter().next().unwrap();
        let parent_type = match self.constructors.get(first_ctor) {
            Some((ty, _)) => ty.clone(),
            None => return, // unknown constructor, skip
        };

        // Look up all variants for this type
        let all_variants = match self.type_variants.get(&parent_type) {
            Some(v) => v.clone(),
            None => return, // single-variant type or unknown, skip
        };

        // Find missing variants
        let missing: Vec<&String> = all_variants
            .iter()
            .filter(|v| !matched_ctors.contains(*v))
            .collect();

        if !missing.is_empty() {
            let missing_names: Vec<&str> = missing.iter().map(|s| s.as_str()).collect();
            self.error(format!(
                "non-exhaustive match on `{}`: missing {}",
                parent_type,
                missing_names.join(", ")
            ));
        }
    }

    pub fn is_rule_function(&self, name: &str) -> bool {
        !self.user_functions.contains(name)
    }

    fn rule_dispatch_metadata_for_runtime(
        stmts: &[Stmt],
        source_dir: Option<String>,
    ) -> (
        BTreeMap<RuleDispatchKey, String>,
        BTreeMap<RuleDispatchKey, String>,
        BTreeSet<RuleDispatchKey>,
    ) {
        let mut checker = TypeChecker::new();
        checker.source_dir = source_dir;
        checker.install_constructor_prepass(stmts);
        checker.collect_declarations(stmts);
        checker.infer_rule_return_types(stmts);
        checker.infer_canonical_rule_dispatch_metadata(stmts);
        (
            checker.rule_dispatch_return_types,
            checker.rule_dispatch_return_issues,
            checker.rule_dispatch_boolean_miss_safe_keys,
        )
    }

    /// Run the type checker on a program. Returns errors.
    pub fn check(stmts: &[Stmt]) -> Vec<String> {
        Self::check_with_dir(stmts, None)
    }

    /// Run the type checker with a source directory for resolving imports.
    pub fn check_with_dir(stmts: &[Stmt], source_dir: Option<String>) -> Vec<String> {
        Self::check_with_source(stmts, source_dir, "")
    }

    /// Run the type checker with source text for error positions.
    /// Run type checking and return structured diagnostics.
    pub fn check_with_diagnostics(
        stmts: &[Stmt],
        source_dir: Option<String>,
        source: &str,
    ) -> Vec<Diagnostic> {
        Self::check_with_artifacts(stmts, source_dir, source).diagnostics
    }

    /// Run type checking and retain validated calculation contracts for callers
    /// that need them after validation.
    pub fn check_with_artifacts(
        stmts: &[Stmt],
        source_dir: Option<String>,
        source: &str,
    ) -> TypeCheckArtifacts {
        Self::check_with_artifact_options(stmts, source_dir, source, false, true)
    }

    /// Run type checking and additionally collect compile-time metadata from
    /// the complete import graph for a Rust-emitting backend.
    pub fn check_with_backend_artifacts(
        stmts: &[Stmt],
        source_dir: Option<String>,
        source: &str,
    ) -> TypeCheckArtifacts {
        Self::check_with_artifact_options(stmts, source_dir, source, true, true)
    }

    /// Check the complete runtime program while omitting calculation-contract
    /// extraction that the relational Explore engine never consumes.
    pub(crate) fn check_with_explore_artifacts(
        stmts: &[Stmt],
        source_dir: Option<String>,
        source: &str,
    ) -> TypeCheckArtifacts {
        Self::check_with_artifact_options(stmts, source_dir, source, false, false)
    }

    fn check_with_artifact_options(
        stmts: &[Stmt],
        source_dir: Option<String>,
        source: &str,
        collect_all_imported_metadata_bindings: bool,
        extract_calculation_contracts: bool,
    ) -> TypeCheckArtifacts {
        let check_started = std::time::Instant::now();
        Self::trace_explore_check_phase(&check_started, "begin");
        let mut tc = TypeChecker::new();
        tc.source_dir = source_dir;
        tc.source_text = source.to_string();
        tc.install_constructor_prepass(stmts);
        Self::trace_explore_check_phase(&check_started, "constructor prepass");
        tc.collect_declarations(stmts);
        Self::trace_explore_check_phase(&check_started, "declarations");
        // Seed annotated and literal top-level values before validating
        // Explore helper bodies so a hidden immutable producer input retains
        // its declared type inside that helper. The later pass still refines
        // bindings whose type depends on the established callable fixed point.
        tc.infer_top_level_binding_types(stmts);
        tc.infer_rule_return_types(stmts);
        tc.infer_canonical_rule_dispatch_metadata(stmts);
        tc.establish_explore_function_return_types();
        tc.infer_explore_rule_return_types(stmts);
        tc.validate_explore_function_return_types();
        // Re-run canonical dispatch after the exact rule fixed point so
        // recursive families can resolve through their validated provisional
        // seed. The final exact pass then consumes only the canonical result.
        tc.infer_canonical_rule_dispatch_metadata(stmts);
        tc.infer_explore_rule_return_types(stmts);
        Self::trace_explore_check_phase(&check_started, "rule fixed point");
        tc.infer_top_level_binding_types(stmts);
        Self::trace_explore_check_phase(&check_started, "top-level bindings");
        tc.check_program(stmts);
        Self::trace_explore_check_phase(&check_started, "checked statements");
        let mut calculation_contracts = Vec::new();
        let mut compile_time_metadata_bindings = BTreeSet::new();
        let mut exploration_universes = Vec::new();
        if tc.diagnostics.is_empty() {
            match explore::elaborate_queries(
                stmts,
                tc.source_dir.as_deref(),
                &tc.exploration_queries,
                &tc.rule_dispatch_return_types,
                &tc.rule_dispatch_return_issues,
                &tc.rule_dispatch_boolean_miss_safe_keys,
                &tc.explore_rule_return_types_by_arity,
                &tc.explore_rule_return_issues,
                true,
            ) {
                Ok(universes) => exploration_universes = universes,
                Err(mut diagnostics) => tc.diagnostics.append(&mut diagnostics),
            }
        }
        Self::trace_explore_check_phase(&check_started, "elaborated explorations");
        if extract_calculation_contracts && tc.diagnostics.is_empty() {
            match calculate::extract_calculation_artifacts_with_checker(
                stmts,
                source,
                tc.source_dir.clone(),
                &tc,
                collect_all_imported_metadata_bindings,
            ) {
                Ok(artifacts) => {
                    calculation_contracts = artifacts.contracts;
                    compile_time_metadata_bindings = artifacts.compile_time_metadata_bindings;
                }
                Err(mut diagnostics) => tc.diagnostics.append(&mut diagnostics),
            }
        }
        Self::trace_explore_check_phase(
            &check_started,
            if extract_calculation_contracts {
                "extracted calculations"
            } else {
                "skipped calculation extraction"
            },
        );
        let checked_resolutions = CheckedResolutionRecorder::record(&tc);
        Self::trace_explore_check_phase(&check_started, "recorded resolutions");
        let (checked_exploration_queries, checked_exploration_query_issue) =
            if tc.diagnostics.is_empty() {
                match build_checked_explore_query_artifacts(
                    &tc.analysis_program,
                    &checked_resolutions,
                    &exploration_universes,
                ) {
                    Ok(queries) => (queries, None),
                    Err(issue) => (Vec::new(), Some(issue)),
                }
            } else {
                (Vec::new(), None)
            };
        Self::trace_explore_check_phase(&check_started, "minted exploration identities");
        let exploration_queries = if tc.diagnostics.is_empty() {
            tc.exploration_queries
        } else {
            exploration_universes.clear();
            Vec::new()
        };
        let runtime_root_statements: Arc<[Stmt]> = stmts.to_vec().into();
        let runtime_root_program = TypeChecker::checked_resolved_program_id(
            &tc.analysis_program,
            &runtime_root_statements,
        );
        let runtime_root_source_dir = tc.source_dir.clone().map(String::into_boxed_str);
        TypeCheckArtifacts {
            diagnostics: tc.diagnostics,
            calculation_contracts,
            compile_time_metadata_bindings,
            rule_return_types: tc.rule_return_types,
            rule_scope_member_return_types: tc.rule_scope_member_return_types,
            rule_dispatch_return_types: tc.rule_dispatch_return_types,
            rule_dispatch_return_issues: tc.rule_dispatch_return_issues,
            rule_dispatch_boolean_miss_safe_keys: tc.rule_dispatch_boolean_miss_safe_keys,
            exploration_queries,
            exploration_universes,
            checked_exploration_queries,
            checked_exploration_query_issue,
            analysis_program: tc.analysis_program,
            resolved_program: tc.resolved_program,
            runtime_root_statements,
            runtime_root_program,
            runtime_root_source_dir,
            checked_resolutions,
        }
    }

    fn trace_explore_check_phase(started: &std::time::Instant, phase: &str) {
        if env::var_os("FUTURUNA_EXPLORE_TRACE").is_some() {
            eprintln!(
                "Explore typecheck: {phase}; elapsed={}ms",
                started.elapsed().as_millis()
            );
        }
    }

    /// Legacy wrapper — returns string-formatted errors for backward compatibility.
    pub fn check_with_source(
        stmts: &[Stmt],
        source_dir: Option<String>,
        source: &str,
    ) -> Vec<String> {
        let diags = Self::check_with_diagnostics(stmts, source_dir, source);
        diags
            .iter()
            .map(|d| {
                if let Some(span) = d.span {
                    let (line, col) = span.start_line_col(&source);
                    format!("{}:{}: {}", line, col, d.message)
                } else {
                    d.message.clone()
                }
            })
            .collect()
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MethodReceiverShape {
    None,
    SelfFirst,
    Invalid,
}

// ============================================================================
// PUBLIC EVAL API
// ============================================================================

/// Evaluate Futuruna source code and return captured output.
/// Used by the WASM playground to run code in-browser.
pub fn eval_source(source: &str) -> Result<String, String> {
    eval_source_with_prelude(source, true)
}

/// Evaluate with optional prelude.
/// Catches panics (e.g. from std::process::exit on WASM) and returns them as errors.
pub fn eval_source_with_prelude(source: &str, use_prelude: bool) -> Result<String, String> {
    let source = source.to_string();
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(move || {
        eval_source_inner(&source, use_prelude)
    }));
    match result {
        Ok(inner) => inner,
        Err(panic) => {
            let msg = if let Some(s) = panic.downcast_ref::<&str>() {
                s.to_string()
            } else if let Some(s) = panic.downcast_ref::<String>() {
                s.clone()
            } else {
                "Runtime error".to_string()
            };
            Err(msg)
        }
    }
}

fn eval_source_inner(source: &str, use_prelude: bool) -> Result<String, String> {
    let mut lexer = Lexer::new(source);
    let tokens = lexer.tokenize();
    let mut parser = Parser::new(tokens, source);
    match parser.parse_program() {
        Ok(user_stmts) => {
            let stmts = if use_prelude {
                prepend_prelude(parse_prelude(), &user_stmts)
            } else {
                user_stmts
            };

            // Type check and retain the exact rule return metadata needed by
            // the interpreter's typed Boolean miss semantics.
            let artifacts = TypeChecker::check_with_artifacts(&stmts, None, source);
            if !artifacts.diagnostics.is_empty() {
                let errors = artifacts
                    .diagnostics
                    .iter()
                    .map(|diagnostic| {
                        if let Some(span) = diagnostic.span {
                            let (line, column) = span.start_line_col(source);
                            format!("{}:{}: {}", line, column, diagnostic.message)
                        } else {
                            diagnostic.message.clone()
                        }
                    })
                    .collect::<Vec<_>>();
                return Err(errors.join("\n"));
            }

            // Interpret
            let mut interp = Interpreter::new();
            interp.install_rule_dispatch_metadata(&artifacts);
            let mut env = interp.default_env();
            let result = interp.run_program(&stmts, &mut env);

            // Collect output
            let mut output = interp.output.join("\n");
            match &result {
                Value::Unit => {}
                Value::List(_)
                | Value::Stream(_)
                | Value::Subject(_)
                | Value::Closure { .. }
                | Value::Builtin(_)
                | Value::Actor { .. } => {}
                _ => {
                    if !output.is_empty() {
                        output.push('\n');
                    }
                    output.push_str(&format!("=> {}", result));
                }
            }
            Ok(output)
        }
        Err(e) => Err(e),
    }
}

