    #[test]
    fn explore_source_coverage_fails_closed_for_unmodeled_intrinsic_composition() {
        let source = r#"
# CoverageChild(value: Int)
# CoverageContainer(children: List(CoverageChild))

? explore container_source_coverage {
    from {
        before = CoverageContainer(children = [CoverageChild(value = 1)])
        context = ()
    }
    to after = before
    find all
}
"#;
        let (_, _, manifest) = source_coverage_snapshot(source, "container_source_coverage");
        assert!(manifest.validate_identity());
        assert!(manifest.has_coverage_gaps());
        assert!(matches!(
            &source_coverage_field(&manifest, "before.children").classification,
            CheckedExploreCoverageClassification::CoverageGap {
                reason: CheckedExploreCoverageGapReason::SchemaCompositionUnavailable
            }
        ));
        assert!(!manifest.entries.iter().any(|entry| {
            source_coverage_field_path(entry).as_deref() == Some("before.children.value")
        }));
    }

    #[test]
    fn explore_source_coverage_identity_is_from_visible_and_relation_scoped() {
        let baseline_source = recursive_source_coverage_fixture();
        let (baseline_relation, baseline_question, baseline_manifest) =
            source_coverage_snapshot(baseline_source, "recursive_source_coverage");

        let downstream_only = baseline_source
            .replace("recursive_source_coverage", "renamed_source_coverage")
            .replace(
                "    find all",
                r#"    find matches of before.income >= 0
    results visible_cases {
        each case
        select [before]
    }"#,
            );
        let (downstream_relation, downstream_question, downstream_manifest) =
            source_coverage_snapshot(&downstream_only, "renamed_source_coverage");
        assert_eq!(downstream_relation, baseline_relation);
        assert_ne!(downstream_question, baseline_question);
        assert_eq!(downstream_manifest, baseline_manifest);

        let changed_source =
            baseline_source.replace("hidden_year: Int = 2026", "hidden_year: Int = 2027");
        let (changed_relation, _, changed_manifest) =
            source_coverage_snapshot(&changed_source, "recursive_source_coverage");
        assert_ne!(changed_relation, baseline_relation);
        assert_ne!(
            changed_manifest.semantic_dependency_digest,
            baseline_manifest.semantic_dependency_digest
        );
        assert_ne!(
            changed_manifest.manifest_digest,
            baseline_manifest.manifest_digest
        );

        let changed_to = baseline_source.replace(
            "income = before.income + context.step",
            "income = before.income + context.step + 2",
        );
        let (changed_to_relation, _, changed_to_manifest) =
            source_coverage_snapshot(&changed_to, "recursive_source_coverage");
        assert_ne!(changed_to_relation, baseline_relation);
        assert_eq!(
            changed_to_manifest.semantic_dependency_digest,
            baseline_manifest.semantic_dependency_digest
        );
        assert_ne!(
            changed_to_manifest.manifest_digest,
            baseline_manifest.manifest_digest
        );

        let mut corrupted = baseline_manifest.clone();
        corrupted.entries[0].subject_id[0] ^= 1;
        assert!(!corrupted.validate_identity());
    }

    fn stable_model_owner_identity_source() -> &'static str {
        r#"
# IdentityState = IdentityState(value: Int) | IdentityOther
# IdentityContext = IdentityContext(step: Int) | IdentityContextOther

> identity_step(before: IdentityState, context: IdentityContext) -> IdentityState {
    IdentityState(value = before.value + context.step)
}

> identity_observer(state: IdentityState, context: IdentityContext) -> Int {
    state.value
}

> identity_observer_alt(state: IdentityState, context: IdentityContext) -> Int {
    state.value + context.step
}

? explore identity_target {
    from {
        before in [IdentityState(value = 1)]
        context in [IdentityContext(step = 1)]
    }
    to after = identity_step(before, context)
    find all
    mechanisms paths for selected from identity_observer
}
"#
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    struct StableModelOwnerIdentitySnapshot {
        state_owner: CheckedDataTypeId,
        context_owner: CheckedDataTypeId,
        relation_id: explore::RelationId,
        state_schema_id: [u8; 32],
        context_schema_id: [u8; 32],
        transition_type_id: [u8; 32],
        before_state_id: [u8; 32],
        after_state_id: [u8; 32],
        transition_id: [u8; 32],
    }

    fn stable_model_owner_identity_snapshot(
        source: &str,
        query_name: &str,
    ) -> (
        TypeCheckArtifacts,
        StableModelOwnerIdentitySnapshot,
        explore::MechanismRequestId,
    ) {
        stable_model_owner_identity_snapshot_in_dir(source, query_name, None)
    }

    fn stable_model_owner_identity_snapshot_in_dir(
        source: &str,
        query_name: &str,
        source_dir: Option<String>,
    ) -> (
        TypeCheckArtifacts,
        StableModelOwnerIdentitySnapshot,
        explore::MechanismRequestId,
    ) {
        let statements = parse_test_program(source).expect("parse exploration fixture");
        let artifacts = TypeChecker::check_with_artifacts(&statements, source_dir, source);
        assert!(
            artifacts.diagnostics.is_empty(),
            "unexpected identity-fixture diagnostics: {:?}",
            artifacts.diagnostics
        );
        let query_index = artifacts
            .exploration_universes
            .iter()
            .position(|query| query.name == query_name)
            .expect("target checked Explore query");
        let checked = artifacts
            .checked_exploration_query(query_index)
            .expect("stable checked Explore identity");
        let schemas = checked.transition_schemas();
        let transition = schemas.instantiate(
            explore::ExploreValue::Unit,
            explore::ExploreValue::Int(1),
            explore::ExploreValue::Int(2),
        );
        let request_id = checked
            .analysis_nodes()
            .find_map(|(_, identity)| match identity {
                CheckedExploreAnalysisIdentity::Mechanisms { request_id, .. } => Some(*request_id),
                CheckedExploreAnalysisIdentity::View { .. } => None,
            })
            .expect("mechanism request identity");
        let snapshot = StableModelOwnerIdentitySnapshot {
            state_owner: artifacts.checked_resolutions.data_type_identities["IdentityState"]
                .clone(),
            context_owner: artifacts.checked_resolutions.data_type_identities["IdentityContext"]
                .clone(),
            relation_id: checked.relation_id(),
            state_schema_id: schemas.state_schema_id().bytes(),
            context_schema_id: schemas.context_schema_id().bytes(),
            transition_type_id: schemas.transition_type_id().bytes(),
            before_state_id: transition.before_state_id().bytes(),
            after_state_id: transition.after_state_id().bytes(),
            transition_id: transition.id().bytes(),
        };
        (artifacts, snapshot, request_id)
    }

    #[test]
    fn stable_model_owners_separate_query_analysis_and_executable_layers() {
        let baseline_source = stable_model_owner_identity_source();
        let (_, baseline, baseline_request) =
            stable_model_owner_identity_snapshot(baseline_source, "identity_target");

        let query_renamed = baseline_source.replace("identity_target", "identity_renamed");
        let (_, renamed, renamed_request) =
            stable_model_owner_identity_snapshot(&query_renamed, "identity_renamed");
        assert_eq!(renamed, baseline);
        assert_eq!(renamed_request, baseline_request);

        let with_view = baseline_source.replace(
            "    mechanisms paths for selected from identity_observer\n",
            r#"    results rows {
        each case
        select [case_id, before, after, context]
    }
    mechanisms paths for selected from identity_observer
"#,
        );
        let (_, viewed, viewed_request) =
            stable_model_owner_identity_snapshot(&with_view, "identity_target");
        assert_eq!(viewed, baseline);
        assert_eq!(viewed_request, baseline_request);

        let edited_view = with_view
            .replace("results rows", "results renamed_rows")
            .replace(
                "select [case_id, before, after, context]",
                "select [case_id, before, after]",
            );
        let (_, edited_view_identity, edited_view_request) =
            stable_model_owner_identity_snapshot(&edited_view, "identity_target");
        assert_eq!(edited_view_identity, baseline);
        assert_eq!(edited_view_request, baseline_request);

        let unrelated_prefix = r#"
? explore unrelated {
    from { before in [0]
        context = () }
    to after = before
    find all
}
"#;
        let with_unrelated = format!("{unrelated_prefix}{baseline_source}");
        let (_, unrelated, unrelated_request) =
            stable_model_owner_identity_snapshot(&with_unrelated, "identity_target");
        assert_eq!(unrelated, baseline);
        assert_eq!(unrelated_request, baseline_request);

        let observer_selected = baseline_source.replace(
            "mechanisms paths for selected from identity_observer",
            "mechanisms paths for selected from identity_observer_alt",
        );
        let (_, observer_selected_identity, observer_selected_request) =
            stable_model_owner_identity_snapshot(&observer_selected, "identity_target");
        assert_eq!(observer_selected_identity, baseline);
        assert_ne!(observer_selected_request, baseline_request);

        let observer_body_changed = baseline_source.replace(
            "    state.value\n}\n\n> identity_observer_alt",
            "    state.value + context.step + 1\n}\n\n> identity_observer_alt",
        );
        let (_, observer_identity, observer_request) =
            stable_model_owner_identity_snapshot(&observer_body_changed, "identity_target");
        assert_eq!(observer_identity, baseline);
        assert_ne!(observer_request, baseline_request);

        let relation_logic_changed = baseline_source.replace(
            "before.value + context.step)",
            "before.value + context.step + 1)",
        );
        let (_, relation_logic_identity, _) =
            stable_model_owner_identity_snapshot(&relation_logic_changed, "identity_target");
        assert_eq!(relation_logic_identity.state_owner, baseline.state_owner);
        assert_eq!(
            relation_logic_identity.context_owner,
            baseline.context_owner
        );
        assert_eq!(
            relation_logic_identity.state_schema_id,
            baseline.state_schema_id
        );
        assert_eq!(
            relation_logic_identity.context_schema_id,
            baseline.context_schema_id
        );
        assert_eq!(
            relation_logic_identity.transition_type_id,
            baseline.transition_type_id
        );
        assert_eq!(
            relation_logic_identity.before_state_id,
            baseline.before_state_id
        );
        assert_eq!(
            relation_logic_identity.after_state_id,
            baseline.after_state_id
        );
        assert_eq!(
            relation_logic_identity.transition_id,
            baseline.transition_id
        );
        assert_ne!(relation_logic_identity.relation_id, baseline.relation_id);

        let state_interface_changed = baseline_source.replace(
            "IdentityState(value: Int) | IdentityOther",
            "IdentityState(value: Int) | IdentityOther | IdentityThird",
        );
        let (_, state_changed, _) =
            stable_model_owner_identity_snapshot(&state_interface_changed, "identity_target");
        assert_ne!(state_changed.state_owner, baseline.state_owner);
        assert_ne!(state_changed.state_schema_id, baseline.state_schema_id);
        assert_ne!(state_changed.before_state_id, baseline.before_state_id);
        assert_ne!(
            state_changed.transition_type_id,
            baseline.transition_type_id
        );
        assert_ne!(state_changed.transition_id, baseline.transition_id);
        assert_ne!(state_changed.relation_id, baseline.relation_id);

        let context_interface_changed = baseline_source.replace(
            "IdentityContext(step: Int) | IdentityContextOther",
            "IdentityContext(step: Int) | IdentityContextOther | IdentityContextThird",
        );
        let (_, context_changed, _) =
            stable_model_owner_identity_snapshot(&context_interface_changed, "identity_target");
        assert_ne!(context_changed.context_owner, baseline.context_owner);
        assert_ne!(
            context_changed.context_schema_id,
            baseline.context_schema_id
        );
        assert_ne!(
            context_changed.transition_type_id,
            baseline.transition_type_id
        );
        assert_ne!(context_changed.transition_id, baseline.transition_id);
        assert_ne!(context_changed.relation_id, baseline.relation_id);
    }

    #[test]
    fn stable_model_owners_follow_imported_type_interfaces_not_imported_queries_or_paths() {
        let temp_name = format!(
            "futuruna_stable_model_owner_import_{}_{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        );
        let temp_dir = std::env::temp_dir().join(temp_name);
        std::fs::create_dir_all(&temp_dir).expect("create stable-owner import directory");
        let model = r#"
# IdentityState = IdentityState(value: Int) | IdentityOther
# IdentityContext = IdentityContext(step: Int) | IdentityContextOther
> identity_step(before: IdentityState, context: IdentityContext) -> IdentityState {
    IdentityState(value = before.value + context.step)
}
> identity_observer(state: IdentityState, context: IdentityContext) -> Int {
    state.value
}
"#;
        std::fs::write(temp_dir.join("left.runa"), model).expect("write left model");
        std::fs::write(temp_dir.join("right.runa"), model).expect("write right model");
        let root = |target: &str| {
            format!(
                r#"@ import ./{target}
? explore identity_target {{
    from {{
        before in [IdentityState(value = 1)]
        context in [IdentityContext(step = 1)]
    }}
    to after = identity_step(before, context)
    find all
    mechanisms paths for selected from identity_observer
}}
"#
            )
        };
        let snapshot = |target: &str| {
            stable_model_owner_identity_snapshot_in_dir(
                &root(target),
                "identity_target",
                Some(temp_dir.to_string_lossy().into_owned()),
            )
            .1
        };

        let left = snapshot("left");
        let right = snapshot("right");
        assert_eq!(left, right, "physical import paths are annotations only");

        std::fs::write(
            temp_dir.join("right.runa"),
            format!(
                r#"{model}
? explore imported_query_only {{
    from {{ before in [0]
        context = () }}
    to after = before
    find all
}}
"#
            ),
        )
        .expect("add imported query-only content");
        let query_changed = snapshot("right");
        assert_eq!(right, query_changed);

        std::fs::write(
            temp_dir.join("right.runa"),
            model.replace(
                "IdentityState(value: Int) | IdentityOther",
                "IdentityState(value: Int) | IdentityOther | IdentityThird",
            ),
        )
        .expect("edit imported type interface");
        let interface_changed = snapshot("right");
        assert_ne!(query_changed, interface_changed);

        let _ = std::fs::remove_dir_all(&temp_dir);
    }

    #[test]
    fn mechanism_trace_state_retains_repeated_eventless_call_anchors() {
        let artifacts = explore_artifacts_for_source(
            r#"
> root(state: Int, context: Int) -> Int { state + context }
> child(value: Int) -> Int { value }
"#,
        );
        assert!(
            artifacts.diagnostics.is_empty(),
            "{:?}",
            artifacts.diagnostics
        );
        let root_declaration = artifacts
            .analysis_program
            .declarations
            .iter()
            .find(|declaration| declaration.id.name.as_ref() == "root")
            .expect("root declaration");
        let child_declaration = artifacts
            .analysis_program
            .declarations
            .iter()
            .find(|declaration| declaration.id.name.as_ref() == "child")
            .expect("child declaration");
        let root_callable = CheckedCallableId {
            declaration: CheckedDeclarationOccurrenceId::from_sourced(root_declaration),
            structural_path: Box::default(),
        };
        let child_callable = CheckedCallableId {
            declaration: CheckedDeclarationOccurrenceId::from_sourced(child_declaration),
            structural_path: Box::default(),
        };
        let root_site = ExprSiteId {
            analysis_program: artifacts.analysis_program.id.clone(),
            declaration: root_declaration.id.clone(),
            normalized_declaration_ordinal: root_declaration.normalized_ordinal,
            ast_path: vec![0].into_boxed_slice(),
        };
        let repeated_call_site = ExprSiteId {
            analysis_program: artifacts.analysis_program.id.clone(),
            declaration: root_declaration.id.clone(),
            normalized_declaration_ordinal: root_declaration.normalized_ordinal,
            ast_path: vec![0, 7].into_boxed_slice(),
        };
        let root_path = CheckedInterpreterMechanismActivationPathId(0);
        let catalog = Arc::new(CheckedInterpreterMechanismCatalog {
            analysis_program: artifacts.analysis_program.id.clone(),
            expressions: BTreeMap::new(),
            call_targets: BTreeMap::new(),
            builtin_callbacks: BTreeMap::new(),
            callables: BTreeMap::new(),
            scoped_callables: BTreeMap::new(),
            rule_candidates: BTreeMap::new(),
            rule_candidate_digests: BTreeMap::new(),
        });
        let mut state = CheckedInterpreterMechanismTraceState {
            catalog,
            owners: vec![CheckedInterpreterMechanismOwner::Callable(
                root_callable.clone(),
            )],
            activation_paths: vec![CheckedInterpreterMechanismActivationPathNode {
                parent: None,
                activation: CheckedInterpreterMechanismActivation {
                    call_site: root_site,
                    callee: CheckedInterpreterMechanismCallee::Function(root_callable),
                    invocation_ordinal: 0,
                },
                depth: 1,
            }],
            current_activation_path: root_path,
            call_stack: Vec::new(),
            dependency_scopes: vec![Vec::new()],
            invocation_ordinals: BTreeMap::new(),
            visit_ordinals: BTreeMap::new(),
            events: Vec::new(),
            edge_count: 0,
            memoized_rule_reuses: 0,
            diagnostics_enabled: false,
            attempted_events: 0,
            attempted_event_kinds: [0; 6],
            directly_event_bearing_activation_paths: Vec::new(),
            family_diagnostics: BTreeMap::new(),
            validated_callable_bodies: BTreeSet::new(),
            validated_rule_candidates: BTreeSet::new(),
            error: None,
        };
        let callee = CheckedInterpreterMechanismCallee::Function(child_callable.clone());
        let owner = CheckedInterpreterMechanismOwner::Callable(child_callable);

        for expected_ordinal in 0..2 {
            assert!(state.enter_activation_at(
                repeated_call_site.clone(),
                callee.clone(),
                owner.clone(),
            ));
            assert_eq!(
                state
                    .activation_paths
                    .last()
                    .expect("child anchor")
                    .activation
                    .invocation_ordinal,
                expected_ordinal
            );
            state.exit_activation();
        }

        let trace = state.finish().expect("complete trace");
        assert_eq!(trace.activation_paths.len(), 3);
        assert!(trace.events.is_empty());
        assert_eq!(
            trace.activation_paths[1..]
                .iter()
                .map(|path| path.activation.invocation_ordinal)
                .collect::<Vec<_>>(),
            vec![0, 1]
        );
        assert!(trace.activation_paths[1..]
            .iter()
            .all(|path| path.parent == Some(root_path)));
    }

    fn checked_expression_paths<'a>(statement: &'a Stmt) -> Vec<(Vec<u32>, &'a Expr)> {
        fn collect_expression<'a>(
            node: &'a Expr,
            path: Vec<u32>,
            output: &mut Vec<(Vec<u32>, &'a Expr)>,
        ) {
            output.push((path.clone(), node));
            let mut child_index = 0;
            visit_ast_expr_children(node, &mut |child| {
                let mut child_path = path.clone();
                child_path.push(child_index);
                child_index += 1;
                match child {
                    AstChild::Expr(expression) => {
                        collect_expression(expression, child_path, output)
                    }
                    AstChild::Stmt(statement) => collect_statement(statement, child_path, output),
                }
            });
        }

        fn collect_statement<'a>(
            node: &'a Stmt,
            path: Vec<u32>,
            output: &mut Vec<(Vec<u32>, &'a Expr)>,
        ) {
            let mut child_index = 0;
            visit_ast_stmt_children(node, &mut |child| {
                let mut child_path = path.clone();
                child_path.push(child_index);
                child_index += 1;
                match child {
                    AstChild::Expr(expression) => {
                        collect_expression(expression, child_path, output)
                    }
                    AstChild::Stmt(statement) => collect_statement(statement, child_path, output),
                }
            });
        }

        let mut output = Vec::new();
        collect_statement(statement, Vec::new(), &mut output);
        output
    }

    #[test]
    fn checked_resolution_sites_are_stable_and_binders_are_structural() {
        let source = r#"
= value = 99
# Pairish(left: Int, right: Int)
> twice(value: Int) -> Int { value + value }
> ordered(left: Int, right: Int) -> Int { left - right }
> named() -> Int { ordered(right = 1, left = 2) }
> constructed() -> Pairish { Pairish(right = 1, left = 2) }
> pair_left(pair: Pairish) -> Int { pair.left }
> list_len() -> Int { length([1]) }
| overloaded(value: Int) -> value
| overloaded(left: Int, right: Int) -> left + right
> call_overloads() -> Int { overloaded(1) + overloaded(1, 2) }
| pipe_target(value: Int, limit: Int) -> value > limit
> piped(value: Int) -> Bool { value |> pipe_target(0) }
"#;
        let check = || {
            let statements = parse_test_program(source).expect("parse resolution fixture");
            TypeChecker::check_with_artifacts(&statements, None, source)
        };
        let first = check();
        let second = check();
        assert!(first.diagnostics.is_empty(), "{:?}", first.diagnostics);
        assert_eq!(
            first
                .checked_resolutions
                .expressions
                .keys()
                .collect::<Vec<_>>(),
            second
                .checked_resolutions
                .expressions
                .keys()
                .collect::<Vec<_>>()
        );

        let twice = first
            .analysis_program
            .declarations
            .iter()
            .find(|declaration| declaration.id.name.as_ref() == "twice")
            .expect("twice declaration");
        let twice_bindings = first
            .checked_resolutions
            .expressions
            .iter()
            .filter(|(site, _)| {
                site.declaration == twice.id
                    && site.normalized_declaration_ordinal == twice.normalized_ordinal
            })
            .filter_map(|(site, resolution)| match &resolution.value_binding {
                Some(CheckedValueBinding::Binder { site: binder, .. }) => {
                    Some((site.clone(), binder.clone()))
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(twice_bindings.len(), 2);
        assert_ne!(twice_bindings[0].0, twice_bindings[1].0);
        assert_eq!(twice_bindings[0].1, twice_bindings[1].1);

        let named = first
            .checked_resolutions
            .expressions
            .values()
            .find_map(|resolution| resolution.named_arguments.as_ref())
            .expect("checked named-argument order");
        assert_eq!(named.canonical_source_indices.as_ref(), [1, 0]);
        assert_eq!(
            named
                .parameter_names
                .iter()
                .map(|name| name.as_ref())
                .collect::<Vec<_>>(),
            ["left", "right"]
        );
        assert!(first
            .checked_resolutions
            .expressions
            .values()
            .any(|resolution| matches!(
                &resolution.call_target,
                Some(CheckedCallTarget::Function { callable, arity: 2 })
                    if callable.declaration.declaration.name.as_ref() == "ordered"
            )));
        assert!(first
            .checked_resolutions
            .expressions
            .values()
            .any(|resolution| matches!(
                &resolution.call_target,
                Some(CheckedCallTarget::Builtin { canonical_name, arity: 1 })
                    if canonical_name.as_ref() == "length"
            )));
        let overloads = first
            .checked_resolutions
            .expressions
            .values()
            .filter_map(|resolution| match &resolution.call_target {
                Some(CheckedCallTarget::RuleFamily(key)) if key.name == "overloaded" => {
                    Some(key.arity)
                }
                _ => None,
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(overloads, BTreeSet::from([1, 2]));
        assert!(first
            .checked_resolutions
            .expressions
            .values()
            .any(|resolution| matches!(
                &resolution.call_target,
                Some(CheckedCallTarget::Constructor { owner_type, variant, .. })
                    if owner_type.as_ref() == "Pairish" && variant.as_ref() == "Pairish"
            )));
        assert!(first
            .checked_resolutions
            .expressions
            .values()
            .any(|resolution| matches!(
                &resolution.field,
                Some(CheckedFieldResolution::Data { owner_type, fields })
                    if owner_type.as_ref() == "Pairish"
                        && fields.iter().any(|field| field.field_index == 0)
            )));
        let piped = first
            .analysis_program
            .declarations
            .iter()
            .find(|declaration| declaration.id.name.as_ref() == "piped")
            .expect("piped declaration");
        assert!(
            first
                .checked_resolutions
                .unsupported_sites
                .iter()
                .filter(|(site, _)| site.declaration == piped.id)
                .flat_map(|(_, issues)| issues)
                .filter(|issue| matches!(
                    issue,
                    CheckedResolutionIssue::UnsupportedExpression(reason)
                        if reason.starts_with("pipe ")
                ))
                .count()
                >= 2
        );
        assert!(!first
            .checked_resolutions
            .expressions
            .iter()
            .any(|(site, resolution)| {
                site.declaration == piped.id
                    && matches!(
                        &resolution.call_target,
                        Some(CheckedCallTarget::RuleFamily(key))
                            if key.name == "pipe_target"
                    )
            }));
    }
    #[test]
    fn checked_resolution_rule_family_uses_authoritative_tier_order() {
        let source = r#"
| choose(value: Int) -> 0
| choose(value: Int) -> 1 under value > 0
| exception high choose(value: Int) -> 2 under value > 10
"#;
        let artifacts = explore_artifacts_for_source(source);
        assert!(
            artifacts.diagnostics.is_empty(),
            "{:?}",
            artifacts.diagnostics
        );
        let family = artifacts
            .checked_resolutions
            .rule_families
            .get(&RuleDispatchKey {
                scope: None,
                name: "choose".to_string(),
                arity: 1,
            })
            .expect("checked choose family");
        assert_eq!(
            family
                .candidates
                .iter()
                .map(|candidate| candidate.tier)
                .collect::<Vec<_>>(),
            [
                RuleDispatchTier::Exception,
                RuleDispatchTier::ConditionalDefault,
                RuleDispatchTier::Clause,
            ]
        );
        assert_eq!(
            family
                .candidates
                .iter()
                .map(|candidate| candidate.source_order)
                .collect::<Vec<_>>(),
            [2, 1, 0]
        );
        assert!(family
            .candidates
            .windows(2)
            .all(|pair| pair[0].head_site != pair[1].head_site));
    }

