    #[test]
    fn checked_analysis_identity_covers_query_roots_but_excludes_proof_continuations() {
        let source = |continuation: &str| {
            format!(
                r#"
| eligible(value: Int) -> True under value > 0
| other(value: Int) -> True under value >= 0
? explore scan {{
    from {{
        candidate in [1, 2]
        fixed = 3
        before = candidate + fixed
        context = ()
    }}
    to after = before + 1
    where before before >= 0
    find matches of eligible(after)
    results summary {{
        group by [bucket = before]
        measure [measure = after + before, alternate = before]
        aggregate [profiles = count_distinct(before)]
        having varies(measure)
        select [shown = after, profiles]
        choose all maximizing shown
    }}
}}
| always: True -> True
? always -> {{ @ print("{continuation}") }}
"#
            )
        };
        let identity = |source: &str| {
            let statements = parse_test_program(&source).expect("parse analysis identity fixture");
            TypeChecker::check_with_artifacts(&statements, None, &source)
                .analysis_program
                .id
        };
        let baseline_source = source("first");
        let baseline = identity(&baseline_source);
        for (root, changed) in [
            (
                "question",
                baseline_source.replacen("eligible(after)", "other(after)", 1),
            ),
            (
                "polarity",
                baseline_source.replacen("find matches of", "find violations of", 1),
            ),
            (
                "domain",
                baseline_source.replacen("candidate in [1, 2]", "candidate in [1, 3]", 1),
            ),
            (
                "derived value",
                baseline_source.replacen("fixed = 3", "fixed = 4", 1),
            ),
            (
                "constraint",
                baseline_source.replacen("where before before >= 0", "where before before > 0", 1),
            ),
            (
                "successor",
                baseline_source.replacen("to after = before + 1", "to after = before + 2", 1),
            ),
            (
                "group key",
                baseline_source.replacen("bucket = before", "bucket = before + 1", 1),
            ),
            (
                "measure",
                baseline_source.replacen("measure = after + before", "measure = after - before", 1),
            ),
            (
                "aggregate",
                baseline_source.replacen("count_distinct(before)", "count_distinct(after)", 1),
            ),
            (
                "group filter",
                baseline_source.replacen("varies(measure)", "varies(alternate)", 1),
            ),
            (
                "selected value",
                baseline_source.replacen("shown = after", "shown = before", 1),
            ),
            (
                "choice",
                baseline_source.replacen("maximizing shown", "minimizing shown", 1),
            ),
        ] {
            assert_ne!(
                baseline,
                identity(&changed),
                "{root} must affect analysis identity"
            );
        }
        assert_eq!(
            baseline,
            identity(&source("second")),
            "proof presentation continuations do not rename Explore sites"
        );
    }

    #[test]
    fn explore_parser_builds_canonical_relations_views_and_named_mechanisms() {
        let source = r#"
? explore income_cliffs {
    from {
        income in range(0, 3)
        before = PersonState(
            income = income,
            commune = 101,
            status = Employed
        )
        context in [ExploreContext(step = 1), ExploreContext(step = 2)]
    }
    to after in [
        PersonState(
            income = before.income + context.step,
            commune = before.commune,
            status = before.status
        ),
        PersonState(
            income = before.income + context.step,
            commune = before.commune,
            status = Retired
        )
    ]
    where before before.income >= 0
    where after after.income >= 0
    where transition after.income >= before.income
    find violations of net(after, context) >= net(before, context)
    results cliffs_by_commune from selected {
        group by [commune = before.commune]
        measure [loss = net(before, context) - net(after, context)]
        having varies(loss)
        select [loss, income = before.income]
        choose pareto [maximize loss, minimize income]
    }
    mechanisms cliff_paths for selected from observe_income
    results raw_incidences from mechanisms cliff_paths {
        each incidence
        select [
            case_id,
            signature_id,
            structural_mechanism_id,
            execution_profile_id
        ]
    }
    results mechanism_counts from mechanisms cliff_paths {
        group by [structural_mechanism_id]
        aggregate [
            raw_signatures = count_distinct(signature_id),
            cases = count_distinct(case_id)
        ]
        select [structural_mechanism_id, raw_signatures, cases]
    }
    mechanisms winner_paths for view cliffs_by_commune chosen from Tax::observe_income
}
"#;
        let statements = parse_test_program(source).expect("parse canonical Explore query");
        let Stmt::Explore(query) = &statements[0] else {
            panic!("expected Explore declaration");
        };

        assert_eq!(query.name, "income_cliffs");
        assert_eq!(query.source.bindings.len(), 3);
        assert!(matches!(
            &query.source.bindings[0].kind,
            ExploreSourceBindingKind::Finite { .. }
        ));
        assert!(matches!(
            &query.source.bindings[1].kind,
            ExploreSourceBindingKind::Singleton { .. }
        ));
        assert!(matches!(
            &query.source.bindings[2].kind,
            ExploreSourceBindingKind::Finite { .. }
        ));
        assert!(matches!(
            &query.successor.kind,
            ExploreSuccessorKind::Finite { .. }
        ));
        assert_eq!(
            query
                .admissions
                .iter()
                .map(|admission| admission.scope)
                .collect::<Vec<_>>(),
            vec![
                ExploreAdmissionScope::Before,
                ExploreAdmissionScope::After,
                ExploreAdmissionScope::Transition,
            ]
        );
        assert!(matches!(
            &query.selection,
            ExploreSelection::Violations { .. }
        ));
        let ExploreAnalysisNode::Result(case_view) = &query.analysis[0] else {
            panic!("first analysis node must be the selected-case view");
        };
        assert!(matches!(&case_view.input, ExploreResultInput::Selected));
        assert!(matches!(
            &case_view.grain,
            ExploreResultGrain::GroupBy { .. }
        ));
        assert!(matches!(
            &case_view.choose,
            Some(ExploreResultChoice::Pareto { .. })
        ));
        let ExploreAnalysisNode::Mechanisms(cliff_paths) = &query.analysis[1] else {
            panic!("second analysis node must be the mechanism request");
        };
        assert_eq!(cliff_paths.name, "cliff_paths");
        let ExploreAnalysisNode::Result(raw_incidences) = &query.analysis[2] else {
            panic!("third analysis node must be the incidence-grain view");
        };
        assert!(matches!(
            &raw_incidences.grain,
            ExploreResultGrain::EachIncidence { .. }
        ));
        let ExploreAnalysisNode::Result(mechanism_counts) = &query.analysis[3] else {
            panic!("fourth analysis node must be the grouped mechanism-incidence view");
        };
        assert!(matches!(
            &mechanism_counts.input,
            ExploreResultInput::MechanismIncidence { request_name }
                if request_name == "cliff_paths"
        ));
        assert!(matches!(
            &mechanism_counts.aggregates[0].reducer,
            ExploreAggregateReducer::CountDistinct { .. }
        ));
        let ExploreAnalysisNode::Mechanisms(winner_paths) = &query.analysis[4] else {
            panic!("fifth analysis node must be the chosen-view mechanism request");
        };
        assert!(matches!(
            &winner_paths.target,
            ExploreMechanismTarget::ViewChosen { view_name }
                if view_name == "cliffs_by_commune"
        ));
        assert_eq!(winner_paths.callable_name, "Tax::observe_income");
    }

    fn explore_starter_projection_source(projections: &str) -> String {
        format!(
            r#"
> observe(state: Int, context: Unit) -> Int {{ state }}
? explore starter_projection {{
    from {{ before in [1, 2]
        context = () }}
    to after = before + 1
    find all
    results starter_values {{
        each case
        select [case_id, context, before, after]
    }}
    mechanisms paths for selected from observe
    {projections}
}}
"#
        )
    }

    fn explore_transition_graph_source(consumers: &str) -> String {
        format!(
            r#"
? explore transition_graph {{
    from {{ before in [1, 2]
        context = () }}
    to after = before + 1
    find matches of after > before
    {consumers}
}}
"#
        )
    }

    #[test]
    fn explore_transition_graph_is_a_checked_publication_only_consumer() {
        let source = explore_transition_graph_source("transitions full_case_graph from all cases");
        let statements = parse_test_program(&source).expect("parse transition graph consumer");
        let Stmt::Explore(query) = &statements[0] else {
            panic!("expected Explore declaration");
        };
        assert_eq!(query.transition_graphs.len(), 1);
        assert_eq!(query.transition_graphs[0].name, "full_case_graph");

        let baseline_artifacts = explore_artifacts_for_source(&explore_transition_graph_source(""));
        let graph_artifacts = explore_artifacts_for_source(&source);
        assert!(
            baseline_artifacts.diagnostics.is_empty(),
            "{:?}",
            baseline_artifacts.diagnostics
        );
        assert!(
            graph_artifacts.diagnostics.is_empty(),
            "{:?}",
            graph_artifacts.diagnostics
        );
        let baseline = baseline_artifacts
            .checked_exploration_query(0)
            .expect("checked baseline query");
        let graph = graph_artifacts
            .checked_exploration_query(0)
            .expect("checked graph query");
        assert_eq!(baseline.program_hash(), graph.program_hash());
        assert_eq!(baseline.relation_id(), graph.relation_id());
        assert_eq!(baseline.admission_id(), graph.admission_id());
        assert_eq!(baseline.question_id(), graph.question_id());
        assert_eq!(baseline.analysis_graph_hash(), graph.analysis_graph_hash());
        assert_eq!(
            baseline.transition_schemas().state_schema_id(),
            graph.transition_schemas().state_schema_id()
        );
        assert_eq!(
            baseline.transition_schemas().context_schema_id(),
            graph.transition_schemas().context_schema_id()
        );
        assert_eq!(
            baseline.transition_schemas().transition_type_id(),
            graph.transition_schemas().transition_type_id()
        );
        assert_eq!(baseline.transition_graph_consumers().len(), 0);
        let consumer = graph
            .transition_graph_consumers()
            .next()
            .expect("checked graph consumer");
        assert_eq!(consumer.0.name, "full_case_graph");
        assert_ne!(
            baseline.transition_graph_consumer_set_id(),
            graph.transition_graph_consumer_set_id()
        );

        let renamed_artifacts = explore_artifacts_for_source(&explore_transition_graph_source(
            "transitions renamed from all cases",
        ));
        let renamed = renamed_artifacts
            .checked_exploration_query(0)
            .expect("checked renamed graph consumer");
        assert_eq!(graph.relation_id(), renamed.relation_id());
        assert_eq!(graph.question_id(), renamed.question_id());
        assert_ne!(
            consumer.1.id,
            renamed
                .transition_graph_consumers()
                .next()
                .expect("renamed graph consumer")
                .1
                .id
        );

        let ordered = explore_artifacts_for_source(&explore_transition_graph_source(
            "transitions first from all cases\ntransitions second from all cases",
        ));
        let reversed = explore_artifacts_for_source(&explore_transition_graph_source(
            "transitions second from all cases\ntransitions first from all cases",
        ));
        assert_eq!(
            ordered
                .checked_exploration_query(0)
                .unwrap()
                .transition_graph_consumer_set_id(),
            reversed
                .checked_exploration_query(0)
                .unwrap()
                .transition_graph_consumer_set_id(),
            "consumer-set identity is independent of declaration order"
        );
    }

