    #[test]
    fn explore_canonical_walker_reaches_every_expression_surface() {
        let source = r#"
? explore traversal {
    from {
        auxiliary in source_domain()
        before = make_before(auxiliary)
        context = make_context(auxiliary)
    }
    to after in successors(before, context)
    where before admit_before(before, context)
    where after admit_after(after, context)
    where transition admit_transition(before, after, context)
    find matches of selected(before, after, context)
    results view {
        group by [group_key = group_expression(before)]
        measure [score = measure_expression(after)]
        having varies(score)
        select [shown = select_expression(score)]
        choose pareto [
            maximize maximize_expression(shown),
            minimize minimize_expression(shown)
        ]
    }
    mechanisms paths for selected from observe_expression
    results mechanism_view from mechanisms paths {
        group by [signature = signature_id]
        aggregate [cases = count_distinct(aggregate_expression(case_id))]
        select [signature, cases]
    }
}
"#;
        let statements = parse_test_program(source).expect("parse traversal query");
        let mut calls = BTreeSet::new();
        walk_ast_stmt(&statements[0], &mut |child| {
            if let AstChild::Expr(Expr {
                kind: ExprKind::App(function, _),
                ..
            }) = child
            {
                if let ExprKind::Var(name) = &function.kind {
                    calls.insert(name.clone());
                }
            }
        });
        for expected in [
            "source_domain",
            "make_before",
            "make_context",
            "successors",
            "admit_before",
            "admit_after",
            "admit_transition",
            "selected",
            "group_expression",
            "measure_expression",
            "aggregate_expression",
            "select_expression",
            "maximize_expression",
            "minimize_expression",
            "observe_expression",
        ] {
            assert!(calls.contains(expected), "walker missed {expected}");
        }
    }

    #[test]
    fn explore_typechecker_accepts_ordered_source_and_dependent_successors() {
        let source = r#"
# Status = Employed | Retired
# PersonState(income: Int, commune: Int, status: Status)
# ExploreContext(step: Int)

> promote(
    state: PersonState,
    context: ExploreContext,
    status: Status
) -> PersonState {
    PersonState(
        income = state.income + context.step,
        commune = state.commune,
        status = status
    )
}

> observe_income(state: PersonState, context: ExploreContext) -> Int {
    state.income + context.step
}

? explore income_cliffs {
    from {
        candidate_status in values(Status)
        income in range(0, 3)
        before = PersonState(
            income = income,
            commune = 101,
            status = candidate_status
        )
        context = ExploreContext(step = 1)
    }
    to after in [
        promote(before, context, before.status),
        promote(before, context, Retired)
    ]
    where before before.income >= 0
    where after after.income >= 0
    where transition after.income >= before.income
    find matches of after.income > before.income
    results by_status {
        group by [status = before.status]
        measure [gain = after.income - before.income]
        aggregate [profiles = count_distinct(before.commune)]
        having varies(gain)
        select [gain, profiles, income = before.income]
        choose all maximizing gain
    }
    mechanisms paths for selected from observe_income
    results raw_incidences from mechanisms paths {
        each incidence
        select [
            case_id,
            signature_id,
            structural_mechanism_id,
            execution_profile_id
        ]
    }
    results incidence_counts from mechanisms paths {
        group by [structural_mechanism_id]
        aggregate [
            profiles = count_distinct(execution_profile_id),
            raw_signatures = count_distinct(signature_id),
            cases = count_distinct(case_id)
        ]
        select [structural_mechanism_id, profiles, raw_signatures, cases]
    }
    mechanisms winners for view by_status chosen from observe_income
}
"#;
        let statements = parse_test_program(source).expect("parse checker fixture");
        let mut checker = TypeChecker::new();
        checker.source_text = source.to_string();
        checker.install_constructor_prepass(&statements);
        checker.collect_declarations(&statements);
        checker.infer_rule_return_types(&statements);
        checker.infer_canonical_rule_dispatch_metadata(&statements);
        checker.establish_explore_function_return_types();
        checker.infer_explore_rule_return_types(&statements);
        checker.validate_explore_function_return_types();
        checker.infer_canonical_rule_dispatch_metadata(&statements);
        checker.infer_explore_rule_return_types(&statements);
        checker.infer_top_level_binding_types(&statements);
        checker.check_program(&statements);

        assert!(checker.diagnostics.is_empty(), "{:?}", checker.diagnostics);
        let query = &checker.exploration_queries[0];
        assert_eq!(query.source.bindings.len(), 4);
        assert_eq!(query.source.before_binding_index, 2);
        assert_eq!(query.source.context_binding_index, 3);
        assert_eq!(
            query.source.multiplicity,
            ExploreRelationMultiplicity::SetNormalized
        );
        assert!(matches!(
            &query.successor.kind,
            TypedExploreSuccessorKind::Finite { .. }
        ));
        assert_eq!(query.admissions.len(), 3);
        assert!(matches!(
            &query.selection,
            TypedExploreSelection::Matches { .. }
        ));
        let TypedExploreAnalysisNode::Result(by_status) = &query.analysis[0] else {
            panic!("expected selected-case result view");
        };
        assert!(matches!(
            &by_status.grain,
            TypedExploreResultGrain::GroupBy { .. }
        ));
        assert_eq!(by_status.aggregates.len(), 1);
        let TypedExploreAnalysisNode::Mechanisms(paths) = &query.analysis[1] else {
            panic!("expected mechanism request");
        };
        assert_eq!(paths.name, "paths");
        let TypedExploreAnalysisNode::Result(raw_incidences) = &query.analysis[2] else {
            panic!("expected ungrouped mechanism-incidence view");
        };
        assert!(matches!(
            &raw_incidences.grain,
            TypedExploreResultGrain::EachIncidence { .. }
        ));
        let TypedExploreAnalysisNode::Result(incidence_counts) = &query.analysis[3] else {
            panic!("expected mechanism-incidence result view");
        };
        assert!(matches!(
            &incidence_counts.input,
            TypedExploreResultInput::MechanismIncidence {
                request_node_index: 1,
                ..
            }
        ));
        let TypedExploreAnalysisNode::Mechanisms(winners) = &query.analysis[4] else {
            panic!("expected chosen case-view mechanism request");
        };
        assert!(matches!(
            &winners.target,
            TypedExploreMechanismTarget::ViewChosen {
                view_node_index: 0,
                ..
            }
        ));
    }

    #[test]
    fn explore_typechecker_closes_unchosen_group_projection() {
        let valid = r#"
? explore histogram {
    from {
        before in [1, 2]
        context = ()
    }
    to after = before + 1
    find all
    results bins {
        group by [bucket = before]
        aggregate [cases = count_distinct(before)]
        select [bucket, cases, repeated = cases]
    }
}
"#;
        let artifacts = explore_artifacts_for_source(valid);
        assert!(
            artifacts.diagnostics.is_empty(),
            "{:?}",
            artifacts.diagnostics
        );

        let invalid = valid.replace(
            "select [bucket, cases, repeated = cases]",
            "select [bucket, cases, leaked = after]",
        );
        let artifacts = explore_artifacts_for_source(&invalid);
        assert!(artifacts.diagnostics.iter().any(|diagnostic| {
            diagnostic
                .message
                .contains("name `after` is referenced before its bound or shown value is available")
        }));
    }

    #[test]
    fn parsed_source_module_cache_reuses_exact_content_and_invalidates_rewrites() {
        let temp_path = std::env::temp_dir().join(format!(
            "futuruna_parsed_module_cache_{}_{}.runa",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock")
                .as_nanos()
        ));
        let first_source = "= cached_value = 1\n";
        let second_source = "= cached_value = 2\n";

        std::fs::write(&temp_path, first_source).expect("write first cached module");
        let first = parse_source_module_file_cached(&temp_path).expect("parse first module");
        let unchanged =
            parse_source_module_file_cached(&temp_path).expect("reuse unchanged module");
        assert!(Arc::ptr_eq(&first, &unchanged));

        std::fs::write(&temp_path, second_source).expect("rewrite cached module");
        let rewritten =
            parse_source_module_file_cached(&temp_path).expect("parse rewritten module");
        assert!(!Arc::ptr_eq(&first, &rewritten));
        assert_ne!(first.content_hash(), rewritten.content_hash());
        assert_eq!(rewritten.source(), second_source);

        std::fs::remove_file(temp_path).ok();
    }

    #[test]
    fn localized_fields_preserve_spelling_without_disabling_identifier_aliases() {
        let source = r#"
@ sprog da

# AfregningsResultat(omfang: Heltal)
# Aliasfelt(fold: Heltal)
# LokalRegel(fold: Heltal) {
    | resultat() -> fold + 1
}

= resultat = AfregningsResultat(
    omfang = fold([1, 2], 0, |fold: Heltal, værdi: Heltal| fold + værdi)
)
= aliasfelt = Aliasfelt(fold = 4)
@ print(show_int(resultat.omfang))
@ print(show_int(aliasfelt.fold))
@ print(show_int(LokalRegel(2).resultat()))
"#;
        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize();
        let localized_scope = tokens
            .iter()
            .find(|token| token.source_text == "omfang")
            .expect("localized keyword token");
        assert_eq!(localized_scope.kind, TokenKind::KW);
        assert_eq!(localized_scope.text, "scope");
        let localized_fold = tokens
            .iter()
            .find(|token| token.source_text == "fold")
            .expect("localized builtin token");
        assert_eq!(localized_fold.kind, TokenKind::Ident);
        assert_eq!(localized_fold.text, "foldl");

        let mut parser = Parser::new(tokens, source);
        let statements = parser.parse_program().expect("parse localized field");
        let field_name = statements
            .iter()
            .find_map(|statement| match statement {
                Stmt::TypeDecl(TypeDecl::ADT { name, variants, .. })
                    if name == "AfregningsResultat" =>
                {
                    variants
                        .first()
                        .and_then(|variant| variant.fields.first())
                        .map(|field| field.name.as_str())
                }
                _ => None,
            })
            .expect("localized product field");
        assert_eq!(field_name, "omfang");
        assert_eq!(
            eval_source_with_prelude(source, false).expect("evaluate localized field"),
            "3\n4\n3"
        );
    }

