        let diagnostics = check_source_for_diagnostics(unknown_field);
        assert!(diagnostics.iter().any(|diagnostic| diagnostic
            .message
            .contains("refof type `Input` has no field `missing`")));

        let ambiguous_symbol = r#"
> duplicate() -> Int { 1 }
| duplicate() -> 1
= target = refof(duplicate)
"#;
